CREATE OR REPLACE FUNCTION "public"."accept_pending_invitations"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  UPDATE org_members
  SET
    user_id = NEW.id,
    accepted_at = COALESCE(accepted_at, NOW())
  WHERE LOWER(invited_email) = LOWER(NEW.email)
    AND user_id IS NULL;

  INSERT INTO procurement_team_settings (
    org_profile_id,
    user_id,
    procurement_role,
    notification_mode,
    permission_overrides,
    created_by,
    updated_by
  )
  SELECT
    pending.org_profile_id,
    NEW.id,
    pending.procurement_role,
    pending.notification_mode,
    pending.permission_overrides,
    pending.created_by,
    pending.updated_by
  FROM procurement_pending_team_invites pending
  JOIN org_members member
    ON member.org_profile_id = pending.org_profile_id
   AND LOWER(member.invited_email) = LOWER(pending.invited_email)
   AND member.user_id = NEW.id
  ON CONFLICT (org_profile_id, user_id)
  DO UPDATE SET
    procurement_role = EXCLUDED.procurement_role,
    notification_mode = EXCLUDED.notification_mode,
    permission_overrides = EXCLUDED.permission_overrides,
    updated_by = EXCLUDED.updated_by,
    updated_at = NOW();

  DELETE FROM procurement_pending_team_invites pending
  USING org_members member
  WHERE pending.org_profile_id = member.org_profile_id
    AND LOWER(pending.invited_email) = LOWER(member.invited_email)
    AND member.user_id = NEW.id;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."accept_pending_invitations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acquire_funding_ghl_alignment_lock"("p_alignment_key" "text", "p_run_id" "uuid", "p_lease_seconds" integer DEFAULT 600) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  acquired boolean := false;
BEGIN
  INSERT INTO public.funding_ghl_alignment_state (alignment_key)
  VALUES (p_alignment_key)
  ON CONFLICT (alignment_key) DO NOTHING;

  UPDATE public.funding_ghl_alignment_state
  SET locked_by = p_run_id,
      locked_until = now() + make_interval(secs => greatest(p_lease_seconds, 60)),
      updated_at = now()
  WHERE alignment_key = p_alignment_key
    AND (locked_until IS NULL OR locked_until < now() OR locked_by = p_run_id)
  RETURNING true INTO acquired;

  RETURN coalesce(acquired, false);
END;
$$;


ALTER FUNCTION "public"."acquire_funding_ghl_alignment_lock"("p_alignment_key" "text", "p_run_id" "uuid", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acquire_funding_ghl_sync_lock"("p_sync_key" "text", "p_pipeline_id" "text", "p_run_id" "uuid", "p_lease_seconds" integer DEFAULT 600) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  acquired boolean := false;
BEGIN
  INSERT INTO public.funding_ghl_sync_state (sync_key, pipeline_id)
  VALUES (p_sync_key, p_pipeline_id)
  ON CONFLICT (sync_key) DO NOTHING;

  UPDATE public.funding_ghl_sync_state
  SET pipeline_id = p_pipeline_id,
      locked_by = p_run_id,
      locked_until = now() + make_interval(secs => greatest(p_lease_seconds, 60)),
      updated_at = now()
  WHERE sync_key = p_sync_key
    AND (locked_until IS NULL OR locked_until < now() OR locked_by = p_run_id)
  RETURNING true INTO acquired;

  RETURN coalesce(acquired, false);
END;
$$;


ALTER FUNCTION "public"."acquire_funding_ghl_sync_lock"("p_sync_key" "text", "p_pipeline_id" "text", "p_run_id" "uuid", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."act_auto_pass_stale_pipeline"() RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_deadline_stale int;
  v_rolling_stale int;
  v_total int;
BEGIN
  -- Deadline >30 days past, never actioned
  WITH s AS (
    UPDATE org_pipeline SET
      status = 'passed',
      notes = COALESCE(notes,'') || E'\n[auto-passed: deadline >30d past with no decision · ' || to_char(now(),'YYYY-MM-DD') || ']',
      updated_at = now()
    WHERE opportunity_type = 'grant'
      AND status IN ('prospect','watching','upcoming','discovered')
      AND act_parse_pipeline_deadline(deadline) IS NOT NULL
      AND act_parse_pipeline_deadline(deadline) < CURRENT_DATE - INTERVAL '30 days'
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_deadline_stale FROM s;

  -- Rolling/no-deadline + no activity in 6 months
  WITH s AS (
    UPDATE org_pipeline SET
      status = 'passed',
      notes = COALESCE(notes,'') || E'\n[auto-passed: rolling/no-deadline, no activity 180d · ' || to_char(now(),'YYYY-MM-DD') || ']',
      updated_at = now()
    WHERE opportunity_type = 'grant'
      AND status IN ('prospect','watching','upcoming','discovered')
      AND act_parse_pipeline_deadline(deadline) IS NULL
      AND updated_at < NOW() - INTERVAL '180 days'
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_rolling_stale FROM s;

  v_total := v_deadline_stale + v_rolling_stale;

  RETURN jsonb_build_object(
    'deadline_stale_passed', v_deadline_stale,
    'rolling_stale_passed',  v_rolling_stale,
    'total_passed',          v_total,
    'ran_at',                now()
  );
END;
$$;


ALTER FUNCTION "public"."act_auto_pass_stale_pipeline"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."act_auto_pass_stale_pipeline"() IS 'Auto-pass grant pipeline rows that have either (a) passed deadline >30d ago without decision or (b) rolling/no-deadline with no activity >180d. Excludes foundations/revenue_streams/etc.';



