CREATE OR REPLACE FUNCTION "public"."act_parse_pipeline_deadline"("d" "text") RETURNS "date"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
  IF d IS NULL OR d = '' OR lower(d) IN ('rolling','tbc','tbd','none','n/a') THEN
    RETURN NULL;
  END IF;
  -- ISO first
  IF d ~ '^\d{4}-\d{2}-\d{2}' THEN
    RETURN to_date(left(d,10), 'YYYY-MM-DD');
  END IF;
  -- 'D Mon YYYY' or 'DD Mon YYYY'
  IF d ~ '^\d{1,2}\s+\w{3}\s+\d{4}' THEN
    BEGIN
      RETURN to_date(d, 'DD Mon YYYY');
    EXCEPTION WHEN OTHERS THEN
      RETURN NULL;
    END;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."act_parse_pipeline_deadline"("d" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_new_storyteller"("p_email" "text", "p_full_name" "text", "p_community" "text" DEFAULT NULL::"text", "p_bio" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    v_user_id UUID;
BEGIN
    INSERT INTO users (
        email, 
        full_name, 
        community_affiliation, 
        bio, 
        role,
        created_at
    ) VALUES (
        p_email,
        p_full_name,
        p_community,
        p_bio,
        'storyteller',
        NOW()
    ) RETURNING id INTO v_user_id;
    
    RETURN v_user_id;
END;
$$;


