CREATE OR REPLACE FUNCTION "public"."auto_create_person_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_person_id UUID;
BEGIN
  -- Only process if newly enriched and has email
  IF NEW.exa_enriched = TRUE
     AND NEW.email_address IS NOT NULL
     AND (OLD.exa_enriched IS NULL OR OLD.exa_enriched = FALSE)
     AND NEW.exa_confidence_score >= 0.5 THEN

    -- Check if person identity already exists
    SELECT person_id INTO v_person_id
    FROM person_identity_map
    WHERE email = NEW.email_address
    LIMIT 1;

    IF v_person_id IS NOT NULL THEN
      -- Update existing person identity
      UPDATE person_identity_map
      SET
        full_name = COALESCE(NEW.full_name, full_name),
        contact_data = JSONB_SET(
          COALESCE(contact_data, '{}'::jsonb),
          '{exa_enrichment}',
          JSON_BUILD_OBJECT(
            'bio', NEW.bio,
            'linkedin_url', NEW.linkedin_url,
            'current_company', NEW.current_company,
            'current_position', NEW.current_position,
            'location', NEW.location,
            'industries', NEW.industries,
            'confidence_score', NEW.exa_confidence_score,
            'enriched_at', NEW.exa_last_enriched
          )::jsonb
        ),
        updated_at = NOW()
      WHERE person_id = v_person_id;

      -- Link linkedin_contacts to person_identity_map
      NEW.person_id = v_person_id;

      RAISE NOTICE 'Updated existing person_identity_map: %', v_person_id;

    ELSE
      -- Create new person identity
      INSERT INTO person_identity_map (
        full_name,
        email,
        contact_data,
        data_source,
        discovered_via,
        created_at,
        updated_at
      ) VALUES (
        NEW.full_name,
        NEW.email_address,
        JSON_BUILD_OBJECT(
          'exa_enrichment', JSON_BUILD_OBJECT(
            'bio', NEW.bio,
            'linkedin_url', NEW.linkedin_url,
            'current_company', NEW.current_company,
            'current_position', NEW.current_position,
            'location', NEW.location,
            'industries', NEW.industries,
            'confidence_score', NEW.exa_confidence_score,
            'enriched_at', NEW.exa_last_enriched
          )
        )::jsonb,
        'exa_enrichment',
        'auto_trigger',
        NOW(),
        NOW()
      ) RETURNING person_id INTO v_person_id;

      -- Link linkedin_contacts to new person_identity_map
      NEW.person_id = v_person_id;

      RAISE NOTICE 'Created new person_identity_map: %', v_person_id;
    END IF;

  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_create_person_identity"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."auto_create_person_identity"() IS 'Automatically creates or updates person_identity_map when linkedin_contacts are enriched with Exa.
Triggered when exa_enriched changes to TRUE and confidence >= 0.5';



CREATE OR REPLACE FUNCTION "public"."auto_tag_invoice_income_type"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  -- Only tag ACCREC invoices that don't already have income_type
  IF NEW.type = 'ACCREC' AND NEW.income_type IS NULL AND NEW.contact_name IS NOT NULL THEN
    SELECT r.income_type INTO NEW.income_type
    FROM vendor_project_rules r
    WHERE r.vendor_name = NEW.contact_name
      AND r.income_type IS NOT NULL
      AND r.auto_apply = true
    LIMIT 1;
    
    -- Fallback: check if any previous invoice from this contact has income_type
    IF NEW.income_type IS NULL THEN
      SELECT i.income_type INTO NEW.income_type
      FROM xero_invoices i
      WHERE i.contact_name = NEW.contact_name
        AND i.type = 'ACCREC'
        AND i.income_type IS NOT NULL
      LIMIT 1;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_tag_invoice_income_type"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_theme_map"("raw" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case lower(regexp_replace(coalesce(raw, ''), '[_\s]+', '-', 'g'))
    -- youth justice
    when 'youth-justice'   then 'youth-justice'
    when 'youth-services'  then 'youth-justice'
    when 'diversion'       then 'youth-justice'
    -- child protection / family
    when 'child-protection' then 'child-protection'
    when 'family-services'  then 'family-services'
    -- legal
    when 'legal-services'  then 'legal-services'
    -- corrections / community safety
    when 'corrections'      then 'corrections'
    when 'community-safety' then 'corrections'
    -- community (broadest social bucket)
    when 'community-services'            then 'community'
    when 'community'                     then 'community'
    when 'community-led'                 then 'community'
    when 'community-economic-development' then 'community'
    when 'human-services'                then 'community'
    -- education
    when 'education' then 'education'
    -- health
    when 'health' then 'health'
    -- disability
    when 'disability' then 'disability'
    when 'ndis'       then 'disability'
    -- housing
    when 'housing' then 'housing'
    -- indigenous
    when 'indigenous' then 'indigenous'
    when 'aboriginal' then 'indigenous'
    -- prevention (maps into youth-justice program space)
    when 'prevention' then 'youth-justice'
    else null
  end;
$$;


ALTER FUNCTION "public"."award_theme_map"("raw" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."award_theme_map"("raw" "text") IS 'Phase 6: maps a raw sector/topic/category/classie token to a canonical award-history theme, or NULL. The interoperable join axis between grants and historical awards.';



CREATE OR REPLACE FUNCTION "public"."backfill_all_community_programs_to_alma"() RETURNS TABLE("program_id" "uuid", "intervention_id" "uuid", "program_name" "text", "status" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_program RECORD;
  v_intervention_id UUID;
BEGIN
  FOR v_program IN
    SELECT id, name, alma_intervention_id
    FROM community_programs
    WHERE alma_intervention_id IS NULL -- Only backfill programs not yet linked
    ORDER BY is_featured DESC, created_at ASC -- Featured programs first
  LOOP
    BEGIN
      -- Backfill this program
      v_intervention_id := backfill_community_program_to_alma_intervention(v_program.id);

      -- Return success
      program_id := v_program.id;
      intervention_id := v_intervention_id;
      program_name := v_program.name;
      status := 'Success';
      RETURN NEXT;

    EXCEPTION WHEN OTHERS THEN
      -- Return error
      program_id := v_program.id;
      intervention_id := NULL;
      program_name := v_program.name;
      status := 'Error: ' || SQLERRM;
      RETURN NEXT;
    END;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."backfill_all_community_programs_to_alma"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."backfill_all_community_programs_to_alma"() IS 'Batch backfill all community programs to ALMA interventions';



CREATE OR REPLACE FUNCTION "public"."backfill_community_program_to_alma_intervention"("p_program_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_intervention_id UUID;
  v_program RECORD;
  v_intervention_type TEXT;
BEGIN
  -- Get the community program
  SELECT * INTO v_program
  FROM community_programs
  WHERE id = p_program_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Community program not found: %', p_program_id;
  END IF;

  -- Map approach to intervention type
  v_intervention_type := CASE v_program.approach
    WHEN 'Indigenous-led' THEN 'Community-Led'
    WHEN 'Community-based' THEN 'Community-Led'
    WHEN 'Grassroots' THEN 'Community-Led'
    WHEN 'Culturally-responsive' THEN 'Cultural Connection'
    ELSE 'Community-Led'
  END;

  -- Create ALMA intervention
  INSERT INTO alma_interventions (
    name,
    type,
    description,
    geography,
    evidence_level,
    cultural_authority,
    consent_level,
    permitted_uses,
    operating_organization,
    years_operating,
    review_status,
    linked_community_program_id,
    metadata
  ) VALUES (
    v_program.name,
    v_intervention_type,
    v_program.description || E'\n\nImpact: ' || v_program.impact_summary,
    ARRAY[v_program.state],
    CASE
      WHEN v_program.indigenous_knowledge THEN 'Indigenous-led (culturally grounded, community authority)'
      WHEN v_program.success_rate >= 80 THEN 'Effective (strong evaluation, positive outcomes)'
      WHEN v_program.success_rate >= 60 THEN 'Promising (community-endorsed, emerging evidence)'
      ELSE 'Promising (community-endorsed, emerging evidence)'
    END,
    CASE
      WHEN v_program.indigenous_knowledge THEN v_program.organization || ' (Indigenous-led)'
      ELSE v_program.organization
    END,
    'Community Controlled', -- Default to Community Controlled for existing programs
    ARRAY['Query (internal)', 'Publish (JusticeHub)']::TEXT[],
    v_program.organization,
    v_program.years_operating,
    'Approved', -- Mark as Approved since they're already published in JusticeHub
    v_program.id,
    jsonb_build_object(
      'source', 'backfill_from_community_programs',
      'original_approach', v_program.approach,
      'success_rate', v_program.success_rate,
      'participants_served', v_program.participants_served,
      'community_connection_score', v_program.community_connection_score,
      'is_featured', v_program.is_featured,
      'tags', v_program.tags
    )
  ) RETURNING id INTO v_intervention_id;

  -- Link back to community program
  UPDATE community_programs
  SET alma_intervention_id = v_intervention_id
  WHERE id = p_program_id;

  -- Create consent ledger entry
  INSERT INTO alma_consent_ledger (
    entity_type,
    entity_id,
    consent_level,
    permitted_uses,
    cultural_authority,
    contributors,
    attribution_text,
    consent_given_by,
    revenue_share_enabled
  ) VALUES (
    'intervention',
    v_intervention_id,
    'Community Controlled',
    ARRAY['Query (internal)', 'Publish (JusticeHub)']::TEXT[],
    CASE
      WHEN v_program.indigenous_knowledge THEN v_program.organization || ' (Indigenous-led)'
      ELSE v_program.organization
    END,
    jsonb_build_array(
      jsonb_build_object(
        'name', v_program.organization,
        'role', 'Program operator',
        'contact', COALESCE(v_program.contact_email, v_program.contact_phone)
      )
    ),
    'Data sourced from ' || v_program.organization || ' community program',
    'JusticeHub backfill migration',
    true -- Enable revenue sharing for community contributions
  );

  RETURN v_intervention_id;
END;
$$;


ALTER FUNCTION "public"."backfill_community_program_to_alma_intervention"("p_program_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."backfill_community_program_to_alma_intervention"("p_program_id" "uuid") IS 'Convert a community program to an ALMA intervention with consent tracking';



CREATE OR REPLACE FUNCTION "public"."bridge_civicscope_to_act_exact"("p_rebuild" boolean DEFAULT false) RETURNS bigint
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_count bigint := 0;
BEGIN
  IF p_rebuild THEN
    DELETE FROM civicscope_act_entity_bridge
    WHERE act_source_table = 'canonical_entities'
      AND match_method = 'name_exact';
  END IF;

  WITH candidates AS (
    SELECT
      ce.id AS act_id,
      ce.canonical_company AS act_company,
      upper(btrim(ce.canonical_company)) AS norm_company
    FROM canonical_entities ce
    WHERE ce.canonical_company IS NOT NULL
      AND length(btrim(ce.canonical_company)) >= 3
  ),
  matched AS (
    SELECT
      c.act_id,
      c.act_company,
      g.id AS gs_entity_id,
      g.gs_id,
      g.canonical_name AS gs_name
    FROM candidates c
    CROSS JOIN LATERAL (
      SELECT id, gs_id, canonical_name
      FROM gs_entities
      WHERE upper(btrim(canonical_name)) = c.norm_company
      LIMIT 1
    ) g
  )
  INSERT INTO civicscope_act_entity_bridge (
    act_source_table, act_source_id, act_match_value,
    gs_entity_id, gs_id, gs_canonical_name,
    match_method, confidence, matched_field
  )
  SELECT
    'canonical_entities', m.act_id, m.act_company,
    m.gs_entity_id, m.gs_id, m.gs_name,
    'name_exact', 0.95, 'canonical_company'
  FROM matched m
  ON CONFLICT (act_source_table, act_source_id, gs_entity_id) DO UPDATE
    SET match_method  = 'name_exact',
        confidence    = GREATEST(civicscope_act_entity_bridge.confidence, EXCLUDED.confidence),
        matched_field = EXCLUDED.matched_field,
        updated_at    = now();

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."bridge_civicscope_to_act_exact"("p_rebuild" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bridge_civicscope_to_act_exact"("p_rebuild" boolean) IS 'Exact match canonical_entities.canonical_company → gs_entities.canonical_name via upper(btrim()) index.';



CREATE OR REPLACE FUNCTION "public"."bridge_civicscope_to_act_fuzzy"("p_batch_limit" integer DEFAULT 500, "p_after_id" "uuid" DEFAULT NULL::"uuid", "p_min_similarity" numeric DEFAULT 0.70) RETURNS TABLE("rows_inserted" bigint, "batch_processed" bigint, "last_id" "uuid", "done" boolean)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'extensions', 'public', 'pg_temp'
    AS $_$
DECLARE
  v_inserted bigint := 0;
  v_batch_size bigint := 0;
  v_last_id uuid;
BEGIN
  PERFORM set_limit(0.5);
  CREATE TEMP TABLE _bridge_batch ON COMMIT DROP AS
  SELECT ce.id, ce.canonical_company
  FROM canonical_entities ce
  LEFT JOIN civicscope_act_entity_bridge b
    ON b.act_source_id = ce.id AND b.act_source_table = 'canonical_entities'
  WHERE ce.canonical_company IS NOT NULL
    AND length(btrim(ce.canonical_company)) >= 6
    AND b.id IS NULL
    AND (p_after_id IS NULL OR ce.id > p_after_id)
    AND lower(btrim(ce.canonical_company)) !~ '^(self|n/?a|none|null|tbd|tba|unknown|sole trader|consultant|consulting|freelance|freelancer|retired|self employed|self-employed|independent)$'
    AND NOT (canonical_company !~ '\s' AND length(btrim(canonical_company)) < 8)
  ORDER BY ce.id
  LIMIT p_batch_limit;
  SELECT COUNT(*) INTO v_batch_size FROM _bridge_batch;
  SELECT id INTO v_last_id FROM _bridge_batch ORDER BY id DESC LIMIT 1;
  INSERT INTO civicscope_act_entity_bridge (
    act_source_table, act_source_id, act_match_value,
    gs_entity_id, gs_id, gs_canonical_name,
    match_method, confidence, matched_field
  )
  SELECT 'canonical_entities', b.id, b.canonical_company,
    g.id, g.gs_id, g.canonical_name,
    'name_fuzzy', similarity(lower(g.canonical_name), lower(b.canonical_company)), 'canonical_company'
  FROM _bridge_batch b
  CROSS JOIN LATERAL (
    SELECT id, gs_id, canonical_name FROM gs_entities
    WHERE canonical_name % b.canonical_company
    ORDER BY canonical_name <-> b.canonical_company LIMIT 1
  ) g
  WHERE similarity(lower(g.canonical_name), lower(b.canonical_company)) >= p_min_similarity
  ON CONFLICT (act_source_table, act_source_id, gs_entity_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  RETURN QUERY SELECT v_inserted, v_batch_size, v_last_id, v_batch_size = 0;
END;
$_$;


ALTER FUNCTION "public"."bridge_civicscope_to_act_fuzzy"("p_batch_limit" integer, "p_after_id" "uuid", "p_min_similarity" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bridge_civicscope_to_act_fuzzy"("p_batch_limit" integer, "p_after_id" "uuid", "p_min_similarity" numeric) IS 'Batched pg_trgm fuzzy match. Returns (inserted, batch_size, last_id, done). Loop until done.';



