CREATE OR REPLACE FUNCTION "public"."civicscope_normalize_org_name"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT NULLIF(
    btrim(
      regexp_replace(
        regexp_replace(
          regexp_replace(
            lower(coalesce(p_name, '')),
            E'\\b(pty\\.?\\s*ltd\\.?|pty\\s*limited|limited|incorporated|inc\\.?|corporation|corp\\.?|llc|llp|p/l|p\\.?l\\.?|the|and|&)\\b',
            ' ', 'g'
          ),
          '[^a-z0-9 ]', ' ', 'g'
        ),
        E'\\s+', ' ', 'g'
      )
    ),
    ''
  );
$$;


