CREATE OR REPLACE FUNCTION "public"."clarity_measure_edge"("p_edge_id" bigint, "p_timeout_ms" integer DEFAULT 8000) RETURNS TABLE("out_rate" numeric, "out_method" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  e           record;
  n_total     bigint;
  n_present   bigint;
  n_matched   bigint;
  n_keys      bigint;
  n_tgt_rows  bigint;
  rate        numeric;
  method      text := 'count_join';
  grain_text  text;
BEGIN
  SELECT * INTO e FROM clarity_edge WHERE id = p_edge_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'clarity_measure_edge: no edge %', p_edge_id;
  END IF;

  -- A view_lineage edge is not a join and has no match rate to measure. Saying
  -- so is different from measuring it at 0.
  IF e.mechanism = 'view_lineage' THEN
    UPDATE clarity_edge SET match_method = 'not_a_join', match_measured_at = now()
     WHERE id = p_edge_id;
    RETURN QUERY SELECT NULL::numeric, 'not_a_join'::text;
    RETURN;
  END IF;

  PERFORM set_config('statement_timeout', p_timeout_ms::text, true);

  BEGIN
    EXECUTE format(
      'SELECT count(*), count(%I) FROM %I', e.src_column, e.src_object)
      INTO n_total, n_present;

    EXECUTE format(
      'SELECT count(*) FROM %I s WHERE s.%I IS NOT NULL AND EXISTS ' ||
      '(SELECT 1 FROM %I t WHERE t.%I = s.%I)',
      e.src_object, e.src_column, e.tgt_object, e.tgt_column, e.src_column)
      INTO n_matched;

    -- Grain: how many target rows a single key resolves to. A choropleth built
    -- on a frayed key silently multiplies its own numbers, which is the defect
    -- no match rate would ever reveal.
    EXECUTE format(
      'SELECT count(*), count(DISTINCT %I) FROM %I WHERE %I IS NOT NULL',
      e.tgt_column, e.tgt_object, e.tgt_column)
      INTO n_tgt_rows, n_keys;

    grain_text := CASE
      WHEN n_keys IS NULL OR n_keys = 0 THEN NULL
      WHEN n_tgt_rows = n_keys          THEN '1:1'
      WHEN n_tgt_rows::numeric / n_keys < 1.01 THEN 'n:1'
      ELSE 'frayed ' || round(n_tgt_rows::numeric / n_keys, 2) || ' rows/key'
    END;

    rate := CASE WHEN coalesce(n_present, 0) = 0 THEN NULL
                 ELSE round(n_matched::numeric / n_present::numeric, 3) END;
  EXCEPTION
    WHEN query_canceled THEN
      method := 'timeout';   rate := NULL;
    WHEN OTHERS THEN
      method := 'error: ' || left(SQLERRM, 80); rate := NULL;
  END;

  PERFORM set_config('statement_timeout', '0', true);

  -- History first, so a series exists even for the run that produced it.
  INSERT INTO clarity_edge_history
    (edge_id, match_rate, match_numerator, match_denominator, rows_at_stake)
  VALUES (p_edge_id, rate, n_matched, n_present, n_total);

  UPDATE clarity_edge SET
    match_rate        = rate,
    match_numerator   = n_matched,
    match_denominator = n_present,
    rows_at_stake     = n_total,
    grain             = coalesce(grain_text, grain),
    match_method      = method,
    match_measured_at = now()
   WHERE id = p_edge_id;

  RETURN QUERY SELECT rate, method;
END;
$$;


ALTER FUNCTION "public"."clarity_measure_edge"("p_edge_id" bigint, "p_timeout_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clarity_measure_gaps"("p_cost_class" "text" DEFAULT NULL::"text") RETURNS TABLE("metric_key" "text", "value" numeric, "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    SET "statement_timeout" TO '0'
    AS $$
DECLARE
  m record; num bigint; den bigint; v numeric; t0 timestamptz; st text; err text;
BEGIN
  FOR m IN SELECT * FROM clarity_gap_metric
            WHERE enabled AND (p_cost_class IS NULL OR cost_class = p_cost_class)
            ORDER BY metric_key
  LOOP
    t0 := clock_timestamp(); num := NULL; den := NULL; v := NULL; st := 'ok'; err := NULL;
    BEGIN
      EXECUTE m.numerator_sql INTO num;
      IF m.denominator_sql IS NOT NULL THEN
        EXECUTE m.denominator_sql INTO den;
        v := CASE WHEN coalesce(den,0) = 0 THEN NULL
                  ELSE round(100.0 * num::numeric / den::numeric, 4) END;
      ELSE
        v := num::numeric;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      st := 'error'; err := SQLERRM;
    END;
    INSERT INTO clarity_gap_measurement
      (metric_key, numerator, denominator, value, duration_ms, status, error_text)
    VALUES (m.metric_key, num, den, v,
            (extract(epoch FROM clock_timestamp()-t0)*1000)::int, st, err);
    metric_key := m.metric_key; value := v; status := st;
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."clarity_measure_gaps"("p_cost_class" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clarity_measure_seams"("p_limit" integer DEFAULT 25, "p_only_unmeasured" boolean DEFAULT true, "p_timeout_ms" integer DEFAULT 8000) RETURNS TABLE("out_edge_id" bigint, "out_src" "text", "out_tgt" "text", "out_rate" numeric, "out_method" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    SET "statement_timeout" TO '0'
    AS $$
DECLARE
  r record;
  res record;
BEGIN
  FOR r IN
    SELECT id, src_object, src_column, tgt_object, tgt_column
      FROM clarity_edge
     WHERE mechanism <> 'view_lineage'
       AND (NOT p_only_unmeasured OR match_measured_at IS NULL)
     ORDER BY id
     LIMIT p_limit
  LOOP
    SELECT * INTO res FROM clarity_measure_edge(r.id, p_timeout_ms);
    out_edge_id := r.id;
    out_src := r.src_object || '.' || r.src_column;
    out_tgt := r.tgt_object || '.' || r.tgt_column;
    out_rate := res.out_rate;
    out_method := res.out_method;
    RETURN NEXT;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."clarity_measure_seams"("p_limit" integer, "p_only_unmeasured" boolean, "p_timeout_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clarity_question_rows"("p_slug" "text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sql       text;
  v_stripped  text;
  v_limit     integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_offset    integer := greatest(coalesce(p_offset, 0), 0);
  v_rows      jsonb;
BEGIN
  SELECT rows_sql INTO v_sql FROM clarity_question WHERE slug = p_slug;

  IF v_sql IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'no rows_sql registered for this question');
  END IF;

  v_stripped := btrim(v_sql);

  -- Single statement only. A semicolon anywhere is a refusal, not a trim: trimming a trailing
  -- one would quietly accept "SELECT 1; DROP ..." on the next edit.
  IF position(';' IN v_stripped) > 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'rows_sql must be a single statement');
  END IF;

  IF v_stripped !~* '^\s*(select|with)\s' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'rows_sql must begin with SELECT or WITH');
  END IF;

  EXECUTE format(
    'SELECT coalesce(jsonb_agg(to_jsonb(z)), ''[]''::jsonb) FROM (%s LIMIT %s OFFSET %s) z',
    v_stripped, v_limit, v_offset
  ) INTO v_rows;

  RETURN jsonb_build_object(
    'ok', true,
    'rows', v_rows,
    'limit', v_limit,
    'offset', v_offset
  );
END;
$$;


ALTER FUNCTION "public"."clarity_question_rows"("p_slug" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clarity_record_reason"("p_event_id" bigint, "p_reason" "text", "p_by" "text") RETURNS TABLE("out_id" bigint, "out_reason" "text", "out_by" "text", "out_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF coalesce(btrim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'clarity_record_reason: a reason cannot be blank';
  END IF;
  RETURN QUERY
  UPDATE clarity_event e
     SET reason = btrim(p_reason), reason_by = p_by, reason_at = now()
   WHERE e.id = p_event_id
  RETURNING e.id, e.reason, e.reason_by, e.reason_at;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'clarity_record_reason: no event %', p_event_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."clarity_record_reason"("p_event_id" bigint, "p_reason" "text", "p_by" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clarity_refresh"("p_exact_count_max" bigint DEFAULT 2000000, "p_fresh_scan_max" bigint DEFAULT 2000000, "p_write_history" boolean DEFAULT true) RETURNS TABLE("objects" integer, "relations" integer, "routines" integer, "exact_counts" integer, "estimated_counts" integer, "freshness_ok" integer, "freshness_deferred" integer, "elapsed_ms" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    SET "statement_timeout" TO '0'
    AS $_$
DECLARE
  rec         record;
  t0          timestamptz := clock_timestamp();
  tprobe      timestamptz;
  n_rel       integer := 0;
  n_fn        integer := 0;
  n_exact     integer := 0;
  n_est       integer := 0;
  n_fresh_ok  integer := 0;
  n_fresh_def integer := 0;
  v_rows      bigint;
  v_est       boolean;
  v_probe     clarity_probe;
  v_ms        integer;
  v_fcol      text;
  v_findexed  boolean;
  v_last      timestamptz;
  v_fprobe    clarity_probe;
  v_fms       integer;
BEGIN
  -- ===================== A. RELATIONS: tables, matviews, views ==============
  FOR rec IN
    SELECT c.oid,
           c.relname,
           (CASE c.relkind WHEN 'r' THEN 'table' WHEN 'm' THEN 'matview' ELSE 'view' END)::clarity_object_kind AS kind,
           c.relkind,
           GREATEST(c.reltuples, 0)::bigint AS est_rows,
           pg_total_relation_size(c.oid)    AS bytes,
           c.relrowsecurity                 AS rls,
           (SELECT count(*) FROM pg_policy p WHERE p.polrelid = c.oid)::int AS npol,
           (SELECT count(*) FROM pg_policy p
             WHERE p.polrelid = c.oid AND p.polpermissive AND p.polcmd IN ('r','*')
               AND coalesce(pg_get_expr(p.polqual, p.polrelid), 'true') = 'true'
               AND (p.polroles = '{0}'::oid[]
                    OR EXISTS (SELECT 1 FROM unnest(p.polroles) rr
                                WHERE pg_get_userbyid(rr) = 'anon')))::int AS anon_open,
           has_table_privilege('anon', c.oid, 'SELECT')          AS anon_grant,
           has_table_privilege('authenticated', c.oid, 'SELECT') AS auth_grant,
           (c.relkind = 'v' AND EXISTS (SELECT 1 FROM unnest(coalesce(c.reloptions,'{}'::text[]))
                                          o WHERE o = 'security_invoker=true')) AS sec_invoker
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relkind IN ('r','m','v')
    ORDER BY c.relname
  LOOP
    n_rel := n_rel + 1;

    ------------------------------------------------------------------ row count
    -- n_live_tup is BROKEN on this instance (political_donations -> 0 for
    -- 2,549,483 real rows). reltuples is the router; count(*) is the answer.
    v_ms := NULL;
    IF rec.relkind = 'v' THEN
      -- Views cannot be bounded from inside a function (see header). The runner
      -- counts them one statement at a time, where a timeout can actually fire.
      v_rows := NULL; v_est := false; v_probe := 'deferred_too_large';
    ELSIF rec.est_rows < p_exact_count_max THEN
      tprobe := clock_timestamp();
      BEGIN
        EXECUTE format('SELECT count(*) FROM public.%I', rec.relname) INTO v_rows;
        v_est := false; v_probe := 'ok'; n_exact := n_exact + 1;
      EXCEPTION WHEN OTHERS THEN
        v_rows := rec.est_rows; v_est := true; v_probe := 'error'; n_est := n_est + 1;
      END;
      v_ms := (extract(epoch FROM clock_timestamp() - tprobe) * 1000)::int;
    ELSE
      -- Measured: all 6 relations >= 2M rows sit within 0.26% of exact.
      v_rows := rec.est_rows; v_est := true; v_probe := 'ok'; n_est := n_est + 1;
    END IF;

    ------------------------------------------------------------------ freshness
    v_fcol := NULL; v_last := NULL; v_fms := NULL; v_findexed := false;

    IF rec.relkind = 'm' THEN
      -- Only 1 of 98 matviews carries a timestamp column. mv_refresh_log is the
      -- only honest source, and it only knows 44 of them.
      SELECT max(l.started_at) INTO v_last
        FROM mv_refresh_log l
       WHERE l.mv_name = rec.relname AND l.status LIKE 'success%';
      v_fprobe := CASE WHEN v_last IS NULL THEN 'no_column' ELSE 'ok' END;
    ELSE
      -- pg_attribute, NOT information_schema: matviews are absent from the latter
      -- (verified: 0 of 98), and this branch also serves views.
      SELECT a.attname,
             EXISTS (SELECT 1 FROM pg_index x
                      WHERE x.indrelid = rec.oid AND x.indkey[0] = a.attnum)
        INTO v_fcol, v_findexed
        FROM pg_attribute a
        JOIN clarity_freshness_candidate f ON f.column_name = a.attname
       WHERE a.attrelid = rec.oid AND a.attnum > 0 AND NOT a.attisdropped
         AND format_type(a.atttypid, NULL) IN
             ('timestamp with time zone','timestamp without time zone','date')
       ORDER BY f.priority
       LIMIT 1;

      IF v_fcol IS NULL THEN
        v_fprobe := 'no_column';
      ELSIF rec.relkind = 'v' THEN
        v_fprobe := 'deferred_too_large';   -- runner's job, same reason as view counts
      ELSIF NOT v_findexed AND rec.est_rows > p_fresh_scan_max THEN
        v_fprobe := 'deferred_too_large';
        n_fresh_def := n_fresh_def + 1;
      ELSE
        tprobe := clock_timestamp();
        BEGIN
          EXECUTE format('SELECT max(%I)::timestamptz FROM public.%I', v_fcol, rec.relname)
            INTO v_last;
          v_fprobe := 'ok'; n_fresh_ok := n_fresh_ok + 1;
        EXCEPTION WHEN OTHERS THEN
          v_fprobe := 'error';
        END;
        v_fms := (extract(epoch FROM clock_timestamp() - tprobe) * 1000)::int;
      END IF;
    END IF;

    ------------------------------------------------------------------ upsert
    INSERT INTO clarity_object AS o (
      object_key, object_name, object_kind, oid,
      row_count, row_count_is_estimate, row_count_probe, row_count_ms, bytes,
      column_count, nullable_columns,
      freshness_column, freshness_source, last_write_at, freshness_probe, freshness_ms,
      rls_enabled, policy_count, anon_grant, anon_open_policies, anon_readable,
      authenticated_grant, security_invoker,
      refreshed_at, missing_since
    ) VALUES (
      rec.relname, rec.relname, rec.kind, rec.oid,
      v_rows, v_est, v_probe, v_ms, rec.bytes,
      (SELECT count(*) FROM pg_attribute a
        WHERE a.attrelid = rec.oid AND a.attnum > 0 AND NOT a.attisdropped),
      (SELECT count(*) FROM pg_attribute a
        WHERE a.attrelid = rec.oid AND a.attnum > 0 AND NOT a.attisdropped AND NOT a.attnotnull),
      v_fcol,
      CASE WHEN rec.relkind = 'm' THEN 'mv_refresh_log'
           WHEN v_fcol IS NOT NULL THEN 'column' ELSE 'none' END,
      v_last, v_fprobe, v_fms,
      rec.rls, rec.npol, rec.anon_grant, rec.anon_open,
      (rec.anon_grant AND (NOT rec.rls OR rec.anon_open > 0)),
      rec.auth_grant,
      CASE WHEN rec.relkind = 'v' THEN rec.sec_invoker ELSE NULL END,
      now(), NULL
    )
    ON CONFLICT (object_key) DO UPDATE SET
      object_kind = EXCLUDED.object_kind,
      oid = EXCLUDED.oid,
      -- a deferred probe must not wipe a value the runner filled in
      row_count = CASE WHEN EXCLUDED.row_count_probe = 'deferred_too_large'
                       THEN o.row_count ELSE EXCLUDED.row_count END,
      row_count_is_estimate = CASE WHEN EXCLUDED.row_count_probe = 'deferred_too_large'
                       THEN o.row_count_is_estimate ELSE EXCLUDED.row_count_is_estimate END,
      row_count_probe = EXCLUDED.row_count_probe,
      row_count_ms = EXCLUDED.row_count_ms,
      bytes = EXCLUDED.bytes,
      column_count = EXCLUDED.column_count,
      nullable_columns = EXCLUDED.nullable_columns,
      freshness_column = EXCLUDED.freshness_column,
      freshness_source = EXCLUDED.freshness_source,
      last_write_at = CASE WHEN EXCLUDED.freshness_probe = 'deferred_too_large'
                       THEN o.last_write_at ELSE EXCLUDED.last_write_at END,
      freshness_probe = EXCLUDED.freshness_probe,
      freshness_ms = EXCLUDED.freshness_ms,
      rls_enabled = EXCLUDED.rls_enabled,
      policy_count = EXCLUDED.policy_count,
      anon_grant = EXCLUDED.anon_grant,
      anon_open_policies = EXCLUDED.anon_open_policies,
      anon_readable = EXCLUDED.anon_readable,
      authenticated_grant = EXCLUDED.authenticated_grant,
      security_invoker = EXCLUDED.security_invoker,
      refreshed_at = now(),
      missing_since = NULL;
  END LOOP;

  -- ===================== B. ROUTINES: the 409 nobody inventoried ============
  FOR rec IN
    SELECT p.oid,
           p.proname,
           p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')' AS key,
           l.lanname,
           p.prosecdef,
           p.provolatile,
           pg_get_function_result(p.oid) AS rettype,
           length(coalesce(p.prosrc,'')) AS srclen,
           has_function_privilege('anon', p.oid, 'EXECUTE') AS anon_exec,
           has_function_privilege('authenticated', p.oid, 'EXECUTE') AS auth_exec,
           (SELECT count(*) FROM pg_trigger t
             WHERE t.tgfoid = p.oid AND NOT t.tgisinternal)::int AS trg
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    JOIN pg_language  l ON l.oid = p.prolang
    WHERE n.nspname = 'public'
    ORDER BY p.proname
  LOOP
    n_fn := n_fn + 1;
    INSERT INTO clarity_object AS o (
      object_key, object_name, object_kind, oid,
      row_count_probe, freshness_probe, lifecycle,
      routine_language, routine_kind, routine_returns, routine_volatility,
      routine_src_bytes, trigger_attachments,
      security_definer, anon_execute, authenticated_grant,
      refreshed_at, missing_since
    ) VALUES (
      rec.key, rec.proname, 'function', rec.oid,
      'not_applicable', 'not_applicable', 'routine',
      rec.lanname,
      CASE WHEN rec.rettype = 'trigger' THEN 'trigger'
           WHEN rec.prosecdef THEN 'security_definer' ELSE 'plain' END,
      rec.rettype, rec.provolatile, rec.srclen, rec.trg,
      rec.prosecdef, rec.anon_exec, rec.auth_exec,
      now(), NULL
    )
    ON CONFLICT (object_key) DO UPDATE SET
      oid = EXCLUDED.oid,
      routine_language = EXCLUDED.routine_language,
      routine_kind = EXCLUDED.routine_kind,
      routine_returns = EXCLUDED.routine_returns,
      routine_volatility = EXCLUDED.routine_volatility,
      routine_src_bytes = EXCLUDED.routine_src_bytes,
      trigger_attachments = EXCLUDED.trigger_attachments,
      security_definer = EXCLUDED.security_definer,
      anon_execute = EXCLUDED.anon_execute,
      authenticated_grant = EXCLUDED.authenticated_grant,
      refreshed_at = now(),
      missing_since = NULL;
  END LOOP;

  -- ===================== C. COLUMNS (pg_attribute, covers matviews) =========
  DELETE FROM clarity_column c
   WHERE NOT EXISTS (SELECT 1 FROM pg_class pc JOIN pg_namespace pn ON pn.oid = pc.relnamespace
                      WHERE pn.nspname='public' AND pc.relname = c.object_key);

  INSERT INTO clarity_column (object_key, ordinal, column_name, data_type, is_nullable,
                              is_pk, is_indexed, is_vector, vector_dim)
  SELECT c.relname, a.attnum, a.attname,
         format_type(a.atttypid, a.atttypmod),
         NOT a.attnotnull,
         EXISTS (SELECT 1 FROM pg_index x WHERE x.indrelid=c.oid AND x.indisprimary
                                            AND a.attnum = ANY(x.indkey::int2[])),
         EXISTS (SELECT 1 FROM pg_index x WHERE x.indrelid=c.oid
                                            AND a.attnum = ANY(x.indkey::int2[])),
         (t.typname = 'vector'),
         CASE WHEN t.typname = 'vector' THEN a.atttypmod END
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  JOIN pg_attribute a ON a.attrelid = c.oid
  JOIN pg_type t      ON t.oid = a.atttypid
  WHERE n.nspname='public' AND c.relkind IN ('r','m','v')
    AND a.attnum > 0 AND NOT a.attisdropped
  ON CONFLICT (object_key, ordinal) DO UPDATE SET
    column_name = EXCLUDED.column_name,
    data_type   = EXCLUDED.data_type,
    is_nullable = EXCLUDED.is_nullable,
    is_pk       = EXCLUDED.is_pk,
    is_indexed  = EXCLUDED.is_indexed,
    is_vector   = EXCLUDED.is_vector,
    vector_dim  = EXCLUDED.vector_dim;

  -- ===================== D. EDGES: declared FKs + view lineage ==============
  INSERT INTO clarity_edge (src_object, src_column, tgt_object, tgt_column,
                            mechanism, declared, note)
  SELECT DISTINCT cl1.relname, att1.attname, cl2.relname, att2.attname,
                  'fk', true, con.conname
  FROM pg_constraint con
  JOIN pg_class cl1      ON con.conrelid  = cl1.oid
  JOIN pg_class cl2      ON con.confrelid = cl2.oid
  JOIN pg_attribute att1 ON att1.attrelid = cl1.oid AND att1.attnum = ANY(con.conkey)
  JOIN pg_attribute att2 ON att2.attrelid = cl2.oid AND att2.attnum = ANY(con.confkey)
  JOIN pg_namespace ns   ON cl1.relnamespace = ns.oid
  WHERE con.contype = 'f' AND ns.nspname = 'public'
  ON CONFLICT DO NOTHING;

  -- pg_depend/pg_rewrite: which views and matviews read which base relations.
  -- 695 edges today. This is the lineage the FK graph cannot see.
  INSERT INTO clarity_edge (src_object, src_column, tgt_object, tgt_column,
                            mechanism, declared)
  SELECT DISTINCT dep.relname, NULL, base.relname, NULL, 'view_lineage', true
  FROM pg_depend d
  JOIN pg_rewrite rw     ON rw.oid = d.objid
  JOIN pg_class dep      ON dep.oid = rw.ev_class
  JOIN pg_class base     ON base.oid = d.refobjid
  JOIN pg_namespace nd   ON nd.oid = dep.relnamespace
  JOIN pg_namespace nb   ON nb.oid = base.relnamespace
  WHERE d.classid = 'pg_rewrite'::regclass AND d.refclassid = 'pg_class'::regclass
    AND nd.nspname='public' AND nb.nspname='public'
    AND dep.oid <> base.oid
    AND dep.relkind IN ('v','m') AND base.relkind IN ('r','m','v')
  ON CONFLICT DO NOTHING;

  -- ===================== E. DEGREES =========================================
  UPDATE clarity_object o SET
    fk_out      = coalesce((SELECT count(*) FROM clarity_edge e
                             WHERE e.src_object=o.object_key AND e.mechanism='fk'),0),
    fk_in       = coalesce((SELECT count(*) FROM clarity_edge e
                             WHERE e.tgt_object=o.object_key AND e.mechanism='fk'),0),
    lineage_out = coalesce((SELECT count(*) FROM clarity_edge e
                             WHERE e.src_object=o.object_key AND e.mechanism='view_lineage'),0),
    lineage_in  = coalesce((SELECT count(*) FROM clarity_edge e
                             WHERE e.tgt_object=o.object_key AND e.mechanism='view_lineage'),0),
    join_out    = coalesce((SELECT count(*) FROM clarity_edge e
                             WHERE e.src_object=o.object_key AND e.mechanism NOT IN ('fk','view_lineage')),0),
    join_in     = coalesce((SELECT count(*) FROM clarity_edge e
                             WHERE e.tgt_object=o.object_key AND e.mechanism NOT IN ('fk','view_lineage')),0)
  WHERE o.object_kind <> 'function';

  -- ===================== F. DB-FUNCTION REFERENCES ==========================
  -- The scan the 2026-08-14 pass never ran: 386,420 characters of pg_proc.prosrc.
  -- 202 relations are referenced ONLY here. Treating them as dark is how 19 live
  -- objects reached a DROP list.
  DELETE FROM clarity_code_ref WHERE ref_class = 'db_function';
  INSERT INTO clarity_code_ref (object_key, ref_class, repo, file_path, hits)
  SELECT r.object_key, 'db_function', 'database', f.key, count(*)::int
  FROM (SELECT object_key, object_name FROM clarity_object WHERE object_kind <> 'function') r
  JOIN (SELECT p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')' AS key,
               coalesce(p.prosrc,'') AS src
          FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
         WHERE n.nspname='public') f
    -- strpos() first: it is a plain substring search and it prunes the 1,024 x 410
    -- pair space before the regex runs. Measured on this instance: regex alone
    -- 103.8s, strpos + regex 3.6s, identical result (586 pairs, 209 relations).
    ON strpos(f.src, r.object_name) > 0
   AND f.src ~ ('(^|[^a-zA-Z0-9_])' || r.object_name || '([^a-zA-Z0-9_]|$)')
  GROUP BY 1,4
  ON CONFLICT DO NOTHING;

  -- triggers: 219 of them on 178 tables, invisible to every FK-based lineage model
  DELETE FROM clarity_code_ref WHERE ref_class = 'trigger';
  INSERT INTO clarity_code_ref (object_key, ref_class, repo, file_path, hits)
  SELECT c.relname, 'trigger', 'database',
         p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')', 1
  FROM pg_trigger t
  JOIN pg_class c     ON c.oid = t.tgrelid
  JOIN pg_namespace n ON n.oid = c.relnamespace
  JOIN pg_proc p      ON p.oid = t.tgfoid
  WHERE n.nspname='public' AND NOT t.tgisinternal
  ON CONFLICT DO NOTHING;

  UPDATE clarity_object o SET
    refs_db_function = coalesce((SELECT count(*) FROM clarity_code_ref r
                                  WHERE r.object_key=o.object_key
                                    AND r.ref_class IN ('db_function','trigger')),0);

  -- ===================== G. ACT PRIVATE-BUSINESS FLAG (Ben, decision 1) =====
  -- The cluster leaves this database. Until it does, it is flagged so no civic
  -- surface shows it and the /clarity default filter hides it.
  UPDATE clarity_object SET
    act_business = true,
    act_business_source = coalesce(act_business_source, 'name_rule')
  WHERE object_kind <> 'function'
    AND act_business_source IS DISTINCT FROM 'manual'
    AND object_name ~ '^(act_|xero_|ghl_|notion_|receipt|finance_|bank_|email_|gmail_|imessage_|telegram_|memory_|calendar_|communications_|sprint|team_members|project_salary|saas_|goods_|ce_users|ce_metrics)';

  -- A regular view is a saved question, not stored data. Label it once so the
  -- ranking's lifecycle weight has something to read; the shards never classified
  -- any of the 212.
  UPDATE clarity_object SET lifecycle = 'lens'
   WHERE object_kind = 'view' AND lifecycle IS NULL;

  -- ===================== H. STATE ===========================================
  UPDATE clarity_object SET state = CASE
    WHEN object_kind = 'function'                                        THEN 'routine'
    WHEN object_name ~ '_backup(_|$)' OR object_name ~ '^_backup'
         OR object_name ~ '_bak$' OR lifecycle = 'backup'                THEN 'backup'
    WHEN lifecycle = 'superseded'                                        THEN 'superseded'
    WHEN lifecycle = 'staging' OR object_name ~ '^stg_'
         OR object_name ~ '^dedup_' OR object_name ~ '_20[0-9]{6}[a-z]?$' THEN 'staging'
    WHEN row_count IS NULL                                               THEN 'unknown'
    WHEN row_count = 0                                                   THEN 'empty'
    WHEN row_count < 10                                                  THEN 'tiny'
    ELSE 'live' END;

  -- ===================== I. IMPORTANCE ======================================
  PERFORM clarity_score();

  -- ===================== J. HISTORY + single-writer catalog snapshot ========
  IF p_write_history THEN
    INSERT INTO clarity_object_history
      (object_key, object_kind, row_count, row_count_is_estimate, bytes,
       last_write_at, degree, importance)
    SELECT object_key, object_kind, row_count, row_count_is_estimate, bytes,
           last_write_at, degree, importance
    FROM clarity_object WHERE missing_since IS NULL;

    -- data_catalog_snapshots keeps its 25-table provenance series; this makes
    -- clarity_refresh() its only writer so the two cannot disagree.
    INSERT INTO data_catalog_snapshots (table_name, row_count, freshness_hours, notes)
    SELECT dc.table_name, o.row_count,
           CASE WHEN o.last_write_at IS NULL THEN NULL
                ELSE round(extract(epoch FROM now() - o.last_write_at)/3600.0, 2) END,
           'clarity_refresh'
    FROM data_catalog dc
    JOIN clarity_object o ON o.object_key = dc.table_name;
  END IF;

  -- ===================== K. RETIRE, do not delete ===========================
  UPDATE clarity_object o SET missing_since = coalesce(o.missing_since, now())
   WHERE (o.object_kind = 'function'
          AND NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                           WHERE n.nspname='public'
                             AND p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')' = o.object_key))
      OR (o.object_kind <> 'function'
          AND NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
                           WHERE n.nspname='public' AND c.relkind IN ('r','m','v')
                             AND c.relname = o.object_key));

  RETURN QUERY SELECT n_rel + n_fn, n_rel, n_fn, n_exact, n_est, n_fresh_ok, n_fresh_def,
                      (extract(epoch FROM clock_timestamp() - t0) * 1000)::int;
END;
$_$;


ALTER FUNCTION "public"."clarity_refresh"("p_exact_count_max" bigint, "p_fresh_scan_max" bigint, "p_write_history" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clarity_rows"("p_object_key" "text", "p_limit" integer DEFAULT 25) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  obj record;
  n int;
  cols text;
  rows jsonb;
  census jsonb;
  flag record;
  yes bigint; no bigint; unrecorded bigint;
BEGIN
  n := least(greatest(coalesce(p_limit, 25), 1), 50);

  SELECT object_key, object_kind, domain, row_count
    INTO obj
    FROM clarity_object
   WHERE object_key = p_object_key;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'not in the catalogue — the catalogue is the allowlist');
  END IF;

  IF obj.object_kind NOT IN ('table', 'matview', 'view') THEN
    RETURN jsonb_build_object('allowed', false, 'reason', format('a %s has no rows to view', obj.object_kind));
  END IF;

  -- The consent refusal. Mirrors visibility-floor.ts (WITHHELD_DOMAIN + WITHHELD_OBJECTS).
  IF obj.domain = 'storytelling_consent'
     OR obj.object_key IN ('story_analysis', 'transcript_analysis', 'tour_stories', 'partner_storytellers_v')
  THEN
    -- Per-flag census over the real rows: every boolean consent_% column, counted three ways.
    -- NULL is "unrecorded", and unrecorded is not consent.
    census := '[]'::jsonb;
    FOR flag IN
      SELECT column_name
        FROM information_schema.columns
       WHERE table_schema = 'public'
         AND table_name = p_object_key
         AND data_type = 'boolean'
         AND column_name LIKE 'consent\_%'
       ORDER BY ordinal_position
    LOOP
      EXECUTE format(
        'SELECT count(*) FILTER (WHERE %1$I IS TRUE),
                count(*) FILTER (WHERE %1$I IS FALSE),
                count(*) FILTER (WHERE %1$I IS NULL)
           FROM public.%2$I', flag.column_name, p_object_key)
        INTO yes, no, unrecorded;
      census := census || jsonb_build_object(
        'flag', flag.column_name, 'yes', yes, 'no', no, 'unrecorded', unrecorded);
    END LOOP;

    RETURN jsonb_build_object(
      'allowed', false,
      'reason', CASE WHEN obj.domain = 'storytelling_consent'
                     THEN 'consent-governed: filed under storytelling_consent'
                     ELSE 'consent-governed: holds story content or identifies storytellers' END,
      'consent_census', census,
      'row_count', obj.row_count);
  END IF;

  -- The relation must really exist as a row-bearing thing in public. Catalogue rot must fail
  -- closed, not fall through to dynamic SQL against something else.
  IF NOT EXISTS (
    SELECT 1 FROM pg_class c JOIN pg_namespace ns ON ns.oid = c.relnamespace
     WHERE ns.nspname = 'public' AND c.relname = p_object_key
       AND c.relkind IN ('r', 'p', 'v', 'm'))
  THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'catalogued but not found in the database — the catalogue may be stale');
  END IF;

  SELECT string_agg(quote_ident(column_name), ', ' ORDER BY ordinal_position)
    INTO cols
    FROM information_schema.columns
   WHERE table_schema = 'public' AND table_name = p_object_key
     AND udt_name <> 'vector';

  IF cols IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'no readable columns');
  END IF;

  EXECUTE format(
    'SELECT coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) FROM (SELECT %s FROM public.%I LIMIT %s) t',
    cols, p_object_key, n)
    INTO rows;

  RETURN jsonb_build_object('allowed', true, 'rows', rows, 'limit', n, 'row_count', obj.row_count);
END;
$_$;


ALTER FUNCTION "public"."clarity_rows"("p_object_key" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clarity_run_detectors"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  n_join int;
  n_orphan int;
BEGIN
  -- Detector 1: undiscovered join. An identifier-shaped column that is a PROVEN join key
  -- elsewhere (some edge somewhere joins on this column name), on a populated object that has
  -- no edge on it at all. Identifier shape, not every shared name: 16,124 columns share
  -- created_at and that is not a join.
  WITH idcols AS (
    SELECT cc.object_key, cc.column_name
      FROM clarity_column cc
     WHERE cc.column_name ~ '(_id|_abn|_key|_code|_slug)$'
        OR cc.column_name IN ('abn', 'acn', 'gs_id', 'postcode', 'icn')
  ), proven AS (
    SELECT DISTINCT c FROM (
      SELECT src_column AS c FROM clarity_edge
      UNION SELECT tgt_column FROM clarity_edge
    ) t WHERE c IS NOT NULL
  ), edged AS (
    SELECT src_object AS o, src_column AS c FROM clarity_edge
    UNION SELECT tgt_object, tgt_column FROM clarity_edge
  ), found AS (
    SELECT ic.object_key,
           ic.column_name,
           (SELECT count(DISTINCT ic2.object_key) FROM idcols ic2
             WHERE ic2.column_name = ic.column_name AND ic2.object_key <> ic.object_key) AS peers
      FROM idcols ic
      JOIN clarity_object o ON o.object_key = ic.object_key
     WHERE coalesce(o.row_count, 0) > 0
       AND ic.column_name IN (SELECT c FROM proven)
       AND NOT EXISTS (SELECT 1 FROM edged e
                        WHERE e.o = ic.object_key AND e.c = ic.column_name)
  ), upserted AS (
    INSERT INTO clarity_finding (detector, subject_object_key, column_name, title, evidence)
    SELECT 'undiscovered_join',
           f.object_key,
           f.column_name,
           format('%s.%s is a proven join key elsewhere but this object has no edge on it', f.object_key, f.column_name),
           jsonb_build_object('peer_objects_with_column', f.peers)
      FROM found f
    ON CONFLICT (detector, subject_object_key, column_name)
    DO UPDATE SET last_seen_at = now(), evidence = excluded.evidence
    RETURNING 1
  )
  SELECT count(*) INTO n_join FROM upserted;

  -- Detector 2: orphan. A populated table/matview that nothing references: no app file, no
  -- script, no migration (all three MEASURED by the slice 6b scanner — 0 means scanned-unused),
  -- no db function, nothing derived from it, and no question built on it. Views are excluded:
  -- their row_count is not populated, and an unreferenced view is dead weight of a different
  -- kind. Every clause is a measurement; absence of any one of them keeps the object out.
  WITH orphans AS (
    SELECT o.object_key, o.row_count, o.bytes, o.last_write_at
      FROM clarity_object o
     WHERE o.object_kind IN ('table', 'matview')
       AND coalesce(o.row_count, 0) > 0
       AND coalesce(o.refs_app, 0) = 0
       AND coalesce(o.refs_script, 0) = 0
       AND coalesce(o.refs_migration, 0) = 0
       AND coalesce(o.refs_db_function, 0) = 0
       AND coalesce(o.lineage_out, 0) = 0
       AND NOT EXISTS (SELECT 1 FROM clarity_question_ingredient qi
                        WHERE qi.object_key = 'public.' || o.object_key)
  ), upserted AS (
    INSERT INTO clarity_finding (detector, subject_object_key, title, evidence)
    SELECT 'orphan',
           x.object_key,
           format('%s holds %s rows and nothing references it', x.object_key, coalesce(x.row_count::text, '?')),
           jsonb_build_object('row_count', x.row_count, 'bytes', x.bytes, 'last_write_at', x.last_write_at)
      FROM orphans x
    ON CONFLICT (detector, subject_object_key, column_name)
    DO UPDATE SET last_seen_at = now(), evidence = excluded.evidence
    RETURNING 1
  )
  SELECT count(*) INTO n_orphan FROM upserted;

  RETURN jsonb_build_object('undiscovered_join', n_join, 'orphan', n_orphan);
END;
$_$;


ALTER FUNCTION "public"."clarity_run_detectors"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clarity_score"("w_size" numeric DEFAULT 0.20, "w_bytes" numeric DEFAULT 0.10, "w_degree" numeric DEFAULT 0.26, "w_app" numeric DEFAULT 0.18, "w_pipe" numeric DEFAULT 0.12, "w_recency" numeric DEFAULT 0.14, "w_unknown_recency" numeric DEFAULT 0.30, "w_act" numeric DEFAULT 0.50) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  max_rows  bigint;
  max_bytes bigint;
  n integer;
BEGIN
  SELECT GREATEST(max(row_count), 2), GREATEST(max(bytes), 2)
    INTO max_rows, max_bytes FROM clarity_object WHERE object_kind <> 'function';

  UPDATE clarity_object o SET importance = ROUND((
      -- how much of the estate it is
      w_size  * LEAST(1.0, ln(GREATEST(coalesce(o.row_count,0),1))::numeric / ln(max_rows::numeric))
    + w_bytes * LEAST(1.0, ln(GREATEST(o.bytes,1)+1)::numeric      / ln(max_bytes::numeric + 1))
      -- how central it is
    + w_degree * LEAST(1.0, ln(1 + o.degree)::numeric              / ln(41::numeric))
      -- whether a product surface reads it (distinct FILES, not hits)
    + w_app   * LEAST(1.0, ln(1 + o.refs_app)::numeric             / ln(26::numeric))
      -- whether a pipeline, DB function or downstream view depends on it
    + w_pipe  * LEAST(1.0, ln(1 + o.refs_script + o.refs_db_function + o.lineage_in)::numeric
                                                                   / ln(26::numeric))
      -- whether it is current
    + w_recency * CASE
        WHEN o.last_write_at IS NULL                            THEN w_unknown_recency
        WHEN o.last_write_at > now() - interval '7 days'         THEN 1.00
        WHEN o.last_write_at > now() - interval '30 days'        THEN 0.70
        WHEN o.last_write_at > now() - interval '180 days'       THEN 0.40
        WHEN o.last_write_at > now() - interval '730 days'       THEN 0.20
        ELSE 0.05 END
  )
  -- state penalty: a backup is not important because it is big
  * CASE o.state WHEN 'backup' THEN 0.05 WHEN 'staging' THEN 0.10
                 WHEN 'superseded' THEN 0.15 WHEN 'empty' THEN 0.25
                 WHEN 'tiny' THEN 0.60 ELSE 1.00 END
  -- lifecycle: this is a catalogue of DATA, not of application tables
  * CASE o.lifecycle
      WHEN 'core_source' THEN 1.00 WHEN 'derived' THEN 0.95 WHEN 'crosswalk' THEN 0.95
      WHEN 'app_operational' THEN 0.60 WHEN 'staging' THEN 0.25 WHEN 'backup' THEN 0.10
      WHEN 'superseded' THEN 0.20 WHEN 'scaffold_empty' THEN 0.30
      WHEN 'lens' THEN 0.85 WHEN 'routine' THEN 0.50 ELSE 0.80 END
  -- Ben's decision 1: ACT private business is not civic data
  * CASE WHEN o.act_business THEN w_act ELSE 1.00 END
  , 4)
  WHERE o.missing_since IS NULL;

  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$$;


ALTER FUNCTION "public"."clarity_score"("w_size" numeric, "w_bytes" numeric, "w_degree" numeric, "w_app" numeric, "w_pipe" numeric, "w_recency" numeric, "w_unknown_recency" numeric, "w_act" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clarity_set_probe"("p_object_key" "text", "p_kind" "text", "p_probe" "public"."clarity_probe", "p_rows" bigint DEFAULT NULL::bigint, "p_last_write" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ms" integer DEFAULT NULL::integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF p_kind = 'row_count' THEN
    UPDATE clarity_object
       SET row_count = COALESCE(p_rows, row_count),
           row_count_is_estimate = false,
           row_count_probe = p_probe,
           row_count_ms = p_ms
     WHERE object_key = p_object_key;
  ELSIF p_kind = 'freshness' THEN
    UPDATE clarity_object
       SET last_write_at = COALESCE(p_last_write, last_write_at),
           freshness_probe = p_probe,
           freshness_ms = p_ms
     WHERE object_key = p_object_key;
  ELSE
    RAISE EXCEPTION 'clarity_set_probe: unknown kind %', p_kind;
  END IF;
END;
$$;


ALTER FUNCTION "public"."clarity_set_probe"("p_object_key" "text", "p_kind" "text", "p_probe" "public"."clarity_probe", "p_rows" bigint, "p_last_write" timestamp with time zone, "p_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clarity_sync_house"() RETURNS TABLE("questions_upserted" integer, "answers_written" integer)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_q int := 0;
  v_a int := 0;
BEGIN
  -- A card that LOSES its price must stop being a want before anything else touches it.
  -- blocked_has_a_price forbids an unanswerable question with no unlock_effort, and the upsert
  -- below writes the new (null) price while the old state is still 'unanswerable' — so without
  -- this step the whole function aborts. That is exactly what happened when
  -- justice_edge_drillthrough was corrected and its fix_effort cleared: the gap was no longer
  -- real, so it no longer had a price, so the card could no longer be a want.
  UPDATE clarity_question q
     SET state = 'draft', updated_at = now()
    FROM clarity_gap_metric g
   WHERE q.subject = 'HOUSE'
     AND q.state = 'unanswerable'
     AND q.blocked_by_metric = g.metric_key
     AND (g.fix_effort IS NULL OR g.fix_note IS NULL);

  -- One question per enabled metric. Disabled metrics (matviews_unregistered, which waits on a
  -- table that does not exist yet) get no card, because a card whose number can never arrive is
  -- the failure this whole surface exists to stop.
  WITH upserted AS (
    INSERT INTO clarity_question (
      slug, stub, question, subject, state, form, honest_at, publishable,
      caveat, exclusions, claim_phrasing, answer_sql, blocked_by, blocked_by_metric,
      unlock_effort, unlock_note, unlock_dollars, uniqueness, uniqueness_basis, surface
    )
    SELECT
      'house-' || replace(g.metric_key, '_', '-'),
      upper(g.title),
      g.question,
      'HOUSE',
      -- Provisional. Set for real below, off the latest measurement.
      'draft'::clarity_question_state,
      'scalar'::clarity_form_kind,
      'none'::clarity_honest_at,
      'internal'::clarity_publishable,
      'Measured about this database by clarity_measure_gaps(), on the schedule in job 11. '
        || coalesce(g.note, ''),
      '',
      -- HOUSE questions are internal. They get no publishable claim phrasing, and the empty
      -- string is the honest value rather than a sentence nobody may quote.
      '',
      format('SELECT (%s) AS numerator, (%s) AS denominator', g.numerator_sql, g.denominator_sql),
      -- The blocker is the metric itself, not an object in the catalog. Prefixed so it can never
      -- be mistaken for an object_key by anything that joins on blocked_by.
      ARRAY['metric:' || g.metric_key],
      g.metric_key,
      g.fix_effort,
      g.fix_note,
      g.fix_dollars,
      1.0,
      'Measured about this database and nowhere else.',
      '/clarity/wants'
    FROM clarity_gap_metric g
    WHERE g.enabled
    ON CONFLICT (slug) DO UPDATE SET
      stub          = excluded.stub,
      question      = excluded.question,
      caveat        = excluded.caveat,
      answer_sql    = excluded.answer_sql,
      blocked_by    = excluded.blocked_by,
      unlock_effort = excluded.unlock_effort,
      unlock_note   = excluded.unlock_note,
      unlock_dollars= excluded.unlock_dollars,
      updated_at    = now()
    RETURNING 1
  )
  SELECT count(*)::int INTO v_q FROM upserted;

  -- State off the latest measurement. Four outcomes, never collapsed:
  --   answered     — measured, and inside target
  --   contested    — measured, and outside target. This is the adjudication CTA.
  --   unanswerable — never measured or the probe errored, AND somebody has priced the fix
  --   draft        — never measured and nobody has priced the fix. Registered, not yet a want.
  --
  -- That last split is forced by the blocked_has_a_price constraint slice 2 put on this table,
  -- and the constraint is right: an unanswerable question with no price is a complaint, not a
  -- want. It stays draft until someone fills in fix_effort.
  UPDATE clarity_question q
     SET state = CASE
           WHEN m.value IS NOT NULL AND m.status = 'ok' AND m.breached IS NOT TRUE THEN 'answered'
           WHEN m.value IS NOT NULL AND m.status = 'ok'                            THEN 'contested'
           WHEN g.fix_effort IS NOT NULL AND g.fix_note IS NOT NULL                THEN 'unanswerable'
           ELSE 'draft'
         END::clarity_question_state,
         updated_at = now()
    FROM clarity_gap_metric g
    LEFT JOIN v_clarity_metric_latest m ON m.metric_key = g.metric_key
   WHERE q.subject = 'HOUSE'
     AND q.blocked_by_metric = g.metric_key;

  -- A HOUSE card is a board card, so it needs an answer row like every other card. One answer per
  -- measurement, written once — re-running this function does not fabricate a new data point.
  WITH written AS (
    INSERT INTO clarity_answer (
      question_slug, computed_at, ok, headline, headline_sub, headline_num,
      coverage_num, coverage_den, coverage_label, row_count, duration_ms
    )
    SELECT
      q.slug,
      x.measured_at,
      x.status = 'ok',
      CASE
        WHEN x.value IS NULL THEN 'not measured'
        WHEN g.unit = 'pct'  THEN round(x.value, 1)::text || '%'
        ELSE round(x.value, 0)::text
      END,
      CASE
        WHEN g.target IS NULL THEN 'no target set'
        WHEN g.direction = 'higher_better' THEN 'target ≥ ' || g.target::text
        ELSE 'target ≤ ' || g.target::text
      END,
      x.value,
      x.numerator,
      x.denominator,
      g.unit,
      NULL,
      x.duration_ms
    FROM clarity_gap_measurement x
    JOIN clarity_gap_metric g   ON g.metric_key = x.metric_key
    JOIN clarity_question q     ON q.blocked_by_metric = x.metric_key AND q.subject = 'HOUSE'
    WHERE NOT EXISTS (
      SELECT 1 FROM clarity_answer a
       WHERE a.question_slug = q.slug AND a.computed_at = x.measured_at
    )
    RETURNING 1
  )
  SELECT count(*)::int INTO v_a FROM written;

  RETURN QUERY SELECT v_q, v_a;
END;
$$;


ALTER FUNCTION "public"."clarity_sync_house"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."clarity_sync_house"() IS 'Registers every enabled gap metric as a HOUSE question and mirrors its measurements into clarity_answer. Idempotent: re-running writes no duplicate answers. Called nightly by job 11.';



CREATE OR REPLACE FUNCTION "public"."classify_alma_topics"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  NEW.topics := ARRAY_REMOVE(ARRAY[
    CASE WHEN NEW.name ILIKE '%child%' OR NEW.name ILIKE '%protect%'
         OR NEW.name ILIKE '%foster%' OR NEW.name ILIKE '%out of home%'
    THEN 'child-protection' END,

    CASE WHEN NEW.name ILIKE '%youth%' OR NEW.name ILIKE '%justice%'
         OR NEW.name ILIKE '%juvenile%' OR NEW.name ILIKE '%detention%'
    THEN 'youth-justice' END,

    CASE WHEN NEW.name ILIKE '%disab%' OR NEW.name ILIKE '%ndis%'
    THEN 'ndis' END,

    CASE WHEN NEW.name ILIKE '%indigenous%' OR NEW.name ILIKE '%aboriginal%'
         OR NEW.type = 'Cultural Connection'
    THEN 'indigenous' END,

    CASE WHEN NEW.name ILIKE '%diversion%' OR NEW.type = 'Diversion'
    THEN 'diversion' END,

    CASE WHEN NEW.name ILIKE '%prevention%' OR NEW.type = 'Prevention'
         OR NEW.type = 'Early Intervention'
    THEN 'prevention' END,

    CASE WHEN NEW.type = 'Community-Led' OR NEW.type = 'Justice Reinvestment'
         OR NEW.name ILIKE '%community-led%' OR NEW.name ILIKE '%co-design%'
    THEN 'community-led' END,

    CASE WHEN NEW.type = 'Wraparound Support'
         OR NEW.name ILIKE '%wraparound%' OR NEW.name ILIKE '%support service%'
    THEN 'wraparound' END,

    CASE WHEN NEW.name ILIKE '%family%' OR NEW.type = 'Family Strengthening'
    THEN 'family-services' END
  ], NULL);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."classify_alma_topics"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classify_justice_funding_topics"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  NEW.topics := ARRAY_REMOVE(ARRAY[
    CASE WHEN NEW.program_name ILIKE '%child protection%'
         OR NEW.program_name ILIKE '%child safety%'
         OR NEW.program_name ILIKE '%out of home care%'
         OR NEW.program_name ILIKE '%foster care%'
         OR NEW.program_name ILIKE '%child related costs%'
         OR NEW.program_name ILIKE '%kinship%'
         OR NEW.program_name ILIKE '%residential care%'
         OR NEW.program_name ILIKE '%care leav%'
         OR NEW.program_name ILIKE '%community care%'
         OR NEW.program_name ILIKE '%specialised support service%'
         OR NEW.program_name ILIKE '%specialised assessment%'
         OR NEW.program_name ILIKE '%young adults exiting the care%'
    THEN 'child-protection' END,

    CASE WHEN NEW.program_name ILIKE '%youth justice%'
         OR NEW.program_name ILIKE '%juvenile%'
         OR NEW.program_name LIKE 'ROGS Youth Justice%'
         OR NEW.program_name ILIKE '%young offend%'
         OR NEW.program_name ILIKE '%youth offend%'
         OR NEW.program_name ILIKE '%bail support%'
         OR NEW.program_name ILIKE '%young people%'
    THEN 'youth-justice' END,

    CASE WHEN NEW.program_name ILIKE '%ndis%'
         OR NEW.program_name ILIKE '%disability%'
    THEN 'ndis' END,

    CASE WHEN NEW.program_name ILIKE '%family%'
         OR NEW.program_name ILIKE '%domestic violence%'
         OR NEW.program_name ILIKE '%sexual violence%'
         OR NEW.program_name ILIKE '%victim service%'
         OR NEW.program_name ILIKE '%homelessness%'
    THEN 'family-services' END,

    CASE WHEN NEW.program_name ILIKE '%indigenous%'
         OR NEW.program_name ILIKE '%aboriginal%'
         OR NEW.program_name ILIKE '%torres strait%'
    THEN 'indigenous' END,

    CASE WHEN NEW.program_name ILIKE '%legal%'
         OR NEW.program_name ILIKE '%court%'
    THEN 'legal-services' END,

    CASE WHEN NEW.program_name ILIKE '%diversion%'
         OR NEW.program_name ILIKE '%bail support%'
         OR NEW.program_name ILIKE '%conferencing%'
         OR NEW.program_name ILIKE '%restorative justice%'
         OR NEW.program_name ILIKE '%community justice group%'
    THEN 'diversion' END,

    CASE WHEN NEW.program_name ILIKE '%crime prevention%'
         OR NEW.program_name ILIKE '%community safety%'
         OR NEW.program_name ILIKE '%early intervention%'
         OR NEW.program_name ILIKE '%prevention%'
    THEN 'prevention' END,

    CASE WHEN NEW.program_name ILIKE '%community justice group%'
         OR NEW.program_name ILIKE '%community action%'
         OR NEW.program_name ILIKE '%social inclusion%'
         OR NEW.program_name ILIKE '%social enterprise%'
    THEN 'community-led' END
  ], NULL);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."classify_justice_funding_topics"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_expired_conversations"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  deleted_count INTEGER;
BEGIN
  DELETE FROM conversation_context
  WHERE expires_at < NOW();

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_expired_conversations"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cleanup_expired_conversations"() IS 'Removes expired chatbot sessions (called by cron)';



CREATE OR REPLACE FUNCTION "public"."cleanup_expired_proposals"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  UPDATE agent_proposals
  SET status = 'expired', updated_at = NOW()
  WHERE status = 'pending'
    AND deadline IS NOT NULL
    AND deadline < NOW();
END;
$$;


ALTER FUNCTION "public"."cleanup_expired_proposals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_old_audit_logs"("retention_days" integer DEFAULT 365) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    deleted_count INT;
BEGIN
    DELETE FROM agent_audit_log
    WHERE timestamp < NOW() - (retention_days || ' days')::INTERVAL;

    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_old_audit_logs"("retention_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_old_integration_events"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  deleted_count INTEGER;
BEGIN
  DELETE FROM integration_events
  WHERE created_at < NOW() - INTERVAL '30 days';
  GET DIAGNOSTICS deleted_count = ROW_COUNT;

  DELETE FROM webhook_delivery_log
  WHERE created_at < NOW() - INTERVAL '90 days';

  RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_old_integration_events"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_old_sync_events"("retention_days" integer DEFAULT 30) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM sync_events
    WHERE 
        sync_status IN ('completed', 'skipped')
        AND processed_at < NOW() - (retention_days || ' days')::INTERVAL;

    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    
    -- Also clean up old failed events that exceeded max retries
    DELETE FROM sync_events
    WHERE 
        sync_status = 'failed'
        AND retry_count >= max_retries
        AND created_at < NOW() - (retention_days || ' days')::INTERVAL;

    RETURN deleted_count;
END;
$$;


ALTER FUNCTION "public"."cleanup_old_sync_events"("retention_days" integer) OWNER TO "postgres";


