CREATE OR REPLACE FUNCTION "public"."community_voices_by_location"("p_state" "text" DEFAULT 'QLD'::"text") RETURNS json
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  SELECT json_agg(row_to_json(t) ORDER BY t.voice_count DESC)
  FROM (
    SELECT
      location,
      count(*) as voice_count,
      array_agg(DISTINCT unnested) FILTER (WHERE unnested IS NOT NULL) as all_priorities,
      count(DISTINCT author_name) FILTER (WHERE NOT author_anonymous) as named_authors
    FROM community_voices
    LEFT JOIN LATERAL unnest(priority_areas) AS unnested ON true
    WHERE state = p_state AND status = 'approved'
    GROUP BY location
  ) t;
$$;


ALTER FUNCTION "public"."community_voices_by_location"("p_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."community_voices_for_org"("p_org_id" "uuid") RETURNS json
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  SELECT json_agg(json_build_object(
    'id', cv.id,
    'location', cv.location,
    'author_role', cv.author_role,
    'what_is_needed', cv.what_is_needed,
    'what_is_working', cv.what_is_working,
    'what_is_harmful', cv.what_is_harmful,
    'what_success_looks_like', cv.what_success_looks_like,
    'priority_areas', cv.priority_areas,
    'created_at', cv.created_at
  ) ORDER BY cv.created_at DESC)
  FROM community_voices cv
  WHERE cv.organization_id = p_org_id AND cv.status = 'approved' AND cv.consent_level = 'public';
$$;


ALTER FUNCTION "public"."community_voices_for_org"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compare_interventions"("p_intervention_ids" "uuid"[]) RETURNS TABLE("intervention_id" "uuid", "name" "text", "type" "text", "geography" "text", "evidence_level" "text", "evidence_count" bigint, "outcome_count" bigint, "consent_level" "text", "cost_per_day" numeric, "outcome_types" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    i.id as intervention_id,
    i.name,
    i.type,
    i.geography,
    i.evidence_level,
    (SELECT COUNT(*) FROM alma_intervention_evidence ie WHERE ie.intervention_id = i.id) as evidence_count,
    (SELECT COUNT(*) FROM alma_intervention_outcomes io WHERE io.intervention_id = i.id) as outcome_count,
    i.consent_level,
    i.cost_per_participant_per_day as cost_per_day,
    (SELECT array_agg(DISTINCT o.outcome_type)
     FROM alma_intervention_outcomes io
     JOIN alma_outcomes o ON o.id = io.outcome_id
     WHERE io.intervention_id = i.id) as outcome_types
  FROM alma_interventions i
  WHERE i.id = ANY(p_intervention_ids)
  ORDER BY array_position(p_intervention_ids, i.id);
END;
$$;


ALTER FUNCTION "public"."compare_interventions"("p_intervention_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_ralph_task"("p_task_id" "uuid", "p_run_id" "uuid", "p_success" boolean, "p_output" "text" DEFAULT NULL::"text", "p_error" "text" DEFAULT NULL::"text", "p_commit_sha" "text" DEFAULT NULL::"text", "p_files_modified" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE v_prd_id UUID;
BEGIN
  SELECT prd_id INTO v_prd_id FROM ralph_tasks WHERE id = p_task_id;
  UPDATE ralph_tasks SET
    status = CASE WHEN p_success THEN 'completed' ELSE 'failed' END,
    passes = p_success, last_error = p_error, commit_sha = p_commit_sha,
    files_modified = p_files_modified, completed_at = NOW(), updated_at = NOW()
  WHERE id = p_task_id;
  UPDATE ralph_runs SET
    status = CASE WHEN p_success THEN 'completed' ELSE 'failed' END,
    success = p_success, output_summary = p_output, error_message = p_error,
    completed_at = NOW(), duration_ms = EXTRACT(EPOCH FROM (NOW() - started_at)) * 1000
  WHERE id = p_run_id;
  UPDATE ralph_prds SET
    completed_tasks = (SELECT COUNT(*) FROM ralph_tasks WHERE prd_id = v_prd_id AND status = 'completed'),
    failed_tasks = (SELECT COUNT(*) FROM ralph_tasks WHERE prd_id = v_prd_id AND status = 'failed'),
    updated_at = NOW()
  WHERE id = v_prd_id;
  UPDATE ralph_prds SET status = 'completed', completed_at = NOW()
  WHERE id = v_prd_id AND (SELECT COUNT(*) FROM ralph_tasks WHERE prd_id = v_prd_id AND status = 'pending') = 0;
END;
$$;


ALTER FUNCTION "public"."complete_ralph_task"("p_task_id" "uuid", "p_run_id" "uuid", "p_success" boolean, "p_output" "text", "p_error" "text", "p_commit_sha" "text", "p_files_modified" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_task"("p_task_id" "uuid", "p_output" "jsonb", "p_reasoning" "text" DEFAULT NULL::"text", "p_confidence" numeric DEFAULT NULL::numeric) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_agent_id TEXT;
  v_started_at TIMESTAMPTZ;
BEGIN
  -- Get task info
  SELECT assigned_agent, started_at INTO v_agent_id, v_started_at
  FROM agent_task_queue WHERE id = p_task_id;

  -- Update task
  UPDATE agent_task_queue
  SET status = 'done',
      output = p_output,
      reasoning = p_reasoning,
      confidence = p_confidence,
      completed_at = NOW(),
      duration_ms = EXTRACT(EPOCH FROM (NOW() - v_started_at))::INT * 1000,
      updated_at = NOW()
  WHERE id = p_task_id;

  -- Clear agent's current task
  UPDATE agents
  SET current_task_id = NULL,
      last_heartbeat = NOW()
  WHERE id = v_agent_id;
END;
$$;


ALTER FUNCTION "public"."complete_task"("p_task_id" "uuid", "p_output" "jsonb", "p_reasoning" "text", "p_confidence" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contact_matches_region"("contact_location" "text", "region_tags" "text"[]) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
    IF region_tags IS NULL OR array_length(region_tags, 1) IS NULL THEN
        RETURN false;
    END IF;
    
    IF contact_location IS NULL OR contact_location = '' THEN
        RETURN false;
    END IF;
    
    RETURN EXISTS (
        SELECT 1 FROM unnest(region_tags) AS tag
        WHERE LOWER(contact_location) LIKE '%' || LOWER(tag) || '%'
    );
END;
$$;


ALTER FUNCTION "public"."contact_matches_region"("contact_location" "text", "region_tags" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contact_matches_region"("contact_location" "text", "region_tags" "text"[]) IS 'Checks if contact location matches any of the opportunity region tags';



CREATE OR REPLACE FUNCTION "public"."contact_matches_role"("contact_position" "text", "contact_company" "text", "contact_industry" "text", "contact_skills" "text"[], "contact_alignment_tags" "text"[], "role_tags" "text"[]) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
    IF role_tags IS NULL OR array_length(role_tags, 1) IS NULL THEN
        RETURN false;
    END IF;
    
    RETURN EXISTS (
        SELECT 1 FROM unnest(role_tags) AS tag
        WHERE 
            (contact_position IS NOT NULL AND LOWER(contact_position) LIKE '%' || LOWER(tag) || '%')
            OR (contact_company IS NOT NULL AND LOWER(contact_company) LIKE '%' || LOWER(tag) || '%')
            OR (contact_industry IS NOT NULL AND LOWER(contact_industry) LIKE '%' || LOWER(tag) || '%')
            OR (contact_skills IS NOT NULL AND EXISTS (
                SELECT 1 FROM unnest(contact_skills) AS skill
                WHERE LOWER(skill) LIKE '%' || LOWER(tag) || '%'
            ))
            OR (contact_alignment_tags IS NOT NULL AND EXISTS (
                SELECT 1 FROM unnest(contact_alignment_tags) AS align_tag
                WHERE LOWER(align_tag) LIKE '%' || LOWER(tag) || '%'
            ))
    );
END;
$$;


ALTER FUNCTION "public"."contact_matches_role"("contact_position" "text", "contact_company" "text", "contact_industry" "text", "contact_skills" "text"[], "contact_alignment_tags" "text"[], "role_tags" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contact_matches_role"("contact_position" "text", "contact_company" "text", "contact_industry" "text", "contact_skills" "text"[], "contact_alignment_tags" "text"[], "role_tags" "text"[]) IS 'Checks if contact professional info matches any of the opportunity role tags';



CREATE OR REPLACE FUNCTION "public"."contract_browse_stats"("p_from_year" integer DEFAULT 2020) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'contracts', count(*),
    'total_value', sum(contract_value),
    'suppliers', count(DISTINCT COALESCE(NULLIF(supplier_abn, ''), lower(btrim(supplier_name)))),
    'buyers', count(DISTINCT lower(btrim(buyer_name)))
  )
  FROM austender_contracts
  WHERE contract_start >= make_date(GREATEST(COALESCE(p_from_year, 2020), 2000), 1, 1)
    AND contract_start < make_date(2031, 1, 1)
$$;


ALTER FUNCTION "public"."contract_browse_stats"("p_from_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contract_buyer_browse"("p_q" "text" DEFAULT NULL::"text", "p_from_year" integer DEFAULT 2020, "p_sort" "text" DEFAULT 'total'::"text", "p_limit" integer DEFAULT 200, "p_offset" integer DEFAULT 0) RETURNS TABLE("buyer_key" "text", "buyer_name" "text", "contract_count" bigint, "total_value" numeric, "supplier_count" bigint, "top_supplier" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    lower(btrim(c.buyer_name)) AS buyer_key,
    max(c.buyer_name) AS buyer_name,
    count(*) AS contract_count,
    sum(c.contract_value) AS total_value,
    count(DISTINCT COALESCE(NULLIF(c.supplier_abn, ''), lower(btrim(c.supplier_name)))) AS supplier_count,
    (array_agg(c.supplier_name ORDER BY c.contract_value DESC NULLS LAST))[1] AS top_supplier
  FROM austender_contracts c
  WHERE c.buyer_name IS NOT NULL AND btrim(c.buyer_name) <> ''
    AND c.contract_start >= make_date(GREATEST(COALESCE(p_from_year, 2020), 2000), 1, 1)
    AND c.contract_start < make_date(2031, 1, 1)
    AND (p_q IS NULL OR c.buyer_name ILIKE '%' || p_q || '%')
  GROUP BY lower(btrim(c.buyer_name))
  ORDER BY
    CASE WHEN p_sort = 'contracts' THEN count(*) END DESC NULLS LAST,
    CASE WHEN p_sort = 'suppliers' THEN count(DISTINCT COALESCE(NULLIF(c.supplier_abn, ''), lower(btrim(c.supplier_name)))) END DESC NULLS LAST,
    CASE WHEN p_sort = 'name' THEN max(c.buyer_name) END ASC NULLS LAST,
    sum(c.contract_value) DESC NULLS LAST,
    max(c.buyer_name) ASC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 200), 1), 500)
  OFFSET GREATEST(COALESCE(p_offset, 0), 0)
$$;


ALTER FUNCTION "public"."contract_buyer_browse"("p_q" "text", "p_from_year" integer, "p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contract_buyer_detail"("p_key" "text", "p_from_year" integer DEFAULT 2020) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH rows AS (
    SELECT c.title, c.supplier_name, c.contract_value, c.contract_start, c.contract_end, c.buyer_name
    FROM austender_contracts c
    WHERE lower(btrim(c.buyer_name)) = p_key
      AND c.contract_start >= make_date(GREATEST(COALESCE(p_from_year, 2020), 2000), 1, 1)
      AND c.contract_start < make_date(2031, 1, 1)
  )
  SELECT jsonb_build_object(
    'buyer_name', (SELECT max(buyer_name) FROM rows),
    'contract_count', (SELECT count(*) FROM rows),
    'total_value', (SELECT sum(contract_value) FROM rows),
    'suppliers', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('supplier', s.supplier_name, 'value', s.v, 'contracts', s.n) ORDER BY s.v DESC NULLS LAST), '[]'::jsonb)
      FROM (SELECT supplier_name, sum(contract_value) AS v, count(*) AS n FROM rows GROUP BY supplier_name ORDER BY sum(contract_value) DESC NULLS LAST LIMIT 12) s
    ),
    'contracts', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'title', g.title, 'supplier', g.supplier_name, 'value', g.contract_value,
        'start', g.contract_start, 'end', g.contract_end
      ) ORDER BY g.contract_value DESC NULLS LAST), '[]'::jsonb)
      FROM (SELECT * FROM rows ORDER BY contract_value DESC NULLS LAST LIMIT 50) g
    )
  )
$$;


ALTER FUNCTION "public"."contract_buyer_detail"("p_key" "text", "p_from_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contract_supplier_browse"("p_q" "text" DEFAULT NULL::"text", "p_from_year" integer DEFAULT 2020, "p_sort" "text" DEFAULT 'total'::"text", "p_limit" integer DEFAULT 200, "p_offset" integer DEFAULT 0) RETURNS TABLE("supplier_key" "text", "supplier_name" "text", "supplier_abn" "text", "contract_count" bigint, "total_value" numeric, "buyer_count" bigint, "top_buyer" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  SELECT
    COALESCE(NULLIF(c.supplier_abn, ''), m.abn, root.abn, n.nk) AS supplier_key,
    mode() WITHIN GROUP (ORDER BY c.supplier_name) AS supplier_name,
    max(COALESCE(NULLIF(c.supplier_abn, ''), m.abn, root.abn)) AS supplier_abn,
    count(*) AS contract_count,
    sum(c.contract_value) AS total_value,
    count(DISTINCT c.buyer_name) AS buyer_count,
    (array_agg(c.buyer_name ORDER BY c.contract_value DESC NULLS LAST))[1] AS top_buyer
  FROM austender_contracts c
  JOIN supplier_name_keys n ON n.supplier_name = c.supplier_name
  LEFT JOIN donor_key_abn m ON m.n = n.nk
  LEFT JOIN donor_key_abn root ON n.nk LIKE '% pty ltd'
        AND root.n = regexp_replace(n.nk, ' pty ltd$', '')
  WHERE c.contract_start >= make_date(GREATEST(COALESCE(p_from_year, 2020), 2000), 1, 1)
    AND c.contract_start < make_date(2031, 1, 1)
    AND (p_q IS NULL OR c.supplier_name ILIKE '%' || p_q || '%')
  GROUP BY COALESCE(NULLIF(c.supplier_abn, ''), m.abn, root.abn, n.nk)
  ORDER BY
    CASE WHEN p_sort = 'contracts' THEN count(*) END DESC NULLS LAST,
    CASE WHEN p_sort = 'buyers' THEN count(DISTINCT c.buyer_name) END DESC NULLS LAST,
    CASE WHEN p_sort = 'name' THEN mode() WITHIN GROUP (ORDER BY c.supplier_name) END ASC NULLS LAST,
    sum(c.contract_value) DESC NULLS LAST,
    mode() WITHIN GROUP (ORDER BY c.supplier_name) ASC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 200), 1), 500)
  OFFSET GREATEST(COALESCE(p_offset, 0), 0)
$_$;


ALTER FUNCTION "public"."contract_supplier_browse"("p_q" "text", "p_from_year" integer, "p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contract_supplier_detail"("p_key" "text", "p_from_year" integer DEFAULT 2020) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  WITH rows AS (
    SELECT c.title, c.buyer_name, c.contract_value, c.contract_start, c.contract_end, c.supplier_name, c.supplier_abn
    FROM austender_contracts c
    JOIN supplier_name_keys n ON n.supplier_name = c.supplier_name
    LEFT JOIN donor_key_abn m ON m.n = n.nk
    LEFT JOIN donor_key_abn root ON n.nk LIKE '% pty ltd'
          AND root.n = regexp_replace(n.nk, ' pty ltd$', '')
    WHERE COALESCE(NULLIF(c.supplier_abn, ''), m.abn, root.abn, n.nk) = p_key
      AND c.contract_start >= make_date(GREATEST(COALESCE(p_from_year, 2020), 2000), 1, 1)
      AND c.contract_start < make_date(2031, 1, 1)
  )
  SELECT jsonb_build_object(
    'supplier_name', (SELECT mode() WITHIN GROUP (ORDER BY supplier_name) FROM rows),
    'supplier_abn', (SELECT max(NULLIF(supplier_abn, '')) FROM rows),
    'contract_count', (SELECT count(*) FROM rows),
    'total_value', (SELECT sum(contract_value) FROM rows),
    'buyers', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('buyer', b.buyer_name, 'value', b.v, 'contracts', b.n) ORDER BY b.v DESC NULLS LAST), '[]'::jsonb)
      FROM (SELECT buyer_name, sum(contract_value) AS v, count(*) AS n FROM rows GROUP BY buyer_name ORDER BY sum(contract_value) DESC NULLS LAST LIMIT 12) b
    ),
    'contracts', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'title', g.title, 'buyer', g.buyer_name, 'value', g.contract_value,
        'start', g.contract_start, 'end', g.contract_end
      ) ORDER BY g.contract_value DESC NULLS LAST), '[]'::jsonb)
      FROM (SELECT * FROM rows ORDER BY contract_value DESC NULLS LAST LIMIT 50) g
    )
  )
$_$;


ALTER FUNCTION "public"."contract_supplier_detail"("p_key" "text", "p_from_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cosine_similarity"("a" "extensions"."vector", "b" "extensions"."vector") RETURNS double precision
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  -- Cosine similarity = 1 - cosine distance
  RETURN 1 - (a <=> b);
END;
$$;


