    CONSTRAINT "gs_entities_cc_tier_check" CHECK ((("community_controlled_tier" IS NULL) OR ("community_controlled_tier" = ANY (ARRAY['oric'::"text", 'acnc_indigenous'::"text", 'self_identified'::"text", 'board_analyzed'::"text", 'unclassified'::"text"])))),
    CONSTRAINT "gs_entities_confidence_check" CHECK (("confidence" = ANY (ARRAY['registry'::"text", 'verified'::"text", 'reported'::"text", 'inferred'::"text", 'unverified'::"text"]))),
    CONSTRAINT "gs_entities_entity_type_check" CHECK (("entity_type" = ANY (ARRAY['company'::"text", 'charity'::"text", 'foundation'::"text", 'government_body'::"text", 'indigenous_corp'::"text", 'political_party'::"text", 'person'::"text", 'social_enterprise'::"text", 'trust'::"text", 'unknown'::"text", 'program'::"text"])))
)
WITH ("autovacuum_analyze_scale_factor"='0.01', "autovacuum_vacuum_scale_factor"='0.05');


