COMMENT ON TABLE "public"."gs_entities" IS 'Unified entity registry — every organisation across all GrantScope datasets';



COMMENT ON COLUMN "public"."gs_entities"."oric_status" IS 'ORIC registration status. Deregistered corporations must not be presented as current organisations on any public surface.';



COMMENT ON COLUMN "public"."gs_entities"."oric_matched_by" IS 'How the ORIC record was matched: abn or exact_name. Exact_name is only used where the entity has no ABN.';



COMMENT ON COLUMN "public"."gs_entities"."lga_source" IS 'How the LGA was determined: registry_address where derived from a published address, inferred_from_org_name where taken from the community named in the organisation name. Null for pre-existing values.';



COMMENT ON COLUMN "public"."gs_entities"."oric_sector" IS 'ORIC industry sector. Available for many corporations that have no ABN and therefore no traceable funding, so it is often the only evidence of what an organisation does.';



COMMENT ON COLUMN "public"."gs_entities"."oric_income_band" IS 'ORIC income band as published. Bands are kept rather than converted to a midpoint, which would invent precision the source does not have.';



COMMENT ON COLUMN "public"."gs_entities"."oric_employee_band" IS 'ORIC workforce band as published (<5, 5 - 24, >24, 0). Kept as a band because the source does not give a count.';



CREATE TABLE IF NOT EXISTS "public"."gs_relationships" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_entity_id" "uuid" NOT NULL,
    "target_entity_id" "uuid" NOT NULL,
    "relationship_type" "text" NOT NULL,
    "amount" numeric,
    "currency" "text" DEFAULT 'AUD'::"text",
    "year" integer,
    "start_date" "date",
    "end_date" "date",
    "dataset" "text" NOT NULL,
    "source_record_id" "text",
    "source_url" "text",
    "confidence" "text" DEFAULT 'registry'::"text",
    "first_seen" timestamp with time zone DEFAULT "now"(),
    "last_seen" timestamp with time zone DEFAULT "now"(),
    "created_at" timestamp with time zone DEFAULT "now"(),
    "properties" "jsonb" DEFAULT '{}'::"jsonb",
    CONSTRAINT "gs_relationships_confidence_check" CHECK (("confidence" = ANY (ARRAY['registry'::"text", 'verified'::"text", 'reported'::"text", 'inferred'::"text", 'unverified'::"text"]))),
    CONSTRAINT "gs_relationships_relationship_type_check" CHECK (("relationship_type" = ANY (ARRAY['donation'::"text", 'party_receipt'::"text", 'contract'::"text", 'grant'::"text", 'directorship'::"text", 'ownership'::"text", 'charity_link'::"text", 'program_funding'::"text", 'tax_record'::"text", 'registered_as'::"text", 'listed_as'::"text", 'subsidiary_of'::"text", 'member_of'::"text", 'lobbies_for'::"text", 'partners_with'::"text", 'shared_director'::"text", 'affiliated_with'::"text", 'trustee_of'::"text", 'offers_grant_program'::"text"])))
)
WITH ("autovacuum_analyze_scale_factor"='0.005', "autovacuum_vacuum_scale_factor"='0.02');


ALTER TABLE "public"."gs_relationships" OWNER TO "postgres";


COMMENT ON TABLE "public"."gs_relationships" IS 'Entity graph edges — every connection (donation, contract, grant, etc.) between entities';



CREATE MATERIALIZED VIEW "public"."mv_gs_entity_stats" AS
 WITH "directional" AS (
         SELECT "gs_relationships"."source_entity_id" AS "entity_id",
            "gs_relationships"."target_entity_id" AS "counterparty_id",
            "gs_relationships"."relationship_type",
            "gs_relationships"."amount",
            "gs_relationships"."year",
            'outbound'::"text" AS "direction"
           FROM "public"."gs_relationships"
        UNION ALL
         SELECT "gs_relationships"."target_entity_id" AS "entity_id",
            "gs_relationships"."source_entity_id" AS "counterparty_id",
            "gs_relationships"."relationship_type",
            "gs_relationships"."amount",
            "gs_relationships"."year",
            'inbound'::"text" AS "direction"
           FROM "public"."gs_relationships"
        ), "type_stats" AS (
         SELECT "directional"."entity_id",
            "directional"."relationship_type",
            "directional"."direction",
            "count"(*) AS "rel_count",
            COALESCE("sum"("directional"."amount"), (0)::numeric) AS "rel_amount"
           FROM "directional"
          GROUP BY "directional"."entity_id", "directional"."relationship_type", "directional"."direction"
        ), "year_stats" AS (
         SELECT "directional"."entity_id",
            "directional"."year",
            "count"(*) AS "rel_count"
           FROM "directional"
          WHERE ("directional"."year" IS NOT NULL)
          GROUP BY "directional"."entity_id", "directional"."year"
        ), "counterparty_totals" AS (
         SELECT "directional"."entity_id",
            "directional"."counterparty_id",
            "sum"(COALESCE("directional"."amount", (0)::numeric)) AS "cp_total"
           FROM "directional"
          GROUP BY "directional"."entity_id", "directional"."counterparty_id"
        ), "concentration" AS (
         SELECT "counterparty_totals"."entity_id",
                CASE
                    WHEN ("sum"("counterparty_totals"."cp_total") > (0)::numeric) THEN ("max"("counterparty_totals"."cp_total") / "sum"("counterparty_totals"."cp_total"))
                    ELSE (0)::numeric
                END AS "top_counterparty_share",
            "count"(DISTINCT "counterparty_totals"."counterparty_id") AS "distinct_counterparties"
           FROM "counterparty_totals"
          GROUP BY "counterparty_totals"."entity_id"
        ), "entity_agg" AS (
         SELECT "type_stats"."entity_id",
            "sum"(
                CASE
                    WHEN ("type_stats"."direction" = 'outbound'::"text") THEN "type_stats"."rel_count"
                    ELSE (0)::bigint
                END) AS "outbound_count",
            "sum"(
                CASE
                    WHEN ("type_stats"."direction" = 'inbound'::"text") THEN "type_stats"."rel_count"
                    ELSE (0)::bigint
                END) AS "inbound_count",
            "sum"(
                CASE
                    WHEN ("type_stats"."direction" = 'outbound'::"text") THEN "type_stats"."rel_amount"
                    ELSE (0)::numeric
                END) AS "total_outbound_amount",
            "sum"(
                CASE
                    WHEN ("type_stats"."direction" = 'inbound'::"text") THEN "type_stats"."rel_amount"
                    ELSE (0)::numeric
                END) AS "total_inbound_amount",
            "array_agg"(DISTINCT "type_stats"."relationship_type") FILTER (WHERE ("type_stats"."direction" = 'outbound'::"text")) AS "outbound_types",
            "array_agg"(DISTINCT "type_stats"."relationship_type") FILTER (WHERE ("type_stats"."direction" = 'inbound'::"text")) AS "inbound_types",
            "jsonb_object_agg"((("type_stats"."relationship_type" || ':'::"text") || "type_stats"."direction"), "jsonb_build_object"('count', "type_stats"."rel_count", 'amount', "type_stats"."rel_amount", 'direction', "type_stats"."direction")) AS "type_breakdown"
           FROM "type_stats"
          GROUP BY "type_stats"."entity_id"
        ), "year_agg" AS (
         SELECT "year_stats"."entity_id",
            "jsonb_object_agg"(("year_stats"."year")::"text", "year_stats"."rel_count") AS "year_distribution"
           FROM "year_stats"
          GROUP BY "year_stats"."entity_id"
        )
 SELECT "e"."id",
    "e"."gs_id",
    "e"."canonical_name",
    "e"."entity_type",
    "e"."abn",
    "e"."source_count",
    COALESCE("ea"."outbound_count", (0)::numeric) AS "outbound_relationships",
    COALESCE("ea"."inbound_count", (0)::numeric) AS "inbound_relationships",
    (COALESCE("ea"."outbound_count", (0)::numeric) + COALESCE("ea"."inbound_count", (0)::numeric)) AS "total_relationships",
    COALESCE("ea"."total_outbound_amount", (0)::numeric) AS "total_outbound_amount",
    COALESCE("ea"."total_inbound_amount", (0)::numeric) AS "total_inbound_amount",
    "ea"."outbound_types",
    "ea"."inbound_types",
    COALESCE("ea"."type_breakdown", '{}'::"jsonb") AS "type_breakdown",
    COALESCE("ya"."year_distribution", '{}'::"jsonb") AS "year_distribution",
    COALESCE("c"."top_counterparty_share", (0)::numeric) AS "top_counterparty_share",
    COALESCE("c"."distinct_counterparties", (0)::bigint) AS "distinct_counterparties"
   FROM ((("public"."gs_entities" "e"
     JOIN "entity_agg" "ea" ON (("e"."id" = "ea"."entity_id")))
     LEFT JOIN "year_agg" "ya" ON (("e"."id" = "ya"."entity_id")))
     LEFT JOIN "concentration" "c" ON (("e"."id" = "c"."entity_id")))
  WHERE ((COALESCE("ea"."outbound_count", (0)::numeric) + COALESCE("ea"."inbound_count", (0)::numeric)) > (0)::numeric)
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_gs_entity_stats" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."counterparty_count"("public"."mv_gs_entity_stats") RETURNS bigint
    LANGUAGE "sql" STABLE
    AS $_$
  select $1.distinct_counterparties;
$_$;


