CREATE OR REPLACE FUNCTION "public"."create_review_reminders"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  pages_due CURSOR FOR
    SELECT id, title, slug, next_review_due, last_reviewed_at
    FROM wiki_pages
    WHERE status = 'active'
    AND next_review_due < NOW()
    AND NOT EXISTS (
      -- Don't create duplicate notifications
      SELECT 1 FROM wiki_notifications
      WHERE wiki_page_id = wiki_pages.id
      AND type = 'review_due'
      AND is_read = false
      AND created_at > NOW() - INTERVAL '7 days'
    );

  page_record RECORD;
  days_overdue INTEGER;
  notification_count INTEGER := 0;
BEGIN
  FOR page_record IN pages_due LOOP
    days_overdue := EXTRACT(DAY FROM NOW() - page_record.next_review_due)::INTEGER;

    INSERT INTO wiki_notifications (
      type,
      title,
      message,
      link,
      priority,
      wiki_page_id,
      metadata
    ) VALUES (
      'review_due',
      'Page Due for Review',
      page_record.title || ' is ' || days_overdue || ' days overdue for review',
      '/wiki/' || page_record.slug || '/edit',
      CASE
        WHEN days_overdue > 30 THEN 'urgent'
        WHEN days_overdue > 14 THEN 'high'
        WHEN days_overdue > 7 THEN 'normal'
        ELSE 'low'
      END,
      page_record.id,
      jsonb_build_object(
        'days_overdue', days_overdue,
        'last_reviewed_at', page_record.last_reviewed_at,
        'next_review_due', page_record.next_review_due
      )
    );

    notification_count := notification_count + 1;
  END LOOP;

  RETURN notification_count;
END;
$$;


ALTER FUNCTION "public"."create_review_reminders"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."create_review_reminders"() IS 'Creates notifications for pages due for review (run daily)';



CREATE OR REPLACE FUNCTION "public"."dashboard_foundation_tiers"() RETURNS TABLE("tier" "text", "count" bigint, "avg_giving" numeric, "total_giving" numeric, "color" "text")
    LANGUAGE "sql" STABLE
    AS $_$
  WITH tiered AS (
    SELECT
      CASE
        WHEN total_giving_annual >= 5000000 THEN 'Major ($5M+)'
        WHEN total_giving_annual >= 1000000 THEN 'Large ($1-5M)'
        WHEN total_giving_annual >= 250000 THEN 'Medium ($250K-1M)'
        WHEN total_giving_annual >= 50000 THEN 'Small ($50-250K)'
        ELSE 'Micro (<$50K)'
      END AS tier,
      CASE
        WHEN total_giving_annual >= 5000000 THEN 5000000
        WHEN total_giving_annual >= 1000000 THEN 1000000
        WHEN total_giving_annual >= 250000 THEN 250000
        WHEN total_giving_annual >= 50000 THEN 50000
        ELSE 0
      END AS min_value,
      CASE
        WHEN total_giving_annual >= 5000000 THEN '#059669'
        WHEN total_giving_annual >= 1000000 THEN '#7c3aed'
        WHEN total_giving_annual >= 250000 THEN '#F0C020'
        WHEN total_giving_annual >= 50000 THEN '#f97316'
        ELSE '#777777'
      END AS color,
      total_giving_annual
    FROM public.foundations
    WHERE total_giving_annual IS NOT NULL
  )
  SELECT
    tier,
    count(*) AS count,
    round(avg(total_giving_annual))::numeric AS avg_giving,
    round(sum(total_giving_annual))::numeric AS total_giving,
    color
  FROM tiered
  GROUP BY tier, min_value, color
  ORDER BY min_value DESC;
$_$;


