CREATE OR REPLACE FUNCTION "public"."entity_name_key"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $_$
  SELECT btrim(
    regexp_replace(
      regexp_replace(
        regexp_replace(lower(btrim(p_name)), '[.,''`]', '', 'g'),
        '\s+', ' ', 'g'),
      '\s*\m(proprietary|pty|p/l)(\s+(limited|ltd))?\s*$', ' pty ltd')
  )
$_$;


