CREATE OR REPLACE FUNCTION "public"."estate_cost_measures"() RETURNS TABLE("db_bytes" bigint, "unused_index_bytes" bigint, "unused_index_count" integer, "index_bytes_total" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  SELECT
    pg_database_size(current_database())::bigint,
    coalesce(sum(pg_relation_size(i.oid)) FILTER (
      WHERE s.idx_scan = 0 AND NOT x.indisunique AND NOT x.indisprimary
    ), 0)::bigint,
    count(*) FILTER (
      WHERE s.idx_scan = 0 AND NOT x.indisunique AND NOT x.indisprimary
    )::integer,
    coalesce(sum(pg_relation_size(i.oid)), 0)::bigint
  FROM pg_stat_user_indexes s
  JOIN pg_class i ON i.oid = s.indexrelid
  JOIN pg_index x ON x.indexrelid = i.oid;
$$;


ALTER FUNCTION "public"."estate_cost_measures"() OWNER TO "postgres";


