CREATE OR REPLACE FUNCTION "public"."evaluate_autonomy_change"("p_action_name" "text", "p_window_days" integer DEFAULT 60) RETURNS TABLE("current_level" integer, "recommended_level" integer, "success_rate" numeric, "sample_size" bigint, "rejection_rate" numeric, "reason" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_current_level INTEGER;
  v_success DECIMAL;
  v_rejection DECIMAL;
  v_sample BIGINT;
  v_recommend INTEGER;
  v_reason TEXT;
BEGIN
  SELECT autonomy_level INTO v_current_level
  FROM agent_actions WHERE action_name = p_action_name;

  SELECT
    ROUND(100.0 * COUNT(*) FILTER (WHERE status = 'completed') /
      NULLIF(COUNT(*) FILTER (WHERE status IN ('completed', 'failed')), 0), 2),
    ROUND(100.0 * COUNT(*) FILTER (WHERE status = 'rejected') /
      NULLIF(COUNT(*) FILTER (WHERE status IN ('approved', 'rejected', 'completed')), 0), 2),
    COUNT(*)
  INTO v_success, v_rejection, v_sample
  FROM agent_proposals
  WHERE action_name = p_action_name
    AND created_at > NOW() - (p_window_days || ' days')::INTERVAL;

  v_recommend := v_current_level;
  v_reason := 'No change recommended';

  IF v_success > 95 AND COALESCE(v_rejection, 0) < 5 AND v_sample > 20 THEN
    IF v_current_level < 3 THEN
      v_recommend := v_current_level + 1;
      v_reason := format('Excellent track record: %s%% success, %s%% rejection over %s actions',
        v_success, v_rejection, v_sample);
    END IF;
  ELSIF (v_success IS NOT NULL AND v_success < 80) OR (v_rejection IS NOT NULL AND v_rejection > 20) THEN
    IF v_current_level > 1 THEN
      v_recommend := v_current_level - 1;
      v_reason := format('Poor track record: %s%% success, %s%% rejection over %s actions',
        v_success, v_rejection, v_sample);
    END IF;
  END IF;

  RETURN QUERY SELECT v_current_level, v_recommend, v_success, v_sample, v_rejection, v_reason;
END;
$$;


ALTER FUNCTION "public"."evaluate_autonomy_change"("p_action_name" "text", "p_window_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."exec_agent_sql"("query_text" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result jsonb;
  normalized text;
BEGIN
  normalized := upper(trim(query_text));

  -- Only allow SELECT and WITH (CTE) statements
  IF NOT (normalized LIKE 'SELECT%' OR normalized LIKE 'WITH%') THEN
    RETURN jsonb_build_object(
      'error', 'Only SELECT queries are allowed.',
      'hint', 'Use SELECT to read data. INSERT, UPDATE, DELETE, and DDL are blocked.'
    );
  END IF;

  -- Block multiple statements (semicolons in the middle)
  IF position(';' in trim(trailing ';' from trim(query_text))) > 0 THEN
    RETURN jsonb_build_object(
      'error', 'Multiple SQL statements are not allowed.',
      'hint', 'Send one SELECT query at a time.'
    );
  END IF;

  -- Execute the query and capture results as JSON
  EXECUTE 'SELECT coalesce(jsonb_agg(row_to_json(t)), ''[]''::jsonb) FROM (' || query_text || ') t'
    INTO result;

  RETURN result;

EXCEPTION
  WHEN insufficient_privilege THEN
    RETURN jsonb_build_object(
      'error', 'Permission denied. The agent can only read data, not modify it.',
      'detail', SQLERRM
    );
  WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'error', SQLERRM,
      'hint', 'Check your SQL syntax and table/column names.'
    );
END;
$$;


ALTER FUNCTION "public"."exec_agent_sql"("query_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."exec_agent_sql"("query_text" "text") IS 'Executes a read-only SQL query (SELECT/WITH only, single statement). Used by the Telegram bot and web chat agent tools. Blocks INSERT, UPDATE, DELETE, DDL, and multi-statement queries.';



CREATE OR REPLACE FUNCTION "public"."exec_sql"("query" "text") RETURNS SETOF json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY EXECUTE 'SELECT row_to_json(t) FROM (' || query || ') t';
END;
$$;


