CREATE OR REPLACE FUNCTION "public"."exhibition_search"("q" "text", "lim" integer DEFAULT 8) RETURNS TABLE("result_type" "text", "id" "text", "title" "text", "subtitle" "text", "detail" "text", "meta" "jsonb", "slug" "text", "similarity" numeric)
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  qc text := trim(lower(q));
BEGIN
  RETURN QUERY
  (SELECT
    'organization'::text, o.id::text, o.name,
    COALESCE(o.city, o.state, '')::text,
    COALESCE(o.description, '')::text,
    jsonb_build_object(
      'state', o.state, 'acco_certified', o.acco_certified,
      'is_indigenous_org', o.is_indigenous_org,
      'logo_url', o.logo_url, 'website', COALESCE(o.website_url, o.website),
      'tier1', cls.is_tier1
    ),
    o.slug::text,
    -- YJ boost: Tier 1 confirmed +0.6, ACCO +0.3, has-intervention +0.2
    (GREATEST(similarity(lower(o.name), qc), COALESCE(similarity(lower(o.city), qc), 0))
      + CASE WHEN cls.is_tier1 THEN 0.6 ELSE 0 END
      + CASE WHEN o.acco_certified THEN 0.3 ELSE 0 END
      + CASE WHEN cls.has_intervention THEN 0.2 ELSE 0 END
    )::numeric
  FROM organizations o
  LEFT JOIN LATERAL (
    SELECT
      EXISTS (SELECT 1 FROM civic_org_classifications cc WHERE cc.organization_id = o.id AND cc.tier = 1 AND cc.confirmed_at IS NOT NULL) AS is_tier1,
      EXISTS (SELECT 1 FROM alma_interventions i WHERE i.operating_organization_id = o.id AND i.verification_status <> 'ai_generated') AS has_intervention
  ) cls ON true
  WHERE o.archived <> true AND o.is_active = true
    AND (o.name ILIKE '%' || q || '%' OR similarity(lower(o.name), qc) > 0.3 OR similarity(lower(COALESCE(o.city, '')), qc) > 0.4)
  ORDER BY 8 DESC LIMIT lim)
  UNION ALL
  (SELECT
    'claim'::text, c.claim_id::text,
    COALESCE(c.display_label, c.claim_id)::text,
    CONCAT(c.chapter, ' · ', c.region)::text,
    COALESCE(c.value_text, '')::text,
    jsonb_build_object('chapter', c.chapter, 'region', c.region, 'tier', c.tier),
    c.claim_id::text,
    GREATEST(similarity(lower(COALESCE(c.display_label, '')), qc), similarity(lower(COALESCE(c.value_text, '')), qc))::numeric
  FROM civic_intelligence_claims c
  WHERE c.display_label ILIKE '%' || q || '%' OR c.value_text ILIKE '%' || q || '%' OR c.region ILIKE '%' || q || '%'
  ORDER BY 8 DESC LIMIT lim)
  UNION ALL
  (SELECT
    'gov_program'::text, p.id::text, p.name::text, p.jurisdiction::text,
    COALESCE(p.description, '')::text,
    jsonb_build_object('jurisdiction', p.jurisdiction, 'budget', p.budget_amount, 'status', p.status, 'community_led', p.community_led, 'evidence_community_led', p.evidence_community_led),
    NULL::text,
    similarity(lower(p.name), qc)::numeric
  FROM alma_government_programs p
  WHERE p.name ILIKE '%' || q || '%' OR p.jurisdiction ILIKE '%' || q || '%' OR similarity(lower(p.name), qc) > 0.3
  ORDER BY 8 DESC LIMIT lim)
  UNION ALL
  (SELECT
    'grant_opportunity'::text, g.id::text, g.name::text,
    COALESCE(g.provider, g.source, '')::text,
    COALESCE(g.description, '')::text,
    jsonb_build_object('amount_min', g.amount_min, 'amount_max', g.amount_max, 'deadline', g.deadline, 'provider', g.provider, 'url', g.url),
    NULL::text,
    similarity(lower(g.name), qc)::numeric
  FROM grant_opportunities g
  WHERE g.name ILIKE '%' || q || '%' OR similarity(lower(g.name), qc) > 0.3
  ORDER BY 8 DESC LIMIT lim)
  UNION ALL
  (SELECT
    'foundation'::text, o.id::text, o.name::text,
    COALESCE(o.city, o.state, '')::text,
    COALESCE(o.description, '')::text,
    jsonb_build_object('state', o.state, 'website', COALESCE(o.website_url, o.website)),
    o.slug::text,
    similarity(lower(o.name), qc)::numeric
  FROM organizations o
  WHERE o.type = 'foundation' AND o.archived <> true
    AND (o.name ILIKE '%' || q || '%' OR similarity(lower(o.name), qc) > 0.3)
  ORDER BY 8 DESC LIMIT lim);
END;
$$;


