CREATE OR REPLACE FUNCTION "public"."foundation_browse"("p_q" "text" DEFAULT NULL::"text", "p_type" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'giving'::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "name" "text", "abn" "text", "type" "text", "giving" numeric, "grantees" bigint, "board_links" bigint, "ais_year" integer, "granted" numeric, "total_assets" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  WITH g AS (
    SELECT foundation_id, count(*) AS n FROM mv_foundation_grantees GROUP BY 1
  ), b AS (
    SELECT foundation_id, count(*) AS n FROM funder_board_paths GROUP BY 1
  )
  SELECT f.id, f.name, f.acnc_abn, f.type,
         f.total_giving_annual,
         coalesce(g.n, 0), coalesce(b.n, 0),
         ais.ais_year::int, ais.grants_donations_au, ais.total_assets
    FROM foundations f
    LEFT JOIN g ON g.foundation_id = f.id
    LEFT JOIN b ON b.foundation_id = f.id
    -- LATERAL latest-AIS probe per foundation: the DISTINCT ON version deduplicated all 361K
    -- AIS rows on every call (74s); ~11K index probes via idx_acnc_ais_lookup run in ~1s.
    LEFT JOIN LATERAL (
      SELECT a.ais_year, a.grants_donations_au, a.total_assets
        FROM acnc_ais a
       WHERE a.abn = f.acnc_abn
       ORDER BY a.ais_year DESC
       LIMIT 1
    ) ais ON true
   WHERE (p_q IS NULL OR f.name ILIKE '%' || p_q || '%')
     AND (p_type IS NULL OR f.type = p_type)
   ORDER BY
     CASE WHEN p_sort = 'giving'   THEN f.total_giving_annual END DESC NULLS LAST,
     CASE WHEN p_sort = 'assets'   THEN ais.total_assets END DESC NULLS LAST,
     CASE WHEN p_sort = 'granted'  THEN ais.grants_donations_au END DESC NULLS LAST,
     CASE WHEN p_sort = 'grantees' THEN coalesce(g.n, 0) END DESC,
     CASE WHEN p_sort = 'board'    THEN coalesce(b.n, 0) END DESC,
     f.name ASC
   LIMIT least(greatest(coalesce(p_limit, 200), 1), 500);
$$;


ALTER FUNCTION "public"."foundation_browse"("p_q" "text", "p_type" "text", "p_sort" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."funding_remoteness_by_topic"("p_topic" "text", "p_fy" "text" DEFAULT NULL::"text") RETURNS TABLE("remoteness" "text", "dollars" numeric, "grants" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    COALESCE(NULLIF(btrim(e.remoteness), ''), '(unplaced)') AS remoteness,
    sum(j.amount_dollars) AS dollars,
    count(*) AS grants
  FROM justice_funding j
  LEFT JOIN gs_entities e ON e.id = j.gs_entity_id
  WHERE j.measure_kind = 'grant'
    AND j.is_aggregate IS NOT TRUE
    AND j.recipient_name IS NOT NULL
    AND lower(btrim(j.recipient_name)) <> ALL (ARRAY[
      'total','totals','grand total','subtotal','sub-total','various',
      'n/a','na','unknown','tbc','other','(blank)'])
    AND (p_topic IS NULL OR j.topics @> ARRAY[p_topic])
    AND (NULLIF(p_fy, '') IS NULL OR j.financial_year = p_fy)
  GROUP BY 1
$$;


ALTER FUNCTION "public"."funding_remoteness_by_topic"("p_topic" "text", "p_fy" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_album_slug"("title_text" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    base_slug TEXT;
    final_slug TEXT;
    counter INTEGER := 0;
BEGIN
    -- Create base slug from title
    base_slug := lower(regexp_replace(title_text, '[^a-zA-Z0-9]+', '-', 'g'));
    base_slug := trim(both '-' from base_slug);
    final_slug := base_slug;
    
    -- Check if slug exists, if so add number
    WHILE EXISTS (SELECT 1 FROM photo_albums WHERE slug = final_slug) LOOP
        counter := counter + 1;
        final_slug := base_slug || '-' || counter;
    END LOOP;
    
    RETURN final_slug;
END;
$$;


ALTER FUNCTION "public"."generate_album_slug"("title_text" "text") OWNER TO "postgres";


