CREATE OR REPLACE FUNCTION "public"."get_calendar_events"("p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_project_code" "text" DEFAULT NULL::"text", "p_calendar_id" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "google_event_id" "text", "title" "text", "description" "text", "start_time" timestamp with time zone, "end_time" timestamp with time zone, "location" "text", "event_type" "text", "project_code" "text", "attendee_count" integer, "calendar_name" "text", "calendar_color" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ce.id,
    ce.google_event_id,
    ce.title,
    ce.description,
    ce.start_time,
    ce.end_time,
    ce.location,
    ce.event_type,
    ce.project_code,
    jsonb_array_length(ce.attendees)::INTEGER as attendee_count,
    ce.calendar_name,
    ce.calendar_color
  FROM calendar_events ce
  WHERE ce.status != 'cancelled'
    AND ce.start_time >= p_start_date
    AND ce.start_time < p_end_date
    AND (p_project_code IS NULL OR ce.project_code = p_project_code)
    AND (p_calendar_id IS NULL OR ce.google_calendar_id = p_calendar_id)
  ORDER BY ce.start_time ASC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_calendar_events"("p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone, "p_project_code" "text", "p_calendar_id" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_calendar_stats"("p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) RETURNS TABLE("total_events" integer, "total_hours" numeric, "events_by_type" "jsonb", "events_by_project" "jsonb", "top_attendees" "jsonb")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  WITH event_data AS (
    SELECT
      ce.*,
      EXTRACT(EPOCH FROM (ce.end_time - ce.start_time))/3600 as duration_hours
    FROM calendar_events ce
    WHERE ce.status != 'cancelled'
      AND ce.start_time >= p_start_date
      AND ce.start_time < p_end_date
  ),
  type_stats AS (
    SELECT jsonb_object_agg(
      COALESCE(event_type, 'unknown'),
      cnt
    ) as stats
    FROM (
      SELECT event_type, COUNT(*) as cnt
      FROM event_data
      GROUP BY event_type
    ) t
  ),
  project_stats AS (
    SELECT jsonb_object_agg(
      COALESCE(project_code, 'unlinked'),
      cnt
    ) as stats
    FROM (
      SELECT project_code, COUNT(*) as cnt
      FROM event_data
      WHERE project_code IS NOT NULL
      GROUP BY project_code
    ) t
  ),
  attendee_stats AS (
    SELECT jsonb_agg(jsonb_build_object(
      'email', att->>'email',
      'count', att_count
    ) ORDER BY att_count DESC) as stats
    FROM (
      SELECT att, COUNT(*) as att_count
      FROM event_data, jsonb_array_elements(attendees) att
      GROUP BY att
      ORDER BY att_count DESC
      LIMIT 10
    ) t
  )
  SELECT
    COUNT(*)::INTEGER as total_events,
    COALESCE(SUM(duration_hours), 0)::NUMERIC as total_hours,
    COALESCE((SELECT stats FROM type_stats), '{}'::JSONB) as events_by_type,
    COALESCE((SELECT stats FROM project_stats), '{}'::JSONB) as events_by_project,
    COALESCE((SELECT stats FROM attendee_stats), '[]'::JSONB) as top_attendees
  FROM event_data;
END;
$$;


ALTER FUNCTION "public"."get_calendar_stats"("p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_case_for_change"() RETURNS json
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $_$
DECLARE
  result json;
BEGIN
  SELECT json_build_object(
    'spending', (
      SELECT json_agg(row_to_json(s))
      FROM (
        SELECT financial_year, service_type,
          COALESCE(aust, 0) as aust,
          COALESCE(qld, 0) as qld,
          COALESCE(nsw, 0) as nsw,
          COALESCE(vic, 0) as vic,
          COALESCE(nt, 0) as nt
        FROM rogs_justice_spending
        WHERE rogs_section = 'youth_justice'
          AND measure = 'Real recurrent expenditure ($''000)'
        ORDER BY financial_year DESC
        LIMIT 30
      ) s
    ),
    'total_spending', (
      SELECT json_agg(row_to_json(t))
      FROM (
        SELECT financial_year,
          COALESCE(aust, 0) as aust,
          COALESCE(qld, 0) as qld
        FROM rogs_justice_spending
        WHERE rogs_section = 'youth_justice'
          AND measure = 'Total real recurrent expenditure ($''000)'
        ORDER BY financial_year DESC
        LIMIT 10
      ) t
    ),
    'indigenous', (
      SELECT json_agg(row_to_json(i))
      FROM (
        SELECT financial_year,
          COALESCE(aust, 0) as ratio,
          0 as indigenous_count,
          0 as total_count
        FROM rogs_justice_spending
        WHERE rogs_section = 'youth_justice'
          AND measure ILIKE '%rate ratio%Indigenous%'
        ORDER BY financial_year DESC
        LIMIT 10
      ) i
    ),
    'supervision', (
      SELECT json_agg(row_to_json(sv))
      FROM (
        SELECT financial_year, service_type,
          COALESCE(aust, 0) as total,
          0 as rate
        FROM rogs_justice_spending
        WHERE rogs_section = 'youth_justice'
          AND measure ILIKE '%average daily%'
        ORDER BY financial_year DESC
        LIMIT 20
      ) sv
    ),
    'interventions', (
      SELECT json_agg(row_to_json(iv))
      FROM (
        SELECT type, COUNT(*) as count
        FROM alma_interventions
        WHERE verification_status != 'ai_generated'
        GROUP BY type
        ORDER BY count DESC
      ) iv
    ),
    'funding_evidence', (
      SELECT json_build_object(
        'with_evidence', COALESCE((
          SELECT SUM(jf.amount_dollars)
          FROM justice_funding jf
          JOIN organizations o ON lower(jf.recipient_name) = lower(o.name)
          JOIN alma_interventions ai ON ai.operating_organization_id = o.id
          WHERE ai.verification_status != 'ai_generated'
        ), 0),
        'without_evidence', COALESCE((
          SELECT SUM(amount_dollars) FROM justice_funding
        ), 0) - COALESCE((
          SELECT SUM(jf.amount_dollars)
          FROM justice_funding jf
          JOIN organizations o ON lower(jf.recipient_name) = lower(o.name)
          JOIN alma_interventions ai ON ai.operating_organization_id = o.id
          WHERE ai.verification_status != 'ai_generated'
        ), 0)
      )
    ),
    'outcome_types', (
      SELECT json_agg(row_to_json(ot))
      FROM (
        SELECT ao.outcome_type, COUNT(DISTINCT aio.intervention_id) as intervention_count
        FROM alma_outcomes ao
        JOIN alma_intervention_outcomes aio ON ao.id = aio.outcome_id
        GROUP BY ao.outcome_type
        ORDER BY intervention_count DESC
      ) ot
    ),
    'intervention_outcome_matrix', (
      SELECT json_agg(row_to_json(m))
      FROM (
        SELECT ai.type as intervention_type, ao.outcome_type, COUNT(*) as link_count
        FROM alma_intervention_outcomes aio
        JOIN alma_interventions ai ON ai.id = aio.intervention_id
        JOIN alma_outcomes ao ON ao.id = aio.outcome_id
        WHERE ai.verification_status != 'ai_generated'
        GROUP BY ai.type, ao.outcome_type
        ORDER BY ai.type, link_count DESC
      ) m
    ),
    'detention_facilities', (
      SELECT json_agg(row_to_json(f))
      FROM (
        SELECT name, state, operational_status, capacity_beds,
          current_population, indigenous_population_percentage,
          has_therapeutic_programs, has_cultural_programs
        FROM youth_detention_facilities
        ORDER BY state, name
      ) f
    ),
    'stats', (
      SELECT json_build_object(
        'total_interventions', (SELECT COUNT(*) FROM alma_interventions WHERE verification_status != 'ai_generated'),
        'interventions_with_outcomes', (SELECT COUNT(DISTINCT intervention_id) FROM alma_intervention_outcomes),
        'total_outcomes', (SELECT COUNT(*) FROM alma_outcomes),
        'total_evidence', (SELECT COUNT(*) FROM alma_evidence),
        'total_orgs', (SELECT COUNT(*) FROM organizations),
        'indigenous_orgs', (SELECT COUNT(*) FROM organizations WHERE is_indigenous_org = true),
        'media_articles', (SELECT COUNT(*) FROM alma_media_articles),
        'detention_facilities', (SELECT COUNT(*) FROM youth_detention_facilities),
        'operational_facilities', (SELECT COUNT(*) FROM youth_detention_facilities WHERE operational_status = 'operational'),
        'total_beds', (SELECT COALESCE(SUM(capacity_beds), 0) FROM youth_detention_facilities WHERE operational_status = 'operational'),
        'total_current_population', (SELECT COALESCE(SUM(current_population), 0) FROM youth_detention_facilities WHERE operational_status = 'operational'),
        'avg_indigenous_pct', (SELECT ROUND(AVG(indigenous_population_percentage)) FROM youth_detention_facilities WHERE operational_status = 'operational' AND indigenous_population_percentage IS NOT NULL),
        'political_donations_total', (SELECT COALESCE(SUM(amount), 0) FROM political_donations),
        'political_donation_records', (SELECT COUNT(*) FROM political_donations),
        'case_studies', (SELECT COUNT(*) FROM alma_stories WHERE status = 'published'),
        'research_findings', (SELECT COUNT(*) FROM alma_research_findings WHERE validated = true),
        'source_documents', (SELECT COUNT(*) FROM alma_source_documents),
        'justice_cases_au', (SELECT COUNT(*) FROM justice_matrix_cases WHERE country_code = 'AU'),
        'active_campaigns', (SELECT COUNT(*) FROM justice_matrix_campaigns WHERE country_code = 'AU' AND is_ongoing = true)
      )
    )
  ) INTO result;

  RETURN result;
END;
$_$;


ALTER FUNCTION "public"."get_case_for_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_contacts_needing_attention"("days_threshold" integer DEFAULT 14) RETURNS TABLE("ghl_contact_id" "text", "last_communication" timestamp with time zone, "days_since_contact" integer, "total_communications" bigint, "last_direction" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  WITH last_comms AS (
    SELECT
      cc.ghl_contact_id,
      MAX(cc.occurred_at) AS last_communication,
      COUNT(*)::BIGINT AS total_communications,
      (SELECT direction FROM contact_communications cc2
       WHERE cc2.ghl_contact_id = cc.ghl_contact_id
       ORDER BY cc2.occurred_at DESC LIMIT 1) AS last_direction
    FROM contact_communications cc
    GROUP BY cc.ghl_contact_id
  )
  SELECT
    lc.ghl_contact_id,
    lc.last_communication,
    EXTRACT(DAY FROM NOW() - lc.last_communication)::INT AS days_since_contact,
    lc.total_communications,
    lc.last_direction
  FROM last_comms lc
  WHERE lc.last_communication < NOW() - (days_threshold || ' days')::INTERVAL
  ORDER BY lc.last_communication ASC;
END;
$$;


ALTER FUNCTION "public"."get_contacts_needing_attention"("days_threshold" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_contacts_needing_attention"("days_threshold" integer) IS 'Returns contacts who have not been contacted within the threshold days';



CREATE OR REPLACE FUNCTION "public"."get_contained_intel_summary"() RETURNS TABLE("tour_stops" integer, "programs_catalogued" integer, "strong_evidence_count" integer, "orgs_indexed" integer, "indigenous_led_orgs" integer, "funding_tracked_dollars" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    (SELECT count(*)::int FROM tour_stops WHERE campaign_slug = 'the-contained'),
    (SELECT count(*)::int FROM alma_interventions WHERE verification_status != 'ai_generated'),
    (SELECT count(*)::int FROM alma_interventions
      WHERE verification_status = 'verified'
        AND evidence_level IN (
          'Proven (RCT/quasi-experimental, replicated)',
          'Effective (strong evaluation, positive outcomes)',
          'Indigenous-led (culturally grounded, community authority)'
        )),
    (SELECT count(DISTINCT operating_organization_id)::int FROM alma_interventions
      WHERE verification_status != 'ai_generated'
        AND operating_organization_id IS NOT NULL),
    (SELECT count(DISTINCT i.operating_organization_id)::int
       FROM alma_interventions i
       JOIN organizations o ON o.id = i.operating_organization_id
      WHERE i.verification_status != 'ai_generated'
        AND o.is_indigenous_org = true),
    (SELECT coalesce(sum(amount_dollars), 0) FROM justice_funding
      WHERE alma_intervention_id IS NOT NULL);
$$;


