CREATE OR REPLACE FUNCTION "public"."get_feedback_adjusted_score"("p_user_id" "uuid", "p_grant_id" "uuid", "p_base_score" double precision) RETURNS double precision
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_boost FLOAT := 0;
  v_grant RECORD;
  v_up_count INT;
  v_down_count INT;
BEGIN
  SELECT provider, categories INTO v_grant
  FROM grant_opportunities WHERE id = p_grant_id;

  SELECT
    COALESCE(SUM(CASE WHEN f.vote = 1 THEN 1 ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN f.vote = -1 THEN 1 ELSE 0 END), 0)
  INTO v_up_count, v_down_count
  FROM grant_feedback f
  JOIN grant_opportunities g ON g.id = f.grant_id
  WHERE f.user_id = p_user_id
    AND (g.provider = v_grant.provider OR g.categories && v_grant.categories);

  v_boost := LEAST(v_up_count * 1.0, 5.0) - LEAST(v_down_count * 2.0, 10.0);

  RETURN LEAST(100, GREATEST(0, p_base_score + v_boost));
END;
$$;


ALTER FUNCTION "public"."get_feedback_adjusted_score"("p_user_id" "uuid", "p_grant_id" "uuid", "p_base_score" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_foundation_acnc_summary"() RETURNS TABLE("foundation_id" "uuid", "latest_year" integer, "total_assets" numeric, "grants_given" numeric, "total_revenue" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  SELECT f.id as foundation_id, 
    a.ais_year as latest_year,
