  FROM foundations f
  JOIN LATERAL (
    SELECT ais_year, total_assets, grants_donations_au, grants_donations_intl, total_revenue
    FROM acnc_ais
    WHERE abn = f.acnc_abn AND total_assets::numeric > 0
    ORDER BY ais_year DESC
    LIMIT 1
  ) a ON true;
$$;


