CREATE OR REPLACE FUNCTION "public"."get_grant_award_history"("p_grant_id" "uuid", "p_winner_limit" integer DEFAULT 8) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    AS $$
  with themes as (
    select unnest(grant_award_themes(p_grant_id)) as theme
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'theme', h.theme,
      'n_awards', h.n_awards,
      'distinct_recipients', h.distinct_recipients,
      'total_awarded', h.total_awarded,
      'median_award', h.median_award,
      'p25_award', h.p25_award,
      'p75_award', h.p75_award,
      'earliest_year', h.earliest_year,
      'latest_year', h.latest_year,
      'n_peer_recipients', h.n_peer_recipients,
      'peer_total_awarded', h.peer_total_awarded,
      'peer_median_award', h.peer_median_award,
      'n_community_controlled', h.n_community_controlled,
      'n_charity', h.n_charity,
      'n_social_enterprise', h.n_social_enterprise,
      'winners', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'recipient_name', w.recipient_name,
          'recipient_abn', w.recipient_abn,
          'gs_entity_id', w.gs_entity_id,
          'entity_type', w.entity_type,
          'is_community_controlled', w.is_community_controlled,
          'n_awards', w.n_awards,
          'total_awarded', w.total_awarded,
          'latest_year', w.latest_year
        ) order by w.rn), '[]'::jsonb)
        from mv_award_winner_by_theme w
        where w.theme = h.theme and w.rn <= p_winner_limit
      )
    ) order by h.total_awarded desc
  ), '[]'::jsonb)
  from themes t
  join mv_award_history_by_theme h on h.theme = t.theme;
$$;


ALTER FUNCTION "public"."get_grant_award_history"("p_grant_id" "uuid", "p_winner_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_grant_award_history"("p_grant_id" "uuid", "p_winner_limit" integer) IS 'Phase 6: award-history payload for a grant detail page — per-theme aggregates + top winners. Empty [] when the grant maps to no themes with historical awards.';



CREATE OR REPLACE FUNCTION "public"."get_grant_source_breakdown"() RETURNS TABLE("source" "text", "total" bigint, "has_description" bigint, "enriched" bigint, "embedded" bigint, "has_url" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  SELECT 
    source,
    count(*) as total,
    count(*) FILTER (WHERE description IS NOT NULL AND length(description) > 10) as has_description,
    count(*) FILTER (WHERE enriched_at IS NOT NULL) as enriched,
    count(*) FILTER (WHERE embedding IS NOT NULL) as embedded,
    count(*) FILTER (WHERE url IS NOT NULL) as has_url
  FROM grant_opportunities
  GROUP BY source
  ORDER BY count(*) DESC;
$$;


