CREATE OR REPLACE FUNCTION "public"."get_intervention_comprehensive"("p_intervention_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'intervention', row_to_json(i),
    'evidence', COALESCE((
      SELECT jsonb_agg(row_to_json(e))
      FROM alma_intervention_evidence ie
      JOIN alma_evidence e ON e.id = ie.evidence_id
      WHERE ie.intervention_id = p_intervention_id
    ), '[]'::JSONB),
    'outcomes', COALESCE((
      SELECT jsonb_agg(row_to_json(o))
      FROM alma_intervention_outcomes io
      JOIN alma_outcomes o ON o.id = io.outcome_id
      WHERE io.intervention_id = p_intervention_id
    ), '[]'::JSONB),
    'contexts', COALESCE((
      SELECT jsonb_agg(row_to_json(c))
      FROM alma_intervention_contexts ic
      JOIN alma_contexts c ON c.id = ic.context_id
      WHERE ic.intervention_id = p_intervention_id
    ), '[]'::JSONB),
    'related_articles', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'title', a.title,
        'content_type', a.content_type,
        'slug', a.slug
      ))
      FROM article_related_interventions ari
      JOIN articles a ON a.id = ari.article_id
      WHERE ari.intervention_id = p_intervention_id
    ), '[]'::JSONB)
  ) INTO result
  FROM alma_interventions i
  WHERE i.id = p_intervention_id;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_intervention_comprehensive"("p_intervention_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_jurisdiction_stats"("p_jurisdiction" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'jurisdiction', p_jurisdiction,
    'intervention_count', (
      SELECT COUNT(*) FROM alma_interventions
      WHERE geography = p_jurisdiction AND consent_level = 'Public Knowledge Commons'
    ),
    'intervention_types', (
      SELECT jsonb_object_agg(type, cnt)
      FROM (
        SELECT type, COUNT(*) as cnt
        FROM alma_interventions
        WHERE geography = p_jurisdiction AND consent_level = 'Public Knowledge Commons'
        GROUP BY type
      ) sub
    ),
    'evidence_levels', (
      SELECT jsonb_object_agg(COALESCE(evidence_level, 'Unknown'), cnt)
      FROM (
        SELECT evidence_level, COUNT(*) as cnt
        FROM alma_interventions
        WHERE geography = p_jurisdiction AND consent_level = 'Public Knowledge Commons'
        GROUP BY evidence_level
      ) sub
    ),
    'total_evidence_links', (
      SELECT COUNT(*)
      FROM alma_intervention_evidence ie
      JOIN alma_interventions i ON i.id = ie.intervention_id
      WHERE i.geography = p_jurisdiction
    ),
    'total_outcome_links', (
      SELECT COUNT(*)
      FROM alma_intervention_outcomes io
      JOIN alma_interventions i ON i.id = io.intervention_id
      WHERE i.geography = p_jurisdiction
    )
  ) INTO result;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_jurisdiction_stats"("p_jurisdiction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_knowledge_neighbors"("p_node_type" "text", "p_node_id" "uuid", "p_edge_types" "text"[] DEFAULT NULL::"text"[], "p_min_strength" double precision DEFAULT 0.0, "p_limit" integer DEFAULT 20) RETURNS TABLE("edge_id" "uuid", "edge_type" "text", "neighbor_type" "text", "neighbor_id" "uuid", "direction" "text", "strength" double precision, "confidence" double precision, "reasoning" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT ke.id, ke.edge_type, ke.target_type, ke.target_id,
         'outgoing'::TEXT, ke.strength, ke.confidence, ke.reasoning
  FROM knowledge_edges ke
  WHERE ke.source_type = p_node_type AND ke.source_id = p_node_id
    AND ke.strength >= p_min_strength AND ke.decay_score > 0.05
    AND (p_edge_types IS NULL OR ke.edge_type = ANY(p_edge_types))
  UNION ALL
  SELECT ke.id, ke.edge_type, ke.source_type, ke.source_id,
         'incoming'::TEXT, ke.strength, ke.confidence, ke.reasoning
  FROM knowledge_edges ke
  WHERE ke.target_type = p_node_type AND ke.target_id = p_node_id
    AND ke.strength >= p_min_strength AND ke.decay_score > 0.05
    AND (p_edge_types IS NULL OR ke.edge_type = ANY(p_edge_types))
  ORDER BY strength DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."get_knowledge_neighbors"("p_node_type" "text", "p_node_id" "uuid", "p_edge_types" "text"[], "p_min_strength" double precision, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_knowledge_subgraph"("p_node_type" "text", "p_node_id" "uuid", "p_hops" integer DEFAULT 2, "p_min_strength" double precision DEFAULT 0.3, "p_limit" integer DEFAULT 50) RETURNS TABLE("hop" integer, "edge_id" "uuid", "edge_type" "text", "from_type" "text", "from_id" "uuid", "to_type" "text", "to_id" "uuid", "strength" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 1, ke.id, ke.edge_type, ke.source_type, ke.source_id,
         ke.target_type, ke.target_id, ke.strength
  FROM knowledge_edges ke
  WHERE ((ke.source_type = p_node_type AND ke.source_id = p_node_id)
     OR (ke.target_type = p_node_type AND ke.target_id = p_node_id))
    AND ke.strength >= p_min_strength AND ke.decay_score > 0.05;

  IF p_hops >= 2 THEN
    RETURN QUERY
    SELECT 2, ke2.id, ke2.edge_type, ke2.source_type, ke2.source_id,
           ke2.target_type, ke2.target_id, ke2.strength
    FROM knowledge_edges ke1
    JOIN knowledge_edges ke2 ON (
      (ke2.source_type = ke1.target_type AND ke2.source_id = ke1.target_id)
      OR (ke2.target_type = ke1.target_type AND ke2.target_id = ke1.target_id)
    )
    WHERE ((ke1.source_type = p_node_type AND ke1.source_id = p_node_id)
       OR (ke1.target_type = p_node_type AND ke1.target_id = p_node_id))
      AND ke2.strength >= p_min_strength AND ke2.decay_score > 0.05
      AND ke2.id NOT IN (
        SELECT ke3.id FROM knowledge_edges ke3
        WHERE (ke3.source_type = p_node_type AND ke3.source_id = p_node_id)
           OR (ke3.target_type = p_node_type AND ke3.target_id = p_node_id)
      )
    LIMIT p_limit;
  END IF;
END;
$$;


ALTER FUNCTION "public"."get_knowledge_subgraph"("p_node_type" "text", "p_node_id" "uuid", "p_hops" integer, "p_min_strength" double precision, "p_limit" integer) OWNER TO "postgres";


