CREATE OR REPLACE FUNCTION "public"."get_pipeline_stats"() RETURNS TABLE("grants_total" bigint, "grants_embedded" bigint, "grants_described" bigint, "grants_expired" bigint, "grants_no_close" bigint, "foundations_total" bigint, "foundations_enriched" bigint, "foundations_unenriched" bigint, "foundations_high" bigint, "foundations_medium" bigint, "foundations_low" bigint, "foundations_recent_7d" bigint, "foundations_recent_30d" bigint, "se_total" bigint, "se_enriched" bigint, "se_indigenous" bigint, "community_orgs" bigint, "foundation_programs" bigint, "acnc_records" bigint)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    (SELECT count(*) FROM public.grant_opportunities) AS grants_total,
    (SELECT count(*) FROM public.grant_opportunities WHERE embedding IS NOT NULL) AS grants_embedded,
    (SELECT count(*) FROM public.grant_opportunities WHERE description IS NOT NULL) AS grants_described,
    (SELECT count(*) FROM public.grant_opportunities WHERE closes_at < current_date) AS grants_expired,
    (SELECT count(*) FROM public.grant_opportunities WHERE closes_at IS NULL) AS grants_no_close,
    (SELECT count(*) FROM public.foundations) AS foundations_total,
    (SELECT count(*) FROM public.foundations WHERE enriched_at IS NOT NULL) AS foundations_enriched,
    (SELECT count(*) FROM public.foundations WHERE website IS NOT NULL AND enriched_at IS NULL) AS foundations_unenriched,
    (SELECT count(*) FROM public.foundations WHERE profile_confidence = 'high') AS foundations_high,
    (SELECT count(*) FROM public.foundations WHERE profile_confidence = 'medium') AS foundations_medium,
    (SELECT count(*) FROM public.foundations WHERE profile_confidence = 'low') AS foundations_low,
    (SELECT count(*) FROM public.foundations WHERE enriched_at >= now() - interval '7 days') AS foundations_recent_7d,
    (SELECT count(*) FROM public.foundations WHERE enriched_at >= now() - interval '30 days') AS foundations_recent_30d,
    (SELECT count(*) FROM public.social_enterprises) AS se_total,
    (SELECT count(*) FROM public.social_enterprises WHERE enriched_at IS NOT NULL) AS se_enriched,
    (SELECT count(*) FROM public.social_enterprises WHERE org_type = 'indigenous_business') AS se_indigenous,
    (SELECT count(*) FROM public.community_orgs) AS community_orgs,
    (SELECT count(*) FROM public.foundation_programs WHERE status IN ('open', 'closed')) AS foundation_programs,
    (SELECT count(*) FROM public.acnc_ais) AS acnc_records;
$$;


ALTER FUNCTION "public"."get_pipeline_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_power_holder"("p_abn" "text" DEFAULT NULL::"text", "p_gs_id" "text" DEFAULT NULL::"text", "p_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    AS $$
  WITH e AS (
    SELECT *
    FROM mv_entity_power_index
    WHERE (p_abn   IS NOT NULL AND abn = p_abn)
       OR (p_abn   IS NULL AND p_gs_id IS NOT NULL AND gs_id = p_gs_id)
       OR (p_abn   IS NULL AND p_gs_id IS NULL AND p_name IS NOT NULL
           AND canonical_name ILIKE '%' || p_name || '%')
    ORDER BY power_score DESC NULLS LAST
    LIMIT 1
  )
  SELECT jsonb_build_object(
    'entity', jsonb_build_object(
      'gs_id', e.gs_id,
      'name', e.canonical_name,
      'abn', e.abn,
      'entity_type', e.entity_type,
      'state', e.state,
      'lga_name', e.lga_name,
      'is_community_controlled', e.is_community_controlled,
      'power_score', round(e.power_score)::int,
      'system_count', e.system_count,
      'total_dollar_flow', e.total_dollar_flow,
      'procurement_dollars', e.procurement_dollars,
      'justice_dollars', e.recorded_grants_dollars,
      'donation_dollars', e.donation_dollars,
      'foundation_giving', e.foundation_giving,
      'contract_count', e.contract_count,
      'distinct_govt_buyers', e.distinct_govt_buyers,
      'distinct_parties_funded', e.distinct_parties_funded,
      'systems', jsonb_build_object(
        'procurement', e.in_procurement,
        'justice', e.in_recorded_grants,
        'donations', e.in_political_donations,
        'charity', e.in_charity_registry,
        'foundation', e.in_foundation,
        'ato', e.in_ato_transparency,
        'ndis', e.in_ndis_provider
      )
    ),
    'board_people', COALESCE((
      SELECT jsonb_agg(x) FROM (
        SELECT jsonb_build_object(
                 'name', n.person_name_display,
                 'identity_key', n.identity_key,
                 'is_nominee_block', n.is_nominee_block
               ) AS x
        FROM mv_person_identity_network n
        WHERE n.entity_id = e.id
        ORDER BY n.is_nominee_block, n.person_name_display
        LIMIT 50
      ) s
    ), '[]'::jsonb),
    'foundation_backers', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('foundation', f.foundation_name, 'total', f.total) ORDER BY f.total DESC)
      FROM (
        SELECT foundation_name, sum(grant_amount) AS total
        FROM mv_foundation_grantees
        WHERE grantee_entity_id = e.id AND link_method = 'relationship'
        GROUP BY foundation_name
      ) f
    ), '[]'::jsonb),
    'revolving_door', (
      SELECT jsonb_build_object(
               'score', round(rd.revolving_door_score)::int,
               'influence_vectors', rd.influence_vectors,
               'lobbies', rd.lobbies,
               'donates', rd.donates,
               'contracts', rd.contracts,
               'receives_funding', rd.receives_funding,
               'donate_then_win', (rd.donates AND rd.contracts),
               'parties_funded', rd.parties_funded,
               'distinct_buyers', rd.distinct_buyers
             )
      FROM mv_revolving_door rd
      WHERE rd.id = e.id
    )
  )
  FROM e;
$$;


ALTER FUNCTION "public"."get_power_holder"("p_abn" "text", "p_gs_id" "text", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_power_map_board_connectors"("top_org_limit" integer DEFAULT 50, "min_boards" integer DEFAULT 2, "lim" integer DEFAULT 25) RETURNS TABLE("person_name" "text", "org_count" bigint, "org_names" "text"[])
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  WITH top_abns AS (
    SELECT o.abn
    FROM justice_funding jf
    JOIN organizations o ON o.id = jf.alma_organization_id
    WHERE jf.amount_dollars > 0 AND o.abn IS NOT NULL
    GROUP BY o.abn, o.id
    ORDER BY SUM(jf.amount_dollars) DESC
    LIMIT top_org_limit
  )
  SELECT 
    pr.person_name,
    COUNT(DISTINCT pr.company_abn) as org_count,
    array_agg(DISTINCT pr.company_name ORDER BY pr.company_name) as org_names
  FROM person_roles pr
  WHERE pr.cessation_date IS NULL
    AND pr.company_abn IN (SELECT abn FROM top_abns)
  GROUP BY pr.person_name
  HAVING COUNT(DISTINCT pr.company_abn) >= min_boards
  ORDER BY COUNT(DISTINCT pr.company_abn) DESC
  LIMIT lim;
$$;


ALTER FUNCTION "public"."get_power_map_board_connectors"("top_org_limit" integer, "min_boards" integer, "lim" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_power_map_control_breakdown"() RETURNS TABLE("control_type" "text", "org_count" bigint, "total_funding" numeric, "avg_funding" numeric, "program_count" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  WITH org_totals AS (
    SELECT 
      o.control_type,
      o.id,
      SUM(jf.amount_dollars) as org_funding
    FROM justice_funding jf
    JOIN organizations o ON o.id = jf.alma_organization_id
    WHERE jf.amount_dollars > 0
    GROUP BY o.control_type, o.id
  )
  SELECT 
    ot.control_type,
    COUNT(DISTINCT ot.id) as org_count,
    SUM(ot.org_funding) as total_funding,
    AVG(ot.org_funding) as avg_funding,
    (SELECT COUNT(*) FROM alma_interventions ai 
     JOIN organizations o2 ON o2.id = ai.operating_organization_id
     WHERE o2.control_type = ot.control_type AND ai.verification_status != 'ai_generated') as program_count
  FROM org_totals ot
  GROUP BY ot.control_type
  ORDER BY SUM(ot.org_funding) DESC;
$$;


ALTER FUNCTION "public"."get_power_map_control_breakdown"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_power_map_stats"() RETURNS TABLE("grand_total" numeric, "funded_org_count" bigint, "top10_total" numeric, "top50_total" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  WITH filtered AS (
    SELECT alma_organization_id, amount_dollars
    FROM justice_funding
    WHERE alma_organization_id IS NOT NULL
      AND amount_dollars IS NOT NULL AND amount_dollars > 0
      AND source NOT IN ('austender-direct', 'foundation-notable-grants', 'rogs-yj-expenditure', 'rogs-2026', 'aihw-yj')
      AND COALESCE(sector, '') NOT IN ('national_reporting')
      AND NOT (sector = 'community_services' AND (
        program_name ILIKE '%transport service contract%'
        OR program_name ILIKE '%bus operator%'
        OR program_name ILIKE '%rail concession%'
        OR program_name ILIKE '%sport & recreation%'
        OR program_name ILIKE '%gold coast light rail%'
        OR program_name ILIKE '%GCLR operator%'
        OR program_name ILIKE '%TAFE%'
      ))
  ),
  all_funding AS (
    SELECT alma_organization_id, SUM(amount_dollars) as org_total
    FROM filtered GROUP BY alma_organization_id
  ),
  ranked AS (
    SELECT org_total, ROW_NUMBER() OVER (ORDER BY org_total DESC) as rn
    FROM all_funding
  )
  SELECT
    (SELECT SUM(org_total) FROM all_funding),
    (SELECT COUNT(*) FROM all_funding),
    (SELECT COALESCE(SUM(org_total), 0) FROM ranked WHERE rn <= 10),
    (SELECT COALESCE(SUM(org_total), 0) FROM ranked WHERE rn <= 50);
$$;


ALTER FUNCTION "public"."get_power_map_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_power_map_top_orgs"("lim" integer DEFAULT 50) RETURNS TABLE("org_id" "uuid", "org_name" "text", "slug" "text", "state" "text", "control_type" "text", "is_indigenous_org" boolean, "acnc_size" "text", "abn" "text", "total_funding" numeric, "funding_records" bigint, "funding_sources" bigint, "program_count" bigint, "director_count" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  WITH org_funding AS (
    SELECT 
      jf.alma_organization_id,
      SUM(jf.amount_dollars) as total_funding,
      COUNT(*) as funding_records,
      COUNT(DISTINCT jf.source) as funding_sources
    FROM justice_funding jf
    WHERE jf.alma_organization_id IS NOT NULL
      AND jf.amount_dollars IS NOT NULL AND jf.amount_dollars > 0
      AND jf.source NOT IN ('austender-direct', 'foundation-notable-grants', 'rogs-yj-expenditure', 'rogs-2026', 'aihw-yj')
      AND COALESCE(jf.sector, '') NOT IN ('national_reporting')
      AND NOT (jf.sector = 'community_services' AND (
        jf.program_name ILIKE '%transport service contract%'
        OR jf.program_name ILIKE '%bus operator%'
        OR jf.program_name ILIKE '%rail concession%'
        OR jf.program_name ILIKE '%sport & recreation%'
        OR jf.program_name ILIKE '%gold coast light rail%'
        OR jf.program_name ILIKE '%GCLR operator%'
        OR jf.program_name ILIKE '%TAFE%'
      ))
    GROUP BY jf.alma_organization_id
    ORDER BY SUM(jf.amount_dollars) DESC
    LIMIT lim
  ),
  prog_counts AS (
    SELECT operating_organization_id, COUNT(*) as cnt
    FROM alma_interventions
    WHERE verification_status != 'ai_generated'
      AND operating_organization_id IN (SELECT alma_organization_id FROM org_funding)
    GROUP BY operating_organization_id
  ),
  dir_counts AS (
    SELECT pr.company_abn, COUNT(DISTINCT pr.person_name) as cnt
    FROM person_roles pr
    WHERE pr.cessation_date IS NULL
      AND pr.company_abn IN (
        SELECT o.abn FROM organizations o 
        WHERE o.id IN (SELECT alma_organization_id FROM org_funding) AND o.abn IS NOT NULL
      )
    GROUP BY pr.company_abn
  )
  SELECT o.id, o.name, o.slug, o.state, o.control_type, o.is_indigenous_org,
    o.acnc_data->>'charity_size', o.abn,
    f.total_funding, f.funding_records, f.funding_sources,
    COALESCE(p.cnt, 0), COALESCE(d.cnt, 0)
  FROM org_funding f
  JOIN organizations o ON o.id = f.alma_organization_id
  LEFT JOIN prog_counts p ON p.operating_organization_id = o.id
  LEFT JOIN dir_counts d ON d.company_abn = o.abn
  ORDER BY f.total_funding DESC;
$$;


ALTER FUNCTION "public"."get_power_map_top_orgs"("lim" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_context"("p_project_code" "text", "p_days" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "knowledge_type" "text", "title" "text", "content" "text", "summary" "text", "recorded_at" timestamp with time zone, "importance" "text", "decision_status" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    cutoff_date TIMESTAMPTZ;
BEGIN
    cutoff_date := NOW() - (p_days || ' days')::INTERVAL;

    RETURN QUERY
    -- Recent items
    SELECT
        pk.id,
        pk.knowledge_type,
        pk.title,
        pk.content,
        pk.summary,
        pk.recorded_at,
        pk.importance,
        pk.decision_status
    FROM project_knowledge pk
    WHERE pk.project_code = p_project_code
    AND (pk.recorded_at >= cutoff_date OR pk.importance IN ('critical', 'high'))
    ORDER BY
        CASE pk.importance
            WHEN 'critical' THEN 1
            WHEN 'high' THEN 2
            ELSE 3
        END,
        pk.recorded_at DESC
    LIMIT 25;
END;
$$;


ALTER FUNCTION "public"."get_project_context"("p_project_code" "text", "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_project_media"("p_link_type" "text", "p_link_id" "text") RETURNS TABLE("id" "uuid", "file_url" "text", "thumbnail_url" "text", "file_type" "text", "title" "text", "description" "text", "alt_text" "text", "caption" "text", "credit" "text", "width" integer, "height" integer, "blurhash" "text", "display_order" integer, "is_hero" boolean, "is_featured" boolean)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    m.id,
    m.file_url,
    COALESCE(m.thumbnail_url, '') as thumbnail_url,
    m.file_type,
    COALESCE(m.title, '') as title,
    COALESCE(m.description, '') as description,
    COALESCE(pml.alt_text, m.alt_text, '') as alt_text,
    COALESCE(pml.caption, m.caption, '') as caption,
    COALESCE(m.credit, '') as credit,
    COALESCE(m.width, 0) as width,
    COALESCE(m.height, 0) as height,
    COALESCE(m.blurhash, '') as blurhash,
    COALESCE(pml.display_order, 0) as display_order,
    COALESCE(pml.is_hero, false) as is_hero,
    COALESCE(pml.is_featured, false) as is_featured
  FROM media_items m
  INNER JOIN project_media_links pml ON m.id = pml.media_id
  WHERE pml.link_type = p_link_type
    AND pml.link_id = p_link_id
  ORDER BY pml.is_hero DESC, pml.display_order ASC, m.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_project_media"("p_link_type" "text", "p_link_id" "text") OWNER TO "postgres";


