    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        pk.id,
        pk.knowledge_type,
        pk.title,
        pk.content,
        pk.summary,
        pk.recorded_at,
        pk.participants,
        pk.importance,
        pk.action_required
    FROM project_knowledge pk
    WHERE pk.project_code = p_project_code
    AND (p_types IS NULL OR pk.knowledge_type = ANY(p_types))
    ORDER BY pk.recorded_at DESC
    LIMIT p_limit;
END;
