CREATE OR REPLACE FUNCTION "public"."get_timing_windows"() RETURNS TABLE("timing_window" "text", "match_count" bigint, "entity_count" bigint, "contract_value" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  SELECT
    timing_window,
    COUNT(*) as match_count,
    COUNT(DISTINCT abn) as entity_count,
    SUM(contract_value) as contract_value
  FROM mv_donation_contract_timing
  GROUP BY timing_window
  ORDER BY CASE timing_window
    WHEN 'immediate' THEN 1
    WHEN 'short' THEN 2
    WHEN 'medium' THEN 3
    WHEN 'long' THEN 4
    ELSE 5
  END;
$$;


ALTER FUNCTION "public"."get_timing_windows"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_top_justice_funding"() RETURNS TABLE("recipient_name" "text", "amount_dollars" numeric, "source" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT jf.recipient_name, jf.amount_dollars, jf.source
  FROM public.justice_funding AS jf
  WHERE jf.amount_dollars IS NOT NULL
    AND jf.amount_dollars > 0
  ORDER BY jf.amount_dollars DESC NULLS LAST
  LIMIT 30;
$$;


