CREATE OR REPLACE FUNCTION "public"."get_user_feedback_signals"("p_user_id" "uuid", "p_project_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_result jsonb;
  v_project_domains text[];
BEGIN
  IF p_project_profile_id IS NOT NULL THEN
    SELECT domains INTO v_project_domains
    FROM project_profiles WHERE id = p_project_profile_id;
  END IF;

  WITH user_feedback AS (
    SELECT f.grant_id, f.vote, f.reason, g.provider, g.categories, g.geography,
           g.closes_at, g.name AS grant_name
    FROM grant_feedback f
    JOIN grant_opportunities g ON g.id = f.grant_id
    WHERE f.user_id = p_user_id
      AND (p_project_profile_id IS NULL OR f.project_profile_id = p_project_profile_id OR f.project_profile_id IS NULL)
  ),
  excluded AS (
    SELECT jsonb_agg(DISTINCT grant_id) AS ids
    FROM user_feedback
  ),
  not_a_grant AS (
    SELECT jsonb_agg(DISTINCT f.grant_id) AS ids
    FROM grant_feedback f
    WHERE f.reason = 'Not a grant'
  ),
  penalized_providers AS (
    SELECT jsonb_agg(DISTINCT provider) AS names
    FROM (
      SELECT provider, COUNT(*) AS cnt
      FROM user_feedback
      WHERE vote = -1 AND provider IS NOT NULL
      GROUP BY provider
      HAVING COUNT(*) >= 2
    ) sub
  ),
  penalized_categories AS (
    SELECT jsonb_agg(DISTINCT cat) AS names
    FROM (
      SELECT unnest(categories) AS cat
      FROM user_feedback
      WHERE vote = -1 AND reason = 'Wrong sector'
    ) cats
    WHERE (
      SELECT COUNT(*)
      FROM user_feedback
      WHERE vote = -1 AND reason = 'Wrong sector'
    ) >= 3
    AND (
      v_project_domains IS NULL
      OR NOT EXISTS (
        SELECT 1 FROM unnest(v_project_domains) AS d
        WHERE lower(d) LIKE '%' || lower(cat) || '%'
           OR lower(cat) LIKE '%' || lower(d) || '%'
      )
    )
  ),
  penalized_geos AS (
    SELECT jsonb_agg(DISTINCT geography) AS names
    FROM user_feedback
    WHERE vote = -1 AND reason = 'Wrong location' AND geography IS NOT NULL
  ),
  -- Providers with thumbs-up
  boosted_providers AS (
    SELECT jsonb_agg(DISTINCT provider) AS names
    FROM user_feedback
    WHERE vote = 1 AND provider IS NOT NULL
  ),
  -- Categories from 'Right sector' or 'Strong fit' upvotes
  boosted_categories AS (
    SELECT jsonb_agg(DISTINCT cat) AS names
    FROM (
      SELECT unnest(categories) AS cat
      FROM user_feedback
      WHERE vote = 1 AND reason IN ('Right sector', 'Strong fit')
    ) cats
  ),
  -- Geographies from 'Right location' upvotes
  boosted_geos AS (
    SELECT jsonb_agg(DISTINCT geography) AS names
    FROM user_feedback
    WHERE vote = 1 AND reason = 'Right location' AND geography IS NOT NULL
  ),
  total AS (
    SELECT COUNT(*) AS cnt FROM user_feedback
  ),
  up_total AS (
    SELECT COUNT(*) AS cnt FROM user_feedback WHERE vote = 1
  ),
  down_total AS (
    SELECT COUNT(*) AS cnt FROM user_feedback WHERE vote = -1
  )
  SELECT jsonb_build_object(
    'excluded_grant_ids', COALESCE(excluded.ids, '[]'::jsonb),
    'not_a_grant_ids', COALESCE(not_a_grant.ids, '[]'::jsonb),
    'penalized_providers', COALESCE(penalized_providers.names, '[]'::jsonb),
    'penalized_categories', COALESCE(penalized_categories.names, '[]'::jsonb),
    'penalized_geos', COALESCE(penalized_geos.names, '[]'::jsonb),
    'boosted_providers', COALESCE(boosted_providers.names, '[]'::jsonb),
    'boosted_categories', COALESCE(boosted_categories.names, '[]'::jsonb),
    'boosted_geos', COALESCE(boosted_geos.names, '[]'::jsonb),
    'total_votes', total.cnt,
    'up_votes', up_total.cnt,
    'down_votes', down_total.cnt
  )
  INTO v_result
  FROM excluded, not_a_grant, penalized_providers, penalized_categories,
       penalized_geos, boosted_providers, boosted_categories, boosted_geos,
       total, up_total, down_total;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_user_feedback_signals"("p_user_id" "uuid", "p_project_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_week_start"("p_date" "date" DEFAULT CURRENT_DATE) RETURNS "date"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN p_date - (EXTRACT(DOW FROM p_date)::INTEGER + 6) % 7;
END;
$$;


