CREATE OR REPLACE FUNCTION "public"."get_yj_orgs_for_browser"() RETURNS TABLE("org_id" "uuid", "name" "text", "slug" "text", "abn" "text", "state" "text", "postcode" "text", "locality" "text", "lga_name" "text", "remoteness" "text", "sector" "text", "community_controlled" boolean, "cc_tier" "text", "supply_nation_certified" boolean, "charity_size" "text", "acnc_registered" boolean, "acnc_registration_date" "date", "ben_aboriginal_tsi" boolean, "ben_youth" boolean, "is_oric_corporation" boolean, "program_count" integer, "strong_evidence_count" integer, "funding_yj" numeric, "funding_all" numeric, "funding_records" integer, "funding_yj_records" integer, "org_row_count" integer, "lat" numeric, "lng" numeric, "tier" "text", "unmappable_reason" "text")
    LANGUAGE "sql" STABLE
    AS $$
  WITH yj_orgs AS (
    SELECT DISTINCT o.id AS jh_org_id, o.gs_entity_id,
      coalesce(o.gs_entity_id::text, o.id::text) AS group_key,
      o.name AS jh_name, o.slug
    FROM organizations o
    WHERE EXISTS (
      SELECT 1 FROM alma_interventions i
      WHERE i.operating_organization_id = o.id
        AND i.verification_status != 'ai_generated'
    )
  ),
  program_per_org AS (
    SELECT i.operating_organization_id AS jh_org_id,
           count(*)::int AS program_count,
           count(*) FILTER (WHERE i.evidence_level IN (
             'Proven (RCT/quasi-experimental, replicated)',
             'Effective (strong evaluation, positive outcomes)',
             'Indigenous-led (culturally grounded, community authority)'
           ))::int AS strong_evidence_count
    FROM alma_interventions i
    WHERE i.verification_status != 'ai_generated' AND i.operating_organization_id IS NOT NULL
    GROUP BY i.operating_organization_id
  ),
  rep_org AS (
    SELECT DISTINCT ON (y.group_key)
      y.group_key, y.jh_org_id AS rep_jh_org_id, y.gs_entity_id,
      y.jh_name AS rep_name, y.slug AS rep_slug
    FROM yj_orgs y
    LEFT JOIN program_per_org p ON p.jh_org_id = y.jh_org_id
    ORDER BY y.group_key, coalesce(p.program_count, 0) DESC, y.jh_org_id
  ),
  group_program_rollup AS (
    SELECT y.group_key,
           sum(coalesce(p.program_count, 0))::int AS program_count,
           sum(coalesce(p.strong_evidence_count, 0))::int AS strong_evidence_count,
           count(DISTINCT y.jh_org_id)::int AS org_row_count
    FROM yj_orgs y
    LEFT JOIN program_per_org p ON p.jh_org_id = y.jh_org_id
    GROUP BY y.group_key
  ),
  -- All-sector funding (context)
  group_funding_all AS (
    SELECT y.group_key,
           coalesce(sum(f.amount_dollars), 0) AS funding_all,
           count(DISTINCT f.id)::int AS funding_records
    FROM yj_orgs y
    JOIN organizations o ON o.id = y.jh_org_id
    LEFT JOIN justice_funding f
      ON (f.alma_organization_id = y.jh_org_id
          OR (o.abn IS NOT NULL AND f.recipient_abn = o.abn))
    GROUP BY y.group_key
  ),
  -- YJ-scoped funding: strict — sector='youth_justice' OR linked to a YJ intervention
  group_funding_yj AS (
    SELECT y.group_key,
           coalesce(sum(f.amount_dollars), 0) AS funding_yj,
           count(DISTINCT f.id)::int AS funding_yj_records
    FROM yj_orgs y
    JOIN organizations o ON o.id = y.jh_org_id
    LEFT JOIN justice_funding f
      ON (f.alma_organization_id = y.jh_org_id
          OR (o.abn IS NOT NULL AND f.recipient_abn = o.abn))
     AND (f.sector IN ('youth_justice','youth-justice','youth_services')
          OR f.alma_intervention_id IS NOT NULL)
    GROUP BY y.group_key
  ),
  joined AS (
    SELECT
      r.rep_jh_org_id AS org_id,
      coalesce(e.canonical_name, r.rep_name)::text AS name,
      r.rep_slug AS slug,
      e.abn,
      e.state,
      e.postcode,
      pg.locality,
      coalesce(e.lga_name, pg.lga_name)::text AS lga_name,
      coalesce(e.remoteness, pg.remoteness_2021)::text AS remoteness,
      e.sector,
      coalesce(e.is_community_controlled, false) AS community_controlled,
      e.community_controlled_tier AS cc_tier,
      coalesce(e.is_supply_nation_certified, false) AS supply_nation_certified,
      a.charity_size,
      (a.abn IS NOT NULL) AS acnc_registered,
      a.registration_date AS acnc_registration_date,
      coalesce(a.ben_aboriginal_tsi, false) AS ben_aboriginal_tsi,
      coalesce(a.ben_youth, false) AS ben_youth,
      coalesce(a.is_oric_corporation, false) AS is_oric_corporation,
      gp.program_count, gp.strong_evidence_count, gp.org_row_count,
      gfy.funding_yj, gfy.funding_yj_records,
      gfa.funding_all, gfa.funding_records,
      pg.latitude AS lat,
      pg.longitude AS lng,
      r.gs_entity_id,
      e.postcode IS NOT NULL AS gs_has_postcode,
      pg.latitude IS NOT NULL AS pg_has_coords
    FROM rep_org r
    LEFT JOIN gs_entities e ON e.id = r.gs_entity_id
    LEFT JOIN acnc_charities a ON a.abn = e.abn
    LEFT JOIN group_program_rollup gp ON gp.group_key = r.group_key
    LEFT JOIN group_funding_all gfa ON gfa.group_key = r.group_key
    LEFT JOIN group_funding_yj gfy ON gfy.group_key = r.group_key
    LEFT JOIN LATERAL (
      SELECT * FROM postcode_geo pg2
      WHERE pg2.postcode = e.postcode AND pg2.latitude IS NOT NULL
      LIMIT 1
    ) pg ON true
  )
  SELECT
    org_id, name, slug, abn, state, postcode, locality, lga_name, remoteness, sector,
    community_controlled, cc_tier, supply_nation_certified, charity_size, acnc_registered,
    acnc_registration_date, ben_aboriginal_tsi, ben_youth, is_oric_corporation,
    program_count, strong_evidence_count,
    funding_yj, funding_all, funding_records, funding_yj_records,
    org_row_count, lat, lng,
    -- Tier classification now uses YJ-scoped funding (defensible)
    CASE
      WHEN program_count >= 5 AND funding_yj >= 1000000 THEN 'heavy_lifter'
      WHEN program_count >= 3 OR funding_yj >= 500000 OR (community_controlled AND acnc_registered) THEN 'established'
      WHEN program_count >= 1 AND (acnc_registered OR community_controlled) THEN 'verified'
      ELSE 'emerging'
    END AS tier,
    CASE
      WHEN gs_entity_id IS NULL THEN 'no_gs_entity_link'
      WHEN NOT gs_has_postcode THEN 'no_postcode_in_gs_entity'
      WHEN NOT pg_has_coords THEN 'postcode_not_geocoded'
      ELSE NULL
    END AS unmappable_reason
  FROM joined;
$$;


ALTER FUNCTION "public"."get_yj_orgs_for_browser"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_yj_orgs_for_map"() RETURNS TABLE("org_id" "uuid", "name" "text", "abn" "text", "state" "text", "postcode" "text", "locality" "text", "lga_name" "text", "remoteness" "text", "sector" "text", "community_controlled" boolean, "cc_tier" "text", "program_count" integer, "lat" numeric, "lng" numeric, "unmappable_reason" "text")
    LANGUAGE "sql" STABLE
    AS $$
  WITH yj_orgs AS (
    SELECT
      o.id AS org_id,
      o.name AS jh_name,
      o.gs_entity_id,
      count(i.id)::int AS program_count
    FROM organizations o
    JOIN alma_interventions i ON i.operating_organization_id = o.id
    WHERE i.verification_status != 'ai_generated'
    GROUP BY o.id, o.name, o.gs_entity_id
  ),
  with_gs AS (
    SELECT
      y.*,
      e.canonical_name,
      e.abn,
      e.state,
      e.postcode,
      e.lga_name AS gs_lga,
      e.remoteness AS gs_remoteness,
      e.sector,
      e.is_community_controlled,
      e.community_controlled_tier
    FROM yj_orgs y
    LEFT JOIN gs_entities e ON e.id = y.gs_entity_id
  ),
  with_geo AS (
    SELECT DISTINCT ON (w.org_id)
      w.*,
      pg.latitude,
      pg.longitude,
      pg.locality,
      pg.lga_name AS pg_lga,
      pg.remoteness_2021 AS pg_remoteness
    FROM with_gs w
    LEFT JOIN postcode_geo pg
      ON pg.postcode = w.postcode AND pg.latitude IS NOT NULL
    ORDER BY w.org_id, pg.locality
  )
  SELECT
    org_id,
    coalesce(canonical_name, jh_name)::text AS name,
    abn,
    state,
    postcode,
    locality,
    coalesce(gs_lga, pg_lga)::text AS lga_name,
    coalesce(gs_remoteness, pg_remoteness)::text AS remoteness,
    sector,
    coalesce(is_community_controlled, false) AS community_controlled,
    community_controlled_tier AS cc_tier,
    program_count,
    latitude AS lat,
    longitude AS lng,
    CASE
      WHEN gs_entity_id IS NULL THEN 'no_gs_entity_link'
      WHEN postcode IS NULL THEN 'no_postcode_in_gs_entity'
      WHEN latitude IS NULL THEN 'postcode_not_geocoded'
      ELSE NULL
    END AS unmappable_reason
  FROM with_geo
  ORDER BY program_count DESC;
$$;


ALTER FUNCTION "public"."get_yj_orgs_for_map"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_yj_programs_for_browser"() RETURNS TABLE("program_id" "uuid", "name" "text", "type" "text", "description" "text", "evidence_level" "text", "target_cohort" "text"[], "geography" "text"[], "years_operating" integer, "cultural_authority" "text", "portfolio_score" numeric, "org_id" "uuid", "org_name" "text", "org_state" "text", "org_postcode" "text", "org_locality" "text", "org_lga" "text", "org_remoteness" "text", "org_community_controlled" boolean, "org_charity_size" "text")
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    i.id AS program_id,
    i.name,
    i.type,
    i.description,
    i.evidence_level,
    i.target_cohort,
    i.geography,
    i.years_operating,
    i.cultural_authority,
    i.portfolio_score,
    o.id AS org_id,
    coalesce(e.canonical_name, o.name)::text AS org_name,
    e.state AS org_state,
    e.postcode AS org_postcode,
    pg.locality AS org_locality,
    coalesce(e.lga_name, pg.lga_name)::text AS org_lga,
    coalesce(e.remoteness, pg.remoteness_2021)::text AS org_remoteness,
    coalesce(e.is_community_controlled, false) AS org_community_controlled,
    a.charity_size AS org_charity_size
  FROM alma_interventions i
  LEFT JOIN organizations o ON o.id = i.operating_organization_id
  LEFT JOIN gs_entities e ON e.id = o.gs_entity_id
  LEFT JOIN acnc_charities a ON a.abn = e.abn
  LEFT JOIN LATERAL (
    SELECT * FROM postcode_geo pg2
    WHERE pg2.postcode = e.postcode AND pg2.latitude IS NOT NULL LIMIT 1
  ) pg ON true
  WHERE i.verification_status != 'ai_generated';
$$;


ALTER FUNCTION "public"."get_yj_programs_for_browser"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."goods_compute_warmth"("p_stage" "text", "p_last_touch" timestamp with time zone, "p_total_received" numeric, "p_alignment" numeric, "p_has_prior" boolean, "p_advocacy" numeric DEFAULT 0) RETURNS integer
    LANGUAGE "plpgsql" STABLE
    AS $_$
DECLARE
  v_stage   numeric := 0;
  v_recency numeric := 0;
  v_history numeric := 0;
  v_align   numeric := 0;
  v_adv     numeric := 0;
  v_days    numeric;
BEGIN
  -- Stage (40%) — position on the normalized ladder
  v_stage := CASE p_stage
    WHEN 'identified'      THEN 10
    WHEN 'researching'     THEN 25
    WHEN 'contacted'       THEN 40
    WHEN 'in_conversation' THEN 60
    WHEN 'proposal'        THEN 75
    WHEN 'committed'       THEN 90
    WHEN 'repeat'          THEN 100
    WHEN 'dormant'         THEN 20
    ELSE 0
  END;

  -- Recency (20%) — exponential decay, ~42-day half-life
  IF p_last_touch IS NULL THEN
    v_recency := 0;
  ELSE
    v_days := EXTRACT(EPOCH FROM (now() - p_last_touch)) / 86400.0;
    v_recency := GREATEST(0, 100 * exp(-GREATEST(v_days, 0) / 60.0));
  END IF;

  -- History (20%) — prior giving/partnering floor + log-scaled $ received
  IF p_has_prior THEN
    v_history := LEAST(100, 50 + 12 * ln(GREATEST(1, COALESCE(p_total_received, 0)) / 1000.0 + 1));
  ELSE
    v_history := 0;
  END IF;

  -- Alignment (15%) and Advocacy (5%) — clamp to 0..100
  v_align := LEAST(100, GREATEST(0, COALESCE(p_alignment, 0)));
  v_adv   := LEAST(100, GREATEST(0, COALESCE(p_advocacy, 0)));

  RETURN ROUND(v_stage * 0.40 + v_recency * 0.20 + v_history * 0.20 + v_align * 0.15 + v_adv * 0.05)::int;
END;
$_$;


ALTER FUNCTION "public"."goods_compute_warmth"("p_stage" "text", "p_last_touch" timestamp with time zone, "p_total_received" numeric, "p_alignment" numeric, "p_has_prior" boolean, "p_advocacy" numeric) OWNER TO "postgres";


