CREATE OR REPLACE FUNCTION "public"."grant_recipient_browse"("p_q" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text", "p_topic" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'total'::"text", "p_limit" integer DEFAULT 200, "p_offset" integer DEFAULT 0) RETURNS TABLE("recipient_key" "text", "recipient_name" "text", "recipient_abn" "text", "grant_count" bigint, "total_dollars" numeric, "states" "text"[], "first_year" "text", "last_year" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    lower(btrim(j.recipient_name)) AS recipient_key,
    max(j.recipient_name) AS recipient_name,
    max(j.recipient_abn) AS recipient_abn,
    count(*) AS grant_count,
    sum(j.amount_dollars) AS total_dollars,
    array_agg(DISTINCT j.state) FILTER (WHERE j.state IS NOT NULL) AS states,
    min(j.financial_year) AS first_year,
    max(j.financial_year) AS last_year
  FROM justice_funding j
  WHERE j.measure_kind = 'grant'
    AND j.is_aggregate IS NOT TRUE
    AND j.recipient_name IS NOT NULL
    AND btrim(j.recipient_name) <> ''
    AND lower(btrim(j.recipient_name)) NOT IN
        ('total','totals','grand total','subtotal','sub-total','various','n/a','na','unknown','tbc','other','(blank)')
    AND (p_q IS NULL OR j.recipient_name ILIKE '%' || p_q || '%')
    AND (p_state IS NULL OR j.state = p_state)
    AND (p_topic IS NULL OR j.topics @> ARRAY[p_topic])
  GROUP BY lower(btrim(j.recipient_name))
  ORDER BY
    CASE WHEN p_sort = 'grants' THEN count(*) END DESC NULLS LAST,
    CASE WHEN p_sort = 'recent' THEN max(j.financial_year) END DESC NULLS LAST,
    CASE WHEN p_sort = 'name' THEN max(j.recipient_name) END ASC NULLS LAST,
    sum(j.amount_dollars) DESC NULLS LAST,
    max(j.recipient_name) ASC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 200), 1), 500)
  OFFSET GREATEST(COALESCE(p_offset, 0), 0)
$$;


ALTER FUNCTION "public"."grant_recipient_browse"("p_q" "text", "p_state" "text", "p_topic" "text", "p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_recipient_detail"("p_key" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH rows AS (
    SELECT j.program_name, j.financial_year, j.amount_dollars, j.state, j.topics, j.recipient_abn, j.recipient_name
    FROM justice_funding j
    WHERE j.measure_kind = 'grant'
      AND j.is_aggregate IS NOT TRUE
      AND lower(btrim(j.recipient_name)) = p_key
  )
  SELECT jsonb_build_object(
    'recipient_name', (SELECT max(recipient_name) FROM rows),
    'recipient_abn', (SELECT max(recipient_abn) FROM rows),
    'grant_count', (SELECT count(*) FROM rows),
    'total_dollars', (SELECT sum(amount_dollars) FROM rows),
    'by_year', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object('year', y.financial_year, 'dollars', y.dollars, 'grants', y.n) ORDER BY y.financial_year), '[]'::jsonb)
      FROM (SELECT financial_year, sum(amount_dollars) AS dollars, count(*) AS n FROM rows GROUP BY financial_year) y
    ),
    'grants', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'program', g.program_name, 'year', g.financial_year, 'amount', g.amount_dollars,
        'state', g.state, 'topics', to_jsonb(g.topics)
      ) ORDER BY g.amount_dollars DESC NULLS LAST), '[]'::jsonb)
      FROM (SELECT * FROM rows ORDER BY amount_dollars DESC NULLS LAST LIMIT 100) g
    )
  )
$$;


ALTER FUNCTION "public"."grant_recipient_detail"("p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gs_make_id"("p_abn" "text" DEFAULT NULL::"text", "p_acn" "text" DEFAULT NULL::"text", "p_icn" "text" DEFAULT NULL::"text", "p_asx_code" "text" DEFAULT NULL::"text", "p_buyer_id" "text" DEFAULT NULL::"text", "p_fallback_name" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  IF p_abn IS NOT NULL AND p_abn != '' THEN
    RETURN 'AU-ABN-' || REPLACE(p_abn, ' ', '');
  ELSIF p_acn IS NOT NULL AND p_acn != '' THEN
    RETURN 'AU-ACN-' || REPLACE(p_acn, ' ', '');
  ELSIF p_icn IS NOT NULL AND p_icn != '' THEN
    RETURN 'AU-ORIC-' || p_icn;
  ELSIF p_asx_code IS NOT NULL AND p_asx_code != '' THEN
    RETURN 'AU-ASX-' || UPPER(p_asx_code);
  ELSIF p_buyer_id IS NOT NULL AND p_buyer_id != '' THEN
    RETURN 'AU-GOV-' || p_buyer_id;
  ELSIF p_fallback_name IS NOT NULL AND p_fallback_name != '' THEN
    RETURN 'AU-NAME-' || MD5(UPPER(TRIM(p_fallback_name)));
  ELSE
    RETURN 'AU-UNK-' || gen_random_uuid()::text;
  END IF;
END;
$$;


