CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  new_full_name text;
  new_avatar_url text;
  new_username text;
BEGIN
  new_full_name := new.raw_user_meta_data->>'full_name';
  new_avatar_url := new.raw_user_meta_data->>'avatar_url';

  IF new_full_name IS NULL OR new_full_name = '' THEN
    new_full_name := 'Anonymous Member';
  END IF;

  -- Generate username from email (part before @)
  new_username := split_part(new.email, '@', 1) || '_' || substr(new.id::text, 1, 8);

  -- Insert into public.users (all NOT NULL columns accounted for)
  INSERT INTO public.users (
    id, email, username, name, user_role, password_hash, is_active
  ) VALUES (
    new.id, new.email, new_username, new_full_name,
    COALESCE(new.raw_user_meta_data->>'role', 'user'),
    'auth_managed',
    true
  )
  ON CONFLICT (id) DO UPDATE SET
    email = EXCLUDED.email,
    name = COALESCE(EXCLUDED.name, public.users.name),
    updated_at = NOW();

  -- Insert into public_profiles
  INSERT INTO public.public_profiles (
    user_id, full_name, photo_url, email, is_public
  ) VALUES (
    new.id, new_full_name, new_avatar_url, new.email, true
  )
  ON CONFLICT DO NOTHING;

  RETURN new;
EXCEPTION WHEN OTHERS THEN
  -- Log but don't block user creation
  RAISE WARNING 'handle_new_user error: %', SQLERRM;
  RETURN new;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hybrid_memory_search"("query_embedding" "extensions"."vector", "p_project_code" "text" DEFAULT NULL::"text", "p_entity_id" "uuid" DEFAULT NULL::"uuid", "p_include_episodes" boolean DEFAULT true, "p_freshness_weight" double precision DEFAULT 0.2, "p_graph_weight" double precision DEFAULT 0.2, "p_vector_weight" double precision DEFAULT 0.6, "match_threshold" double precision DEFAULT 0.4, "match_count" integer DEFAULT 20) RETURNS TABLE("source_table" "text", "source_id" "uuid", "title" "text", "content" "text", "vector_score" double precision, "decay_score" double precision, "graph_score" double precision, "combined_score" double precision, "metadata" "jsonb")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  WITH vector_results AS (
    SELECT 'project_knowledge'::TEXT as src, pk.id, pk.title, pk.content,
           (1 - (pk.embedding <=> query_embedding))::FLOAT as vscore,
           COALESCE(pk.decay_score, 1.0)::FLOAT as dscore,
           pk.importance, pk.knowledge_type
    FROM project_knowledge pk
    WHERE pk.embedding IS NOT NULL
      AND pk.superseded_by IS NULL
      AND 1 - (pk.embedding <=> query_embedding) > match_threshold * 0.8
      AND (p_project_code IS NULL OR pk.project_code = p_project_code)

    UNION ALL

    SELECT 'knowledge_chunks'::TEXT, kc.id, NULL, kc.content,
           (1 - (kc.embedding <=> query_embedding))::FLOAT,
           COALESCE(kc.decay_score, 1.0)::FLOAT,
           'normal', kc.source_type
    FROM knowledge_chunks kc
    WHERE kc.embedding IS NOT NULL
      AND kc.consolidated_into IS NULL
      AND 1 - (kc.embedding <=> query_embedding) > match_threshold * 0.8
  ),
  graph_scores AS (
    SELECT vr.id,
           COALESCE(
             (SELECT AVG(ke.strength) FROM knowledge_edges ke
              WHERE (ke.source_id = vr.id OR ke.target_id = vr.id)
                AND ke.decay_score > 0.05
                AND (p_entity_id IS NULL OR ke.source_id = p_entity_id OR ke.target_id = p_entity_id)
             ), 0.0
           )::FLOAT as gscore
    FROM vector_results vr
  )
  SELECT vr.src, vr.id, vr.title, vr.content,
         vr.vscore, vr.dscore,
         COALESCE(gs.gscore, 0.0),
         (vr.vscore * p_vector_weight + vr.dscore * p_freshness_weight + COALESCE(gs.gscore, 0.0) * p_graph_weight)::FLOAT,
         jsonb_build_object('importance', vr.importance, 'knowledge_type', vr.knowledge_type)
  FROM vector_results vr
  LEFT JOIN graph_scores gs ON gs.id = vr.id
  WHERE (vr.vscore * p_vector_weight + vr.dscore * p_freshness_weight + COALESCE(gs.gscore, 0.0) * p_graph_weight) > match_threshold
  ORDER BY (vr.vscore * p_vector_weight + vr.dscore * p_freshness_weight + COALESCE(gs.gscore, 0.0) * p_graph_weight) DESC
  LIMIT match_count;
END;
$$;


ALTER FUNCTION "public"."hybrid_memory_search"("query_embedding" "extensions"."vector", "p_project_code" "text", "p_entity_id" "uuid", "p_include_episodes" boolean, "p_freshness_weight" double precision, "p_graph_weight" double precision, "p_vector_weight" double precision, "match_threshold" double precision, "match_count" integer) OWNER TO "postgres";


