CREATE OR REPLACE FUNCTION "public"."insert_receipt_emails"("rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  row_data jsonb;
  inserted integer := 0;
BEGIN
  FOR row_data IN SELECT * FROM jsonb_array_elements(rows)
  LOOP
    INSERT INTO receipt_emails (
      gmail_message_id, mailbox, from_email, subject, received_at,
      vendor_name, amount_detected, currency,
      attachment_url, attachment_filename, attachment_content_type,
      status, source, dext_item_id, match_method
    ) VALUES (
      row_data->>'gmail_message_id',
      row_data->>'mailbox',
      row_data->>'from_email',
      row_data->>'subject',
      (row_data->>'received_at')::timestamptz,
      row_data->>'vendor_name',
      (row_data->>'amount_detected')::numeric,
      COALESCE(row_data->>'currency', 'AUD'),
      row_data->>'attachment_url',
      row_data->>'attachment_filename',
      row_data->>'attachment_content_type',
      COALESCE(row_data->>'status', 'captured'),
      COALESCE(row_data->>'source', 'dext_import'),
      row_data->>'dext_item_id',
      row_data->>'match_method'
    )
    ON CONFLICT (gmail_message_id) DO NOTHING;
    
    IF FOUND THEN inserted := inserted + 1; END IF;
  END LOOP;
  
  RETURN inserted;
END;
$$;


