CREATE OR REPLACE FUNCTION "public"."is_org_member"("org" "uuid", "min_role" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public.organization_members member
    where member.organization_id = org
      and member.user_id = auth.uid()
      and member.status = 'active'
      and case min_role
        when 'owner' then member.role in ('owner', 'admin')
        when 'editor' then member.role in ('owner', 'admin', 'editor')
        when 'viewer' then true
        else false
      end
  );
$$;


