CREATE OR REPLACE FUNCTION "public"."jm_rate_check"("p_key" "text", "p_limit" integer, "p_window_seconds" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_bucket bigint;
  v_count integer;
begin
  if p_key is null or p_key = '' or p_limit is null or p_window_seconds is null or p_window_seconds <= 0 then
    return jsonb_build_object('allowed', true, 'count', 0, 'limit', p_limit);
  end if;

  v_bucket := floor(extract(epoch from now()) / p_window_seconds)::bigint;

  delete from public.jm_rate_limits where key = p_key and window_bucket < v_bucket;

  insert into public.jm_rate_limits (key, window_bucket, count, expires_at)
    values (p_key, v_bucket, 1, to_timestamp((v_bucket + 1) * p_window_seconds))
  on conflict (key, window_bucket) do update set count = public.jm_rate_limits.count + 1
  returning count into v_count;

  return jsonb_build_object('allowed', v_count <= p_limit, 'count', v_count, 'limit', p_limit);
end;
$$;


ALTER FUNCTION "public"."jm_rate_check"("p_key" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."jm_stage_discovery"("p_row" "jsonb", "p_cap" integer) RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_eid text := p_row->>'external_id';
  v_src text := p_row->>'external_source';
  v_recent integer;
  v_inserted boolean;
begin
  if v_eid is null or v_eid = '' then
    return 'invalid';
  end if;

  if exists (select 1 from public.jm_external_ids where value = v_eid) then
    return 'already_owned';
  end if;

  if p_cap is not null and not exists (
       select 1 from public.justice_matrix_discovered
        where external_id = v_eid and external_source = v_src
     ) then
    select count(*) into v_recent
      from public.justice_matrix_discovered
     where source_id is null and status = 'pending'
       and created_at > now() - interval '1 hour';
    if v_recent >= p_cap then
      return 'rate_limited';
    end if;
  end if;

  insert into public.justice_matrix_discovered
    (source_id, source_url, item_type, raw_data, extracted_title, extracted_year,
     external_id, external_source, status, demand_count, discovered_at)
  values
    (null, p_row->>'source_url', p_row->>'item_type', p_row->'raw_data',
     p_row->>'extracted_title', nullif(p_row->>'extracted_year', '')::integer,
     v_eid, v_src, 'pending', 1, coalesce((p_row->>'discovered_at')::timestamptz, now()))
  on conflict (external_id, external_source) where external_id is not null
    do update set demand_count = public.justice_matrix_discovered.demand_count + 1
  returning (xmax = 0) into v_inserted;

  return case when v_inserted then 'staged' else 'demand_bumped' end;
end;
$$;


ALTER FUNCTION "public"."jm_stage_discovery"("p_row" "jsonb", "p_cap" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."jr_approve_outcome"("p_outcome_id" "uuid", "p_actor_id" "uuid", "p_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  outcome public.jr_outcomes%rowtype;
  lead_org_id uuid;
  outcome_visibility text;
begin
  select * into outcome
  from public.jr_outcomes
  where id = p_outcome_id
  for update;
  if not found then raise exception 'Outcome not found'; end if;

  select site.lead_organization_id into lead_org_id
  from public.jr_sites site where site.id = outcome.jr_site_id;
  if lead_org_id is null or not exists (
    select 1 from public.organization_members member
    where member.organization_id = lead_org_id
      and member.user_id = p_actor_id
      and member.status = 'active'
      and member.role in ('owner', 'admin')
  ) then
    raise exception 'Only the community owner can approve this outcome';
  end if;

  outcome_visibility := case
    when 'public_profile' = any(outcome.allowed_purposes) then 'public'
    else 'community'
  end;

  update public.jr_outcomes
  set workflow_state = 'approved',
      visibility = outcome_visibility,
      approved_by = p_actor_id,
      approved_at = now(),
      updated_by = p_actor_id
  where id = outcome.id;

  insert into public.jr_review_decisions (
    jr_outcome_id, decision, authority_scope, actor_id, actor_role,
    note, audience, allowed_purposes
  ) values (
    outcome.id, 'approved', 'community_approval', p_actor_id, 'owner',
    p_note,
    case when outcome_visibility = 'public' then 'community' else outcome_visibility end,
    outcome.allowed_purposes
  );

  return outcome.id;
end;
$$;


