ALTER FUNCTION "public"."jr_keep_review_decisions_immutable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."jr_money_by_measure"() RETURNS TABLE("measure_kind" "text", "dollars" numeric, "youth_dollars" numeric, "records" bigint, "sources" bigint, "excluded_aggregates" bigint)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  WITH eligible AS (
    SELECT f.measure_kind, f.amount_dollars, f.sector, f.source, f.is_aggregate
    FROM justice_funding f
    WHERE f.measure_kind IN ('grant', 'contract_value', 'budget_announcement')
      AND f.amount_dollars IS NOT NULL
  )
  SELECT
    e.measure_kind::text,
    sum(e.amount_dollars) FILTER (WHERE NOT COALESCE(e.is_aggregate, false))            AS dollars,
    COALESCE(sum(e.amount_dollars) FILTER (
      WHERE NOT COALESCE(e.is_aggregate, false) AND e.sector ILIKE '%youth%'), 0)       AS youth_dollars,
    count(*) FILTER (WHERE NOT COALESCE(e.is_aggregate, false))                         AS records,
    count(DISTINCT e.source) FILTER (WHERE NOT COALESCE(e.is_aggregate, false))         AS sources,
    count(*) FILTER (WHERE COALESCE(e.is_aggregate, false))                             AS excluded_aggregates
  FROM eligible e
  GROUP BY e.measure_kind
  HAVING sum(e.amount_dollars) FILTER (WHERE NOT COALESCE(e.is_aggregate, false)) IS NOT NULL
  ORDER BY 2 DESC;
$$;


ALTER FUNCTION "public"."jr_money_by_measure"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."jr_money_by_measure"() IS 'Per-measure-kind funding totals for the State of JR report. Aggregated in SQL because an unbounded PostgREST select silently caps at 1,000 rows out of ~156,000. Returns NO total by design: promised, committed and paid are three different claims and one dollar can appear in all three.';



CREATE OR REPLACE FUNCTION "public"."jr_promote_evidence_draft"("p_draft_id" "uuid", "p_actor_id" "uuid", "p_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  draft public.jr_evidence_drafts%rowtype;
  outcome public.jr_outcomes%rowtype;
  latest_source_decision text;
  metric_id uuid;
  evaluation_id uuid;
  evidence_link_id uuid;
  lead_org_id uuid;
  evidence_visibility text;
begin
  select * into draft
  from public.jr_evidence_drafts
  where id = p_draft_id
  for update;

  if not found then
    raise exception 'Evidence draft not found';
  end if;
  if draft.status <> 'submitted_for_review' or draft.promoted_at is not null then
    raise exception 'Only an unpromoted submitted draft can be approved';
  end if;

  select site.lead_organization_id into lead_org_id
  from public.jr_sites site where site.id = draft.jr_site_id;
  if lead_org_id is null or not exists (
    select 1 from public.organization_members member
    where member.organization_id = lead_org_id
      and member.user_id = p_actor_id
      and member.status = 'active'
      and member.role in ('owner', 'admin')
  ) then
    raise exception 'Only the community owner can approve this evidence';
  end if;

  select decision.decision into latest_source_decision
  from public.jr_review_decisions decision
  where decision.jr_evidence_draft_id = draft.id
    and decision.authority_scope = 'source_validation'
  order by decision.decided_at desc, decision.created_at desc
  limit 1;

  if latest_source_decision is distinct from 'source_validated' then
    raise exception 'Source validation is required before community approval';
  end if;

  select * into outcome
  from public.jr_outcomes
  where id = draft.selected_outcome_id
    and jr_site_id = draft.jr_site_id
  for update;

  if not found or outcome.workflow_state <> 'approved' then
    raise exception 'Approve the linked local outcome before approving its evidence';
  end if;

  evidence_visibility := case
    when 'public_profile' = any(draft.allowed_purposes) then 'public'
    else 'community'
  end;

  if draft.evidence_type = 'observation' then
    insert into public.jr_site_metrics (
      jr_site_id, metric, value, as_reported, source_url, year, metric_class,
      confirmed, confirmed_by_org, reviewed_at, reviewed_by, review_note,
      updated_at
    ) values (
      draft.jr_site_id,
      draft.what_changed,
      coalesce(nullif(btrim(draft.value_text), ''), 'Observed change'),
      coalesce(nullif(btrim(draft.context_note), ''), draft.what_changed),
      draft.source_url,
      draft.year,
      'outcome',
      true,
      true,
      now(),
      p_actor_id,
      p_note,
      now()
    )
    on conflict on constraint jr_site_metrics_natural_key do nothing
    returning id into metric_id;

    if metric_id is null then
      select metric.id into metric_id
      from public.jr_site_metrics metric
      where metric.jr_site_id = draft.jr_site_id
        and metric.metric = draft.what_changed
        and metric.source_url = draft.source_url
        and metric.year is not distinct from draft.year;
    end if;
  elsif draft.evidence_type = 'report' then
    insert into public.jr_evaluations (
      program_name, site_location, publication_year, outcomes_json,
      source_url, verification_status, extractor
    ) values (
      draft.source_title,
      draft.where_scope,
      draft.year,
      jsonb_strip_nulls(jsonb_build_object(
        'community_summary', draft.what_changed,
        'local_context', draft.context_note,
        'period', draft.period_label,
        'source_page', draft.source_page
      )),
      draft.source_url,
      'human_reviewed',
      jsonb_build_object('source', 'jr-community-review')
    )
    on conflict (source_url) do nothing
    returning id into evaluation_id;

    if evaluation_id is null then
      select evaluation.id into evaluation_id
      from public.jr_evaluations evaluation
      where evaluation.source_url = draft.source_url;
    end if;
  end if;

  select evidence.id into evidence_link_id
  from public.jr_outcome_evidence_links evidence
  where evidence.jr_outcome_id = outcome.id
    and (
      (metric_id is not null and evidence.jr_site_metric_id = metric_id)
      or (evaluation_id is not null and evidence.jr_evaluation_id = evaluation_id)
      or (draft.story_related_site_id is not null
        and evidence.story_related_site_id = draft.story_related_site_id)
    )
  limit 1
  for update;

  if evidence_link_id is null then
    insert into public.jr_outcome_evidence_links (
      jr_outcome_id, jr_site_metric_id, story_related_site_id,
      jr_evaluation_id, relevance_note, local_interpretation,
      contribution_claim, source_title, source_url, source_page,
      workflow_state, visibility, allowed_purposes, is_active,
      approved_by, approved_at, created_by, updated_by
    ) values (
      outcome.id,
      metric_id,
      draft.story_related_site_id,
      evaluation_id,
      draft.what_changed,
      draft.context_note,
      'Community-reviewed contribution to the local outcome; no sole attribution is asserted.',
      case when draft.evidence_type = 'community_yarn' then null else draft.source_title end,
      case when draft.evidence_type = 'community_yarn' then null else draft.source_url end,
      case when draft.evidence_type = 'community_yarn' then null else draft.source_page end,
      'approved',
      evidence_visibility,
      draft.allowed_purposes,
      true,
      p_actor_id,
      now(),
      draft.created_by,
      p_actor_id
    )
    returning id into evidence_link_id;
  else
    update public.jr_outcome_evidence_links
    set relevance_note = draft.what_changed,
        local_interpretation = draft.context_note,
        source_title = case when draft.evidence_type = 'community_yarn' then null else draft.source_title end,
        source_url = case when draft.evidence_type = 'community_yarn' then null else draft.source_url end,
        source_page = case when draft.evidence_type = 'community_yarn' then null else draft.source_page end,
        workflow_state = 'approved',
        visibility = evidence_visibility,
        allowed_purposes = draft.allowed_purposes,
        is_active = true,
        approved_by = p_actor_id,
        approved_at = now(),
        updated_by = p_actor_id
    where id = evidence_link_id;
  end if;

  insert into public.jr_review_decisions (
    jr_evidence_draft_id, decision, authority_scope, actor_id, actor_role,
    note, audience, allowed_purposes
  ) values (
    draft.id, 'approved', 'community_approval', p_actor_id, 'owner',
    p_note,
    case when evidence_visibility = 'public' then 'community' else evidence_visibility end,
    draft.allowed_purposes
  );

  update public.jr_evidence_drafts
  set status = 'archived',
      submitted_at = null,
      promoted_metric_id = metric_id,
      promoted_evaluation_id = evaluation_id,
      promoted_evidence_link_id = evidence_link_id,
      promoted_by = p_actor_id,
      promoted_at = now(),
      updated_by = p_actor_id
  where id = draft.id;

  return evidence_link_id;
end;
$$;


ALTER FUNCTION "public"."jr_promote_evidence_draft"("p_draft_id" "uuid", "p_actor_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."jr_protect_published_snapshot"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' and old.status <> 'staged' then
    raise exception 'Published JR snapshots must be withdrawn, not deleted';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  if old.status = 'withdrawn' then
    raise exception 'Withdrawn JR snapshots are immutable';
  end if;

  if old.status = 'staged' and new.status = 'withdrawn' then
    raise exception 'A JR snapshot must be published before it can be withdrawn';
  end if;

  if old.status = 'published' and (
    new.jr_site_id is distinct from old.jr_site_id
    or new.version is distinct from old.version
    or new.snapshot_schema_version is distinct from old.snapshot_schema_version
    or new.public_payload is distinct from old.public_payload
    or new.source_outcome_ids is distinct from old.source_outcome_ids
    or new.publication_note is distinct from old.publication_note
    or new.created_by is distinct from old.created_by
    or new.created_at is distinct from old.created_at
    or new.published_by is distinct from old.published_by
    or new.published_at is distinct from old.published_at
    or new.status not in ('published', 'withdrawn')
  ) then
    raise exception 'Published JR snapshot content is immutable; create a new version';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."jr_protect_published_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."jr_publish_approved_snapshot"("p_site_id" "uuid", "p_actor_id" "uuid", "p_note" "text") RETURNS TABLE("snapshot_id" "uuid", "snapshot_version" integer, "published_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  lead_org_id uuid;
  next_version integer;
  outcome_ids uuid[];
  payload jsonb;
  new_snapshot_id uuid;
  outcome_count integer;
begin
  select site.lead_organization_id into lead_org_id
  from public.jr_sites site
  where site.id = p_site_id
  for update;

  if not found then raise exception 'JR site not found'; end if;
  if lead_org_id is null or not exists (
    select 1 from public.organization_members member
    where member.organization_id = lead_org_id
      and member.user_id = p_actor_id
      and member.status = 'active'
      and member.role in ('owner', 'admin')
  ) then
    raise exception 'Only the community owner can publish this JR profile';
  end if;

  select coalesce(array_agg(outcome.id order by outcome.created_at), '{}')
  into outcome_ids
  from public.jr_outcomes outcome
  where outcome.jr_site_id = p_site_id
    and outcome.workflow_state = 'approved'
    and outcome.visibility = 'public'
    and outcome.withdrawn_at is null
    and 'public_profile' = any(outcome.allowed_purposes);

  outcome_count := cardinality(outcome_ids);
  if outcome_count = 0 then
    raise exception 'Approve at least one public-profile outcome before publishing';
  end if;

  select jsonb_build_object(
    'schemaVersion', 2,
    'siteId', p_site_id,
    'publishedAt', now(),
    'outcomes', coalesce(jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object(
        'id', outcome.id,
        'localTitle', outcome.local_title,
        'localDomain', outcome.local_domain,
        'communityInterpretation', outcome.community_interpretation,
        'authorityNote', outcome.authority_note,
        'sharedDomain', outcome.shared_domain,
        'allowedPurposes', outcome.allowed_purposes,
        'latestPeriodLabel', outcome.latest_period_label,
        'nextReviewAt', outcome.next_review_at,
        'evidence', (
          select coalesce(jsonb_agg(
            jsonb_strip_nulls(jsonb_build_object(
              'id', evidence.id,
              'type', case
                when evidence.jr_site_metric_id is not null then 'observation'
                when evidence.story_related_site_id is not null then 'community_yarn'
                else 'report'
              end,
              'metricId', evidence.jr_site_metric_id,
              'storyRelationshipId', evidence.story_related_site_id,
              'evaluationId', evidence.jr_evaluation_id,
              'relevanceNote', evidence.relevance_note,
              'localInterpretation', evidence.local_interpretation,
              'contributionClaim', evidence.contribution_claim,
              'sourceTitle', evidence.source_title,
              'sourceUrl', evidence.source_url,
              'sourcePage', evidence.source_page,
              'allowedPurposes', evidence.allowed_purposes
            )) order by evidence.display_order, evidence.created_at
          ), '[]'::jsonb)
          from public.jr_outcome_evidence_links evidence
          where evidence.jr_outcome_id = outcome.id
            and evidence.workflow_state = 'approved'
            and evidence.visibility = 'public'
            and evidence.is_active = true
            and evidence.withdrawn_at is null
            and 'public_profile' = any(evidence.allowed_purposes)
        )
      )) order by outcome.created_at
    ), '[]'::jsonb)
  ) into payload
  from public.jr_outcomes outcome
  where outcome.id = any(outcome_ids);

  update public.jr_publication_snapshots
  set status = 'withdrawn',
      withdrawn_by = p_actor_id,
      withdrawn_at = now(),
      withdrawal_note = 'Superseded by a newer community-published edition'
  where jr_site_id = p_site_id
    and status = 'published'
    and withdrawn_at is null;

  select coalesce(max(snapshot.version), 0) + 1 into next_version
  from public.jr_publication_snapshots snapshot
  where snapshot.jr_site_id = p_site_id;

  insert into public.jr_publication_snapshots (
    jr_site_id, version, snapshot_schema_version, status, public_payload,
    source_outcome_ids, publication_note, created_by, published_by, published_at
  ) values (
    p_site_id, next_version, 2, 'published', payload,
    outcome_ids, p_note, p_actor_id, p_actor_id, now()
  ) returning id into new_snapshot_id;

  insert into public.jr_review_decisions (
    jr_outcome_id, decision, authority_scope, actor_id, actor_role,
    note, audience, allowed_purposes
  )
  select outcome.id, 'publication_authorized', 'publication', p_actor_id,
    'owner', p_note, 'public', outcome.allowed_purposes
  from public.jr_outcomes outcome
  where outcome.id = any(outcome_ids);

  update public.jr_sites
  set published_at = coalesce(published_at, now()),
      updated_at = now()
  where id = p_site_id;

  return query select new_snapshot_id, next_version, outcome_count;
end;
$$;


ALTER FUNCTION "public"."jr_publish_approved_snapshot"("p_site_id" "uuid", "p_actor_id" "uuid", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."jr_publish_approved_snapshot"("p_site_id" "uuid", "p_actor_id" "uuid", "p_note" "text") IS 'Owner-only immutable JR publication. Schema v2 records outcome usage scopes so shared-learning aggregation fails closed.';



CREATE OR REPLACE FUNCTION "public"."jr_revoke_authority_on_lead_org_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.lead_organization_id is distinct from old.lead_organization_id then
    update public.jr_site_authorities authority
    set status = 'revoked',
        publication_enabled = false,
        revoked_at = now(),
        revoked_by = auth.uid(),
        revocation_note = 'Lead organisation changed; site authority requires fresh verification',
        updated_at = now()
    where authority.jr_site_id = new.id
      and authority.status <> 'revoked';
  end if;
  return new;
end;
$$;


