CREATE OR REPLACE FUNCTION "public"."jr_site_authority_is_verified"("p_site_id" "uuid", "p_organization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select exists (
    select 1
    from public.jr_site_authorities authority
    where authority.jr_site_id = p_site_id
      and authority.organization_id = p_organization_id
