CREATE OR REPLACE FUNCTION "public"."jr_validate_evidence_draft_site"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.selected_outcome_id is not null and not exists (
    select 1 from public.jr_outcomes outcome
    where outcome.id = new.selected_outcome_id
      and outcome.jr_site_id = new.jr_site_id
  ) then
    raise exception 'Draft outcome must belong to the same JR site';
  end if;

  if new.story_related_site_id is not null and not exists (
    select 1 from public.story_related_sites story_link
    where story_link.id = new.story_related_site_id
      and story_link.jr_site_id = new.jr_site_id
      and story_link.is_active = true
  ) then
    raise exception 'Draft story relationship must be active on the same JR site';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."jr_validate_evidence_draft_site"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."jr_validate_outcome_evidence_site"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  outcome_site_id uuid;
begin
  select jr_site_id into outcome_site_id
  from public.jr_outcomes
  where id = new.jr_outcome_id;

  if new.jr_site_metric_id is not null and not exists (
    select 1 from public.jr_site_metrics
    where id = new.jr_site_metric_id and jr_site_id = outcome_site_id
  ) then
    raise exception 'Outcome metric evidence must belong to the same JR site';
  end if;

  if new.story_related_site_id is not null and not exists (
    select 1 from public.story_related_sites
    where id = new.story_related_site_id and jr_site_id = outcome_site_id
  ) then
    raise exception 'Outcome story evidence must belong to the same JR site';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."jr_validate_outcome_evidence_site"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."jr_validate_review_authority"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target_site_id uuid;
  lead_org_id uuid;
begin
  if new.authority_scope not in ('community_approval', 'publication', 'withdrawal') then
    return new;
  end if;

  if new.jr_outcome_id is not null then
    select outcome.jr_site_id into target_site_id
    from public.jr_outcomes outcome
    where outcome.id = new.jr_outcome_id;
  elsif new.jr_outcome_evidence_link_id is not null then
    select outcome.jr_site_id into target_site_id
    from public.jr_outcome_evidence_links evidence
    join public.jr_outcomes outcome on outcome.id = evidence.jr_outcome_id
    where evidence.id = new.jr_outcome_evidence_link_id;
  else
    select draft.jr_site_id into target_site_id
    from public.jr_evidence_drafts draft
    where draft.id = new.jr_evidence_draft_id;
  end if;

  select site.lead_organization_id into lead_org_id
  from public.jr_sites site
  where site.id = target_site_id;

  if new.actor_role <> 'owner'
    or lead_org_id is null
    or not public.jr_site_authority_is_verified(target_site_id, lead_org_id)
    or not exists (
      select 1
      from public.organization_members member
      where member.organization_id = lead_org_id
        and member.user_id = new.actor_id
        and member.status = 'active'
        and member.role in ('owner', 'admin')
    )
  then
    raise exception 'Verified site-specific community authority is required for this JR decision';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."jr_validate_review_authority"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."jr_validate_site_authority"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  lead_org_id uuid;
begin
  select site.lead_organization_id into lead_org_id
  from public.jr_sites site
  where site.id = new.jr_site_id;

  if lead_org_id is null or lead_org_id <> new.organization_id then
    raise exception 'JR authority organisation must match the site lead organisation';
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."jr_validate_site_authority"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."jr_validate_snapshot_authority"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  lead_org_id uuid;
  authority_actor_id uuid;
begin
  if tg_op = 'INSERT' then
    if new.status = 'withdrawn' then
      raise exception 'A JR snapshot must be published before it can be withdrawn';
    elsif new.status = 'published' then
      authority_actor_id := new.published_by;
    else
      return new;
    end if;
  elsif new.status = 'published' and old.status <> 'published' then
    authority_actor_id := new.published_by;
  elsif new.status = 'withdrawn' and old.status <> 'withdrawn' then
    authority_actor_id := new.withdrawn_by;
  else
    return new;
  end if;

  select site.lead_organization_id into lead_org_id
  from public.jr_sites site
  where site.id = new.jr_site_id;

  if lead_org_id is null
    or authority_actor_id is null
    or not public.jr_site_authority_is_verified(new.jr_site_id, lead_org_id)
    or not exists (
      select 1
      from public.organization_members member
      where member.organization_id = lead_org_id
        and member.user_id = authority_actor_id
        and member.status = 'active'
        and member.role in ('owner', 'admin')
    )
  then
    if new.status = 'withdrawn' then
      raise exception 'Verified site-specific community authority is required to withdraw this JR snapshot';
    end if;
    raise exception 'Verified site-specific community authority is required to publish this JR snapshot';
  end if;

  if new.status = 'published' and exists (
    select 1
    from unnest(new.source_outcome_ids) as source(outcome_id)
    left join public.jr_outcomes outcome on outcome.id = source.outcome_id
    where outcome.id is null
      or outcome.jr_site_id <> new.jr_site_id
      or outcome.workflow_state <> 'approved'
      or outcome.visibility <> 'public'
      or outcome.withdrawn_at is not null
      or not ('public_profile' = any(outcome.allowed_purposes))
  ) then
    raise exception 'Published JR snapshots may include only approved public outcomes from the same site';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."jr_validate_snapshot_authority"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."jr_withdraw_published_snapshot"("p_site_id" "uuid", "p_actor_id" "uuid", "p_note" "text") RETURNS TABLE("snapshot_id" "uuid", "snapshot_version" integer, "withdrawn_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  lead_org_id uuid;
  current_snapshot public.jr_publication_snapshots%rowtype;
  outcome_count integer;
begin
  if p_note is null or char_length(btrim(p_note)) < 3 or char_length(p_note) > 2000 then
    raise exception 'A short community withdrawal note is required';
  end if;

  select site.lead_organization_id into lead_org_id
  from public.jr_sites site
  where site.id = p_site_id
  for update;

  if not found then
    raise exception 'JR site not found';
  end if;
  if lead_org_id is null or not exists (
    select 1
    from public.organization_members member
    where member.organization_id = lead_org_id
      and member.user_id = p_actor_id
      and member.status = 'active'
      and member.role in ('owner', 'admin')
  ) then
    raise exception 'Only the community owner can withdraw this JR profile';
  end if;

  select snapshot.* into current_snapshot
  from public.jr_publication_snapshots snapshot
  where snapshot.jr_site_id = p_site_id
    and snapshot.status = 'published'
    and snapshot.withdrawn_at is null
  order by snapshot.version desc
  limit 1
  for update;

  if not found then
    raise exception 'There is no current community-published edition to withdraw';
  end if;

  update public.jr_publication_snapshots
  set status = 'withdrawn',
      withdrawn_by = p_actor_id,
      withdrawn_at = now(),
      withdrawal_note = btrim(p_note)
  where id = current_snapshot.id;

  insert into public.jr_review_decisions (
    jr_outcome_id, decision, authority_scope, actor_id, actor_role,
    note, audience, allowed_purposes
  )
  select outcome_id, 'withdrawn', 'withdrawal', p_actor_id, 'owner',
    btrim(p_note), 'private', array['public_profile']::text[]
  from unnest(current_snapshot.source_outcome_ids) outcome_id;

  update public.jr_sites
  set published_at = null,
      updated_at = now()
  where id = p_site_id;

  outcome_count := cardinality(current_snapshot.source_outcome_ids);
  return query
    select current_snapshot.id, current_snapshot.version, outcome_count;
end;
$$;


ALTER FUNCTION "public"."jr_withdraw_published_snapshot"("p_site_id" "uuid", "p_actor_id" "uuid", "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."jr_withdraw_published_snapshot"("p_site_id" "uuid", "p_actor_id" "uuid", "p_note" "text") IS 'Owner-only atomic withdrawal of the current JR publication snapshot. Records the authority decision and closes the public site gate without deleting history.';



