CREATE OR REPLACE FUNCTION "public"."justice_funding_map_locations"("p_state" "text" DEFAULT 'QLD'::"text", "p_q" "text" DEFAULT NULL::"text", "p_sector" "text" DEFAULT NULL::"text", "p_indigenous_only" boolean DEFAULT false, "p_location" "text" DEFAULT NULL::"text", "p_funding_type" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT NULL::"text", "p_beneficiary" "text" DEFAULT NULL::"text", "p_purpose" "text" DEFAULT NULL::"text", "p_charity_size" "text" DEFAULT NULL::"text", "p_alma_only" boolean DEFAULT false) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  result json;
BEGIN
  SELECT json_agg(row_to_json(sub)) INTO result
  FROM (
    SELECT
      lower(trim(jf.location)) as location,
      count(DISTINCT lower(trim(jf.recipient_name)))::int as org_count,
      sum(jf.amount_dollars)::numeric as total_dollars,
      count(DISTINCT CASE WHEN (
        jf.recipient_name ILIKE '%aboriginal%'
        OR jf.recipient_name ILIKE '%torres strait%'
        OR jf.recipient_name ILIKE '%indigenous%'
        OR jf.recipient_name ILIKE '%murri%'
        OR jf.recipient_name ILIKE '%first nations%'
      ) THEN lower(trim(jf.recipient_name)) END)::int as indigenous_org_count,
      count(DISTINCT CASE WHEN jf.alma_organization_id IS NOT NULL
        THEN lower(trim(jf.recipient_name)) END)::int as alma_org_count
    FROM justice_funding jf
    LEFT JOIN acnc_charities ac ON jf.recipient_abn = ac.abn
      AND (p_beneficiary IS NOT NULL OR p_purpose IS NOT NULL OR p_charity_size IS NOT NULL)
    WHERE jf.state = p_state
      AND jf.location IS NOT NULL AND jf.location != ''
      AND lower(trim(jf.location)) NOT IN ('multiple', 'not applicable', 'n/a', 'statewide', 'various', 'unknown')
      AND jf.recipient_name IS NOT NULL AND jf.recipient_name != ''
      AND lower(trim(jf.recipient_name)) NOT IN ('', 'various', 'unknown', 'n/a', 'not applicable', 'tba', 'tbc')
      AND (p_q IS NULL OR (
        jf.recipient_name ILIKE '%' || p_q || '%'
        OR jf.location ILIKE '%' || p_q || '%'
        OR jf.recipient_abn ILIKE '%' || p_q || '%'
      ))
      AND (p_sector IS NULL OR jf.sector = p_sector)
      AND (p_location IS NULL OR lower(trim(jf.location)) = lower(trim(p_location)))
      AND (NOT p_indigenous_only OR (
        jf.recipient_name ILIKE '%aboriginal%'
        OR jf.recipient_name ILIKE '%torres strait%'
        OR jf.recipient_name ILIKE '%indigenous%'
        OR jf.recipient_name ILIKE '%murri%'
        OR jf.recipient_name ILIKE '%first nations%'
      ))
      AND (p_funding_type IS NULL OR jf.funding_type = p_funding_type)
      AND (p_source IS NULL OR jf.source = p_source)
      AND (NOT p_alma_only OR jf.alma_organization_id IS NOT NULL)
      AND (p_beneficiary IS NULL OR (
        CASE p_beneficiary
          WHEN 'ben_youth' THEN ac.ben_youth
          WHEN 'ben_children' THEN ac.ben_children
          WHEN 'ben_aboriginal_tsi' THEN ac.ben_aboriginal_tsi
          WHEN 'ben_pre_post_release' THEN ac.ben_pre_post_release
          WHEN 'ben_victims_of_crime' THEN ac.ben_victims_of_crime
          WHEN 'ben_people_at_risk_of_homelessness' THEN ac.ben_people_at_risk_of_homelessness
          ELSE false
        END = true
      ))
      AND (p_purpose IS NULL OR (
        CASE p_purpose
          WHEN 'purpose_law_policy' THEN ac.purpose_law_policy
          WHEN 'purpose_reconciliation' THEN ac.purpose_reconciliation
          WHEN 'purpose_social_welfare' THEN ac.purpose_social_welfare
          WHEN 'purpose_human_rights' THEN ac.purpose_human_rights
          ELSE false
        END = true
      ))
      AND (p_charity_size IS NULL OR ac.charity_size = p_charity_size)
    GROUP BY lower(trim(jf.location))
    ORDER BY total_dollars DESC NULLS LAST
  ) sub;

  RETURN COALESCE(result, '[]'::json);
END;
$$;


ALTER FUNCTION "public"."justice_funding_map_locations"("p_state" "text", "p_q" "text", "p_sector" "text", "p_indigenous_only" boolean, "p_location" "text", "p_funding_type" "text", "p_source" "text", "p_beneficiary" "text", "p_purpose" "text", "p_charity_size" "text", "p_alma_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."justice_funding_org_profile"("p_org_id" "uuid") RETURNS json
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  SELECT json_build_object(
    'organization', (
      SELECT json_build_object(
        'id', o.id, 'name', o.name, 'slug', o.slug, 'type', o.type,
        'state', o.state, 'city', o.city, 'description', o.description
      ) FROM organizations o WHERE o.id = p_org_id
    ),
    'funding', json_build_object(
      'total_dollars', COALESCE((SELECT sum(amount_dollars) FROM justice_funding WHERE alma_organization_id = p_org_id), 0)::bigint,
      'grant_count', (SELECT count(*) FROM justice_funding WHERE alma_organization_id = p_org_id),
      'years_funded', (SELECT count(DISTINCT financial_year) FROM justice_funding WHERE alma_organization_id = p_org_id),
      'by_year', (
        SELECT json_agg(row_to_json(t) ORDER BY t.financial_year)
        FROM (
          SELECT financial_year, sum(amount_dollars)::bigint as dollars, count(*) as grants,
                 array_agg(DISTINCT program_name) FILTER (WHERE program_name IS NOT NULL) as programs
          FROM justice_funding WHERE alma_organization_id = p_org_id AND financial_year IS NOT NULL
          GROUP BY financial_year ORDER BY financial_year
        ) t
      ),
      'by_sector', (
        SELECT json_agg(row_to_json(t))
        FROM (
          SELECT sector, sum(amount_dollars)::bigint as dollars, count(*) as grants
          FROM justice_funding WHERE alma_organization_id = p_org_id AND sector IS NOT NULL
          GROUP BY sector ORDER BY dollars DESC
        ) t
      )
    ),
    'interventions', (
      SELECT json_agg(json_build_object(
        'id', ai.id, 'name', ai.name, 'type', ai.type,
        'description', ai.description, 'target_cohort', ai.target_cohort,
        'geography', ai.geography, 'portfolio_score', ai.portfolio_score,
        'evidence_level', ai.evidence_level,
        'outcomes', (
          SELECT json_agg(json_build_object(
            'type', ao.outcome_type, 'description', ao.description,
            'measurement', ao.measurement_method, 'beneficiary', ao.beneficiary
          ))
          FROM alma_intervention_outcomes aio
          JOIN alma_outcomes ao ON ao.id = aio.outcome_id
          WHERE aio.intervention_id = ai.id
        ),
        'evidence_count', (SELECT count(*) FROM alma_intervention_evidence WHERE intervention_id = ai.id)
      ))
      FROM alma_interventions ai
      WHERE ai.operating_organization_id = p_org_id
        AND ai.verification_status IS DISTINCT FROM 'ai_generated'
    ),
    'is_indigenous', (
      SELECT COALESCE(is_indigenous_org, false)
      FROM organizations WHERE id = p_org_id
    )
  );
$$;


ALTER FUNCTION "public"."justice_funding_org_profile"("p_org_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."justice_funding_org_profile"("p_org_id" "uuid") IS 'Public org profile. Quarantines ai_generated interventions IN SQL (2026-08-08). is_indigenous reads organizations.is_indigenous_org, the register — it previously guessed from a regex over the NAME, which erased 741 Indigenous organisations and labelled two courts and the federal government as Indigenous.';



CREATE OR REPLACE FUNCTION "public"."justice_funding_organizations"("p_state" "text" DEFAULT 'QLD'::"text", "p_q" "text" DEFAULT NULL::"text", "p_sector" "text" DEFAULT NULL::"text", "p_indigenous_only" boolean DEFAULT false, "p_location" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS json
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  result json;
  total_count int;
  orgs json;
  locations json;
  -- Standard exclusion filter used as a subquery base
  base_filter text := '
    AND source NOT IN (''rogs-yj-expenditure'', ''rogs-2026'', ''aihw-yj'')
    AND recipient_name NOT IN (''Total'', ''2'', '''', ''(blank)'')
    AND recipient_name NOT LIKE ''Youth Justice - %''
    AND recipient_name NOT LIKE ''% - Total%''
    AND LENGTH(TRIM(recipient_name)) > 2
    AND recipient_name NOT LIKE ''Department of Youth Justice%''
    AND recipient_name NOT LIKE ''Department of Children%''
    AND recipient_name NOT LIKE ''Department of Communities%''
    AND recipient_name NOT LIKE ''Department of Justice%''
  ';
BEGIN
  SELECT count(*) INTO total_count
  FROM (
    SELECT lower(trim(recipient_name)) as norm_name
    FROM justice_funding
    WHERE state = p_state
      AND recipient_name IS NOT NULL
      AND recipient_name != ''
      AND lower(trim(recipient_name)) NOT IN ('', 'various', 'unknown', 'n/a', 'not applicable', 'tba', 'tbc')
      AND source NOT IN ('rogs-yj-expenditure', 'rogs-2026', 'aihw-yj')
      AND recipient_name NOT IN ('Total', '2', '(blank)')
      AND recipient_name NOT LIKE 'Youth Justice - %'
      AND recipient_name NOT LIKE '% - Total%'
      AND LENGTH(TRIM(recipient_name)) > 2
      AND recipient_name NOT LIKE 'Department of Youth Justice%'
      AND recipient_name NOT LIKE 'Department of Children%'
      AND recipient_name NOT LIKE 'Department of Communities%'
      AND recipient_name NOT LIKE 'Department of Justice%'
      AND (p_q IS NULL OR (
        recipient_name ILIKE '%' || p_q || '%'
        OR location ILIKE '%' || p_q || '%'
        OR recipient_abn ILIKE '%' || p_q || '%'
      ))
      AND (p_sector IS NULL OR sector = p_sector)
      AND (p_location IS NULL OR lower(trim(location)) = lower(trim(p_location)))
      AND (NOT p_indigenous_only OR (
        recipient_name ILIKE '%aboriginal%'
        OR recipient_name ILIKE '%torres strait%'
        OR recipient_name ILIKE '%indigenous%'
        OR recipient_name ILIKE '%murri%'
        OR recipient_name ILIKE '%first nations%'
      ))
    GROUP BY norm_name
  ) sub;

  SELECT json_agg(row_to_json(sub)) INTO orgs
  FROM (
    SELECT
      max(recipient_name) as recipient_name,
      max(recipient_abn) as recipient_abn,
      mode() WITHIN GROUP (ORDER BY location) as location,
      sum(amount_dollars)::numeric as total_dollars,
      count(*)::int as grant_count,
      count(DISTINCT financial_year)::int as years_funded,
      array_agg(DISTINCT sector) FILTER (WHERE sector IS NOT NULL) as sectors,
      bool_or(
        recipient_name ILIKE '%aboriginal%'
        OR recipient_name ILIKE '%torres strait%'
        OR recipient_name ILIKE '%indigenous%'
        OR recipient_name ILIKE '%murri%'
        OR recipient_name ILIKE '%first nations%'
      ) as is_indigenous,
      bool_or(alma_organization_id IS NOT NULL) as alma_linked,
      max(alma_organization_id::text) as alma_org_id
    FROM justice_funding
    WHERE state = p_state
      AND recipient_name IS NOT NULL
      AND recipient_name != ''
      AND lower(trim(recipient_name)) NOT IN ('', 'various', 'unknown', 'n/a', 'not applicable', 'tba', 'tbc')
      AND source NOT IN ('rogs-yj-expenditure', 'rogs-2026', 'aihw-yj')
      AND recipient_name NOT IN ('Total', '2', '(blank)')
      AND recipient_name NOT LIKE 'Youth Justice - %'
      AND recipient_name NOT LIKE '% - Total%'
      AND LENGTH(TRIM(recipient_name)) > 2
      AND recipient_name NOT LIKE 'Department of Youth Justice%'
      AND recipient_name NOT LIKE 'Department of Children%'
      AND recipient_name NOT LIKE 'Department of Communities%'
      AND recipient_name NOT LIKE 'Department of Justice%'
      AND (p_q IS NULL OR (
        recipient_name ILIKE '%' || p_q || '%'
        OR location ILIKE '%' || p_q || '%'
        OR recipient_abn ILIKE '%' || p_q || '%'
      ))
      AND (p_sector IS NULL OR sector = p_sector)
      AND (p_location IS NULL OR lower(trim(location)) = lower(trim(p_location)))
      AND (NOT p_indigenous_only OR (
        recipient_name ILIKE '%aboriginal%'
        OR recipient_name ILIKE '%torres strait%'
        OR recipient_name ILIKE '%indigenous%'
        OR recipient_name ILIKE '%murri%'
        OR recipient_name ILIKE '%first nations%'
      ))
    GROUP BY lower(trim(recipient_name))
    ORDER BY sum(amount_dollars) DESC NULLS LAST
    LIMIT p_limit
    OFFSET p_offset
  ) sub;

  SELECT json_agg(row_to_json(sub)) INTO locations
  FROM (
    SELECT lower(trim(location)) as location, count(*) as org_count
    FROM justice_funding
    WHERE state = p_state
      AND location IS NOT NULL
      AND location != ''
      AND lower(trim(location)) NOT IN ('multiple', 'not applicable', 'n/a', 'statewide', 'various', 'unknown')
    GROUP BY lower(trim(location))
    HAVING count(*) >= 5
    ORDER BY count(*) DESC
    LIMIT 200
  ) sub;

  result := json_build_object(
    'organizations', COALESCE(orgs, '[]'::json),
    'total', total_count,
    'locations', COALESCE(locations, '[]'::json)
  );

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."justice_funding_organizations"("p_state" "text", "p_q" "text", "p_sector" "text", "p_indigenous_only" boolean, "p_location" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."justice_funding_organizations"("p_state" "text" DEFAULT 'QLD'::"text", "p_q" "text" DEFAULT NULL::"text", "p_sector" "text" DEFAULT NULL::"text", "p_indigenous_only" boolean DEFAULT false, "p_location" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0, "p_funding_type" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT NULL::"text", "p_beneficiary" "text" DEFAULT NULL::"text", "p_purpose" "text" DEFAULT NULL::"text", "p_charity_size" "text" DEFAULT NULL::"text", "p_alma_only" boolean DEFAULT false, "p_sort" "text" DEFAULT 'funding'::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  result json;
  total_count int;
  orgs json;
  locations json;
  summary json;
BEGIN
  -- Count total matching orgs
  SELECT count(*) INTO total_count
  FROM (
    SELECT lower(trim(jf.recipient_name)) as norm_name
    FROM justice_funding jf
    LEFT JOIN acnc_charities ac ON jf.recipient_abn = ac.abn
      AND (p_beneficiary IS NOT NULL OR p_purpose IS NOT NULL OR p_charity_size IS NOT NULL)
    WHERE jf.state = p_state
      AND jf.recipient_name IS NOT NULL AND jf.recipient_name != ''
      AND lower(trim(jf.recipient_name)) NOT IN ('', 'various', 'unknown', 'n/a', 'not applicable', 'tba', 'tbc')
      AND (p_q IS NULL OR (
        jf.recipient_name ILIKE '%' || p_q || '%'
        OR jf.location ILIKE '%' || p_q || '%'
        OR jf.recipient_abn ILIKE '%' || p_q || '%'
      ))
      AND (p_sector IS NULL OR jf.sector = p_sector)
      AND (p_location IS NULL OR lower(trim(jf.location)) = lower(trim(p_location)))
      AND (NOT p_indigenous_only OR (
        jf.recipient_name ILIKE '%aboriginal%'
        OR jf.recipient_name ILIKE '%torres strait%'
        OR jf.recipient_name ILIKE '%indigenous%'
        OR jf.recipient_name ILIKE '%murri%'
        OR jf.recipient_name ILIKE '%first nations%'
      ))
      AND (p_funding_type IS NULL OR jf.funding_type = p_funding_type)
      AND (p_source IS NULL OR jf.source = p_source)
      AND (NOT p_alma_only OR jf.alma_organization_id IS NOT NULL)
      AND (p_beneficiary IS NULL OR (
        CASE p_beneficiary
          WHEN 'ben_youth' THEN ac.ben_youth
          WHEN 'ben_children' THEN ac.ben_children
          WHEN 'ben_aboriginal_tsi' THEN ac.ben_aboriginal_tsi
          WHEN 'ben_pre_post_release' THEN ac.ben_pre_post_release
          WHEN 'ben_victims_of_crime' THEN ac.ben_victims_of_crime
          WHEN 'ben_people_at_risk_of_homelessness' THEN ac.ben_people_at_risk_of_homelessness
          ELSE false
        END = true
      ))
      AND (p_purpose IS NULL OR (
        CASE p_purpose
          WHEN 'purpose_law_policy' THEN ac.purpose_law_policy
          WHEN 'purpose_reconciliation' THEN ac.purpose_reconciliation
          WHEN 'purpose_social_welfare' THEN ac.purpose_social_welfare
          WHEN 'purpose_human_rights' THEN ac.purpose_human_rights
          ELSE false
        END = true
      ))
      AND (p_charity_size IS NULL OR ac.charity_size = p_charity_size)
    GROUP BY norm_name
  ) sub;

  -- Get paginated orgs with ACNC data
  SELECT json_agg(row_to_json(sub)) INTO orgs
  FROM (
    SELECT
      max(jf.recipient_name) as recipient_name,
      max(jf.recipient_abn) as recipient_abn,
      mode() WITHIN GROUP (ORDER BY jf.location) as location,
      sum(jf.amount_dollars)::numeric as total_dollars,
      count(*)::int as grant_count,
      count(DISTINCT jf.financial_year)::int as years_funded,
      array_agg(DISTINCT jf.sector) FILTER (WHERE jf.sector IS NOT NULL) as sectors,
      bool_or(
        jf.recipient_name ILIKE '%aboriginal%'
        OR jf.recipient_name ILIKE '%torres strait%'
        OR jf.recipient_name ILIKE '%indigenous%'
        OR jf.recipient_name ILIKE '%murri%'
        OR jf.recipient_name ILIKE '%first nations%'
      ) as is_indigenous,
      bool_or(jf.alma_organization_id IS NOT NULL) as alma_linked,
      max(jf.alma_organization_id::text) as alma_org_id,
      -- ACNC fields
      max(ac.charity_size) as charity_size,
      bool_or(ac.pbi) as is_pbi,
      ARRAY(
        SELECT unnest FROM unnest(ARRAY[
          CASE WHEN bool_or(ac.purpose_law_policy) THEN 'Law & Policy' END,
          CASE WHEN bool_or(ac.purpose_reconciliation) THEN 'Reconciliation' END,
          CASE WHEN bool_or(ac.purpose_social_welfare) THEN 'Social Welfare' END,
          CASE WHEN bool_or(ac.purpose_human_rights) THEN 'Human Rights' END
        ]) WHERE unnest IS NOT NULL
      ) as acnc_purposes,
      ARRAY(
        SELECT unnest FROM unnest(ARRAY[
          CASE WHEN bool_or(ac.ben_youth) THEN 'Youth' END,
          CASE WHEN bool_or(ac.ben_children) THEN 'Children' END,
          CASE WHEN bool_or(ac.ben_aboriginal_tsi) THEN 'First Nations' END,
          CASE WHEN bool_or(ac.ben_pre_post_release) THEN 'Pre/Post Release' END,
          CASE WHEN bool_or(ac.ben_victims_of_crime) THEN 'Victims of Crime' END,
          CASE WHEN bool_or(ac.ben_people_at_risk_of_homelessness) THEN 'Homelessness Risk' END
        ]) WHERE unnest IS NOT NULL
      ) as acnc_beneficiaries
    FROM justice_funding jf
    LEFT JOIN acnc_charities ac ON jf.recipient_abn = ac.abn
    WHERE jf.state = p_state
      AND jf.recipient_name IS NOT NULL AND jf.recipient_name != ''
      AND lower(trim(jf.recipient_name)) NOT IN ('', 'various', 'unknown', 'n/a', 'not applicable', 'tba', 'tbc')
      AND (p_q IS NULL OR (
        jf.recipient_name ILIKE '%' || p_q || '%'
        OR jf.location ILIKE '%' || p_q || '%'
        OR jf.recipient_abn ILIKE '%' || p_q || '%'
      ))
      AND (p_sector IS NULL OR jf.sector = p_sector)
      AND (p_location IS NULL OR lower(trim(jf.location)) = lower(trim(p_location)))
      AND (NOT p_indigenous_only OR (
        jf.recipient_name ILIKE '%aboriginal%'
        OR jf.recipient_name ILIKE '%torres strait%'
        OR jf.recipient_name ILIKE '%indigenous%'
        OR jf.recipient_name ILIKE '%murri%'
        OR jf.recipient_name ILIKE '%first nations%'
      ))
      AND (p_funding_type IS NULL OR jf.funding_type = p_funding_type)
      AND (p_source IS NULL OR jf.source = p_source)
      AND (NOT p_alma_only OR jf.alma_organization_id IS NOT NULL)
      AND (p_beneficiary IS NULL OR (
        CASE p_beneficiary
          WHEN 'ben_youth' THEN ac.ben_youth
          WHEN 'ben_children' THEN ac.ben_children
          WHEN 'ben_aboriginal_tsi' THEN ac.ben_aboriginal_tsi
          WHEN 'ben_pre_post_release' THEN ac.ben_pre_post_release
          WHEN 'ben_victims_of_crime' THEN ac.ben_victims_of_crime
          WHEN 'ben_people_at_risk_of_homelessness' THEN ac.ben_people_at_risk_of_homelessness
          ELSE false
        END = true
      ))
      AND (p_purpose IS NULL OR (
        CASE p_purpose
          WHEN 'purpose_law_policy' THEN ac.purpose_law_policy
          WHEN 'purpose_reconciliation' THEN ac.purpose_reconciliation
          WHEN 'purpose_social_welfare' THEN ac.purpose_social_welfare
          WHEN 'purpose_human_rights' THEN ac.purpose_human_rights
          ELSE false
        END = true
      ))
      AND (p_charity_size IS NULL OR ac.charity_size = p_charity_size)
    GROUP BY lower(trim(jf.recipient_name))
    ORDER BY
      CASE p_sort
        WHEN 'grants' THEN count(*)
        WHEN 'name' THEN 0
        ELSE 0
      END DESC NULLS LAST,
      CASE p_sort
        WHEN 'name' THEN max(jf.recipient_name)
        ELSE NULL
      END ASC NULLS LAST,
      CASE WHEN p_sort IS NULL OR p_sort = 'funding' THEN sum(jf.amount_dollars) ELSE NULL END DESC NULLS LAST
    LIMIT p_limit
    OFFSET p_offset
  ) sub;

  -- Locations for dropdown
  SELECT json_agg(row_to_json(sub)) INTO locations
  FROM (
    SELECT lower(trim(location)) as location, count(*) as org_count
    FROM justice_funding
    WHERE state = p_state
      AND location IS NOT NULL AND location != ''
      AND lower(trim(location)) NOT IN ('multiple', 'not applicable', 'n/a', 'statewide', 'various', 'unknown')
    GROUP BY lower(trim(location))
    HAVING count(*) >= 5
    ORDER BY count(*) DESC
    LIMIT 200
  ) sub;

  -- Summary stats for current filter
  SELECT json_build_object(
    'total_orgs', total_count,
    'total_dollars', (
      SELECT sum(amount_dollars)::numeric FROM justice_funding jf
      LEFT JOIN acnc_charities ac ON jf.recipient_abn = ac.abn
        AND (p_beneficiary IS NOT NULL OR p_purpose IS NOT NULL OR p_charity_size IS NOT NULL)
      WHERE jf.state = p_state
        AND jf.recipient_name IS NOT NULL AND jf.recipient_name != ''
        AND lower(trim(jf.recipient_name)) NOT IN ('', 'various', 'unknown', 'n/a', 'not applicable', 'tba', 'tbc')
        AND (p_q IS NULL OR (
          jf.recipient_name ILIKE '%' || p_q || '%'
          OR jf.location ILIKE '%' || p_q || '%'
          OR jf.recipient_abn ILIKE '%' || p_q || '%'
        ))
        AND (p_sector IS NULL OR jf.sector = p_sector)
        AND (p_location IS NULL OR lower(trim(jf.location)) = lower(trim(p_location)))
        AND (NOT p_indigenous_only OR (
          jf.recipient_name ILIKE '%aboriginal%'
          OR jf.recipient_name ILIKE '%torres strait%'
          OR jf.recipient_name ILIKE '%indigenous%'
          OR jf.recipient_name ILIKE '%murri%'
          OR jf.recipient_name ILIKE '%first nations%'
        ))
        AND (p_funding_type IS NULL OR jf.funding_type = p_funding_type)
        AND (p_source IS NULL OR jf.source = p_source)
        AND (NOT p_alma_only OR jf.alma_organization_id IS NOT NULL)
        AND (p_beneficiary IS NULL OR (
          CASE p_beneficiary
            WHEN 'ben_youth' THEN ac.ben_youth
            WHEN 'ben_children' THEN ac.ben_children
            WHEN 'ben_aboriginal_tsi' THEN ac.ben_aboriginal_tsi
            WHEN 'ben_pre_post_release' THEN ac.ben_pre_post_release
            WHEN 'ben_victims_of_crime' THEN ac.ben_victims_of_crime
            WHEN 'ben_people_at_risk_of_homelessness' THEN ac.ben_people_at_risk_of_homelessness
            ELSE false
          END = true
        ))
        AND (p_purpose IS NULL OR (
          CASE p_purpose
            WHEN 'purpose_law_policy' THEN ac.purpose_law_policy
            WHEN 'purpose_reconciliation' THEN ac.purpose_reconciliation
            WHEN 'purpose_social_welfare' THEN ac.purpose_social_welfare
            WHEN 'purpose_human_rights' THEN ac.purpose_human_rights
            ELSE false
          END = true
        ))
        AND (p_charity_size IS NULL OR ac.charity_size = p_charity_size)
    ),
    'indigenous_orgs', (
      SELECT count(DISTINCT lower(trim(jf.recipient_name)))::int FROM justice_funding jf
      LEFT JOIN acnc_charities ac ON jf.recipient_abn = ac.abn
        AND (p_beneficiary IS NOT NULL OR p_purpose IS NOT NULL OR p_charity_size IS NOT NULL)
      WHERE jf.state = p_state
        AND jf.recipient_name IS NOT NULL AND jf.recipient_name != ''
        AND lower(trim(jf.recipient_name)) NOT IN ('', 'various', 'unknown', 'n/a', 'not applicable', 'tba', 'tbc')
        AND (jf.recipient_name ILIKE '%aboriginal%'
          OR jf.recipient_name ILIKE '%torres strait%'
          OR jf.recipient_name ILIKE '%indigenous%'
          OR jf.recipient_name ILIKE '%murri%'
          OR jf.recipient_name ILIKE '%first nations%')
        AND (p_q IS NULL OR (
          jf.recipient_name ILIKE '%' || p_q || '%'
          OR jf.location ILIKE '%' || p_q || '%'
          OR jf.recipient_abn ILIKE '%' || p_q || '%'
        ))
        AND (p_sector IS NULL OR jf.sector = p_sector)
        AND (p_location IS NULL OR lower(trim(jf.location)) = lower(trim(p_location)))
        AND (p_funding_type IS NULL OR jf.funding_type = p_funding_type)
        AND (p_source IS NULL OR jf.source = p_source)
        AND (NOT p_alma_only OR jf.alma_organization_id IS NOT NULL)
        AND (p_beneficiary IS NULL OR (
          CASE p_beneficiary
            WHEN 'ben_youth' THEN ac.ben_youth
            WHEN 'ben_children' THEN ac.ben_children
            WHEN 'ben_aboriginal_tsi' THEN ac.ben_aboriginal_tsi
            WHEN 'ben_pre_post_release' THEN ac.ben_pre_post_release
            WHEN 'ben_victims_of_crime' THEN ac.ben_victims_of_crime
            WHEN 'ben_people_at_risk_of_homelessness' THEN ac.ben_people_at_risk_of_homelessness
            ELSE false
          END = true
        ))
        AND (p_purpose IS NULL OR (
          CASE p_purpose
            WHEN 'purpose_law_policy' THEN ac.purpose_law_policy
            WHEN 'purpose_reconciliation' THEN ac.purpose_reconciliation
            WHEN 'purpose_social_welfare' THEN ac.purpose_social_welfare
            WHEN 'purpose_human_rights' THEN ac.purpose_human_rights
            ELSE false
          END = true
        ))
        AND (p_charity_size IS NULL OR ac.charity_size = p_charity_size)
    ),
    'alma_orgs', (
      SELECT count(DISTINCT lower(trim(jf.recipient_name)))::int FROM justice_funding jf
      LEFT JOIN acnc_charities ac ON jf.recipient_abn = ac.abn
        AND (p_beneficiary IS NOT NULL OR p_purpose IS NOT NULL OR p_charity_size IS NOT NULL)
      WHERE jf.state = p_state
        AND jf.recipient_name IS NOT NULL AND jf.recipient_name != ''
        AND lower(trim(jf.recipient_name)) NOT IN ('', 'various', 'unknown', 'n/a', 'not applicable', 'tba', 'tbc')
        AND jf.alma_organization_id IS NOT NULL
        AND (p_q IS NULL OR (
          jf.recipient_name ILIKE '%' || p_q || '%'
          OR jf.location ILIKE '%' || p_q || '%'
          OR jf.recipient_abn ILIKE '%' || p_q || '%'
        ))
        AND (p_sector IS NULL OR jf.sector = p_sector)
        AND (p_location IS NULL OR lower(trim(jf.location)) = lower(trim(p_location)))
        AND (NOT p_indigenous_only OR (
          jf.recipient_name ILIKE '%aboriginal%'
          OR jf.recipient_name ILIKE '%torres strait%'
          OR jf.recipient_name ILIKE '%indigenous%'
          OR jf.recipient_name ILIKE '%murri%'
          OR jf.recipient_name ILIKE '%first nations%'
        ))
        AND (p_funding_type IS NULL OR jf.funding_type = p_funding_type)
        AND (p_source IS NULL OR jf.source = p_source)
        AND (p_beneficiary IS NULL OR (
          CASE p_beneficiary
            WHEN 'ben_youth' THEN ac.ben_youth
            WHEN 'ben_children' THEN ac.ben_children
            WHEN 'ben_aboriginal_tsi' THEN ac.ben_aboriginal_tsi
            WHEN 'ben_pre_post_release' THEN ac.ben_pre_post_release
            WHEN 'ben_victims_of_crime' THEN ac.ben_victims_of_crime
            WHEN 'ben_people_at_risk_of_homelessness' THEN ac.ben_people_at_risk_of_homelessness
            ELSE false
          END = true
        ))
        AND (p_purpose IS NULL OR (
          CASE p_purpose
            WHEN 'purpose_law_policy' THEN ac.purpose_law_policy
            WHEN 'purpose_reconciliation' THEN ac.purpose_reconciliation
            WHEN 'purpose_social_welfare' THEN ac.purpose_social_welfare
            WHEN 'purpose_human_rights' THEN ac.purpose_human_rights
            ELSE false
          END = true
        ))
        AND (p_charity_size IS NULL OR ac.charity_size = p_charity_size)
    )
  ) INTO summary;

  result := json_build_object(
    'organizations', COALESCE(orgs, '[]'::json),
    'total', total_count,
    'locations', COALESCE(locations, '[]'::json),
    'summary', summary
  );

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."justice_funding_organizations"("p_state" "text", "p_q" "text", "p_sector" "text", "p_indigenous_only" boolean, "p_location" "text", "p_limit" integer, "p_offset" integer, "p_funding_type" "text", "p_source" "text", "p_beneficiary" "text", "p_purpose" "text", "p_charity_size" "text", "p_alma_only" boolean, "p_sort" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."justice_funding_overview"("p_state" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH filtered AS (
    SELECT
      jf.*,
      (
        coalesce(o.is_indigenous_org, false) AND o.indigenous_org_basis IN ('oric_registered', 'supply_nation_certified', 'acnc_indigenous_charity', 'acco_certified', 'self_identified')
        OR coalesce(o.acco_certified, false)
      ) AS is_indigenous
    FROM public.justice_funding AS jf
    LEFT JOIN public.organizations AS o ON o.id = jf.alma_organization_id
    WHERE (p_state IS NULL OR jf.state = upper(p_state))
      AND jf.amount_dollars IS NOT NULL
      AND jf.amount_dollars > 0
  ),
  sector_totals AS (
    SELECT coalesce(sector, 'unknown') AS sector, sum(amount_dollars) AS total_dollars
    FROM filtered
    GROUP BY coalesce(sector, 'unknown')
    ORDER BY total_dollars DESC NULLS LAST
    LIMIT 1
  )
  SELECT jsonb_build_object(
    'total_records', count(*)::bigint,
    'total_dollars', coalesce(sum(amount_dollars), 0)::numeric,
    'unique_orgs', count(DISTINCT coalesce(alma_organization_id::text, recipient_abn, recipient_name))::bigint,
    'unique_programs', count(DISTINCT program_name)::bigint,
    'alma_linked', count(*) FILTER (WHERE alma_organization_id IS NOT NULL)::bigint,
    'years_covered', count(DISTINCT financial_year)::bigint,
    'indigenous_records', count(*) FILTER (WHERE is_indigenous)::bigint,
    'indigenous_dollars', coalesce(sum(amount_dollars) FILTER (WHERE is_indigenous), 0)::numeric,
    'indigenous_orgs', count(DISTINCT coalesce(alma_organization_id::text, recipient_abn, recipient_name)) FILTER (WHERE is_indigenous)::bigint,
    'non_indigenous_dollars', coalesce(sum(amount_dollars) FILTER (WHERE NOT is_indigenous), 0)::numeric,
    'top_sector', (SELECT sector FROM sector_totals),
    'earliest_year', min(financial_year),
    'latest_year', max(financial_year)
  )
  FROM filtered;
$$;


ALTER FUNCTION "public"."justice_funding_overview"("p_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."justice_funding_parse_fy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  p record;
BEGIN
  p := parse_financial_year(NEW.financial_year);
  NEW.fy_start := p.fy_start;
  NEW.fy_end := p.fy_end;
  NEW.fy_open_ended := p.fy_open_ended;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."justice_funding_parse_fy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."justice_funding_power_concentration"("p_state" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
WITH filtered_funding AS (
  SELECT * FROM justice_funding
  WHERE (p_state IS NULL OR state = p_state)
    AND recipient_name NOT IN ('Total', '2', '', '(blank)')
    AND recipient_name NOT LIKE 'Youth Justice - %'
    AND recipient_name NOT LIKE '% - Total%'
    AND LENGTH(TRIM(recipient_name)) > 2
    AND source NOT IN ('rogs-yj-expenditure', 'rogs-2026', 'aihw-yj')
    AND recipient_name NOT LIKE 'Department of Youth Justice%'
    AND recipient_name NOT LIKE 'Department of Children%'
    AND recipient_name NOT LIKE 'Department of Communities%'
    AND recipient_name NOT LIKE 'Department of Justice%'
)
SELECT json_build_object(
  'top10_share', (
    SELECT json_build_object(
      'dollars', sum(top_dollars)::bigint,
      'pct', round((sum(top_dollars) / NULLIF((SELECT sum(amount_dollars) FROM filtered_funding), 0) * 100)::numeric, 1),
      'orgs', json_agg(json_build_object('name', recipient_name, 'dollars', top_dollars::bigint, 'abn', abn) ORDER BY top_dollars DESC)
    )
    FROM (
      SELECT recipient_name, sum(amount_dollars) as top_dollars,
        MAX(recipient_abn) as abn
      FROM filtered_funding
      GROUP BY recipient_name ORDER BY top_dollars DESC NULLS LAST LIMIT 10
    ) t
  ),
  'repeat_winners', (
    SELECT json_agg(row_to_json(t) ORDER BY t.total_dollars DESC)
    FROM (
      SELECT recipient_name, count(DISTINCT financial_year) as years_active,
        COALESCE(sum(amount_dollars), 0)::bigint as total_dollars,
        count(DISTINCT sector) as sector_count,
        count(*) as grant_count,
        MAX(recipient_abn) as abn,
        bool_or(EXISTS (SELECT 1 FROM public.organizations o WHERE o.abn = filtered_funding.recipient_abn AND (coalesce(o.acco_certified, false) OR (coalesce(o.is_indigenous_org, false) AND o.indigenous_org_basis IN ('oric_registered', 'supply_nation_certified', 'acnc_indigenous_charity', 'acco_certified', 'self_identified'))))) as is_indigenous
      FROM filtered_funding
      GROUP BY recipient_name
      HAVING count(DISTINCT financial_year) >= 10
      ORDER BY total_dollars DESC NULLS LAST
      LIMIT 25
    ) t
  ),
  'intermediaries', (
    SELECT json_agg(row_to_json(t) ORDER BY t.total_dollars DESC)
    FROM (
      SELECT recipient_name,
        COALESCE(sum(amount_dollars), 0)::bigint as total_dollars,
        count(*) as grant_count,
        count(DISTINCT financial_year) as years_active,
        MAX(recipient_abn) as abn,
        array_agg(DISTINCT sector) FILTER (WHERE sector IS NOT NULL) as sectors
      FROM filtered_funding
      WHERE sector IN ('youth_justice', 'community_services', 'indigenous_services')
        AND NOT (recipient_name ~* '(aboriginal|torres strait|indigenous|murri|first nations)')
        AND NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.abn = filtered_funding.recipient_abn AND (coalesce(o.acco_certified, false) OR (coalesce(o.is_indigenous_org, false) AND o.indigenous_org_basis IN ('oric_registered', 'supply_nation_certified', 'acnc_indigenous_charity', 'acco_certified', 'self_identified'))))
        AND amount_dollars > 100000
      GROUP BY recipient_name
      HAVING COALESCE(sum(amount_dollars), 0) > 5000000
      ORDER BY total_dollars DESC NULLS LAST
      LIMIT 20
    ) t
  ),
  'concentration', (
    SELECT json_build_object(
      'total_orgs', count(DISTINCT recipient_name),
      'orgs_for_50pct', (
        SELECT count(*) FROM (
          SELECT recipient_name, sum(amount_dollars) as org_total,
            sum(sum(amount_dollars)) OVER (ORDER BY sum(amount_dollars) DESC) as running_total
          FROM filtered_funding WHERE amount_dollars IS NOT NULL
          GROUP BY recipient_name
        ) sub
        WHERE running_total <= (SELECT sum(amount_dollars) * 0.5 FROM filtered_funding)
      ),
      'orgs_for_80pct', (
        SELECT count(*) FROM (
          SELECT recipient_name, sum(amount_dollars) as org_total,
            sum(sum(amount_dollars)) OVER (ORDER BY sum(amount_dollars) DESC) as running_total
          FROM filtered_funding WHERE amount_dollars IS NOT NULL
          GROUP BY recipient_name
        ) sub
        WHERE running_total <= (SELECT sum(amount_dollars) * 0.8 FROM filtered_funding)
      )
    )
    FROM filtered_funding
  )
);
$$;


ALTER FUNCTION "public"."justice_funding_power_concentration"("p_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."justice_funding_top_recipients"("p_state" "text" DEFAULT NULL::"text", "p_sector" "text" DEFAULT NULL::"text", "p_year" "text" DEFAULT NULL::"text", "p_indigenous_only" boolean DEFAULT false, "p_limit" integer DEFAULT 25) RETURNS TABLE("recipient_name" "text", "recipient_abn" "text", "grant_count" bigint, "total_dollars" numeric, "years_funded" bigint, "program_count" bigint, "sectors" "text"[], "is_indigenous" boolean, "alma_linked" boolean, "alma_org_id" "uuid")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  WITH filtered AS (
    SELECT
      jf.*,
      (
        coalesce(o.is_indigenous_org, false) AND o.indigenous_org_basis IN ('oric_registered', 'supply_nation_certified', 'acnc_indigenous_charity', 'acco_certified', 'self_identified')
        OR coalesce(o.acco_certified, false)
      ) AS is_indigenous
    FROM public.justice_funding AS jf
    LEFT JOIN public.organizations AS o ON o.id = jf.alma_organization_id
    WHERE (p_state IS NULL OR jf.state = upper(p_state))
      AND (p_sector IS NULL OR jf.sector = p_sector)
      AND (p_year IS NULL OR jf.financial_year = p_year)
      AND jf.amount_dollars IS NOT NULL
      AND jf.amount_dollars > 0
  )
  SELECT
    f.recipient_name,
    max(f.recipient_abn) AS recipient_abn,
    count(*)::bigint AS grant_count,
    coalesce(sum(f.amount_dollars), 0)::numeric AS total_dollars,
    count(DISTINCT f.financial_year)::bigint AS years_funded,
    count(DISTINCT f.program_name)::bigint AS program_count,
    array_remove(array_agg(DISTINCT f.sector), NULL) AS sectors,
    bool_or(f.is_indigenous) AS is_indigenous,
    bool_or(f.alma_organization_id IS NOT NULL) AS alma_linked,
    (array_remove(array_agg(DISTINCT f.alma_organization_id), NULL))[1] AS alma_org_id
  FROM filtered AS f
  WHERE (NOT p_indigenous_only OR f.is_indigenous)
  GROUP BY f.recipient_name
  ORDER BY total_dollars DESC NULLS LAST
  LIMIT greatest(1, least(coalesce(p_limit, 25), 100));
$$;


ALTER FUNCTION "public"."justice_funding_top_recipients"("p_state" "text", "p_sector" "text", "p_year" "text", "p_indigenous_only" boolean, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."justice_matrix_hybrid_campaigns"("query_text" "text", "query_embedding" "extensions"."vector" DEFAULT NULL::"extensions"."vector", "match_limit" integer DEFAULT 20, "p_cats" "text"[] DEFAULT NULL::"text"[], "p_region" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "p_scope" "text" DEFAULT 'all'::"text") RETURNS TABLE("id" "uuid", "campaign_name" "text", "country_region" "text", "lead_organizations" "text", "goals" "text", "notable_tactics" "text", "outcome_status" "text", "campaign_link" "text", "start_year" integer, "end_year" integer, "is_ongoing" boolean, "categories" "text"[], "country_code" character varying, "distance" double precision, "rrf_score" double precision)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  ts_q tsquery;
BEGIN
  SET LOCAL hnsw.ef_search = 200;
  ts_q := websearch_to_tsquery('english', coalesce(query_text, ''));

  RETURN QUERY
  WITH facet AS (
    SELECT c.id AS cid
    FROM justice_matrix_campaigns c
    WHERE (p_cats IS NULL OR c.categories && p_cats)
      AND (p_region IS NULL OR c.country_region ILIKE '%' || p_region || '%')
      AND (p_country IS NULL OR c.country_code = p_country)
      AND (
        p_scope = 'all'
        OR (p_scope = 'au' AND c.country_region ILIKE '%australia%')
        OR (p_scope = 'global' AND (c.country_region IS NULL OR c.country_region NOT ILIKE '%australia%'))
      )
  ),
  kw AS (
    SELECT
      c.id AS cid,
      row_number() OVER (
        ORDER BY ts_rank_cd(
          setweight(to_tsvector('english'::regconfig,
            coalesce(c.campaign_name, '') || ' ' ||
            coalesce(c.goals, '') || ' ' ||
            coalesce(c.notable_tactics, '')), 'A') ||
          setweight(to_tsvector('english'::regconfig,
            coalesce(c.lead_organizations, '') || ' ' ||
            coalesce(c.country_region, '') || ' ' ||
            coalesce(c.outcome_status, '')), 'B'),
          ts_q) DESC
      ) AS kw_rank
    FROM justice_matrix_campaigns c
    JOIN facet f ON f.cid = c.id
    WHERE ts_q IS NOT NULL
      AND ts_q <> ''::tsquery
      AND (
        setweight(to_tsvector('english'::regconfig,
          coalesce(c.campaign_name, '') || ' ' ||
          coalesce(c.goals, '') || ' ' ||
          coalesce(c.notable_tactics, '')), 'A') ||
        setweight(to_tsvector('english'::regconfig,
          coalesce(c.lead_organizations, '') || ' ' ||
          coalesce(c.country_region, '') || ' ' ||
          coalesce(c.outcome_status, '')), 'B')
      ) @@ ts_q
    LIMIT 100
  ),
  vec AS (
    SELECT
      c.id AS cid,
      (c.embedding <=> query_embedding) AS dist,
      row_number() OVER (ORDER BY c.embedding <=> query_embedding) AS vec_rank
    FROM justice_matrix_campaigns c
    JOIN facet f ON f.cid = c.id
    WHERE query_embedding IS NOT NULL
      AND c.embedding IS NOT NULL
    ORDER BY c.embedding <=> query_embedding
    LIMIT 100
  ),
  fused AS (
    SELECT
      coalesce(kw.cid, vec.cid) AS cid,
      vec.dist AS dist,
      (coalesce(1.0 / (60 + kw.kw_rank), 0.0)
        + coalesce(1.0 / (60 + vec.vec_rank), 0.0))::double precision AS score
    FROM kw
    FULL OUTER JOIN vec ON kw.cid = vec.cid
  )
  SELECT
    c.id, c.campaign_name, c.country_region, c.lead_organizations, c.goals,
    c.notable_tactics, c.outcome_status, c.campaign_link, c.start_year,
    c.end_year, c.is_ongoing, c.categories, c.country_code,
    fused.dist AS distance, fused.score AS rrf_score
  FROM fused
  JOIN justice_matrix_campaigns c ON c.id = fused.cid
  ORDER BY fused.score DESC, fused.dist ASC NULLS LAST
  LIMIT match_limit;
END;
$$;


