CREATE OR REPLACE FUNCTION "public"."justice_matrix_hybrid_cases"("query_text" "text", "query_embedding" "extensions"."vector" DEFAULT NULL::"extensions"."vector", "match_limit" integer DEFAULT 20, "p_cats" "text"[] DEFAULT NULL::"text"[], "p_outcome" "text" DEFAULT NULL::"text", "p_strength" "text" DEFAULT NULL::"text", "p_region" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "p_scope" "text" DEFAULT 'all'::"text") RETURNS TABLE("id" "uuid", "case_citation" "text", "jurisdiction" "text", "year" integer, "court" "text", "strategic_issue" "text", "key_holding" "text", "region" "text", "country_code" character varying, "categories" "text"[], "outcome" character varying, "precedent_strength" character varying, "case_type" "text", "authoritative_link" "text", "verified" boolean, "human_confirmed" boolean, "distance" double precision, "rrf_score" double precision)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  ts_q tsquery;
BEGIN
  SET LOCAL hnsw.ef_search = 200;
  ts_q := websearch_to_tsquery('english', coalesce(query_text, ''));

  RETURN QUERY
  WITH facet AS (
    SELECT c.id AS cid
    FROM justice_matrix_cases c
    WHERE (p_cats IS NULL OR c.categories && p_cats)
      AND (p_outcome IS NULL OR c.outcome = p_outcome)
      AND (p_strength IS NULL OR c.precedent_strength = p_strength)
      AND (p_region IS NULL OR c.region ILIKE '%' || p_region || '%')
      AND (p_country IS NULL OR c.country_code = p_country)
      AND (
        p_scope = 'all'
        OR (p_scope = 'au' AND c.jurisdiction ILIKE '%australia%')
        OR (p_scope = 'global' AND (c.jurisdiction IS NULL OR c.jurisdiction NOT ILIKE '%australia%'))
      )
  ),
  kw AS (
    SELECT
      c.id AS cid,
      row_number() OVER (
        ORDER BY ts_rank_cd(
          setweight(to_tsvector('english'::regconfig,
            coalesce(c.case_citation, '') || ' ' ||
            coalesce(c.strategic_issue, '') || ' ' ||
            coalesce(c.key_holding, '')), 'A') ||
          setweight(to_tsvector('english'::regconfig,
            coalesce(c.court, '') || ' ' ||
            coalesce(c.jurisdiction, '')), 'B'),
          ts_q) DESC
      ) AS kw_rank
    FROM justice_matrix_cases c
    JOIN facet f ON f.cid = c.id
    WHERE ts_q IS NOT NULL
      AND ts_q <> ''::tsquery
      AND (
        setweight(to_tsvector('english'::regconfig,
          coalesce(c.case_citation, '') || ' ' ||
          coalesce(c.strategic_issue, '') || ' ' ||
          coalesce(c.key_holding, '')), 'A') ||
        setweight(to_tsvector('english'::regconfig,
          coalesce(c.court, '') || ' ' ||
          coalesce(c.jurisdiction, '')), 'B')
      ) @@ ts_q
    LIMIT 200
  ),
  vec AS (
    SELECT
      c.id AS cid,
      (c.embedding <=> query_embedding) AS dist,
      row_number() OVER (ORDER BY c.embedding <=> query_embedding) AS vec_rank
    FROM justice_matrix_cases c
    JOIN facet f ON f.cid = c.id
    WHERE query_embedding IS NOT NULL
      AND c.embedding IS NOT NULL
    ORDER BY c.embedding <=> query_embedding
    LIMIT 200
  ),
  fused AS (
    SELECT
      coalesce(kw.cid, vec.cid) AS cid,
      vec.dist AS dist,
      (coalesce(1.0 / (60 + kw.kw_rank), 0.0)
        + coalesce(1.0 / (60 + vec.vec_rank), 0.0))::double precision AS score
    FROM kw
    FULL OUTER JOIN vec ON kw.cid = vec.cid
  )
  SELECT
    c.id, c.case_citation, c.jurisdiction, c.year, c.court, c.strategic_issue,
    c.key_holding, c.region, c.country_code, c.categories, c.outcome,
    c.precedent_strength, c.case_type, c.authoritative_link, c.verified,
    c.human_confirmed, fused.dist AS distance, fused.score AS rrf_score
  FROM fused
  JOIN justice_matrix_cases c ON c.id = fused.cid
  ORDER BY fused.score DESC, fused.dist ASC NULLS LAST
  LIMIT match_limit;
END;
$$;


