CREATE OR REPLACE FUNCTION "public"."justice_matrix_related_campaigns"("campaign_id" "uuid", "match_limit" integer DEFAULT 6) RETURNS TABLE("id" "uuid", "campaign_name" "text", "country_region" "text", "start_year" integer, "is_ongoing" boolean, "distance" double precision)
    LANGUAGE "sql" STABLE
    AS $$
  WITH base AS (
    SELECT embedding FROM justice_matrix_campaigns WHERE id = campaign_id
  )
  SELECT
    c.id,
    c.campaign_name,
    c.country_region,
    c.start_year,
    c.is_ongoing,
    (c.embedding <=> (SELECT embedding FROM base)) AS distance
  FROM justice_matrix_campaigns c, base
  WHERE c.id <> campaign_id
    AND c.embedding IS NOT NULL
    AND base.embedding IS NOT NULL
  ORDER BY c.embedding <=> base.embedding
  LIMIT match_limit;
$$;


