CREATE OR REPLACE FUNCTION "public"."match_answer_bank"("p_org_profile_id" "uuid", "p_query_embedding" "extensions"."vector", "p_match_count" integer DEFAULT 5, "p_match_threshold" double precision DEFAULT 0.5) RETURNS TABLE("id" "uuid", "question" "text", "answer" "text", "category" "text", "tags" "text"[], "use_count" integer, "similarity" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ab.id,
    ab.question,
    ab.answer,
    ab.category,
    ab.tags,
    ab.use_count,
    (1 - (ab.embedding <=> p_query_embedding))::FLOAT AS similarity
  FROM grant_answer_bank ab
  WHERE ab.org_profile_id = p_org_profile_id
    AND ab.embedding IS NOT NULL
    AND (1 - (ab.embedding <=> p_query_embedding)) > p_match_threshold
  ORDER BY ab.embedding <=> p_query_embedding
  LIMIT p_match_count;
END;
$$;


