    c.id,
    c.source_table,
    c.source_id,
    c.chunk_text,
    c.metadata,
    1 - (c.embedding <=> query_embedding) AS similarity
  FROM civic_intelligence_chunks c
  WHERE (filter_source IS NULL OR c.source_table = filter_source)
    AND c.embedding IS NOT NULL
  ORDER BY c.embedding <=> query_embedding
  LIMIT match_count;
END;
$$;


