CREATE OR REPLACE FUNCTION "public"."match_grants_for_org"("org_embedding" "extensions"."vector", "threshold" double precision DEFAULT 0.7, "match_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "name" "text", "provider" "text", "description" "text", "amount_max" integer, "closes_at" "date", "categories" "text"[], "url" "text", "grant_type" "text", "status" "text", "focus_areas" "text"[], "geography" "text", "similarity" double precision)
    LANGUAGE "sql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  SELECT
    g.id, g.name, g.provider, g.description,
    g.amount_max, g.closes_at, g.categories,
    g.url, g.grant_type, g.status,
    g.focus_areas, g.geography,
    (1 - (g.embedding <=> org_embedding))::FLOAT AS similarity
  FROM grant_opportunities g
  WHERE g.embedding IS NOT NULL
    AND g.grant_type NOT IN ('historical_award', 'service_directory')
    AND g.status NOT IN ('closed', 'expired')
    AND (g.closes_at IS NULL OR g.closes_at > CURRENT_DATE)
    AND (1 - (g.embedding <=> org_embedding)) >= threshold
  ORDER BY g.embedding <=> org_embedding
  LIMIT match_limit;
$$;


