CREATE OR REPLACE FUNCTION "public"."merge_duplicate_organizations"("p_dry_run" boolean DEFAULT true, "p_limit" integer DEFAULT NULL::integer) RETURNS TABLE("slug" "text", "winner_id" "uuid", "loser_ids" "uuid"[], "rows_repointed" bigint, "tables_touched" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  grp record;
  fk record;
  v_winner uuid;
  v_losers uuid[];
  v_moved bigint;
  v_total bigint;
  v_tables text[];
  v_sql text;
  v_done integer := 0;
begin
  for grp in
    select o.slug, o.abn, count(*) as n
    from organizations o
    where o.is_active
      and o.slug is not null
      and o.abn is not null
      and o.merged_into is null
    group by o.slug, o.abn
    having count(*) > 1
       and count(distinct lower(btrim(o.name))) = 1
       -- Never touch a record a community has engaged with.
       and not exists (
         select 1 from organization_claims c
         join organizations x on x.id = c.organization_id
         where x.slug = o.slug and x.abn = o.abn
       )
       and not exists (
         select 1 from organization_members m
         join organizations x on x.id = m.organization_id
         where x.slug = o.slug and x.abn = o.abn
       )
    order by o.slug
  loop
    exit when p_limit is not null and v_done >= p_limit;

    -- Winner: the row carrying the most attached funding, then the oldest.
    select id into v_winner
    from organizations o
    where o.slug = grp.slug and o.abn = grp.abn and o.is_active and o.merged_into is null
    order by
      (select count(*) from justice_funding f where f.alma_organization_id = o.id) desc,
      (select count(*) from alma_interventions i where i.operating_organization_id = o.id) desc,
      o.created_at asc nulls last
    limit 1;

    select array_agg(id) into v_losers
    from organizations o
    where o.slug = grp.slug and o.abn = grp.abn and o.is_active
      and o.merged_into is null and o.id <> v_winner;

    if v_losers is null or array_length(v_losers, 1) = 0 then
      continue;
    end if;

    v_total := 0;
    v_tables := '{}';

    for fk in
      select c.conrelid::regclass::text as tbl, a.attname as col
      from pg_constraint c
      join unnest(c.conkey) k(attnum) on true
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = k.attnum
      where c.contype = 'f' and c.confrelid = 'organizations'::regclass
    loop
      -- organizations.merged_into points at organizations; never rewrite it here.
      if fk.tbl = 'organizations' then continue; end if;

      execute format('select count(*) from %s where %I = any($1)', fk.tbl, fk.col)
        into v_moved using v_losers;

      if v_moved > 0 then
        v_total := v_total + v_moved;
        v_tables := v_tables || (fk.tbl || '.' || fk.col);

        if not p_dry_run then
          v_sql := format('update %s set %I = $1 where %I = any($2)', fk.tbl, fk.col, fk.col);
          begin
            execute v_sql using v_winner, v_losers;
          exception when unique_violation then
            -- The loser and winner both have a row in a table with a uniqueness rule
            -- on organization_id. Leave it; a human decides which record survives.
            v_tables := v_tables || (fk.tbl || '.' || fk.col || ' [SKIPPED unique_violation]');
          end;
        end if;
      end if;
    end loop;

    if not p_dry_run then
      update organizations
         set is_active = false,
             merged_into = v_winner,
             merged_at = now(),
             merge_basis = 'same_abn_identical_name'
       where id = any(v_losers);
    end if;

    slug := grp.slug;
    winner_id := v_winner;
    loser_ids := v_losers;
    rows_repointed := v_total;
    tables_touched := v_tables;
    return next;

    v_done := v_done + 1;
  end loop;
end;
$_$;


ALTER FUNCTION "public"."merge_duplicate_organizations"("p_dry_run" boolean, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_duplicate_organizations"("p_dry_run" boolean, "p_limit" integer) IS 'Merges same-slug/same-ABN/identical-name organisation duplicates. Dry run by default. Repoints every FK found in pg_constraint. Never deletes; losers keep merged_into.';



CREATE OR REPLACE FUNCTION "public"."merge_organization_pair"("p_winner" "uuid", "p_loser" "uuid", "p_basis" "text", "p_dry_run" boolean DEFAULT true) RETURNS TABLE("winner_id" "uuid", "loser_id" "uuid", "rows_repointed" bigint, "tables_touched" "text"[], "refused" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  fk record;
  v_moved bigint;
  v_total bigint := 0;
  v_tables text[] := '{}';
  v_refused text := null;
begin
  winner_id := p_winner;
  loser_id := p_loser;

  if p_winner = p_loser then
    refused := 'winner and loser are the same row';
    rows_repointed := 0; tables_touched := '{}';
    return next; return;
  end if;

  if p_basis is null or btrim(p_basis) = '' then
    refused := 'a merge basis is required, so the class can be reversed later';
    rows_repointed := 0; tables_touched := '{}';
    return next; return;
  end if;

  if not exists (select 1 from organizations where id = p_winner) then
    v_refused := 'winner does not exist';
  elsif not exists (select 1 from organizations where id = p_loser) then
    v_refused := 'loser does not exist';
  elsif exists (select 1 from organizations where id = p_loser and merged_into is not null) then
    v_refused := 'loser has already been merged';
  elsif exists (select 1 from organization_claims where organization_id = p_loser)
     or exists (select 1 from organization_members where organization_id = p_loser) then
    v_refused := 'a community has claimed or joined the losing row; not a data migration';
  end if;

  if v_refused is null
     and exists (select 1 from organizations where id = p_loser and is_indigenous_org)
     and not exists (select 1 from organizations where id = p_winner and is_indigenous_org) then
    v_refused := 'losing row is flagged Indigenous-led and the winner is not; resolve the flag first';
  end if;

  if v_refused is not null then
    refused := v_refused;
    rows_repointed := 0; tables_touched := '{}';
    return next; return;
  end if;

  for fk in
    select c.conrelid::regclass::text as tbl, a.attname as col
    from pg_constraint c
    join unnest(c.conkey) k(attnum) on true
    join pg_attribute a on a.attrelid = c.conrelid and a.attnum = k.attnum
    where c.contype = 'f' and c.confrelid = 'organizations'::regclass
  loop
    if fk.tbl = 'organizations' then continue; end if;

    execute format('select count(*) from %s where %I = $1', fk.tbl, fk.col)
      into v_moved using p_loser;

    if v_moved > 0 then
      v_total := v_total + v_moved;
      v_tables := v_tables || (fk.tbl || '.' || fk.col);

      if not p_dry_run then
        begin
          execute format('update %s set %I = $1 where %I = $2', fk.tbl, fk.col, fk.col)
            using p_winner, p_loser;
        exception when unique_violation then
          v_tables := v_tables || (fk.tbl || '.' || fk.col || ' [SKIPPED unique_violation]');
        end;
      end if;
    end if;
  end loop;

  if not p_dry_run then
    update organizations
       set is_active = false,
           merged_into = p_winner,
           merged_at = now(),
           merge_basis = p_basis
     where id = p_loser;
  end if;

  rows_repointed := v_total;
  tables_touched := v_tables;
  refused := null;
  return next;
end;
$_$;


ALTER FUNCTION "public"."merge_organization_pair"("p_winner" "uuid", "p_loser" "uuid", "p_basis" "text", "p_dry_run" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_organization_pair"("p_winner" "uuid", "p_loser" "uuid", "p_basis" "text", "p_dry_run" boolean) IS 'Merges a named losing organisation into a named winner. Dry run by default. Repoints every FK in pg_constraint, never deletes, and refuses when the loser is claimed, has members, or carries an Indigenous-led flag the winner lacks.';



CREATE OR REPLACE FUNCTION "public"."mv_refresh_plan"("p_tier" "text" DEFAULT 'nightly'::"text") RETURNS TABLE("seq" integer, "mv_name" "text", "depth" integer, "use_concurrent" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
WITH RECURSIVE members AS (
  -- registry rows for this tier that still exist as a populated matview
  SELECT r.mv_name, r.force_non_concurrent
  FROM mv_refresh_registry r
  JOIN pg_class c      ON c.relname = r.mv_name AND c.relkind = 'm'
  JOIN pg_namespace n  ON n.oid = c.relnamespace AND n.nspname = 'public'
  WHERE r.tier = p_tier
    AND r.enabled
),
edges AS (
  SELECT e.mv_name, e.depends_on
  FROM v_mv_dependency_edges e
  JOIN members m1 ON m1.mv_name = e.mv_name
  JOIN members m2 ON m2.mv_name = e.depends_on
),
depth (mv_name, d) AS (
  SELECT m.mv_name, 0
  FROM members m
  WHERE NOT EXISTS (SELECT 1 FROM edges e WHERE e.mv_name = m.mv_name)
  UNION ALL
  SELECT e.mv_name, dp.d + 1
  FROM depth dp
  JOIN edges e ON e.depends_on = dp.mv_name
  WHERE dp.d < 32              -- cycle guard; there are none today
),
ranked AS (
  SELECT m.mv_name,
         COALESCE(MAX(dp.d), 0) AS depth,
         -- CONCURRENTLY is only legal with a unique index. Derive it; never hardcode.
         (EXISTS (
            SELECT 1
            FROM pg_index i
            JOIN pg_class c ON c.oid = i.indrelid
            JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
            WHERE c.relname = m.mv_name AND i.indisunique
              -- CORRECTED 2026-08-14 (adversarial review, B8): REFRESH ... CONCURRENTLY
              -- also requires the unique index to be non-partial and expression-free.
              -- mv_foundation_landscape_geo has a unique EXPRESSION index today.
              AND i.indpred IS NULL AND i.indexprs IS NULL
          ) AND NOT m.force_non_concurrent) AS use_concurrent
  FROM members m
  LEFT JOIN depth dp ON dp.mv_name = m.mv_name
  GROUP BY m.mv_name, m.force_non_concurrent
)
SELECT (ROW_NUMBER() OVER (ORDER BY depth, mv_name))::int AS seq,
       mv_name, depth, use_concurrent
FROM ranked
ORDER BY depth, mv_name;
$$;


ALTER FUNCTION "public"."mv_refresh_plan"("p_tier" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mv_refresh_plan"("p_tier" "text") IS 'Dependency-ordered refresh plan for one tier. Order comes from pg_depend, CONCURRENTLY eligibility from pg_index. Read by refresh_civicgraph_mvs() and by scripts/refresh-views-v2.mjs so both use exactly the same list.';



CREATE OR REPLACE FUNCTION "public"."name_similarity"("name1" "text", "name2" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    n1 TEXT;
    n2 TEXT;
    max_len INT;
    distance INT;
BEGIN
    IF name1 IS NULL OR name2 IS NULL THEN RETURN 0; END IF;

    n1 := LOWER(TRIM(name1));
    n2 := LOWER(TRIM(name2));

    IF n1 = n2 THEN RETURN 1.00; END IF;

    max_len := GREATEST(LENGTH(n1), LENGTH(n2));
    IF max_len = 0 THEN RETURN 0; END IF;

    distance := levenshtein(n1, n2);
    RETURN GREATEST(0, 1.0 - (distance::DECIMAL / max_len))::DECIMAL(3,2);
END;
$$;


ALTER FUNCTION "public"."name_similarity"("name1" "text", "name2" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."name_similarity"("name1" "text", "name2" "text") IS 'Calculate similarity between two names (0.0 to 1.0)';



CREATE OR REPLACE FUNCTION "public"."normalize_company_name"("name" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $_$
DECLARE
  result text;
BEGIN
  result := UPPER(COALESCE(name, ''));
  -- Strip "as trustee for..." / "ATF..." / "ACN nnn" suffixes
  result := REGEXP_REPLACE(result, '\s*(AS\s+TRUSTEE\s+FOR|ATF|A\.T\.F\.)\s+.*$', '');
  -- Strip dash suffixes like "- Hotel Loan"
  result := REGEXP_REPLACE(result, '\s*-\s+.*$', '');
  -- Strip possessives  
  result := REGEXP_REPLACE(result, '''S?\s', ' ', 'g');
  -- Remove common company suffixes/articles
  result := REGEXP_REPLACE(result, '\mPTY\M', '', 'g');
  result := REGEXP_REPLACE(result, '\mLTD\M', '', 'g');
  result := REGEXP_REPLACE(result, '\mLIMITED\M', '', 'g');
  result := REGEXP_REPLACE(result, '\mINC\M', '', 'g');
  result := REGEXP_REPLACE(result, '\mINCORPORATED\M', '', 'g');
  result := REGEXP_REPLACE(result, '\mCORPORATION\M', '', 'g');
  result := REGEXP_REPLACE(result, '\mTHE\M', '', 'g');
  -- Strip non-alphanumeric (keep spaces)
  result := REGEXP_REPLACE(result, '[^A-Z0-9 ]', '', 'g');
  -- Collapse whitespace and trim
  result := TRIM(REGEXP_REPLACE(result, '\s+', ' ', 'g'));
  RETURN result;
END;
$_$;


