CREATE OR REPLACE FUNCTION "public"."parse_financial_year"("fy" "text", OUT "fy_start" smallint, OUT "fy_end" smallint, OUT "fy_open_ended" boolean) RETURNS "record"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
DECLARE
  a int; b int;
BEGIN
  fy_open_ended := false;
  IF fy IS NULL OR trim(fy) = '' THEN
    RETURN;
  END IF;
  fy := trim(fy);
  IF fy ~ '^\d{4}-\d{2}$' THEN
    a := left(fy, 4)::int;
    b := (a / 100) * 100 + right(fy, 2)::int;
    IF b <= a THEN b := b + 100; END IF;   -- e.g. 1999-00
    fy_start := a; fy_end := b;            -- covers both FY '2020-21' and span '2021-25'
  ELSIF fy ~ '^\d{4}-\d{4}$' THEN
    a := left(fy, 4)::int; b := right(fy, 4)::int;
    IF b >= a THEN fy_start := a; fy_end := b; END IF;  -- reversed ranges stay unparsed
  ELSIF fy ~* '^\d{4}-ongoing$' THEN
    fy_start := left(fy, 4)::int; fy_end := NULL; fy_open_ended := true;
  ELSIF fy ~ '^\d{4}$' THEN
    fy_start := fy::int; fy_end := fy::int; -- bare calendar year; excluded from FY vocab
  END IF;
END;
$_$;


ALTER FUNCTION "public"."parse_financial_year"("fy" "text", OUT "fy_start" smallint, OUT "fy_end" smallint, OUT "fy_open_ended" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."person_browse"("p_q" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'influence'::"text", "p_limit" integer DEFAULT 200, "p_offset" integer DEFAULT 0) RETURNS TABLE("identity_key" "text", "person_name" "text", "person_name_normalised" "text", "board_count" bigint, "acco_boards" bigint, "attributed_procurement" numeric, "attributed_justice" numeric, "attributed_donations" numeric, "financial_system_count" integer, "influence_score" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    v.identity_key, v.person_name, v.person_name_normalised, v.board_count, v.acco_boards,
    v.attributed_procurement, v.attributed_justice, v.attributed_donations,
    v.financial_system_count, v.influence_score_attributed
  FROM mv_person_identity_influence_v2 v
  WHERE v.is_nominee_block IS NOT TRUE
    AND v.board_count <= 10
    AND (p_q IS NULL OR v.person_name ILIKE '%' || p_q || '%')
  ORDER BY
    CASE WHEN p_sort = 'boards' THEN v.board_count END DESC NULLS LAST,
    CASE WHEN p_sort = 'systems' THEN v.financial_system_count END DESC NULLS LAST,
    CASE WHEN p_sort = 'procurement' THEN v.attributed_procurement END DESC NULLS LAST,
    CASE WHEN p_sort = 'justice' THEN v.attributed_justice END DESC NULLS LAST,
    CASE WHEN p_sort = 'donations' THEN v.attributed_donations END DESC NULLS LAST,
    CASE WHEN p_sort = 'name' THEN v.person_name END ASC NULLS LAST,
    v.influence_score_attributed DESC NULLS LAST,
    v.person_name ASC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 200), 1), 500)
  OFFSET GREATEST(COALESCE(p_offset, 0), 0)
$$;


ALTER FUNCTION "public"."person_browse"("p_q" "text", "p_sort" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


