CREATE OR REPLACE FUNCTION "public"."power_page_donations"("p_state" "text" DEFAULT 'QLD'::"text", "p_limit" integer DEFAULT 50) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $_$
DECLARE
  result json;
BEGIN
  SELECT json_agg(row_data) INTO result
  FROM (
    SELECT json_build_object(
      'org_name', jf.recipient_name,
      'abn', jf.recipient_abn,
      'justice_funding_total', jf.total_funding,
      'grant_count', jf.grant_count,
      'sectors', jf.sectors,
      'political_party', pd.party_group,
      'donation_total', pd.donation_total,
      'donation_count', pd.donation_count,
      'parties_detail', pd.parties_detail
    ) AS row_data
    FROM (
      SELECT
        recipient_abn,
        (ARRAY_AGG(recipient_name ORDER BY LENGTH(recipient_name) DESC)
         FILTER (WHERE recipient_name NOT IN ('Multiple', 'multiple', '(blank)', 'INDIVIDUALS', 'Individual names omitted', 'Various', 'various', 'Not specified', 'Withheld', 'N/A')
                 AND recipient_name !~ '^\s*$')
        )[1] AS recipient_name,
        SUM(amount_dollars) AS total_funding,
        COUNT(*) AS grant_count,
        ARRAY_AGG(DISTINCT sector) FILTER (WHERE sector IS NOT NULL) AS sectors
      FROM justice_funding
      WHERE (p_state IS NULL OR state = UPPER(p_state))
        AND recipient_abn IS NOT NULL
        AND amount_dollars > 0
      GROUP BY recipient_abn
      HAVING COUNT(*) FILTER (WHERE recipient_name NOT IN ('Multiple', 'multiple', '(blank)', 'INDIVIDUALS', 'Individual names omitted', 'Various', 'various', 'Not specified', 'Withheld', 'N/A')
                                AND recipient_name !~ '^\s*$') > 0
    ) jf
    JOIN (
      -- First: classify each donation into a party group, then aggregate by ABN + group
      SELECT
        donor_abn,
        (ARRAY_AGG(donor_name ORDER BY LENGTH(donor_name) DESC))[1] AS donor_name,
        party_group,
        SUM(amount) AS donation_total,
        SUM(cnt) AS donation_count,
        ARRAY_AGG(DISTINCT orig_donation_to) AS parties_detail
      FROM (
        SELECT
          donor_abn,
          donor_name,
          donation_to AS orig_donation_to,
          amount,
          1 AS cnt,
          CASE
            WHEN LOWER(donation_to) LIKE '%labor%' OR LOWER(donation_to) LIKE '%alp%' THEN 'Labor'
            WHEN LOWER(donation_to) LIKE '%liberal%' THEN 'Liberal'
            WHEN LOWER(donation_to) LIKE '%national%' AND LOWER(donation_to) LIKE '%party%' THEN 'Nationals'
            WHEN LOWER(donation_to) LIKE '%greens%' THEN 'Greens'
            ELSE 'Other'
          END AS party_group
        FROM political_donations
        WHERE donor_abn IS NOT NULL
          AND amount > 100
      ) classified
      GROUP BY donor_abn, party_group
    ) pd ON pd.donor_abn = jf.recipient_abn
      AND (
        EXISTS (
          SELECT 1
          FROM unnest(string_to_array(LOWER(regexp_replace(jf.recipient_name, '[^a-zA-Z ]', '', 'g')), ' ')) AS w
          WHERE LENGTH(w) >= 4
            AND w NOT IN ('pty', 'ltd', 'the', 'and', 'for', 'inc', 'limited', 'australia', 'australian', 'services', 'incorporated', 'group', 'association', 'community', 'national', 'council', 'union', 'centre', 'institute', 'training')
            AND LOWER(pd.donor_name) LIKE '%' || w || '%'
        )
      )
    WHERE jf.recipient_name IS NOT NULL
    ORDER BY jf.total_funding DESC
    LIMIT p_limit
  ) sub;

  RETURN COALESCE(result, '[]'::json);
END;
$_$;


ALTER FUNCTION "public"."power_page_donations"("p_state" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."power_page_network"("p_state" "text" DEFAULT 'QLD'::"text", "p_limit" integer DEFAULT 100) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  result json;
BEGIN
  -- Only show orgs that have political donation links — the actual power connections
  WITH funded_orgs AS (
    SELECT
      recipient_abn AS abn,
      (ARRAY_AGG(recipient_name ORDER BY LENGTH(recipient_name) DESC)
       FILTER (WHERE recipient_name NOT IN ('Multiple', 'multiple', '(blank)', 'INDIVIDUALS'))
      )[1] AS name,
      SUM(amount_dollars) AS total_funding,
      ARRAY_AGG(DISTINCT sector) FILTER (WHERE sector IS NOT NULL) AS sectors,
      BOOL_OR(
        recipient_name ILIKE '%aboriginal%' OR recipient_name ILIKE '%torres strait%'
        OR recipient_name ILIKE '%indigenous%' OR recipient_name ILIKE '%murri%'
        OR recipient_name ILIKE '%first nations%'
      ) AS is_indigenous
    FROM justice_funding
    WHERE (p_state IS NULL OR state = UPPER(p_state))
      AND recipient_abn IS NOT NULL
      AND amount_dollars > 0
    GROUP BY recipient_abn
  ),
  donation_links AS (
    SELECT
      fo.abn AS org_abn,
      fo.name AS org_name,
      fo.total_funding,
      fo.sectors,
      fo.is_indigenous,
      CASE
        WHEN LOWER(pd.donation_to) LIKE '%labor%' OR LOWER(pd.donation_to) LIKE '%alp%' THEN 'Labor'
        WHEN LOWER(pd.donation_to) LIKE '%liberal%' THEN 'Liberal'
        WHEN LOWER(pd.donation_to) LIKE '%national%' AND LOWER(pd.donation_to) LIKE '%party%' THEN 'Nationals'
        WHEN LOWER(pd.donation_to) LIKE '%greens%' THEN 'Greens'
        ELSE 'Other'
      END AS party_group,
      SUM(pd.amount) AS donation_total
    FROM funded_orgs fo
    JOIN political_donations pd ON pd.donor_abn = fo.abn
    WHERE pd.amount > 100
      -- Name similarity check
      AND EXISTS (
        SELECT 1
        FROM unnest(string_to_array(LOWER(regexp_replace(fo.name, '[^a-zA-Z ]', '', 'g')), ' ')) AS w
        WHERE LENGTH(w) >= 4
          AND w NOT IN ('pty', 'ltd', 'the', 'and', 'for', 'inc', 'limited', 'australia', 'australian', 'services', 'incorporated', 'group', 'association', 'community', 'national', 'council', 'union', 'centre', 'institute', 'training')
          AND LOWER(pd.donor_name) LIKE '%' || w || '%'
      )
    GROUP BY fo.abn, fo.name, fo.total_funding, fo.sectors, fo.is_indigenous,
      CASE
        WHEN LOWER(pd.donation_to) LIKE '%labor%' OR LOWER(pd.donation_to) LIKE '%alp%' THEN 'Labor'
        WHEN LOWER(pd.donation_to) LIKE '%liberal%' THEN 'Liberal'
        WHEN LOWER(pd.donation_to) LIKE '%national%' AND LOWER(pd.donation_to) LIKE '%party%' THEN 'Nationals'
        WHEN LOWER(pd.donation_to) LIKE '%greens%' THEN 'Greens'
        ELSE 'Other'
      END
    ORDER BY fo.total_funding DESC
    LIMIT p_limit
  ),
  org_nodes AS (
    SELECT DISTINCT ON (org_abn) jsonb_build_object(
      'id', org_abn,
      'name', org_name,
      'type', 'organization',
      'funding', total_funding,
      'sectors', to_jsonb(sectors),
      'is_indigenous', is_indigenous
    ) AS node FROM donation_links
  ),
  party_nodes AS (
    SELECT jsonb_build_object(
      'id', 'party_' || party_group,
      'name', party_group,
      'type', 'political_party',
      'funding', SUM(donation_total),
      'sectors', '[]'::jsonb,
      'is_indigenous', false
    ) AS node
    FROM donation_links
    GROUP BY party_group
  ),
  links AS (
    SELECT jsonb_build_object(
      'source', org_abn,
      'target', 'party_' || party_group,
      'type', 'political_donation',
      'value', donation_total
    ) AS link FROM donation_links
  )
  SELECT json_build_object(
    'nodes', COALESCE((SELECT jsonb_agg(node) FROM org_nodes), '[]'::jsonb)
             || COALESCE((SELECT jsonb_agg(node) FROM party_nodes), '[]'::jsonb),
    'links', COALESCE((SELECT jsonb_agg(link) FROM links), '[]'::jsonb)
  ) INTO result;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."power_page_network"("p_state" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."power_page_sankey"("p_state" "text" DEFAULT 'QLD'::"text") RETURNS json
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  result json;
BEGIN
  WITH funding_flows AS (
    SELECT
      COALESCE(jf.source, 'Government') AS funding_source,
      COALESCE(jf.sector, 'other') AS sector,
      CASE
        WHEN jf.recipient_name ILIKE '%aboriginal%' OR jf.recipient_name ILIKE '%torres strait%'
          OR jf.recipient_name ILIKE '%indigenous%' OR jf.recipient_name ILIKE '%murri%'
          OR jf.recipient_name ILIKE '%first nations%' THEN 'Indigenous-led'
        WHEN jf.amount_dollars > 10000000 THEN 'Large Organisation'
        WHEN jf.amount_dollars > 1000000 THEN 'Medium Organisation'
        ELSE 'Small Organisation'
      END AS org_type,
      SUM(jf.amount_dollars) AS total_amount,
      COUNT(*) AS grant_count
    FROM justice_funding jf
    WHERE (p_state IS NULL OR jf.state = UPPER(p_state))
      AND jf.amount_dollars > 0
    GROUP BY funding_source, sector, org_type
    HAVING SUM(jf.amount_dollars) > 10000
  ),
  -- Build nodes
  source_nodes AS (
    SELECT DISTINCT funding_source AS name, 'source' AS node_type FROM funding_flows
  ),
  sector_nodes AS (
    SELECT DISTINCT sector AS name, 'sector' AS node_type FROM funding_flows
  ),
  org_nodes AS (
    SELECT DISTINCT org_type AS name, 'org_type' AS node_type FROM funding_flows
  ),
  all_nodes AS (
    SELECT name, node_type, ROW_NUMBER() OVER () - 1 AS idx FROM (
      SELECT * FROM source_nodes
      UNION ALL
      SELECT * FROM sector_nodes
      UNION ALL
      SELECT * FROM org_nodes
    ) sub
  ),
  -- Build links: source → sector
  links_1 AS (
    SELECT
      src.idx AS source,
      tgt.idx AS target,
      SUM(ff.total_amount) AS value
    FROM funding_flows ff
    JOIN all_nodes src ON src.name = ff.funding_source AND src.node_type = 'source'
    JOIN all_nodes tgt ON tgt.name = ff.sector AND tgt.node_type = 'sector'
    GROUP BY src.idx, tgt.idx
  ),
  -- Build links: sector → org_type
  links_2 AS (
    SELECT
      src.idx AS source,
      tgt.idx AS target,
      SUM(ff.total_amount) AS value
    FROM funding_flows ff
    JOIN all_nodes src ON src.name = ff.sector AND src.node_type = 'sector'
    JOIN all_nodes tgt ON tgt.name = ff.org_type AND tgt.node_type = 'org_type'
    GROUP BY src.idx, tgt.idx
  )
  SELECT json_build_object(
    'nodes', (SELECT json_agg(json_build_object('name', name, 'type', node_type)) FROM all_nodes),
    'links', (SELECT json_agg(json_build_object('source', source, 'target', target, 'value', value))
              FROM (SELECT * FROM links_1 UNION ALL SELECT * FROM links_2) all_links
              WHERE value > 0)
  ) INTO result;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."power_page_sankey"("p_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."power_page_top_orgs"("p_state" "text" DEFAULT 'QLD'::"text", "p_limit" integer DEFAULT 50) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $_$
DECLARE
  result json;
  state_total numeric;
BEGIN
  -- Get state total for percentage calculation
  SELECT COALESCE(SUM(amount_dollars), 1) INTO state_total
  FROM justice_funding
  WHERE (p_state IS NULL OR state = UPPER(p_state))
    AND amount_dollars > 0;

  SELECT json_agg(row_data) INTO result
  FROM (
    SELECT json_build_object(
      'recipient_name', sub.recipient_name,
      'recipient_abn', sub.recipient_abn,
      'total_funding', sub.total_funding,
      'grant_count', sub.grant_count,
      'sectors', sub.sectors,
      'is_indigenous', sub.is_indigenous,
      'pct_of_total', ROUND((sub.total_funding / state_total * 100)::numeric, 2)
    ) AS row_data
    FROM (
      SELECT
        (ARRAY_AGG(recipient_name ORDER BY LENGTH(recipient_name) DESC)
         FILTER (WHERE recipient_name NOT IN ('Multiple', 'multiple', '(blank)', 'INDIVIDUALS', 'Individual names omitted', 'Various', 'various', 'Not specified', 'Withheld', 'N/A')
                 AND recipient_name !~ '^\s*$')
        )[1] AS recipient_name,
        recipient_abn,
        SUM(amount_dollars) AS total_funding,
        COUNT(*) AS grant_count,
        ARRAY_AGG(DISTINCT sector) FILTER (WHERE sector IS NOT NULL) AS sectors,
        BOOL_OR(
          recipient_name ILIKE '%aboriginal%' OR recipient_name ILIKE '%torres strait%'
          OR recipient_name ILIKE '%indigenous%' OR recipient_name ILIKE '%murri%'
          OR recipient_name ILIKE '%first nations%' OR recipient_name ILIKE '%koori%'
          OR recipient_name ILIKE '%ATSILS%' OR recipient_name ILIKE '%NAAJA%'
        ) AS is_indigenous
      FROM justice_funding
      WHERE (p_state IS NULL OR state = UPPER(p_state))
        AND amount_dollars > 0
      GROUP BY recipient_abn
      HAVING (ARRAY_AGG(recipient_name ORDER BY LENGTH(recipient_name) DESC)
              FILTER (WHERE recipient_name NOT IN ('Multiple', 'multiple', '(blank)', 'INDIVIDUALS')
                      AND recipient_name !~ '^\s*$'))[1] IS NOT NULL
      ORDER BY total_funding DESC
      LIMIT p_limit
    ) sub
  ) agg;

  RETURN COALESCE(result, '[]'::json);
END;
$_$;


ALTER FUNCTION "public"."power_page_top_orgs"("p_state" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_cultural_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    v_restrictions RECORD;
BEGIN
    -- Check cultural restrictions for the source entity
    SELECT * INTO v_restrictions
    FROM check_cultural_restrictions(NEW.source_table, NEW.source_id);

    -- If target is external and data is restricted
    IF NEW.target_system != 'internal' THEN
        -- Check if 'external' is NOT in permitted uses
        IF v_restrictions.has_restrictions
           AND NOT ('external' = ANY(v_restrictions.permitted_uses)) THEN

            -- Log the blocked attempt (if audit table exists)
            BEGIN
                INSERT INTO agent_audit_log (
                    agent_id, action, target_table, target_id,
                    success, error_message, cultural_data_accessed, cultural_review_required
                ) VALUES (
                    'sync-queue', 'sync_blocked', NEW.source_table, NEW.source_id,
                    FALSE, 'Blocked by cultural protocol: external sync not permitted',
                    TRUE, TRUE
                );
            EXCEPTION WHEN undefined_table THEN
                -- agent_audit_log doesn't exist yet, skip logging
                NULL;
            END;

            -- Either block or mark for review based on sensitivity
            IF v_restrictions.sensitivity_level IN ('sacred', 'restricted') THEN
                RAISE EXCEPTION 'Cannot sync culturally protected data (%) to external system. Contact cultural liaison: %',
                    v_restrictions.sensitivity_level, v_restrictions.cultural_liaison_id;
            ELSE
                -- For sensitive data, mark for review instead of blocking
                NEW.status := 'blocked';
                NEW.cultural_check_passed := FALSE;
                NEW.error_message := 'Requires cultural review before external sync';
            END IF;
        ELSE
            NEW.cultural_check_passed := TRUE;
        END IF;
    ELSE
        NEW.cultural_check_passed := TRUE;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_cultural_sync"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."prevent_cultural_sync"() IS 'Trigger function to block syncing culturally restricted data';



CREATE OR REPLACE FUNCTION "public"."process_new_transcript"("p_story_id" "uuid", "p_transcript_text" "text", "p_source" "text" DEFAULT 'manual'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    v_transcript_id UUID;
    v_word_count INTEGER;
BEGIN
    v_word_count := array_length(string_to_array(trim(p_transcript_text), ' '), 1);
    
    -- Mark existing as non-current
    UPDATE transcripts 
    SET is_current = false 
    WHERE story_id = p_story_id AND is_current = true;
    
    -- Insert new transcript
    INSERT INTO transcripts (
        story_id,
        raw_transcript,
        edited_transcript,
        source,
        word_count,
        processing_status,
        processing_completed_at
    ) VALUES (
        p_story_id,
        p_transcript_text,
        p_transcript_text,
        p_source,
        COALESCE(v_word_count, 0),
        'completed',
        NOW()
    ) RETURNING id INTO v_transcript_id;
    
    -- Update story for backward compatibility
    UPDATE stories 
    SET transcript = p_transcript_text 
    WHERE id = p_story_id;
    
    RETURN v_transcript_id;
END;
$$;


ALTER FUNCTION "public"."process_new_transcript"("p_story_id" "uuid", "p_transcript_text" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."profiles_block_privilege_self_edit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF current_user IN ('service_role', 'postgres', 'supabase_admin') THEN
    RETURN NEW;
  END IF;
  IF NEW.role IS DISTINCT FROM OLD.role
     OR NEW.is_super_admin IS DISTINCT FROM OLD.is_super_admin
     OR NEW.permissions IS DISTINCT FROM OLD.permissions
     OR NEW.account_status IS DISTINCT FROM OLD.account_status
  THEN
    RAISE EXCEPTION 'profiles: role, is_super_admin, permissions and account_status may only be changed by the service role' USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."profiles_block_privilege_self_edit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_campaign_for_enrichment"("p_campaign_id" "uuid", "p_campaign_type" "text", "p_limit" integer DEFAULT 100) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_queued_count INTEGER := 0;
  v_person RECORD;
BEGIN
  -- Get campaign contacts not yet enriched
  FOR v_person IN
    SELECT cca.person_id, cca.priority_score
    FROM contact_campaign_assignments cca
    JOIN person_identity_map pim ON cca.person_id = pim.person_id
    WHERE cca.campaign_id = p_campaign_id
      AND (pim.exa_enriched = FALSE OR pim.exa_refresh_needed = TRUE)
      AND cca.status NOT IN ('declined', 'no_response')
    ORDER BY cca.priority_score DESC NULLS LAST
    LIMIT p_limit
  LOOP
    PERFORM queue_for_exa_enrichment(
      v_person.person_id,
      p_campaign_type,
      COALESCE(v_person.priority_score, 50)::integer
    );
    v_queued_count := v_queued_count + 1;
  END LOOP;

  RETURN v_queued_count;
END;
$$;


ALTER FUNCTION "public"."queue_campaign_for_enrichment"("p_campaign_id" "uuid", "p_campaign_type" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_community_event_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    operation_type TEXT;
    sync_data JSONB;
BEGIN
    -- Determine operation type
    IF TG_OP = 'DELETE' THEN
        operation_type = 'delete';
        sync_data = to_jsonb(OLD);
    ELSIF TG_OP = 'UPDATE' THEN
        operation_type = 'update';
        sync_data = to_jsonb(NEW);
    ELSIF TG_OP = 'INSERT' THEN
        operation_type = 'insert';
        sync_data = to_jsonb(NEW);
    END IF;

    -- Only sync certain types of community events
    IF (NEW.event_category IN ('collaboration', 'impact') OR OLD.event_category IN ('collaboration', 'impact')) THEN
        -- Queue the sync event
        INSERT INTO sync_events (
            event_type,
            table_name,
            record_id,
            operation_data,
            sync_target,
            priority
        ) VALUES (
            operation_type,
            'community_events',
            COALESCE(NEW.id, OLD.id),
            sync_data,
            'neo4j',
            6 -- Lower priority for events
        );
    END IF;

    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."queue_community_event_sync"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_for_exa_enrichment"("p_person_id" "uuid", "p_campaign_type" "text" DEFAULT 'general'::"text", "p_priority" integer DEFAULT 50, "p_enrich_network" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_queue_id UUID;
  v_existing_status TEXT;
BEGIN
  -- Check if already in queue
  SELECT status INTO v_existing_status
  FROM exa_enrichment_queue
  WHERE person_id = p_person_id AND campaign_type = p_campaign_type;

  IF v_existing_status = 'completed' THEN
    -- Already enriched, skip
    RAISE NOTICE 'Person already enriched for campaign %', p_campaign_type;
    RETURN NULL;
  ELSIF v_existing_status = 'pending' OR v_existing_status = 'processing' THEN
    -- Already queued, just update priority if higher
    UPDATE exa_enrichment_queue
    SET priority = GREATEST(priority, p_priority),
        enrich_network = enrich_network OR p_enrich_network
    WHERE person_id = p_person_id AND campaign_type = p_campaign_type
    RETURNING id INTO v_queue_id;

    RETURN v_queue_id;
  ELSE
    -- New queue entry or failed previous attempt
    INSERT INTO exa_enrichment_queue (
      person_id,
      campaign_type,
      priority,
      enrich_network
    )
    VALUES (p_person_id, p_campaign_type, p_priority, p_enrich_network)
    ON CONFLICT (person_id, campaign_type) DO UPDATE
    SET priority = GREATEST(exa_enrichment_queue.priority, EXCLUDED.priority),
        status = 'pending',
        enrich_network = exa_enrichment_queue.enrich_network OR EXCLUDED.enrich_network,
        retry_count = 0,
        error_message = NULL
    RETURNING id INTO v_queue_id;

    RETURN v_queue_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."queue_for_exa_enrichment"("p_person_id" "uuid", "p_campaign_type" "text", "p_priority" integer, "p_enrich_network" boolean) OWNER TO "postgres";


