CREATE OR REPLACE FUNCTION "public"."queue_project_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    operation_type TEXT;
    sync_data JSONB;
BEGIN
    -- Determine operation type
    IF TG_OP = 'DELETE' THEN
        operation_type = 'delete';
        sync_data = to_jsonb(OLD);
    ELSIF TG_OP = 'UPDATE' THEN
        operation_type = 'update';
        sync_data = to_jsonb(NEW);
    ELSIF TG_OP = 'INSERT' THEN
        operation_type = 'insert';
        sync_data = to_jsonb(NEW);
    END IF;

    -- Queue the sync event
    INSERT INTO sync_events (
        event_type,
        table_name,
        record_id,
        operation_data,
        sync_target,
        priority
    ) VALUES (
        operation_type,
        'projects',
        COALESCE(NEW.id, OLD.id),
        sync_data,
        'neo4j',
        4 -- Medium-high priority for projects
    );

    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."queue_project_sync"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_user_profile_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    operation_type TEXT;
    sync_data JSONB;
BEGIN
    -- Determine operation type
    IF TG_OP = 'DELETE' THEN
        operation_type = 'delete';
        sync_data = to_jsonb(OLD);
    ELSIF TG_OP = 'UPDATE' THEN
        operation_type = 'update';
        sync_data = to_jsonb(NEW);
    ELSIF TG_OP = 'INSERT' THEN
        operation_type = 'insert';
        sync_data = to_jsonb(NEW);
    END IF;

    -- Queue the sync event
    INSERT INTO sync_events (
        event_type,
        table_name,
        record_id,
        operation_data,
        sync_target,
        priority
    ) VALUES (
        operation_type,
        'user_profiles',
        COALESCE(NEW.user_id, OLD.user_id),
        sync_data,
        'neo4j',
        3 -- High priority for user changes
    );

    -- Log the event
    RAISE NOTICE 'Queued % sync event for user_profiles record %', operation_type, COALESCE(NEW.user_id, OLD.user_id);

    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."queue_user_profile_sync"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."queue_user_profile_sync"() IS 'Trigger function to queue user profile changes for sync';



CREATE OR REPLACE FUNCTION "public"."rebuild_funder_board_paths"() RETURNS TABLE("paths" bigint, "low_risk" bigint, "medium_risk" bigint, "high_risk" bigint, "funders_with_paths" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  DELETE FROM funder_board_paths;

  INSERT INTO funder_board_paths (
    foundation_id, foundation_abn, foundation_name,
    person_name, identity_key, identity_confidence, cluster_size, role_at_funder,
    connected_entity_id, connected_entity_name, connected_entity_type,
    connected_state, connected_community_controlled, role_at_connected,
    path_grade, collision_risk, computed_at
  )
  SELECT DISTINCT ON (f.id, pi.identity_key, pr2.entity_id)
    f.id, f.acnc_abn, f.name,
    pr.person_name, pi.identity_key, pi.confidence, pi.cluster_size, pr.role_type,
    pr2.entity_id, e2.canonical_name, e2.entity_type,
    e2.state, e2.is_community_controlled, pr2.role_type,
    'unverified',
    CASE WHEN coalesce(pi.cluster_size, 1) <= 2 THEN 'low'
         WHEN coalesce(pi.cluster_size, 1) <= 5 THEN 'medium'
         ELSE 'high' END,
    now()
  FROM foundations f
  JOIN person_roles pr ON pr.entity_id = f.gs_entity_id AND pr.cessation_date IS NULL
  JOIN person_identities pi ON pi.role_id = pr.id
  JOIN person_identities pi2 ON pi2.identity_key = pi.identity_key
  JOIN person_roles pr2 ON pr2.id = pi2.role_id
  LEFT JOIN gs_entities e2 ON e2.id = pr2.entity_id
  WHERE pi.is_nominee_block = false
    AND pi.confidence IN ('high','medium')
    AND coalesce(pi.cluster_size, 1) <= 10
    AND pi2.is_nominee_block = false
    AND pr2.entity_id IS NOT NULL
    -- The other end must be a different organisation, or it is not a path.
    AND pr2.entity_id IS DISTINCT FROM f.gs_entity_id
  ORDER BY f.id, pi.identity_key, pr2.entity_id, pi.confidence DESC;

  RETURN QUERY
    SELECT count(*)::bigint,
           count(*) FILTER (WHERE collision_risk = 'low')::bigint,
           count(*) FILTER (WHERE collision_risk = 'medium')::bigint,
           count(*) FILTER (WHERE collision_risk = 'high')::bigint,
           count(DISTINCT foundation_id)::bigint
      FROM funder_board_paths;
END;
$$;


ALTER FUNCTION "public"."rebuild_funder_board_paths"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rebuild_funder_board_paths"() IS 'Rebuilds funder_board_paths from resolved identities. Full replace: a path that no longer holds must disappear rather than linger.';



CREATE OR REPLACE FUNCTION "public"."rebuild_funder_intelligence"() RETURNS TABLE("rows_written" bigint, "tier1" bigint, "tier2" bigint, "with_derived_themes" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  WITH reach AS (
    SELECT fg.foundation_id,
           count(DISTINCT fg.grantee_entity_id) AS grantees,
           count(DISTINCT fg.grantee_entity_id) FILTER (WHERE fg.grantee_community_controlled) AS cc,
           count(DISTINCT fg.grantee_entity_id) FILTER (WHERE fg.grantee_state IN ('NT','WA','QLD','SA')) AS tgt
      FROM mv_foundation_grantees fg
     GROUP BY fg.foundation_id
  ), grantee_tags AS (
    -- One row per (funder, grantee, tag). DISTINCT on grantee so a funder that
    -- gave to the same organisation ten times does not count it ten times.
    SELECT DISTINCT fg.foundation_id, fg.grantee_entity_id, t.tag
      FROM mv_foundation_grantees fg
      JOIN gs_entities e ON e.id = fg.grantee_entity_id
      CROSS JOIN LATERAL (
        SELECT unnest(array_remove(ARRAY[
          -- Aboriginal community control is the strongest signal we hold, and
          -- it is a registry attribute rather than an inference.
          CASE WHEN e.entity_type = 'indigenous_corp' OR e.is_community_controlled
               OR lower(coalesce(e.sector,'')) LIKE '%indigenous%' THEN 'indigenous' END,
          CASE WHEN e.remoteness IN ('Outer Regional Australia','Remote Australia','Very Remote Australia')
               THEN 'rural_remote' END,
          -- SEIFA 1-3 is the most disadvantaged 30% of areas.
          CASE WHEN e.seifa_irsd_decile IS NOT NULL AND e.seifa_irsd_decile <= 3
               THEN 'disadvantage' END,
          CASE WHEN lower(coalesce(e.sector,'')) LIKE '%education%' THEN 'education' END,
          CASE WHEN lower(coalesce(e.sector,'')) LIKE '%health%' THEN 'health' END,
          CASE WHEN lower(coalesce(e.sector,'')) LIKE '%arts%' THEN 'arts' END,
          CASE WHEN lower(coalesce(e.sector,'')) LIKE '%social welfare%' THEN 'social-welfare' END,
          CASE WHEN lower(coalesce(e.sector,'')) LIKE '%communit%' THEN 'community' END,
          CASE WHEN lower(coalesce(e.sector,'')) LIKE '%environment%' THEN 'environment' END,
          CASE WHEN lower(coalesce(e.sector,'')) LIKE '%religion%' THEN 'religion' END
        ], NULL)) AS tag
      ) t
  ), tag_counts AS (
    SELECT gt.foundation_id, gt.tag, count(*) AS tagged
      FROM grantee_tags gt
     GROUP BY gt.foundation_id, gt.tag
  ), derived AS (
    -- A tag survives when it covers at least 10% of a funder's grantees and at
    -- least 3 of them. The floor stops a single grant from branding a funder;
    -- the share stops a large funder's long tail from acquiring every tag.
    SELECT tc.foundation_id,
           array_agg(tc.tag ORDER BY tc.tagged DESC)
             FILTER (WHERE tc.tagged >= 3 AND tc.tagged::numeric / r.grantees >= 0.10) AS tags,
           jsonb_object_agg(tc.tag, tc.tagged) AS evidence
      FROM tag_counts tc
      JOIN reach r ON r.foundation_id = tc.foundation_id
     GROUP BY tc.foundation_id
  ), boards AS (
    SELECT f.id AS foundation_id,
           count(DISTINCT pr.person_name_normalised) AS members
      FROM foundations f
      JOIN person_roles pr ON pr.entity_id = f.gs_entity_id
     WHERE pr.cessation_date IS NULL
     GROUP BY f.id
  ), paths AS (
    SELECT f.id AS foundation_id, count(*) AS path_count
      FROM foundations f
      JOIN (
        SELECT DISTINCT foundation_abn, trustee_name, grantee_abn
          FROM mv_trustee_grantee_chain
         WHERE trustee_on_grantee_board
      ) t ON t.foundation_abn = f.acnc_abn
     GROUP BY f.id
  )
  INSERT INTO funder_intelligence AS fi (
    foundation_id, foundation_abn, foundation_name,
    total_giving_annual, giving_grade,
    grantee_count, community_controlled_grantees, target_state_grantees, reach_grade,
    thematic_focus, geographic_focus, theme_grade,
    derived_thematics, derived_theme_evidence, derived_theme_grade,
    board_member_count, board_path_count, board_grade,
    funder_type, type_grade,
    evidence_tier, rank_score, computed_at
  )
  SELECT
    f.id, f.acnc_abn, f.name,
    f.total_giving_annual,
    CASE WHEN f.total_giving_annual IS NULL THEN 'missing' ELSE 'inferred' END,
    coalesce(r.grantees, 0), coalesce(r.cc, 0), coalesce(r.tgt, 0),
    CASE WHEN r.grantees IS NULL THEN 'missing' ELSE 'verified' END,
    f.thematic_focus, f.geographic_focus,
    CASE WHEN f.thematic_focus IS NULL OR cardinality(f.thematic_focus) = 0 THEN 'missing' ELSE 'inferred' END,
    d.tags, coalesce(d.evidence, '{}'::jsonb),
    CASE WHEN d.tags IS NULL OR cardinality(d.tags) = 0 THEN 'missing' ELSE 'verified' END,
    coalesce(b.members, 0), coalesce(p.path_count, 0),
    CASE WHEN b.members IS NULL THEN 'missing' ELSE 'verified' END,
    f.type, 'unverified',
    CASE WHEN coalesce(r.grantees,0) > 0 THEN 1
         WHEN coalesce(b.members,0) > 0 THEN 2
         ELSE 3 END,
    round(
      coalesce(r.cc, 0) * 3
      + coalesce(r.tgt, 0) * 1
      + coalesce(p.path_count, 0) * 2
      + CASE WHEN coalesce(f.total_giving_annual, 0) > 0
             THEN log(10, f.total_giving_annual) * 2 ELSE 0 END
    , 2),
    now()
  FROM foundations f
  LEFT JOIN reach r ON r.foundation_id = f.id
  LEFT JOIN derived d ON d.foundation_id = f.id
  LEFT JOIN boards b ON b.foundation_id = f.id
  LEFT JOIN paths p ON p.foundation_id = f.id
  ON CONFLICT (foundation_id) DO UPDATE SET
    foundation_abn = EXCLUDED.foundation_abn,
    foundation_name = EXCLUDED.foundation_name,
    total_giving_annual = EXCLUDED.total_giving_annual,
    giving_grade = EXCLUDED.giving_grade,
    grantee_count = EXCLUDED.grantee_count,
    community_controlled_grantees = EXCLUDED.community_controlled_grantees,
    target_state_grantees = EXCLUDED.target_state_grantees,
    reach_grade = EXCLUDED.reach_grade,
    thematic_focus = EXCLUDED.thematic_focus,
    geographic_focus = EXCLUDED.geographic_focus,
    theme_grade = EXCLUDED.theme_grade,
    derived_thematics = EXCLUDED.derived_thematics,
    derived_theme_evidence = EXCLUDED.derived_theme_evidence,
    derived_theme_grade = EXCLUDED.derived_theme_grade,
    board_member_count = EXCLUDED.board_member_count,
    board_path_count = EXCLUDED.board_path_count,
    board_grade = EXCLUDED.board_grade,
    funder_type = EXCLUDED.funder_type,
    type_grade = EXCLUDED.type_grade,
    evidence_tier = EXCLUDED.evidence_tier,
    previous_rank_score = fi.rank_score,
    rank_score = EXCLUDED.rank_score,
    computed_at = EXCLUDED.computed_at;

  RETURN QUERY
    SELECT count(*)::bigint,
           count(*) FILTER (WHERE evidence_tier = 1)::bigint,
           count(*) FILTER (WHERE evidence_tier = 2)::bigint,
           count(*) FILTER (WHERE derived_theme_grade = 'verified')::bigint
      FROM funder_intelligence;
END;
$$;


ALTER FUNCTION "public"."rebuild_funder_intelligence"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rebuild_place_funding_snapshot"() RETURNS TABLE("areas" bigint, "entities_counted" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  DELETE FROM place_funding_snapshot;

  WITH area_entity AS (
    SELECT e.id, e.abn, e.is_community_controlled, e.entity_type,
           CASE
             WHEN e.lga_name = 'Alice Springs' AND e.state = 'NT' THEN 'alice-springs'
             WHEN e.lga_name = 'Barkly' AND e.state = 'NT' THEN 'barkly'
             WHEN e.lga_name = 'MacDonnell' AND e.state = 'NT' THEN 'macdonnell'
             WHEN e.lga_name = 'Central Desert' AND e.state = 'NT' THEN 'central-desert'
             -- Explicitly the residue: still unplaced, so it cannot overlap above.
             WHEN e.postcode = '0872' AND e.state = 'NT' AND e.lga_name IS NULL THEN 'remote-unplaced'
           END AS area_key
      FROM gs_entities e
     WHERE e.state = 'NT'
  ), scoped AS (
    SELECT * FROM area_entity WHERE area_key IS NOT NULL
  ), orgs AS (
    SELECT area_key, count(*)::int AS org_count,
           count(*) FILTER (WHERE is_community_controlled OR entity_type = 'indigenous_corp')::int AS cc
      FROM scoped GROUP BY area_key
  ), contracts AS (
    SELECT s.area_key, count(*)::int AS n, coalesce(sum(c.contract_value), 0) AS val
      FROM scoped s JOIN austender_contracts c ON c.supplier_abn = s.abn
     WHERE s.abn IS NOT NULL GROUP BY s.area_key
  ), grants AS (
    SELECT s.area_key, count(*)::int AS n, coalesce(sum(jf.amount_dollars), 0) AS val
      FROM scoped s JOIN justice_funding jf ON jf.gs_entity_id = s.id
     GROUP BY s.area_key
  ), phil AS (
    SELECT s.area_key, count(DISTINCT fg.foundation_name)::int AS funders, count(*)::int AS n
      FROM scoped s JOIN mv_foundation_grantees fg ON fg.grantee_entity_id = s.id
     GROUP BY s.area_key
  )
  INSERT INTO place_funding_snapshot (
    area_key, area_label, area_note, state,
    org_count, community_controlled_count,
    contract_count, contract_value, govt_grant_count, govt_grant_value,
    philanthropic_funder_count, philanthropic_grant_count, lga_resolved, computed_at
  )
  SELECT o.area_key,
         CASE o.area_key
           WHEN 'alice-springs' THEN 'Mparntwe (Alice Springs)'
           WHEN 'barkly' THEN 'Barkly, including Tennant Creek'
           WHEN 'macdonnell' THEN 'MacDonnell'
           WHEN 'central-desert' THEN 'Central Desert'
           WHEN 'remote-unplaced' THEN 'Remote communities without a recorded council'
         END,
         CASE o.area_key
           WHEN 'macdonnell' THEN 'Includes Papunya, Hermannsburg and Areyonga.'
           WHEN 'central-desert' THEN 'Includes Yuendumu and Atitjere.'
           WHEN 'barkly' THEN 'Includes Tennant Creek, Ali Curung and Ampilatwatja in the Utopia homelands.'
           WHEN 'remote-unplaced' THEN 'These organisations are registered with ORIC, which publishes no address, so no council can be recorded for them. They are counted here rather than left out.'
           ELSE NULL
         END,
         'NT',
         o.org_count, o.cc,
         coalesce(c.n, 0), coalesce(c.val, 0),
         coalesce(g.n, 0), coalesce(g.val, 0),
         coalesce(ph.funders, 0), coalesce(ph.n, 0),
         o.area_key <> 'remote-unplaced',
         now()
    FROM orgs o
    LEFT JOIN contracts c ON c.area_key = o.area_key
    LEFT JOIN grants g ON g.area_key = o.area_key
    LEFT JOIN phil ph ON ph.area_key = o.area_key;

  RETURN QUERY SELECT count(*)::bigint, coalesce(sum(org_count), 0)::bigint FROM place_funding_snapshot;
END;
$$;


ALTER FUNCTION "public"."rebuild_place_funding_snapshot"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_alma_metric"("p_metric_type" "text", "p_value" integer, "p_period_start" "date" DEFAULT CURRENT_DATE, "p_period_end" "date" DEFAULT CURRENT_DATE, "p_project_id" "uuid" DEFAULT NULL::"uuid", "p_breakdown" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE v_id UUID; v_previous INTEGER;
BEGIN
  SELECT value INTO v_previous FROM alma_impact_metrics
  WHERE metric_type = p_metric_type AND (p_project_id IS NULL OR project_id = p_project_id)
  ORDER BY period_end DESC LIMIT 1;
  INSERT INTO alma_impact_metrics (metric_type, value, delta, period_start, period_end, project_id, breakdown)
  VALUES (p_metric_type, p_value, COALESCE(p_value - v_previous, 0), p_period_start, p_period_end, p_project_id, p_breakdown)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."record_alma_metric"("p_metric_type" "text", "p_value" integer, "p_period_start" "date", "p_period_end" "date", "p_project_id" "uuid", "p_breakdown" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_decision_feedback"("p_decision_id" "uuid", "p_feedback" "text", "p_feedback_by" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
    UPDATE decision_traces
    SET human_feedback = p_feedback,
        feedback_by = p_feedback_by,
        feedback_notes = p_notes,
        feedback_at = NOW(),
        -- Update outcome based on feedback
        outcome_status = CASE
            WHEN p_feedback = 'correct' THEN 'correct'
            WHEN p_feedback = 'incorrect' THEN 'incorrect'
            ELSE 'partial'
        END,
        outcome_recorded_at = NOW()
    WHERE id = p_decision_id;
END;
$$;


ALTER FUNCTION "public"."record_decision_feedback"("p_decision_id" "uuid", "p_feedback" "text", "p_feedback_by" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_execution_review_feedback"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.review_outcome IS NOT NULL AND OLD.review_outcome IS NULL THEN
    INSERT INTO agent_feedback_records (
      agent_id, action_name, execution_id, feedback_type,
      original_action, agent_confidence, action_context
    ) VALUES (
      NEW.agent_id, NEW.action_name, NEW.id,
      CASE NEW.review_outcome
        WHEN 'correct' THEN 'review_correct'
        WHEN 'incorrect' THEN 'review_incorrect'
        ELSE 'review_incorrect'
      END,
      NEW.action_params, NEW.confidence, NEW.reasoning
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."record_execution_review_feedback"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_memory_access"("p_table" "text", "p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  IF p_table = 'knowledge_chunks' THEN
    UPDATE knowledge_chunks SET access_count = access_count + 1, last_accessed_at = NOW() WHERE id = p_id;
  ELSIF p_table = 'project_knowledge' THEN
    UPDATE project_knowledge SET access_count = access_count + 1, last_accessed_at = NOW() WHERE id = p_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."record_memory_access"("p_table" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_opportunity_review"("p_user_id" "uuid", "p_org_profile_id" "uuid", "p_source_type" "text", "p_source_ref" "text", "p_project_code" "text" DEFAULT NULL::"text", "p_pathway" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_evidence_gaps" "text"[] DEFAULT '{}'::"text"[], "p_outcome" "text" DEFAULT NULL::"text", "p_judgment" "jsonb" DEFAULT '{}'::"jsonb", "p_supersedes_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("decision_id" "uuid", "action_event_id" "uuid")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_decision_id uuid;
  v_action_event_id uuid;
  v_action jsonb;
  v_action_kind text;
  v_action_owner text;
  v_action_beneficiary text;
  v_action_text text;
  v_action_due_at text;
begin
  if btrim(coalesce(p_source_type, '')) = '' or btrim(coalesce(p_source_ref, '')) = '' then
    raise exception 'source_type and source_ref are required';
  end if;

  if jsonb_typeof(coalesce(p_judgment, '{}'::jsonb)) <> 'object' then
    raise exception 'judgment must be a JSON object';
  end if;

  if btrim(coalesce(p_judgment ->> 'whatChanged', '')) = '' then
    raise exception 'judgment.whatChanged is required';
  end if;

  if p_supersedes_id is not null then
    perform 1
    from public.opportunity_decisions prior
    where prior.id = p_supersedes_id
      and prior.org_profile_id is not distinct from p_org_profile_id
      and prior.source_type = p_source_type
      and prior.source_ref = p_source_ref;

    if not found then
      raise exception 'supersedes_id must reference an earlier review for the same organisation and source';
    end if;
  end if;

  insert into public.opportunity_decisions (
    user_id,
    org_profile_id,
    source_type,
    source_ref,
    project_code,
    pathway,
    decision,
    reason,
    notes,
    evidence_gaps,
    outcome,
    judgment,
    supersedes_id
  )
  values (
    p_user_id,
    p_org_profile_id,
    p_source_type,
    p_source_ref,
    p_project_code,
    p_pathway,
    'review',
    p_reason,
    p_notes,
    coalesce(p_evidence_gaps, '{}'),
    p_outcome,
    coalesce(p_judgment, '{}'::jsonb),
    p_supersedes_id
  )
  returning id into v_decision_id;

  v_action := p_judgment -> 'commitment';

  if v_action is not null and v_action <> 'null'::jsonb then
    if jsonb_typeof(v_action) <> 'object' then
      raise exception 'judgment commitment/return must be a JSON object';
    end if;

    v_action_kind := lower(coalesce(v_action ->> 'kind', v_action ->> 'type', 'commitment'));
    v_action_owner := btrim(coalesce(v_action ->> 'owner', ''));
    v_action_beneficiary := nullif(btrim(coalesce(v_action ->> 'beneficiary', '')), '');
    v_action_text := btrim(coalesce(v_action ->> 'action', ''));
    v_action_due_at := nullif(btrim(coalesce(v_action ->> 'dueAt', '')), '');

    if v_action_kind not in ('commitment', 'return') then
      raise exception 'judgment commitment kind must be commitment or return';
    end if;

    if v_action_owner = '' or v_action_text = '' then
      raise exception 'judgment commitment/return requires an owner and action';
    end if;

    insert into public.opportunity_context_events (
      org_profile_id,
      source_system,
      source_type,
      source_ref,
      title,
      summary,
      actor_name,
      organisation,
      lane,
      signal_kind,
      confidence,
      happened_at,
      metadata,
      decision_id
    )
    values (
      p_org_profile_id,
      'human_review',
      'decision_action',
      v_decision_id::text,
      case
        when v_action_kind = 'return' then 'Return: ' || v_action_text
        else 'Commitment: ' || v_action_text
      end,
      v_action_text,
      v_action_owner,
      v_action_beneficiary,
      'relationship',
      'relationship_' || v_action_kind,
      1,
      now(),
      jsonb_strip_nulls(
        jsonb_build_object(
          'kind', v_action_kind,
          'owner', v_action_owner,
          'beneficiary', v_action_beneficiary,
          'action', v_action_text,
          'dueAt', v_action_due_at
        )
      ),
      v_decision_id
    )
    returning id into v_action_event_id;
  end if;

  return query select v_decision_id, v_action_event_id;
end;
$$;


