CREATE OR REPLACE FUNCTION "public"."refresh_civicgraph_mvs"("p_tier" "text" DEFAULT 'nightly'::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    SET "statement_timeout" TO '0'
    AS $$
DECLARE
  r          record;
  v_started  timestamptz;
  v_finished timestamptz;
  v_status   text;
  v_conc     boolean;
  v_error    text;
BEGIN
  FOR r IN SELECT * FROM mv_refresh_plan(p_tier) ORDER BY seq LOOP
    v_started := clock_timestamp();
    v_error   := NULL;
    v_status  := 'success';
    v_conc    := r.use_concurrent;

    BEGIN
      IF r.use_concurrent THEN
        EXECUTE format('REFRESH MATERIALIZED VIEW CONCURRENTLY %I', r.mv_name);
      ELSE
        EXECUTE format('REFRESH MATERIALIZED VIEW %I', r.mv_name);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_error  := SQLERRM;
      v_status := 'failed';
    END;

    IF v_status = 'failed' AND v_conc THEN
      BEGIN
        EXECUTE format('REFRESH MATERIALIZED VIEW %I', r.mv_name);
        v_status := 'success-fallback';
        v_conc   := false;
      EXCEPTION WHEN OTHERS THEN
        v_error := COALESCE(v_error, '') || ' | non-concurrent retry: ' || SQLERRM;
      END;
    END IF;

    v_finished := clock_timestamp();

    INSERT INTO mv_refresh_log
      (mv_name, started_at, finished_at, duration_ms, status, used_concurrent, error_message, triggered_by)
    VALUES
      (r.mv_name, v_started, v_finished,
       (EXTRACT(EPOCH FROM (v_finished - v_started)) * 1000)::int,
       v_status, v_conc, left(v_error, 1000), 'pg_cron:' || p_tier);
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."refresh_civicgraph_mvs"("p_tier" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refresh_civicgraph_mvs"("p_tier" "text") IS 'Backward-compatible wrapper. Reads mv_refresh_plan() — no hardcoded list. Cannot COMMIT per matview (functions cannot); prefer CALL refresh_civicgraph_mvs_run(tier).';



CREATE PROCEDURE "public"."refresh_civicgraph_mvs_run"(IN "p_tier" "text" DEFAULT 'nightly'::"text")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  r          record;
  v_started  timestamptz;
  v_finished timestamptz;
  v_status   text;
  v_conc     boolean;
  v_error    text;
BEGIN
  SET search_path TO 'public', 'extensions', 'pg_catalog';
  SET statement_timeout TO '0';

  FOR r IN SELECT * FROM mv_refresh_plan(p_tier) ORDER BY seq LOOP
    v_started := clock_timestamp();   -- NOT now(): now() is frozen per transaction
    v_error   := NULL;
    v_status  := 'success';
    v_conc    := r.use_concurrent;

    BEGIN
      IF r.use_concurrent THEN
        EXECUTE format('REFRESH MATERIALIZED VIEW CONCURRENTLY %I', r.mv_name);
      ELSE
        EXECUTE format('REFRESH MATERIALIZED VIEW %I', r.mv_name);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_error  := SQLERRM;
      v_status := 'failed';
    END;

    -- A CONCURRENTLY attempt can still fail on a matview whose unique index
    -- exists but is not usable (e.g. duplicate rows appeared). Retry once,
    -- non-concurrently, rather than losing the night's data for that object.
    IF v_status = 'failed' AND v_conc THEN
      BEGIN
        EXECUTE format('REFRESH MATERIALIZED VIEW %I', r.mv_name);
        v_status := 'success-fallback';
        v_conc   := false;
      EXCEPTION WHEN OTHERS THEN
        v_error := COALESCE(v_error, '') || ' | non-concurrent retry: ' || SQLERRM;
      END;
    END IF;

    v_finished := clock_timestamp();

    INSERT INTO mv_refresh_log
      (mv_name, started_at, finished_at, duration_ms, status, used_concurrent, error_message, triggered_by)
    VALUES
      (r.mv_name, v_started, v_finished,
       (EXTRACT(EPOCH FROM (v_finished - v_started)) * 1000)::int,
       v_status, v_conc, left(v_error, 1000), 'pg_cron:' || p_tier);

    COMMIT;   -- durable per matview: a later crash cannot erase this row
  END LOOP;
END;
$$;


ALTER PROCEDURE "public"."refresh_civicgraph_mvs_run"(IN "p_tier" "text") OWNER TO "postgres";


COMMENT ON PROCEDURE "public"."refresh_civicgraph_mvs_run"(IN "p_tier" "text") IS 'Refreshes every enabled matview in one tier, in dependency order from mv_refresh_plan(). One subtransaction per matview so a single failure does not stop the run, and one COMMIT per matview so the log survives a mid-run crash. Uses clock_timestamp() for real durations.';



CREATE OR REPLACE FUNCTION "public"."refresh_closing_the_gap_state_summary"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    SET "statement_timeout" TO '0'
    AS $$
DECLARE
  v_started timestamptz := now();
  v_finished timestamptz;
BEGIN
  REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_closing_the_gap_state_summary;
  v_finished := now();

  INSERT INTO public.mv_refresh_log (
    mv_name, started_at, finished_at, duration_ms, status, used_concurrent, triggered_by
  ) VALUES (
    'mv_closing_the_gap_state_summary', v_started, v_finished,
    extract(epoch FROM (v_finished - v_started)) * 1000, 'success', true, 'pg_cron'
  );
EXCEPTION WHEN OTHERS THEN
  v_finished := now();

  INSERT INTO public.mv_refresh_log (
    mv_name, started_at, finished_at, duration_ms, status, used_concurrent,
    error_message, triggered_by
  ) VALUES (
    'mv_closing_the_gap_state_summary', v_started, v_finished,
    extract(epoch FROM (v_finished - v_started)) * 1000, 'failed', true, SQLERRM, 'pg_cron'
  );

  RAISE;
END;
$$;


