CREATE OR REPLACE FUNCTION "public"."replace_current_project_funding_profiles"("p_rows" "jsonb") RETURNS TABLE("id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  written integer := 0;
BEGIN
  IF jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_rows) AS incoming(
      org_project_id uuid,
      org_profile_id uuid,
      schema_version text,
      profile_version text,
      completeness_status text,
      profile jsonb,
      provenance jsonb,
      created_by text,
      embedding_text text
    )
    LEFT JOIN public.org_projects project
      ON project.id = incoming.org_project_id
     AND project.org_profile_id = incoming.org_profile_id
    WHERE project.id IS NULL
  ) THEN
    RAISE EXCEPTION 'Funding profile project/org mismatch';
  END IF;

  UPDATE public.project_funding_profiles profile
  SET is_current = false, updated_at = now()
  WHERE profile.is_current
    AND profile.org_project_id IN (
      SELECT incoming.org_project_id
      FROM jsonb_to_recordset(p_rows) AS incoming(org_project_id uuid)
    );

  RETURN QUERY
  INSERT INTO public.project_funding_profiles (
    org_project_id,
    org_profile_id,
    schema_version,
    profile_version,
    effective_at,
    is_current,
    completeness_status,
    profile,
    provenance,
    created_by,
    embedding_text,
    updated_at
  )
  SELECT
    incoming.org_project_id,
    incoming.org_profile_id,
    incoming.schema_version,
    incoming.profile_version,
    now(),
    true,
    incoming.completeness_status,
    incoming.profile,
    incoming.provenance,
    incoming.created_by,
    incoming.embedding_text,
    now()
  FROM jsonb_to_recordset(p_rows) AS incoming(
    org_project_id uuid,
    org_profile_id uuid,
    schema_version text,
    profile_version text,
    completeness_status text,
    profile jsonb,
    provenance jsonb,
    created_by text,
    embedding_text text
  )
  ON CONFLICT (org_project_id, profile_version) DO UPDATE
  SET
    org_profile_id = EXCLUDED.org_profile_id,
    schema_version = EXCLUDED.schema_version,
    effective_at = EXCLUDED.effective_at,
    is_current = true,
    completeness_status = EXCLUDED.completeness_status,
    profile = EXCLUDED.profile,
    provenance = EXCLUDED.provenance,
    created_by = EXCLUDED.created_by,
    embedding_text = EXCLUDED.embedding_text,
    updated_at = EXCLUDED.updated_at
  RETURNING project_funding_profiles.id;

  GET DIAGNOSTICS written = ROW_COUNT;
  IF written <> jsonb_array_length(p_rows) THEN
    RAISE EXCEPTION 'Attempted % profiles but wrote %', jsonb_array_length(p_rows), written;
  END IF;
END;
$$;


ALTER FUNCTION "public"."replace_current_project_funding_profiles"("p_rows" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."replace_current_project_funding_profiles"("p_rows" "jsonb") IS 'Atomically retires current project funding profiles and promotes exactly one compiled version per incoming project.';



CREATE OR REPLACE FUNCTION "public"."reset_failed_sync_events"("table_filter" "text" DEFAULT NULL::"text", "max_age_hours" integer DEFAULT 24) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    reset_count INTEGER;
BEGIN
    UPDATE sync_events
    SET 
        sync_status = 'pending',
        retry_count = 0,
        error_message = NULL,
        processed_at = NULL
    WHERE 
        sync_status = 'failed'
        AND retry_count < max_retries
        AND created_at > NOW() - (max_age_hours || ' hours')::INTERVAL
        AND (table_filter IS NULL OR table_name = table_filter);

    GET DIAGNOSTICS reset_count = ROW_COUNT;
    RETURN reset_count;
END;
$$;


ALTER FUNCTION "public"."reset_failed_sync_events"("table_filter" "text", "max_age_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_entity"("p_source" "text", "p_source_id" "text", "p_name" "text", "p_email" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_company" "text" DEFAULT NULL::"text", "p_entity_type" "text" DEFAULT 'person'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    v_entity_id UUID;
    v_normalized_email TEXT;
    v_normalized_phone TEXT;
    v_existing_entity_id UUID;
BEGIN
    v_normalized_email := normalize_email(p_email);
    v_normalized_phone := normalize_phone(p_phone);

    -- 1. Check if source record already linked
    SELECT entity_id INTO v_existing_entity_id
    FROM entity_identifiers
    WHERE source = p_source AND source_record_id = p_source_id
    LIMIT 1;

    IF v_existing_entity_id IS NOT NULL THEN
        RETURN v_existing_entity_id;
    END IF;

    -- 2. Try to find existing entity by email
    IF v_normalized_email IS NOT NULL THEN
        SELECT entity_id INTO v_existing_entity_id
        FROM entity_identifiers
        WHERE identifier_type = 'email' AND normalized_value = v_normalized_email
        LIMIT 1;

        IF v_existing_entity_id IS NOT NULL THEN
            -- Add source ID to existing entity
            INSERT INTO entity_identifiers (entity_id, identifier_type, identifier_value, normalized_value, source, source_record_id)
            VALUES (v_existing_entity_id, p_source || '_id', p_source_id, p_source_id, p_source, p_source_id)
            ON CONFLICT DO NOTHING;
            RETURN v_existing_entity_id;
        END IF;
    END IF;

    -- 3. Try to find by phone
    IF v_normalized_phone IS NOT NULL THEN
        SELECT entity_id INTO v_existing_entity_id
        FROM entity_identifiers
        WHERE identifier_type = 'phone' AND normalized_value = v_normalized_phone
        LIMIT 1;

        IF v_existing_entity_id IS NOT NULL THEN
            -- Add source ID and email to existing entity
            INSERT INTO entity_identifiers (entity_id, identifier_type, identifier_value, normalized_value, source, source_record_id)
            VALUES (v_existing_entity_id, p_source || '_id', p_source_id, p_source_id, p_source, p_source_id)
            ON CONFLICT DO NOTHING;

            IF v_normalized_email IS NOT NULL THEN
                INSERT INTO entity_identifiers (entity_id, identifier_type, identifier_value, normalized_value, source, source_record_id)
                VALUES (v_existing_entity_id, 'email', p_email, v_normalized_email, p_source, p_source_id)
                ON CONFLICT DO NOTHING;
            END IF;

            RETURN v_existing_entity_id;
        END IF;
    END IF;

    -- 4. Create new canonical entity
    INSERT INTO canonical_entities (entity_type, canonical_name, canonical_email, canonical_phone, canonical_company)
    VALUES (p_entity_type, p_name, v_normalized_email, v_normalized_phone, p_company)
    RETURNING id INTO v_entity_id;

    -- Add identifiers
    INSERT INTO entity_identifiers (entity_id, identifier_type, identifier_value, normalized_value, source, source_record_id)
    VALUES (v_entity_id, p_source || '_id', p_source_id, p_source_id, p_source, p_source_id);

    IF v_normalized_email IS NOT NULL THEN
        INSERT INTO entity_identifiers (entity_id, identifier_type, identifier_value, normalized_value, source, source_record_id, is_primary)
        VALUES (v_entity_id, 'email', p_email, v_normalized_email, p_source, p_source_id, TRUE)
        ON CONFLICT DO NOTHING;
    END IF;

    IF v_normalized_phone IS NOT NULL THEN
        INSERT INTO entity_identifiers (entity_id, identifier_type, identifier_value, normalized_value, source, source_record_id, is_primary)
        VALUES (v_entity_id, 'phone', p_phone, v_normalized_phone, p_source, p_source_id, TRUE)
        ON CONFLICT DO NOTHING;
    END IF;

    RETURN v_entity_id;
END;
$$;


ALTER FUNCTION "public"."resolve_entity"("p_source" "text", "p_source_id" "text", "p_name" "text", "p_email" "text", "p_phone" "text", "p_company" "text", "p_entity_type" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_entity"("p_source" "text", "p_source_id" "text", "p_name" "text", "p_email" "text", "p_phone" "text", "p_company" "text", "p_entity_type" "text") IS 'Find or create canonical entity from a source record';



CREATE OR REPLACE FUNCTION "public"."retry_missed_reactions"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  evt RECORD;
  payload jsonb;
  webhook_url text;
  webhook_secret text;
  retry_count integer := 0;
BEGIN
  SELECT value INTO webhook_url FROM app_config WHERE key = 'reactor_webhook_url';
  SELECT value INTO webhook_secret FROM app_config WHERE key = 'reactor_webhook_secret';

  IF webhook_url IS NULL THEN
    RAISE WARNING 'reactor_webhook_url not configured';
    RETURN;
  END IF;

  -- Find events from last 2 hours with no corresponding reaction and no failed status
  FOR evt IN
    SELECT ie.*
    FROM integration_events ie
    LEFT JOIN event_reactions er ON er.event_id = ie.id
    WHERE ie.created_at > NOW() - INTERVAL '2 hours'
      AND ie.action != 'failed'
      AND ie.event_type != 'system.test'
      AND er.id IS NULL
      -- Only retry event types that have rules
      AND ie.event_type IN (
        'gmail.push_sync',
        'xero.invoice',
        'grant.deadline_warning',
        'opportunity.create',
        'action.overdue',
        'engagement.drop'
      )
    ORDER BY ie.created_at ASC
    LIMIT 20
  LOOP
    payload := jsonb_build_object(
      'type', 'INSERT',
      'table', 'integration_events',
      'schema', 'public',
      'record', row_to_json(evt)::jsonb
    );

    PERFORM net.http_post(
      url := webhook_url,
      body := payload,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || COALESCE(webhook_secret, '')
      )
    );

    retry_count := retry_count + 1;
  END LOOP;

  IF retry_count > 0 THEN
    RAISE NOTICE 'Retried % missed reactor events', retry_count;
  END IF;
END;
$$;


ALTER FUNCTION "public"."retry_missed_reactions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_memory_decay"() RETURNS TABLE("updated_chunks" integer, "updated_knowledge" integer, "archived" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_updated_chunks INT;
  v_updated_knowledge INT;
  v_archived INT;
BEGIN
  UPDATE knowledge_chunks kc
  SET decay_score = calculate_decay_score(
    kc.last_accessed_at, kc.access_count, kc.confidence, 'normal'
  )
  WHERE kc.consolidated_into IS NULL;
  GET DIAGNOSTICS v_updated_chunks = ROW_COUNT;

  UPDATE project_knowledge pk
  SET decay_score = calculate_decay_score(
    pk.last_accessed_at, pk.access_count,
    CASE pk.importance
      WHEN 'critical' THEN 0.95
      WHEN 'high' THEN 0.85
      ELSE 0.7
    END,
    pk.importance
  )
  WHERE pk.superseded_by IS NULL;
  GET DIAGNOSTICS v_updated_knowledge = ROW_COUNT;

  INSERT INTO memory_consolidation_log (consolidation_type, source_ids, reasoning)
  SELECT 'archive', ARRAY[kc.id], 'Decay score below 0.05, not accessed in 90+ days'
  FROM knowledge_chunks kc
  WHERE kc.decay_score < 0.05
    AND kc.last_accessed_at < NOW() - INTERVAL '90 days'
    AND kc.consolidated_into IS NULL;
  GET DIAGNOSTICS v_archived = ROW_COUNT;

  RETURN QUERY SELECT v_updated_chunks, v_updated_knowledge, v_archived;
END;
$$;


ALTER FUNCTION "public"."run_memory_decay"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."se_browse"("p_q" "text" DEFAULT NULL::"text", "p_state" "text" DEFAULT NULL::"text", "p_sort" "text" DEFAULT 'known'::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "name" "text", "abn" "text", "sector" "text", "state" "text", "gs_id" "text", "system_count" integer, "visible_dollars" numeric, "known" integer, "has_abn" boolean, "has_sector" boolean, "has_place" boolean, "has_web" boolean, "on_graph" boolean, "entries" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH base AS (
    SELECT
      s.id, s.name, s.abn, s.sector, s.state, s.postcode, s.website, s.description,
      p.gs_id, p.system_count, p.total_dollar_flow,
      (s.abn IS NOT NULL) AS has_abn,
      (s.sector IS NOT NULL) AS has_sector,
      (s.postcode IS NOT NULL OR s.state IS NOT NULL) AS has_place,
      (s.website IS NOT NULL OR s.description IS NOT NULL) AS has_web,
      (p.gs_id IS NOT NULL) AS on_graph,
      ((s.abn IS NOT NULL)::int + (s.sector IS NOT NULL)::int
       + (s.postcode IS NOT NULL OR s.state IS NOT NULL)::int
       + (s.website IS NOT NULL OR s.description IS NOT NULL)::int
       + (p.gs_id IS NOT NULL)::int) AS known_score,
      -- One group per ABN; ABN-less rows group only with themselves.
      COALESCE(s.abn, s.id::text) AS grp
    FROM social_enterprises s
    LEFT JOIN LATERAL (
      SELECT e.gs_id, e.system_count, e.total_dollar_flow
        FROM mv_entity_power_index e
       WHERE e.abn = s.abn
       LIMIT 1
    ) p ON s.abn IS NOT NULL
  ), named AS (
    SELECT b.abn, min(g.canonical_name) AS canonical_name
      FROM base b
      JOIN gs_entities g ON g.abn = b.abn
     WHERE b.abn IS NOT NULL
     GROUP BY 1
  ), sectors AS (
    -- Flattened separately: array_agg over text[] of differing lengths is an error, and the union
    -- of a group's sectors is what a reader wants to see.
    SELECT b.grp, string_agg(DISTINCT x, ', ') AS sector
      FROM base b, LATERAL unnest(COALESCE(b.sector, ARRAY[]::text[])) AS x
     GROUP BY 1
  ), grouped AS (
    SELECT
      (array_agg(b.id ORDER BY length(b.name), b.name))[1] AS id,
      COALESCE(n.canonical_name, (array_agg(b.name ORDER BY length(b.name), b.name))[1]) AS name,
      max(b.abn) AS abn,
      sec.sector,
      CASE WHEN count(DISTINCT b.state) = 1 THEN max(b.state) ELSE NULL END AS state,
      max(b.gs_id) AS gs_id,
      max(b.system_count)::int AS system_count,
      max(b.total_dollar_flow) AS visible_dollars,
      max(b.known_score) AS known,
      bool_or(b.has_abn) AS has_abn,
      bool_or(b.has_sector) AS has_sector,
      bool_or(b.has_place) AS has_place,
      bool_or(b.has_web) AS has_web,
      bool_or(b.on_graph) AS on_graph,
      count(*)::int AS entries,
      -- Kept out of the returned row; only the filters below need them.
      bool_or(p_q IS NULL OR b.name ILIKE '%' || p_q || '%') AS name_match,
      bool_or(p_state IS NULL OR b.state = p_state) AS state_match
    FROM base b
    LEFT JOIN named n ON n.abn = b.abn
    LEFT JOIN sectors sec ON sec.grp = b.grp
    GROUP BY b.grp, n.canonical_name, sec.sector
  )
  SELECT id, name, abn, sector, state, gs_id, system_count, visible_dollars, known,
         has_abn, has_sector, has_place, has_web, on_graph, entries
    FROM grouped
   -- Matching on ANY entry in the group: searching "Ballarat Red Cross" must still find the row,
   -- even though it now displays as Australian Red Cross Society.
   WHERE name_match AND state_match
   ORDER BY
     CASE WHEN p_sort = 'known' THEN known END DESC,
     CASE WHEN p_sort = 'least' THEN known END ASC,
     CASE WHEN p_sort = 'dollars' THEN visible_dollars END DESC NULLS LAST,
     CASE WHEN p_sort = 'systems' THEN system_count END DESC NULLS LAST,
     name ASC
   LIMIT least(greatest(coalesce(p_limit, 200), 1), 500)
$$;


ALTER FUNCTION "public"."se_browse"("p_q" "text", "p_state" "text", "p_sort" "text", "p_limit" integer) OWNER TO "postgres";


