CREATE OR REPLACE FUNCTION "public"."search_all_entities"("search_term" "text", "max_results" integer DEFAULT 20) RETURNS TABLE("source" "text", "name" "text", "abn" "text", "acn" "text", "entity_type" "text", "status" "text", "state" "text", "postcode" "text", "in_civicgraph" boolean)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  (SELECT 'civicgraph'::text, e.canonical_name, e.abn, a.acn, e.entity_type, COALESCE(a.status,'Unknown')::text, e.state, e.postcode, true
   FROM gs_entities e LEFT JOIN abr_registry a ON e.abn = a.abn
   WHERE e.canonical_name ILIKE '%' || search_term || '%'
   LIMIT max_results)
  UNION ALL
  (SELECT 'abr'::text, a2.entity_name, a2.abn, a2.acn, a2.entity_type, a2.status, a2.state, a2.postcode, false
   FROM abr_registry a2
   WHERE a2.entity_name ILIKE '%' || search_term || '%'
     AND NOT EXISTS (SELECT 1 FROM gs_entities e2 WHERE e2.abn = a2.abn)
   LIMIT max_results);
END;
$$;


ALTER FUNCTION "public"."search_all_entities"("search_term" "text", "max_results" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_alma_interventions"("p_query" "text" DEFAULT NULL::"text", "p_geography" "text"[] DEFAULT NULL::"text"[], "p_type" "text" DEFAULT NULL::"text", "p_evidence_level" "text" DEFAULT NULL::"text", "p_consent_level" "text" DEFAULT 'Public Knowledge Commons'::"text", "p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "name" "text", "type" "text", "description" "text", "geography" "text", "evidence_level" "text", "consent_level" "text", "operating_organization" "text", "evidence_count" bigint, "outcome_count" bigint, "relevance_score" double precision)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    i.id,
    i.name,
    i.type,
    i.description,
    i.geography,
    i.evidence_level,
    i.consent_level,
    i.operating_organization,
    (SELECT COUNT(*) FROM alma_intervention_evidence ie WHERE ie.intervention_id = i.id) as evidence_count,
    (SELECT COUNT(*) FROM alma_intervention_outcomes io WHERE io.intervention_id = i.id) as outcome_count,
    -- Simple relevance scoring
    CASE
      WHEN p_query IS NOT NULL THEN
        ts_rank(
          to_tsvector('english', COALESCE(i.name, '') || ' ' || COALESCE(i.description, '')),
          plainto_tsquery('english', p_query)
        )
      ELSE 1.0
    END::FLOAT as relevance_score
  FROM alma_interventions i
  WHERE
    -- Consent filter (always applied)
    (i.consent_level = 'Public Knowledge Commons' OR
     (p_consent_level IN ('Community Controlled', 'Strictly Private') AND i.consent_level = 'Community Controlled') OR
     (p_consent_level = 'Strictly Private' AND i.consent_level = 'Strictly Private'))
    -- Optional filters
    AND (p_query IS NULL OR
         to_tsvector('english', COALESCE(i.name, '') || ' ' || COALESCE(i.description, ''))
         @@ plainto_tsquery('english', p_query))
    AND (p_geography IS NULL OR i.geography = ANY(p_geography))
    AND (p_type IS NULL OR i.type = p_type)
    AND (p_evidence_level IS NULL OR i.evidence_level ILIKE '%' || p_evidence_level || '%')
  ORDER BY relevance_score DESC, evidence_count DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."search_alma_interventions"("p_query" "text", "p_geography" "text"[], "p_type" "text", "p_evidence_level" "text", "p_consent_level" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_alma_unified"("query_text" "text", "entity_types" "text"[] DEFAULT NULL::"text"[], "jurisdictions" "text"[] DEFAULT NULL::"text"[], "limit_results" integer DEFAULT 50) RETURNS TABLE("entity_type" "text", "entity_id" "uuid", "title" "text", "description" "text", "category" "text", "jurisdiction" "text", "rank" real)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    s.entity_type,
    s.entity_id,
    s.title,
    LEFT(s.description, 500) as description,
    s.category,
    s.jurisdiction,
    (ts_rank(s.search_vector, websearch_to_tsquery('english', query_text)) * s.relevance_boost) as rank
  FROM alma_unified_search s
  WHERE
    s.search_vector @@ websearch_to_tsquery('english', query_text)
    AND (entity_types IS NULL OR s.entity_type = ANY(entity_types))
    AND (jurisdictions IS NULL OR s.jurisdiction = ANY(jurisdictions) OR s.jurisdiction IS NULL)
  ORDER BY rank DESC
  LIMIT limit_results;
END;
$$;


ALTER FUNCTION "public"."search_alma_unified"("query_text" "text", "entity_types" "text"[], "jurisdictions" "text"[], "limit_results" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_entities_fuzzy"("search_name" "text", "min_similarity" double precision DEFAULT 0.3, "max_results" integer DEFAULT 5) RETURNS TABLE("id" "uuid", "canonical_name" "text", "abn" "text", "entity_type" "text", "similarity" double precision)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  SELECT
    e.id,
    e.canonical_name,
    e.abn,
    e.entity_type,
    similarity(e.canonical_name, search_name)::float AS similarity
  FROM gs_entities e
  WHERE similarity(e.canonical_name, search_name) >= min_similarity
  ORDER BY similarity(e.canonical_name, search_name) DESC
  LIMIT max_results;
$$;


ALTER FUNCTION "public"."search_entities_fuzzy"("search_name" "text", "min_similarity" double precision, "max_results" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_entities_prefix_fast"("search_term" "text", "max_results" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "gs_id" "text", "canonical_name" "text", "entity_type" "text", "abn" "text", "state" "text", "source_count" integer, "latest_revenue" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  q text;
  capped int;
BEGIN
  q := lower(
    replace(
      replace(
        btrim(regexp_replace(coalesce(search_term, ''), '\s+', ' ', 'g')),
        '%',
        ''
      ),
      '_',
      ''
    )
  );
  capped := least(greatest(coalesce(max_results, 10), 1), 50);

  IF length(q) < 2 THEN
    RETURN;
  END IF;

  -- Dynamic SQL lets Postgres plan the LIKE prefix as a constant and use the
  -- lower(canonical_name) text_pattern_ops index.
  RETURN QUERY EXECUTE format(
    'SELECT e.id, e.gs_id, e.canonical_name, e.entity_type, e.abn, e.state, e.source_count, e.latest_revenue
     FROM public.gs_entities e
     WHERE lower(e.canonical_name) LIKE %L
     ORDER BY e.source_count DESC NULLS LAST, e.latest_revenue DESC NULLS LAST, e.canonical_name ASC
     LIMIT %s',
    q || '%',
    capped
  );
END;
$$;


ALTER FUNCTION "public"."search_entities_prefix_fast"("search_term" "text", "max_results" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_entities_semantic"("query_embedding" "extensions"."vector", "match_threshold" double precision DEFAULT 0.5, "match_count" integer DEFAULT 20) RETURNS TABLE("gs_id" "text", "canonical_name" "text", "entity_type" "text", "abn" "text", "state" "text", "sector" "text", "remoteness" "text", "lga_name" "text", "source_count" integer, "latest_revenue" numeric, "similarity" double precision)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  SELECT
    e.gs_id,
    e.canonical_name,
    e.entity_type,
    e.abn,
    e.state,
    e.sector,
    e.remoteness,
    e.lga_name,
    e.source_count,
    e.latest_revenue,
    1 - (e.embedding <=> query_embedding) AS similarity
  FROM gs_entities e
  WHERE e.embedding IS NOT NULL
    AND 1 - (e.embedding <=> query_embedding) > match_threshold
  ORDER BY e.embedding <=> query_embedding
  LIMIT match_count;
$$;


ALTER FUNCTION "public"."search_entities_semantic"("query_embedding" "extensions"."vector", "match_threshold" double precision, "match_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_episodes"("query_embedding" "extensions"."vector", "p_project_code" "text" DEFAULT NULL::"text", "p_episode_types" "text"[] DEFAULT NULL::"text"[], "match_threshold" double precision DEFAULT 0.6, "match_count" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "title" "text", "summary" "text", "episode_type" "text", "project_code" "text", "started_at" timestamp with time zone, "status" "text", "similarity" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT me.id, me.title, me.summary, me.episode_type,
         me.project_code, me.started_at, me.status,
         (1 - (me.embedding <=> query_embedding))::FLOAT as similarity
  FROM memory_episodes me
  WHERE me.embedding IS NOT NULL
    AND 1 - (me.embedding <=> query_embedding) > match_threshold
    AND (p_project_code IS NULL OR me.project_code = p_project_code)
    AND (p_episode_types IS NULL OR me.episode_type = ANY(p_episode_types))
  ORDER BY me.embedding <=> query_embedding
  LIMIT match_count;
END;
$$;


ALTER FUNCTION "public"."search_episodes"("query_embedding" "extensions"."vector", "p_project_code" "text", "p_episode_types" "text"[], "match_threshold" double precision, "match_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_foundations_semantic"("query_embedding" "extensions"."vector", "match_threshold" double precision DEFAULT 0.5, "match_count" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "name" "text", "acnc_abn" "text", "type" "text", "total_giving_annual" numeric, "thematic_focus" "text"[], "geographic_focus" "text"[], "description" "text", "similarity" double precision)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  SELECT
    f.id,
    f.name,
    f.acnc_abn,
    f.type,
    f.total_giving_annual,
    f.thematic_focus,
    f.geographic_focus,
    f.description,
    1 - (f.embedding <=> query_embedding) AS similarity
  FROM foundations f
  WHERE f.embedding IS NOT NULL
    AND 1 - (f.embedding <=> query_embedding) > match_threshold
  ORDER BY f.embedding <=> query_embedding
  LIMIT match_count;
$$;


ALTER FUNCTION "public"."search_foundations_semantic"("query_embedding" "extensions"."vector", "match_threshold" double precision, "match_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_grants_semantic"("query_embedding" "extensions"."vector", "match_threshold" double precision DEFAULT 0.7, "match_count" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "name" "text", "provider" "text", "description" "text", "amount_min" numeric, "amount_max" numeric, "closes_at" timestamp with time zone, "url" "text", "categories" "text"[], "grant_type" "text", "similarity" double precision)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
  SELECT id, name, provider, description,
    amount_min, amount_max, closes_at, url, categories, grant_type,
    1 - (embedding <=> query_embedding) as similarity
  FROM grant_opportunities
  WHERE embedding IS NOT NULL
    AND grant_type != 'historical_award'
    AND status NOT IN ('closed', 'expired')
    AND 1 - (embedding <=> query_embedding) > match_threshold
  ORDER BY embedding <=> query_embedding
  LIMIT match_count;
$$;


ALTER FUNCTION "public"."search_grants_semantic"("query_embedding" "extensions"."vector", "match_threshold" double precision, "match_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_interventions_unified"("p_search_query" "text", "p_geography" "text"[] DEFAULT NULL::"text"[], "p_consent_level" "text" DEFAULT NULL::"text", "p_min_evidence_level" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "name" "text", "description" "text", "operating_organization" "text", "geography" "text"[], "evidence_level" "text", "source" "text", "relevance_rank" real)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    i.id,
    i.name,
    i.description,
    i.operating_organization,
    i.geography,
    i.evidence_level,
    i.source,
    ts_rank(i.search_vector, websearch_to_tsquery('english', p_search_query)) AS relevance_rank
  FROM alma_interventions_unified i,
       LATERAL (
         SELECT setweight(to_tsvector('english', COALESCE(i.name, '')), 'A') ||
                setweight(to_tsvector('english', COALESCE(i.description, '')), 'B')
       ) AS search_vector(search_vector)
  WHERE
    (p_search_query IS NULL OR search_vector.search_vector @@ websearch_to_tsquery('english', p_search_query))
    AND (p_geography IS NULL OR i.geography && p_geography)
    AND (p_consent_level IS NULL OR i.consent_level = p_consent_level)
    AND (p_min_evidence_level IS NULL OR i.evidence_level >= p_min_evidence_level)
  ORDER BY relevance_rank DESC;
END;
$$;


ALTER FUNCTION "public"."search_interventions_unified"("p_search_query" "text", "p_geography" "text"[], "p_consent_level" "text", "p_min_evidence_level" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_interventions_unified"("p_search_query" "text", "p_geography" "text"[], "p_consent_level" "text", "p_min_evidence_level" "text") IS 'Search across both ALMA interventions and legacy community programs';



CREATE OR REPLACE FUNCTION "public"."search_knowledge"("query_embedding" "extensions"."vector", "match_threshold" double precision DEFAULT 0.7, "match_count" integer DEFAULT 10, "filter_source_type" "text" DEFAULT NULL::"text", "filter_project_id" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "content" "text", "summary" "text", "topics" "text"[], "source_type" "text", "source_id" "text", "project_id" "text", "similarity" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        kc.id,
        kc.content,
        kc.summary,
        kc.topics,
        kc.source_type,
        kc.source_id,
        kc.project_id,
        1 - (kc.embedding <=> query_embedding) as similarity
    FROM knowledge_chunks kc
    WHERE kc.embedding IS NOT NULL
    AND 1 - (kc.embedding <=> query_embedding) > match_threshold
    AND (filter_source_type IS NULL OR kc.source_type = filter_source_type)
    AND (filter_project_id IS NULL OR kc.project_id = filter_project_id)
    ORDER BY kc.embedding <=> query_embedding
    LIMIT match_count;
END;
$$;


ALTER FUNCTION "public"."search_knowledge"("query_embedding" "extensions"."vector", "match_threshold" double precision, "match_count" integer, "filter_source_type" "text", "filter_project_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_knowledge"("query_embedding" "extensions"."vector", "match_threshold" double precision, "match_count" integer, "filter_source_type" "text", "filter_project_id" "text") IS 'Semantic search over knowledge chunks using vector similarity';



CREATE OR REPLACE FUNCTION "public"."search_media"("p_search_query" "text" DEFAULT NULL::"text", "p_file_type" "text" DEFAULT NULL::"text", "p_project_slug" "text" DEFAULT NULL::"text", "p_tag" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "file_url" "text", "thumbnail_url" "text", "file_type" "text", "title" "text", "description" "text", "alt_text" "text", "manual_tags" "text"[], "impact_themes" "text"[], "project_slugs" "text"[], "created_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    m.id,
    m.file_url,
    m.thumbnail_url,
    m.file_type,
    m.title,
    m.description,
    m.alt_text,
    m.manual_tags,
    m.impact_themes,
    m.project_slugs,
    m.created_at
  FROM media_items m
  WHERE
    (p_search_query IS NULL OR
     to_tsvector('english', COALESCE(m.title, '') || ' ' || COALESCE(m.description, ''))
     @@ plainto_tsquery('english', p_search_query))
    AND (p_file_type IS NULL OR m.file_type = p_file_type)
    AND (p_project_slug IS NULL OR p_project_slug = ANY(m.project_slugs))
    AND (p_tag IS NULL OR p_tag = ANY(m.manual_tags) OR p_tag = ANY(m.impact_themes))
  ORDER BY m.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


