CREATE OR REPLACE FUNCTION "public"."search_org_knowledge"("query_embedding" "extensions"."vector", "p_org_profile_id" "uuid", "match_threshold" double precision DEFAULT 0.6, "match_count" integer DEFAULT 10) RETURNS TABLE("id" "uuid", "content" "text", "summary" "text", "topics" "text"[], "source_type" "text", "source_id" "text", "similarity" double precision)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    kc.id,
    kc.content,
    kc.summary,
    kc.topics,
    kc.source_type,
    kc.source_id,
    1 - (kc.embedding <=> query_embedding) AS similarity
  FROM knowledge_chunks kc
  WHERE kc.org_profile_id = p_org_profile_id
    AND kc.embedding IS NOT NULL
    AND 1 - (kc.embedding <=> query_embedding) > match_threshold
  ORDER BY kc.embedding <=> query_embedding
  LIMIT match_count;
END;
$$;


