CREATE OR REPLACE FUNCTION "public"."snapshot_alma_metrics"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  -- Intervention counts by type
  INSERT INTO alma_metrics_history (metric_name, metric_category, intervention_type, value_count)
  SELECT
    'intervention_count',
    'interventions',
    type,
    COUNT(*)
  FROM alma_interventions
  GROUP BY type;

  -- Funding totals by jurisdiction
  INSERT INTO alma_metrics_history (metric_name, metric_category, jurisdiction, value_numeric)
  SELECT
    'total_expenditure',
    'funding',
    jurisdiction,
    SUM(total_expenditure)
  FROM alma_funding_data
  GROUP BY jurisdiction;

  -- Source processing metrics
  INSERT INTO alma_metrics_history (metric_name, metric_category, source_type, value_count, value_percentage)
  SELECT
    'source_success_rate',
    'sources',
    source_type,
    COUNT(*),
    AVG(success_rate)
  FROM alma_source_registry
  GROUP BY source_type;

  -- Queue status
  INSERT INTO alma_metrics_history (metric_name, metric_category, value_count, metadata)
  SELECT
    'pending_links',
    'processing',
    COUNT(*),
    jsonb_build_object(
      'by_status', jsonb_object_agg(status, cnt)
    )
  FROM (
    SELECT status, COUNT(*) as cnt
    FROM alma_discovered_links
    GROUP BY status
  ) s;
END;
$$;


ALTER FUNCTION "public"."snapshot_alma_metrics"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."snapshot_data_catalog"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  rec record;
  snap_at timestamptz := now();
  inserted_count integer := 0;
  row_total bigint;
  freshness numeric(12,2);
  provenance_pct numeric(6,2);
  confidence_pct numeric(6,2);
BEGIN
  FOR rec IN
    SELECT table_name, freshness_key, provenance_field, confidence_field
    FROM data_catalog
    WHERE active = true
  LOOP
    row_total := 0;
    freshness := NULL;
    provenance_pct := NULL;
    confidence_pct := NULL;

    BEGIN
      SELECT COALESCE(
        NULLIF(c.reltuples::bigint, 0),
        NULLIF(s.n_live_tup::bigint, 0),
        0
      )
      INTO row_total
      FROM pg_class c
      LEFT JOIN pg_stat_user_tables s
        ON s.schemaname = 'public'
       AND s.relname = c.relname
      WHERE c.relnamespace = 'public'::regnamespace
        AND c.relkind = 'r'
        AND c.relname = rec.table_name;

      row_total := COALESCE(row_total, 0);
    EXCEPTION WHEN OTHERS THEN
      row_total := 0;
    END;

    IF row_total <= 250000 AND rec.freshness_key IS NOT NULL AND btrim(rec.freshness_key) <> '' THEN
      BEGIN
        EXECUTE format(
          'SELECT CASE WHEN COUNT(*) = 0 THEN NULL ELSE ROUND(EXTRACT(EPOCH FROM (now() - MAX(%I))) / 3600.0, 2) END FROM %I',
          rec.freshness_key,
          rec.table_name
        ) INTO freshness;
      EXCEPTION WHEN OTHERS THEN
        freshness := NULL;
      END;
    END IF;

    IF row_total <= 250000 AND rec.provenance_field IS NOT NULL AND btrim(rec.provenance_field) <> '' THEN
      BEGIN
        EXECUTE format(
          'SELECT CASE WHEN COUNT(*) = 0 THEN NULL ELSE ROUND(100.0 * COUNT(*) FILTER (WHERE %I IS NOT NULL AND btrim(%I::text) <> '''') / COUNT(*), 2) END FROM %I',
          rec.provenance_field,
          rec.provenance_field,
          rec.table_name
        ) INTO provenance_pct;
      EXCEPTION WHEN OTHERS THEN
        provenance_pct := NULL;
      END;
    END IF;

    IF row_total <= 250000 AND rec.confidence_field IS NOT NULL AND btrim(rec.confidence_field) <> '' THEN
      BEGIN
        EXECUTE format(
          'SELECT CASE WHEN COUNT(*) = 0 THEN NULL ELSE ROUND(100.0 * COUNT(*) FILTER (WHERE %I IS NOT NULL AND btrim(%I::text) <> '''') / COUNT(*), 2) END FROM %I',
          rec.confidence_field,
          rec.confidence_field,
          rec.table_name
        ) INTO confidence_pct;
      EXCEPTION WHEN OTHERS THEN
        confidence_pct := NULL;
      END;
    END IF;

    INSERT INTO data_catalog_snapshots (
      snapshot_at,
      table_name,
      row_count,
      freshness_hours,
      provenance_coverage_pct,
      confidence_coverage_pct
    )
    VALUES (
      snap_at,
      rec.table_name,
      row_total,
      freshness,
      provenance_pct,
      confidence_pct
    );

    inserted_count := inserted_count + 1;
  END LOOP;

  RETURN inserted_count;
END;
$$;


ALTER FUNCTION "public"."snapshot_data_catalog"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spawn_sub_task"("p_parent_id" "uuid", "p_parent_agent" "text", "p_target_agent" "text", "p_action_name" "text", "p_params" "jsonb", "p_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_sub_task_id UUID;
  v_title TEXT;
BEGIN
  -- Build title
  v_title := 'Sub-task: ' || p_action_name || ' (delegated by ' || p_parent_agent || ')';

  -- Create the sub-task proposal
  INSERT INTO agent_proposals (
    agent_id,
    target_agent_id,
    action_name,
    title,
    description,
    reasoning,
    proposed_action,
    parent_proposal_id,
    coordination_status,
    coordination_context,
    status,
    priority
  ) VALUES (
    p_target_agent,
    p_target_agent,
    p_action_name,
    v_title,
    'Delegated sub-task from ' || p_parent_agent,
    jsonb_build_object(
      'trigger', 'delegated_from_' || p_parent_agent,
      'parent_proposal', p_parent_id,
      'confidence', 0.9
    ),
    p_params,
    p_parent_id,
    'waiting',
    p_context,
    'pending',
    'normal'
  )
  RETURNING id INTO v_sub_task_id;

  -- Update parent with child reference
  UPDATE agent_proposals
  SET
    child_proposal_ids = array_append(child_proposal_ids, v_sub_task_id),
    coordination_status = 'coordinating',
    updated_at = NOW()
  WHERE id = p_parent_id;

  RETURN v_sub_task_id;
END;
$$;


