CREATE OR REPLACE FUNCTION "public"."start_ralph_task"("p_task_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_prd_id UUID;
  v_iteration INTEGER;
  v_run_id UUID;
BEGIN
  SELECT t.prd_id INTO v_prd_id FROM ralph_tasks t WHERE t.id = p_task_id;
  SELECT p.current_iteration + 1 INTO v_iteration FROM ralph_prds p WHERE p.id = v_prd_id;
  UPDATE ralph_tasks SET status = 'in_progress', attempts = attempts + 1, started_at = NOW(), updated_at = NOW() WHERE id = p_task_id;
  UPDATE ralph_prds SET current_iteration = v_iteration, last_run_at = NOW(), updated_at = NOW() WHERE id = v_prd_id;
  INSERT INTO ralph_runs (prd_id, task_id, iteration, status) VALUES (v_prd_id, p_task_id, v_iteration, 'running') RETURNING id INTO v_run_id;
  RETURN v_run_id;
END;
$$;


ALTER FUNCTION "public"."start_ralph_task"("p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."state_foundation_flows"("state_code" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    AS $$
  WITH state_abns AS (
    SELECT DISTINCT abn FROM organizations
    WHERE state = upper(state_code) AND abn IS NOT NULL AND archived <> true
  ),
  grants AS (
    SELECT fg.grant_amount, fg.foundation_name, fg.yj_relevant
    FROM foundation_grantees fg
    JOIN state_abns sa ON sa.abn = fg.grantee_abn
    WHERE fg.grant_amount IS NOT NULL
  ),
  agg AS (
    SELECT
      COALESCE(SUM(grant_amount), 0) AS total_dollars,
      COUNT(*) AS grant_count,
      COALESCE(SUM(grant_amount) FILTER (WHERE yj_relevant = true), 0) AS yj_dollars,
      COUNT(*) FILTER (WHERE yj_relevant = true) AS yj_grant_count
    FROM grants
  ),
  funders AS (
    SELECT foundation_name, SUM(grant_amount) AS funder_total
    FROM grants
    WHERE foundation_name IS NOT NULL
    GROUP BY foundation_name
    ORDER BY funder_total DESC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'total_dollars', agg.total_dollars,
    'grant_count', agg.grant_count,
    'yj_dollars', agg.yj_dollars,
    'yj_grant_count', agg.yj_grant_count,
    'top_funders', COALESCE(
      (SELECT jsonb_agg(jsonb_build_object('name', foundation_name, 'total', funder_total))
       FROM funders),
      '[]'::jsonb
    )
  )
  FROM agg;
$$;


ALTER FUNCTION "public"."state_foundation_flows"("state_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_linkedin_contacts_from_imports"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $_$
      DECLARE
        rec RECORD;
        contact_id BIGINT;
        inserted_count INTEGER := 0;
      BEGIN
        FOR rec IN 
          SELECT DISTINCT
            payload->>'First Name' as first_name,
            payload->>'Last Name' as last_name,
            payload->>'URL' as linkedin_url,
            payload->>'Email Address' as email_address,
            payload->>'Position' as current_position,
            payload->>'Company' as current_company,
            CASE 
              WHEN payload->>'Connected On' ~ '^[0-9]{2} [A-Za-z]{3} [0-9]{4}$' THEN (payload->>'Connected On')::DATE
              ELSE NULL
            END as connected_on,
            owner as connection_source,
            ARRAY_AGG(id) as import_ids
          FROM linkedin_imports 
          WHERE type = 'connections'
            AND payload->>'First Name' IS NOT NULL 
            AND payload->>'Last Name' IS NOT NULL
          GROUP BY 
            payload->>'First Name',
            payload->>'Last Name', 
            payload->>'URL',
            payload->>'Email Address',
            payload->>'Position',
            payload->>'Company',
            payload->>'Connected On',
            owner
        LOOP
          INSERT INTO linkedin_contacts (
            first_name, last_name, linkedin_url, email_address,
            current_position, current_company, connected_on, 
            connection_source, raw_import_ids
          ) VALUES (
            rec.first_name, rec.last_name, rec.linkedin_url, rec.email_address,
            rec.current_position, rec.current_company, rec.connected_on,
            rec.connection_source, rec.import_ids
          )
          ON CONFLICT (linkedin_url) DO UPDATE SET
            email_address = COALESCE(EXCLUDED.email_address, linkedin_contacts.email_address),
            current_position = COALESCE(EXCLUDED.current_position, linkedin_contacts.current_position),
            current_company = COALESCE(EXCLUDED.current_company, linkedin_contacts.current_company),
            connection_source = CASE 
              WHEN linkedin_contacts.connection_source != EXCLUDED.connection_source 
              THEN 'both' 
              ELSE linkedin_contacts.connection_source 
            END,
            raw_import_ids = linkedin_contacts.raw_import_ids || EXCLUDED.raw_import_ids,
            updated_at = now();
            
          inserted_count := inserted_count + 1;
        END LOOP;
        
        RETURN inserted_count;
      END;
      $_$;


ALTER FUNCTION "public"."sync_linkedin_contacts_from_imports"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_program_intervention_links"() RETURNS TABLE("new_links_created" integer, "programs_with_links" integer, "interventions_linked" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
  v_inserted int;
BEGIN
  -- Insert all discoverable program→intervention links
  WITH funding_matches AS (
    SELECT DISTINCT
      p.id as program_id,
      i.id as intervention_id,
      'funding: ' || o.name as note
    FROM alma_government_programs p
    JOIN justice_funding jf ON jf.program_name ILIKE '%' || LEFT(p.name, 30) || '%'
    JOIN organizations o ON o.id = jf.alma_organization_id
    JOIN alma_interventions i ON i.operating_organization_id = o.id
      AND i.verification_status != 'ai_generated'
    WHERE p.name IS NOT NULL AND LENGTH(p.name) > 5
      AND jf.alma_organization_id IS NOT NULL
  ),
  abn_matches AS (
    SELECT DISTINCT
      p.id as program_id,
      i.id as intervention_id,
      'ABN bridge: ' || jf.recipient_abn as note
    FROM alma_government_programs p
    JOIN justice_funding jf ON jf.program_name ILIKE '%' || LEFT(p.name, 25) || '%'
    JOIN organizations o ON o.abn = jf.recipient_abn
    JOIN alma_interventions i ON i.operating_organization_id = o.id
      AND i.verification_status != 'ai_generated'
    WHERE p.name IS NOT NULL AND LENGTH(p.name) > 5
      AND jf.recipient_abn IS NOT NULL
  ),
  gs_matches AS (
    SELECT DISTINCT
      p.id as program_id,
      i.id as intervention_id,
      'GS contract: ' || contractor.canonical_name as note
    FROM alma_government_programs p
    JOIN gs_entities dept ON dept.canonical_name ILIKE '%' || LEFT(p.department, 30) || '%'
      AND dept.entity_type IN ('government', 'government_body')
    JOIN gs_relationships gr ON gr.source_entity_id = dept.id OR gr.target_entity_id = dept.id
    JOIN gs_entities contractor ON contractor.id = CASE
      WHEN gr.source_entity_id = dept.id THEN gr.target_entity_id
      ELSE gr.source_entity_id
    END
    JOIN organizations o ON o.gs_entity_id = contractor.id
    JOIN alma_interventions i ON i.operating_organization_id = o.id
      AND i.verification_status != 'ai_generated'
    WHERE p.department IS NOT NULL AND LENGTH(p.department) > 5
  ),
  name_matches AS (
    SELECT DISTINCT
      p.id as program_id,
      i.id as intervention_id,
      'name match' as note
    FROM alma_government_programs p
    JOIN alma_interventions i ON i.name ILIKE '%' || p.name || '%'
      AND i.verification_status != 'ai_generated'
    WHERE p.name IS NOT NULL AND LENGTH(p.name) > 5
  ),
  all_links AS (
    SELECT program_id, intervention_id, note FROM funding_matches
    UNION
    SELECT program_id, intervention_id, note FROM abn_matches
    UNION
    SELECT program_id, intervention_id, note FROM gs_matches
    UNION
    SELECT program_id, intervention_id, note FROM name_matches
  ),
  new_links AS (
    SELECT al.program_id, al.intervention_id, LEFT(al.note, 500) as note
    FROM all_links al
    LEFT JOIN alma_program_interventions api
      ON api.program_id = al.program_id AND api.intervention_id = al.intervention_id
    WHERE api.id IS NULL
  ),
  inserted AS (
    INSERT INTO alma_program_interventions (program_id, intervention_id, relationship, notes)
    SELECT program_id, intervention_id, 'implements', note
    FROM new_links
    ON CONFLICT DO NOTHING
    RETURNING id
  )
  SELECT COUNT(*) INTO v_inserted FROM inserted;

  -- Also bulk-link orgs to GS entities via ABN
  UPDATE organizations o
  SET gs_entity_id = ge.id
  FROM gs_entities ge
  WHERE o.gs_entity_id IS NULL
    AND o.abn IS NOT NULL
    AND ge.abn = REPLACE(o.abn, ' ', '')
    AND LENGTH(REPLACE(o.abn, ' ', '')) >= 9;

  RETURN QUERY
  SELECT
    v_inserted,
    (SELECT COUNT(DISTINCT program_id)::int FROM alma_program_interventions),
    (SELECT COUNT(DISTINCT intervention_id)::int FROM alma_program_interventions);
END;
$$;


ALTER FUNCTION "public"."sync_program_intervention_links"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_program_intervention_links"() IS 'Auto-links government programs to interventions via funding recipients, ABN bridge, GS contracts, and name matching. Also bulk-links orgs to GS entities via ABN. Safe to run repeatedly — only inserts new links.';



CREATE OR REPLACE FUNCTION "public"."system_org_funding_by_fy"("org_ids" "uuid"[], "fys" "text"[]) RETURNS TABLE("alma_organization_id" "uuid", "financial_year" "text", "total" numeric)
    LANGUAGE "sql" STABLE
    AS $$
  select
    f.alma_organization_id,
    f.financial_year,
    sum(f.amount_dollars)::numeric as total
  from public.justice_funding f
  where f.alma_organization_id = any(org_ids)
    and f.financial_year = any(fys)
  group by f.alma_organization_id, f.financial_year
$$;


