CREATE OR REPLACE FUNCTION "public"."wiki_hybrid_search"("query_text" "text", "query_embedding" "extensions"."vector", "match_count" integer DEFAULT 15, "rrf_k" integer DEFAULT 60) RETURNS TABLE("article_path" "text", "title" "text", "section_id" "text", "snippet" "text", "fts_rank" double precision, "vec_score" double precision, "rrf_score" double precision)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
WITH fts_results AS (
  SELECT w.article_path, w.title, w.section_id, w.body,
         ts_rank_cd(w.fts, websearch_to_tsquery('english', query_text))::FLOAT as rank,
         ROW_NUMBER() OVER (ORDER BY ts_rank_cd(w.fts, websearch_to_tsquery('english', query_text)) DESC) as rn
  FROM wiki_search_index w
  WHERE w.fts @@ websearch_to_tsquery('english', query_text)
  ORDER BY rank DESC LIMIT 30
),
vec_results AS (
  SELECT w.article_path, w.title, w.section_id, w.body,
         (1 - (w.embedding <=> query_embedding))::FLOAT as score,
         ROW_NUMBER() OVER (ORDER BY w.embedding <=> query_embedding) as rn
  FROM wiki_search_index w
  WHERE w.embedding IS NOT NULL
  ORDER BY w.embedding <=> query_embedding LIMIT 30
),
combined AS (
  SELECT
    COALESCE(f.article_path, v.article_path) as article_path,
    COALESCE(f.title, v.title) as title,
    COALESCE(f.section_id, v.section_id) as section_id,
    COALESCE(f.body, v.body) as body,
    COALESCE(f.rank, 0) as fts_rank,
    COALESCE(v.score, 0) as vec_score,
    COALESCE(1.0 / (rrf_k + f.rn), 0) + COALESCE(1.0 / (rrf_k + v.rn), 0) as rrf_score
  FROM fts_results f
  FULL OUTER JOIN vec_results v ON f.article_path = v.article_path
)
SELECT c.article_path, c.title, c.section_id,
       ts_headline('english', c.body, websearch_to_tsquery('english', query_text),
         'MaxWords=35, MinWords=15, StartSel=**, StopSel=**') as snippet,
       c.fts_rank, c.vec_score, c.rrf_score
FROM combined c
ORDER BY c.rrf_score DESC
LIMIT match_count;
$$;


ALTER FUNCTION "public"."wiki_hybrid_search"("query_text" "text", "query_embedding" "extensions"."vector", "match_count" integer, "rrf_k" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wiki_page_create_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  -- Only create version if content actually changed
  IF (OLD.content IS DISTINCT FROM NEW.content) OR
     (OLD.title IS DISTINCT FROM NEW.title) OR
     (OLD.excerpt IS DISTINCT FROM NEW.excerpt) THEN

    -- Increment version number
    NEW.version := OLD.version + 1;

    -- Save old version to history
    INSERT INTO wiki_page_versions (page_id, version, title, content, excerpt, changed_by)
    VALUES (OLD.id, OLD.version, OLD.title, OLD.content, OLD.excerpt, NEW.updated_by);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."wiki_page_create_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wiki_pages_review_due_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.last_reviewed_at IS NOT NULL AND NEW.review_frequency_days IS NOT NULL THEN
    NEW.next_review_due := NEW.last_reviewed_at + (NEW.review_frequency_days || ' days')::INTERVAL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."wiki_pages_review_due_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wiki_pages_search_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  NEW.search_vector :=
    setweight(to_tsvector('english', COALESCE(NEW.title, '')), 'A') ||
    setweight(to_tsvector('english', COALESCE(NEW.excerpt, '')), 'B') ||
    setweight(to_tsvector('english', COALESCE(NEW.content, '')), 'C') ||
    setweight(to_tsvector('english', COALESCE(array_to_string(NEW.tags, ' '), '')), 'D');
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."wiki_pages_search_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wiki_search_index_fts_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions', 'pg_catalog'
    AS $$
BEGIN
  NEW.fts :=
    setweight(to_tsvector('english', coalesce(NEW.title, '')), 'A') ||
    setweight(to_tsvector('english', coalesce(array_to_string(NEW.aliases, ' '), '')), 'A') ||
    setweight(to_tsvector('english', coalesce(array_to_string(NEW.tags, ' '), '')), 'B') ||
    setweight(to_tsvector('english', coalesce(NEW.body, '')), 'C');
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."wiki_search_index_fts_trigger"() OWNER TO "postgres";


