COMMENT ON TABLE "public"."alma_funding_opportunities" IS 'Funding opportunities from government, philanthropy, corporate, and community sources';



COMMENT ON COLUMN "public"."alma_funding_opportunities"."opportunity_type" IS 'What is this row really? Only open_grant flows through act_grant_recommendations.';



COMMENT ON COLUMN "public"."alma_funding_opportunities"."verification_status" IS 'Has the program-level URL been confirmed live with current round? verified | placeholder | stale | unverified.';



CREATE OR REPLACE VIEW "public"."act_funding_opportunity_current_status" AS
 WITH "assessed" AS (
         SELECT "opportunity"."id" AS "opportunity_id",
            "opportunity"."verification_status",
            "opportunity"."verified_at",
            "opportunity"."deadline",
            "opportunity"."source_url",
            "opportunity"."application_url",
            (("opportunity"."verified_at" IS NOT NULL) AND ("opportunity"."verified_at" < ("now"() - '7 days'::interval))) AS "is_stale",
            (("opportunity"."verified_at" IS NOT NULL) AND ("opportunity"."verified_at" < ("now"() - '21 days'::interval))) AS "is_very_stale",
                CASE
                    WHEN ("opportunity"."verified_at" IS NULL) THEN NULL::integer
                    ELSE (EXTRACT(day FROM ("now"() - "opportunity"."verified_at")))::integer
                END AS "days_since_verified",
            "array_remove"(ARRAY[
                CASE
                    WHEN ("opportunity"."verification_status" IS DISTINCT FROM 'verified'::"text") THEN 'not_verified'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN ("opportunity"."verified_at" IS NULL) THEN 'missing_verification_timestamp'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN (NULLIF("btrim"("opportunity"."source_url"), ''::"text") IS NULL) THEN 'missing_official_source'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN (NULLIF("btrim"("opportunity"."application_url"), ''::"text") IS NULL) THEN 'missing_application_url'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN ("opportunity"."deadline" < "now"()) THEN 'past_deadline'::"text"
                    ELSE NULL::"text"
                END], NULL::"text") AS "hard_failures"
           FROM "public"."alma_funding_opportunities" "opportunity"
          WHERE ("opportunity"."opportunity_type" = 'open_grant'::"text")
        )
 SELECT "opportunity_id",
        CASE
            WHEN ("cardinality"("hard_failures") > 0) THEN 'quarantined'::"text"
            WHEN "is_very_stale" THEN 'quarantined'::"text"
            WHEN "is_stale" THEN 'stale_warning'::"text"
            WHEN ("deadline" IS NULL) THEN 'rolling'::"text"
            ELSE 'apply_now'::"text"
        END AS "feed_status",
        CASE
            WHEN ("cardinality"("hard_failures") > 0) THEN "hard_failures"
            WHEN "is_very_stale" THEN ARRAY['stale_verification'::"text"]
            ELSE '{}'::"text"[]
        END AS "failed_requirements",
    (GREATEST((0)::numeric, "round"(((((6 - "cardinality"(
        CASE
            WHEN ("cardinality"("hard_failures") > 0) THEN "hard_failures"
            WHEN "is_very_stale" THEN ARRAY['stale_verification'::"text"]
            ELSE '{}'::"text"[]
        END)))::numeric / (6)::numeric) * (100)::numeric))))::integer AS "evidence_completeness",
    "verification_status",
    "verified_at",
    "deadline",
    "source_url",
    "application_url",
    "days_since_verified",
    "is_stale"
   FROM "assessed";


ALTER VIEW "public"."act_funding_opportunity_current_status" OWNER TO "postgres";


COMMENT ON VIEW "public"."act_funding_opportunity_current_status" IS 'Evidence-backed current-status contract. Only apply_now rows may appear in current project funding feeds.';



CREATE TABLE IF NOT EXISTS "public"."act_grant_recommendation_decisions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "project_code" "text" NOT NULL,
    "opportunity_id" "uuid" NOT NULL,
    "decision" "text" NOT NULL,
    "decided_by" "uuid",
    "decided_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "notes" "text",
    "notion_page_id" "text",
    "ghl_opportunity_id" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "grant_opportunity_id" "uuid",
    "decision_scope" "text" DEFAULT 'operational'::"text" NOT NULL,
    "decision_origin" "text" DEFAULT 'legacy'::"text" NOT NULL,
    CONSTRAINT "act_grant_recommendation_decisions_decision_check" CHECK (("decision" = ANY (ARRAY['discovered'::"text", 'pursuing'::"text", 'watching'::"text", 'passed'::"text", 'applied'::"text", 'submitted'::"text", 'won'::"text", 'lost'::"text"]))),
    CONSTRAINT "act_grant_recommendation_decisions_origin_check" CHECK (("decision_origin" = ANY (ARRAY['legacy'::"text", 'grantscope_pursue'::"text", 'manual_admin'::"text", 'notion_sync'::"text", 'ghl_callback'::"text", 'xero_invoices'::"text"]))),
    CONSTRAINT "act_grant_recommendation_decisions_scope_check" CHECK (("decision_scope" = ANY (ARRAY['operational'::"text", 'historical_evidence'::"text"])))
);


ALTER TABLE "public"."act_grant_recommendation_decisions" OWNER TO "postgres";


COMMENT ON TABLE "public"."act_grant_recommendation_decisions" IS 'Admin decisions on ACT grant recommendations. One row per (project, opportunity). UI writes; Notion sync (P7) reads.';



COMMENT ON COLUMN "public"."act_grant_recommendation_decisions"."grant_opportunity_id" IS 'Mirrored grant_opportunities row used by /tracker. Populated when decision becomes pursuing/applied/submitted.';



COMMENT ON COLUMN "public"."act_grant_recommendation_decisions"."decision_scope" IS 'operational rows may drive GHL/Notion; historical_evidence rows only contribute funding history and proof.';



COMMENT ON COLUMN "public"."act_grant_recommendation_decisions"."decision_origin" IS 'System that created the decision row. Used for provenance and safe downstream routing.';



CREATE TABLE IF NOT EXISTS "public"."act_grant_recommendation_projects" (
    "project_code" "text" NOT NULL,
    "theme_keywords" "text"[] NOT NULL,
    "home_states" "text"[] DEFAULT ARRAY['QLD'::"text"] NOT NULL,
    "secondary_states" "text"[] DEFAULT ARRAY['NT'::"text", 'NSW'::"text"] NOT NULL,
    "in_scope" boolean DEFAULT true NOT NULL,
    "notes" "text",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "project_label" "text",
    "layer" "text",
    "readiness" "text",
    "current_state" "text",
    "intelligence_role" "text",
    "opportunity_alignment" "text",
    "next_question" "text",
    "source_doc" "text",
    "dgr_required" boolean DEFAULT false,
    "entity_preference" "text" DEFAULT 'sole_trader_then_pty'::"text",
    "qbe_ready" boolean DEFAULT false,
    "preferred_funder_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[],
    "evidence_we_have" "jsonb" DEFAULT '{}'::"jsonb",
    "act_context" "jsonb" DEFAULT '{}'::"jsonb",
    "org_project_id" "uuid",
    "primary_funding_route" "text",
    CONSTRAINT "act_grant_recommendation_projects_primary_funding_route_check" CHECK (("primary_funding_route" = ANY (ARRAY['grants'::"text", 'buyers'::"text", 'overhead'::"text", 'earned'::"text", 'mixed'::"text"])))
);


ALTER TABLE "public"."act_grant_recommendation_projects" OWNER TO "postgres";


COMMENT ON TABLE "public"."act_grant_recommendation_projects" IS 'Per-project fit-scoring config for act_grant_recommendations MV. Edit and refresh MV to re-scope.';



COMMENT ON COLUMN "public"."act_grant_recommendation_projects"."entity_preference" IS 'sole_trader | pty_ltd | charity | sole_trader_then_pty (default during 2026-06-30 cutover)';



COMMENT ON COLUMN "public"."act_grant_recommendation_projects"."qbe_ready" IS 'TRUE if this project has gone through internal Qualify/Bid/Evaluate readiness checks';



COMMENT ON COLUMN "public"."act_grant_recommendation_projects"."preferred_funder_ids" IS 'Foundation/funder IDs ACT has existing relationship with for this project';



COMMENT ON COLUMN "public"."act_grant_recommendation_projects"."evidence_we_have" IS 'JSONB: { case_studies, datasets, partner_letters, prior_grants } — what evidence already exists';



COMMENT ON COLUMN "public"."act_grant_recommendation_projects"."act_context" IS 'Free-form JSONB for additional project context (ACT_POSITION fragments, role patterns, etc.)';



COMMENT ON COLUMN "public"."act_grant_recommendation_projects"."org_project_id" IS 'Canonical link to org_projects. project_code stays as the historical key used by act_grant_recommendation_decisions; this column is what the app should join on.';



COMMENT ON COLUMN "public"."act_grant_recommendation_projects"."primary_funding_route" IS 'How this project is actually funded. Where this is not ''grants'', an empty grant list is the expected result, not a defect — the UI says so rather than leaving the absence unexplained.';



CREATE TABLE IF NOT EXISTS "public"."funder_blocklist" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
