    CONSTRAINT "projects_tier_check" CHECK (("tier" = ANY (ARRAY['engine'::"text", 'campaign'::"text", 'community'::"text", 'art'::"text", 'ecosystem'::"text", 'studio'::"text", 'satellite'::"text", 'background'::"text"])))
);


ALTER TABLE "public"."projects" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_funder_tag_density" AS
 SELECT "funder_name",
    "count"(*) AS "opp_count",
    "round"("avg"("array_length"((COALESCE("focus_areas", '{}'::"text"[]) || COALESCE("keywords", '{}'::"text"[])), 1)), 1) AS "avg_tag_count",
        CASE
            WHEN ("avg"("array_length"((COALESCE("focus_areas", '{}'::"text"[]) || COALESCE("keywords", '{}'::"text"[])), 1)) >= (15)::numeric) THEN 0.5
            ELSE 1.0
        END AS "theme_multiplier"
   FROM "public"."alma_funding_opportunities"
  WHERE (("opportunity_type" = 'open_grant'::"text") AND ("verification_status" = 'verified'::"text") AND ("funder_name" IS NOT NULL))
  GROUP BY "funder_name";


ALTER VIEW "public"."v_funder_tag_density" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_funder_tag_density" IS 'Per-funder avg tag count. theme_multiplier=0.5 when avg_tag_count>=15 (tag-stuffers).';



CREATE MATERIALIZED VIEW "public"."act_grant_recommendations" AS
 WITH "project_themes" AS (
         SELECT "arp"."project_code",
            "p"."name" AS "project_name",
            "arp"."theme_keywords",
            "arp"."home_states",
            "arp"."secondary_states"
           FROM ("public"."act_grant_recommendation_projects" "arp"
             JOIN "public"."projects" "p" ON (("p"."code" = "arp"."project_code")))
          WHERE ("arp"."in_scope" = true)
        ), "opps" AS (
         SELECT "a"."id",
            "a"."name",
            "a"."funder_name",
            "a"."min_grant_amount",
            "a"."max_grant_amount",
            "a"."opens_at",
            "a"."deadline",
            "a"."jurisdictions",
            "a"."is_national",
            "a"."eligible_org_types",
            "a"."requires_deductible_gift_recipient",
            "a"."focus_areas",
            "a"."keywords",
            "a"."source_url",
            "a"."application_url",
            "a"."opportunity_type",
            "a"."verification_status",
            "a"."verified_at"
           FROM "public"."alma_funding_opportunities" "a"
          WHERE ((COALESCE("a"."status", 'open'::"text") <> ALL (ARRAY['archived'::"text", 'closed'::"text", 'cancelled'::"text", 'rejected'::"text"])) AND (("a"."deadline" IS NULL) OR ("a"."deadline" >= "now"())) AND ("a"."opportunity_type" = 'open_grant'::"text") AND ("a"."verification_status" = 'verified'::"text") AND (NOT (EXISTS ( SELECT 1
                   FROM "public"."funder_blocklist" "b"
                  WHERE (("b"."active" = true) AND ("lower"("b"."funder_name") = "lower"("a"."funder_name")))))))
        ), "tr_decisions" AS (
         SELECT "d"."project_code",
            "d"."opportunity_id",
            "d"."decision",
            "lower"("a"."funder_name") AS "funder_lc"
           FROM ("public"."act_grant_recommendation_decisions" "d"
             JOIN "public"."alma_funding_opportunities" "a" ON (("a"."id" = "d"."opportunity_id")))
        ), "tr_won_funders" AS (
         SELECT DISTINCT "tr_decisions"."funder_lc"
           FROM "tr_decisions"
          WHERE (("tr_decisions"."decision" = 'won'::"text") AND ("tr_decisions"."funder_lc" IS NOT NULL))
        ), "tr_passed" AS (
         SELECT "tr_decisions"."project_code",
            "tr_decisions"."funder_lc"
           FROM "tr_decisions"
          WHERE (("tr_decisions"."decision" = 'passed'::"text") AND ("tr_decisions"."funder_lc" IS NOT NULL))
          GROUP BY "tr_decisions"."project_code", "tr_decisions"."funder_lc"
         HAVING ("count"(*) >= 2)
        ), "tr_decided_opps" AS (
         SELECT DISTINCT "act_grant_recommendation_decisions"."project_code",
            "act_grant_recommendation_decisions"."opportunity_id"
           FROM "public"."act_grant_recommendation_decisions"
          WHERE ("act_grant_recommendation_decisions"."decision" = ANY (ARRAY['won'::"text", 'passed'::"text", 'pursuing'::"text"]))
        ), "scored" AS (
         SELECT "pt"."project_code",
            "pt"."project_name",
            "o"."id" AS "opportunity_id",
            "o"."name" AS "opportunity_name",
            "o"."funder_name",
            "o"."deadline",
            "o"."opens_at",
            "o"."min_grant_amount",
            "o"."max_grant_amount",
            "o"."is_national",
            "o"."jurisdictions",
            "o"."eligible_org_types",
            "o"."focus_areas",
            "o"."keywords",
            "o"."source_url",
            "o"."application_url",
            "o"."opportunity_type",
            "o"."verification_status",
            "o"."verified_at",
            (LEAST((50)::bigint, ( SELECT ("count"(DISTINCT "pk"."pk") * 10)
                   FROM "unnest"("pt"."theme_keywords") "pk"("pk")
                  WHERE (("length"("pk"."pk") >= 4) AND (EXISTS ( SELECT 1
                           FROM "unnest"((COALESCE("o"."focus_areas", '{}'::"text"[]) || COALESCE("o"."keywords", '{}'::"text"[]))) "okw"("okw")
                          WHERE (("length"("okw"."okw") >= 4) AND (("lower"("okw"."okw") ~~ (('%'::"text" || "lower"("pk"."pk")) || '%'::"text")) OR ("lower"("pk"."pk") ~~ (('%'::"text" || "lower"("okw"."okw")) || '%'::"text"))))))))))::numeric AS "theme_score_raw",
            COALESCE("tdp"."theme_multiplier", 1.0) AS "theme_multiplier",
            COALESCE("tdp"."avg_tag_count", (0)::numeric) AS "funder_avg_tags",
                CASE
                    WHEN "o"."is_national" THEN 15
                    WHEN ("o"."jurisdictions" && "pt"."home_states") THEN 15
                    WHEN ("o"."jurisdictions" && "pt"."secondary_states") THEN 9
                    ELSE 0
                END AS "geography_score",
                CASE
                    WHEN ("o"."eligible_org_types" && ARRAY['charity'::"text", 'company'::"text", 'community_organisation'::"text", 'social_enterprise'::"text", 'arts_organisation'::"text", 'collective'::"text"]) THEN 20
                    WHEN ("o"."eligible_org_types" && ARRAY['aboriginal_corporation'::"text", 'indigenous_charity'::"text", 'indigenous_org'::"text", 'community_org'::"text"]) THEN 10
                    ELSE 5
                END AS "eligibility_score",
                CASE
                    WHEN ("o"."deadline" IS NULL) THEN 8
                    WHEN ("o"."deadline" >= ("now"() + '30 days'::interval)) THEN 15
                    WHEN ("o"."deadline" >= ("now"() + '7 days'::interval)) THEN 8
                    WHEN ("o"."deadline" >= "now"()) THEN 4
                    ELSE 0
                END AS "timing_score",
                CASE
                    WHEN ("wf"."funder_lc" IS NOT NULL) THEN 15
                    ELSE 0
                END AS "won_funder_boost",
                CASE
                    WHEN ("pp"."funder_lc" IS NOT NULL) THEN '-10'::integer
                    ELSE 0
                END AS "passed_penalty",
            ("wf"."funder_lc" IS NOT NULL) AS "won_funder",
            "array_remove"(ARRAY[
                CASE
                    WHEN "o"."requires_deductible_gift_recipient" THEN 'requires_dgr'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN (("o"."eligible_org_types" && ARRAY['aboriginal_corporation'::"text", 'indigenous_charity'::"text", 'indigenous_org'::"text"]) AND (NOT ("o"."eligible_org_types" && ARRAY['charity'::"text", 'company'::"text", 'community_organisation'::"text"]))) THEN 'partner_required'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN (("o"."deadline" IS NOT NULL) AND ("o"."deadline" < ("now"() + '14 days'::interval))) THEN 'tight_deadline'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN "o"."is_national" THEN 'national'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN (("o"."max_grant_amount" IS NOT NULL) AND ("o"."max_grant_amount" >= (500000)::numeric)) THEN 'large_grant'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN (("o"."max_grant_amount" IS NOT NULL) AND ("o"."max_grant_amount" < (50000)::numeric)) THEN 'small_grant'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN (COALESCE("tdp"."theme_multiplier", 1.0) < 1.0) THEN 'tag_stuffed'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN ("wf"."funder_lc" IS NOT NULL) THEN 'won_funder'::"text"
                    ELSE NULL::"text"
                END,
                CASE
                    WHEN ("pp"."funder_lc" IS NOT NULL) THEN 'repeatedly_passed'::"text"
                    ELSE NULL::"text"
                END], NULL::"text") AS "flags"
           FROM (((("project_themes" "pt"
             CROSS JOIN "opps" "o")
             LEFT JOIN "public"."v_funder_tag_density" "tdp" ON (("tdp"."funder_name" = "o"."funder_name")))
             LEFT JOIN "tr_won_funders" "wf" ON (("wf"."funder_lc" = "lower"("o"."funder_name"))))
             LEFT JOIN "tr_passed" "pp" ON ((("pp"."funder_lc" = "lower"("o"."funder_name")) AND ("pp"."project_code" = "pt"."project_code"))))
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM "tr_decided_opps" "td"
                  WHERE (("td"."project_code" = "pt"."project_code") AND ("td"."opportunity_id" = "o"."id")))))
        )
 SELECT "project_code",
    "project_name",
    "opportunity_id",
    "opportunity_name",
    "funder_name",
    "deadline",
    "opens_at",
    "min_grant_amount",
    "max_grant_amount",
    "is_national",
    "jurisdictions",
    "eligible_org_types",
    "focus_areas",
    "keywords",
    "source_url",
    "application_url",
    "opportunity_type",
    "verification_status",
    "verified_at",
    ("round"(("theme_score_raw" * "theme_multiplier")))::integer AS "theme_score",
    "geography_score",
    "eligibility_score",
    "timing_score",
    ("won_funder_boost" + "passed_penalty") AS "track_record_score",
    "won_funder",
    (((((("round"(("theme_score_raw" * "theme_multiplier")))::integer + "geography_score") + "eligibility_score") + "timing_score") + "won_funder_boost") + "passed_penalty") AS "fit_score",
    ((("round"(("theme_score_raw" * "theme_multiplier")))::integer > 0) AND ((((((("round"(("theme_score_raw" * "theme_multiplier")))::integer + "geography_score") + "eligibility_score") + "timing_score") + "won_funder_boost") + "passed_penalty") >= 55)) AS "is_strong_fit",
    ("theme_multiplier" < 1.0) AS "tag_density_penalised",
    "funder_avg_tags",
    "flags",
    "now"() AS "computed_at"
   FROM "scored"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."act_grant_recommendations" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."act_grant_recommendations_current" WITH ("security_invoker"='true') AS
 WITH "proj" AS (
         SELECT "act_grant_recommendation_projects"."project_code",
            ARRAY( SELECT "upper"("s"."s") AS "upper"
                   FROM "unnest"((COALESCE("act_grant_recommendation_projects"."home_states", '{}'::"text"[]) || COALESCE("act_grant_recommendation_projects"."secondary_states", '{}'::"text"[]))) "s"("s")) AS "ok_states"
           FROM "public"."act_grant_recommendation_projects"
        ), "tagged" AS (
         SELECT "rec"."project_code",
            "rec"."project_name",
            "rec"."opportunity_id",
            "rec"."opportunity_name",
            "rec"."funder_name",
            "rec"."deadline",
            "rec"."opens_at",
            "rec"."min_grant_amount",
            "rec"."max_grant_amount",
            "rec"."is_national",
            "rec"."jurisdictions",
            "rec"."eligible_org_types",
            "rec"."focus_areas",
            "rec"."keywords",
            "rec"."source_url",
            "rec"."application_url",
            "rec"."opportunity_type",
            "rec"."verification_status",
            "rec"."verified_at",
            "rec"."theme_score",
            "rec"."geography_score",
            "rec"."eligibility_score",
            "rec"."timing_score",
            "rec"."track_record_score",
            "rec"."won_funder",
            "rec"."fit_score",
            "rec"."is_strong_fit",
            "rec"."tag_density_penalised",
            "rec"."funder_avg_tags",
            "rec"."flags",
            "rec"."computed_at",
            "cs"."feed_status",
            "p"."ok_states",
                CASE
                    WHEN ("rec"."funder_name" ~* '(victorian government|government of victoria)'::"text") THEN 'VIC'::"text"
                    WHEN ("rec"."funder_name" ~* '(nsw government|government of new south wales)'::"text") THEN 'NSW'::"text"
                    WHEN ("rec"."funder_name" ~* '(queensland government|qld government)'::"text") THEN 'QLD'::"text"
                    WHEN ("rec"."funder_name" ~* '(south australian government|government of south australia)'::"text") THEN 'SA'::"text"
                    WHEN ("rec"."funder_name" ~* '(western australian government|government of western australia)'::"text") THEN 'WA'::"text"
                    WHEN ("rec"."funder_name" ~* '(tasmanian government|government of tasmania)'::"text") THEN 'TAS'::"text"
                    WHEN ("rec"."funder_name" ~* '(northern territory government|nt government)'::"text") THEN 'NT'::"text"
                    ELSE NULL::"text"
                END AS "funder_state"
           FROM (("public"."act_grant_recommendations" "rec"
             JOIN "public"."act_funding_opportunity_current_status" "cs" ON (("cs"."opportunity_id" = "rec"."opportunity_id")))
             LEFT JOIN "proj" "p" ON (("p"."project_code" = "rec"."project_code")))
          WHERE (("cs"."feed_status" = ANY (ARRAY['apply_now'::"text", 'rolling'::"text", 'stale_warning'::"text"])) AND (("rec"."max_grant_amount" IS NULL) OR ("rec"."max_grant_amount" >= (5000)::numeric)))
        ), "eligible" AS (
         SELECT "tagged"."project_code",
            "tagged"."project_name",
            "tagged"."opportunity_id",
            "tagged"."opportunity_name",
            "tagged"."funder_name",
            "tagged"."deadline",
            "tagged"."opens_at",
            "tagged"."min_grant_amount",
            "tagged"."max_grant_amount",
            "tagged"."is_national",
            "tagged"."jurisdictions",
            "tagged"."eligible_org_types",
            "tagged"."focus_areas",
            "tagged"."keywords",
            "tagged"."source_url",
            "tagged"."application_url",
            "tagged"."opportunity_type",
            "tagged"."verification_status",
            "tagged"."verified_at",
            "tagged"."theme_score",
            "tagged"."geography_score",
            "tagged"."eligibility_score",
            "tagged"."timing_score",
            "tagged"."track_record_score",
            "tagged"."won_funder",
            "tagged"."fit_score",
            "tagged"."is_strong_fit",
            "tagged"."tag_density_penalised",
            "tagged"."funder_avg_tags",
            "tagged"."flags",
            "tagged"."computed_at",
            "tagged"."feed_status",
            "tagged"."ok_states",
            "tagged"."funder_state"
           FROM "tagged"
          WHERE (("tagged"."ok_states" IS NULL) OR COALESCE("tagged"."is_national", false) OR
                CASE
                    WHEN (("tagged"."jurisdictions" IS NOT NULL) AND ("cardinality"("tagged"."jurisdictions") > 0)) THEN (EXISTS ( SELECT 1
                       FROM "unnest"("tagged"."jurisdictions") "j"("j")
                      WHERE (("upper"("replace"("j"."j", 'AU-'::"text", ''::"text")) = ANY ("tagged"."ok_states")) OR ("upper"("replace"("j"."j", 'AU-'::"text", ''::"text")) = 'NATIONAL'::"text"))))
                    WHEN ("tagged"."funder_state" IS NOT NULL) THEN ("tagged"."funder_state" = ANY ("tagged"."ok_states"))
                    ELSE true
                END)
        ), "stemmed" AS (
         SELECT "eligible"."project_code",
            "eligible"."project_name",
            "eligible"."opportunity_id",
            "eligible"."opportunity_name",
            "eligible"."funder_name",
            "eligible"."deadline",
            "eligible"."opens_at",
            "eligible"."min_grant_amount",
            "eligible"."max_grant_amount",
            "eligible"."is_national",
            "eligible"."jurisdictions",
            "eligible"."eligible_org_types",
            "eligible"."focus_areas",
            "eligible"."keywords",
            "eligible"."source_url",
            "eligible"."application_url",
            "eligible"."opportunity_type",
            "eligible"."verification_status",
            "eligible"."verified_at",
            "eligible"."theme_score",
            "eligible"."geography_score",
            "eligible"."eligibility_score",
            "eligible"."timing_score",
            "eligible"."track_record_score",
            "eligible"."won_funder",
            "eligible"."fit_score",
            "eligible"."is_strong_fit",
            "eligible"."tag_density_penalised",
            "eligible"."funder_avg_tags",
            "eligible"."flags",
            "eligible"."computed_at",
            "eligible"."feed_status",
            "eligible"."ok_states",
            "eligible"."funder_state",
            "row_number"() OVER (PARTITION BY "eligible"."project_code", ("lower"(TRIM(BOTH FROM COALESCE("eligible"."funder_name", ''::"text")))), (TRIM(BOTH FROM "regexp_replace"("regexp_replace"("lower"(COALESCE("eligible"."opportunity_name", ''::"text")), '\s*\(.*?\)'::"text", ''::"text", 'g'::"text"), '\s*[:–—-]\s.*$'::"text", ''::"text"))) ORDER BY "eligible"."fit_score" DESC NULLS LAST, "eligible"."deadline", "eligible"."opportunity_id") AS "program_rn"
           FROM "eligible"
        ), "deduped" AS (
         SELECT "stemmed"."project_code",
            "stemmed"."project_name",
            "stemmed"."opportunity_id",
            "stemmed"."opportunity_name",
            "stemmed"."funder_name",
            "stemmed"."deadline",
            "stemmed"."opens_at",
            "stemmed"."min_grant_amount",
            "stemmed"."max_grant_amount",
            "stemmed"."is_national",
            "stemmed"."jurisdictions",
            "stemmed"."eligible_org_types",
            "stemmed"."focus_areas",
            "stemmed"."keywords",
            "stemmed"."source_url",
            "stemmed"."application_url",
            "stemmed"."opportunity_type",
            "stemmed"."verification_status",
            "stemmed"."verified_at",
            "stemmed"."theme_score",
            "stemmed"."geography_score",
            "stemmed"."eligibility_score",
            "stemmed"."timing_score",
            "stemmed"."track_record_score",
            "stemmed"."won_funder",
            "stemmed"."fit_score",
            "stemmed"."is_strong_fit",
            "stemmed"."tag_density_penalised",
            "stemmed"."funder_avg_tags",
            "stemmed"."flags",
            "stemmed"."computed_at",
            "stemmed"."feed_status",
            "stemmed"."ok_states",
            "stemmed"."funder_state",
            "stemmed"."program_rn"
           FROM "stemmed"
          WHERE ("stemmed"."program_rn" = 1)
        )
 SELECT "project_code",
    "project_name",
    "opportunity_id",
    "opportunity_name",
    "funder_name",
    "deadline",
    "opens_at",
    "min_grant_amount",
    "max_grant_amount",
    "is_national",
    "jurisdictions",
    "eligible_org_types",
    "focus_areas",
    "keywords",
    "source_url",
    "application_url",
    "opportunity_type",
    "verification_status",
    "verified_at",
    "theme_score",
    "geography_score",
    "eligibility_score",
    "timing_score",
    "track_record_score",
    "won_funder",
    "fit_score",
    ("is_strong_fit" AND ((COALESCE("geography_score", 0) > 0) OR (COALESCE("max_grant_amount", (0)::numeric) >= (50000)::numeric) OR "won_funder")) AS "is_strong_fit",
    "tag_density_penalised",
    "funder_avg_tags",
    "flags",
    "computed_at",
    "feed_status",
    ("row_number"() OVER (PARTITION BY "project_code" ORDER BY "fit_score" DESC NULLS LAST, "max_grant_amount" DESC NULLS LAST, "deadline"))::integer AS "project_rank"
   FROM "deduped";


