COMMENT ON COLUMN "public"."alma_evidence"."consent_authority" IS 'Who authorised the classification — the holding community body, agreement, or person whose call this was. The sovereignty record.';



COMMENT ON COLUMN "public"."alma_evidence"."revocation_token" IS 'Per-row capability SECRET. Holder may flip this row to Strictly Private via the revoke endpoint. MUST NOT be exposed in any GET/API read. Delivered out of band to the holding community so revocation is community-held.';



CREATE TABLE IF NOT EXISTS "public"."alma_extraction_patterns" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "source_type" "text" NOT NULL,
    "pattern_name" "text" NOT NULL,
    "pattern_version" integer DEFAULT 1,
    "extraction_prompt" "text" NOT NULL,
    "times_used" integer DEFAULT 0,
    "successful_extractions" integer DEFAULT 0,
    "total_entities_extracted" integer DEFAULT 0,
    "success_rate" numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN ("times_used" > 0) THEN ((("successful_extractions")::numeric / ("times_used")::numeric) * (100)::numeric)
    ELSE (0)::numeric
END) STORED,
    "avg_entities" numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN ("successful_extractions" > 0) THEN (("total_entities_extracted")::numeric / ("successful_extractions")::numeric)
    ELSE (0)::numeric
END) STORED,
    "is_active" boolean DEFAULT true,
    "last_used_at" timestamp with time zone,
    "superseded_by" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb"
);


