CREATE TABLE IF NOT EXISTS "public"."assertions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "subject_table" "text" NOT NULL,
    "subject_id" "text" NOT NULL,
    "predicate" "text" NOT NULL,
    "value" "text",
    "asserter_kind" "text" NOT NULL,
    "basis" "text" NOT NULL,
    "asserter_user_id" "uuid",
    "asserter_name" "text",
    "asserter_org_id" "uuid",
    "machine_rule" "text",
    "note" "text" NOT NULL,
    "source_url" "text",
    "superseded_by" "uuid",
    "superseded_at" timestamp with time zone,
    "disagreement_kind" "text",
    "disagrees_with" "uuid",
    "audience" "text" DEFAULT 'private'::"text" NOT NULL,
    "asserted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "assertions_asserter_kind_check" CHECK (("asserter_kind" = ANY (ARRAY['register'::"text", 'certifier'::"text", 'government'::"text", 'self'::"text", 'us'::"text", 'media'::"text", 'research'::"text", 'community'::"text"]))),
    CONSTRAINT "assertions_asserter_name_check" CHECK ((("asserter_name" IS NULL) OR (("length"(TRIM(BOTH FROM "asserter_name")) >= 1) AND ("length"(TRIM(BOTH FROM "asserter_name")) <= 200)))),
    CONSTRAINT "assertions_attribution" CHECK ((("machine_rule" IS NOT NULL) OR ("asserter_user_id" IS NOT NULL) OR ("asserter_name" IS NOT NULL) OR ("audience" = 'private'::"text"))),
    CONSTRAINT "assertions_audience_check" CHECK (("audience" = ANY (ARRAY['private'::"text", 'community'::"text", 'public'::"text"]))),
    CONSTRAINT "assertions_basis_check" CHECK (("basis" = ANY (ARRAY['statutory'::"text", 'certified'::"text", 'disclosed'::"text", 'stated'::"text", 'derived'::"text", 'inferred'::"text"]))),
    CONSTRAINT "assertions_disagreement_kind_check" CHECK ((("disagreement_kind" IS NULL) OR ("disagreement_kind" = ANY (ARRAY['conflict'::"text", 'different_measure'::"text", 'different_basis'::"text", 'silence'::"text"])))),
    CONSTRAINT "assertions_no_self_supersession" CHECK (("superseded_by" IS DISTINCT FROM "id")),
    CONSTRAINT "assertions_note_check" CHECK ((("length"(TRIM(BOTH FROM "note")) >= 3) AND ("length"(TRIM(BOTH FROM "note")) <= 4000))),
    CONSTRAINT "assertions_predicate_check" CHECK ((("length"(TRIM(BOTH FROM "predicate")) >= 1) AND ("length"(TRIM(BOTH FROM "predicate")) <= 120))),
    CONSTRAINT "assertions_subject_id_check" CHECK ((("length"(TRIM(BOTH FROM "subject_id")) >= 1) AND ("length"(TRIM(BOTH FROM "subject_id")) <= 200))),
    CONSTRAINT "assertions_subject_table_check" CHECK ((("length"(TRIM(BOTH FROM "subject_table")) >= 1) AND ("length"(TRIM(BOTH FROM "subject_table")) <= 120))),
    CONSTRAINT "assertions_supersession_is_dated" CHECK (((("superseded_by" IS NULL) AND ("superseded_at" IS NULL)) OR (("superseded_by" IS NOT NULL) AND ("superseded_at" IS NOT NULL))))
);


ALTER TABLE "public"."assertions" OWNER TO "postgres";


COMMENT ON TABLE "public"."assertions" IS 'Append-only ledger of claims about any record. Corrections supersede, never delete. Anonymous assertions are recorded and read as derived until a person is confirmed behind them.';



COMMENT ON COLUMN "public"."assertions"."asserter_kind" IS 'WHO asserts. Kept apart from `basis`, which is HOW they know. `community` is a community speaking about its own place without claiming to be the subject of the record; `self` is the subject about itself. `research` keeps an evaluation body out of the `media` bucket.';



COMMENT ON CONSTRAINT "assertions_attribution" ON "public"."assertions" IS 'Anonymous first answers count (Ben 2026-08-04), so an unattributed assertion is allowed while it stays private. Nothing reaches a community or public audience without a machine rule, a user, or a name: the rung protects the reader, the gate does not.';



