CREATE TABLE IF NOT EXISTS "public"."ato_tax_transparency" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "entity_name" "text" NOT NULL,
    "abn" "text" NOT NULL,
    "total_income" numeric,
    "taxable_income" numeric,
    "tax_payable" numeric,
    "industry" "text",
    "entity_type" "text",
    "report_year" "text" NOT NULL,
    "effective_tax_rate" numeric GENERATED ALWAYS AS (
CASE
    WHEN ("taxable_income" > (0)::numeric) THEN "round"((("tax_payable" / "taxable_income") * (100)::numeric), 2)
    ELSE (0)::numeric
END) STORED,
    "acnc_match" boolean DEFAULT false,
    "asic_match" boolean DEFAULT false,
    "asx_listed" boolean DEFAULT false,
    "source_file" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
