    "geocode_precision" "public"."geocode_precision",
    "geocode_place" "text",
    "geocode_radius_km" numeric,
    "geocoded_at" timestamp with time zone,
    "geocode_source" "text",
    "merged_into" "uuid",
    "merged_at" timestamp with time zone,
    "merge_basis" "text",
    "indigenous_org_basis" "text",
    "indigenous_org_basis_at" timestamp with time zone,
    CONSTRAINT "organizations_geocode_precision_complete" CHECK ((("geocoded_at" IS NULL) OR (("geocode_precision" IS NOT NULL) AND ("latitude" IS NOT NULL) AND ("longitude" IS NOT NULL)))),
    CONSTRAINT "organizations_merged_not_active" CHECK ((("merged_into" IS NULL) OR ("is_active" = false)))
)
WITH ("autovacuum_analyze_scale_factor"='0.02');


ALTER TABLE "public"."organizations" OWNER TO "postgres";


COMMENT ON TABLE "public"."organizations" IS 'Organizations in the Empathy Ledger multi-tenant system';



COMMENT ON COLUMN "public"."organizations"."stripe_customer_id" IS 'Stripe customer ID (cus_xxx) for billing via ACT Ventures';



COMMENT ON COLUMN "public"."organizations"."plan" IS 'Subscription tier: community, organisation, institution, enterprise';



COMMENT ON COLUMN "public"."organizations"."billing_status" IS 'Billing status: active, trialing, past_due, paused, canceled';



COMMENT ON COLUMN "public"."organizations"."control_type" IS 'community_controlled | community_adjacent | intermediary | government | university | peak_body';



COMMENT ON COLUMN "public"."organizations"."profile_completeness_score" IS '0.00-1.00 — fraction of profile fields populated. Calculated by lib/alma/profile-completeness.ts. See profile_completeness_breakdown for per-field detail.';



COMMENT ON COLUMN "public"."organizations"."featured_on_map" IS 'True for exemplar profiles surfaced on the public Map by default. Either auto-set when score crosses 0.75, or manually flagged by admin.';



COMMENT ON COLUMN "public"."organizations"."annual_report_url" IS 'URL to the latest publicly available annual report. Single field — track historical reports in a separate table if needed later.';



COMMENT ON COLUMN "public"."organizations"."history_summary" IS 'Short prose paragraph describing org founding, lineage, and any cultural authority context. Populated by enrichment, edited by claim flow.';



COMMENT ON COLUMN "public"."organizations"."acco_certified" IS 'TRUE if organization ABN appears in oric_corporations. Authoritative ACCO test (Aboriginal Community Controlled Organisation). is_indigenous_org is a looser heuristic flag.';



COMMENT ON COLUMN "public"."organizations"."hero_photo_url" IS 'Single chosen hero portrait URL for the org. Powers the /kiosk hook rotator and /kiosk/lenses/stories fallback. Editable via /admin/kiosk/heroes.';



COMMENT ON COLUMN "public"."organizations"."geocode_precision" IS 'How well the coordinate is known. locality ~2km, postcode ~5km. Absent means the coordinate was not machine-derived. There is no state tier on purpose.';



COMMENT ON COLUMN "public"."organizations"."geocode_place" IS 'The named place the coordinate came from, e.g. "CAIRNS NORTH 4870". Shown to readers so a dot is not mistaken for an address.';



COMMENT ON COLUMN "public"."organizations"."geocode_radius_km" IS 'Approximate radius the point stands for. Render it; a dot without it overstates what is known.';



COMMENT ON COLUMN "public"."organizations"."geocode_source" IS 'Gazetteer the match came from, e.g. postcode_geo.';



COMMENT ON COLUMN "public"."organizations"."merged_into" IS 'Set when this row was merged into another. The row is kept, not deleted, so the merge is traceable and reversible.';



COMMENT ON COLUMN "public"."organizations"."merge_basis" IS 'Why the merge was considered safe, e.g. same_abn_identical_name. Lets a whole class be reversed if the rule turns out wrong.';



COMMENT ON COLUMN "public"."organizations"."indigenous_org_basis" IS 'Why is_indigenous_org holds its value. oric_registered | acco_certified | name_indicator | unverified | community_confirmed. "unverified" means WE have not found a basis, never that the organisation is not Indigenous-led.';



CREATE OR REPLACE VIEW "public"."canonical_organizations" AS
 SELECT "o"."id",
    "o"."gs_entity_id",
    "o"."abn",
    "o"."name",
    "o"."slug",
    "o"."state",
    "o"."city",
    "o"."is_indigenous_org",
    "o"."indigenous_org_basis",
        CASE
            WHEN (NOT COALESCE("o"."is_indigenous_org", false)) THEN 'none'::"text"
            WHEN ("o"."indigenous_org_basis" = ANY (ARRAY['oric_registered'::"text", 'supply_nation_certified'::"text", 'acnc_indigenous_charity'::"text", 'acco_certified'::"text"])) THEN 'register'::"text"
            WHEN ("o"."indigenous_org_basis" = 'self_identified'::"text") THEN 'self_declared'::"text"
            WHEN ("o"."indigenous_org_basis" = ANY (ARRAY['name_indicator'::"text", 'unverified'::"text", 'reviewed_indigenous_led'::"text"])) THEN 'weak'::"text"
            ELSE 'none'::"text"
        END AS "indigenous_basis_strength",
    (COALESCE("o"."is_indigenous_org", false) AND ("o"."indigenous_org_basis" = ANY (ARRAY['oric_registered'::"text", 'supply_nation_certified'::"text", 'acnc_indigenous_charity'::"text", 'acco_certified'::"text", 'self_identified'::"text"]))) AS "is_established_indigenous",
    "g"."lga_name",
    "g"."lga_code",
    "g"."sa2_code",
    "g"."remoteness",
    "g"."seifa_irsd_decile",
    "g"."postcode",
    "g"."is_community_controlled" AS "register_says_community_controlled",
    "g"."community_controlled_tier" AS "register_tier",
    "g"."is_supply_nation_certified",
    "g"."entity_type",
    "g"."latest_revenue"
   FROM ("public"."organizations" "o"
     LEFT JOIN "public"."gs_entities" "g" ON (("g"."id" = "o"."gs_entity_id")))
  WHERE ("o"."merged_into" IS NULL);


ALTER VIEW "public"."canonical_organizations" OWNER TO "postgres";


COMMENT ON VIEW "public"."canonical_organizations" IS 'One row per organisation, merged duplicates removed. JOIN ON gs_entity_id, never abn: abn is duplicated 5,487 times here and unindexed, while gs_entity_id is on 99.7% of rows and indexed both sides. Filter is_established_indigenous when publishing any list of Aboriginal organisations; is_indigenous_org alone includes flags resting on our own reading of a name.';



