    "verdict" "public"."clarity_verdict",
    "verdict_reason" "text",
    "verdict_by" "text",
    "verdict_at" timestamp with time zone,
    "first_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "refreshed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "missing_since" timestamp with time zone,
    "noun" "text",
    "noun_source" "text",
    "noun_proposed" "text",
    "curated_at" timestamp with time zone,
    "curated_by" "text",
    "owner_app_proposed" "text",
    "owner_source" "text",
    "owner_set_by" "text",
    "owner_set_at" timestamp with time zone,
    "project_codes" "text"[],
    CONSTRAINT "clarity_object_act_business_source_check" CHECK (("act_business_source" = ANY (ARRAY['canonical_d14'::"text", 'name_rule'::"text", 'manual'::"text", 'scope_table'::"text"]))),
    CONSTRAINT "clarity_object_cruft_needs_reason" CHECK ((("verdict" IS DISTINCT FROM 'cruft'::"public"."clarity_verdict") OR (("verdict_reason" IS NOT NULL) AND ("btrim"("verdict_reason") <> ''::"text")))),
    CONSTRAINT "clarity_object_freshness_source_check" CHECK (("freshness_source" = ANY (ARRAY['column'::"text", 'mv_refresh_log'::"text", 'cron'::"text", 'none'::"text"]))),
    CONSTRAINT "clarity_object_no_cruft_while_referenced" CHECK ((("verdict" IS DISTINCT FROM 'cruft'::"public"."clarity_verdict") OR (("refs_app" = 0) AND ("refs_script" = 0) AND ("refs_db_function" = 0) AND ("lineage_in" = 0)))),
    CONSTRAINT "clarity_object_noun_check" CHECK (("noun" = ANY (ARRAY['money'::"text", 'organisations'::"text", 'people'::"text", 'places'::"text", 'evidence'::"text", 'machine'::"text"]))),
    CONSTRAINT "clarity_object_noun_proposed_check" CHECK (("noun_proposed" = ANY (ARRAY['money'::"text", 'organisations'::"text", 'people'::"text", 'places'::"text", 'evidence'::"text", 'machine'::"text"]))),
    CONSTRAINT "clarity_object_noun_source_check" CHECK (("noun_source" = ANY (ARRAY['domain_rule'::"text", 'human'::"text"]))),
    CONSTRAINT "clarity_object_owner_app_check" CHECK (("owner_app" = ANY (ARRAY['civicgraph'::"text", 'justicehub'::"text", 'both'::"text", 'neither'::"text"]))),
    CONSTRAINT "clarity_object_owner_app_proposed_check" CHECK (("owner_app_proposed" = ANY (ARRAY['civicgraph'::"text", 'justicehub'::"text", 'both'::"text"]))),
    CONSTRAINT "clarity_object_owner_source_check" CHECK (("owner_source" = ANY (ARRAY['code_refs_rule'::"text", 'human'::"text"]))),
    CONSTRAINT "clarity_object_routine_kind_check" CHECK (("routine_kind" = ANY (ARRAY['trigger'::"text", 'security_definer'::"text", 'plain'::"text"])))
);


