    CONSTRAINT "clarity_question_caveat_check" CHECK (("length"("btrim"("caveat")) > 20)),
    CONSTRAINT "clarity_question_uniqueness_check" CHECK ((("uniqueness" >= (0)::numeric) AND ("uniqueness" <= (1)::numeric))),
