    CONSTRAINT "executable_or_blocked" CHECK (((("state" = ANY (ARRAY['answered'::"public"."clarity_question_state", 'contested'::"public"."clarity_question_state"])) AND ("answer_sql" IS NOT NULL)) OR (("state" = ANY (ARRAY['unanswerable'::"public"."clarity_question_state", 'refused'::"public"."clarity_question_state"])) AND ("array_length"("blocked_by", 1) >= 1)) OR ("state" = ANY (ARRAY['draft'::"public"."clarity_question_state", 'retired'::"public"."clarity_question_state"]))))
);


