CREATE OR REPLACE VIEW "public"."current_knowledge" WITH ("security_invoker"='true') AS
 SELECT "knowledge_id",
    "version",
    "content",
    "content_type",
    "tags",
    "projects",
    "active_from",
    "changed_by",
    "reason_for_change"
