CREATE OR REPLACE VIEW "public"."discrimination_aggregations_v" WITH ("security_invoker"='true') AS
 SELECT "r"."sa3_code",
    "r"."sa3_name",
    "r"."state" AS "sa3_state",
    "dr"."system_type",
    "count"(*) AS "report_count"
   FROM ("public"."discrimination_reports" "dr"
     JOIN "public"."sa3_regions" "r" ON (("r"."sa3_code" = "dr"."sa3_code")))
  GROUP BY "r"."sa3_code", "r"."sa3_name", "r"."state", "dr"."system_type";


