CREATE OR REPLACE VIEW "public"."discrimination_sa3_totals_v" WITH ("security_invoker"='true') AS
 SELECT "r"."sa3_code",
    "r"."sa3_name",
    "r"."state" AS "sa3_state",
    "count"(*) AS "total_reports",
    "count"(DISTINCT "dr"."system_type") AS "system_types_reported"
   FROM ("public"."discrimination_reports" "dr"
     JOIN "public"."sa3_regions" "r" ON (("r"."sa3_code" = "dr"."sa3_code")))
  GROUP BY "r"."sa3_code", "r"."sa3_name", "r"."state";


