CREATE MATERIALIZED VIEW "public"."donor_name_keys" AS
 SELECT "donor_name",
    "public"."entity_name_key"("donor_name") AS "nk"
   FROM ( SELECT DISTINCT "political_donations"."donor_name"
           FROM "public"."political_donations"
          WHERE (("political_donations"."receipt_type" = 'donation received'::"text") AND ("political_donations"."donor_name" IS NOT NULL) AND ("btrim"("political_donations"."donor_name") <> ''::"text"))) "s"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."donor_name_keys" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."donor_key_abn" AS
 SELECT "k"."nk" AS "n",
    "min"(NULLIF("d"."donor_abn", ''::"text")) AS "abn"
   FROM ("public"."political_donations" "d"
     JOIN "public"."donor_name_keys" "k" ON (("k"."donor_name" = "d"."donor_name")))
  WHERE (("d"."receipt_type" = 'donation received'::"text") AND (NULLIF("d"."donor_abn", ''::"text") IS NOT NULL))
  GROUP BY "k"."nk"
 HAVING ("count"(DISTINCT NULLIF("d"."donor_abn", ''::"text")) = 1)
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."donor_key_abn" OWNER TO "postgres";


