    CONSTRAINT "funder_intelligence_derived_theme_grade_check" CHECK (("derived_theme_grade" = ANY (ARRAY['verified'::"text", 'inferred'::"text", 'unverified'::"text", 'missing'::"text"]))),
    CONSTRAINT "funder_intelligence_evidence_tier_check" CHECK ((("evidence_tier" >= 1) AND ("evidence_tier" <= 3))),
    CONSTRAINT "funder_intelligence_giving_grade_check" CHECK (("giving_grade" = ANY (ARRAY['verified'::"text", 'inferred'::"text", 'unverified'::"text", 'missing'::"text"]))),
    CONSTRAINT "funder_intelligence_reach_grade_check" CHECK (("reach_grade" = ANY (ARRAY['verified'::"text", 'inferred'::"text", 'unverified'::"text", 'missing'::"text"]))),
    CONSTRAINT "funder_intelligence_theme_grade_check" CHECK (("theme_grade" = ANY (ARRAY['verified'::"text", 'inferred'::"text", 'unverified'::"text", 'missing'::"text"]))),
    CONSTRAINT "funder_intelligence_type_grade_check" CHECK (("type_grade" = ANY (ARRAY['verified'::"text", 'inferred'::"text", 'unverified'::"text", 'missing'::"text"])))
);


ALTER TABLE "public"."funder_intelligence" OWNER TO "postgres";


COMMENT ON TABLE "public"."funder_intelligence" IS 'One durable row per funder with per-field trust grades. Reach is counted only from ABN-resolved grant links; name-similarity attribution is never used.';



COMMENT ON COLUMN "public"."funder_intelligence"."previous_rank_score" IS 'Rank score from the prior rebuild, so week-to-week movement is visible without a snapshot table.';



COMMENT ON COLUMN "public"."funder_intelligence"."derived_thematics" IS 'Themes derived from the attributes of ABN-resolved grantees. Prefer this over thematic_focus, which is enrichment prose and demonstrably incomplete.';



COMMENT ON COLUMN "public"."funder_intelligence"."derived_theme_evidence" IS 'Grantee counts behind each derived tag, so every tag can be audited back to the grants that produced it.';



