CREATE TABLE IF NOT EXISTS "public"."goods_products" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "slug" "text" NOT NULL,
    "name" "text" NOT NULL,
    "category" "text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "bom_description" "text",
    "material_cost_aud" numeric,
    "manufacturing_cost_aud" numeric,
    "wholesale_price_aud" numeric,
    "typical_retail_price_aud" numeric,
    "typical_delivered_cost_remote" numeric,
    "idiot_index" numeric GENERATED ALWAYS AS (
CASE
    WHEN (("material_cost_aud" > (0)::numeric) AND ("typical_delivered_cost_remote" > (0)::numeric)) THEN "round"(("typical_delivered_cost_remote" / "material_cost_aud"), 1)
    ELSE NULL::numeric
END) STORED,
    "goods_delivered_cost_remote" numeric,
    "cost_advantage_pct" numeric GENERATED ALWAYS AS (
CASE
    WHEN (("typical_delivered_cost_remote" > (0)::numeric) AND ("goods_delivered_cost_remote" > (0)::numeric)) THEN "round"((100.0 * (1.0 - ("goods_delivered_cost_remote" / "typical_delivered_cost_remote"))), 1)
    ELSE NULL::numeric
END) STORED,
    "expected_lifespan_months" integer,
    "warranty_months" integer,
    "mean_time_to_failure_months" integer,
    "common_failure_modes" "text"[],
    "maintenance_interval_months" integer,
    "weight_kg" numeric,
    "volume_m3" numeric,
    "flat_packable" boolean DEFAULT false,
    "assembly_time_minutes" integer,
    "specs" "jsonb" DEFAULT '{}'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "goods_products_category_check" CHECK (("category" = ANY (ARRAY['bed'::"text", 'washer'::"text", 'fridge'::"text", 'mattress'::"text", 'furniture'::"text", 'appliance'::"text", 'other'::"text"]))),
    CONSTRAINT "goods_products_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'prototype'::"text", 'discontinued'::"text", 'planned'::"text"])))
);


