    CONSTRAINT "governed_proof_runs_eval_score_check" CHECK ((("eval_score" IS NULL) OR (("eval_score" >= 0.00) AND ("eval_score" <= 1.00)))),
    CONSTRAINT "governed_proof_runs_result_status_check" CHECK (("result_status" = ANY (ARRAY['success'::"text", 'partial'::"text", 'failed'::"text"])))
);


