CREATE TABLE IF NOT EXISTS "public"."governed_proof_tasks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "task_type" "text" NOT NULL,
    "status" "text" DEFAULT 'queued'::"text" NOT NULL,
    "queue_lane" "text" DEFAULT 'core'::"text" NOT NULL,
    "priority" "text" DEFAULT 'medium'::"text" NOT NULL,
    "owner_system" "text" DEFAULT 'SHARED'::"text" NOT NULL,
    "system_scope" "text"[] DEFAULT ARRAY[]::"text"[] NOT NULL,
    "target_type" "text" NOT NULL,
    "target_id" "text" NOT NULL,
    "value_score" numeric(6,2) DEFAULT 0 NOT NULL,
    "confidence_required" numeric(3,2) DEFAULT 0.80 NOT NULL,
    "input_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "acceptance_checks" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "review_status" "text" DEFAULT 'not_required'::"text" NOT NULL,
    "promotion_status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "claimed_by" "text",
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "governed_proof_tasks_confidence_required_check" CHECK ((("confidence_required" >= 0.00) AND ("confidence_required" <= 1.00))),
    CONSTRAINT "governed_proof_tasks_owner_system_check" CHECK (("owner_system" = ANY (ARRAY['GS'::"text", 'JH'::"text", 'EL'::"text", 'SHARED'::"text"]))),
    CONSTRAINT "governed_proof_tasks_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"]))),
    CONSTRAINT "governed_proof_tasks_promotion_status_check" CHECK (("promotion_status" = ANY (ARRAY['draft'::"text", 'internal'::"text", 'partner'::"text", 'public'::"text", 'suppressed'::"text"]))),
    CONSTRAINT "governed_proof_tasks_queue_lane_check" CHECK (("queue_lane" = ANY (ARRAY['hot'::"text", 'core'::"text", 'repair'::"text", 'exploration'::"text"]))),
    CONSTRAINT "governed_proof_tasks_review_status_check" CHECK (("review_status" = ANY (ARRAY['not_required'::"text", 'pending'::"text", 'approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "governed_proof_tasks_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'claimed'::"text", 'running'::"text", 'blocked'::"text", 'failed'::"text", 'completed'::"text"]))),
    CONSTRAINT "governed_proof_tasks_task_type_check" CHECK (("task_type" = ANY (ARRAY['discover_gap'::"text", 'resolve_identity'::"text", 'enrich_record'::"text", 'link_records'::"text", 'validate_record'::"text", 'assemble_proof'::"text", 'refresh_bundle'::"text", 'review_required'::"text"])))
);


