COMMENT ON COLUMN "public"."grant_opportunities"."feedback" IS 'Human feedback array: [{action, reason, timestamp}]';



COMMENT ON COLUMN "public"."grant_opportunities"."sources" IS 'JSONB array of {pluginId, foundAt, rawUrl, confidence} per source';



COMMENT ON COLUMN "public"."grant_opportunities"."discovery_method" IS 'How this grant was found (source plugin ID or combo)';



COMMENT ON COLUMN "public"."grant_opportunities"."last_verified_at" IS 'Last time this grant was confirmed still open via web search';



COMMENT ON COLUMN "public"."grant_opportunities"."program_type" IS 'grant, fellowship, award, scholarship, program, other';



COMMENT ON COLUMN "public"."grant_opportunities"."pile" IS 'Voice|Flow|Ground|Grants|Other|Uncoded — derived from aligned_projects[] via canonical pile map';



COMMENT ON COLUMN "public"."grant_opportunities"."provider_org_id" IS 'organizations.id for grants whose provider is a government body, university, or general org (not a private foundation). Use this when foundation_id is NULL.';



COMMENT ON COLUMN "public"."grant_opportunities"."goods_relevance_score" IS 'Goods/ACT-GD relevance 0-100. >=50 triggers ACT-GD tag in aligned_projects. Set by scripts/lib/goods-relevance.mjs.';



COMMENT ON COLUMN "public"."grant_opportunities"."goods_relevance_signals" IS 'Which signals contributed to the score: { keyword: [...], geography, amount_band, category: [...], embedding_similarity }.';



COMMENT ON COLUMN "public"."grant_opportunities"."dgr_required" IS 'TRUE if grant requires Deductible Gift Recipient endorsement. Backfilled from eligibility_criteria JSONB.';



COMMENT ON COLUMN "public"."grant_opportunities"."accepts_sole_trader" IS 'TRUE if sole trader applicants are eligible. NULL = unknown.';



COMMENT ON COLUMN "public"."grant_opportunities"."accepts_pty_ltd" IS 'TRUE if Pty Ltd applicants are eligible. NULL = unknown.';



COMMENT ON COLUMN "public"."grant_opportunities"."accepts_charity" IS 'TRUE if ACNC-registered charities are eligible. NULL = unknown.';



COMMENT ON COLUMN "public"."grant_opportunities"."accepts_unincorporated" IS 'TRUE if unincorporated associations are eligible. NULL = unknown.';



COMMENT ON COLUMN "public"."grant_opportunities"."eligibility_signals_at" IS 'Last time the backfill job ran for this row.';



