    "unit" "text",
    "direction" "text",
    "year" integer,
    "who_scope" "text",
    "where_scope" "text",
    "period_label" "text",
    "source_title" "text",
    "source_url" "text",
    "source_page" "text",
    "context_note" "text",
    "story_related_site_id" "uuid",
    "selected_outcome_id" "uuid",
    "outcome_link_confirmed" boolean DEFAULT false NOT NULL,
    "allowed_purposes" "text"[] DEFAULT ARRAY['community_learning'::"text"] NOT NULL,
    "created_by" "uuid" NOT NULL,
    "updated_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "submitted_at" timestamp with time zone,
    "promoted_metric_id" "uuid",
    "promoted_evaluation_id" "uuid",
    "promoted_evidence_link_id" "uuid",
    "promoted_by" "uuid",
    "promoted_at" timestamp with time zone,
    CONSTRAINT "jr_evidence_drafts_allowed_purposes_check" CHECK (("allowed_purposes" <@ ARRAY['community_learning'::"text", 'service_improvement'::"text", 'funding'::"text", 'public_profile'::"text", 'shared_learning'::"text"])),
    CONSTRAINT "jr_evidence_drafts_context_note_check" CHECK ((("context_note" IS NULL) OR ("char_length"("context_note") <= 3000))),
    CONSTRAINT "jr_evidence_drafts_current_step_check" CHECK ((("current_step" >= 1) AND ("current_step" <= 4))),
    CONSTRAINT "jr_evidence_drafts_direction_check" CHECK ((("direction" IS NULL) OR ("direction" = ANY (ARRAY['increase'::"text", 'decrease'::"text", 'stable'::"text", 'mixed'::"text", 'not_collected'::"text", 'not_applicable'::"text"])))),
    CONSTRAINT "jr_evidence_drafts_evidence_type_check" CHECK (("evidence_type" = ANY (ARRAY['community_yarn'::"text", 'observation'::"text", 'report'::"text"]))),
    CONSTRAINT "jr_evidence_drafts_period_label_check" CHECK ((("period_label" IS NULL) OR ("char_length"("period_label") <= 200))),
    CONSTRAINT "jr_evidence_drafts_promotion_state" CHECK (((("promoted_at" IS NULL) AND ("promoted_by" IS NULL) AND ("promoted_metric_id" IS NULL) AND ("promoted_evaluation_id" IS NULL) AND ("promoted_evidence_link_id" IS NULL)) OR (("promoted_at" IS NOT NULL) AND ("promoted_by" IS NOT NULL) AND ("promoted_evidence_link_id" IS NOT NULL) AND ("status" = 'archived'::"text") AND ((("evidence_type" = 'community_yarn'::"text") AND ("promoted_metric_id" IS NULL) AND ("promoted_evaluation_id" IS NULL)) OR (("evidence_type" = 'observation'::"text") AND ("promoted_metric_id" IS NOT NULL) AND ("promoted_evaluation_id" IS NULL)) OR (("evidence_type" = 'report'::"text") AND ("promoted_metric_id" IS NULL) AND ("promoted_evaluation_id" IS NOT NULL)))))),
    CONSTRAINT "jr_evidence_drafts_source_page_check" CHECK ((("source_page" IS NULL) OR ("char_length"("source_page") <= 100))),
    CONSTRAINT "jr_evidence_drafts_source_title_check" CHECK ((("source_title" IS NULL) OR ("char_length"("source_title") <= 300))),
    CONSTRAINT "jr_evidence_drafts_source_url_check" CHECK ((("source_url" IS NULL) OR (("char_length"("source_url") <= 1000) AND ("source_url" ~* '^https?://'::"text")))),
    CONSTRAINT "jr_evidence_drafts_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted_for_review'::"text", 'archived'::"text"]))),
    CONSTRAINT "jr_evidence_drafts_story_lane" CHECK ((("evidence_type" = 'community_yarn'::"text") OR ("story_related_site_id" IS NULL))),
    CONSTRAINT "jr_evidence_drafts_submission_state" CHECK (((("status" <> 'submitted_for_review'::"text") AND ("submitted_at" IS NULL)) OR (("status" = 'submitted_for_review'::"text") AND ("submitted_at" IS NOT NULL) AND ("current_step" = 4) AND ("what_changed" IS NOT NULL) AND ("char_length"("btrim"("what_changed")) > 0) AND ("selected_outcome_id" IS NOT NULL) AND ("outcome_link_confirmed" = true) AND ((("evidence_type" = 'community_yarn'::"text") AND ("story_related_site_id" IS NOT NULL)) OR (("evidence_type" = ANY (ARRAY['observation'::"text", 'report'::"text"])) AND ("source_title" IS NOT NULL) AND ("char_length"("btrim"("source_title")) > 0) AND ("source_url" IS NOT NULL)))))),
    CONSTRAINT "jr_evidence_drafts_unit_check" CHECK ((("unit" IS NULL) OR ("char_length"("unit") <= 80))),
    CONSTRAINT "jr_evidence_drafts_value_text_check" CHECK ((("value_text" IS NULL) OR ("char_length"("value_text") <= 240))),
    CONSTRAINT "jr_evidence_drafts_what_changed_check" CHECK ((("what_changed" IS NULL) OR ("char_length"("what_changed") <= 4000))),
    CONSTRAINT "jr_evidence_drafts_where_scope_check" CHECK ((("where_scope" IS NULL) OR ("char_length"("where_scope") <= 500))),
    CONSTRAINT "jr_evidence_drafts_who_scope_check" CHECK ((("who_scope" IS NULL) OR ("char_length"("who_scope") <= 500))),
    CONSTRAINT "jr_evidence_drafts_year_check" CHECK ((("year" IS NULL) OR (("year" >= 1900) AND ("year" <= 2100))))
);


