    CONSTRAINT "jr_outcome_evidence_links_source_title_check" CHECK ((("source_title" IS NULL) OR ("char_length"("source_title") <= 300))),
    CONSTRAINT "jr_outcome_evidence_links_source_url_check" CHECK ((("source_url" IS NULL) OR ("char_length"("source_url") <= 1000))),
    CONSTRAINT "jr_outcome_evidence_links_visibility_check" CHECK (("visibility" = ANY (ARRAY['private'::"text", 'community'::"text", 'public'::"text"]))),
    CONSTRAINT "jr_outcome_evidence_links_withdrawal_note_check" CHECK ((("withdrawal_note" IS NULL) OR ("char_length"("withdrawal_note") <= 1000))),
    CONSTRAINT "jr_outcome_evidence_links_workflow_state_check" CHECK (("workflow_state" = ANY (ARRAY['draft'::"text", 'steward_review'::"text", 'community_discussion'::"text", 'approved'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "jr_outcome_evidence_public_state" CHECK ((("visibility" <> 'public'::"text") OR (("workflow_state" = 'approved'::"text") AND ("approved_by" IS NOT NULL) AND ("approved_at" IS NOT NULL) AND ("is_active" = true) AND ('public_profile'::"text" = ANY ("allowed_purposes"))))),
