    CONSTRAINT "jr_site_authorities_lifecycle" CHECK (((("status" = 'pending'::"text") AND ("publication_enabled" = false) AND ("verified_at" IS NULL) AND ("verified_by" IS NULL) AND ("revoked_at" IS NULL) AND ("revoked_by" IS NULL) AND ("revocation_note" IS NULL)) OR (("status" = 'verified'::"text") AND ("verified_at" IS NOT NULL) AND ("verified_by" IS NOT NULL) AND ("revoked_at" IS NULL) AND ("revoked_by" IS NULL) AND ("revocation_note" IS NULL)) OR (("status" = 'revoked'::"text") AND ("publication_enabled" = false) AND ("revoked_at" IS NOT NULL) AND ("revocation_note" IS NOT NULL) AND ((("verified_at" IS NULL) AND ("verified_by" IS NULL)) OR (("verified_at" IS NOT NULL) AND ("verified_by" IS NOT NULL)))))),
    CONSTRAINT "jr_site_authorities_revocation_note_check" CHECK ((("revocation_note" IS NULL) OR (("char_length"("btrim"("revocation_note")) >= 3) AND ("char_length"("btrim"("revocation_note")) <= 2000)))),
    CONSTRAINT "jr_site_authorities_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'verified'::"text", 'revoked'::"text"]))),
    CONSTRAINT "jr_site_authorities_verification_note_check" CHECK ((("char_length"("btrim"("verification_note")) >= 3) AND ("char_length"("btrim"("verification_note")) <= 2000)))
);


