    (COALESCE("sum"("total_expenses"), (0)::numeric))::bigint AS "expenses",
    (COALESCE("sum"("total_assets"), (0)::numeric))::bigint AS "assets",
    (COALESCE("sum"((COALESCE("grants_donations_au", (0)::numeric) + COALESCE("grants_donations_intl", (0)::numeric))), (0)::numeric))::bigint AS "grants",
    (COALESCE("sum"("staff_fte"), (0)::numeric))::integer AS "staff",
    (COALESCE("sum"("staff_volunteers"), (0)::bigint))::integer AS "volunteers"
   FROM "public"."acnc_ais"
  WHERE ("ais_year" >= 2017)
  GROUP BY "ais_year"
  ORDER BY "ais_year"
