CREATE OR REPLACE VIEW "public"."v_award_rows" AS
 SELECT "public"."award_theme_map"("j"."sector") AS "sector_theme",
    "j"."sector",
    "j"."topics",
    "j"."recipient_name",
    "j"."recipient_abn",
    "j"."gs_entity_id",
    "e"."entity_type",
    "e"."is_community_controlled",
    "j"."amount_dollars",
    (NULLIF("substring"("j"."financial_year", '(\d{4})'::"text"), ''::"text"))::integer AS "award_year",
    (COALESCE("e"."entity_type", ''::"text") = ANY (ARRAY['charity'::"text", 'indigenous_corp'::"text", 'social_enterprise'::"text", 'foundation'::"text"])) AS "is_peer"
   FROM ("public"."justice_funding" "j"
     LEFT JOIN "public"."gs_entities" "e" ON (("e"."id" = "j"."gs_entity_id")))
  WHERE ((COALESCE("j"."is_aggregate", false) = false) AND ("j"."amount_dollars" > (0)::numeric) AND ("j"."recipient_name" IS NOT NULL) AND ("length"(TRIM(BOTH FROM "regexp_replace"("j"."recipient_name", '[^a-zA-Z0-9]'::"text", ''::"text", 'g'::"text"))) >= 2) AND (COALESCE("e"."entity_type", ''::"text") <> 'government_body'::"text") AND ("j"."recipient_name" !~* '(department|directorate|ministry|commonwealth of|treasury|the state of|government of|councils?$|city of|shire of|attorney[- ]general)'::"text"));


ALTER VIEW "public"."v_award_rows" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_award_rows" IS 'Phase 6: gated historical award rows from justice_funding — non-aggregate, has amount, real named recipient, government administrators excluded. Base for the award-history MVs.';



CREATE MATERIALIZED VIEW "public"."mv_award_history_by_theme" AS
 WITH "themed" AS (
         SELECT "r"."sector_theme",
            "r"."sector",
            "r"."topics",
            "r"."recipient_name",
            "r"."recipient_abn",
            "r"."gs_entity_id",
            "r"."entity_type",
            "r"."is_community_controlled",
            "r"."amount_dollars",
            "r"."award_year",
            "r"."is_peer",
            "t"."theme"
           FROM ("public"."v_award_rows" "r"
             CROSS JOIN LATERAL ( SELECT DISTINCT "u"."th"
                   FROM ( SELECT "r"."sector_theme" AS "th"
                        UNION ALL
                         SELECT "public"."award_theme_map"("tp"."tp") AS "award_theme_map"
                           FROM "unnest"(COALESCE("r"."topics", '{}'::"text"[])) "tp"("tp")) "u"
                  WHERE ("u"."th" IS NOT NULL)) "t"("theme"))
        )
 SELECT "theme",
    "count"(*) AS "n_awards",
    "count"(DISTINCT COALESCE("recipient_abn", "recipient_name")) AS "distinct_recipients",
    "round"("sum"("amount_dollars")) AS "total_awarded",
    "round"("percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("amount_dollars")::double precision))) AS "median_award",
    "round"("percentile_cont"((0.25)::double precision) WITHIN GROUP (ORDER BY (("amount_dollars")::double precision))) AS "p25_award",
    "round"("percentile_cont"((0.75)::double precision) WITHIN GROUP (ORDER BY (("amount_dollars")::double precision))) AS "p75_award",
    "min"("award_year") AS "earliest_year",
    "max"("award_year") AS "latest_year",
    "count"(DISTINCT COALESCE("recipient_abn", "recipient_name")) FILTER (WHERE "is_peer") AS "n_peer_recipients",
    "round"("sum"("amount_dollars") FILTER (WHERE "is_peer")) AS "peer_total_awarded",
    "round"("percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("amount_dollars")::double precision)) FILTER (WHERE "is_peer")) AS "peer_median_award",
    "count"(*) FILTER (WHERE "is_community_controlled") AS "n_community_controlled",
    "count"(*) FILTER (WHERE ("entity_type" = 'charity'::"text")) AS "n_charity",
    "count"(*) FILTER (WHERE ("entity_type" = 'social_enterprise'::"text")) AS "n_social_enterprise"
   FROM "themed"
  GROUP BY "theme"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_award_history_by_theme" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_award_history_by_theme" IS 'Phase 6: per-theme historical award aggregates (n_awards, totals, percentiles, recipient mix). Refresh nightly via refresh-views-v2.mjs.';



CREATE MATERIALIZED VIEW "public"."mv_award_winner_by_theme" AS
 WITH "themed" AS (
         SELECT "r"."sector_theme",
            "r"."sector",
            "r"."topics",
            "r"."recipient_name",
            "r"."recipient_abn",
            "r"."gs_entity_id",
            "r"."entity_type",
            "r"."is_community_controlled",
            "r"."amount_dollars",
            "r"."award_year",
            "r"."is_peer",
            "t"."theme"
           FROM ("public"."v_award_rows" "r"
             CROSS JOIN LATERAL ( SELECT DISTINCT "u"."th"
                   FROM ( SELECT "r"."sector_theme" AS "th"
                        UNION ALL
                         SELECT "public"."award_theme_map"("tp"."tp") AS "award_theme_map"
                           FROM "unnest"(COALESCE("r"."topics", '{}'::"text"[])) "tp"("tp")) "u"
                  WHERE ("u"."th" IS NOT NULL)) "t"("theme"))
        ), "agg" AS (
         SELECT "themed"."theme",
            COALESCE("themed"."recipient_abn", "themed"."recipient_name") AS "recipient_key",
            "max"("themed"."recipient_name") AS "recipient_name",
            "max"("themed"."recipient_abn") AS "recipient_abn",
            "max"(("themed"."gs_entity_id")::"text") AS "gs_entity_id",
            "max"("themed"."entity_type") AS "entity_type",
            "bool_or"("themed"."is_community_controlled") AS "is_community_controlled",
            "count"(*) AS "n_awards",
            "round"("sum"("themed"."amount_dollars")) AS "total_awarded",
            "max"("themed"."award_year") AS "latest_year"
           FROM "themed"
          WHERE "themed"."is_peer"
          GROUP BY "themed"."theme", COALESCE("themed"."recipient_abn", "themed"."recipient_name")
        ), "ranked" AS (
         SELECT "agg"."theme",
            "agg"."recipient_key",
            "agg"."recipient_name",
            "agg"."recipient_abn",
            "agg"."gs_entity_id",
            "agg"."entity_type",
            "agg"."is_community_controlled",
            "agg"."n_awards",
            "agg"."total_awarded",
            "agg"."latest_year",
            "row_number"() OVER (PARTITION BY "agg"."theme" ORDER BY "agg"."total_awarded" DESC) AS "rn"
           FROM "agg"
        )
 SELECT "theme",
    "rn",
    "recipient_name",
    "recipient_abn",
    "gs_entity_id",
    "entity_type",
    "is_community_controlled",
    "n_awards",
    "total_awarded",
    "latest_year"
   FROM "ranked"
  WHERE ("rn" <= 25)
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_award_winner_by_theme" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_award_winner_by_theme" IS 'Phase 6: top 25 historical award recipients per theme (name, abn, entity_type, n_awards, total). Refresh nightly.';



