CREATE MATERIALIZED VIEW "public"."mv_board_contractor_links" AS
 SELECT "pr"."person_name",
    "pr"."person_name_normalised",
    "pr"."company_name",
    "pr"."company_abn",
    "pr"."role_type",
    "c"."total_contracts",
    "c"."contract_count",
    "c"."departments"
   FROM ("public"."person_roles" "pr"
     JOIN ( SELECT "austender_contracts"."supplier_abn",
            "sum"("austender_contracts"."contract_value") AS "total_contracts",
            "count"(*) AS "contract_count",
            "array_agg"(DISTINCT "austender_contracts"."buyer_name") AS "departments"
           FROM "public"."austender_contracts"
          WHERE (("austender_contracts"."supplier_abn" IS NOT NULL) AND ("austender_contracts"."contract_value" > (10000)::numeric))
          GROUP BY "austender_contracts"."supplier_abn") "c" ON (("c"."supplier_abn" = "pr"."company_abn")))
  WHERE ("pr"."source" = 'acnc'::"text")
  ORDER BY "c"."total_contracts" DESC
  WITH NO DATA;


