CREATE MATERIALIZED VIEW "public"."mv_entity_power_index" AS
 WITH "procurement_ids" AS (
         SELECT DISTINCT "e"."id" AS "entity_id"
           FROM ("public"."austender_contracts" "ac"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "ac"."supplier_abn")))
          WHERE ("ac"."supplier_abn" IS NOT NULL)
        ), "justice_ids" AS (
         SELECT DISTINCT "justice_funding"."gs_entity_id" AS "entity_id"
           FROM "public"."justice_funding"
          WHERE (("justice_funding"."gs_entity_id" IS NOT NULL) AND ("justice_funding"."measure_kind" = 'grant'::"text") AND ("justice_funding"."is_aggregate" IS NOT TRUE) AND ("lower"("btrim"("justice_funding"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"])))
        ), "donation_ids" AS (
         SELECT DISTINCT "e"."id" AS "entity_id"
           FROM ("public"."political_donations" "pd"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "pd"."donor_abn")))
          WHERE (("pd"."donor_abn" IS NOT NULL) AND ("pd"."receipt_type" = 'donation received'::"text"))
        ), "charity_ids" AS (
         SELECT DISTINCT "e"."id" AS "entity_id"
           FROM ("public"."acnc_charities" "ac"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "ac"."abn")))
          WHERE ("ac"."abn" IS NOT NULL)
        ), "foundation_ids" AS (
         SELECT DISTINCT "e"."id" AS "entity_id"
           FROM ("public"."foundations" "f_1"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "f_1"."acnc_abn")))
          WHERE ("f_1"."acnc_abn" IS NOT NULL)
        ), "alma_ids" AS (
         SELECT DISTINCT "alma_interventions"."gs_entity_id" AS "entity_id"
           FROM "public"."alma_interventions"
          WHERE ("alma_interventions"."gs_entity_id" IS NOT NULL)
        ), "ato_ids" AS (
         SELECT DISTINCT "e"."id" AS "entity_id"
           FROM ("public"."ato_tax_transparency" "att"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "att"."abn")))
          WHERE ("att"."abn" IS NOT NULL)
        ), "ndis_ids" AS (
         SELECT DISTINCT "e"."id" AS "entity_id"
           FROM ("public"."ndis_registered_providers" "nrp"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "nrp"."abn")))
          WHERE (("nrp"."abn" IS NOT NULL) AND ("nrp"."registration_status" = 'Approved'::"text"))
        ), "universe" AS (
         SELECT "procurement_ids"."entity_id"
           FROM "procurement_ids"
        UNION
         SELECT "justice_ids"."entity_id"
           FROM "justice_ids"
        UNION
         SELECT "donation_ids"."entity_id"
           FROM "donation_ids"
        UNION
         SELECT "charity_ids"."entity_id"
           FROM "charity_ids"
        UNION
         SELECT "foundation_ids"."entity_id"
           FROM "foundation_ids"
        UNION
         SELECT "alma_ids"."entity_id"
           FROM "alma_ids"
        UNION
         SELECT "ato_ids"."entity_id"
           FROM "ato_ids"
        UNION
         SELECT "ndis_ids"."entity_id"
           FROM "ndis_ids"
        ), "procurement" AS (
         SELECT "e"."id" AS "entity_id",
            "count"(*) AS "contract_count",
            COALESCE("sum"("ac"."contract_value"), (0)::numeric) AS "procurement_dollars",
            "count"(DISTINCT "ac"."buyer_name") AS "distinct_buyers",
            "array_agg"(DISTINCT (EXTRACT(year FROM "ac"."contract_start"))::integer ORDER BY ((EXTRACT(year FROM "ac"."contract_start"))::integer)) FILTER (WHERE ("ac"."contract_start" IS NOT NULL)) AS "procurement_years"
           FROM ("public"."austender_contracts" "ac"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "ac"."supplier_abn")))
          WHERE (("ac"."supplier_abn" IS NOT NULL) AND ("e"."id" IN ( SELECT "universe"."entity_id"
                   FROM "universe")))
          GROUP BY "e"."id"
        ), "justice" AS (
         SELECT "justice_funding"."gs_entity_id" AS "entity_id",
            "count"(*) AS "justice_count",
            COALESCE("sum"("justice_funding"."amount_dollars"), (0)::numeric) AS "justice_dollars",
            "count"(DISTINCT "justice_funding"."program_name") AS "distinct_programs",
            "array_agg"(DISTINCT "justice_funding"."state" ORDER BY "justice_funding"."state") FILTER (WHERE ("justice_funding"."state" IS NOT NULL)) AS "justice_states"
           FROM "public"."justice_funding"
          WHERE (("justice_funding"."gs_entity_id" IS NOT NULL) AND ("justice_funding"."measure_kind" = 'grant'::"text") AND ("justice_funding"."is_aggregate" IS NOT TRUE) AND ("lower"("btrim"("justice_funding"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"])) AND ("justice_funding"."gs_entity_id" IN ( SELECT "universe"."entity_id"
                   FROM "universe")))
          GROUP BY "justice_funding"."gs_entity_id"
        ), "donations" AS (
         SELECT "e"."id" AS "entity_id",
            "count"(*) AS "donation_count",
            COALESCE("sum"("pd"."amount"), (0)::numeric) AS "donation_dollars",
            "array_agg"(DISTINCT "pd"."donation_to" ORDER BY "pd"."donation_to") FILTER (WHERE ("pd"."donation_to" IS NOT NULL)) AS "parties_funded",
            "count"(DISTINCT "pd"."donation_to") AS "distinct_parties"
           FROM ("public"."political_donations" "pd"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "pd"."donor_abn")))
          WHERE (("pd"."donor_abn" IS NOT NULL) AND ("pd"."receipt_type" = 'donation received'::"text") AND ("e"."id" IN ( SELECT "universe"."entity_id"
                   FROM "universe")))
          GROUP BY "e"."id"
        ), "charity" AS (
         SELECT "e"."id" AS "entity_id",
            "ac"."charity_size",
            "ac"."purposes",
            "ac"."beneficiaries"
           FROM ("public"."acnc_charities" "ac"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "ac"."abn")))
          WHERE (("ac"."abn" IS NOT NULL) AND ("e"."id" IN ( SELECT "universe"."entity_id"
                   FROM "universe")))
        ), "foundation" AS (
         SELECT "e"."id" AS "entity_id",
            "f_1"."total_giving_annual",
            "f_1"."thematic_focus",
            "f_1"."geographic_focus"
           FROM ("public"."foundations" "f_1"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "f_1"."acnc_abn")))
          WHERE (("f_1"."acnc_abn" IS NOT NULL) AND ("e"."id" IN ( SELECT "universe"."entity_id"
                   FROM "universe")))
        ), "alma" AS (
         SELECT "alma_interventions"."gs_entity_id" AS "entity_id",
            "count"(*) AS "intervention_count",
            "array_agg"(DISTINCT "alma_interventions"."type" ORDER BY "alma_interventions"."type") FILTER (WHERE ("alma_interventions"."type" IS NOT NULL)) AS "intervention_types",
            "avg"("alma_interventions"."portfolio_score") AS "avg_evidence_score"
           FROM "public"."alma_interventions"
          WHERE (("alma_interventions"."gs_entity_id" IS NOT NULL) AND ("alma_interventions"."gs_entity_id" IN ( SELECT "universe"."entity_id"
                   FROM "universe")))
          GROUP BY "alma_interventions"."gs_entity_id"
        ), "ato" AS (
         SELECT "e"."id" AS "entity_id",
            "att"."total_income" AS "ato_total_income",
            "att"."taxable_income" AS "ato_taxable_income",
            "att"."tax_payable" AS "ato_tax_payable",
            "att"."report_year" AS "ato_year"
           FROM ("public"."ato_tax_transparency" "att"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "att"."abn")))
          WHERE (("att"."abn" IS NOT NULL) AND ("e"."id" IN ( SELECT "universe"."entity_id"
                   FROM "universe")))
        ), "ndis" AS (
         SELECT "e"."id" AS "entity_id",
            "count"(DISTINCT "nrp"."provider_detail_id") AS "ndis_provider_count",
            "array_agg"(DISTINCT "nrp"."state_code" ORDER BY "nrp"."state_code") FILTER (WHERE ("nrp"."state_code" IS NOT NULL)) AS "ndis_states"
           FROM ("public"."ndis_registered_providers" "nrp"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "nrp"."abn")))
          WHERE (("nrp"."abn" IS NOT NULL) AND ("nrp"."registration_status" = 'Approved'::"text") AND ("e"."id" IN ( SELECT "universe"."entity_id"
                   FROM "universe")))
          GROUP BY "e"."id"
        ), "boards" AS (
         SELECT "gs_relationships"."target_entity_id" AS "entity_id",
            "count"(*) AS "board_connections",
            "count"(DISTINCT "gs_relationships"."source_entity_id") AS "distinct_directors"
           FROM "public"."gs_relationships"
          WHERE (("gs_relationships"."relationship_type" = ANY (ARRAY['directorship'::"text", 'member_of'::"text"])) AND ("gs_relationships"."target_entity_id" IN ( SELECT "universe"."entity_id"
                   FROM "universe")))
          GROUP BY "gs_relationships"."target_entity_id"
        )
 SELECT "ge"."id",
    "ge"."gs_id",
    "ge"."canonical_name",
    "ge"."entity_type",
    "ge"."abn",
    "ge"."state",
    "ge"."postcode",
    "ge"."remoteness",
    "ge"."seifa_irsd_decile",
    "ge"."is_community_controlled",
    "ge"."lga_name",
    (("p"."entity_id" IS NOT NULL))::integer AS "in_procurement",
    (("j"."entity_id" IS NOT NULL))::integer AS "in_recorded_grants",
    (("d"."entity_id" IS NOT NULL))::integer AS "in_political_donations",
    (("c"."entity_id" IS NOT NULL))::integer AS "in_charity_registry",
    (("f"."entity_id" IS NOT NULL))::integer AS "in_foundation",
    (("a"."entity_id" IS NOT NULL))::integer AS "in_alma_evidence",
    (("t"."entity_id" IS NOT NULL))::integer AS "in_ato_transparency",
    (("n"."entity_id" IS NOT NULL))::integer AS "in_ndis_provider",
    (("b"."entity_id" IS NOT NULL))::integer AS "has_board_links",
    ((((((((("p"."entity_id" IS NOT NULL))::integer + (("j"."entity_id" IS NOT NULL))::integer) + (("d"."entity_id" IS NOT NULL))::integer) + (("c"."entity_id" IS NOT NULL))::integer) + (("f"."entity_id" IS NOT NULL))::integer) + (("a"."entity_id" IS NOT NULL))::integer) + (("t"."entity_id" IS NOT NULL))::integer) + (("n"."entity_id" IS NOT NULL))::integer) AS "system_count",
    COALESCE("p"."procurement_dollars", (0)::numeric) AS "procurement_dollars",
    COALESCE("j"."justice_dollars", (0)::numeric) AS "recorded_grants_dollars",
    COALESCE("d"."donation_dollars", (0)::numeric) AS "donation_dollars",
    COALESCE("f"."total_giving_annual", (0)::numeric) AS "foundation_giving",
    COALESCE("t"."ato_total_income", (0)::numeric) AS "ato_income",
    ((COALESCE("p"."procurement_dollars", (0)::numeric) + COALESCE("j"."justice_dollars", (0)::numeric)) + COALESCE("d"."donation_dollars", (0)::numeric)) AS "total_dollar_flow",
    COALESCE("p"."contract_count", (0)::bigint) AS "contract_count",
    COALESCE("j"."justice_count", (0)::bigint) AS "recorded_grants_count",
    COALESCE("d"."donation_count", (0)::bigint) AS "donation_count",
    COALESCE("a"."intervention_count", (0)::bigint) AS "alma_intervention_count",
    COALESCE("n"."ndis_provider_count", (0)::bigint) AS "ndis_provider_count",
    COALESCE("b"."board_connections", (0)::bigint) AS "board_connections",
    COALESCE("p"."distinct_buyers", (0)::bigint) AS "distinct_govt_buyers",
    COALESCE("j"."distinct_programs", (0)::bigint) AS "distinct_grant_programs",
    COALESCE("d"."distinct_parties", (0)::bigint) AS "distinct_parties_funded",
    COALESCE("b"."distinct_directors", (0)::bigint) AS "distinct_directors",
    "c"."charity_size",
    "d"."parties_funded",
    "a"."intervention_types" AS "alma_types",
    "a"."avg_evidence_score",
    "j"."justice_states" AS "recorded_grants_states",
    "n"."ndis_states",
    ((((((((((((("p"."entity_id" IS NOT NULL))::integer * 2) + ((("j"."entity_id" IS NOT NULL))::integer * 2)) + ((("d"."entity_id" IS NOT NULL))::integer * 3)) + ((("c"."entity_id" IS NOT NULL))::integer * 1)) + ((("f"."entity_id" IS NOT NULL))::integer * 2)) + ((("a"."entity_id" IS NOT NULL))::integer * 1)) + ((("t"."entity_id" IS NOT NULL))::integer * 1)) + ((("n"."entity_id" IS NOT NULL))::integer * 2)) + LEAST(COALESCE("b"."board_connections", (0)::bigint), (5)::bigint)) +
        CASE
            WHEN (COALESCE("p"."procurement_dollars", (0)::numeric) > (10000000)::numeric) THEN 2
            WHEN (COALESCE("p"."procurement_dollars", (0)::numeric) > (1000000)::numeric) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE("d"."donation_dollars", (0)::numeric) > (100000)::numeric) THEN 2
            WHEN (COALESCE("d"."donation_dollars", (0)::numeric) > (10000)::numeric) THEN 1
            ELSE 0
        END) AS "power_score"
   FROM (((((((((("universe" "u"
     JOIN "public"."gs_entities" "ge" ON (("ge"."id" = "u"."entity_id")))
     LEFT JOIN "procurement" "p" ON (("p"."entity_id" = "u"."entity_id")))
     LEFT JOIN "justice" "j" ON (("j"."entity_id" = "u"."entity_id")))
     LEFT JOIN "donations" "d" ON (("d"."entity_id" = "u"."entity_id")))
     LEFT JOIN "charity" "c" ON (("c"."entity_id" = "u"."entity_id")))
     LEFT JOIN "foundation" "f" ON (("f"."entity_id" = "u"."entity_id")))
     LEFT JOIN "alma" "a" ON (("a"."entity_id" = "u"."entity_id")))
     LEFT JOIN LATERAL ( SELECT "ato"."entity_id",
            "ato"."ato_total_income",
            "ato"."ato_taxable_income",
            "ato"."ato_tax_payable",
            "ato"."ato_year"
           FROM "ato"
          WHERE ("ato"."entity_id" = "u"."entity_id")
          ORDER BY "ato"."ato_year" DESC
         LIMIT 1) "t" ON (true))
     LEFT JOIN "ndis" "n" ON (("n"."entity_id" = "u"."entity_id")))
     LEFT JOIN "boards" "b" ON (("b"."entity_id" = "u"."entity_id")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_entity_power_index" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_entity_power_index" IS 'Cross-system power concentration. recorded_grants_* columns hold money from the justice_funding TABLE — a grants register, not a justice figure. Renamed from justice_* 2026-08-16. Money filters applied at all four sites the same day. See thoughts/shared/data-map/justice-funding-filter-audit.md';



COMMENT ON COLUMN "public"."mv_entity_power_index"."in_recorded_grants" IS 'Presence in the recorded-grants register after mandatory filters.';



CREATE MATERIALIZED VIEW "public"."mv_board_interlocks" AS
 WITH "multi_board_persons" AS (
         SELECT "person_roles"."person_name_normalised"
           FROM "public"."person_roles"
          WHERE (("person_roles"."person_name_normalised" IS NOT NULL) AND ("person_roles"."person_name_normalised" <> ''::"text") AND ("person_roles"."company_abn" IS NOT NULL))
          GROUP BY "person_roles"."person_name_normalised"
         HAVING ("count"(DISTINCT "person_roles"."company_abn") >= 2)
        ), "person_summary" AS (
         SELECT "pr"."person_name_normalised",
            "min"("pr"."person_name") AS "person_name_display",
            "count"(DISTINCT "pr"."company_abn") AS "board_count",
            "array_agg"(DISTINCT "pr"."company_name" ORDER BY "pr"."company_name") AS "organisations",
            "array_agg"(DISTINCT "pr"."company_abn" ORDER BY "pr"."company_abn") AS "organisation_abns",
            "array_agg"(DISTINCT "pr"."entity_id") FILTER (WHERE ("pr"."entity_id" IS NOT NULL)) AS "entity_ids",
            "array_agg"(DISTINCT "pr"."role_type" ORDER BY "pr"."role_type") AS "role_types",
            "array_agg"(DISTINCT "pr"."source" ORDER BY "pr"."source") AS "sources"
           FROM ("public"."person_roles" "pr"
             JOIN "multi_board_persons" "mb" ON (("mb"."person_name_normalised" = "pr"."person_name_normalised")))
          WHERE ("pr"."company_abn" IS NOT NULL)
          GROUP BY "pr"."person_name_normalised"
        )
 SELECT "ps"."person_name_normalised",
    "ps"."person_name_display",
    "ps"."board_count",
    "ps"."organisations",
    "ps"."organisation_abns",
    "ps"."entity_ids",
    "ps"."role_types",
    "ps"."sources",
    COALESCE("pi_agg"."total_procurement_dollars", (0)::numeric) AS "total_procurement_dollars",
    COALESCE("pi_agg"."total_justice_dollars", (0)::numeric) AS "total_justice_dollars",
    COALESCE("pi_agg"."total_donation_dollars", (0)::numeric) AS "total_donation_dollars",
    COALESCE("pi_agg"."max_system_count", 0) AS "max_entity_system_count",
    COALESCE("pi_agg"."sum_power_score", (0)::numeric) AS "total_power_score",
    COALESCE("pi_agg"."has_community_controlled", false) AS "connects_community_controlled",
    (((("ps"."board_count")::numeric * "ln"((GREATEST(((COALESCE("pi_agg"."total_procurement_dollars", (0)::numeric) + COALESCE("pi_agg"."total_justice_dollars", (0)::numeric)) + COALESCE("pi_agg"."total_donation_dollars", (0)::numeric)), (0)::numeric) + (1)::numeric))) * (GREATEST(COALESCE("pi_agg"."max_system_count", 1), 1))::numeric))::numeric(12,2) AS "interlock_score"
   FROM ("person_summary" "ps"
     LEFT JOIN LATERAL ( SELECT "sum"("pi"."procurement_dollars") AS "total_procurement_dollars",
            "sum"("pi"."recorded_grants_dollars") AS "total_justice_dollars",
            "sum"("pi"."donation_dollars") AS "total_donation_dollars",
            "max"("pi"."system_count") AS "max_system_count",
            "sum"("pi"."power_score") AS "sum_power_score",
            "bool_or"("pi"."is_community_controlled") AS "has_community_controlled"
           FROM "public"."mv_entity_power_index" "pi"
          WHERE ("pi"."id" = ANY ("ps"."entity_ids"))) "pi_agg" ON (true))
  ORDER BY ((((("ps"."board_count")::numeric * "ln"((GREATEST(((COALESCE("pi_agg"."total_procurement_dollars", (0)::numeric) + COALESCE("pi_agg"."total_justice_dollars", (0)::numeric)) + COALESCE("pi_agg"."total_donation_dollars", (0)::numeric)), (0)::numeric) + (1)::numeric))) * (GREATEST(COALESCE("pi_agg"."max_system_count", 1), 1))::numeric))::numeric(12,2)) DESC NULLS LAST
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_board_interlocks" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_board_power" AS
 WITH "board_counts" AS (
         SELECT "pr"."person_name",
            "count"(DISTINCT "pr"."company_abn") AS "board_seats",
            "array_agg"(DISTINCT "e"."canonical_name" ORDER BY "e"."canonical_name") AS "organizations",
            "array_agg"(DISTINCT "e"."sector") FILTER (WHERE ("e"."sector" IS NOT NULL)) AS "sectors",
            "array_agg"(DISTINCT "e"."state") FILTER (WHERE ("e"."state" IS NOT NULL)) AS "states"
           FROM ("public"."person_roles" "pr"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "pr"."company_abn")))
          WHERE (("pr"."cessation_date" IS NULL) AND ("pr"."person_name" IS NOT NULL) AND ("pr"."person_name" <> ''::"text"))
          GROUP BY "pr"."person_name"
         HAVING ("count"(DISTINCT "pr"."company_abn") >= 2)
        ), "financials" AS (
         SELECT "pr"."person_name",
            "sum"("a"."total_gross_income") AS "total_org_revenue",
            "sum"("a"."total_assets") AS "total_org_assets",
            "sum"("a"."staff_fte") AS "total_org_fte"
           FROM ("public"."person_roles" "pr"
             JOIN "public"."acnc_ais" "a" ON ((("a"."abn" = "pr"."company_abn") AND ("a"."ais_year" = 2023))))
          WHERE (("pr"."cessation_date" IS NULL) AND ("pr"."person_name" IS NOT NULL))
          GROUP BY "pr"."person_name"
        )
 SELECT "bc"."person_name",
    "bc"."board_seats",
    COALESCE("f"."total_org_revenue", (0)::numeric) AS "total_org_revenue",
    COALESCE("f"."total_org_assets", (0)::numeric) AS "total_org_assets",
    COALESCE("f"."total_org_fte", (0)::numeric) AS "total_org_fte",
    "bc"."organizations",
    "bc"."sectors",
    "bc"."states",
    "rank"() OVER (ORDER BY "bc"."board_seats" DESC, COALESCE("f"."total_org_revenue", (0)::numeric) DESC) AS "rank_seats",
    "rank"() OVER (ORDER BY COALESCE("f"."total_org_revenue", (0)::numeric) DESC, "bc"."board_seats" DESC) AS "rank_revenue"
   FROM ("board_counts" "bc"
     LEFT JOIN "financials" "f" ON (("f"."person_name" = "bc"."person_name")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_board_power" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_charity_browse" AS
 SELECT "c"."abn",
    "c"."name",
    "c"."charity_size",
    "c"."state",
    "c"."is_foundation",
    "p"."gs_id",
    "p"."system_count",
    "p"."total_dollar_flow",
    "a"."ais_year",
    "a"."total_assets",
    (((((("c"."charity_size" IS NOT NULL))::integer + (("c"."state" IS NOT NULL))::integer) + (("p"."gs_id" IS NOT NULL))::integer) + (("a"."ais_year" IS NOT NULL))::integer) + (("p"."total_dollar_flow" > (0)::numeric))::integer) AS "known_score"
   FROM (("public"."acnc_charities" "c"
     LEFT JOIN LATERAL ( SELECT "e"."gs_id",
            "e"."system_count",
            "e"."total_dollar_flow"
           FROM "public"."mv_entity_power_index" "e"
          WHERE ("e"."abn" = "c"."abn")
         LIMIT 1) "p" ON (true))
     LEFT JOIN LATERAL ( SELECT "x"."ais_year",
            "x"."total_assets"
           FROM "public"."acnc_ais" "x"
          WHERE ("x"."abn" = "c"."abn")
          ORDER BY "x"."ais_year" DESC
         LIMIT 1) "a" ON (true))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_charity_browse" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_charity_network" AS
 SELECT "e"."abn",
    ("count"(DISTINCT "r"."target_entity_id") FILTER (WHERE ("r"."source_entity_id" = "e"."id")) + "count"(DISTINCT "r"."source_entity_id") FILTER (WHERE ("r"."target_entity_id" = "e"."id"))) AS "network_connections"
   FROM ("public"."gs_entities" "e"
     LEFT JOIN "public"."gs_relationships" "r" ON (((("r"."source_entity_id" = "e"."id") OR ("r"."target_entity_id" = "e"."id")) AND ("r"."relationship_type" = 'shared_director'::"text"))))
  WHERE ("e"."abn" IS NOT NULL)
  GROUP BY "e"."abn", "e"."id"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_charity_network" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_charity_rankings" AS
 WITH "latest" AS (
         SELECT "a"."abn",
            "a"."charity_name" AS "name",
            "a"."charity_size",
            "a"."total_gross_income" AS "revenue",
            "a"."total_expenses" AS "expenses",
            "a"."total_assets" AS "assets",
            "a"."net_surplus_deficit" AS "surplus",
            "a"."staff_fte" AS "fte",
            "a"."staff_volunteers" AS "volunteers",
                CASE
                    WHEN (NULLIF("a"."staff_fte", (0)::numeric) > (0)::numeric) THEN (("a"."staff_volunteers")::numeric / "a"."staff_fte")
                    ELSE (0)::numeric
                END AS "vol_fte_ratio",
                CASE
                    WHEN (NULLIF("a"."staff_fte", (0)::numeric) > (0)::numeric) THEN ("a"."total_gross_income" / "a"."staff_fte")
                    ELSE (0)::numeric
                END AS "rev_per_fte"
           FROM "public"."acnc_ais" "a"
          WHERE (("a"."ais_year" = 2023) AND ("a"."total_gross_income" > (0)::numeric))
        ), "growth" AS (
         SELECT "curr"."abn",
                CASE
                    WHEN (("base"."total_gross_income" > (0)::numeric) AND ("curr"."total_gross_income" > (0)::numeric)) THEN (("power"((("curr"."total_gross_income")::double precision / ("base"."total_gross_income")::double precision), ((1.0 / (5)::numeric))::double precision) - (1)::double precision) * (100)::double precision)
                    ELSE (0)::double precision
                END AS "cagr"
           FROM ("public"."acnc_ais" "curr"
             JOIN "public"."acnc_ais" "base" ON ((("curr"."abn" = "base"."abn") AND ("base"."ais_year" = 2018))))
          WHERE (("curr"."ais_year" = 2023) AND ("curr"."total_gross_income" > (0)::numeric))
        ), "maxvals" AS (
         SELECT "max"("latest"."revenue") AS "max_revenue"
           FROM "latest"
          WHERE ("latest"."revenue" > (0)::numeric)
        ), "scored" AS (
         SELECT "l"."abn",
            "l"."name",
            "e"."gs_id",
            "e"."id" AS "entity_id",
            "e"."entity_type",
            "e"."sector",
            "e"."state",
            "e"."is_community_controlled",
            "l"."charity_size",
            "l"."revenue",
            "l"."expenses",
            "l"."assets",
            "l"."surplus",
            "l"."fte",
            "l"."volunteers",
            "l"."vol_fte_ratio",
            "l"."rev_per_fte",
            COALESCE("g"."cagr", (0)::double precision) AS "cagr",
            COALESCE("n"."network_connections", (0)::bigint) AS "network_connections",
            LEAST((100)::numeric,
                CASE
                    WHEN (("l"."revenue" > (0)::numeric) AND ("m"."max_revenue" > (0)::numeric)) THEN (("log"("l"."revenue") / "log"("m"."max_revenue")) * (100)::numeric)
                    ELSE (0)::numeric
                END) AS "score_revenue",
            LEAST((100)::double precision, GREATEST((0)::double precision, (COALESCE("g"."cagr", (0)::double precision) * (2.5)::double precision))) AS "score_growth",
            LEAST((100)::numeric, ("l"."vol_fte_ratio" * (2)::numeric)) AS "score_leverage",
            LEAST((100)::numeric, (("l"."rev_per_fte" / (500000)::numeric) * (100)::numeric)) AS "score_efficiency",
            LEAST((100)::bigint, (COALESCE("n"."network_connections", (0)::bigint) * 5)) AS "score_network",
            LEAST((100)::numeric, GREATEST((0)::numeric,
                CASE
                    WHEN (NULLIF("l"."revenue", (0)::numeric) > (0)::numeric) THEN ((("l"."surplus" / "l"."revenue") + 0.1) * (200)::numeric)
                    ELSE (0)::numeric
                END)) AS "score_health"
           FROM (((("latest" "l"
             CROSS JOIN "maxvals" "m")
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "l"."abn")))
             LEFT JOIN "growth" "g" ON (("g"."abn" = "l"."abn")))
             LEFT JOIN "public"."mv_charity_network" "n" ON (("n"."abn" = "l"."abn")))
          WHERE ("e"."entity_type" = ANY (ARRAY['charity'::"text", 'foundation'::"text", 'social_enterprise'::"text", 'company'::"text", 'trust'::"text", 'association'::"text", 'cooperative'::"text"]))
        )
 SELECT "abn",
    "name",
    "gs_id",
    "entity_id",
    "entity_type",
    "sector",
    "state",
    "is_community_controlled",
    "charity_size",
    "revenue",
    "expenses",
    "assets",
    "surplus",
    "fte",
    "volunteers",
    "vol_fte_ratio",
    "rev_per_fte",
    "cagr",
    "network_connections",
    "score_revenue",
    "score_growth",
    "score_leverage",
    "score_efficiency",
    "score_network",
    "score_health",
    "round"((((((((("score_revenue" * 0.25))::double precision + ("score_growth" * (0.25)::double precision)) + (("score_leverage" * 0.15))::double precision) + (("score_efficiency" * 0.10))::double precision) + ((("score_network")::numeric * 0.15))::double precision) + (("score_health" * 0.10))::double precision))::numeric, 1) AS "score_composite",
    "rank"() OVER (ORDER BY ((((((("score_revenue" * 0.25))::double precision + ("score_growth" * (0.25)::double precision)) + (("score_leverage" * 0.15))::double precision) + (("score_efficiency" * 0.10))::double precision) + ((("score_network")::numeric * 0.15))::double precision) + (("score_health" * 0.10))::double precision) DESC) AS "rank_composite",
    "rank"() OVER (ORDER BY "revenue" DESC NULLS LAST) AS "rank_revenue",
    "rank"() OVER (ORDER BY "cagr" DESC NULLS LAST) AS "rank_growth",
    "rank"() OVER (ORDER BY "vol_fte_ratio" DESC NULLS LAST) AS "rank_leverage",
    "rank"() OVER (ORDER BY "network_connections" DESC NULLS LAST) AS "rank_network",
    "rank"() OVER (ORDER BY "fte" DESC NULLS LAST) AS "rank_fte",
    "rank"() OVER (ORDER BY "volunteers" DESC NULLS LAST) AS "rank_volunteers",
    "count"(*) OVER () AS "total_ranked"
   FROM "scored" "s"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_charity_rankings" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_clarity_flow" AS
 SELECT COALESCE("s"."entity_type", 'unknown'::"text") AS "source_type",
    COALESCE("t"."entity_type", 'unknown'::"text") AS "target_type",
    COALESCE("r"."relationship_type", 'unknown'::"text") AS "relationship_type",
    "count"(*) AS "edges",
    "count"(*) FILTER (WHERE ("r"."amount" IS NOT NULL)) AS "edges_with_amount",
    "sum"("r"."amount") AS "amount_recorded",
    "count"(*) FILTER (WHERE ("r"."year" IS NOT NULL)) AS "edges_with_year",
    "count"(DISTINCT "r"."source_entity_id") AS "distinct_sources",
    "count"(DISTINCT "r"."target_entity_id") AS "distinct_targets",
    "min"("r"."year") AS "year_min",
    "max"("r"."year") AS "year_max"
   FROM (("public"."gs_relationships" "r"
     JOIN "public"."gs_entities" "s" ON (("s"."id" = "r"."source_entity_id")))
     JOIN "public"."gs_entities" "t" ON (("t"."id" = "r"."target_entity_id")))
  GROUP BY COALESCE("s"."entity_type", 'unknown'::"text"), COALESCE("t"."entity_type", 'unknown'::"text"), COALESCE("r"."relationship_type", 'unknown'::"text")
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_clarity_flow" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_clarity_flow" IS 'How kinds of organisation move money to kinds of organisation. edges is complete; amount_recorded is a FLOOR, not a total, because gs_relationships.amount is ~77% populated. edges_with_amount and edges_with_year exist so no cell can print a number that reads as complete when it is not.';



