CREATE MATERIALIZED VIEW "public"."mv_donor_contract_crossref" AS
 SELECT "d"."donor_abn",
    "d"."primary_donor_name" AS "donor_name",
    "d"."total_donated",
    "d"."donation_count",
    "d"."parties_donated_to",
    "d"."name_variants",
    "c"."contract_count",
    "c"."total_contract_value",
    "c"."buyers"
   FROM (( SELECT "sub"."donor_abn",
            ("array_agg"("sub"."donor_name" ORDER BY "sub"."cnt" DESC))[1] AS "primary_donor_name",
            "sum"("sub"."total_amount") AS "total_donated",
            "sum"("sub"."cnt") AS "donation_count",
            "string_agg"(DISTINCT "sub"."party", ', '::"text" ORDER BY "sub"."party") AS "parties_donated_to",
            ("count"(DISTINCT "sub"."donor_name"))::integer AS "name_variants"
           FROM ( SELECT "political_donations"."donor_abn",
                    "political_donations"."donor_name",
                    "sum"("political_donations"."amount") AS "total_amount",
                    "count"(*) AS "cnt",
                    "unnest"("array_agg"(DISTINCT "political_donations"."donation_to")) AS "party"
                   FROM "public"."political_donations"
                  WHERE (("political_donations"."donor_abn" IS NOT NULL) AND ("political_donations"."donor_abn" <> ''::"text") AND ("political_donations"."donor_abn" <> '0'::"text"))
                  GROUP BY "political_donations"."donor_abn", "political_donations"."donor_name") "sub"
          GROUP BY "sub"."donor_abn") "d"
     JOIN ( SELECT "austender_contracts"."supplier_abn",
            "count"(*) AS "contract_count",
            "sum"("austender_contracts"."contract_value") AS "total_contract_value",
            "string_agg"(DISTINCT "austender_contracts"."buyer_name", ', '::"text" ORDER BY "austender_contracts"."buyer_name") AS "buyers"
           FROM "public"."austender_contracts"
          WHERE (("austender_contracts"."supplier_abn" IS NOT NULL) AND ("austender_contracts"."supplier_abn" <> ''::"text"))
          GROUP BY "austender_contracts"."supplier_abn") "c" ON (("d"."donor_abn" = "c"."supplier_abn")))
  ORDER BY "d"."total_donated" DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_donor_contract_crossref" OWNER TO "postgres";


