CREATE MATERIALIZED VIEW "public"."mv_crossref_quality" AS
 SELECT 'grant→foundation'::"text" AS "link_type",
    ("count"(*))::integer AS "total",
    ("count"(*) FILTER (WHERE ("grant_opportunities"."foundation_id" IS NOT NULL)))::integer AS "linked",
    "round"(((100.0 * ("count"(*) FILTER (WHERE ("grant_opportunities"."foundation_id" IS NOT NULL)))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_linked"
   FROM "public"."grant_opportunities"
UNION ALL
 SELECT 'donation→entity_match'::"text" AS "link_type",
    (( SELECT "count"(DISTINCT "political_donations"."donor_name") AS "count"
           FROM "public"."political_donations"))::integer AS "total",
    (( SELECT "count"(*) AS "count"
           FROM "public"."donor_entity_matches"))::integer AS "linked",
    "round"(((100.0 * (( SELECT "count"(*) AS "count"
           FROM "public"."donor_entity_matches"))::numeric) / (NULLIF(( SELECT "count"(DISTINCT "political_donations"."donor_name") AS "count"
           FROM "public"."political_donations"), 0))::numeric), 1) AS "pct_linked"
UNION ALL
 SELECT 'donation→contract'::"text" AS "link_type",
    (( SELECT "count"(DISTINCT "political_donations"."donor_abn") AS "count"
           FROM "public"."political_donations"
          WHERE (("political_donations"."donor_abn" IS NOT NULL) AND ("political_donations"."donor_abn" <> ''::"text") AND ("political_donations"."donor_abn" <> '0'::"text"))))::integer AS "total",
    (( SELECT "count"(*) AS "count"
           FROM "public"."mv_donor_contract_crossref"))::integer AS "linked",
    "round"(((100.0 * (( SELECT "count"(*) AS "count"
           FROM "public"."mv_donor_contract_crossref"))::numeric) / (NULLIF(( SELECT "count"(DISTINCT "political_donations"."donor_abn") AS "count"
           FROM "public"."political_donations"
          WHERE (("political_donations"."donor_abn" IS NOT NULL) AND ("political_donations"."donor_abn" <> ''::"text") AND ("political_donations"."donor_abn" <> '0'::"text"))), 0))::numeric), 1) AS "pct_linked"
UNION ALL
 SELECT 'oric→acnc'::"text" AS "link_type",
    (( SELECT "count"(*) AS "count"
           FROM "public"."oric_corporations"
          WHERE ("oric_corporations"."status" = 'Registered'::"text")))::integer AS "total",
    (( SELECT "count"(*) AS "count"
           FROM "public"."oric_corporations"
          WHERE (("oric_corporations"."status" = 'Registered'::"text") AND ("oric_corporations"."abn" IS NOT NULL) AND ("oric_corporations"."abn" <> ''::"text") AND (EXISTS ( SELECT 1
                   FROM "public"."acnc_charities" "c"
                  WHERE ("c"."abn" = "oric_corporations"."abn"))))))::integer AS "linked",
    "round"(((100.0 * (( SELECT "count"(*) AS "count"
           FROM "public"."oric_corporations"
          WHERE (("oric_corporations"."status" = 'Registered'::"text") AND ("oric_corporations"."abn" IS NOT NULL) AND ("oric_corporations"."abn" <> ''::"text") AND (EXISTS ( SELECT 1
                   FROM "public"."acnc_charities" "c"
                  WHERE ("c"."abn" = "oric_corporations"."abn"))))))::numeric) / (NULLIF(( SELECT "count"(*) AS "count"
           FROM "public"."oric_corporations"
          WHERE ("oric_corporations"."status" = 'Registered'::"text")), 0))::numeric), 1) AS "pct_linked"
  WITH NO DATA;


