CREATE MATERIALIZED VIEW "public"."mv_data_quality" AS
 SELECT 'foundations'::"text" AS "dataset",
    ("count"(*))::integer AS "total_records",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("foundations"."name" IS NOT NULL) AND ("foundations"."name" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_name",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("foundations"."description" IS NOT NULL) AND ("foundations"."description" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_description",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("foundations"."website" IS NOT NULL) AND ("foundations"."website" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_website",
    NULL::numeric AS "pct_abn",
    NULL::numeric AS "pct_amount",
    NULL::numeric AS "pct_geo"
   FROM "public"."foundations"
UNION ALL
 SELECT 'grant_opportunities'::"text" AS "dataset",
    ("count"(*))::integer AS "total_records",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("grant_opportunities"."name" IS NOT NULL) AND ("grant_opportunities"."name" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_name",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("grant_opportunities"."description" IS NOT NULL) AND ("grant_opportunities"."description" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_description",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("grant_opportunities"."url" IS NOT NULL) AND ("grant_opportunities"."url" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_website",
    NULL::numeric AS "pct_abn",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("grant_opportunities"."amount_max" IS NOT NULL) AND ("grant_opportunities"."amount_max" > 0))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_amount",
    NULL::numeric AS "pct_geo"
   FROM "public"."grant_opportunities"
  WHERE ("grant_opportunities"."source" <> 'ghl_sync'::"text")
UNION ALL
 SELECT 'acnc_charities'::"text" AS "dataset",
    ("count"(*))::integer AS "total_records",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("acnc_charities"."name" IS NOT NULL) AND ("acnc_charities"."name" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_name",
    NULL::numeric AS "pct_description",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("acnc_charities"."website" IS NOT NULL) AND ("acnc_charities"."website" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_website",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("acnc_charities"."abn" IS NOT NULL) AND ("acnc_charities"."abn" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_abn",
    NULL::numeric AS "pct_amount",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("acnc_charities"."postcode" IS NOT NULL) AND ("acnc_charities"."postcode" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_geo"
   FROM "public"."acnc_charities"
UNION ALL
 SELECT 'oric_corporations'::"text" AS "dataset",
    ("count"(*))::integer AS "total_records",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("oric_corporations"."name" IS NOT NULL) AND ("oric_corporations"."name" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_name",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("oric_corporations"."enriched_description" IS NOT NULL) AND ("oric_corporations"."enriched_description" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_description",
    NULL::numeric AS "pct_website",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("oric_corporations"."abn" IS NOT NULL) AND ("oric_corporations"."abn" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_abn",
    NULL::numeric AS "pct_amount",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("oric_corporations"."state" IS NOT NULL) AND ("oric_corporations"."state" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_geo"
   FROM "public"."oric_corporations"
UNION ALL
 SELECT 'political_donations'::"text" AS "dataset",
    ("count"(*))::integer AS "total_records",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("political_donations"."donor_name" IS NOT NULL) AND ("political_donations"."donor_name" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_name",
    NULL::numeric AS "pct_description",
    NULL::numeric AS "pct_website",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("political_donations"."donor_abn" IS NOT NULL) AND ("political_donations"."donor_abn" <> ''::"text") AND ("political_donations"."donor_abn" <> '0'::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_abn",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("political_donations"."amount" IS NOT NULL) AND ("political_donations"."amount" > (0)::numeric))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_amount",
    NULL::numeric AS "pct_geo"
   FROM "public"."political_donations"
UNION ALL
 SELECT 'austender_contracts'::"text" AS "dataset",
    ("count"(*))::integer AS "total_records",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("austender_contracts"."supplier_name" IS NOT NULL) AND ("austender_contracts"."supplier_name" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_name",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("austender_contracts"."description" IS NOT NULL) AND ("austender_contracts"."description" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_description",
    NULL::numeric AS "pct_website",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("austender_contracts"."supplier_abn" IS NOT NULL) AND ("austender_contracts"."supplier_abn" <> ''::"text"))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_abn",
    "round"(((100.0 * ("count"(*) FILTER (WHERE (("austender_contracts"."contract_value" IS NOT NULL) AND ("austender_contracts"."contract_value" > (0)::numeric))))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "pct_amount",
    NULL::numeric AS "pct_geo"
   FROM "public"."austender_contracts"
  WITH NO DATA;


