CREATE MATERIALIZED VIEW "public"."mv_funding_by_lga" AS
 SELECT "e"."lga_name",
    "e"."lga_code",
    "e"."state",
    "count"(DISTINCT "e"."id") AS "entity_count",
    "count"(DISTINCT
        CASE
            WHEN "e"."is_community_controlled" THEN "e"."id"
            ELSE NULL::"uuid"
        END) AS "community_controlled_count",
    COALESCE("sum"("r"."amount"), (0)::numeric) AS "total_funding",
    "count"(DISTINCT "r"."id") AS "relationship_count",
    "avg"("e"."seifa_irsd_decile") AS "avg_seifa_decile"
   FROM ("public"."gs_entities" "e"
     LEFT JOIN "public"."gs_relationships" "r" ON ((("r"."target_entity_id" = "e"."id") AND ("r"."relationship_type" = ANY (ARRAY['donation'::"text", 'contract'::"text", 'grant'::"text"])))))
  WHERE ("e"."lga_name" IS NOT NULL)
  GROUP BY "e"."lga_name", "e"."lga_code", "e"."state"
  ORDER BY ("count"(DISTINCT "e"."id")) DESC
  WITH NO DATA;


