CREATE MATERIALIZED VIEW "public"."mv_disability_landscape" AS
 WITH "ndis_by_lga" AS (
         SELECT "regexp_replace"("ndis_participants_lga"."lga_name", ' \([^)]*\)(\s*\([^)]*\))?$'::"text", ''::"text") AS "lga_name",
            "ndis_participants_lga"."state",
            "sum"("ndis_participants_lga"."participant_count") AS "ndis_participants"
           FROM "public"."ndis_participants_lga"
          WHERE ("ndis_participants_lga"."quarter_date" = ( SELECT "max"("ndis_participants_lga_1"."quarter_date") AS "max"
                   FROM "public"."ndis_participants_lga" "ndis_participants_lga_1"))
          GROUP BY ("regexp_replace"("ndis_participants_lga"."lga_name", ' \([^)]*\)(\s*\([^)]*\))?$'::"text", ''::"text")), "ndis_participants_lga"."state"
        ), "disability_entities" AS (
         SELECT "regexp_replace"("ge"."lga_name", ' \([^)]*\)$'::"text", ''::"text") AS "lga_name",
            "upper"("ge"."state") AS "state",
            "count"(*) AS "civicgraph_disability_entities",
            "count"(*) FILTER (WHERE "ge"."is_community_controlled") AS "community_controlled_disability",
            "sum"(
                CASE
                    WHEN ("pi"."in_recorded_grants" = 1) THEN 1
                    ELSE 0
                END) AS "also_in_justice",
            "sum"(
                CASE
                    WHEN ("pi"."in_procurement" = 1) THEN 1
                    ELSE 0
                END) AS "also_in_procurement",
            "avg"("pi"."system_count") AS "avg_system_count"
           FROM (("public"."gs_entities" "ge"
             JOIN "public"."ndis_registered_providers" "nrp" ON (("nrp"."abn" = "ge"."abn")))
             LEFT JOIN "public"."mv_entity_power_index" "pi" ON (("pi"."id" = "ge"."id")))
          WHERE ("ge"."lga_name" IS NOT NULL)
          GROUP BY ("regexp_replace"("ge"."lga_name", ' \([^)]*\)$'::"text", ''::"text")), ("upper"("ge"."state"))
        ), "utilisation_by_state" AS (
         SELECT "ndis_utilisation"."state",
            "avg"("ndis_utilisation"."utilisation_rate") FILTER (WHERE (("ndis_utilisation"."disability_type" = 'ALL'::"text") AND ("ndis_utilisation"."age_group" = 'ALL'::"text") AND ("ndis_utilisation"."support_class" = 'ALL'::"text") AND ("ndis_utilisation"."service_district" <> 'ALL'::"text"))) AS "overall_utilisation",
            "min"("ndis_utilisation"."utilisation_rate") FILTER (WHERE (("ndis_utilisation"."disability_type" = 'ALL'::"text") AND ("ndis_utilisation"."age_group" = 'ALL'::"text") AND ("ndis_utilisation"."support_class" = 'ALL'::"text") AND ("ndis_utilisation"."service_district" <> 'ALL'::"text"))) AS "min_utilisation"
           FROM "public"."ndis_utilisation"
          WHERE ("ndis_utilisation"."quarter_date" = ( SELECT "max"("ndis_utilisation_1"."quarter_date") AS "max"
                   FROM "public"."ndis_utilisation" "ndis_utilisation_1"))
          GROUP BY "ndis_utilisation"."state"
        ), "first_nations_by_state" AS (
         SELECT "ndis_first_nations"."state",
            "sum"("ndis_first_nations"."participant_count") FILTER (WHERE ("ndis_first_nations"."remoteness" = 'All'::"text")) AS "fn_total_participants",
            "sum"("ndis_first_nations"."participant_count") FILTER (WHERE ("ndis_first_nations"."remoteness" = 'Very Remote'::"text")) AS "fn_very_remote_participants",
            "avg"("ndis_first_nations"."avg_annualised_support") FILTER (WHERE ("ndis_first_nations"."remoteness" = 'All'::"text")) AS "fn_avg_budget",
            "avg"("ndis_first_nations"."avg_annualised_support") FILTER (WHERE ("ndis_first_nations"."remoteness" = 'Very Remote'::"text")) AS "fn_very_remote_avg_budget"
           FROM "public"."ndis_first_nations"
          WHERE ("ndis_first_nations"."quarter_date" = ( SELECT "max"("ndis_first_nations_1"."quarter_date") AS "max"
                   FROM "public"."ndis_first_nations" "ndis_first_nations_1"))
          GROUP BY "ndis_first_nations"."state"
        ), "alma_disability" AS (
         SELECT COALESCE("ge"."lga_name", 'Unknown'::"text") AS "lga_name",
            COALESCE("ge"."state", 'Unknown'::"text") AS "state",
            "count"(*) AS "disability_interventions",
            "avg"("ai"."portfolio_score") AS "avg_evidence_score"
           FROM ("public"."alma_interventions" "ai"
             LEFT JOIN "public"."gs_entities" "ge" ON (("ge"."id" = "ai"."gs_entity_id")))
          WHERE (("ai"."topics" @> ARRAY['ndis'::"text"]) OR ("ai"."name" ~~* '%disab%'::"text") OR ("ai"."description" ~~* '%disab%'::"text") OR (("ai"."target_cohort")::"text" ~~* '%disab%'::"text"))
          GROUP BY COALESCE("ge"."lga_name", 'Unknown'::"text"), COALESCE("ge"."state", 'Unknown'::"text")
        ), "desert" AS (
         SELECT DISTINCT ON ("mv_funding_deserts"."lga_name", ("upper"("mv_funding_deserts"."state"))) "mv_funding_deserts"."lga_name",
            "upper"("mv_funding_deserts"."state") AS "state",
            "mv_funding_deserts"."remoteness",
            "mv_funding_deserts"."desert_score",
            "mv_funding_deserts"."avg_irsd_decile"
           FROM "public"."mv_funding_deserts"
          WHERE ("mv_funding_deserts"."state" IS NOT NULL)
          ORDER BY "mv_funding_deserts"."lga_name", ("upper"("mv_funding_deserts"."state")), "mv_funding_deserts"."desert_score" DESC NULLS LAST
        )
 SELECT COALESCE("n"."lga_name", "de"."lga_name", "ds"."lga_name") AS "lga_name",
    COALESCE("n"."state", "de"."state", "ds"."state") AS "state",
    "ds"."remoteness",
    "ds"."desert_score",
    "ds"."avg_irsd_decile",
    COALESCE("n"."ndis_participants", (0)::bigint) AS "ndis_participants",
    COALESCE("de"."civicgraph_disability_entities", (0)::bigint) AS "disability_entities",
    COALESCE("de"."community_controlled_disability", (0)::bigint) AS "community_controlled_disability",
    COALESCE("de"."also_in_justice", (0)::bigint) AS "cross_system_justice",
    COALESCE("de"."also_in_procurement", (0)::bigint) AS "cross_system_procurement",
    COALESCE("de"."avg_system_count", (0)::numeric) AS "avg_entity_system_count",
    COALESCE("u"."overall_utilisation", (0)::numeric) AS "state_avg_utilisation",
    COALESCE("u"."min_utilisation", (0)::numeric) AS "state_min_utilisation",
    COALESCE("fn"."fn_total_participants", (0)::bigint) AS "fn_ndis_participants",
    COALESCE("fn"."fn_very_remote_participants", (0)::bigint) AS "fn_very_remote_participants",
    COALESCE("fn"."fn_avg_budget", (0)::numeric) AS "fn_avg_budget",
    COALESCE("fn"."fn_very_remote_avg_budget", (0)::numeric) AS "fn_very_remote_avg_budget",
    COALESCE("al"."disability_interventions", (0)::bigint) AS "alma_disability_interventions",
    COALESCE("al"."avg_evidence_score", (0)::numeric) AS "alma_avg_evidence_score",
        CASE
            WHEN ((COALESCE("n"."ndis_participants", (0)::bigint) > 0) AND (COALESCE("de"."civicgraph_disability_entities", (0)::bigint) = 0)) THEN 'CRITICAL'::"text"
            WHEN ((COALESCE("n"."ndis_participants", (0)::bigint) > 500) AND (COALESCE("de"."civicgraph_disability_entities", (0)::bigint) < 3)) THEN 'SEVERE'::"text"
            WHEN ((COALESCE("n"."ndis_participants", (0)::bigint) > 100) AND (COALESCE("de"."civicgraph_disability_entities", (0)::bigint) < 5)) THEN 'MODERATE'::"text"
            WHEN (COALESCE("n"."ndis_participants", (0)::bigint) > 0) THEN 'ADEQUATE'::"text"
            ELSE 'NO_DATA'::"text"
        END AS "thin_market_status",
        CASE
            WHEN (COALESCE("de"."civicgraph_disability_entities", (0)::bigint) > 0) THEN "round"(((COALESCE("n"."ndis_participants", (0)::bigint))::numeric / ("de"."civicgraph_disability_entities")::numeric), 1)
            ELSE NULL::numeric
        END AS "participants_per_provider"
   FROM ((((("ndis_by_lga" "n"
     FULL JOIN "disability_entities" "de" ON ((("de"."lga_name" = "n"."lga_name") AND ("de"."state" = "n"."state"))))
     LEFT JOIN "desert" "ds" ON ((("ds"."lga_name" = COALESCE("n"."lga_name", "de"."lga_name")) AND ("ds"."state" = COALESCE("n"."state", "de"."state")))))
     LEFT JOIN "utilisation_by_state" "u" ON (("u"."state" = COALESCE("n"."state", "de"."state"))))
     LEFT JOIN "first_nations_by_state" "fn" ON (("fn"."state" = COALESCE("n"."state", "de"."state"))))
     LEFT JOIN "alma_disability" "al" ON ((("al"."lga_name" = COALESCE("n"."lga_name", "de"."lga_name")) AND ("al"."state" = COALESCE("n"."state", "de"."state")))))
  WHERE (COALESCE("n"."lga_name", "de"."lga_name") IS NOT NULL)
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_disability_landscape" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_donation_contract_timing" AS
 WITH "dated_donations" AS (
         SELECT "political_donations"."donor_abn",
            "political_donations"."donor_name",
            "political_donations"."donation_to",
            "political_donations"."donation_date",
            "political_donations"."amount",
            "political_donations"."financial_year"
           FROM "public"."political_donations"
          WHERE (("political_donations"."donor_abn" IS NOT NULL) AND ("political_donations"."donation_date" IS NOT NULL) AND ("political_donations"."amount" > (0)::numeric))
        ), "dated_contracts" AS (
         SELECT "austender_contracts"."id" AS "contract_id",
            "austender_contracts"."supplier_abn",
            "austender_contracts"."supplier_name",
            "austender_contracts"."buyer_name",
            "austender_contracts"."title",
            "austender_contracts"."contract_value",
            "austender_contracts"."contract_start",
            "austender_contracts"."contract_end"
           FROM "public"."austender_contracts"
          WHERE (("austender_contracts"."supplier_abn" IS NOT NULL) AND ("austender_contracts"."contract_start" IS NOT NULL) AND ("austender_contracts"."contract_value" > (10000)::numeric))
        ), "temporal_matches" AS (
         SELECT "d"."donor_abn" AS "abn",
            "d"."donor_name",
            "d"."donation_to" AS "party",
            "d"."donation_date",
            "d"."amount" AS "donation_amount",
            "c"."contract_id",
            "c"."buyer_name",
            "c"."title" AS "contract_title",
            "c"."contract_value",
            "c"."contract_start",
            ("c"."contract_start" - "d"."donation_date") AS "days_between",
                CASE
                    WHEN ((("c"."contract_start" - "d"."donation_date") >= 0) AND (("c"."contract_start" - "d"."donation_date") <= 90)) THEN 'immediate'::"text"
                    WHEN ((("c"."contract_start" - "d"."donation_date") >= 91) AND (("c"."contract_start" - "d"."donation_date") <= 180)) THEN 'short'::"text"
                    WHEN ((("c"."contract_start" - "d"."donation_date") >= 181) AND (("c"."contract_start" - "d"."donation_date") <= 365)) THEN 'medium'::"text"
                    WHEN ((("c"."contract_start" - "d"."donation_date") >= 366) AND (("c"."contract_start" - "d"."donation_date") <= 730)) THEN 'long'::"text"
                    ELSE 'very_long'::"text"
                END AS "timing_window"
           FROM ("dated_donations" "d"
             JOIN "dated_contracts" "c" ON (("c"."supplier_abn" = "d"."donor_abn")))
          WHERE (("c"."contract_start" >= "d"."donation_date") AND ("c"."contract_start" <= ("d"."donation_date" + '2 years'::interval)))
        )
 SELECT "abn",
    "donor_name",
    "party",
    "donation_date",
    "donation_amount",
    "contract_id",
    "buyer_name",
    "contract_title",
    "contract_value",
    "contract_start",
    "days_between",
    "timing_window",
        CASE
            WHEN ("donation_amount" > (0)::numeric) THEN "round"(("contract_value" / "donation_amount"), 1)
            ELSE (0)::numeric
        END AS "roi_multiple"
   FROM "temporal_matches"
  ORDER BY "contract_value" DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_donation_contract_timing" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."person_identities" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "role_id" "uuid" NOT NULL,
    "person_name_normalised" "text" NOT NULL,
    "identity_key" "text" NOT NULL,
    "cluster_size" integer NOT NULL,
    "is_nominee_block" boolean DEFAULT false NOT NULL,
    "confidence" "text" NOT NULL,
    "method" "text" DEFAULT 'codir-graph-v1'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "person_identities_confidence_chk" CHECK (("confidence" = ANY (ARRAY['high'::"text", 'medium'::"text", 'low'::"text"])))
);


ALTER TABLE "public"."person_identities" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_person_network" AS
 WITH "person_boards" AS (
         SELECT "person_roles"."person_name_normalised",
            "count"(DISTINCT "person_roles"."company_abn") FILTER (WHERE ("person_roles"."company_abn" IS NOT NULL)) AS "board_count",
            "count"(*) AS "role_count",
            "array_agg"(DISTINCT "person_roles"."source") AS "sources",
            "array_agg"(DISTINCT "person_roles"."company_abn") FILTER (WHERE ("person_roles"."company_abn" IS NOT NULL)) AS "org_abns",
            "bool_or"((("person_roles"."source" ~~ '%parliament%'::"text") OR ("person_roles"."source" = 'openpolitics_au'::"text"))) AS "is_politician",
            "bool_or"(("person_roles"."source" = 'foundation_board'::"text")) AS "is_foundation_trustee"
           FROM "public"."person_roles"
          WHERE (("person_roles"."person_name_normalised" IS NOT NULL) AND ("person_roles"."person_name_normalised" <> ''::"text"))
          GROUP BY "person_roles"."person_name_normalised"
        ), "person_donations" AS (
         SELECT "upper"(TRIM(BOTH FROM "regexp_replace"("pd_1"."donor_name", '\s+'::"text", ' '::"text", 'g'::"text"))) AS "person_name_normalised",
            "count"(*) AS "donation_count",
            "count"(DISTINCT "pd_1"."donation_to") AS "parties_count",
            ("sum"("pd_1"."amount"))::bigint AS "total_donated"
           FROM "public"."political_donations" "pd_1"
          WHERE (("pd_1"."amount" > (0)::numeric) AND ("pd_1"."donor_name" IS NOT NULL) AND ("pd_1"."receipt_type" = 'donation received'::"text"))
          GROUP BY ("upper"(TRIM(BOTH FROM "regexp_replace"("pd_1"."donor_name", '\s+'::"text", ' '::"text", 'g'::"text"))))
        ), "person_org_pairs" AS (
         SELECT DISTINCT "person_roles"."person_name_normalised",
            "person_roles"."company_abn"
           FROM "public"."person_roles"
          WHERE (("person_roles"."company_abn" IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM "public"."person_identities" "pi"
                  WHERE (("pi"."person_name_normalised" = "person_roles"."person_name_normalised") AND "pi"."is_nominee_block")))))
        ), "person_contracts" AS (
         SELECT "pr"."person_name_normalised",
            "count"(DISTINCT "ac"."id") AS "contract_count",
            ("sum"("ac"."contract_value"))::bigint AS "total_contract_value"
           FROM ("person_org_pairs" "pr"
             JOIN "public"."austender_contracts" "ac" ON (("ac"."supplier_abn" = "pr"."company_abn")))
          WHERE ("ac"."contract_value" > (0)::numeric)
          GROUP BY "pr"."person_name_normalised"
        ), "person_justice" AS (
         SELECT "pr"."person_name_normalised",
            "count"(DISTINCT "jf"."id") AS "justice_grant_count",
            ("sum"("jf"."amount_dollars"))::bigint AS "total_justice_funding"
           FROM ("person_org_pairs" "pr"
             JOIN "public"."justice_funding" "jf" ON (("jf"."recipient_abn" = "pr"."company_abn")))
          WHERE (("jf"."amount_dollars" > (0)::numeric) AND ("jf"."measure_kind" = 'grant'::"text") AND ("jf"."is_aggregate" IS NOT TRUE) AND ("lower"("btrim"("jf"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"])))
          GROUP BY "pr"."person_name_normalised"
        ), "person_foundations" AS (
         SELECT "pr"."person_name_normalised",
            "count"(DISTINCT "f"."id") AS "foundation_count",
            ("sum"("f"."total_giving_annual"))::bigint AS "total_foundation_giving"
           FROM ("person_org_pairs" "pr"
             JOIN "public"."foundations" "f" ON (("f"."acnc_abn" = "pr"."company_abn")))
          WHERE ("f"."total_giving_annual" > (0)::numeric)
          GROUP BY "pr"."person_name_normalised"
        )
 SELECT "pb"."person_name_normalised",
    "pb"."board_count",
    "pb"."role_count",
    "pb"."sources",
    "pb"."org_abns",
    "pb"."is_politician",
    "pb"."is_foundation_trustee",
    COALESCE("pd"."donation_count", (0)::bigint) AS "donation_count",
    COALESCE("pd"."parties_count", (0)::bigint) AS "parties_donated_to",
    COALESCE("pd"."total_donated", (0)::bigint) AS "total_donated",
    COALESCE("pc"."contract_count", (0)::bigint) AS "contract_count",
    COALESCE("pc"."total_contract_value", (0)::bigint) AS "total_contract_value",
    COALESCE("pj"."justice_grant_count", (0)::bigint) AS "justice_grant_count",
    COALESCE("pj"."total_justice_funding", (0)::bigint) AS "total_justice_funding",
    COALESCE("pf"."foundation_count", (0)::bigint) AS "foundation_count",
    COALESCE("pf"."total_foundation_giving", (0)::bigint) AS "total_foundation_giving",
    (((((
        CASE
            WHEN ("pb"."board_count" > 0) THEN 1
            ELSE 0
        END +
        CASE
            WHEN (COALESCE("pd"."total_donated", (0)::bigint) > 0) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE("pc"."contract_count", (0)::bigint) > 0) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE("pj"."justice_grant_count", (0)::bigint) > 0) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE("pf"."foundation_count", (0)::bigint) > 0) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN "pb"."is_politician" THEN 1
            ELSE 0
        END) AS "system_count",
    (((((((LEAST("pb"."board_count", (20)::bigint) * 2) +
        CASE
            WHEN (COALESCE("pd"."total_donated", (0)::bigint) > 0) THEN LEAST(("log"((("pd"."total_donated" + 1))::double precision))::integer, 20)
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE("pc"."total_contract_value", (0)::bigint) > 0) THEN LEAST(("log"((("pc"."total_contract_value" + 1))::double precision))::integer, 20)
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE("pj"."total_justice_funding", (0)::bigint) > 0) THEN LEAST(("log"((("pj"."total_justice_funding" + 1))::double precision))::integer, 15)
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE("pf"."total_foundation_giving", (0)::bigint) > 0) THEN LEAST(("log"((("pf"."total_foundation_giving" + 1))::double precision))::integer, 15)
            ELSE 0
        END) +
        CASE
            WHEN "pb"."is_politician" THEN 10
            ELSE 0
        END) + ((((((
        CASE
            WHEN ("pb"."board_count" > 0) THEN 1
            ELSE 0
        END +
        CASE
            WHEN (COALESCE("pd"."total_donated", (0)::bigint) > 0) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE("pc"."contract_count", (0)::bigint) > 0) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE("pj"."justice_grant_count", (0)::bigint) > 0) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE("pf"."foundation_count", (0)::bigint) > 0) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN "pb"."is_politician" THEN 1
            ELSE 0
        END) * 5)) AS "power_score"
   FROM (((("person_boards" "pb"
     LEFT JOIN "person_donations" "pd" ON (("pd"."person_name_normalised" = "pb"."person_name_normalised")))
     LEFT JOIN "person_contracts" "pc" ON (("pc"."person_name_normalised" = "pb"."person_name_normalised")))
     LEFT JOIN "person_justice" "pj" ON (("pj"."person_name_normalised" = "pb"."person_name_normalised")))
     LEFT JOIN "person_foundations" "pf" ON (("pf"."person_name_normalised" = "pb"."person_name_normalised")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_person_network" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_donor_person_crosslink" AS
 WITH "donor_totals" AS (
         SELECT "upper"(TRIM(BOTH FROM "regexp_replace"("political_donations"."donor_name", '\s+'::"text", ' '::"text", 'g'::"text"))) AS "person_name_normalised",
            "political_donations"."donor_name",
            "count"(*) AS "donation_count",
            "count"(DISTINCT "political_donations"."donation_to") AS "parties_count",
            ("sum"("political_donations"."amount"))::bigint AS "total_donated",
            "array_agg"(DISTINCT "political_donations"."donation_to") AS "parties",
            "array_agg"(DISTINCT "political_donations"."financial_year") AS "donation_years",
            "min"("political_donations"."donation_date") AS "first_donation",
            "max"("political_donations"."donation_date") AS "last_donation"
           FROM "public"."political_donations"
          WHERE (("political_donations"."donor_abn" IS NULL) AND ("political_donations"."amount" > (0)::numeric) AND ("political_donations"."donor_name" IS NOT NULL))
          GROUP BY ("upper"(TRIM(BOTH FROM "regexp_replace"("political_donations"."donor_name", '\s+'::"text", ' '::"text", 'g'::"text")))), "political_donations"."donor_name"
        )
 SELECT "dt"."person_name_normalised",
    "dt"."donor_name",
    "dt"."donation_count",
    "dt"."parties_count",
    "dt"."total_donated",
    "dt"."parties",
    "dt"."donation_years",
    "dt"."first_donation",
    "dt"."last_donation",
    "pd"."board_count",
    "pd"."org_abns",
    "pd"."sources" AS "board_sources",
    "pd"."is_foundation_trustee",
    "pd"."is_politician",
    "pd"."total_contract_value",
    "pd"."total_justice_funding",
    "pd"."power_score",
    "pd"."system_count"
   FROM ("donor_totals" "dt"
     JOIN "public"."mv_person_network" "pd" ON (("pd"."person_name_normalised" = "dt"."person_name_normalised")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_donor_person_crosslink" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_entity_total_funding" AS
 WITH "grants" AS (
         SELECT "e"."id" AS "entity_id",
            "e"."gs_id",
            "e"."canonical_name",
            "e"."abn",
            'grant'::"text" AS "funding_type",
            "e"."state",
            "e"."postcode",
            "e"."remoteness",
            "e"."sector",
            "e"."is_community_controlled",
            "count"(DISTINCT "r"."id") AS "record_count",
            COALESCE("sum"("r"."amount"), (0)::numeric) AS "total_amount",
            "min"("r"."start_date") AS "earliest_date",
            "max"("r"."last_seen") AS "latest_date"
           FROM ("public"."gs_entities" "e"
             JOIN "public"."gs_relationships" "r" ON (("r"."target_entity_id" = "e"."id")))
          WHERE (("r"."relationship_type" = 'funder_to_recipient'::"text") AND ("r"."amount" IS NOT NULL))
          GROUP BY "e"."id", "e"."gs_id", "e"."canonical_name", "e"."abn", "e"."state", "e"."postcode", "e"."remoteness", "e"."sector", "e"."is_community_controlled"
        ), "contracts" AS (
         SELECT "e"."id" AS "entity_id",
            "e"."gs_id",
            "e"."canonical_name",
            "e"."abn",
            'contract'::"text" AS "funding_type",
            "e"."state",
            "e"."postcode",
            "e"."remoteness",
            "e"."sector",
            "e"."is_community_controlled",
            "count"(DISTINCT "ac"."id") AS "record_count",
            COALESCE("sum"("ac"."contract_value"), (0)::numeric) AS "total_amount",
            "min"("ac"."contract_start") AS "earliest_date",
            "max"("ac"."contract_end") AS "latest_date"
           FROM ("public"."gs_entities" "e"
             JOIN "public"."austender_contracts" "ac" ON (("ac"."supplier_abn" = "e"."abn")))
          WHERE ("e"."abn" IS NOT NULL)
          GROUP BY "e"."id", "e"."gs_id", "e"."canonical_name", "e"."abn", "e"."state", "e"."postcode", "e"."remoteness", "e"."sector", "e"."is_community_controlled"
        ), "justice" AS (
         SELECT "e"."id" AS "entity_id",
            "e"."gs_id",
            "e"."canonical_name",
            "e"."abn",
            'justice_funding'::"text" AS "funding_type",
            "e"."state",
            "e"."postcode",
            "e"."remoteness",
            "e"."sector",
            "e"."is_community_controlled",
            "count"(DISTINCT "jf"."id") AS "record_count",
            COALESCE("sum"("jf"."amount_dollars"), (0)::numeric) AS "total_amount",
            NULL::"date" AS "earliest_date",
            NULL::"date" AS "latest_date"
           FROM ("public"."gs_entities" "e"
             JOIN "public"."justice_funding" "jf" ON (("jf"."recipient_abn" = "e"."abn")))
          WHERE (("e"."abn" IS NOT NULL) AND ("jf"."measure_kind" = 'grant'::"text") AND ("jf"."is_aggregate" IS NOT TRUE) AND ("lower"("btrim"("jf"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"])))
          GROUP BY "e"."id", "e"."gs_id", "e"."canonical_name", "e"."abn", "e"."state", "e"."postcode", "e"."remoteness", "e"."sector", "e"."is_community_controlled"
        ), "donations" AS (
         SELECT "e"."id" AS "entity_id",
            "e"."gs_id",
            "e"."canonical_name",
            "e"."abn",
            'political_donation'::"text" AS "funding_type",
            "e"."state",
            "e"."postcode",
            "e"."remoteness",
            "e"."sector",
            "e"."is_community_controlled",
            "count"(DISTINCT "pd"."id") AS "record_count",
            COALESCE("sum"("pd"."amount"), (0)::numeric) AS "total_amount",
            NULL::"date" AS "earliest_date",
            NULL::"date" AS "latest_date"
           FROM ("public"."gs_entities" "e"
             JOIN "public"."political_donations" "pd" ON (("pd"."donor_abn" = "e"."abn")))
          WHERE (("e"."abn" IS NOT NULL) AND ("pd"."receipt_type" = 'donation received'::"text"))
          GROUP BY "e"."id", "e"."gs_id", "e"."canonical_name", "e"."abn", "e"."state", "e"."postcode", "e"."remoteness", "e"."sector", "e"."is_community_controlled"
        ), "all_sources" AS (
         SELECT "grants"."entity_id",
            "grants"."gs_id",
            "grants"."canonical_name",
            "grants"."abn",
            "grants"."funding_type",
            "grants"."state",
            "grants"."postcode",
            "grants"."remoteness",
            "grants"."sector",
            "grants"."is_community_controlled",
            "grants"."record_count",
            "grants"."total_amount",
            "grants"."earliest_date",
            "grants"."latest_date"
           FROM "grants"
        UNION ALL
         SELECT "contracts"."entity_id",
            "contracts"."gs_id",
            "contracts"."canonical_name",
            "contracts"."abn",
            "contracts"."funding_type",
            "contracts"."state",
            "contracts"."postcode",
            "contracts"."remoteness",
            "contracts"."sector",
            "contracts"."is_community_controlled",
            "contracts"."record_count",
            "contracts"."total_amount",
            "contracts"."earliest_date",
            "contracts"."latest_date"
           FROM "contracts"
        UNION ALL
         SELECT "justice"."entity_id",
            "justice"."gs_id",
            "justice"."canonical_name",
            "justice"."abn",
            "justice"."funding_type",
            "justice"."state",
            "justice"."postcode",
            "justice"."remoteness",
            "justice"."sector",
            "justice"."is_community_controlled",
            "justice"."record_count",
            "justice"."total_amount",
            "justice"."earliest_date",
            "justice"."latest_date"
           FROM "justice"
        UNION ALL
         SELECT "donations"."entity_id",
            "donations"."gs_id",
            "donations"."canonical_name",
            "donations"."abn",
            "donations"."funding_type",
            "donations"."state",
            "donations"."postcode",
            "donations"."remoteness",
            "donations"."sector",
            "donations"."is_community_controlled",
            "donations"."record_count",
            "donations"."total_amount",
            "donations"."earliest_date",
            "donations"."latest_date"
           FROM "donations"
        )
 SELECT "entity_id",
    "gs_id",
    "canonical_name",
    "abn",
    "state",
    "postcode",
    "remoteness",
    "sector",
    "is_community_controlled",
    COALESCE("sum"(
        CASE
            WHEN ("funding_type" = 'grant'::"text") THEN "total_amount"
            ELSE NULL::numeric
        END), (0)::numeric) AS "grants_total",
    COALESCE("sum"(
        CASE
            WHEN ("funding_type" = 'contract'::"text") THEN "total_amount"
            ELSE NULL::numeric
        END), (0)::numeric) AS "contracts_total",
    COALESCE("sum"(
        CASE
            WHEN ("funding_type" = 'justice_funding'::"text") THEN "total_amount"
            ELSE NULL::numeric
        END), (0)::numeric) AS "recorded_grants_total",
    COALESCE("sum"(
        CASE
            WHEN ("funding_type" = 'political_donation'::"text") THEN "total_amount"
            ELSE NULL::numeric
        END), (0)::numeric) AS "donations_total",
    (COALESCE("sum"(
        CASE
            WHEN ("funding_type" = 'grant'::"text") THEN "record_count"
            ELSE NULL::bigint
        END), (0)::numeric))::integer AS "grants_count",
    (COALESCE("sum"(
        CASE
            WHEN ("funding_type" = 'contract'::"text") THEN "record_count"
            ELSE NULL::bigint
        END), (0)::numeric))::integer AS "contracts_count",
    (COALESCE("sum"(
        CASE
            WHEN ("funding_type" = 'justice_funding'::"text") THEN "record_count"
            ELSE NULL::bigint
        END), (0)::numeric))::integer AS "recorded_grants_count",
    (COALESCE("sum"(
        CASE
            WHEN ("funding_type" = 'political_donation'::"text") THEN "record_count"
            ELSE NULL::bigint
        END), (0)::numeric))::integer AS "donations_count",
    "sum"("total_amount") AS "grand_total_funding",
    ("sum"("record_count"))::integer AS "grand_total_records",
    "count"(DISTINCT "funding_type") AS "funding_source_diversity",
    "now"() AS "computed_at"
   FROM "all_sources"
  GROUP BY "entity_id", "gs_id", "canonical_name", "abn", "state", "postcode", "remoteness", "sector", "is_community_controlled"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_entity_total_funding" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_entity_total_funding" IS 'Per-entity funding rollup. recorded_grants_total is money from the justice_funding TABLE — 81% the whole-of-QLD qgip register, 19.7% topic-tagged; NOT a justice figure. Renamed from justice_total 2026-08-16. Money filters applied at the same time. See thoughts/shared/data-map/justice-funding-filter-audit.md';



COMMENT ON COLUMN "public"."mv_entity_total_funding"."recorded_grants_total" IS 'Grant dollars from justice_funding after the mandatory filters.';



CREATE MATERIALIZED VIEW "public"."mv_foundation_grantees" AS
 SELECT "f"."id" AS "foundation_id",
    "f"."name" AS "foundation_name",
    "f"."acnc_abn" AS "foundation_abn",
    "f"."total_giving_annual",
    "ge_grantee"."id" AS "grantee_entity_id",
    "ge_grantee"."gs_id" AS "grantee_gs_id",
    "ge_grantee"."canonical_name" AS "grantee_name",
    "ge_grantee"."abn" AS "grantee_abn",
    "ge_grantee"."entity_type" AS "grantee_type",
    "ge_grantee"."state" AS "grantee_state",
    "ge_grantee"."is_community_controlled" AS "grantee_community_controlled",
    "r"."amount" AS "grant_amount",
    ("r"."year")::"text" AS "grant_year",
    "r"."dataset" AS "source_dataset",
    'relationship'::"text" AS "link_method"
   FROM ((("public"."foundations" "f"
     JOIN "public"."gs_entities" "ge_fdn" ON (("ge_fdn"."abn" = "f"."acnc_abn")))
     JOIN "public"."gs_relationships" "r" ON (("r"."source_entity_id" = "ge_fdn"."id")))
     JOIN "public"."gs_entities" "ge_grantee" ON (("ge_grantee"."id" = "r"."target_entity_id")))
  WHERE (("r"."relationship_type" = ANY (ARRAY['grant'::"text", 'funds'::"text", 'grants_to'::"text", 'gave_grant_to'::"text"])) AND ("r"."source_entity_id" <> "r"."target_entity_id") AND ("f"."acnc_abn" IS NOT NULL))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_foundation_grantees" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_foundation_grantees" IS 'Foundation to grantee links resolved by ABN through gs_relationships. Funder attribution is identity-based only; name-similarity attribution was removed 2026-08-03 after it produced 1,505 phantom funders.';



CREATE MATERIALIZED VIEW "public"."mv_evidence_backed_funding" AS
 WITH "foundation_orgs" AS (
         SELECT DISTINCT "fg"."foundation_name",
            "fg"."foundation_abn",
            "fg"."grantee_name",
            "fg"."grantee_abn"
           FROM "public"."mv_foundation_grantees" "fg"
        ), "alma_orgs" AS (
         SELECT DISTINCT "ai"."gs_entity_id",
            "e"."abn" AS "org_abn",
            "e"."canonical_name" AS "org_name",
            "ai"."name" AS "intervention_name",
            "ai"."type" AS "intervention_type",
            "ai"."evidence_level",
            "ai"."cultural_authority",
            "ai"."portfolio_score"
           FROM ("public"."alma_interventions" "ai"
             JOIN "public"."gs_entities" "e" ON (("e"."id" = "ai"."gs_entity_id")))
          WHERE (("ai"."gs_entity_id" IS NOT NULL) AND ("e"."abn" IS NOT NULL))
        )
 SELECT DISTINCT ON ("fo"."foundation_abn", "fo"."grantee_abn", "ao"."intervention_name") "fo"."foundation_name",
    "fo"."foundation_abn",
    "fo"."grantee_name",
    "fo"."grantee_abn",
    "ao"."intervention_name",
    "ao"."intervention_type",
    "ao"."evidence_level",
    "ao"."cultural_authority",
    "ao"."portfolio_score"
   FROM ("foundation_orgs" "fo"
     JOIN "alma_orgs" "ao" ON (("ao"."org_abn" = "fo"."grantee_abn")))
  ORDER BY "fo"."foundation_abn", "fo"."grantee_abn", "ao"."intervention_name", "ao"."portfolio_score" DESC NULLS LAST
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_evidence_backed_funding" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_foundation_landscape_access" AS
 WITH "program_modes" AS (
         SELECT "foundation_programs"."foundation_id",
            "bool_or"(("foundation_programs"."status" = ANY (ARRAY['open'::"text", 'ongoing'::"text", 'upcoming'::"text"]))) AS "has_open_program",
            "bool_or"(("foundation_programs"."application_mode" = 'online_application'::"text")) AS "has_online_application",
            "bool_or"(("foundation_programs"."application_mode" = 'eoi'::"text")) AS "has_eoi",
            "bool_or"((("foundation_programs"."application_mode" = 'invitation_only'::"text") OR ("foundation_programs"."status" = 'invitation_only'::"text"))) AS "has_invitation_only",
            "bool_or"((("foundation_programs"."application_mode" = ANY (ARRAY['relationship_based'::"text", 'monitor'::"text"])) OR ("foundation_programs"."status" = 'monitor'::"text"))) AS "has_relationship_monitor"
           FROM "public"."foundation_programs"
          GROUP BY "foundation_programs"."foundation_id"
        ), "foundation_access" AS (
         SELECT "f"."id",
            "f"."total_giving_annual",
                CASE
                    WHEN ("pm"."has_open_program" AND "pm"."has_online_application") THEN 'open_application'::"text"
                    WHEN ("pm"."has_open_program" AND "pm"."has_eoi") THEN 'eoi'::"text"
                    WHEN "pm"."has_invitation_only" THEN 'invitation_only'::"text"
                    WHEN "pm"."has_relationship_monitor" THEN 'relationship_led'::"text"
                    WHEN "pm"."has_open_program" THEN 'open_or_rolling'::"text"
                    WHEN (("f"."application_tips" IS NOT NULL) OR ("f"."giving_philosophy" IS NOT NULL)) THEN 'relationship_led'::"text"
                    ELSE 'unknown'::"text"
                END AS "access_mode"
           FROM ("public"."foundations" "f"
             LEFT JOIN "program_modes" "pm" ON (("pm"."foundation_id" = "f"."id")))
        )
 SELECT "access_mode",
    ("count"(*))::integer AS "foundation_count",
    COALESCE("sum"("total_giving_annual"), (0)::numeric) AS "estimated_annual_giving"
   FROM "foundation_access"
  GROUP BY "access_mode"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_foundation_landscape_access" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_foundation_landscape_category" AS
 WITH "category_foundations" AS (
         SELECT DISTINCT "foundation_category_assignments"."foundation_id",
            "foundation_category_assignments"."category_slug"
           FROM "public"."foundation_category_assignments"
          WHERE ("foundation_category_assignments"."confidence" >= 0.35)
        ), "program_counts" AS (
         SELECT "foundation_programs"."foundation_id",
            "count"(*) FILTER (WHERE ("foundation_programs"."status" = ANY (ARRAY['open'::"text", 'ongoing'::"text", 'upcoming'::"text"]))) AS "open_program_count",
            "count"(*) AS "program_count"
           FROM "public"."foundation_programs"
          GROUP BY "foundation_programs"."foundation_id"
        ), "grantee_counts" AS (
         SELECT "foundation_grantees"."foundation_id",
            "count"(*) AS "observed_grantee_count",
            COALESCE("sum"("foundation_grantees"."grant_amount"), (0)::numeric) AS "observed_grant_amount"
           FROM "public"."foundation_grantees"
          GROUP BY "foundation_grantees"."foundation_id"
        )
 SELECT "c"."category_slug",
    "c"."label",
    "c"."color_hex",
    "c"."sort_order",
    ("count"(DISTINCT "f"."id"))::integer AS "foundation_count",
    COALESCE("sum"("f"."total_giving_annual"), (0)::numeric) AS "estimated_annual_giving",
    (COALESCE("sum"("pc"."open_program_count"), (0)::numeric))::integer AS "open_program_count",
    (COALESCE("sum"("pc"."program_count"), (0)::numeric))::integer AS "program_count",
    (COALESCE("sum"("gc"."observed_grantee_count"), (0)::numeric))::integer AS "observed_grantee_count",
    COALESCE("sum"("gc"."observed_grant_amount"), (0)::numeric) AS "observed_grant_amount"
   FROM (((("public"."foundation_categories" "c"
     LEFT JOIN "category_foundations" "cf" ON (("cf"."category_slug" = "c"."category_slug")))
     LEFT JOIN "public"."foundations" "f" ON (("f"."id" = "cf"."foundation_id")))
     LEFT JOIN "program_counts" "pc" ON (("pc"."foundation_id" = "f"."id")))
     LEFT JOIN "grantee_counts" "gc" ON (("gc"."foundation_id" = "f"."id")))
  GROUP BY "c"."category_slug", "c"."label", "c"."color_hex", "c"."sort_order"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_foundation_landscape_category" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_foundation_landscape_geo" AS
 WITH "geo_foundations" AS (
         SELECT DISTINCT "foundation_geo_focus"."foundation_id",
            "foundation_geo_focus"."geo_type",
            "foundation_geo_focus"."geo_code",
            "foundation_geo_focus"."geo_name"
           FROM "public"."foundation_geo_focus"
          WHERE ("foundation_geo_focus"."confidence" >= 0.35)
        ), "program_counts" AS (
         SELECT "foundation_programs"."foundation_id",
            "count"(*) FILTER (WHERE ("foundation_programs"."status" = ANY (ARRAY['open'::"text", 'ongoing'::"text", 'upcoming'::"text"]))) AS "open_program_count"
           FROM "public"."foundation_programs"
          GROUP BY "foundation_programs"."foundation_id"
        )
 SELECT "gf"."geo_type",
    "gf"."geo_code",
    "gf"."geo_name",
    ("count"(DISTINCT "f"."id"))::integer AS "foundation_count",
    COALESCE("sum"("f"."total_giving_annual"), (0)::numeric) AS "estimated_annual_giving",
    (COALESCE("sum"("pc"."open_program_count"), (0)::numeric))::integer AS "open_program_count"
   FROM (("geo_foundations" "gf"
     JOIN "public"."foundations" "f" ON (("f"."id" = "gf"."foundation_id")))
     LEFT JOIN "program_counts" "pc" ON (("pc"."foundation_id" = "f"."id")))
  GROUP BY "gf"."geo_type", "gf"."geo_code", "gf"."geo_name"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_foundation_landscape_geo" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_foundation_landscape_top_foundations" AS
 WITH "category_rollup" AS (
         SELECT "fca"."foundation_id",
            "array_agg"(DISTINCT "fc"."label" ORDER BY "fc"."label") AS "categories"
           FROM ("public"."foundation_category_assignments" "fca"
             JOIN "public"."foundation_categories" "fc" ON (("fc"."category_slug" = "fca"."category_slug")))
          WHERE ("fca"."confidence" >= 0.35)
          GROUP BY "fca"."foundation_id"
        ), "geo_rollup" AS (
         SELECT "foundation_geo_focus"."foundation_id",
            "array_agg"(DISTINCT "foundation_geo_focus"."geo_name" ORDER BY "foundation_geo_focus"."geo_name") AS "geographies"
           FROM "public"."foundation_geo_focus"
          WHERE ("foundation_geo_focus"."confidence" >= 0.35)
          GROUP BY "foundation_geo_focus"."foundation_id"
        ), "program_counts" AS (
         SELECT "foundation_programs"."foundation_id",
            "count"(*) FILTER (WHERE ("foundation_programs"."status" = ANY (ARRAY['open'::"text", 'ongoing'::"text", 'upcoming'::"text"]))) AS "open_program_count",
            "count"(*) AS "program_count"
           FROM "public"."foundation_programs"
          GROUP BY "foundation_programs"."foundation_id"
        ), "grantee_counts" AS (
         SELECT "foundation_grantees"."foundation_id",
            "count"(*) AS "observed_grantee_count",
            COALESCE("sum"("foundation_grantees"."grant_amount"), (0)::numeric) AS "observed_grant_amount"
           FROM "public"."foundation_grantees"
          GROUP BY "foundation_grantees"."foundation_id"
        )
 SELECT "f"."id" AS "foundation_id",
    "f"."name",
    "f"."type",
    "f"."website",
    "f"."total_giving_annual",
    "f"."profile_confidence",
    COALESCE("cr"."categories", ARRAY[]::"text"[]) AS "categories",
    COALESCE("gr"."geographies", ARRAY[]::"text"[]) AS "geographies",
    (COALESCE("pc"."open_program_count", (0)::bigint))::integer AS "open_program_count",
    (COALESCE("pc"."program_count", (0)::bigint))::integer AS "program_count",
    (COALESCE("gc"."observed_grantee_count", (0)::bigint))::integer AS "observed_grantee_count",
    COALESCE("gc"."observed_grant_amount", (0)::numeric) AS "observed_grant_amount",
    GREATEST(COALESCE("f"."total_giving_annual", (0)::numeric), COALESCE("gc"."observed_grant_amount", (0)::numeric)) AS "landscape_weight"
   FROM (((("public"."foundations" "f"
     LEFT JOIN "category_rollup" "cr" ON (("cr"."foundation_id" = "f"."id")))
     LEFT JOIN "geo_rollup" "gr" ON (("gr"."foundation_id" = "f"."id")))
     LEFT JOIN "program_counts" "pc" ON (("pc"."foundation_id" = "f"."id")))
     LEFT JOIN "grantee_counts" "gc" ON (("gc"."foundation_id" = "f"."id")))
  WHERE ((COALESCE("f"."total_giving_annual", (0)::numeric) > (0)::numeric) OR (COALESCE("pc"."program_count", (0)::bigint) > 0) OR (COALESCE("gc"."observed_grantee_count", (0)::bigint) > 0))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_foundation_landscape_top_foundations" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_foundation_need_alignment" AS
 WITH "grantee_locations" AS (
         SELECT "fg"."foundation_name",
            "fg"."foundation_abn",
            "fg"."grantee_name",
            "fg"."grantee_abn",
            "e"."lga_name",
            "e"."lga_code",
            "e"."state",
            "e"."remoteness",
            "e"."seifa_irsd_decile",
            "e"."is_community_controlled"
           FROM ("public"."mv_foundation_grantees" "fg"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "fg"."grantee_abn")))
          WHERE ("e"."lga_name" IS NOT NULL)
        )
 SELECT "gl"."foundation_name",
    "gl"."foundation_abn",
    "gl"."lga_name",
    "gl"."state",
    "gl"."remoteness",
    "count"(DISTINCT "gl"."grantee_abn") AS "grantee_count",
    COALESCE("fd"."desert_score", (0)::numeric) AS "desert_score",
    COALESCE("fd"."avg_irsd_decile", (0)::numeric) AS "avg_lga_disadvantage",
    COALESCE("fd"."total_funding_all_sources", (0)::numeric) AS "existing_funding",
    "count"(DISTINCT "gl"."grantee_abn") FILTER (WHERE "gl"."is_community_controlled") AS "community_controlled_count",
    "avg"("gl"."seifa_irsd_decile") AS "avg_grantee_disadvantage_decile"
   FROM ("grantee_locations" "gl"
     LEFT JOIN "public"."mv_funding_deserts" "fd" ON (("fd"."lga_name" = "gl"."lga_name")))
  GROUP BY "gl"."foundation_name", "gl"."foundation_abn", "gl"."lga_name", "gl"."state", "gl"."remoteness", "fd"."desert_score", "fd"."avg_irsd_decile", "fd"."total_funding_all_sources"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_foundation_need_alignment" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_person_entity_crosswalk" AS
 WITH "person_orgs" AS (
         SELECT "person_roles"."person_name_normalised",
            "person_roles"."company_abn",
            "array_agg"(DISTINCT "person_roles"."source") AS "sources",
            "array_agg"(DISTINCT "person_roles"."role_type") AS "roles"
           FROM "public"."person_roles"
          WHERE (("person_roles"."person_name_normalised" IS NOT NULL) AND ("person_roles"."company_abn" IS NOT NULL))
          GROUP BY "person_roles"."person_name_normalised", "person_roles"."company_abn"
        ), "person_entities" AS (
         SELECT "po"."person_name_normalised",
            "po"."company_abn",
            "po"."sources",
            "po"."roles",
            "ge"."id" AS "entity_id",
            "ge"."gs_id",
            "ge"."canonical_name",
            "ge"."entity_type",
            "ge"."sector",
            "ge"."state",
            "ge"."is_community_controlled"
           FROM ("person_orgs" "po"
             JOIN "public"."gs_entities" "ge" ON (("ge"."abn" = "po"."company_abn")))
        )
 SELECT "pe"."person_name_normalised",
    "pe"."company_abn",
    "pe"."sources" AS "role_sources",
    "pe"."roles",
    "pe"."entity_id",
    "pe"."gs_id",
    "pe"."canonical_name",
    "pe"."entity_type",
    "pe"."sector",
    "pe"."state",
    "pe"."is_community_controlled",
    COALESCE("ac"."contract_total", (0)::bigint) AS "contract_dollars",
    COALESCE("ac"."contract_count", (0)::bigint) AS "contract_count",
    COALESCE("jf"."justice_total", (0)::bigint) AS "justice_dollars",
    COALESCE("jf"."justice_count", (0)::bigint) AS "justice_count",
    COALESCE("pd"."donation_total", (0)::bigint) AS "donation_dollars",
    COALESCE("pd"."donation_count", (0)::bigint) AS "donation_count"
   FROM ((("person_entities" "pe"
     LEFT JOIN LATERAL ( SELECT ("sum"("austender_contracts"."contract_value"))::bigint AS "contract_total",
            "count"(*) AS "contract_count"
           FROM "public"."austender_contracts"
          WHERE ("austender_contracts"."supplier_abn" = "pe"."company_abn")) "ac" ON (true))
     LEFT JOIN LATERAL ( SELECT ("sum"("justice_funding"."amount_dollars"))::bigint AS "justice_total",
            "count"(*) AS "justice_count"
           FROM "public"."justice_funding"
          WHERE (("justice_funding"."recipient_abn" = "pe"."company_abn") AND ("justice_funding"."measure_kind" = 'grant'::"text") AND ("justice_funding"."is_aggregate" IS NOT TRUE) AND ("lower"("btrim"("justice_funding"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"])))) "jf" ON (true))
     LEFT JOIN LATERAL ( SELECT ("sum"("political_donations"."amount"))::bigint AS "donation_total",
            "count"(*) AS "donation_count"
           FROM "public"."political_donations"
          WHERE (("political_donations"."donor_abn" = "pe"."company_abn") AND ("political_donations"."receipt_type" = 'donation received'::"text"))) "pd" ON (true))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_person_entity_crosswalk" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_trustee_grantee_chain" AS
 WITH "foundation_trustees" AS (
         SELECT DISTINCT "pec"."person_name_normalised",
            "pec"."company_abn" AS "foundation_abn",
            "pec"."canonical_name" AS "foundation_name",
            "pec"."roles",
            "pec"."role_sources"
           FROM "public"."mv_person_entity_crosswalk" "pec"
          WHERE ("pec"."entity_type" = 'foundation'::"text")
        ), "foundation_grantees" AS (
         SELECT DISTINCT "fg_1"."foundation_name",
            "fg_1"."foundation_abn",
            "fg_1"."grantee_name",
            "fg_1"."grantee_abn",
            "fg_1"."link_method",
            "fg_1"."grant_year"
           FROM "public"."mv_foundation_grantees" "fg_1"
        )
 SELECT "ft"."person_name_normalised" AS "trustee_name",
    "ft"."foundation_name",
    "ft"."foundation_abn",
    "ft"."roles" AS "trustee_roles",
    "fg"."grantee_name",
    "fg"."grantee_abn",
    "fg"."link_method",
    "fg"."grant_year",
    (EXISTS ( SELECT 1
           FROM "public"."mv_person_entity_crosswalk" "pec2"
          WHERE (("pec2"."person_name_normalised" = "ft"."person_name_normalised") AND ("pec2"."company_abn" = "fg"."grantee_abn")))) AS "trustee_on_grantee_board"
   FROM ("foundation_trustees" "ft"
     JOIN "foundation_grantees" "fg" ON (("fg"."foundation_abn" = "ft"."foundation_abn")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_trustee_grantee_chain" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_foundation_scores" AS
 WITH "foundation_base" AS (
         SELECT "f"."id" AS "foundation_id",
            "f"."name",
            "f"."acnc_abn",
            "f"."total_giving_annual",
            "f"."type",
            "f"."parent_company",
            "f"."thematic_focus",
            "f"."geographic_focus"
           FROM "public"."foundations" "f"
          WHERE (("f"."acnc_abn" IS NOT NULL) AND ("f"."total_giving_annual" > (100000)::numeric))
        ), "transparency" AS (
         SELECT "fb_1"."foundation_id",
            "count"(DISTINCT "fg"."grantee_abn") AS "grantee_count",
            "count"(DISTINCT "fg"."link_method") AS "link_methods",
            LEAST((100)::bigint, ("count"(DISTINCT "fg"."grantee_abn") * 5)) AS "transparency_score"
           FROM ("foundation_base" "fb_1"
             LEFT JOIN "public"."mv_foundation_grantees" "fg" ON (("fg"."foundation_abn" = "fb_1"."acnc_abn")))
          GROUP BY "fb_1"."foundation_id"
        ), "need_align" AS (
         SELECT "fb_1"."foundation_id",
            "count"(DISTINCT "fna"."lga_name") AS "lgas_funded",
            COALESCE("avg"("fna"."desert_score"), (0)::numeric) AS "avg_desert_score",
            COALESCE("avg"("fna"."avg_lga_disadvantage"), (5)::numeric) AS "avg_disadvantage",
            "sum"("fna"."community_controlled_count") AS "community_controlled_grantees",
            LEAST((100)::numeric, (COALESCE("avg"("fna"."desert_score"), (0)::numeric) * 1.2)) AS "need_alignment_score"
           FROM ("foundation_base" "fb_1"
             LEFT JOIN "public"."mv_foundation_need_alignment" "fna" ON (("fna"."foundation_abn" = "fb_1"."acnc_abn")))
          GROUP BY "fb_1"."foundation_id"
        ), "evidence" AS (
         SELECT "fb_1"."foundation_id",
            "count"(DISTINCT "ebf"."grantee_abn") AS "evidence_backed_orgs",
            "count"(DISTINCT "ebf"."intervention_name") AS "interventions",
            COALESCE("avg"("ebf"."portfolio_score"), (0)::numeric) AS "avg_portfolio_score",
                CASE
                    WHEN ("t_1"."grantee_count" = 0) THEN (0)::double precision
                    ELSE LEAST((100)::double precision, (((("count"(DISTINCT "ebf"."grantee_abn"))::double precision / (GREATEST("t_1"."grantee_count", (1)::bigint))::double precision) * (100)::double precision) * (2)::double precision))
                END AS "evidence_score"
           FROM (("foundation_base" "fb_1"
             LEFT JOIN "public"."mv_evidence_backed_funding" "ebf" ON (("ebf"."foundation_abn" = "fb_1"."acnc_abn")))
             LEFT JOIN "transparency" "t_1" ON (("t_1"."foundation_id" = "fb_1"."foundation_id")))
          GROUP BY "fb_1"."foundation_id", "t_1"."grantee_count"
        ), "concentration" AS (
         SELECT "fb_1"."foundation_id",
            "count"(DISTINCT "fna"."state") AS "states_funded",
            "count"(DISTINCT "fna"."remoteness") AS "remoteness_categories",
            "count"(DISTINCT "fna"."lga_name") AS "unique_lgas",
            LEAST((100)::bigint, (((COALESCE("count"(DISTINCT "fna"."state"), (0)::bigint) * 10) + (COALESCE("count"(DISTINCT "fna"."remoteness"), (0)::bigint) * 10)) + LEAST((50)::bigint, COALESCE("count"(DISTINCT "fna"."lga_name"), (0)::bigint)))) AS "concentration_score"
           FROM ("foundation_base" "fb_1"
             LEFT JOIN "public"."mv_foundation_need_alignment" "fna" ON (("fna"."foundation_abn" = "fb_1"."acnc_abn")))
          GROUP BY "fb_1"."foundation_id"
        ), "governance" AS (
         SELECT "fb_1"."foundation_id",
            "count"(DISTINCT "tgc"."trustee_name") AS "total_trustees",
            "count"(DISTINCT "tgc"."trustee_name") FILTER (WHERE "tgc"."trustee_on_grantee_board") AS "overlapping_trustees",
            "count"(*) FILTER (WHERE "tgc"."trustee_on_grantee_board") AS "overlap_instances"
           FROM ("foundation_base" "fb_1"
             LEFT JOIN "public"."mv_trustee_grantee_chain" "tgc" ON (("tgc"."foundation_abn" = "fb_1"."acnc_abn")))
          GROUP BY "fb_1"."foundation_id"
        )
 SELECT "fb"."foundation_id",
    "fb"."name",
    "fb"."acnc_abn",
    "fb"."total_giving_annual",
    "fb"."type",
    "fb"."parent_company",
    (COALESCE("t"."transparency_score", (0)::bigint))::integer AS "transparency_score",
    (COALESCE("na"."need_alignment_score", (0)::numeric))::integer AS "need_alignment_score",
    (COALESCE("ev"."evidence_score", (0)::double precision))::integer AS "evidence_score",
    (COALESCE("co"."concentration_score", (0)::bigint))::integer AS "concentration_score",
    (((((((COALESCE("t"."transparency_score", (0)::bigint))::numeric * 0.25) + (COALESCE("na"."need_alignment_score", (0)::numeric) * 0.30)))::double precision + (COALESCE("ev"."evidence_score", (0)::double precision) * (0.25)::double precision)) + (((COALESCE("co"."concentration_score", (0)::bigint))::numeric * 0.20))::double precision))::integer AS "foundation_score",
    COALESCE("t"."grantee_count", (0)::bigint) AS "grantee_count",
    COALESCE("na"."lgas_funded", (0)::bigint) AS "lgas_funded",
    (COALESCE("na"."avg_desert_score", (0)::numeric))::numeric(5,1) AS "avg_desert_score",
    COALESCE("na"."community_controlled_grantees", (0)::numeric) AS "community_controlled_grantees",
    COALESCE("ev"."evidence_backed_orgs", (0)::bigint) AS "evidence_backed_orgs",
    COALESCE("ev"."interventions", (0)::bigint) AS "interventions_funded",
    COALESCE("co"."states_funded", (0)::bigint) AS "states_funded",
    COALESCE("co"."unique_lgas", (0)::bigint) AS "unique_lgas",
    COALESCE("g"."total_trustees", (0)::bigint) AS "total_trustees",
    COALESCE("g"."overlapping_trustees", (0)::bigint) AS "overlapping_trustees",
    COALESCE("g"."overlap_instances", (0)::bigint) AS "overlap_instances"
   FROM ((((("foundation_base" "fb"
     LEFT JOIN "transparency" "t" ON (("t"."foundation_id" = "fb"."foundation_id")))
     LEFT JOIN "need_align" "na" ON (("na"."foundation_id" = "fb"."foundation_id")))
     LEFT JOIN "evidence" "ev" ON (("ev"."foundation_id" = "fb"."foundation_id")))
     LEFT JOIN "concentration" "co" ON (("co"."foundation_id" = "fb"."foundation_id")))
     LEFT JOIN "governance" "g" ON (("g"."foundation_id" = "fb"."foundation_id")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_foundation_scores" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_foundation_readiness" AS
 WITH "foundation_base" AS (
         SELECT "f"."id",
            "f"."name",
            "f"."acnc_abn",
            "f"."type",
            "f"."total_giving_annual",
            ("f"."acnc_data" IS NOT NULL) AS "has_ais_data",
            "f"."enrichment_source",
            "f"."profile_confidence"
           FROM "public"."foundations" "f"
          WHERE ("f"."type" <> ALL (ARRAY['university'::"text", 'legal_aid'::"text", 'primary_health_network'::"text", 'religious_organisation'::"text", 'education_body'::"text", 'hospital'::"text", 'service_delivery'::"text", 'unknown'::"text"]))
        ), "entity_match" AS (
         SELECT DISTINCT ON ("fb_1"."id") "fb_1"."id" AS "foundation_id",
            "e"."gs_id",
            "e"."id" AS "entity_uuid"
           FROM ("foundation_base" "fb_1"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "fb_1"."acnc_abn")))
          WHERE ("fb_1"."acnc_abn" IS NOT NULL)
        ), "grantee_counts" AS (
         SELECT "mv_foundation_grantees"."foundation_abn",
            "count"(*) AS "grantee_count"
           FROM "public"."mv_foundation_grantees"
          GROUP BY "mv_foundation_grantees"."foundation_abn"
        ), "score_lookup" AS (
         SELECT DISTINCT ON ("mv_foundation_scores"."acnc_abn") "mv_foundation_scores"."acnc_abn" AS "score_abn",
            "mv_foundation_scores"."foundation_score",
                CASE
                    WHEN ("mv_foundation_scores"."foundation_score" >= 50) THEN 'high'::"text"
                    WHEN ("mv_foundation_scores"."foundation_score" >= 20) THEN 'medium'::"text"
                    ELSE 'low'::"text"
                END AS "score_tier"
           FROM "public"."mv_foundation_scores"
          WHERE ("mv_foundation_scores"."acnc_abn" IS NOT NULL)
          ORDER BY "mv_foundation_scores"."acnc_abn", "mv_foundation_scores"."foundation_score" DESC
        )
 SELECT "fb"."id",
    "fb"."name",
    "fb"."acnc_abn",
    "fb"."type",
    ("fb"."total_giving_annual")::bigint AS "total_giving_annual",
    ("fb"."acnc_abn" IS NOT NULL) AS "has_abn",
    ("em"."gs_id" IS NOT NULL) AS "has_entity",
    "fb"."has_ais_data",
    (COALESCE("gc"."grantee_count", (0)::bigint))::integer AS "grantee_count",
    ("gc"."grantee_count" IS NOT NULL) AS "has_grantees",
    ("sl"."foundation_score" IS NOT NULL) AS "has_score",
    "sl"."foundation_score",
    "sl"."score_tier",
    ((((
        CASE
            WHEN ("fb"."acnc_abn" IS NOT NULL) THEN 1
            ELSE 0
        END +
        CASE
            WHEN ("em"."gs_id" IS NOT NULL) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN "fb"."has_ais_data" THEN 1
            ELSE 0
        END) +
        CASE
            WHEN ("gc"."grantee_count" IS NOT NULL) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN ("sl"."foundation_score" IS NOT NULL) THEN 1
            ELSE 0
        END) AS "readiness_score",
    "em"."gs_id",
    "fb"."enrichment_source",
    "fb"."profile_confidence"
   FROM ((("foundation_base" "fb"
     LEFT JOIN "entity_match" "em" ON (("em"."foundation_id" = "fb"."id")))
     LEFT JOIN "grantee_counts" "gc" ON (("gc"."foundation_abn" = "fb"."acnc_abn")))
     LEFT JOIN "score_lookup" "sl" ON (("sl"."score_abn" = "fb"."acnc_abn")))
  ORDER BY "fb"."total_giving_annual" DESC NULLS LAST
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_foundation_readiness" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_foundation_regranting" AS
 WITH "regranters" AS (
         SELECT DISTINCT "fg"."grantee_abn" AS "regranter_abn",
            "fg"."grantee_name" AS "regranter_name",
            "f2"."id" AS "regranter_foundation_id",
            "f2"."total_giving_annual" AS "regranter_giving",
            "f2"."type" AS "regranter_type"
           FROM ("public"."mv_foundation_grantees" "fg"
             JOIN "public"."foundations" "f2" ON (("f2"."acnc_abn" = "fg"."grantee_abn")))
          WHERE ("fg"."grantee_abn" IS NOT NULL)
        ), "chains" AS (
         SELECT "fg1"."foundation_name" AS "source_foundation",
            "fg1"."foundation_abn" AS "source_abn",
            "fg1"."total_giving_annual" AS "source_giving",
            "r"."regranter_name",
            "r"."regranter_abn",
            "r"."regranter_giving",
            "r"."regranter_type",
            "fg2"."grantee_name" AS "ultimate_grantee",
            "fg2"."grantee_abn" AS "ultimate_grantee_abn",
            "fg2"."grant_amount" AS "downstream_amount",
            "fg2"."grant_year" AS "downstream_year"
           FROM (("public"."mv_foundation_grantees" "fg1"
             JOIN "regranters" "r" ON (("r"."regranter_abn" = "fg1"."grantee_abn")))
             JOIN "public"."mv_foundation_grantees" "fg2" ON (("fg2"."foundation_abn" = "r"."regranter_abn")))
          WHERE ("fg1"."foundation_abn" <> "fg2"."grantee_abn")
        )
 SELECT "source_foundation",
    "source_abn",
    ("source_giving")::bigint AS "source_giving",
    "regranter_name",
    "regranter_abn",
    ("regranter_giving")::bigint AS "regranter_giving",
    "regranter_type",
    "ultimate_grantee",
    "ultimate_grantee_abn",
    ("downstream_amount")::bigint AS "downstream_amount",
    "downstream_year",
    (((("source_foundation" || ' → '::"text") || "regranter_name") || ' → '::"text") || "ultimate_grantee") AS "chain_label"
   FROM "chains"
  ORDER BY (("source_giving")::bigint) DESC NULLS LAST, (("regranter_giving")::bigint) DESC NULLS LAST
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_foundation_regranting" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_foundation_trends" AS
 WITH "foundation_years" AS (
         SELECT "f"."id" AS "foundation_id",
            "f"."name",
            "f"."acnc_abn",
            "f"."type",
            "a"."ais_year",
            "a"."grants_donations_au",
            "a"."total_revenue",
            "a"."total_expenses",
            "a"."donations_and_bequests",
            "a"."revenue_from_government",
            "a"."total_assets",
            "a"."net_assets_liabilities",
            "a"."staff_fte",
            "a"."staff_volunteers",
            "a"."charity_size"
           FROM ("public"."foundations" "f"
             JOIN "public"."acnc_ais" "a" ON (("a"."abn" = "f"."acnc_abn")))
          WHERE ("f"."acnc_abn" IS NOT NULL)
        ), "with_lag" AS (
         SELECT "foundation_years"."foundation_id",
            "foundation_years"."name",
            "foundation_years"."acnc_abn",
            "foundation_years"."type",
            "foundation_years"."ais_year",
            "foundation_years"."grants_donations_au",
            "foundation_years"."total_revenue",
            "foundation_years"."total_expenses",
            "foundation_years"."donations_and_bequests",
            "foundation_years"."revenue_from_government",
            "foundation_years"."total_assets",
            "foundation_years"."net_assets_liabilities",
            "foundation_years"."staff_fte",
            "foundation_years"."staff_volunteers",
            "foundation_years"."charity_size",
            "lag"("foundation_years"."grants_donations_au") OVER (PARTITION BY "foundation_years"."acnc_abn" ORDER BY "foundation_years"."ais_year") AS "prev_giving",
            "lag"("foundation_years"."total_revenue") OVER (PARTITION BY "foundation_years"."acnc_abn" ORDER BY "foundation_years"."ais_year") AS "prev_revenue",
            "lag"("foundation_years"."total_assets") OVER (PARTITION BY "foundation_years"."acnc_abn" ORDER BY "foundation_years"."ais_year") AS "prev_assets",
            "lag"("foundation_years"."staff_fte") OVER (PARTITION BY "foundation_years"."acnc_abn" ORDER BY "foundation_years"."ais_year") AS "prev_fte"
           FROM "foundation_years"
        )
 SELECT "foundation_id",
    "name",
    "acnc_abn",
    "type",
    "ais_year",
    ("grants_donations_au")::bigint AS "giving",
    ("total_revenue")::bigint AS "revenue",
    ("total_expenses")::bigint AS "expenses",
    ("donations_and_bequests")::bigint AS "donations_received",
    ("revenue_from_government")::bigint AS "govt_revenue",
    ("total_assets")::bigint AS "assets",
    ("net_assets_liabilities")::bigint AS "net_assets",
    "staff_fte",
    "staff_volunteers",
    "charity_size",
        CASE
            WHEN ("prev_giving" > (0)::numeric) THEN "round"(((("grants_donations_au" - "prev_giving") / "prev_giving") * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS "giving_growth_pct",
        CASE
            WHEN ("prev_revenue" > (0)::numeric) THEN "round"(((("total_revenue" - "prev_revenue") / "prev_revenue") * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS "revenue_growth_pct",
        CASE
            WHEN ("prev_assets" > (0)::numeric) THEN "round"(((("total_assets" - "prev_assets") / "prev_assets") * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS "asset_growth_pct",
        CASE
            WHEN ("total_expenses" > (0)::numeric) THEN "round"((("grants_donations_au" / "total_expenses") * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS "giving_ratio_pct",
        CASE
            WHEN ("total_revenue" > (0)::numeric) THEN "round"(((("total_revenue" - COALESCE("revenue_from_government", (0)::numeric)) / "total_revenue") * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS "self_sufficiency_pct"
   FROM "with_lag"
  WHERE ("ais_year" >= 2017)
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_foundation_trends" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_funding_by_disadvantage" AS
 SELECT "s"."decile_national" AS "irsd_decile",
        CASE
            WHEN ("s"."decile_national" <= 3) THEN 'Most Disadvantaged'::"text"
            WHEN ("s"."decile_national" <= 7) THEN 'Middle'::"text"
            ELSE 'Least Disadvantaged'::"text"
        END AS "disadvantage_group",
    "count"(DISTINCT "c"."abn") AS "charity_count",
    "round"("sum"("a"."total_gross_income"), 0) AS "total_income",
    "round"("sum"("a"."revenue_from_government"), 0) AS "govt_revenue",
    "round"("sum"("a"."donations_and_bequests"), 0) AS "donations",
    "round"("sum"("a"."total_expenses"), 0) AS "total_expenses",
    "round"("avg"("a"."total_gross_income"), 0) AS "avg_income",
    "round"("avg"("a"."revenue_from_government"), 0) AS "avg_govt_revenue",
    "round"("avg"("a"."staff_fte"), 1) AS "avg_staff_fte",
    "sum"("a"."staff_volunteers") AS "total_volunteers"
   FROM (("public"."acnc_charities" "c"
     JOIN "public"."seifa_2021" "s" ON ((("c"."postcode" = "s"."postcode") AND ("s"."index_type" = 'IRSD'::"text"))))
     JOIN "public"."acnc_ais" "a" ON (("c"."abn" = "a"."abn")))
  WHERE (("a"."ais_year" = ( SELECT "max"("acnc_ais"."ais_year") AS "max"
           FROM "public"."acnc_ais")) AND ("a"."total_gross_income" IS NOT NULL) AND ("a"."total_gross_income" > (0)::numeric) AND ("s"."decile_national" IS NOT NULL))
  GROUP BY "s"."decile_national"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_funding_by_disadvantage" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_funding_by_postcode" AS
 SELECT "e"."postcode",
    "e"."state",
    "pg"."remoteness_2021" AS "remoteness",
    "s"."decile_national" AS "seifa_irsd_decile",
    "pg"."locality",
    "count"(DISTINCT "e"."id") AS "entity_count",
    "count"(DISTINCT "e"."id") FILTER (WHERE "e"."is_community_controlled") AS "community_controlled_count",
    COALESCE("sum"("r"."amount"), (0)::numeric) AS "total_funding",
    COALESCE("sum"("r"."amount") FILTER (WHERE "e"."is_community_controlled"), (0)::numeric) AS "community_controlled_funding",
    "count"(DISTINCT "r"."id") AS "relationship_count"
   FROM ((("public"."gs_entities" "e"
     LEFT JOIN "public"."gs_relationships" "r" ON ((("r"."target_entity_id" = "e"."id") AND ("r"."relationship_type" = ANY (ARRAY['grant'::"text", 'contract'::"text", 'donation'::"text"])))))
     LEFT JOIN ( SELECT DISTINCT ON ("postcode_geo"."postcode") "postcode_geo"."postcode",
            "postcode_geo"."remoteness_2021",
            "postcode_geo"."locality"
           FROM "public"."postcode_geo") "pg" ON (("pg"."postcode" = "e"."postcode")))
     LEFT JOIN "public"."seifa_2021" "s" ON ((("s"."postcode" = "e"."postcode") AND ("s"."index_type" = 'IRSD'::"text"))))
  WHERE ("e"."postcode" IS NOT NULL)
  GROUP BY "e"."postcode", "e"."state", "pg"."remoteness_2021", "s"."decile_national", "pg"."locality"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_funding_by_postcode" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."outcome_submissions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "submitted_by" "uuid",
    "org_name" "text" NOT NULL,
    "org_abn" "text",
    "gs_entity_id" "text",
    "contact_email" "text",
    "program_name" "text" NOT NULL,
    "reporting_period" "text" NOT NULL,
    "outcomes" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "narrative" "text",
    "evidence_urls" "text"[],
    "methodology" "text",
    "status" "text" DEFAULT 'submitted'::"text" NOT NULL,
    "reviewer_notes" "text",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "proof_bundle_id" "uuid",
    "postcode" "text",
    "lga_name" "text",
    "state" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "outcome_submissions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'under_review'::"text", 'validated'::"text", 'rejected'::"text", 'published'::"text"])))
);


ALTER TABLE "public"."outcome_submissions" OWNER TO "postgres";


COMMENT ON TABLE "public"."outcome_submissions" IS 'Partner-submitted program outcomes for Governed Proof validation. Flows: draft → submitted → under_review → validated/rejected → published';



CREATE MATERIALIZED VIEW "public"."mv_funding_outcomes_summary" AS
 WITH "funding" AS (
         SELECT "jf"."gs_entity_id",
            "count"(*) AS "funding_records",
            "sum"("jf"."amount_dollars") AS "total_funding",
            "array_agg"(DISTINCT "jf"."program_name") FILTER (WHERE ("jf"."program_name" IS NOT NULL)) AS "funding_programs"
           FROM "public"."justice_funding" "jf"
          WHERE (("jf"."gs_entity_id" IS NOT NULL) AND ("jf"."measure_kind" = 'grant'::"text") AND ("jf"."is_aggregate" IS NOT TRUE) AND (("jf"."recipient_name" IS NULL) OR ("lower"("btrim"("jf"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"]))))
          GROUP BY "jf"."gs_entity_id"
        ), "outcomes" AS (
         SELECT "os"."gs_entity_id",
            "count"(*) AS "outcome_submissions",
            "count"(*) FILTER (WHERE ("os"."status" = 'validated'::"text")) AS "validated_submissions"
           FROM "public"."outcome_submissions" "os"
          GROUP BY "os"."gs_entity_id"
        ), "alma" AS (
         SELECT "ai"."gs_entity_id",
            "count"(*) AS "alma_interventions",
            "max"("ai"."portfolio_score") AS "max_portfolio_score",
            "max"("ai"."evidence_level") AS "best_evidence_level"
           FROM "public"."alma_interventions" "ai"
          GROUP BY "ai"."gs_entity_id"
        )
 SELECT "ge"."id" AS "entity_id",
    "ge"."gs_id",
    "ge"."canonical_name",
    "ge"."abn",
    "ge"."state",
    "ge"."is_community_controlled",
    "f"."funding_records",
    "f"."total_funding",
    "f"."funding_programs",
    COALESCE("o"."outcome_submissions", (0)::bigint) AS "outcome_submissions",
    COALESCE("o"."validated_submissions", (0)::bigint) AS "validated_submissions",
    COALESCE("a"."alma_interventions", (0)::bigint) AS "alma_interventions",
    "a"."max_portfolio_score",
    "a"."best_evidence_level",
        CASE
            WHEN (COALESCE("o"."validated_submissions", (0)::bigint) > 0) THEN 'proven'::"text"
            WHEN (COALESCE("o"."outcome_submissions", (0)::bigint) > 0) THEN 'submitted'::"text"
            WHEN (COALESCE("a"."alma_interventions", (0)::bigint) > 0) THEN 'evidence_exists'::"text"
            ELSE 'no_outcomes'::"text"
        END AS "outcomes_status",
    LEAST(100, (((
        CASE
            WHEN (COALESCE("o"."validated_submissions", (0)::bigint) > 0) THEN 40
            ELSE 0
        END +
        CASE
            WHEN (COALESCE("a"."alma_interventions", (0)::bigint) > 0) THEN 30
            ELSE 0
        END) +
        CASE
            WHEN ("a"."max_portfolio_score" > (50)::numeric) THEN 20
            ELSE COALESCE((("a"."max_portfolio_score")::integer / 3), 0)
        END) +
        CASE
            WHEN (COALESCE("o"."outcome_submissions", (0)::bigint) > 0) THEN 10
            ELSE 0
        END)) AS "proof_completeness"
   FROM ((("public"."gs_entities" "ge"
     JOIN "funding" "f" ON (("f"."gs_entity_id" = "ge"."id")))
     LEFT JOIN "outcomes" "o" ON (("o"."gs_entity_id" = "ge"."gs_id")))
     LEFT JOIN "alma" "a" ON (("a"."gs_entity_id" = "ge"."id")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_funding_outcomes_summary" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_funding_outcomes_summary" IS 'Per-entity: recorded grants received vs outcome submissions vs ALMA evidence. Rewritten 2026-08-16: per-lane CTE aggregation (the old three-way join fan-out multiplied sums by submissions x interventions — one entity showed $258.5bn) and the mandatory money filters. See thoughts/shared/data-map/unfiltered-money-views-audit.md';



CREATE MATERIALIZED VIEW "public"."mv_fy_donation_contracts" AS
 WITH "fy_donations" AS (
         SELECT "political_donations"."donor_abn",
            "political_donations"."donor_name",
            "political_donations"."donation_to",
            "political_donations"."financial_year",
            "sum"("political_donations"."amount") AS "total_donated",
            "count"(*) AS "donation_count"
           FROM "public"."political_donations"
          WHERE (("political_donations"."donor_abn" IS NOT NULL) AND ("political_donations"."financial_year" IS NOT NULL) AND ("political_donations"."amount" > (0)::numeric))
          GROUP BY "political_donations"."donor_abn", "political_donations"."donor_name", "political_donations"."donation_to", "political_donations"."financial_year"
        ), "fy_contracts" AS (
         SELECT "austender_contracts"."supplier_abn",
            "austender_contracts"."supplier_name",
            "austender_contracts"."buyer_name",
                CASE
                    WHEN (EXTRACT(month FROM "austender_contracts"."contract_start") >= (7)::numeric) THEN (((EXTRACT(year FROM "austender_contracts"."contract_start"))::integer || '-'::"text") || ((((EXTRACT(year FROM "austender_contracts"."contract_start"))::integer + 1) - 2000))::"text")
                    ELSE ((((EXTRACT(year FROM "austender_contracts"."contract_start"))::integer - 1) || '-'::"text") || (((EXTRACT(year FROM "austender_contracts"."contract_start"))::integer - 2000))::"text")
                END AS "contract_fy",
            "sum"("austender_contracts"."contract_value") AS "total_contract_value",
            "count"(*) AS "contract_count"
           FROM "public"."austender_contracts"
          WHERE (("austender_contracts"."supplier_abn" IS NOT NULL) AND ("austender_contracts"."contract_start" IS NOT NULL) AND ("austender_contracts"."contract_value" > (10000)::numeric))
          GROUP BY "austender_contracts"."supplier_abn", "austender_contracts"."supplier_name", "austender_contracts"."buyer_name",
                CASE
                    WHEN (EXTRACT(month FROM "austender_contracts"."contract_start") >= (7)::numeric) THEN (((EXTRACT(year FROM "austender_contracts"."contract_start"))::integer || '-'::"text") || ((((EXTRACT(year FROM "austender_contracts"."contract_start"))::integer + 1) - 2000))::"text")
                    ELSE ((((EXTRACT(year FROM "austender_contracts"."contract_start"))::integer - 1) || '-'::"text") || (((EXTRACT(year FROM "austender_contracts"."contract_start"))::integer - 2000))::"text")
                END
        )
 SELECT "d"."donor_abn" AS "abn",
    "d"."donor_name",
    "d"."donation_to" AS "party",
    "d"."financial_year" AS "donation_fy",
    "d"."total_donated" AS "fy_donation_total",
    "c"."buyer_name",
    "c"."contract_fy",
    "c"."total_contract_value" AS "fy_contract_total",
    "c"."contract_count",
        CASE
            WHEN ("d"."financial_year" = "c"."contract_fy") THEN 'same_fy'::"text"
            ELSE 'next_fy'::"text"
        END AS "fy_relationship",
        CASE
            WHEN ("d"."total_donated" > (0)::numeric) THEN "round"(("c"."total_contract_value" / "d"."total_donated"), 1)
            ELSE (0)::numeric
        END AS "fy_roi"
   FROM ("fy_donations" "d"
     JOIN "fy_contracts" "c" ON (("c"."supplier_abn" = "d"."donor_abn")))
  WHERE (("c"."contract_fy" = "d"."financial_year") OR ("c"."contract_fy" = (((("split_part"("d"."financial_year", '-'::"text", 1))::integer + 1) || '-'::"text") || ((("split_part"("d"."financial_year", '-'::"text", 2))::integer + 1))::"text")))
  ORDER BY "c"."total_contract_value" DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_fy_donation_contracts" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_grant_contract_overlap" AS
 WITH "grant_totals" AS (
         SELECT "justice_funding"."recipient_abn" AS "abn",
            ("array_agg"("justice_funding"."recipient_name" ORDER BY "justice_funding"."amount_dollars" DESC NULLS LAST))[1] AS "recipient_name",
            ("count"(*))::integer AS "grant_count",
            (COALESCE("sum"("justice_funding"."amount_dollars"), (0)::numeric))::bigint AS "grant_total",
            "min"("justice_funding"."financial_year") AS "grant_first_year",
            "max"("justice_funding"."financial_year") AS "grant_last_year"
           FROM "public"."justice_funding"
          WHERE (("justice_funding"."recipient_abn" IS NOT NULL) AND ("justice_funding"."measure_kind" = 'grant'::"text") AND ("justice_funding"."is_aggregate" IS NOT TRUE) AND (("justice_funding"."recipient_name" IS NULL) OR ("lower"("btrim"("justice_funding"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"]))))
          GROUP BY "justice_funding"."recipient_abn"
        ), "contract_totals" AS (
         SELECT "austender_contracts"."supplier_abn" AS "abn",
            ("array_agg"("austender_contracts"."supplier_name" ORDER BY "austender_contracts"."contract_value" DESC NULLS LAST))[1] AS "supplier_name",
            ("count"(*))::integer AS "contract_count",
            (COALESCE("sum"("austender_contracts"."contract_value"), (0)::numeric))::bigint AS "contract_total",
            ("min"(EXTRACT(year FROM "austender_contracts"."contract_start")))::integer AS "contract_first_year",
            ("max"(EXTRACT(year FROM "austender_contracts"."contract_start")))::integer AS "contract_last_year"
           FROM "public"."austender_contracts"
          WHERE ("austender_contracts"."supplier_abn" IS NOT NULL)
          GROUP BY "austender_contracts"."supplier_abn"
        )
 SELECT "g"."abn",
    "g"."recipient_name",
    "c"."supplier_name",
    "g"."grant_count",
    "g"."grant_total",
    "c"."contract_count",
    "c"."contract_total",
    ("g"."grant_total" + "c"."contract_total") AS "combined_public_funding",
    "g"."grant_first_year",
    "g"."grant_last_year",
    "c"."contract_first_year",
    "c"."contract_last_year",
        CASE
            WHEN ("c"."contract_total" > "g"."grant_total") THEN 'contract_heavy'::"text"
            WHEN ("g"."grant_total" > "c"."contract_total") THEN 'grant_heavy'::"text"
            ELSE 'balanced'::"text"
        END AS "funding_profile",
    "e"."gs_id",
    "e"."entity_type",
    "e"."state",
    "e"."is_community_controlled",
    "e"."community_controlled_tier"
   FROM (("grant_totals" "g"
     JOIN "contract_totals" "c" ON (("c"."abn" = "g"."abn")))
     LEFT JOIN "public"."gs_entities" "e" ON (("e"."abn" = "g"."abn")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_grant_contract_overlap" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_gs_donor_contractors" AS
 SELECT "e"."id",
    "e"."gs_id",
    "e"."canonical_name",
    "e"."entity_type",
    "e"."abn",
    "e"."sector",
    "e"."state",
    "d"."total_donated",
    "d"."donation_count",
    "d"."parties_donated_to",
    "d"."donation_years",
    "c"."total_contract_value",
    "c"."contract_count",
    "c"."government_buyers",
    "c"."contract_years"
   FROM (("public"."gs_entities" "e"
     JOIN ( SELECT "r"."source_entity_id",
            "sum"("r"."amount") AS "total_donated",
            "count"(*) AS "donation_count",
            "array_agg"(DISTINCT "t"."canonical_name") AS "parties_donated_to",
            "array_agg"(DISTINCT "r"."year" ORDER BY "r"."year") FILTER (WHERE ("r"."year" IS NOT NULL)) AS "donation_years"
           FROM ("public"."gs_relationships" "r"
             JOIN "public"."gs_entities" "t" ON (("r"."target_entity_id" = "t"."id")))
          WHERE (("r"."relationship_type" = 'donation'::"text") AND ("r"."amount" > (0)::numeric) AND (("r"."properties" ->> 'receipt_type'::"text") = 'donation received'::"text"))
          GROUP BY "r"."source_entity_id") "d" ON (("e"."id" = "d"."source_entity_id")))
     JOIN ( SELECT "r"."target_entity_id",
            "sum"("r"."amount") AS "total_contract_value",
            "count"(*) AS "contract_count",
            "array_agg"(DISTINCT "s"."canonical_name") AS "government_buyers",
            "array_agg"(DISTINCT "r"."year" ORDER BY "r"."year") FILTER (WHERE ("r"."year" IS NOT NULL)) AS "contract_years"
           FROM ("public"."gs_relationships" "r"
             JOIN "public"."gs_entities" "s" ON (("r"."source_entity_id" = "s"."id")))
          WHERE (("r"."relationship_type" = 'contract'::"text") AND ("r"."amount" > (0)::numeric))
          GROUP BY "r"."target_entity_id") "c" ON (("e"."id" = "c"."target_entity_id")))
  ORDER BY "d"."total_donated" DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_gs_donor_contractors" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_indigenous_funding_by_disadvantage" AS
 SELECT "s"."decile_national" AS "irsd_decile",
        CASE
            WHEN ("s"."decile_national" <= 3) THEN 'Most Disadvantaged'::"text"
            WHEN ("s"."decile_national" <= 7) THEN 'Middle'::"text"
            ELSE 'Least Disadvantaged'::"text"
        END AS "disadvantage_group",
    "count"(DISTINCT "c"."abn") AS "charity_count",
    "round"("sum"("a"."total_gross_income"), 0) AS "total_income",
    "round"("sum"("a"."revenue_from_government"), 0) AS "govt_revenue",
    "round"("sum"("a"."donations_and_bequests"), 0) AS "donations",
    "round"("avg"("a"."total_gross_income"), 0) AS "avg_income",
    "round"("avg"("a"."revenue_from_government"), 0) AS "avg_govt_revenue",
    "round"("avg"("a"."staff_fte"), 1) AS "avg_staff_fte"
   FROM (("public"."acnc_charities" "c"
     JOIN "public"."seifa_2021" "s" ON ((("c"."postcode" = "s"."postcode") AND ("s"."index_type" = 'IRSD'::"text"))))
     JOIN "public"."acnc_ais" "a" ON (("c"."abn" = "a"."abn")))
  WHERE (("a"."ais_year" = ( SELECT "max"("acnc_ais"."ais_year") AS "max"
           FROM "public"."acnc_ais")) AND ("a"."total_gross_income" IS NOT NULL) AND ("a"."total_gross_income" > (0)::numeric) AND ("s"."decile_national" IS NOT NULL) AND ("c"."ben_aboriginal_tsi" = true))
  GROUP BY "s"."decile_national"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_indigenous_funding_by_disadvantage" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_indigenous_procurement_score" AS
 WITH "indigenous_entities" AS (
         SELECT "gs_entities"."abn"
           FROM "public"."gs_entities"
          WHERE (("gs_entities"."abn" IS NOT NULL) AND (("gs_entities"."is_community_controlled" = true) OR ("gs_entities"."is_supply_nation_certified" = true) OR ("gs_entities"."entity_type" = 'indigenous_corp'::"text") OR ('bbf-listed'::"text" = ANY ("gs_entities"."tags"))))
        ), "agency_totals" AS (
         SELECT "austender_contracts"."buyer_name" AS "agency",
            (EXTRACT(year FROM "austender_contracts"."contract_start"))::integer AS "year",
            "count"(*) AS "total_contracts",
            COALESCE("sum"("austender_contracts"."contract_value"), (0)::numeric) AS "total_value",
            "count"(*) FILTER (WHERE ("austender_contracts"."supplier_abn" IN ( SELECT "indigenous_entities"."abn"
                   FROM "indigenous_entities"))) AS "indigenous_contracts",
            COALESCE("sum"("austender_contracts"."contract_value") FILTER (WHERE ("austender_contracts"."supplier_abn" IN ( SELECT "indigenous_entities"."abn"
                   FROM "indigenous_entities"))), (0)::numeric) AS "indigenous_value"
           FROM "public"."austender_contracts"
          WHERE (("austender_contracts"."buyer_name" IS NOT NULL) AND ("austender_contracts"."contract_start" IS NOT NULL) AND (EXTRACT(year FROM "austender_contracts"."contract_start") >= (2019)::numeric))
          GROUP BY "austender_contracts"."buyer_name", (EXTRACT(year FROM "austender_contracts"."contract_start"))
        )
 SELECT "agency",
    "year",
    "total_contracts",
    ("total_value")::bigint AS "total_value",
    "indigenous_contracts",
    ("indigenous_value")::bigint AS "indigenous_value",
        CASE
            WHEN ("total_value" > (0)::numeric) THEN "round"((("indigenous_value" / "total_value") * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "indigenous_share_pct",
        CASE
            WHEN ("total_contracts" > 0) THEN "round"(((("indigenous_contracts")::numeric / ("total_contracts")::numeric) * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "indigenous_contract_pct",
        CASE
            WHEN (("total_value" > (0)::numeric) AND (("indigenous_value" / "total_value") >= 0.03)) THEN 'meets_ipp_target'::"text"
            ELSE 'below_ipp_target'::"text"
        END AS "ipp_status"
   FROM "agency_totals"
  WHERE ("total_value" > (100000)::numeric)
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_indigenous_procurement_score" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_indigenous_proven_suppliers" AS
 WITH "oric" AS (
         SELECT DISTINCT ON ("o_1"."abn") "o_1"."abn",
            "o_1"."icn" AS "oric_icn",
            "o_1"."name" AS "oric_name",
            "o_1"."status" AS "oric_status",
            "o_1"."corporation_size",
            "o_1"."registered_on" AS "oric_registered_on",
            "o_1"."industry_sectors"
           FROM "public"."oric_corporations" "o_1"
          WHERE (("o_1"."abn" IS NOT NULL) AND ("o_1"."status" = 'Registered'::"text"))
          ORDER BY "o_1"."abn", "o_1"."registered_on" DESC NULLS LAST
        ), "base" AS (
         SELECT DISTINCT ON ("g"."abn") "g"."id" AS "entity_id",
            "g"."gs_id",
            "g"."abn",
            "g"."canonical_name",
            "g"."entity_type",
            "g"."state",
            "g"."postcode",
            "g"."sector",
            "g"."lga_name",
            "g"."is_community_controlled"
           FROM "public"."gs_entities" "g"
          WHERE (("g"."abn" IS NOT NULL) AND ("g"."abn" IN ( SELECT "oric"."abn"
                   FROM "oric")) AND (EXISTS ( SELECT 1
                   FROM "public"."austender_contracts" "c"
                  WHERE ("c"."supplier_abn" = "g"."abn"))))
          ORDER BY "g"."abn", "g"."gs_id"
        ), "ct" AS (
         SELECT "austender_contracts"."supplier_abn" AS "abn",
            "count"(*) AS "contract_count",
            "sum"("austender_contracts"."contract_value") AS "contract_value",
            "count"(DISTINCT "austender_contracts"."buyer_name") AS "distinct_buyers",
            "max"("austender_contracts"."contract_end") AS "last_contract_end",
            "min"("austender_contracts"."contract_start") AS "first_contract_start"
           FROM "public"."austender_contracts"
          WHERE ("austender_contracts"."supplier_abn" IN ( SELECT "base"."abn"
                   FROM "base"))
          GROUP BY "austender_contracts"."supplier_abn"
        ), "ac" AS (
         SELECT DISTINCT ON ("acnc_charities"."abn") "acnc_charities"."abn",
            "acnc_charities"."charity_size",
            "acnc_charities"."name" AS "acnc_name",
            "acnc_charities"."registration_date" AS "acnc_registered_since"
           FROM "public"."acnc_charities"
          WHERE ("acnc_charities"."abn" IN ( SELECT "base"."abn"
                   FROM "base"))
          ORDER BY "acnc_charities"."abn", "acnc_charities"."registration_date"
        )
 SELECT "b"."gs_id",
    "b"."abn",
    "b"."canonical_name",
    "b"."entity_type",
    "b"."state",
    "b"."postcode",
    "b"."sector",
    "b"."lga_name",
    "b"."is_community_controlled",
    "o"."oric_icn",
    "o"."oric_name",
    "o"."oric_status",
    "o"."corporation_size",
    "o"."oric_registered_on",
    "o"."industry_sectors",
    "ct"."contract_count",
    "ct"."contract_value",
    "ct"."distinct_buyers",
    "ct"."last_contract_end",
    "ct"."first_contract_start",
    "ac"."charity_size",
    "ac"."acnc_name",
    "ac"."acnc_registered_since",
    ("ac"."abn" IS NOT NULL) AS "has_acnc",
    COALESCE("ct"."contract_value", (0)::numeric) AS "total_evidence_dollars",
    (EXISTS ( SELECT 1
           FROM "public"."alma_interventions" "ai"
          WHERE (("ai"."gs_entity_id" = "b"."entity_id") AND (EXISTS ( SELECT 1
                   FROM "public"."alma_intervention_evidence" "e"
                  WHERE ("e"."intervention_id" = "ai"."id"))) AND (EXISTS ( SELECT 1
                   FROM "public"."alma_intervention_outcomes" "ao"
                  WHERE ("ao"."intervention_id" = "ai"."id")))))) AS "has_alma_evidence_outcomes"
   FROM ((("base" "b"
     JOIN "oric" "o" ON (("o"."abn" = "b"."abn")))
     LEFT JOIN "ct" ON (("ct"."abn" = "b"."abn")))
     LEFT JOIN "ac" ON (("ac"."abn" = "b"."abn")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_indigenous_proven_suppliers" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_individual_donors" AS
 WITH "raw_donors" AS (
         SELECT "political_donations"."donor_name",
            "upper"(TRIM(BOTH FROM
                CASE
                    WHEN ("political_donations"."donor_name" ~~ '%, %'::"text") THEN (("split_part"("political_donations"."donor_name", ', '::"text", 2) || ' '::"text") || "split_part"("political_donations"."donor_name", ', '::"text", 1))
                    ELSE "political_donations"."donor_name"
                END)) AS "person_name_normalised",
            ("sum"("political_donations"."amount"))::bigint AS "total_donated",
            "count"(DISTINCT "political_donations"."donation_to") AS "parties_funded",
            "array_agg"(DISTINCT "political_donations"."donation_to" ORDER BY "political_donations"."donation_to") AS "parties",
            "count"(DISTINCT "political_donations"."financial_year") AS "years_active",
            "min"("political_donations"."financial_year") AS "first_year",
            "max"("political_donations"."financial_year") AS "last_year"
           FROM "public"."political_donations"
          WHERE (("political_donations"."donor_name" ~~ '%, %'::"text") AND ("political_donations"."donor_name" !~~ '%Pty%'::"text") AND ("political_donations"."donor_name" !~~ '%Ltd%'::"text") AND ("political_donations"."donor_name" !~~ '%Inc%'::"text") AND ("political_donations"."donor_name" !~~ '%Union%'::"text") AND ("political_donations"."donor_name" !~~ '%Party%'::"text") AND ("political_donations"."donor_name" !~~ '%Association%'::"text") AND ("political_donations"."donor_name" !~~ '%Department%'::"text") AND ("political_donations"."donor_name" !~~ '%Division%'::"text") AND ("political_donations"."donor_name" !~~ '%Foundation%'::"text") AND ("political_donations"."donor_name" !~~ '%Services%'::"text") AND ("political_donations"."donor_name" !~~ '%&%'::"text") AND ("political_donations"."donor_name" !~~ '%Shop%'::"text") AND ("political_donations"."donor_name" !~~ '%Construction%'::"text") AND (("length"("political_donations"."donor_name") >= 5) AND ("length"("political_donations"."donor_name") <= 40)) AND ("array_length"("string_to_array"("political_donations"."donor_name", ' '::"text"), 1) <= 5))
          GROUP BY "political_donations"."donor_name"
        )
 SELECT "donor_name",
    "person_name_normalised",
    "total_donated",
    "parties_funded",
    "parties",
    "years_active",
    "first_year",
    "last_year"
   FROM "raw_donors"
  WHERE ("total_donated" > 1000)
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_individual_donors" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_intervention_funding_chain" AS
 SELECT "e"."id" AS "entity_id",
    "e"."gs_id",
    "e"."canonical_name" AS "org_name",
    "e"."entity_type",
    "e"."abn",
    "e"."state",
    "e"."sector",
    "e"."is_community_controlled",
    (("e"."metadata" ->> 'acnc'::"text") IS NOT NULL) AS "has_acnc_data",
    "count"(DISTINCT "ai"."id") AS "intervention_count",
    "array_agg"(DISTINCT "ai"."type") FILTER (WHERE ("ai"."type" IS NOT NULL)) AS "intervention_types",
    "max"("ai"."evidence_level") AS "max_evidence_level",
    "avg"("ai"."portfolio_score") FILTER (WHERE ("ai"."portfolio_score" IS NOT NULL)) AS "avg_portfolio_score",
    "count"(DISTINCT "aie"."evidence_id") AS "evidence_count",
    "count"(DISTINCT "aio"."outcome_id") AS "outcome_count",
    "count"(DISTINCT "r_grant"."id") AS "grant_count",
    COALESCE("sum"("r_grant"."amount"), (0)::numeric) AS "total_grant_funding",
    "count"(DISTINCT "r_contract"."id") AS "contract_count",
    "count"(DISTINCT "r_donation"."id") AS "donation_count",
    (((
        CASE
            WHEN ("count"(DISTINCT "ai"."id") > 0) THEN 1
            ELSE 0
        END +
        CASE
            WHEN ("count"(DISTINCT "aie"."evidence_id") > 0) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN ("count"(DISTINCT "aio"."outcome_id") > 0) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN (("count"(DISTINCT "r_grant"."id") + "count"(DISTINCT "r_contract"."id")) > 0) THEN 1
            ELSE 0
        END) AS "chain_completeness",
        CASE
            WHEN (("count"(DISTINCT "r_grant"."id") + "count"(DISTINCT "r_contract"."id")) = 0) THEN 'unfunded'::"text"
            WHEN ("count"(DISTINCT "aie"."evidence_id") = 0) THEN 'no_evidence'::"text"
            WHEN ("count"(DISTINCT "aio"."outcome_id") = 0) THEN 'no_outcomes'::"text"
            ELSE 'complete'::"text"
        END AS "chain_status"
   FROM (((((("public"."gs_entities" "e"
     JOIN "public"."alma_interventions" "ai" ON (("ai"."gs_entity_id" = "e"."id")))
     LEFT JOIN "public"."alma_intervention_evidence" "aie" ON (("aie"."intervention_id" = "ai"."id")))
     LEFT JOIN "public"."alma_intervention_outcomes" "aio" ON (("aio"."intervention_id" = "ai"."id")))
     LEFT JOIN "public"."gs_relationships" "r_grant" ON ((("r_grant"."target_entity_id" = "e"."id") AND ("r_grant"."relationship_type" = 'grant'::"text"))))
     LEFT JOIN "public"."gs_relationships" "r_contract" ON ((("r_contract"."target_entity_id" = "e"."id") AND ("r_contract"."relationship_type" = 'contract'::"text"))))
     LEFT JOIN "public"."gs_relationships" "r_donation" ON ((("r_donation"."target_entity_id" = "e"."id") AND ("r_donation"."relationship_type" = 'donation'::"text"))))
  GROUP BY "e"."id", "e"."gs_id", "e"."canonical_name", "e"."entity_type", "e"."abn", "e"."state", "e"."sector", "e"."is_community_controlled", "e"."metadata"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_intervention_funding_chain" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_justice_charity_financial_health" AS
 WITH "justice_abns" AS (
         SELECT DISTINCT "justice_funding"."recipient_abn" AS "abn"
           FROM "public"."justice_funding"
          WHERE (("justice_funding"."recipient_abn" IS NOT NULL) AND ("justice_funding"."recipient_abn" <> ''::"text"))
        ), "latest_ais" AS (
         SELECT DISTINCT ON ("a"."abn") "a"."abn",
            "a"."ais_year",
            "a"."charity_name",
            "a"."charity_size",
            "a"."total_revenue",
            "a"."total_expenses",
            "a"."net_surplus_deficit",
            "a"."total_current_assets",
            "a"."total_current_liabilities",
            "a"."net_assets_liabilities",
            "a"."revenue_from_government"
           FROM ("public"."acnc_ais" "a"
             JOIN "justice_abns" "j" ON (("j"."abn" = "a"."abn")))
          ORDER BY "a"."abn", "a"."ais_year" DESC, "a"."date_ais_received" DESC NULLS LAST
        ), "computed" AS (
         SELECT "l"."abn",
            "l"."ais_year",
            "l"."charity_name",
            "l"."charity_size",
            "l"."total_revenue",
            "l"."total_expenses",
            "l"."net_surplus_deficit",
            "l"."total_current_assets",
            "l"."total_current_liabilities",
            "l"."net_assets_liabilities",
            "l"."revenue_from_government",
                CASE
                    WHEN ("l"."total_revenue" > (0)::numeric) THEN "round"(("l"."net_surplus_deficit" / "l"."total_revenue"), 4)
                    ELSE NULL::numeric
                END AS "operating_margin",
                CASE
                    WHEN ("l"."total_current_liabilities" > (0)::numeric) THEN "round"(("l"."total_current_assets" / "l"."total_current_liabilities"), 4)
                    ELSE NULL::numeric
                END AS "current_ratio",
                CASE
                    WHEN (("l"."total_expenses" > (0)::numeric) AND ("l"."net_assets_liabilities" >= (0)::numeric)) THEN "round"(("l"."net_assets_liabilities" / ("l"."total_expenses" / 12.0)), 2)
                    ELSE NULL::numeric
                END AS "months_of_reserves",
                CASE
                    WHEN (("l"."total_revenue" > (0)::numeric) AND ("l"."revenue_from_government" IS NOT NULL)) THEN "round"(("l"."revenue_from_government" / "l"."total_revenue"), 4)
                    ELSE NULL::numeric
                END AS "govt_revenue_share"
           FROM "latest_ais" "l"
        )
 SELECT "abn",
    "charity_name",
    "charity_size",
    "ais_year",
    "total_revenue",
    "total_expenses",
    "net_surplus_deficit",
    "total_current_assets",
    "total_current_liabilities",
    "net_assets_liabilities",
    "revenue_from_government",
    "operating_margin",
    "current_ratio",
    "months_of_reserves",
    "govt_revenue_share",
    ("net_surplus_deficit" < (0)::numeric) AS "is_deficit",
    ("net_assets_liabilities" < (0)::numeric) AS "net_assets_negative",
        CASE
            WHEN ("current_ratio" IS NOT NULL) THEN ("current_ratio" < 1.0)
            ELSE NULL::boolean
        END AS "low_liquidity",
        CASE
            WHEN ("months_of_reserves" IS NOT NULL) THEN ("months_of_reserves" < (3)::numeric)
            ELSE NULL::boolean
        END AS "low_reserves",
        CASE
            WHEN ("govt_revenue_share" IS NOT NULL) THEN ("govt_revenue_share" > 0.75)
            ELSE NULL::boolean
        END AS "high_govt_dependency",
        CASE
            WHEN (("total_revenue" IS NULL) OR ("total_revenue" <= (0)::numeric)) THEN 'unknown'::"text"
            WHEN ("net_assets_liabilities" < (0)::numeric) THEN 'fragile'::"text"
            WHEN (("months_of_reserves" IS NOT NULL) AND ("months_of_reserves" < (1)::numeric)) THEN 'fragile'::"text"
            WHEN (("months_of_reserves" IS NOT NULL) AND ("months_of_reserves" < (3)::numeric) AND (("net_surplus_deficit" < (0)::numeric) OR ("current_ratio" < 1.0))) THEN 'fragile'::"text"
            WHEN (("months_of_reserves" IS NULL) AND ("net_surplus_deficit" < (0)::numeric) AND ("current_ratio" IS NOT NULL) AND ("current_ratio" < 1.0)) THEN 'fragile'::"text"
            WHEN ("net_surplus_deficit" < (0)::numeric) THEN 'watch'::"text"
            WHEN (("months_of_reserves" IS NOT NULL) AND ("months_of_reserves" < (3)::numeric)) THEN 'watch'::"text"
            WHEN (("current_ratio" IS NOT NULL) AND ("current_ratio" < 1.0) AND (("months_of_reserves" IS NULL) OR ("months_of_reserves" < (6)::numeric))) THEN 'watch'::"text"
            ELSE 'healthy'::"text"
        END AS "fragility_tier"
   FROM "computed" "c"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_justice_charity_financial_health" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_justice_charity_financial_health" IS 'OP4: latest ACNC AIS financial-health signal for justice-funded charities. Fragility tier + raw flags. Liquidity NULL when no balance sheet filed (never inferred). Supply-magnet/mission lens — capacity signal, not a buyer warning.';



CREATE MATERIALIZED VIEW "public"."mv_justice_proven_suppliers" AS
 WITH "base" AS (
         SELECT DISTINCT ON ("g"."abn") "g"."id" AS "entity_id",
            "g"."gs_id",
            "g"."abn",
            "g"."canonical_name",
            "g"."entity_type",
            "g"."state",
            "g"."postcode",
            "g"."sector",
            "g"."lga_name",
            "g"."is_community_controlled"
           FROM "public"."gs_entities" "g"
          WHERE (("g"."abn" IS NOT NULL) AND (EXISTS ( SELECT 1
                   FROM "public"."justice_funding" "j"
                  WHERE (("j"."recipient_abn" = "g"."abn") AND ("j"."measure_kind" = 'grant'::"text") AND ("j"."is_aggregate" IS NOT TRUE) AND (("j"."recipient_name" IS NULL) OR ("lower"("btrim"("j"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"])))))) AND (EXISTS ( SELECT 1
                   FROM "public"."austender_contracts" "c"
                  WHERE ("c"."supplier_abn" = "g"."abn"))))
          ORDER BY "g"."abn", "g"."gs_id"
        ), "jf" AS (
         SELECT "justice_funding"."recipient_abn" AS "abn",
            "sum"("justice_funding"."amount_dollars") AS "justice_dollars",
            "count"(*) AS "justice_record_count",
            "count"(DISTINCT "justice_funding"."program_name") AS "distinct_justice_programs",
            "array_agg"(DISTINCT "justice_funding"."state") FILTER (WHERE ("justice_funding"."state" IS NOT NULL)) AS "justice_states"
           FROM "public"."justice_funding"
          WHERE (true AND ("justice_funding"."measure_kind" = 'grant'::"text") AND ("justice_funding"."is_aggregate" IS NOT TRUE) AND (("justice_funding"."recipient_name" IS NULL) OR ("lower"("btrim"("justice_funding"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"]))) AND ("justice_funding"."recipient_abn" IN ( SELECT "base"."abn"
                   FROM "base")))
          GROUP BY "justice_funding"."recipient_abn"
        ), "ct" AS (
         SELECT "austender_contracts"."supplier_abn" AS "abn",
            "count"(*) AS "contract_count",
            "sum"("austender_contracts"."contract_value") AS "contract_value",
            "count"(DISTINCT "austender_contracts"."buyer_name") AS "distinct_buyers",
            "max"("austender_contracts"."contract_end") AS "last_contract_end",
            "min"("austender_contracts"."contract_start") AS "first_contract_start"
           FROM "public"."austender_contracts"
          WHERE ("austender_contracts"."supplier_abn" IN ( SELECT "base"."abn"
                   FROM "base"))
          GROUP BY "austender_contracts"."supplier_abn"
        ), "ac" AS (
         SELECT DISTINCT ON ("acnc_charities"."abn") "acnc_charities"."abn",
            "acnc_charities"."charity_size",
            "acnc_charities"."name" AS "acnc_name",
            "acnc_charities"."registration_date" AS "acnc_registered_since"
           FROM "public"."acnc_charities"
          WHERE ("acnc_charities"."abn" IN ( SELECT "base"."abn"
                   FROM "base"))
          ORDER BY "acnc_charities"."abn", "acnc_charities"."registration_date"
        )
 SELECT "b"."gs_id",
    "b"."abn",
    "b"."canonical_name",
    "b"."entity_type",
    "b"."state",
    "b"."postcode",
    "b"."sector",
    "b"."lga_name",
    "b"."is_community_controlled",
    "jf"."justice_dollars",
    "jf"."justice_record_count",
    "jf"."distinct_justice_programs",
    "jf"."justice_states",
    "ct"."contract_count",
    "ct"."contract_value",
    "ct"."distinct_buyers",
    "ct"."last_contract_end",
    "ct"."first_contract_start",
    "ac"."charity_size",
    "ac"."acnc_name",
    "ac"."acnc_registered_since",
    ("ac"."abn" IS NOT NULL) AS "has_acnc",
    (COALESCE("jf"."justice_dollars", (0)::numeric) + COALESCE("ct"."contract_value", (0)::numeric)) AS "total_evidence_dollars",
    (EXISTS ( SELECT 1
           FROM "public"."alma_interventions" "ai"
          WHERE (("ai"."gs_entity_id" = "b"."entity_id") AND (EXISTS ( SELECT 1
                   FROM "public"."alma_intervention_evidence" "e"
                  WHERE ("e"."intervention_id" = "ai"."id"))) AND (EXISTS ( SELECT 1
                   FROM "public"."alma_intervention_outcomes" "o"
                  WHERE ("o"."intervention_id" = "ai"."id")))))) AS "has_alma_evidence_outcomes"
   FROM ((("base" "b"
     LEFT JOIN "jf" ON (("jf"."abn" = "b"."abn")))
     LEFT JOIN "ct" ON (("ct"."abn" = "b"."abn")))
     LEFT JOIN "ac" ON (("ac"."abn" = "b"."abn")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_justice_proven_suppliers" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_lga_indigenous_proxy_score" AS
 SELECT "jf"."state",
    "ge"."lga_name",
    "count"(DISTINCT "jf"."recipient_abn") AS "unique_recipients",
    "count"(DISTINCT "jf"."recipient_abn") FILTER (WHERE "ge"."is_community_controlled") AS "indigenous_recipients",
    "count"(DISTINCT "jf"."recipient_abn") FILTER (WHERE (NOT "ge"."is_community_controlled")) AS "non_indigenous_recipients",
    (COALESCE("sum"("jf"."amount_dollars"), (0)::numeric))::bigint AS "total_indigenous_tagged_funding",
    (COALESCE("sum"("jf"."amount_dollars") FILTER (WHERE "ge"."is_community_controlled"), (0)::numeric))::bigint AS "to_community_controlled",
    (COALESCE("sum"("jf"."amount_dollars") FILTER (WHERE (NOT "ge"."is_community_controlled")), (0)::numeric))::bigint AS "to_proxy_orgs",
        CASE
            WHEN ("sum"("jf"."amount_dollars") > (0)::numeric) THEN "round"((("sum"("jf"."amount_dollars") FILTER (WHERE "ge"."is_community_controlled") / "sum"("jf"."amount_dollars")) * (100)::numeric), 1)
            ELSE (0)::numeric
        END AS "community_controlled_share_pct",
        CASE
            WHEN ("sum"("jf"."amount_dollars") > (0)::numeric) THEN "round"((("sum"("jf"."amount_dollars") FILTER (WHERE (NOT "ge"."is_community_controlled")) / "sum"("jf"."amount_dollars")) * (100)::numeric), 1)
            ELSE (0)::numeric
        END AS "proxy_share_pct"
   FROM ("public"."justice_funding" "jf"
     JOIN "public"."gs_entities" "ge" ON (("ge"."id" = "jf"."gs_entity_id")))
  WHERE (("jf"."topics" @> ARRAY['indigenous'::"text"]) AND ("jf"."source" <> 'austender-direct'::"text") AND ("jf"."program_name" !~~ 'ROGS%'::"text") AND ("jf"."program_name" !~~ 'Total%'::"text") AND ("ge"."lga_name" IS NOT NULL) AND ("jf"."state" IS NOT NULL))
  GROUP BY "jf"."state", "ge"."lga_name"
 HAVING ("sum"("jf"."amount_dollars") > (10000)::numeric)
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_lga_indigenous_proxy_score" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_lga_place_profile" AS
 WITH "pc_lga" AS (
         SELECT "postcode_geo"."postcode",
            "min"("postcode_geo"."lga_name") AS "lga_name",
            "min"("postcode_geo"."state") AS "state"
           FROM "public"."postcode_geo"
          WHERE (("postcode_geo"."lga_name" IS NOT NULL) AND ("postcode_geo"."postcode" <> '0872'::"text"))
          GROUP BY "postcode_geo"."postcode"
         HAVING ("count"(DISTINCT "postcode_geo"."lga_name") = 1)
        ), "orgs" AS (
         SELECT "e"."lga_name",
            "e"."state",
            "count"(*) AS "org_count",
            "count"(*) FILTER (WHERE ("e"."is_community_controlled" OR ("e"."entity_type" = 'indigenous_corp'::"text"))) AS "community_controlled",
            "count"(*) FILTER (WHERE ("e"."abn" IS NULL)) AS "without_abn",
            "count"(*) FILTER (WHERE ("e"."oric_status" = 'Registered'::"text")) AS "oric_registered",
            "count"(*) FILTER (WHERE ("e"."oric_sector" ~~* '%land and waters%'::"text")) AS "caring_for_country",
            "count"(*) FILTER (WHERE ("e"."oric_employee_band" = ANY (ARRAY['<5'::"text", '5 - 24'::"text", '>24'::"text"]))) AS "employers",
            "count"(*) FILTER (WHERE ("e"."oric_income_band" = ANY (ARRAY['$100k-<$5m'::"text", '>=$5m'::"text"]))) AS "income_over_100k"
           FROM "public"."gs_entities" "e"
          WHERE ("e"."lga_name" IS NOT NULL)
          GROUP BY "e"."lga_name", "e"."state"
        ), "contracts" AS (
         SELECT "e"."lga_name",
            "e"."state",
            "count"(*) AS "contract_count",
            "sum"("c_1"."contract_value") AS "contract_value_lifetime",
            "sum"("c_1"."contract_value") FILTER (WHERE ("c_1"."contract_start" >= ("now"() - '2 years'::interval))) AS "contract_value_24m"
           FROM ("public"."gs_entities" "e"
             JOIN "public"."austender_contracts" "c_1" ON (("c_1"."supplier_abn" = "e"."abn")))
          WHERE (("e"."lga_name" IS NOT NULL) AND ("e"."abn" IS NOT NULL) AND (("c_1"."contract_start" IS NULL) OR ("c_1"."contract_start" >= '2000-01-01'::"date")))
          GROUP BY "e"."lga_name", "e"."state"
        ), "pc0872" AS (
         SELECT DISTINCT "postcode_geo"."lga_name",
            "postcode_geo"."state"
           FROM "public"."postcode_geo"
          WHERE (("postcode_geo"."postcode" = '0872'::"text") AND ("postcode_geo"."lga_name" IS NOT NULL))
        ), "delivered" AS (
         SELECT "placed"."place_lga" AS "lga_name",
            "placed"."place_state" AS "state",
            "count"(*) AS "grants_delivered",
            "sum"("placed"."value_aud") AS "grants_delivered_value",
            "sum"("placed"."value_aud") FILTER (WHERE ("placed"."recipient_lga" = "placed"."place_lga")) AS "grants_held_locally_value",
            "sum"("placed"."value_aud") FILTER (WHERE ("placed"."approval_date" >= ("now"() - '2 years'::interval))) AS "grants_delivered_24m"
           FROM ( SELECT "ga"."value_aud",
                    "ga"."approval_date",
                    COALESCE("r"."lga_name", "re"."lga_name") AS "recipient_lga",
                        CASE
                            WHEN ("ga"."delivery_postcode" = '0872'::"text") THEN "g0"."lga_name"
                            ELSE "dp"."lga_name"
                        END AS "place_lga",
                        CASE
                            WHEN ("ga"."delivery_postcode" = '0872'::"text") THEN "g0"."state"
                            ELSE "dp"."state"
                        END AS "place_state"
                   FROM (((("public"."grantconnect_awards" "ga"
                     LEFT JOIN "pc_lga" "dp" ON ((("dp"."postcode" = "ga"."delivery_postcode") AND ("ga"."delivery_postcode" <> '0872'::"text"))))
                     LEFT JOIN "public"."gs_entities" "re" ON (("re"."id" = "ga"."gs_entity_id")))
                     LEFT JOIN "pc0872" "g0" ON ((("g0"."lga_name" = "re"."lga_name") AND ("ga"."delivery_postcode" = '0872'::"text"))))
                     LEFT JOIN "pc_lga" "r" ON (("r"."postcode" = "ga"."recipient_postcode")))
                  WHERE ("ga"."delivery_postcode" IS NOT NULL)) "placed"
          WHERE ("placed"."place_lga" IS NOT NULL)
          GROUP BY "placed"."place_lga", "placed"."place_state"
        ), "phil" AS (
         SELECT "e"."lga_name",
            "e"."state",
            "count"(DISTINCT "fg"."foundation_name") AS "philanthropic_funders",
            "count"(*) AS "philanthropic_grants"
           FROM ("public"."gs_entities" "e"
             JOIN "public"."mv_foundation_grantees" "fg" ON (("fg"."grantee_entity_id" = "e"."id")))
          WHERE ("e"."lga_name" IS NOT NULL)
          GROUP BY "e"."lga_name", "e"."state"
        ), "disadvantage" AS (
         SELECT "pg"."lga_name",
            "pg"."state",
            "avg"("s"."decile_national") FILTER (WHERE ("s"."index_type" = 'IRSD'::"text")) AS "avg_irsd_decile",
            "min"("s"."decile_national") FILTER (WHERE ("s"."index_type" = 'IRSD'::"text")) AS "min_irsd_decile",
            "mode"() WITHIN GROUP (ORDER BY "pg"."remoteness_2021") AS "remoteness"
           FROM ("public"."postcode_geo" "pg"
             LEFT JOIN "public"."seifa_2021" "s" ON (("s"."postcode" = "pg"."postcode")))
          WHERE ("pg"."lga_name" IS NOT NULL)
          GROUP BY "pg"."lga_name", "pg"."state"
        )
 SELECT "o"."lga_name",
    "o"."state",
    "d"."remoteness",
    "round"("d"."avg_irsd_decile", 2) AS "avg_irsd_decile",
    "d"."min_irsd_decile",
    "o"."org_count",
    "o"."community_controlled",
    "o"."without_abn",
    "o"."oric_registered",
    "o"."caring_for_country",
    "o"."employers",
    "o"."income_over_100k",
    COALESCE("c"."contract_count", (0)::bigint) AS "contract_count",
    COALESCE("c"."contract_value_lifetime", (0)::numeric) AS "contract_value_lifetime",
    COALESCE("c"."contract_value_24m", (0)::numeric) AS "contract_value_24m",
    COALESCE("g"."grants_delivered", (0)::bigint) AS "grants_delivered",
    COALESCE("g"."grants_delivered_value", (0)::numeric) AS "grants_delivered_value",
    COALESCE("g"."grants_delivered_24m", (0)::numeric) AS "grants_delivered_24m",
    COALESCE("g"."grants_held_locally_value", (0)::numeric) AS "grants_held_locally_value",
        CASE
            WHEN (COALESCE("g"."grants_delivered_value", (0)::numeric) > (0)::numeric) THEN "round"(((100.0 * COALESCE("g"."grants_held_locally_value", (0)::numeric)) / "g"."grants_delivered_value"), 1)
            ELSE NULL::numeric
        END AS "local_retention_pct",
    COALESCE("p"."philanthropic_funders", (0)::bigint) AS "philanthropic_funders",
    COALESCE("p"."philanthropic_grants", (0)::bigint) AS "philanthropic_grants"
   FROM (((("orgs" "o"
     LEFT JOIN "contracts" "c" ON ((("c"."lga_name" = "o"."lga_name") AND (NOT ("c"."state" IS DISTINCT FROM "o"."state")))))
     LEFT JOIN "delivered" "g" ON ((("g"."lga_name" = "o"."lga_name") AND (NOT ("g"."state" IS DISTINCT FROM "o"."state")))))
     LEFT JOIN "phil" "p" ON ((("p"."lga_name" = "o"."lga_name") AND (NOT ("p"."state" IS DISTINCT FROM "o"."state")))))
     LEFT JOIN "disadvantage" "d" ON ((("d"."lga_name" = "o"."lga_name") AND (NOT ("d"."state" IS DISTINCT FROM "o"."state")))));


ALTER VIEW "public"."v_lga_place_profile" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_lga_place_profile" IS 'One row per LGA. Contracts are attributed by supplier registered address (AusTender has no delivery field); grants by delivery postcode. local_retention_pct is the share of delivered grant money held by an organisation based in that same place. Postcode 0872 is excluded from grant attribution because it spans seven councils.';



CREATE MATERIALIZED VIEW "public"."mv_lga_place_profile" AS
 SELECT "lga_name",
    "state",
    "remoteness",
    "avg_irsd_decile",
    "min_irsd_decile",
    "org_count",
    "community_controlled",
    "without_abn",
    "oric_registered",
    "caring_for_country",
    "employers",
    "income_over_100k",
    "contract_count",
    "contract_value_lifetime",
    "contract_value_24m",
    "grants_delivered",
    "grants_delivered_value",
    "grants_delivered_24m",
    "grants_held_locally_value",
    "local_retention_pct",
    "philanthropic_funders",
    "philanthropic_grants"
   FROM "public"."v_lga_place_profile"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_lga_place_profile" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_lga_place_profile" IS 'Materialized v_lga_place_profile. The view aggregates every LGA before filtering, so reading it per request timed out. Refresh after any funding ingest.';



CREATE MATERIALIZED VIEW "public"."mv_multi_board_persons" AS
 SELECT "person_name_normalised",
    "person_name",
    "count"(DISTINCT "company_abn") AS "board_count",
    "array_agg"(DISTINCT "company_name" ORDER BY "company_name") AS "organisations",
    "array_agg"(DISTINCT "company_abn" ORDER BY "company_abn") AS "organisation_abns",
    "array_agg"(DISTINCT "role_type" ORDER BY "role_type") AS "roles"
   FROM "public"."person_roles" "pr"
  WHERE ("source" = 'acnc'::"text")
  GROUP BY "person_name_normalised", "person_name"
 HAVING ("count"(DISTINCT "company_abn") >= 2)
  ORDER BY ("count"(DISTINCT "company_abn")) DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_multi_board_persons" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_org_justice_signals" AS
 SELECT "abn",
    "name",
    "website",
    "charity_size",
    COALESCE((((
        CASE
            WHEN "purpose_law_policy" THEN 20
            ELSE 0
        END +
        CASE
            WHEN "purpose_human_rights" THEN 20
            ELSE 0
        END) +
        CASE
            WHEN "purpose_social_welfare" THEN 15
            ELSE 0
        END) +
        CASE
            WHEN "purpose_reconciliation" THEN 25
            ELSE 0
        END), 0) AS "purpose_score",
    COALESCE(((((
        CASE
            WHEN "ben_youth" THEN 20
            ELSE 0
        END +
        CASE
            WHEN "ben_children" THEN 15
            ELSE 0
        END) +
        CASE
            WHEN "ben_aboriginal_tsi" THEN 25
            ELSE 0
        END) +
        CASE
            WHEN "ben_pre_post_release" THEN 25
            ELSE 0
        END) +
        CASE
            WHEN "ben_victims_of_crime" THEN 15
            ELSE 0
        END), 0) AS "beneficiary_score",
    "purpose_law_policy",
    "purpose_human_rights",
    "purpose_social_welfare",
    "purpose_reconciliation",
    "ben_youth",
    "ben_children",
    "ben_aboriginal_tsi",
    "ben_pre_post_release",
    "ben_victims_of_crime",
    ( SELECT "f"."id"
           FROM "public"."foundations" "f"
          WHERE ("f"."acnc_abn" = "ac"."abn")
         LIMIT 1) AS "foundation_id",
    (EXISTS ( SELECT 1
           FROM "public"."foundations" "f"
          WHERE ("f"."acnc_abn" = "ac"."abn"))) AS "has_foundation",
    ( SELECT "f"."total_giving_annual"
           FROM "public"."foundations" "f"
          WHERE ("f"."acnc_abn" = "ac"."abn")
          ORDER BY "f"."total_giving_annual" DESC NULLS LAST
         LIMIT 1) AS "total_giving_annual",
    (EXISTS ( SELECT 1
           FROM "public"."foundations" "f"
          WHERE (("f"."acnc_abn" = "ac"."abn") AND ("array_to_string"("f"."thematic_focus", ' '::"text") ~* '(justice|youth|indigenous|aboriginal|detention|incarceration)'::"text")))) AS "has_justice_focus",
    (EXISTS ( SELECT 1
           FROM "public"."oric_corporations" "oc"
          WHERE ("oc"."abn" = "ac"."abn"))) AS "is_oric_registered",
    COALESCE(( SELECT "count"(DISTINCT "jf2"."alma_organization_id") AS "count"
           FROM "public"."justice_funding" "jf2"
          WHERE (("jf2"."recipient_abn" = "ac"."abn") AND ("jf2"."alma_organization_id" IS NOT NULL))), (0)::bigint) AS "intervention_count",
    ( SELECT "array_agg"(DISTINCT "ai"."type") FILTER (WHERE ("ai"."type" IS NOT NULL)) AS "array_agg"
           FROM ("public"."justice_funding" "jf2"
             JOIN "public"."alma_interventions" "ai" ON (("ai"."operating_organization_id" = "jf2"."alma_organization_id")))
          WHERE (("jf2"."recipient_abn" = "ac"."abn") AND ("jf2"."alma_organization_id" IS NOT NULL))) AS "intervention_types",
    COALESCE(( SELECT "sum"("jfund"."amount_dollars") AS "sum"
           FROM "public"."justice_funding" "jfund"
          WHERE ("jfund"."recipient_abn" = "ac"."abn")), (0)::numeric) AS "total_funding_received",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."justice_funding" "jfund"
          WHERE ("jfund"."recipient_abn" = "ac"."abn")), (0)::bigint) AS "grant_count",
    "operates_in_qld",
    "operates_in_nsw",
    "operates_in_vic",
    "operates_in_wa",
    "operates_in_sa",
    "operates_in_tas",
    "operates_in_act",
    "operates_in_nt"
   FROM "public"."acnc_charities" "ac"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_org_justice_signals" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_person_cross_system" AS
 WITH "board_members" AS (
         SELECT "pr"."person_name_normalised",
            "min"("pr"."person_name") AS "person_name",
            "count"(DISTINCT "pr"."entity_id") AS "board_count",
            "array_agg"(DISTINCT "pr"."company_name" ORDER BY "pr"."company_name") AS "board_entities",
            "array_agg"(DISTINCT "pr"."company_abn" ORDER BY "pr"."company_abn") FILTER (WHERE ("pr"."company_abn" IS NOT NULL)) AS "board_abns",
            "max"("pr"."role_type") AS "primary_role"
           FROM "public"."person_roles" "pr"
          WHERE (("pr"."person_name_normalised" IS NOT NULL) AND ("length"("pr"."person_name_normalised") > 3))
          GROUP BY "pr"."person_name_normalised"
        ), "donors" AS (
         SELECT "mv_individual_donors"."person_name_normalised",
            "mv_individual_donors"."donor_name",
            "mv_individual_donors"."total_donated",
            "mv_individual_donors"."parties_funded",
            "mv_individual_donors"."parties",
            "mv_individual_donors"."years_active"
           FROM "public"."mv_individual_donors"
        ), "all_persons" AS (
         SELECT "board_members"."person_name_normalised"
           FROM "board_members"
        UNION
         SELECT "donors"."person_name_normalised"
           FROM "donors"
        )
 SELECT DISTINCT ON ("ap"."person_name_normalised") "ap"."person_name_normalised",
    COALESCE("bm"."person_name", "d"."donor_name") AS "display_name",
    ("bm"."person_name" IS NOT NULL) AS "on_charity_boards",
    ("d"."donor_name" IS NOT NULL) AS "is_political_donor",
    ((("bm"."person_name" IS NOT NULL))::integer + (("d"."donor_name" IS NOT NULL))::integer) AS "system_count",
    COALESCE("bm"."board_count", (0)::bigint) AS "board_count",
    "bm"."board_entities",
    "bm"."board_abns",
    "bm"."primary_role",
    COALESCE("d"."total_donated", (0)::bigint) AS "total_donated",
    COALESCE("d"."parties_funded", (0)::bigint) AS "parties_funded",
    "d"."parties" AS "parties_funded_list",
    COALESCE("d"."years_active", (0)::bigint) AS "donation_years",
    ((((COALESCE("bm"."board_count", (0)::bigint) * 3) +
        CASE
            WHEN ("d"."total_donated" > 1000000) THEN 10
            WHEN ("d"."total_donated" > 100000) THEN 5
            WHEN ("d"."total_donated" > 10000) THEN 2
            ELSE 0
        END) + LEAST(COALESCE("d"."parties_funded", (0)::bigint), (5)::bigint)))::integer AS "influence_score"
   FROM (("all_persons" "ap"
     LEFT JOIN "board_members" "bm" ON (("bm"."person_name_normalised" = "ap"."person_name_normalised")))
     LEFT JOIN "donors" "d" ON (("d"."person_name_normalised" = "ap"."person_name_normalised")))
  WHERE (((("bm"."person_name" IS NOT NULL))::integer + (("d"."donor_name" IS NOT NULL))::integer) >= 2)
  ORDER BY "ap"."person_name_normalised"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_person_cross_system" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_person_entity_network" AS
 WITH "person_boards" AS (
         SELECT "pr"."person_name_normalised",
            "min"("pr"."person_name") AS "person_name_display",
            "pr"."entity_id",
            "e"."canonical_name" AS "entity_name",
            "e"."abn" AS "entity_abn",
            "e"."entity_type",
            "e"."is_community_controlled",
            "pr"."role_type",
            "pr"."source",
            "pr"."appointment_date",
            "pr"."cessation_date"
           FROM ("public"."person_roles" "pr"
             JOIN "public"."gs_entities" "e" ON (("e"."id" = "pr"."entity_id")))
          WHERE (("pr"."entity_id" IS NOT NULL) AND ("pr"."cessation_date" IS NULL))
          GROUP BY "pr"."person_name_normalised", "pr"."entity_id", "e"."canonical_name", "e"."abn", "e"."entity_type", "e"."is_community_controlled", "pr"."role_type", "pr"."source", "pr"."appointment_date", "pr"."cessation_date"
        ), "relevant_entities" AS (
         SELECT DISTINCT "person_boards"."entity_id"
           FROM "person_boards"
        ), "person_entity_count" AS (
         SELECT "person_boards"."person_name_normalised",
            "count"(DISTINCT "person_boards"."entity_id") AS "board_count"
           FROM "person_boards"
          GROUP BY "person_boards"."person_name_normalised"
        ), "procurement_agg" AS (
         SELECT "e"."id" AS "entity_id",
            "sum"("ac"."contract_value") AS "contract_total",
            "count"(*) AS "contract_count"
           FROM ("public"."austender_contracts" "ac"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "ac"."supplier_abn")))
          WHERE (("ac"."supplier_abn" IS NOT NULL) AND ("e"."id" IN ( SELECT "relevant_entities"."entity_id"
                   FROM "relevant_entities")))
          GROUP BY "e"."id"
        ), "justice_agg" AS (
         SELECT "justice_funding"."gs_entity_id" AS "entity_id",
            "sum"("justice_funding"."amount_dollars") AS "justice_total",
            "count"(*) AS "justice_count"
           FROM "public"."justice_funding"
          WHERE (("justice_funding"."gs_entity_id" IN ( SELECT "relevant_entities"."entity_id"
                   FROM "relevant_entities")) AND ("justice_funding"."measure_kind" = 'grant'::"text") AND ("justice_funding"."is_aggregate" IS NOT TRUE) AND ("lower"("btrim"("justice_funding"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"])))
          GROUP BY "justice_funding"."gs_entity_id"
        ), "donation_agg" AS (
         SELECT "e"."id" AS "entity_id",
            "sum"("pd"."amount") AS "donation_total",
            "count"(*) AS "donation_count"
           FROM ("public"."political_donations" "pd"
             JOIN "public"."gs_entities" "e" ON (("e"."abn" = "pd"."donor_abn")))
          WHERE (("pd"."donor_abn" IS NOT NULL) AND ("pd"."receipt_type" = 'donation received'::"text") AND ("e"."id" IN ( SELECT "relevant_entities"."entity_id"
                   FROM "relevant_entities")))
          GROUP BY "e"."id"
        )
 SELECT "pb"."person_name_normalised",
    "pb"."person_name_display",
    "pb"."entity_id",
    "pb"."entity_name",
    "pb"."entity_abn",
    "pb"."entity_type",
    "pb"."is_community_controlled",
    "pb"."role_type",
    "pb"."source",
    "pb"."appointment_date",
    "pec"."board_count",
    COALESCE("pa"."contract_total", (0)::numeric) AS "procurement_dollars",
    COALESCE("pa"."contract_count", (0)::bigint) AS "contract_count",
    COALESCE("ja"."justice_total", (0)::numeric) AS "justice_dollars",
    COALESCE("ja"."justice_count", (0)::bigint) AS "justice_count",
    COALESCE("da"."donation_total", (0)::numeric) AS "donation_dollars",
    COALESCE("da"."donation_count", (0)::bigint) AS "donation_count",
    (("pec"."board_count")::numeric * ((1)::numeric + "ln"(((((1)::numeric + COALESCE("pa"."contract_total", (0)::numeric)) + COALESCE("ja"."justice_total", (0)::numeric)) + COALESCE("da"."donation_total", (0)::numeric))))) AS "influence_score"
   FROM (((("person_boards" "pb"
     JOIN "person_entity_count" "pec" ON (("pec"."person_name_normalised" = "pb"."person_name_normalised")))
     LEFT JOIN "procurement_agg" "pa" ON (("pa"."entity_id" = "pb"."entity_id")))
     LEFT JOIN "justice_agg" "ja" ON (("ja"."entity_id" = "pb"."entity_id")))
     LEFT JOIN "donation_agg" "da" ON (("da"."entity_id" = "pb"."entity_id")))
  WHERE ("pec"."board_count" >= 1)
  ORDER BY (("pec"."board_count")::numeric * ((1)::numeric + "ln"(((((1)::numeric + COALESCE("pa"."contract_total", (0)::numeric)) + COALESCE("ja"."justice_total", (0)::numeric)) + COALESCE("da"."donation_total", (0)::numeric))))) DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_person_entity_network" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_person_identity_network" AS
 WITH "idmap" AS (
         SELECT DISTINCT "pr"."person_name_normalised",
            "pr"."entity_id",
            "pi"."identity_key",
            "pi"."is_nominee_block"
           FROM ("public"."person_identities" "pi"
             JOIN "public"."person_roles" "pr" ON (("pr"."id" = "pi"."role_id")))
        ), "net" AS (
         SELECT COALESCE("m"."identity_key", "n"."person_name_normalised") AS "identity_key",
            "n"."person_name_normalised",
            "n"."person_name_display",
            "n"."entity_id",
            "n"."entity_name",
            "n"."entity_abn",
            "n"."entity_type",
            "n"."source",
            "n"."is_community_controlled",
            COALESCE("m"."is_nominee_block", false) AS "is_nominee_block",
            "n"."procurement_dollars",
            "n"."contract_count",
            "n"."justice_dollars",
            "n"."justice_count",
            "n"."donation_dollars",
            "n"."donation_count"
           FROM ("public"."mv_person_entity_network" "n"
             LEFT JOIN "idmap" "m" ON ((("m"."person_name_normalised" = "n"."person_name_normalised") AND ("m"."entity_id" = "n"."entity_id"))))
        )
 SELECT "identity_key",
    "min"("person_name_normalised") AS "person_name_normalised",
    "min"("person_name_display") AS "person_name_display",
    "entity_id",
    "min"("entity_name") AS "entity_name",
    "min"("entity_abn") AS "entity_abn",
    "min"("entity_type") AS "entity_type",
    "bool_or"("is_community_controlled") AS "is_community_controlled",
    "bool_or"("is_nominee_block") AS "is_nominee_block",
    "array_agg"(DISTINCT "source") AS "sources",
    "max"("procurement_dollars") AS "procurement_dollars",
    "max"("contract_count") AS "contract_count",
    "max"("justice_dollars") AS "justice_dollars",
    "max"("justice_count") AS "justice_count",
    "max"("donation_dollars") AS "donation_dollars",
    "max"("donation_count") AS "donation_count"
   FROM "net"
  GROUP BY "identity_key", "entity_id"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_person_identity_network" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_person_identity_influence" AS
 SELECT "identity_key",
    "min"("person_name_normalised") AS "person_name_normalised",
    "min"("person_name_display") AS "person_name",
    "bool_or"("is_nominee_block") AS "is_nominee_block",
    "count"(*) AS "board_count",
    "count"(*) FILTER (WHERE "is_community_controlled") AS "acco_boards",
    "array_agg"(DISTINCT "entity_type") AS "entity_types",
    "sum"("procurement_dollars") AS "total_procurement",
    "sum"("contract_count") AS "total_contracts",
    "sum"("justice_dollars") AS "total_justice",
    "sum"("donation_dollars") AS "total_donations",
    (((("sum"("procurement_dollars") > (0)::numeric))::integer + (("sum"("justice_dollars") > (0)::numeric))::integer) + (("sum"("donation_dollars") > (0)::numeric))::integer) AS "financial_system_count",
    (("count"(*))::numeric * ((1)::numeric + "ln"(((((1)::numeric + "sum"("procurement_dollars")) + "sum"("justice_dollars")) + "sum"("donation_dollars"))))) AS "influence_score"
   FROM "public"."mv_person_identity_network"
  GROUP BY "identity_key"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_person_identity_influence" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_person_identity_influence_v2" AS
 WITH "entity_directors" AS (
         SELECT "mv_person_identity_network"."entity_id",
            "count"(DISTINCT "mv_person_identity_network"."identity_key") AS "director_count"
           FROM "public"."mv_person_identity_network"
          GROUP BY "mv_person_identity_network"."entity_id"
        ), "edges" AS (
         SELECT "n"."identity_key",
            "n"."person_name_normalised",
            "n"."person_name_display",
            "n"."entity_id",
            "n"."entity_name",
            "n"."entity_abn",
            "n"."entity_type",
            "n"."is_community_controlled",
            "n"."is_nominee_block",
            "n"."sources",
            "n"."procurement_dollars",
            "n"."contract_count",
            "n"."justice_dollars",
            "n"."justice_count",
            "n"."donation_dollars",
            "n"."donation_count",
            GREATEST(COALESCE("ed"."director_count", (1)::bigint), (1)::bigint) AS "director_count"
           FROM ("public"."mv_person_identity_network" "n"
             LEFT JOIN "entity_directors" "ed" ON (("ed"."entity_id" = "n"."entity_id")))
        )
 SELECT "identity_key",
    "min"("person_name_normalised") AS "person_name_normalised",
    "min"("person_name_display") AS "person_name",
    "bool_or"("is_nominee_block") AS "is_nominee_block",
    "count"(*) AS "board_count",
    "count"(*) FILTER (WHERE "is_community_controlled") AS "acco_boards",
    "array_agg"(DISTINCT "entity_type") AS "entity_types",
    "sum"("procurement_dollars") AS "total_procurement_affiliated",
    "sum"("justice_dollars") AS "total_justice_affiliated",
    "sum"("donation_dollars") AS "total_donations_affiliated",
    "sum"(("procurement_dollars" / ("director_count")::numeric)) AS "attributed_procurement",
    "sum"(("justice_dollars" / ("director_count")::numeric)) AS "attributed_justice",
    "sum"(("donation_dollars" / ("director_count")::numeric)) AS "attributed_donations",
    "sum"("contract_count") AS "total_contracts",
    "bool_or"(("director_count" > 1)) AS "shares_board_entities",
    "max"("procurement_dollars") AS "max_single_entity_procurement",
    "max"("director_count") AS "max_board_director_count",
    (((("sum"(("procurement_dollars" / ("director_count")::numeric)) > (0)::numeric))::integer + (("sum"(("justice_dollars" / ("director_count")::numeric)) > (0)::numeric))::integer) + (("sum"(("donation_dollars" / ("director_count")::numeric)) > (0)::numeric))::integer) AS "financial_system_count",
    (("count"(*))::numeric * ((1)::numeric + "ln"(((1)::numeric + "sum"(((("procurement_dollars" + "justice_dollars") + "donation_dollars") / ("director_count")::numeric)))))) AS "influence_score_attributed"
   FROM "edges"
  GROUP BY "identity_key"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_person_identity_influence_v2" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_person_influence" AS
 SELECT "person_name_normalised",
    "min"("person_name_display") AS "person_name",
    "count"(DISTINCT "entity_id") AS "board_count",
    "count"(DISTINCT "entity_id") FILTER (WHERE "is_community_controlled") AS "acco_boards",
    "array_agg"(DISTINCT "entity_type") AS "entity_types",
    "array_agg"(DISTINCT "source") AS "data_sources",
    "sum"("procurement_dollars") AS "total_procurement",
    "sum"("contract_count") AS "total_contracts",
    "sum"("justice_dollars") AS "total_justice",
    "sum"("donation_dollars") AS "total_donations",
    "max"("influence_score") AS "max_influence_score",
    (((("sum"("procurement_dollars") > (0)::numeric))::integer + (("sum"("justice_dollars") > (0)::numeric))::integer) + (("sum"("donation_dollars") > (0)::numeric))::integer) AS "financial_system_count"
   FROM "public"."mv_person_entity_network"
  GROUP BY "person_name_normalised"
  ORDER BY ("max"("influence_score")) DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_person_influence" OWNER TO "postgres";


