CREATE MATERIALIZED VIEW "public"."mv_project_quarter_position" AS
 WITH "all_lines" AS (
         SELECT 'ACCREC'::"text" AS "line_type",
            "xero_invoices"."total",
            "xero_invoices"."date",
            "xero_invoices"."project_code",
            'invoice'::"text" AS "source_table"
           FROM "public"."xero_invoices"
          WHERE (("xero_invoices"."type" = 'ACCREC'::"text") AND ("xero_invoices"."project_code" IS NOT NULL) AND ("xero_invoices"."project_code" <> ''::"text"))
        UNION ALL
         SELECT 'ACCPAY'::"text",
            "xero_invoices"."total",
            "xero_invoices"."date",
            "xero_invoices"."project_code",
            'invoice'::"text"
           FROM "public"."xero_invoices"
          WHERE (("xero_invoices"."type" = 'ACCPAY'::"text") AND ("xero_invoices"."project_code" IS NOT NULL) AND ("xero_invoices"."project_code" <> ''::"text"))
        UNION ALL
         SELECT "xero_transactions"."type",
            "xero_transactions"."total",
            "xero_transactions"."date",
            "xero_transactions"."project_code",
            'bank_txn'::"text"
           FROM "public"."xero_transactions"
          WHERE (("xero_transactions"."bank_account" = ANY (ARRAY['NAB Visa ACT #8815'::"text", 'NJ Marchesi T/as ACT Everyday'::"text"])) AND ("xero_transactions"."project_code" IS NOT NULL) AND ("xero_transactions"."project_code" <> ''::"text") AND ("xero_transactions"."type" !~~ '%TRANSFER%'::"text"))
        )
 SELECT "project_code",
    ("date_trunc"('quarter'::"text", ("date")::timestamp with time zone))::"date" AS "quarter_start",
    (EXTRACT(year FROM "date"))::integer AS "year",
    (EXTRACT(quarter FROM "date"))::integer AS "quarter",
    "sum"(
        CASE
            WHEN ("line_type" = 'ACCREC'::"text") THEN "total"
            ELSE (0)::numeric
        END) AS "revenue_invoiced",
    "sum"(
        CASE
            WHEN ("line_type" = 'ACCPAY'::"text") THEN "total"
            ELSE (0)::numeric
        END) AS "expense_billed",
    "sum"(
        CASE
            WHEN ("line_type" = 'SPEND'::"text") THEN "total"
            ELSE (0)::numeric
        END) AS "expense_bank",
    "sum"(
        CASE
            WHEN ("line_type" = 'RECEIVE'::"text") THEN "total"
            ELSE (0)::numeric
        END) AS "receive_bank",
    "count"(*) FILTER (WHERE ("source_table" = 'invoice'::"text")) AS "invoice_count",
    "count"(*) FILTER (WHERE ("source_table" = 'bank_txn'::"text")) AS "txn_count",
    "count"(*) AS "row_count",
    "now"() AS "materialized_at"
   FROM "all_lines"
  GROUP BY "project_code", ("date_trunc"('quarter'::"text", ("date")::timestamp with time zone)), (EXTRACT(year FROM "date")), (EXTRACT(quarter FROM "date"))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_project_quarter_position" OWNER TO "postgres";


