CREATE TABLE IF NOT EXISTS "public"."mv_refresh_registry" (
    "mv_name" "text" NOT NULL,
    "tier" "text" NOT NULL,
    "enabled" boolean DEFAULT true NOT NULL,
    "force_non_concurrent" boolean DEFAULT false NOT NULL,
    "health" "text",
    "notes" "text",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "max_age_hours" integer,
    CONSTRAINT "mv_refresh_registry_health_check" CHECK ((("health" IS NULL) OR ("health" = ANY (ARRAY['broken_upstream'::"text", 'slow_unmeasured'::"text"])))),
