);


ALTER TABLE "public"."mv_refresh_registry" OWNER TO "postgres";


COMMENT ON TABLE "public"."mv_refresh_registry" IS 'Single source of truth for which materialized views get refreshed and how often. Refresh ORDER is derived from pg_depend by mv_refresh_plan() — do not add an order column. Both pg_cron (refresh_civicgraph_mvs) and scripts/refresh-views-v2.mjs read this table.';



COMMENT ON COLUMN "public"."mv_refresh_registry"."tier" IS 'nightly = daily-cadence source data behind live app surfaces. weekly = slow-changing reference/scoring data, or cost not yet measured. on_demand = refreshed by a named owner (another cron job, an RPC, or a pipeline script). retire = no reader in app code, DB functions, DB views, or other matviews; not refreshed.';



COMMENT ON COLUMN "public"."mv_refresh_registry"."max_age_hours" IS 'Hours after which this matview is overdue. NULL means no schedule owns it, so it cannot be overdue -- only unknown. Set from the tier''s cron cadence plus slack, not from taste.';



CREATE MATERIALIZED VIEW "public"."mv_revolving_door" AS
 WITH "lobbyists" AS (
         SELECT DISTINCT COALESCE("r"."source_entity_id", "r"."target_entity_id") AS "entity_id"
           FROM "public"."gs_relationships" "r"
          WHERE ("r"."relationship_type" = 'lobbies_for'::"text")
        ), "donors" AS (
         SELECT "ge_1"."id" AS "entity_id",
            "count"(*) AS "donation_count",
            "sum"("pd"."amount") AS "total_donated",
            "array_agg"(DISTINCT "pd"."donation_to" ORDER BY "pd"."donation_to") AS "parties"
           FROM ("public"."political_donations" "pd"
             JOIN "public"."gs_entities" "ge_1" ON (("ge_1"."abn" = "pd"."donor_abn")))
          WHERE (("pd"."donor_abn" IS NOT NULL) AND ("pd"."receipt_type" = 'donation received'::"text"))
          GROUP BY "ge_1"."id"
        ), "contractors" AS (
         SELECT "ge_1"."id" AS "entity_id",
            "count"(*) AS "contract_count",
            "sum"("ac"."contract_value") AS "total_contracts",
            "count"(DISTINCT "ac"."buyer_name") AS "distinct_buyers"
           FROM ("public"."austender_contracts" "ac"
             JOIN "public"."gs_entities" "ge_1" ON (("ge_1"."abn" = "ac"."supplier_abn")))
          WHERE ("ac"."supplier_abn" IS NOT NULL)
          GROUP BY "ge_1"."id"
        ), "funded" AS (
         SELECT "justice_funding"."gs_entity_id" AS "entity_id",
            "count"(*) AS "funding_count",
            "sum"("justice_funding"."amount_dollars") AS "total_funded"
           FROM "public"."justice_funding"
          WHERE (("justice_funding"."gs_entity_id" IS NOT NULL) AND ("justice_funding"."measure_kind" = 'grant'::"text") AND ("justice_funding"."is_aggregate" IS NOT TRUE) AND ("lower"("btrim"("justice_funding"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"])))
          GROUP BY "justice_funding"."gs_entity_id"
        )
 SELECT "ge"."id",
    "ge"."gs_id",
    "ge"."canonical_name",
    "ge"."entity_type",
    "ge"."abn",
    "ge"."state",
    "ge"."lga_name",
    "ge"."is_community_controlled",
    ("l"."entity_id" IS NOT NULL) AS "lobbies",
    ("d"."entity_id" IS NOT NULL) AS "donates",
    ("c"."entity_id" IS NOT NULL) AS "contracts",
    ("f"."entity_id" IS NOT NULL) AS "receives_funding",
    ((((("l"."entity_id" IS NOT NULL))::integer + (("d"."entity_id" IS NOT NULL))::integer) + (("c"."entity_id" IS NOT NULL))::integer) + (("f"."entity_id" IS NOT NULL))::integer) AS "influence_vectors",
    COALESCE("d"."total_donated", (0)::numeric) AS "total_donated",
    COALESCE("d"."donation_count", (0)::bigint) AS "donation_count",
    "d"."parties" AS "parties_funded",
    COALESCE("c"."total_contracts", (0)::numeric) AS "total_contracts",
    COALESCE("c"."contract_count", (0)::bigint) AS "contract_count",
    COALESCE("c"."distinct_buyers", (0)::bigint) AS "distinct_buyers",
    COALESCE("f"."total_funded", (0)::numeric) AS "total_funded",
    COALESCE("f"."funding_count", (0)::bigint) AS "funding_count",
    ((((((((("l"."entity_id" IS NOT NULL))::integer * 5) + ((("d"."entity_id" IS NOT NULL))::integer * 3)) + ((("c"."entity_id" IS NOT NULL))::integer * 2)) + ((("f"."entity_id" IS NOT NULL))::integer * 1)) +
        CASE
            WHEN (COALESCE("d"."total_donated", (0)::numeric) > (100000)::numeric) THEN 3
            WHEN (COALESCE("d"."total_donated", (0)::numeric) > (10000)::numeric) THEN 1
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE("c"."total_contracts", (0)::numeric) > (10000000)::numeric) THEN 3
            WHEN (COALESCE("c"."total_contracts", (0)::numeric) > (1000000)::numeric) THEN 1
            ELSE 0
        END) + LEAST("array_length"("d"."parties", 1), 5)) AS "revolving_door_score"
   FROM (((("public"."gs_entities" "ge"
     LEFT JOIN "lobbyists" "l" ON (("l"."entity_id" = "ge"."id")))
     LEFT JOIN "donors" "d" ON (("d"."entity_id" = "ge"."id")))
     LEFT JOIN "contractors" "c" ON (("c"."entity_id" = "ge"."id")))
     LEFT JOIN "funded" "f" ON (("f"."entity_id" = "ge"."id")))
  WHERE (((((("l"."entity_id" IS NOT NULL))::integer + (("d"."entity_id" IS NOT NULL))::integer) + (("c"."entity_id" IS NOT NULL))::integer) + (("f"."entity_id" IS NOT NULL))::integer) >= 2)
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_revolving_door" OWNER TO "postgres";


COMMENT ON MATERIALIZED VIEW "public"."mv_revolving_door" IS 'Entities with 2+ influence vectors (lobbies/donates/contracts/receives funding). Money filters applied 2026-08-16: receipt_type=''donation received'' on donations; measure_kind/is_aggregate/recipient-name on justice_funding grants. See thoughts/shared/data-map/unfiltered-money-views-audit.md';



