CREATE MATERIALIZED VIEW "public"."mv_sa2_map_data" AS
 WITH "entity_funding" AS (
         SELECT "gs_relationships"."target_entity_id" AS "entity_id",
            "sum"("gs_relationships"."amount") AS "total_in"
           FROM "public"."gs_relationships"
          WHERE (("gs_relationships"."amount" IS NOT NULL) AND ("gs_relationships"."amount" > (0)::numeric))
          GROUP BY "gs_relationships"."target_entity_id"
        ), "concordance_entities" AS (
         SELECT "c"."sa2_code",
            "g"."id" AS "entity_id",
            "g"."is_community_controlled",
            COALESCE("f"."total_in", (0)::numeric) AS "funding"
           FROM (("public"."postcode_sa2_concordance" "c"
             JOIN "public"."gs_entities" "g" ON (("g"."postcode" = "c"."postcode")))
             LEFT JOIN "entity_funding" "f" ON (("f"."entity_id" = "g"."id")))
        ), "direct_entities" AS (
         SELECT "g"."sa2_code",
            "g"."id" AS "entity_id",
            "g"."is_community_controlled",
            COALESCE("f"."total_in", (0)::numeric) AS "funding"
           FROM ("public"."gs_entities" "g"
             LEFT JOIN "entity_funding" "f" ON (("f"."entity_id" = "g"."id")))
          WHERE ("g"."sa2_code" IS NOT NULL)
        ), "all_entities" AS (
         SELECT DISTINCT ON ("combined"."sa2_code", "combined"."entity_id") "combined"."sa2_code",
            "combined"."entity_id",
            "combined"."is_community_controlled",
            "combined"."funding"
           FROM ( SELECT "concordance_entities"."sa2_code",
                    "concordance_entities"."entity_id",
                    "concordance_entities"."is_community_controlled",
                    "concordance_entities"."funding"
                   FROM "concordance_entities"
                UNION ALL
                 SELECT "direct_entities"."sa2_code",
                    "direct_entities"."entity_id",
                    "direct_entities"."is_community_controlled",
                    "direct_entities"."funding"
                   FROM "direct_entities") "combined"
        ), "sa2_agg" AS (
         SELECT "all_entities"."sa2_code",
            "count"(DISTINCT "all_entities"."entity_id") AS "entity_count",
            "count"(DISTINCT "all_entities"."entity_id") FILTER (WHERE ("all_entities"."is_community_controlled" = true)) AS "cc_count",
            COALESCE("sum"("all_entities"."funding"), (0)::numeric) AS "total_funding",
            COALESCE("sum"("all_entities"."funding") FILTER (WHERE ("all_entities"."is_community_controlled" = true)), (0)::numeric) AS "cc_funding"
           FROM "all_entities"
          GROUP BY "all_entities"."sa2_code"
        ), "seifa_agg" AS (
         SELECT "c"."sa2_code",
            "avg"("s"."decile_national") AS "avg_seifa"
           FROM ("public"."postcode_sa2_concordance" "c"
             JOIN "public"."seifa_2021" "s" ON ((("s"."postcode" = "c"."postcode") AND ("s"."index_type" = 'IRSD'::"text"))))
          GROUP BY "c"."sa2_code"
        )
 SELECT "r"."sa2_code",
    "r"."sa2_name",
    COALESCE("e"."total_funding", (0)::numeric) AS "total_funding",
    COALESCE("e"."entity_count", (0)::bigint) AS "entity_count",
    COALESCE("e"."cc_count", (0)::bigint) AS "community_controlled_count",
        CASE
            WHEN (COALESCE("e"."total_funding", (0)::numeric) > (0)::numeric) THEN ("round"(((100.0 * COALESCE("e"."cc_funding", (0)::numeric)) / "e"."total_funding")))::integer
            ELSE 0
        END AS "community_controlled_pct",
        CASE
            WHEN (COALESCE("e"."total_funding", (0)::numeric) > (0)::numeric) THEN ("round"((100.0 * ((1)::numeric - (COALESCE("e"."cc_funding", (0)::numeric) / "e"."total_funding")))))::integer
            ELSE 100
        END AS "external_provider_pct",
    ("round"(((((10)::numeric - COALESCE("sf"."avg_seifa", (5)::numeric)) / 10.0) * (100)::numeric)))::integer AS "need_gap",
    ("round"(COALESCE("sf"."avg_seifa", (5)::numeric)))::integer AS "seifa_decile"
   FROM (("public"."sa2_reference" "r"
     LEFT JOIN "sa2_agg" "e" ON (("e"."sa2_code" = "r"."sa2_code")))
     LEFT JOIN "seifa_agg" "sf" ON (("sf"."sa2_code" = "r"."sa2_code")))
  ORDER BY COALESCE("e"."total_funding", (0)::numeric) DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_sa2_map_data" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_temporal_summary" AS
 SELECT "abn",
    "donor_name",
    "count"(DISTINCT "donation_date") AS "donation_count",
    "count"(DISTINCT "contract_id") AS "contracts_after_donation",
    "sum"(DISTINCT "donation_amount") AS "total_donated",
    "sum"("contract_value") AS "total_contracts_after",
    "round"("avg"("days_between")) AS "avg_days_to_contract",
    "min"("days_between") AS "min_days_to_contract",
    "count"(*) FILTER (WHERE ("timing_window" = 'immediate'::"text")) AS "immediate_contracts",
    "count"(*) FILTER (WHERE ("timing_window" = 'short'::"text")) AS "short_window_contracts",
    "count"(*) FILTER (WHERE ("timing_window" = 'medium'::"text")) AS "medium_window_contracts",
        CASE
            WHEN ("sum"(DISTINCT "donation_amount") > (0)::numeric) THEN "round"(("sum"("contract_value") / "sum"(DISTINCT "donation_amount")), 1)
            ELSE (0)::numeric
        END AS "overall_roi",
    "array_agg"(DISTINCT "party") AS "parties"
   FROM "public"."mv_donation_contract_timing"
  GROUP BY "abn", "donor_name"
 HAVING ("count"(DISTINCT "contract_id") >= 1)
  ORDER BY ("sum"("contract_value")) DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_temporal_summary" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_triple_proof_suppliers" AS
 WITH "base" AS (
         SELECT DISTINCT ON ("g"."abn") "g"."id" AS "entity_id",
            "g"."gs_id",
            "g"."abn",
            "g"."canonical_name",
            "g"."entity_type",
            "g"."state",
            "g"."postcode",
            "g"."sector",
            "g"."lga_name",
            "g"."is_community_controlled"
           FROM "public"."gs_entities" "g"
          WHERE (("g"."abn" IS NOT NULL) AND (EXISTS ( SELECT 1
                   FROM "public"."justice_funding" "j"
                  WHERE ("j"."recipient_abn" = "g"."abn"))) AND (EXISTS ( SELECT 1
                   FROM "public"."austender_contracts" "c"
                  WHERE ("c"."supplier_abn" = "g"."abn"))) AND (EXISTS ( SELECT 1
                   FROM "public"."acnc_charities" "a"
                  WHERE ("a"."abn" = "g"."abn"))))
          ORDER BY "g"."abn", "g"."gs_id"
        ), "jf" AS (
         SELECT "justice_funding"."recipient_abn" AS "abn",
            "sum"("justice_funding"."amount_dollars") AS "justice_dollars",
            "count"(*) AS "justice_record_count",
            "count"(DISTINCT "justice_funding"."program_name") AS "distinct_justice_programs",
            "array_agg"(DISTINCT "justice_funding"."state") FILTER (WHERE ("justice_funding"."state" IS NOT NULL)) AS "justice_states"
           FROM "public"."justice_funding"
          WHERE ("justice_funding"."recipient_abn" IN ( SELECT "base"."abn"
                   FROM "base"))
          GROUP BY "justice_funding"."recipient_abn"
        ), "ct" AS (
         SELECT "austender_contracts"."supplier_abn" AS "abn",
            "count"(*) AS "contract_count",
            "sum"("austender_contracts"."contract_value") AS "contract_value",
            "count"(DISTINCT "austender_contracts"."buyer_name") AS "distinct_buyers",
            "max"("austender_contracts"."contract_end") AS "last_contract_end",
            "min"("austender_contracts"."contract_start") AS "first_contract_start"
           FROM "public"."austender_contracts"
          WHERE ("austender_contracts"."supplier_abn" IN ( SELECT "base"."abn"
                   FROM "base"))
          GROUP BY "austender_contracts"."supplier_abn"
        ), "ac" AS (
         SELECT DISTINCT ON ("acnc_charities"."abn") "acnc_charities"."abn",
            "acnc_charities"."charity_size",
            "acnc_charities"."name" AS "acnc_name",
            "acnc_charities"."registration_date" AS "acnc_registered_since"
           FROM "public"."acnc_charities"
          WHERE ("acnc_charities"."abn" IN ( SELECT "base"."abn"
                   FROM "base"))
          ORDER BY "acnc_charities"."abn", "acnc_charities"."registration_date"
        )
 SELECT "b"."gs_id",
    "b"."abn",
    "b"."canonical_name",
    "b"."entity_type",
    "b"."state",
    "b"."postcode",
    "b"."sector",
    "b"."lga_name",
    "b"."is_community_controlled",
    "jf"."justice_dollars",
    "jf"."justice_record_count",
    "jf"."distinct_justice_programs",
    "jf"."justice_states",
    "ct"."contract_count",
    "ct"."contract_value",
    "ct"."distinct_buyers",
    "ct"."last_contract_end",
    "ct"."first_contract_start",
    "ac"."charity_size",
    "ac"."acnc_name",
    "ac"."acnc_registered_since",
    (COALESCE("jf"."justice_dollars", (0)::numeric) + COALESCE("ct"."contract_value", (0)::numeric)) AS "total_evidence_dollars",
    (EXISTS ( SELECT 1
           FROM "public"."alma_interventions" "ai"
          WHERE (("ai"."gs_entity_id" = "b"."entity_id") AND (EXISTS ( SELECT 1
                   FROM "public"."alma_intervention_evidence" "e"
                  WHERE ("e"."intervention_id" = "ai"."id"))) AND (EXISTS ( SELECT 1
                   FROM "public"."alma_intervention_outcomes" "o"
                  WHERE ("o"."intervention_id" = "ai"."id")))))) AS "has_alma_evidence_outcomes"
   FROM ((("base" "b"
     LEFT JOIN "jf" ON (("jf"."abn" = "b"."abn")))
     LEFT JOIN "ct" ON (("ct"."abn" = "b"."abn")))
     LEFT JOIN "ac" ON (("ac"."abn" = "b"."abn")))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_triple_proof_suppliers" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_trustee_grantee_overlaps" AS
 SELECT "pr_foundation"."person_name_normalised",
    "pr_foundation"."company_name" AS "foundation_name",
    "pr_foundation"."company_abn" AS "foundation_abn",
    "pr_recipient"."company_name" AS "recipient_name",
    "pr_recipient"."company_abn" AS "recipient_abn",
    "f"."total_giving_annual" AS "foundation_giving",
    ("sum"("jf"."amount_dollars"))::bigint AS "funding_to_recipient",
    "count"(DISTINCT "jf"."id") AS "grant_count"
   FROM ((("public"."person_roles" "pr_foundation"
     JOIN "public"."foundations" "f" ON (("f"."acnc_abn" = "pr_foundation"."company_abn")))
     JOIN "public"."person_roles" "pr_recipient" ON ((("pr_recipient"."person_name_normalised" = "pr_foundation"."person_name_normalised") AND ("pr_recipient"."company_abn" IS NOT NULL) AND ("pr_recipient"."company_abn" <> "pr_foundation"."company_abn"))))
     JOIN "public"."justice_funding" "jf" ON (("jf"."recipient_abn" = "pr_recipient"."company_abn")))
  WHERE (("pr_foundation"."company_abn" IS NOT NULL) AND ("jf"."amount_dollars" > (0)::numeric))
  GROUP BY "pr_foundation"."person_name_normalised", "pr_foundation"."company_name", "pr_foundation"."company_abn", "pr_recipient"."company_name", "pr_recipient"."company_abn", "f"."total_giving_annual"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_trustee_grantee_overlaps" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_yj_report_acco_gap" AS
 SELECT
        CASE
            WHEN "ge"."is_community_controlled" THEN 'Community Controlled'::"text"
            ELSE 'Other service providers'::"text"
        END AS "org_type",
    ("count"(DISTINCT "jf"."recipient_name"))::integer AS "orgs",
    ("sum"("jf"."amount_dollars"))::bigint AS "total_funding",
    ("round"(("sum"("jf"."amount_dollars") / (NULLIF("count"(DISTINCT "jf"."recipient_name"), 0))::numeric)))::bigint AS "avg_per_recipient",
    ("round"("avg"("jf"."amount_dollars")))::bigint AS "avg_grant",
    ("count"(*))::integer AS "funding_rows",
    ("round"((("sum"("jf"."amount_dollars") / NULLIF("sum"("sum"("jf"."amount_dollars")) OVER (), (0)::numeric)) * (100)::numeric), 1))::double precision AS "funding_share_pct"
   FROM ("public"."justice_funding" "jf"
     JOIN "public"."gs_entities" "ge" ON (("ge"."id" = "jf"."gs_entity_id")))
  WHERE (("jf"."topics" @> ARRAY['youth-justice'::"text"]) AND ("jf"."measure_kind" = 'grant'::"text") AND ("jf"."is_aggregate" IS NOT TRUE) AND (("jf"."recipient_name" IS NULL) OR ("lower"("btrim"("jf"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"]))) AND ("jf"."source" <> 'austender-direct'::"text") AND ("jf"."amount_dollars" IS NOT NULL) AND ("jf"."amount_dollars" > (0)::numeric) AND ("jf"."recipient_name" IS NOT NULL) AND ("jf"."recipient_name" <> ''::"text") AND ("jf"."recipient_name" <> 'Total'::"text") AND ("jf"."recipient_name" !~* '^(Department of|Dept |Queensland Government|NSW Government|Victorian Government|Government of|State of|Commonwealth Government)'::"text") AND ("jf"."recipient_name" <> ALL (ARRAY['Territory Families, Housing and Communities'::"text", 'Community Services Directorate'::"text"])) AND ("jf"."program_name" !~~ 'ROGS%'::"text") AND ("jf"."program_name" !~~ 'Total%'::"text"))
  GROUP BY
        CASE
            WHEN "ge"."is_community_controlled" THEN 'Community Controlled'::"text"
            ELSE 'Other service providers'::"text"
        END
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_yj_report_acco_gap" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_yj_report_alma_interventions" AS
 SELECT "row_number"() OVER (ORDER BY "ai"."portfolio_score" DESC NULLS LAST, "ai"."name") AS "snapshot_rank",
    "ai"."name",
    "ai"."type",
    "ai"."evidence_level",
    ("ai"."geography")::"text" AS "geography",
    ("ai"."portfolio_score")::double precision AS "portfolio_score",
    "e"."gs_id",
    "e"."canonical_name" AS "org_name",
    "e"."abn" AS "org_abn"
   FROM ("public"."alma_interventions" "ai"
     LEFT JOIN "public"."gs_entities" "e" ON (("e"."id" = "ai"."gs_entity_id")))
  WHERE ("ai"."topics" @> ARRAY['youth-justice'::"text"])
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_yj_report_alma_interventions" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_yj_report_alma_type_counts" AS
 SELECT COALESCE("type", 'Uncategorised'::"text") AS "type",
    ("count"(*))::integer AS "count"
   FROM "public"."alma_interventions"
  WHERE ("topics" @> ARRAY['youth-justice'::"text"])
  GROUP BY COALESCE("type", 'Uncategorised'::"text")
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_yj_report_alma_type_counts" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_yj_report_contracts" AS
 SELECT "row_number"() OVER (ORDER BY "contract_value" DESC NULLS LAST, "title") AS "snapshot_rank",
    "buyer_name",
    "supplier_name",
    ("contract_value")::bigint AS "amount",
    (EXTRACT(year FROM "contract_start"))::integer AS "year",
    "title"
   FROM "public"."austender_contracts" "ac"
  WHERE (("title" ~~* '%youth%justice%'::"text") OR ("title" ~~* '%juvenile%detention%'::"text") OR ("title" ~~* '%youth%detention%'::"text"))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_yj_report_contracts" OWNER TO "postgres";


