CREATE OR REPLACE VIEW "public"."v_ndis_youth_justice_overlay" AS
 SELECT "service_district",
    "state",
    "sum"(
        CASE
            WHEN (("disability_group" = 'ALL'::"text") AND ("age_band" = 'ALL'::"text")) THEN "active_participants"
            ELSE NULL::integer
        END) AS "total_participants",
    "sum"(
        CASE
            WHEN (("disability_group" = 'Psychosocial disability'::"text") AND ("age_band" = 'ALL'::"text")) THEN "active_participants"
            ELSE NULL::integer
        END) AS "psychosocial_participants",
    "sum"(
        CASE
            WHEN (("disability_group" = 'Intellectual Disability'::"text") AND ("age_band" = 'ALL'::"text")) THEN "active_participants"
            ELSE NULL::integer
        END) AS "intellectual_disability_participants",
    "sum"(
        CASE
            WHEN (("disability_group" = 'Autism'::"text") AND ("age_band" = 'ALL'::"text")) THEN "active_participants"
            ELSE NULL::integer
        END) AS "autism_participants",
    "sum"(
        CASE
            WHEN (("disability_group" = 'ALL'::"text") AND ("age_band" = ANY (ARRAY['0 to 8'::"text", '9 to 14'::"text", '15 to 18'::"text"]))) THEN "active_participants"
            ELSE NULL::integer
        END) AS "youth_participants",
    "sum"(
        CASE
            WHEN (("disability_group" = 'ALL'::"text") AND ("age_band" = 'ALL'::"text")) THEN ("avg_annual_budget" * ("active_participants")::numeric)
            ELSE NULL::numeric
        END) AS "total_annual_budget",
    "avg"(
        CASE
            WHEN (("disability_group" = 'ALL'::"text") AND ("age_band" = 'ALL'::"text")) THEN "avg_annual_budget"
            ELSE NULL::numeric
        END) AS "avg_budget_per_participant"
   FROM "public"."ndis_participants" "np"
  WHERE ("support_class" = 'ALL'::"text")
  GROUP BY "service_district", "state";


ALTER VIEW "public"."v_ndis_youth_justice_overlay" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_yj_report_coverage" AS
 SELECT ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."justice_funding") AS "justice_funding_rows",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."justice_funding"
          WHERE (("justice_funding"."topics" @> ARRAY['youth-justice'::"text"]) AND ("justice_funding"."source" <> 'austender-direct'::"text"))) AS "youth_justice_funding_rows",
    ( SELECT (COALESCE("sum"("justice_funding"."amount_dollars"), (0)::numeric))::bigint AS "coalesce"
           FROM "public"."justice_funding"
          WHERE (("justice_funding"."topics" @> ARRAY['youth-justice'::"text"]) AND ("justice_funding"."source" <> 'austender-direct'::"text"))) AS "youth_justice_funding_dollars",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."justice_funding"
          WHERE ("justice_funding"."source" = 'rogs-2026'::"text")) AS "rogs_rows_in_justice_funding",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."rogs_justice_spending"
          WHERE ("rogs_justice_spending"."rogs_section" = 'youth_justice'::"text")) AS "rogs_rows_in_rogs_table",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."alma_interventions"
          WHERE ("alma_interventions"."topics" @> ARRAY['youth-justice'::"text"])) AS "alma_tagged",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."alma_interventions"
          WHERE (("alma_interventions"."topics" @> ARRAY['youth-justice'::"text"]) OR ("alma_interventions"."serves_youth_justice" = true) OR (("alma_interventions"."target_cohort")::"text" ~~* '%youth justice%'::"text") OR ("alma_interventions"."description" ~~* '%youth justice%'::"text"))) AS "alma_serves_youth_justice",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."lga_cross_system_stats"
          WHERE (("lga_cross_system_stats"."school_count" > 0) OR ("lga_cross_system_stats"."dsp_recipients" > 0) OR ("lga_cross_system_stats"."ndis_youth_participants" > 0))) AS "lga_cross_system_rows",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."v_ndis_youth_justice_overlay"
          WHERE ("v_ndis_youth_justice_overlay"."state" <> 'OT'::"text")) AS "ndis_overlay_rows",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."austender_contracts"
          WHERE (("austender_contracts"."title" ~~* '%youth%justice%'::"text") OR ("austender_contracts"."title" ~~* '%juvenile%detention%'::"text") OR ("austender_contracts"."title" ~~* '%youth%detention%'::"text"))) AS "austender_contracts",
    ( SELECT (COALESCE("sum"("austender_contracts"."contract_value"), (0)::numeric))::bigint AS "coalesce"
           FROM "public"."austender_contracts"
          WHERE (("austender_contracts"."title" ~~* '%youth%justice%'::"text") OR ("austender_contracts"."title" ~~* '%juvenile%detention%'::"text") OR ("austender_contracts"."title" ~~* '%youth%detention%'::"text"))) AS "austender_contract_dollars",
    ( SELECT ("count"(DISTINCT "outcomes_metrics"."metric_name"))::integer AS "count"
           FROM "public"."outcomes_metrics"
          WHERE ("outcomes_metrics"."domain" = 'youth-justice'::"text")) AS "outcome_metric_names"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_yj_report_coverage" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_yj_report_dss_payments" AS
 SELECT "state",
    "payment_type",
    ("sum"("recipient_count"))::integer AS "recipients"
   FROM "public"."dss_payment_demographics"
  WHERE (("payment_type" = ANY (ARRAY['Disability Support Pension'::"text", 'Youth Allowance (other)'::"text", 'JobSeeker Payment'::"text"])) AND ("geography_type" = 'state'::"text") AND ("state" <> 'Unknown'::"text"))
  GROUP BY "state", "payment_type"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_yj_report_dss_payments" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_yj_report_foundations" AS
 SELECT "f"."name",
    ("f"."total_giving_annual")::bigint AS "total_giving_annual",
    ("f"."thematic_focus")::"text" AS "thematic_focus",
    ("f"."geographic_focus")::"text" AS "geographic_focus",
    "ge"."gs_id"
   FROM ("public"."foundations" "f"
     LEFT JOIN "public"."gs_entities" "ge" ON (("ge"."id" = "f"."gs_entity_id")))
  WHERE (((("f"."thematic_focus")::"text" ~~* '%justice%'::"text") OR (("f"."thematic_focus")::"text" ~~* '%youth%'::"text") OR ((("f"."thematic_focus")::"text" ~~* '%indigenous%'::"text") AND ("f"."total_giving_annual" > (50000000)::numeric))) AND (("f"."name" ~~* '%foundation%'::"text") OR ("f"."name" ~~* '%trust%'::"text") OR ("f"."name" ~~* '%philanthropic%'::"text") OR ("f"."name" ~~* '%endowment%'::"text")) AND ("f"."name" !~~* '%university%'::"text"))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_yj_report_foundations" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_yj_report_heatmap" AS
 WITH "alma_by_lga" AS (
         SELECT "ge"."lga_name",
            ("count"(*))::integer AS "alma_count"
           FROM ("public"."alma_interventions" "ai"
             JOIN "public"."gs_entities" "ge" ON (("ge"."id" = "ai"."gs_entity_id")))
          WHERE (("ai"."topics" @> ARRAY['youth-justice'::"text"]) AND ("ge"."lga_name" IS NOT NULL))
          GROUP BY "ge"."lga_name"
        )
 SELECT "l"."lga_name",
    "l"."state",
    COALESCE("l"."population", 0) AS "population",
    COALESCE("l"."low_icsea_schools", 0) AS "low_icsea",
    COALESCE("l"."avg_icsea", 0) AS "avg_icsea",
    COALESCE("l"."school_count", 0) AS "schools",
    (COALESCE("l"."indigenous_pct", (0)::numeric))::double precision AS "indigenous_pct",
    (
        CASE
            WHEN ("l"."population" > 0) THEN "round"(((("l"."dsp_recipients")::numeric / ("l"."population")::numeric) * (1000)::numeric))
            ELSE (0)::numeric
        END)::integer AS "dsp_rate",
    (
        CASE
            WHEN ("l"."population" > 0) THEN "round"(((("l"."jobseeker_recipients")::numeric / ("l"."population")::numeric) * (1000)::numeric))
            ELSE (0)::numeric
        END)::integer AS "jobseeker_rate",
    (
        CASE
            WHEN ("l"."population" > 0) THEN "round"(((("l"."youth_allowance_recipients")::numeric / ("l"."population")::numeric) * (1000)::numeric))
            ELSE (0)::numeric
        END)::integer AS "youth_allowance_rate",
    (COALESCE("l"."cost_per_detention_day", (0)::numeric))::integer AS "cost_per_day",
    ("l"."recidivism_pct")::integer AS "recidivism_pct",
    (COALESCE("l"."indigenous_rate_ratio", (0)::numeric))::double precision AS "indigenous_rate_ratio",
    (COALESCE("l"."detention_indigenous_pct", (0)::numeric))::integer AS "detention_indigenous_pct",
    (
        CASE
            WHEN ("l"."population" > 0) THEN "round"(((("l"."ndis_youth_participants")::numeric / ("l"."population")::numeric) * (1000)::numeric))
            ELSE (0)::numeric
        END)::integer AS "ndis_rate",
    (COALESCE("l"."crime_rate_per_100k", (0)::numeric))::integer AS "crime_rate",
    COALESCE("a"."alma_count", 0) AS "alma_count"
   FROM ("public"."lga_cross_system_stats" "l"
     LEFT JOIN "alma_by_lga" "a" ON (("a"."lga_name" = "l"."lga_name")))
  WHERE (("l"."school_count" > 0) OR ("l"."dsp_recipients" > 0) OR ("l"."ndis_youth_participants" > 0))
  WITH NO DATA;


