    ("count"(*))::integer AS "grants"
   FROM ("public"."justice_funding" "jf"
     JOIN "public"."gs_entities" "ge" ON (("ge"."id" = "jf"."gs_entity_id")))
  WHERE (("jf"."topics" @> ARRAY['youth-justice'::"text"]) AND ("jf"."measure_kind" = 'grant'::"text") AND ("jf"."is_aggregate" IS NOT TRUE) AND (("jf"."recipient_name" IS NULL) OR ("lower"("btrim"("jf"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"]))) AND ("jf"."source" <> 'austender-direct'::"text") AND ("jf"."program_name" !~~ 'ROGS%'::"text") AND ("jf"."program_name" !~~ 'Total%'::"text") AND ("ge"."remoteness" IS NOT NULL))
  GROUP BY "ge"."remoteness"
  WITH NO DATA;


