CREATE MATERIALIZED VIEW "public"."mv_yj_report_state_top_orgs" AS
 WITH "provider_rows" AS (
         SELECT "jf"."id",
            "jf"."source",
            "jf"."source_url",
            "jf"."source_statement_id",
            "jf"."recipient_name",
            "jf"."recipient_abn",
            "jf"."program_name",
            "jf"."program_round",
            "jf"."amount_dollars",
            "jf"."state",
            "jf"."location",
            "jf"."funding_type",
            "jf"."sector",
            "jf"."project_description",
            "jf"."announcement_date",
            "jf"."financial_year",
            "jf"."alma_intervention_id",
            "jf"."alma_organization_id",
            "jf"."created_at",
            "jf"."updated_at",
            "jf"."gs_entity_id",
            "jf"."topics",
            "jf"."is_aggregate"
           FROM "public"."justice_funding" "jf"
          WHERE (("jf"."topics" @> ARRAY['youth-justice'::"text"]) AND ("jf"."measure_kind" = 'grant'::"text") AND ("jf"."is_aggregate" IS NOT TRUE) AND (("jf"."recipient_name" IS NULL) OR ("lower"("btrim"("jf"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'grand total'::"text", 'subtotal'::"text", 'sub-total'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'tbc'::"text", 'other'::"text"]))) AND ("jf"."source" <> 'austender-direct'::"text") AND ("jf"."amount_dollars" IS NOT NULL) AND ("jf"."amount_dollars" > (0)::numeric) AND ("jf"."state" IS NOT NULL) AND ("jf"."program_name" !~~ 'ROGS%'::"text") AND ("jf"."program_name" !~~ 'Total%'::"text") AND ("jf"."recipient_name" IS NOT NULL) AND ("jf"."recipient_name" <> ''::"text") AND ("jf"."recipient_name" <> 'Total'::"text") AND ("jf"."recipient_name" !~~ 'Youth Justice -%'::"text") AND ("jf"."recipient_name" !~~ 'Department of%'::"text") AND ("jf"."recipient_name" !~~ 'State of%'::"text") AND ("jf"."recipient_name" !~~ 'Multiple%'::"text") AND ("jf"."recipient_name" <> ALL (ARRAY['Territory Families, Housing and Communities'::"text", 'Community Services Directorate'::"text"])))
        ), "ranked" AS (
         SELECT "jf"."state",
            "jf"."recipient_name",
            "jf"."recipient_abn",
            ("sum"("jf"."amount_dollars"))::bigint AS "total",
            ("count"(*))::integer AS "grants",
            COALESCE("linked"."gs_id", "by_abn"."gs_id") AS "gs_id",
            "row_number"() OVER (PARTITION BY "jf"."state" ORDER BY ("sum"("jf"."amount_dollars")) DESC NULLS LAST, "jf"."recipient_name") AS "rn"
           FROM (("provider_rows" "jf"
             LEFT JOIN "public"."gs_entities" "linked" ON (("linked"."id" = "jf"."gs_entity_id")))
             LEFT JOIN LATERAL ( SELECT "gs_entities"."gs_id"
                   FROM "public"."gs_entities"
                  WHERE ("gs_entities"."abn" = "jf"."recipient_abn")
                  ORDER BY "gs_entities"."source_count" DESC NULLS LAST
                 LIMIT 1) "by_abn" ON (("jf"."recipient_abn" IS NOT NULL)))
          GROUP BY "jf"."state", "jf"."recipient_name", "jf"."recipient_abn", COALESCE("linked"."gs_id", "by_abn"."gs_id")
        )
 SELECT "state",
    "recipient_name",
    "recipient_abn",
    "grants",
    "total",
    "gs_id"
   FROM "ranked"
