CREATE OR REPLACE VIEW "public"."org_governance" AS
 WITH "current_roles" AS (
         SELECT "pr"."company_abn",
            "pr"."person_name",
            "pr"."person_name_normalised",
            "pr"."role_type",
            "pr"."appointment_date",
            "pr"."source",
            NULLIF(("pr"."properties" ->> 'person_uuid'::"text"), ''::"text") AS "person_uuid"
           FROM "public"."person_roles" "pr"
          WHERE (("pr"."cessation_date" IS NULL) AND ("pr"."company_abn" IS NOT NULL) AND ("length"(TRIM(BOTH FROM COALESCE("pr"."person_name", ''::"text"))) > 1))
        ), "org_counts" AS (
         SELECT "current_roles"."person_uuid",
            "count"(DISTINCT "current_roles"."company_abn") AS "org_count"
           FROM "current_roles"
          WHERE ("current_roles"."person_uuid" IS NOT NULL)
          GROUP BY "current_roles"."person_uuid"
        ), "nominees" AS (
         SELECT DISTINCT "person_identities"."person_name_normalised"
           FROM "public"."person_identities"
          WHERE "person_identities"."is_nominee_block"
        )
 SELECT "r"."company_abn",
    "r"."person_name",
    "r"."role_type",
    "r"."appointment_date",
    "r"."source",
    GREATEST((COALESCE("c"."org_count", (1)::bigint) - 1), (0)::bigint) AS "also_governs_count",
    ("n"."person_name_normalised" IS NOT NULL) AS "is_nominee_block",
    ("r"."person_uuid" IS NOT NULL) AS "identity_resolved"
   FROM (("current_roles" "r"
     LEFT JOIN "org_counts" "c" ON (("c"."person_uuid" = "r"."person_uuid")))
     LEFT JOIN "nominees" "n" ON (("n"."person_name_normalised" = "r"."person_name_normalised")));


ALTER VIEW "public"."org_governance" OWNER TO "postgres";


COMMENT ON VIEW "public"."org_governance" IS 'Current office-holders per organisation, from the public registers, with a COUNT of other organisations each person governs. Counted by the ACNC person_uuid rather than by name, because name matching conflates different people and nominee arrangements. There is deliberately no list of which other organisations: that is a claim about a person, not about this organisation.';



