CREATE OR REPLACE VIEW "public"."pending_extractions" WITH ("security_invoker"='true') AS
 SELECT "id",
    "source_type",
    "source_id",
    "source_url",
    "source_metadata",
    "raw_content",
    "raw_title",
    "extracted_knowledge",
    "suggested_title",
    "suggested_type",
    "suggested_excerpt",
    "suggested_projects",
    "suggested_domains",
    "suggested_tags",
    "suggested_parent_ids",
    "confidence_score",
    "status",
    "reviewed_by",
    "reviewed_at",
    "review_notes",
    "wiki_page_id",
    "extracted_at",
    "extraction_model",
    "extraction_prompt",
    "priority",
    "created_at",
        CASE
            WHEN ("confidence_score" >= 0.8) THEN 'high'::"text"
            WHEN ("confidence_score" >= 0.5) THEN 'medium'::"text"
            ELSE 'low'::"text"
        END AS "confidence_level"
   FROM "public"."knowledge_extraction_queue" "e"
  WHERE ("status" = 'pending'::"text")
  ORDER BY "priority" DESC, "confidence_score" DESC, "created_at";


ALTER VIEW "public"."pending_extractions" OWNER TO "postgres";


