CREATE OR REPLACE VIEW "public"."pending_proposals" WITH ("security_invoker"='true') AS
 SELECT "p"."id",
    "p"."agent_id",
    "p"."title",
    "p"."description",
    "p"."priority",
    "p"."deadline",
    "p"."created_at",
    "a"."autonomy_level",
    "a"."risk_level",
    ("p"."reasoning" ->> 'trigger'::"text") AS "trigger_reason",
    ("p"."reasoning" ->> 'confidence'::"text") AS "confidence",
    "p"."impact_assessment"
   FROM ("public"."agent_proposals" "p"
     LEFT JOIN "public"."agent_actions" "a" ON (("p"."action_id" = "a"."id")))
  WHERE ("p"."status" = 'pending'::"text")
  ORDER BY
        CASE "p"."priority"
            WHEN 'urgent'::"text" THEN 1
            WHEN 'high'::"text" THEN 2
            WHEN 'normal'::"text" THEN 3
            ELSE 4
        END, "p"."created_at";


