CREATE OR REPLACE VIEW "public"."programs_catalog_v" WITH ("security_invoker"='true') AS
 SELECT "rs"."id",
    "rs"."name",
    COALESCE(NULLIF("rs"."description", ''::"text"), "ai"."description") AS "description",
    "rs"."organization_id",
    COALESCE("org"."name", NULLIF("rs"."organization", ''::"text"), "ai"."operating_organization") AS "organization_name",
    NULLIF("rs"."organization", ''::"text") AS "organization",
    "org"."slug" AS "organization_slug",
    COALESCE(NULLIF("rs"."state", ''::"text"), "org"."state", "ai"."geography"[1]) AS "state",
    COALESCE(NULLIF("rs"."location", ''::"text"), "org"."location") AS "location",
    COALESCE(NULLIF("rs"."approach", ''::"text"), "ai"."type") AS "approach",
    COALESCE(NULLIF("rs"."impact_summary", ''::"text"), "ai"."description") AS "impact_summary",
    "rs"."success_rate",
    "rs"."participants_served",
    "rs"."years_operating",
    "rs"."founded_year",
    "rs"."contact_phone",
    "rs"."contact_email",
    "rs"."website",
    "rs"."indigenous_knowledge",
    "rs"."community_connection_score",
    COALESCE("rs"."tags", "ai"."target_cohort") AS "tags",
    COALESCE("rs"."latitude", "ai"."latitude") AS "latitude",
    COALESCE("rs"."longitude", "ai"."longitude") AS "longitude",
    COALESCE("rs"."alma_intervention_id", "ai"."id") AS "alma_intervention_id",
    COALESCE("rs"."linked_service_id", "ai"."linked_service_id") AS "linked_service_id",
    COALESCE("rs"."is_featured", false) AS "is_featured",
    "rs"."created_at",
    "rs"."updated_at"
   FROM (("public"."registered_services" "rs"
     LEFT JOIN "public"."organizations" "org" ON (("org"."id" = "rs"."organization_id")))
     LEFT JOIN LATERAL ( SELECT "ai_pick"."id",
            "ai_pick"."created_at",
            "ai_pick"."updated_at",
            "ai_pick"."name",
            "ai_pick"."type",
            "ai_pick"."description",
            "ai_pick"."target_cohort",
            "ai_pick"."geography",
            "ai_pick"."evidence_level",
            "ai_pick"."cultural_authority",
            "ai_pick"."consent_level",
            "ai_pick"."permitted_uses",
            "ai_pick"."contributors",
            "ai_pick"."source_documents",
            "ai_pick"."risks",
            "ai_pick"."harm_risk_level",
            "ai_pick"."implementation_cost",
            "ai_pick"."cost_per_young_person",
            "ai_pick"."scalability",
            "ai_pick"."replication_readiness",
            "ai_pick"."operating_organization",
            "ai_pick"."contact_person",
            "ai_pick"."contact_email",
            "ai_pick"."contact_phone",
            "ai_pick"."website",
            "ai_pick"."years_operating",
            "ai_pick"."current_funding",
            "ai_pick"."portfolio_score",
            "ai_pick"."evidence_strength_signal",
            "ai_pick"."community_authority_signal",
            "ai_pick"."harm_risk_signal",
            "ai_pick"."implementation_capability_signal",
            "ai_pick"."option_value_signal",
            "ai_pick"."review_status",
            "ai_pick"."reviewed_by",
            "ai_pick"."reviewed_at",
            "ai_pick"."linked_service_id",
            "ai_pick"."linked_community_program_id",
            "ai_pick"."search_vector",
            "ai_pick"."metadata",
            "ai_pick"."operating_organization_id",
            "ai_pick"."latitude",
            "ai_pick"."longitude",
            "ai_pick"."service_area_km",
            "ai_pick"."location_type"
           FROM "public"."alma_interventions" "ai_pick"
          WHERE (("ai_pick"."id" = "rs"."alma_intervention_id") OR ("ai_pick"."linked_community_program_id" = "rs"."id"))
          ORDER BY
                CASE
                    WHEN ("ai_pick"."id" = "rs"."alma_intervention_id") THEN 0
                    ELSE 1
                END, "ai_pick"."created_at" DESC NULLS LAST
         LIMIT 1) "ai" ON (true));


ALTER VIEW "public"."programs_catalog_v" OWNER TO "postgres";


COMMENT ON VIEW "public"."programs_catalog_v" IS 'Canonical read model for community programs used by frontend and API adapters (includes detail fields).';



