    "revoked_at" timestamp with time zone,
    CONSTRAINT "record_grants_subject_id_check" CHECK ((("length"("btrim"("subject_id")) >= 1) AND ("length"("btrim"("subject_id")) <= 200))),
    CONSTRAINT "record_grants_subject_table_check" CHECK (("subject_table" = ANY (ARRAY['public_profiles'::"text", 'organizations'::"text", 'alma_interventions'::"text", 'services'::"text", 'jr_sites'::"text"])))
);


