CREATE TABLE IF NOT EXISTS "public"."relationship_pipeline" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "entity_type" "text" NOT NULL,
    "entity_id" "text" NOT NULL,
    "entity_name" "text" NOT NULL,
    "stage" "text" DEFAULT 'cold'::"text" NOT NULL,
    "love_score" smallint DEFAULT 0 NOT NULL,
    "money_score" smallint DEFAULT 0 NOT NULL,
    "strategic_score" smallint DEFAULT 0 NOT NULL,
    "urgency_score" smallint DEFAULT 0 NOT NULL,
    "color" "text",
    "notes" "text",
    "next_action" "text",
    "next_action_date" "date",
    "last_contact_date" "date",
    "key_contact" "text",
    "value_low" numeric,
    "value_high" numeric,
    "subtitle" "text",
    "project_codes" "text"[],
    "notion_page_id" "text",
    "last_synced_to_notion" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "relationship_pipeline_entity_type_check" CHECK (("entity_type" = ANY (ARRAY['grant'::"text", 'foundation'::"text", 'business'::"text", 'person'::"text", 'opportunity'::"text"]))),
    CONSTRAINT "relationship_pipeline_love_score_check" CHECK ((("love_score" >= 0) AND ("love_score" <= 5))),
    CONSTRAINT "relationship_pipeline_money_score_check" CHECK ((("money_score" >= 0) AND ("money_score" <= 5))),
    CONSTRAINT "relationship_pipeline_stage_check" CHECK (("stage" = ANY (ARRAY['cold'::"text", 'warm'::"text", 'engaged'::"text", 'active'::"text", 'partner'::"text", 'dormant'::"text", 'lost'::"text"]))),
    CONSTRAINT "relationship_pipeline_strategic_score_check" CHECK ((("strategic_score" >= 0) AND ("strategic_score" <= 5))),
    CONSTRAINT "relationship_pipeline_urgency_score_check" CHECK ((("urgency_score" >= 0) AND ("urgency_score" <= 5)))
);


