COMMENT ON COLUMN "public"."social_enterprises"."business_model" IS 'Business model classification (e.g. Employment, Fee for Service)';



COMMENT ON COLUMN "public"."social_enterprises"."verification_tier" IS 'certified = external mark (Social Traders/Supply Nation/BuyAbility/B Corp); verified = statutory register or state-network member with ABN; identified = directory/LLM-classified. See docs/strategy/buyer-wedge.md';



CREATE OR REPLACE VIEW "public"."se_directory" AS
 SELECT "e"."id",
    "e"."name",
    "e"."abn",
    "e"."org_type",
    "e"."legal_structure",
    "e"."description",
    "e"."website",
    "e"."state",
    "e"."city",
    "e"."postcode",
    "e"."sector",
    "e"."certifications",
    "e"."source_primary",
    "e"."target_beneficiaries",
    "e"."logo_url",
    "e"."business_model",
    "e"."profile_confidence",
    "e"."enriched_at",
    "e"."created_at",
    COALESCE("si"."contract_count", 0) AS "contract_count",
    COALESCE("si"."contract_value", (0)::numeric) AS "contract_value",
    "si"."verification_tier",
    ("tp"."abn" IS NOT NULL) AS "triple_proof",
    COALESCE("tp"."has_alma_evidence_outcomes", false) AS "proven_outcomes"
   FROM (("public"."social_enterprises" "e"
     LEFT JOIN "public"."se_search_index" "si" ON (("si"."se_id" = "e"."id")))
     LEFT JOIN ( SELECT DISTINCT ON ("mv_triple_proof_suppliers"."abn") "mv_triple_proof_suppliers"."abn",
            "mv_triple_proof_suppliers"."has_alma_evidence_outcomes"
           FROM "public"."mv_triple_proof_suppliers"
          WHERE ("mv_triple_proof_suppliers"."abn" IS NOT NULL)) "tp" ON (("tp"."abn" = "e"."abn")));


ALTER VIEW "public"."se_directory" OWNER TO "postgres";


