CREATE MATERIALIZED VIEW "public"."supplier_name_keys" AS
 SELECT "supplier_name",
    "public"."entity_name_key"("supplier_name") AS "nk"
   FROM ( SELECT DISTINCT "austender_contracts"."supplier_name"
           FROM "public"."austender_contracts"
          WHERE (("austender_contracts"."supplier_name" IS NOT NULL) AND ("btrim"("austender_contracts"."supplier_name") <> ''::"text"))) "s"
  WITH NO DATA;


