CREATE MATERIALIZED VIEW "public"."supplier_key_abn" AS
 SELECT "k"."nk" AS "n",
    "min"(NULLIF("c"."supplier_abn", ''::"text")) AS "abn"
   FROM ("public"."austender_contracts" "c"
     JOIN "public"."supplier_name_keys" "k" ON (("k"."supplier_name" = "c"."supplier_name")))
  WHERE ((NULLIF("c"."supplier_abn", ''::"text") IS NOT NULL) AND ("c"."contract_start" >= "make_date"(2000, 1, 1)) AND ("c"."contract_start" < "make_date"(2031, 1, 1)))
  GROUP BY "k"."nk"
 HAVING ("count"(DISTINCT NULLIF("c"."supplier_abn", ''::"text")) = 1)
  WITH NO DATA;


