CREATE OR REPLACE VIEW "public"."v_acco_yj_retention_qld" AS
 WITH "yearly" AS (
         SELECT "j"."financial_year",
            "e"."id" AS "entity_id"
           FROM ("public"."justice_funding" "j"
             JOIN "public"."gs_entities" "e" ON (("e"."id" = "j"."gs_entity_id")))
          WHERE (("j"."state" = 'QLD'::"text") AND ("j"."topics" @> ARRAY['youth-justice'::"text"]) AND ("j"."amount_dollars" > (0)::numeric) AND ("e"."is_community_controlled" = true) AND ("j"."financial_year" ~ '^20[0-9]{2}-[0-9]{2}$'::"text"))
          GROUP BY "j"."financial_year", "e"."id"
        ), "pairs" AS (
         SELECT "a"."financial_year" AS "prior_year",
            ((((("substring"("a"."financial_year", 1, 4))::integer + 1))::"text" || '-'::"text") || "lpad"((((("substring"("a"."financial_year", 6, 2))::integer + 1) % 100))::"text", 2, '0'::"text")) AS "next_year",
            "a"."entity_id",
            ("b"."entity_id" IS NOT NULL) AS "retained"
           FROM ("yearly" "a"
             LEFT JOIN "yearly" "b" ON ((("b"."entity_id" = "a"."entity_id") AND ("b"."financial_year" = ((((("substring"("a"."financial_year", 1, 4))::integer + 1))::"text" || '-'::"text") || "lpad"((((("substring"("a"."financial_year", 6, 2))::integer + 1) % 100))::"text", 2, '0'::"text"))))))
        )
 SELECT "prior_year",
    "next_year",
    "count"(*) AS "prior_year_accos",
    "count"(*) FILTER (WHERE "retained") AS "retained_accos",
    "round"(((100.0 * ("count"(*) FILTER (WHERE "retained"))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "retention_pct"
   FROM "pairs"
  GROUP BY "prior_year", "next_year"
  ORDER BY "prior_year";


ALTER VIEW "public"."v_acco_yj_retention_qld" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_acco_yj_retention_qld" IS 'QLD youth-justice ACCO year-over-year retention. Counts community-controlled orgs that received QLD YJ funding in year N and again in N+1.';



CREATE OR REPLACE VIEW "public"."v_acnc_grant_makers" AS
 SELECT "abn",
    "charity_name",
    "ais_year",
    "charity_size",
    "total_revenue",
    "grants_donations_au",
    "grants_donations_intl",
    (COALESCE("grants_donations_au", (0)::numeric) + COALESCE("grants_donations_intl", (0)::numeric)) AS "total_grants",
        CASE
            WHEN ("total_revenue" > (0)::numeric) THEN "round"((((COALESCE("grants_donations_au", (0)::numeric) + COALESCE("grants_donations_intl", (0)::numeric)) / "total_revenue") * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS "giving_ratio_pct",
    "total_assets",
    "net_assets_liabilities",
    "staff_fte",
    "staff_volunteers",
    "charity_website"
   FROM "public"."acnc_ais"
  WHERE ((COALESCE("grants_donations_au", (0)::numeric) + COALESCE("grants_donations_intl", (0)::numeric)) > (0)::numeric)
  ORDER BY (COALESCE("grants_donations_au", (0)::numeric) + COALESCE("grants_donations_intl", (0)::numeric)) DESC;


ALTER VIEW "public"."v_acnc_grant_makers" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_acnc_latest" AS
 SELECT DISTINCT ON ("abn") "id",
