CREATE OR REPLACE VIEW "public"."v_act_expense_history" WITH ("security_invoker"='true') AS
 SELECT "id" AS "invoice_id",
    "invoice_number",
    "contact_name" AS "payee_name",
    "project_code",
    "date" AS "invoice_date",
    "due_date",
    "status",
    ("total")::numeric AS "total",
    ("amount_paid")::numeric AS "amount_paid",
    ("amount_due")::numeric AS "amount_due",
    "reference",
        CASE
            WHEN (("status" = 'AUTHORISED'::"text") AND ("date" IS NOT NULL)) THEN (EXTRACT(day FROM ("now"() - ("date")::timestamp with time zone)))::integer
            ELSE NULL::integer
        END AS "days_outstanding",
        CASE
            WHEN ("lower"("contact_name") ~ 'defy|zinus|telford|tanner|crust mech|equipment|engineering'::"text") THEN 'manufacturing'::"text"
            WHEN ("lower"("contact_name") ~ 'bunnings|kennards|tradies|hardware|nuts and bolts|reece|mitre'::"text") THEN 'supplies'::"text"
            WHEN ("lower"("contact_name") ~ 'qantas|virgin|jetstar|airbnb|hotel|accommodation|hire car|avis|hertz'::"text") THEN 'travel'::"text"
            WHEN ("lower"("contact_name") ~ 'aws|google|github|notion|figma|adobe|slack|zoom|atlassian|cloudflare|vercel|openai|anthropic|sentry|datadog|portabl'::"text") THEN 'software'::"text"
            WHEN ("lower"("contact_name") ~ 'knight photography|consultancy|consulting|photography|advisor|coaching|design studio|imaging'::"text") THEN 'people_contractors'::"text"
            WHEN ("lower"("contact_name") ~ 'oonchiumpa|orange sky|aboriginal corp|community company|elders|streetsmart|sustainable table'::"text") THEN 'partner_orgs'::"text"
            WHEN ("lower"("contact_name") ~ 'stripe|paypal|wise|bank|nab\b|commonwealth|westpac\b|anz\b|ato\b|tax office'::"text") THEN 'banking_fees'::"text"
            WHEN ("lower"("contact_name") ~ 'energy|telstra|optus|water|electricity|gas\b|storage|rent|landlord|self storage'::"text") THEN 'utilities_property'::"text"
            WHEN ("lower"("contact_name") ~ 'insurance|legal|lawyer|solicitor|accountant|bookkeep|standard ledger|asic'::"text") THEN 'compliance'::"text"
            ELSE 'other'::"text"
        END AS "payee_category"
   FROM "public"."xero_invoices" "xi"
  WHERE (("type" = 'ACCPAY'::"text") AND ("status" = ANY (ARRAY['PAID'::"text", 'AUTHORISED'::"text", 'DRAFT'::"text", 'SUBMITTED'::"text"])));


ALTER VIEW "public"."v_act_expense_history" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_act_expense_history" IS 'One row per ACCPAY invoice with payee_category derivation. Mirror of v_act_income_history for outflows.';



CREATE OR REPLACE VIEW "public"."v_act_expense_by_payee" AS
 SELECT "payee_name",
    "payee_category",
    "count"(*) FILTER (WHERE ("status" = 'PAID'::"text")) AS "paid_invoice_count",
    "count"(*) FILTER (WHERE ("status" = 'AUTHORISED'::"text")) AS "auth_invoice_count",
    "count"(*) FILTER (WHERE ("status" = 'DRAFT'::"text")) AS "draft_invoice_count",
    "round"("sum"("total") FILTER (WHERE ("status" = 'PAID'::"text")), 0) AS "paid_total",
    "round"("sum"("total") FILTER (WHERE ("status" = 'AUTHORISED'::"text")), 0) AS "auth_total",
    "round"("sum"("total") FILTER (WHERE ("status" = 'DRAFT'::"text")), 0) AS "draft_total",
    "min"("invoice_date") FILTER (WHERE ("status" = 'PAID'::"text")) AS "first_paid_date",
    "max"("invoice_date") FILTER (WHERE ("status" = 'PAID'::"text")) AS "last_paid_date",
    "array_agg"(DISTINCT "project_code" ORDER BY "project_code") FILTER (WHERE (("project_code" IS NOT NULL) AND ("project_code" <> ''::"text"))) AS "project_codes",
    "max"("days_outstanding") FILTER (WHERE ("status" = 'AUTHORISED'::"text")) AS "longest_outstanding_days"
   FROM "public"."v_act_expense_history"
  GROUP BY "payee_name", "payee_category";


ALTER VIEW "public"."v_act_expense_by_payee" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_act_expense_by_payee" IS 'Per-payee lifetime totals + category + project mix. Drives the Expense History table on /org/act.';



CREATE OR REPLACE VIEW "public"."v_act_expense_by_project" AS
 SELECT "project_code",
    "count"(*) FILTER (WHERE ("status" = 'PAID'::"text")) AS "paid_invoice_count",
    "round"("sum"("total") FILTER (WHERE ("status" = 'PAID'::"text")), 0) AS "paid_total",
    "round"("sum"("total") FILTER (WHERE ("status" = 'AUTHORISED'::"text")), 0) AS "auth_total",
    "round"("sum"("total") FILTER (WHERE ("status" = 'DRAFT'::"text")), 0) AS "draft_total",
    "count"(DISTINCT "payee_name") AS "distinct_payees",
    "min"("invoice_date") FILTER (WHERE ("status" = 'PAID'::"text")) AS "first_paid_date",
    "max"("invoice_date") FILTER (WHERE ("status" = 'PAID'::"text")) AS "last_paid_date"
   FROM "public"."v_act_expense_history"
  WHERE (("project_code" IS NOT NULL) AND ("project_code" <> ''::"text"))
  GROUP BY "project_code";


