CREATE TABLE IF NOT EXISTS "public"."xero_bank_accounts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "xero_id" "text" NOT NULL,
    "name" "text" NOT NULL,
    "code" "text",
    "type" "text" DEFAULT 'BANK'::"text",
    "bank_account_number" "text",
    "currency_code" "text" DEFAULT 'AUD'::"text",
    "status" "text" DEFAULT 'ACTIVE'::"text",
    "current_balance" numeric(12,2),
    "balance_updated_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "created_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."xero_bank_accounts" OWNER TO "postgres";


COMMENT ON TABLE "public"."xero_bank_accounts" IS 'Xero bank account metadata and balances, synced from Xero Accounts API';



COMMENT ON COLUMN "public"."xero_bank_accounts"."current_balance" IS 'Latest known balance — from Xero BankSummary report or manual entry';



CREATE OR REPLACE VIEW "public"."v_act_financial_pulse" WITH ("security_invoker"='true') AS
 WITH "cash" AS (
         SELECT "round"("sum"("xero_bank_accounts"."current_balance"), 0) AS "cash_total",
            "count"(*) AS "account_count",
            "max"("xero_bank_accounts"."balance_updated_at") AS "last_balance_sync"
           FROM "public"."xero_bank_accounts"
          WHERE (("xero_bank_accounts"."status" = 'ACTIVE'::"text") AND (("lower"("xero_bank_accounts"."name") ~~ '%act %'::"text") OR ("lower"("xero_bank_accounts"."name") ~~ '%t/as act%'::"text")) AND ("lower"("xero_bank_accounts"."name") !~~ '%personal%'::"text"))
        ), "burn_90d" AS (
         SELECT COALESCE("round"("sum"("xero_invoices"."total") FILTER (WHERE ("xero_invoices"."date" >= ("now"() - '90 days'::interval))), 0), (0)::numeric) AS "expense_90d",
            COALESCE("round"("sum"("xero_invoices"."total") FILTER (WHERE ("xero_invoices"."date" >= ("now"() - '30 days'::interval))), 0), (0)::numeric) AS "expense_30d",
            "count"(*) FILTER (WHERE ("xero_invoices"."date" >= ("now"() - '90 days'::interval))) AS "bills_90d"
           FROM "public"."xero_invoices"
          WHERE (("xero_invoices"."type" = 'ACCPAY'::"text") AND ("xero_invoices"."status" = 'PAID'::"text"))
        ), "income_30d" AS (
         SELECT COALESCE("round"("sum"("xero_invoices"."total") FILTER (WHERE ("xero_invoices"."date" >= ("now"() - '30 days'::interval))), 0), (0)::numeric) AS "income_30d",
            COALESCE("round"("sum"("xero_invoices"."total") FILTER (WHERE ("xero_invoices"."date" >= ("now"() - '90 days'::interval))), 0), (0)::numeric) AS "income_90d"
           FROM "public"."xero_invoices"
          WHERE (("xero_invoices"."type" = 'ACCREC'::"text") AND ("xero_invoices"."status" = 'PAID'::"text"))
        ), "ar_outstanding" AS (
         SELECT COALESCE("round"("sum"("xero_invoices"."total"), 0), (0)::numeric) AS "ar_total",
            "count"(*) AS "ar_count",
            COALESCE("round"("sum"("xero_invoices"."total") FILTER (WHERE ("xero_invoices"."date" < ("now"() - '60 days'::interval))), 0), (0)::numeric) AS "ar_overdue_60d",
            "count"(*) FILTER (WHERE ("xero_invoices"."date" < ("now"() - '60 days'::interval))) AS "ar_overdue_60d_count"
           FROM "public"."xero_invoices"
          WHERE (("xero_invoices"."type" = 'ACCREC'::"text") AND ("xero_invoices"."status" = 'AUTHORISED'::"text"))
        ), "ap_outstanding" AS (
         SELECT COALESCE("round"("sum"("xero_invoices"."total"), 0), (0)::numeric) AS "ap_total",
            "count"(*) AS "ap_count",
            COALESCE("round"("sum"("xero_invoices"."total") FILTER (WHERE ("xero_invoices"."date" < ("now"() - '60 days'::interval))), 0), (0)::numeric) AS "ap_overdue_60d",
            "count"(*) FILTER (WHERE ("xero_invoices"."date" < ("now"() - '60 days'::interval))) AS "ap_overdue_60d_count"
           FROM "public"."xero_invoices"
          WHERE (("xero_invoices"."type" = 'ACCPAY'::"text") AND ("xero_invoices"."status" = 'AUTHORISED'::"text"))
        )
 SELECT "c"."cash_total",
    "c"."account_count",
    "c"."last_balance_sync",
    "b"."expense_30d" AS "burn_30d",
    "b"."expense_90d" AS "burn_90d",
    "round"(("b"."expense_90d" / 3.0), 0) AS "monthly_burn_avg",
    "i"."income_30d",
    "i"."income_90d",
    "round"(("i"."income_90d" / 3.0), 0) AS "monthly_income_avg",
    ("i"."income_30d" - "b"."expense_30d") AS "net_30d",
    "round"((("i"."income_90d" - "b"."expense_90d") / 3.0), 0) AS "monthly_net_avg",
        CASE
            WHEN ("b"."expense_90d" <= (0)::numeric) THEN NULL::numeric
            ELSE "round"(("c"."cash_total" / NULLIF(("b"."expense_90d" / 3.0), (0)::numeric)), 1)
        END AS "runway_months",
    "ar"."ar_total",
    "ar"."ar_count",
    "ar"."ar_overdue_60d",
    "ar"."ar_overdue_60d_count",
    "ap"."ap_total",
    "ap"."ap_count",
    "ap"."ap_overdue_60d",
    "ap"."ap_overdue_60d_count",
    (("c"."cash_total" + "ar"."ar_total") - "ap"."ap_total") AS "working_capital",
    "now"() AS "computed_at"
   FROM "cash" "c",
    "burn_90d" "b",
    "income_30d" "i",
    "ar_outstanding" "ar",
    "ap_outstanding" "ap";


ALTER VIEW "public"."v_act_financial_pulse" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_act_financial_pulse" IS 'Single-row financial snapshot for ACT: cash, burn, runway, A/R, A/P, working capital. Drives the top-of-dashboard pulse tile.';



CREATE OR REPLACE VIEW "public"."v_act_income_history" WITH ("security_invoker"='true') AS
 SELECT "xi"."id" AS "invoice_id",
    "xi"."invoice_number",
    "xi"."contact_name" AS "funder_name",
    "xi"."project_code",
    "xi"."date" AS "invoice_date",
    "xi"."due_date",
    "xi"."status",
    ("xi"."total")::numeric AS "total",
    ("xi"."amount_paid")::numeric AS "amount_paid",
    ("xi"."amount_due")::numeric AS "amount_due",
    "xi"."currency_code",
    "xi"."reference",
        CASE
            WHEN (("xi"."status" = 'AUTHORISED'::"text") AND ("xi"."date" IS NOT NULL)) THEN (EXTRACT(day FROM ("now"() - ("xi"."date")::timestamp with time zone)))::integer
            ELSE NULL::integer
        END AS "days_outstanding",
        CASE
            WHEN ("lower"("xi"."contact_name") ~ 'aboriginal corp|aboriginal council|community company|picc|elders-in-council|julalikari|ingkerreke|mala''la|minjerribah|homeland'::"text") THEN 'community_controlled'::"text"
            WHEN ("lower"("xi"."contact_name") ~ 'department of|state of|ministry|niaa|nih |government'::"text") THEN 'government'::"text"
            WHEN ("lower"("xi"."contact_name") ~ 'foundation|trust|forum|philanth'::"text") THEN 'philanthropic'::"text"
            WHEN ("lower"("xi"."contact_name") ~ 'rotary|streetsmart|red dust|smart recovery|reinvest'::"text") THEN 'civil_society'::"text"
            WHEN ("lower"("xi"."contact_name") ~ 'pty ltd|gmbh|limited|\binc\b|\bltd\b|fitness|studio|properties|obsession|powerhouse|bigmeats|qic'::"text") THEN 'commercial'::"text"
            ELSE 'other'::"text"
        END AS "funder_category",
    "fcs"."relationship_score",
    "fcs"."foundation_id",
    "fcs"."abn" AS "funder_abn",
    "fcs"."contacts_count",
    "fcs"."most_recent_contact_at"
   FROM ("public"."xero_invoices" "xi"
     LEFT JOIN "public"."funder_context_snapshot" "fcs" ON ((("lower"("fcs"."funder_name") = "lower"("xi"."contact_name")) OR ("xi"."contact_name" = ANY (COALESCE("fcs"."funder_aliases", ARRAY[]::"text"[]))))))
  WHERE (("xi"."type" = 'ACCREC'::"text") AND ("xi"."status" = ANY (ARRAY['PAID'::"text", 'AUTHORISED'::"text", 'DRAFT'::"text", 'SUBMITTED'::"text"])));


ALTER VIEW "public"."v_act_income_history" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_act_income_history" IS 'One row per ACCREC invoice (PAID/AUTHORISED/DRAFT/SUBMITTED) joined to funder_context_snapshot + funder_category. Canonical income lens for /org/act.';



CREATE OR REPLACE VIEW "public"."v_act_income_by_funder" AS
 SELECT "funder_name",
    "funder_category",
    "relationship_score",
    "count"(*) FILTER (WHERE ("status" = 'PAID'::"text")) AS "paid_invoice_count",
    "count"(*) FILTER (WHERE ("status" = 'AUTHORISED'::"text")) AS "auth_invoice_count",
    "count"(*) FILTER (WHERE ("status" = 'DRAFT'::"text")) AS "draft_invoice_count",
    "round"("sum"("total") FILTER (WHERE ("status" = 'PAID'::"text")), 0) AS "paid_total",
    "round"("sum"("total") FILTER (WHERE ("status" = 'AUTHORISED'::"text")), 0) AS "auth_total",
    "round"("sum"("total") FILTER (WHERE ("status" = 'DRAFT'::"text")), 0) AS "draft_total",
    "min"("invoice_date") FILTER (WHERE ("status" = 'PAID'::"text")) AS "first_paid_date",
    "max"("invoice_date") FILTER (WHERE ("status" = 'PAID'::"text")) AS "last_paid_date",
    "array_agg"(DISTINCT "project_code" ORDER BY "project_code") FILTER (WHERE (("project_code" IS NOT NULL) AND ("project_code" <> ''::"text"))) AS "project_codes",
    "max"("days_outstanding") FILTER (WHERE ("status" = 'AUTHORISED'::"text")) AS "longest_outstanding_days"
   FROM "public"."v_act_income_history"
  GROUP BY "funder_name", "funder_category", "relationship_score";


ALTER VIEW "public"."v_act_income_by_funder" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_act_income_by_funder" IS 'Per-funder lifetime totals (paid/auth/draft) with project mix and outstanding days. Drives the Income History table on /org/act.';



CREATE OR REPLACE VIEW "public"."v_act_income_by_project" AS
 SELECT "project_code",
    "count"(*) FILTER (WHERE ("status" = 'PAID'::"text")) AS "paid_invoice_count",
    "round"("sum"("total") FILTER (WHERE ("status" = 'PAID'::"text")), 0) AS "paid_total",
    "round"("sum"("total") FILTER (WHERE ("status" = 'AUTHORISED'::"text")), 0) AS "auth_total",
    "round"("sum"("total") FILTER (WHERE ("status" = 'DRAFT'::"text")), 0) AS "draft_total",
    "count"(DISTINCT "funder_name") AS "distinct_funders",
    "min"("invoice_date") FILTER (WHERE ("status" = 'PAID'::"text")) AS "first_paid_date",
    "max"("invoice_date") FILTER (WHERE ("status" = 'PAID'::"text")) AS "last_paid_date"
   FROM "public"."v_act_income_history"
  WHERE (("project_code" IS NOT NULL) AND ("project_code" <> ''::"text"))
  GROUP BY "project_code";


ALTER VIEW "public"."v_act_income_by_project" OWNER TO "postgres";


