    "ce"."canonical_email" AS "person_email",
    "ce"."canonical_company" AS "act_company_text",
    "ce"."engagement_status",
    "ce"."primary_project_codes",
    "ce"."tags" AS "act_tags",
    "g"."id" AS "gs_entity_uuid",
    "g"."gs_id",
    "g"."canonical_name" AS "gs_canonical_name",
    "g"."abn",
    "g"."entity_type",
    "g"."sector",
    "g"."state",
    "g"."postcode",
    "g"."lga_name",
    "g"."remoteness",
    "g"."seifa_irsd_decile",
    "g"."is_community_controlled",
    "b"."match_method",
    "b"."confidence",
    "b"."created_at" AS "bridged_at",
    "b"."reviewed_at",
    "b"."is_active"
   FROM (("public"."civicscope_act_entity_bridge" "b"
     JOIN "public"."canonical_entities" "ce" ON ((("ce"."id" = "b"."act_source_id") AND ("b"."act_source_table" = 'canonical_entities'::"text"))))
     JOIN "public"."gs_entities" "g" ON (("g"."id" = "b"."gs_entity_id")))
