CREATE OR REPLACE VIEW "public"."v_act_payables_triage" WITH ("security_invoker"='true') AS
 SELECT "id" AS "invoice_id",
    "invoice_number",
    "contact_name" AS "payee_name",
    "project_code",
    "date" AS "invoice_date",
    "due_date",
    ("total")::numeric AS "total",
    ("amount_due")::numeric AS "amount_due",
    (EXTRACT(day FROM ("now"() - ("date")::timestamp with time zone)))::integer AS "days_old",
        CASE
            WHEN ("date" >= ("now"() - '7 days'::interval)) THEN 'this_week'::"text"
            WHEN ("date" >= ("now"() - '30 days'::interval)) THEN 'within_30d'::"text"
            WHEN ("date" >= ("now"() - '60 days'::interval)) THEN '30_to_60d'::"text"
            WHEN ("date" >= ("now"() - '90 days'::interval)) THEN '60_to_90d'::"text"
            WHEN ("date" >= ("now"() - '180 days'::interval)) THEN '90_to_180d'::"text"
            ELSE 'over_180d'::"text"
        END AS "age_bucket",
        CASE
            WHEN ("lower"("contact_name") ~ 'defy|zinus|telford|tanner|crust mech|equipment|engineering'::"text") THEN 'manufacturing'::"text"
            WHEN ("lower"("contact_name") ~ 'bunnings|kennards|tradies|hardware|nuts and bolts|reece|mitre'::"text") THEN 'supplies'::"text"
            WHEN ("lower"("contact_name") ~ 'qantas|virgin|jetstar|airbnb|hotel|accommodation|hire car|avis|hertz'::"text") THEN 'travel'::"text"
            WHEN ("lower"("contact_name") ~ 'aws|google|github|notion|figma|adobe|slack|zoom|atlassian|cloudflare|vercel|openai|anthropic|sentry|datadog|portabl'::"text") THEN 'software'::"text"
            WHEN ("lower"("contact_name") ~ 'knight photography|consultancy|consulting|photography|advisor|coaching|design studio|imaging'::"text") THEN 'people_contractors'::"text"
            WHEN ("lower"("contact_name") ~ 'oonchiumpa|orange sky|aboriginal corp|community company|elders|streetsmart|sustainable table'::"text") THEN 'partner_orgs'::"text"
            WHEN ("lower"("contact_name") ~ 'stripe|paypal|wise|bank|nab\b|commonwealth|westpac\b|anz\b|ato\b|tax office'::"text") THEN 'banking_fees'::"text"
            WHEN ("lower"("contact_name") ~ 'energy|telstra|optus|water|electricity|gas\b|storage|rent|landlord|self storage'::"text") THEN 'utilities_property'::"text"
            WHEN ("lower"("contact_name") ~ 'insurance|legal|lawyer|solicitor|accountant|bookkeep|standard ledger|asic'::"text") THEN 'compliance'::"text"
            ELSE 'other'::"text"
        END AS "payee_category",
    "reference"
   FROM "public"."xero_invoices" "xi"
  WHERE (("type" = 'ACCPAY'::"text") AND ("status" = 'AUTHORISED'::"text"));


ALTER VIEW "public"."v_act_payables_triage" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_act_payables_triage" IS 'One row per AUTHORISED ACCPAY with age bucket + category. Drives /org/[slug]/payables kanban.';



CREATE OR REPLACE VIEW "public"."v_act_people" WITH ("security_invoker"='true') AS
 WITH "xero_people" AS (
         SELECT "xero_invoices"."contact_name" AS "person_name",
            "sum"("xero_invoices"."total") FILTER (WHERE ("xero_invoices"."status" = 'PAID'::"text")) AS "paid_total",
            "count"(*) FILTER (WHERE ("xero_invoices"."status" = 'PAID'::"text")) AS "paid_invoice_count",
            "max"("xero_invoices"."date") FILTER (WHERE ("xero_invoices"."status" = 'PAID'::"text")) AS "last_paid_date",
            "array_agg"(DISTINCT "xero_invoices"."project_code" ORDER BY "xero_invoices"."project_code") FILTER (WHERE (("xero_invoices"."project_code" IS NOT NULL) AND ("xero_invoices"."project_code" <> ''::"text"))) AS "xero_project_codes"
           FROM "public"."xero_invoices"
          WHERE (("xero_invoices"."type" = 'ACCPAY'::"text") AND ("xero_invoices"."contact_name" IS NOT NULL) AND ("lower"("xero_invoices"."contact_name") !~ 'pty|ltd|limited|\binc\b|foundation|group|company|corporation|qantas|virgin|bunnings|kennards|bank|council|services|warehouse|trust|gmbh|hire|insurance|systems|hardware|fitness|studio|properties|obsession|powerhouse|bigmeats|qic|university|college|institute|department|trustee|airbnb|engineering|equipment|imaging|station|aboriginal corp|reserve|defy|zinus|washer|telford|orange sky|portabl|sunshine glamping|crust mech|telstra|optus|airtable|notion|google|cloudflare|adobe|figma|stripe|paypal'::"text"))
          GROUP BY "xero_invoices"."contact_name"
         HAVING ("sum"("xero_invoices"."total") FILTER (WHERE ("xero_invoices"."status" = 'PAID'::"text")) > (0)::numeric)
        ), "ghl_people_raw" AS (
         SELECT COALESCE("ghl_contacts"."full_name", TRIM(BOTH FROM ((COALESCE("ghl_contacts"."first_name", ''::"text") || ' '::"text") || COALESCE("ghl_contacts"."last_name", ''::"text")))) AS "person_name",
            "ghl_contacts"."email",
            "ghl_contacts"."company_name",
            "ghl_contacts"."tags",
            "ghl_contacts"."last_contact_date",
            "ghl_contacts"."first_contact_date",
            "ghl_contacts"."engagement_status",
            "ghl_contacts"."is_storyteller",
            "ghl_contacts"."is_elder"
           FROM "public"."ghl_contacts"
          WHERE ((COALESCE("ghl_contacts"."full_name", "ghl_contacts"."first_name", "ghl_contacts"."last_name") IS NOT NULL) AND ((("ghl_contacts"."tags")::"text" ~~* '%act%'::"text") OR (("ghl_contacts"."tags")::"text" ~~* '%justicehub%'::"text") OR (("ghl_contacts"."tags")::"text" ~~* '%goods%'::"text") OR (("ghl_contacts"."tags")::"text" ~~* '%harvest%'::"text") OR (("ghl_contacts"."tags")::"text" ~~* '%empathy%'::"text")))
        ), "ghl_people" AS (
         SELECT DISTINCT ON (("lower"("ghl_people_raw"."person_name"))) "ghl_people_raw"."person_name",
            "ghl_people_raw"."email",
            "ghl_people_raw"."company_name",
            "ghl_people_raw"."tags",
            "ghl_people_raw"."last_contact_date",
            "ghl_people_raw"."first_contact_date",
            "ghl_people_raw"."engagement_status",
            "ghl_people_raw"."is_storyteller",
            "ghl_people_raw"."is_elder"
           FROM "ghl_people_raw"
          WHERE (("ghl_people_raw"."person_name" IS NOT NULL) AND ("ghl_people_raw"."person_name" <> ''::"text"))
          ORDER BY ("lower"("ghl_people_raw"."person_name")), "ghl_people_raw"."last_contact_date" DESC NULLS LAST
        ), "family" AS (
         SELECT "gs_entities"."canonical_name" AS "person_name",
            "gs_entities"."gs_id"
           FROM "public"."gs_entities"
          WHERE (("gs_entities"."entity_type" = 'person'::"text") AND ("gs_entities"."canonical_name" ~* '\ymarchesi'::"text"))
        )
 SELECT COALESCE("xp"."person_name", "gp"."person_name", "f"."person_name") AS "person_name",
        CASE
            WHEN ("f"."gs_id" IS NOT NULL) THEN 'family'::"text"
            WHEN (("xp"."paid_total" > (0)::numeric) AND ("gp"."email" IS NOT NULL)) THEN 'contact'::"text"
            WHEN ("xp"."paid_total" > (0)::numeric) THEN 'contractor'::"text"
            ELSE 'network'::"text"
        END AS "person_category",
    "array_to_string"("array_remove"(ARRAY[
        CASE
            WHEN ("xp"."person_name" IS NOT NULL) THEN 'xero'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("gp"."person_name" IS NOT NULL) THEN 'ghl'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("f"."gs_id" IS NOT NULL) THEN 'gs_entity'::"text"
            ELSE NULL::"text"
        END], NULL::"text"), ','::"text") AS "sources",
    COALESCE("xp"."paid_total", (0)::numeric) AS "paid_total",
    COALESCE("xp"."paid_invoice_count", (0)::bigint) AS "paid_invoice_count",
    "xp"."last_paid_date",
    "xp"."xero_project_codes",
    "gp"."email",
    "gp"."company_name",
    "gp"."tags",
    "gp"."last_contact_date",
    "gp"."first_contact_date",
    "gp"."engagement_status",
    COALESCE("gp"."is_storyteller", false) AS "is_storyteller",
    COALESCE("gp"."is_elder", false) AS "is_elder",
    "f"."gs_id"
   FROM (("ghl_people" "gp"
     FULL JOIN "xero_people" "xp" ON (("lower"("xp"."person_name") = "lower"("gp"."person_name"))))
     FULL JOIN "family" "f" ON (("lower"("f"."person_name") = "lower"(COALESCE("xp"."person_name", "gp"."person_name")))))
  WHERE (COALESCE("xp"."person_name", "gp"."person_name", "f"."person_name") IS NOT NULL);


ALTER VIEW "public"."v_act_people" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_act_people" IS 'One row per ACT-adjacent person from Xero ACCPAY (contractors), GHL (network), gs_entities (Marchesi family). Drives the People section on /org/act.';



CREATE OR REPLACE VIEW "public"."v_act_pipeline_unified" WITH ("security_invoker"='true') AS
 SELECT "op"."id" AS "pipeline_id",
    "op"."project_code",
    "op"."name" AS "opportunity_name",
    "op"."funder",
    "op"."amount_display",
    "op"."amount_numeric",
    "op"."deadline",
    "op"."status" AS "pipeline_status",
    "op"."opportunity_type",
    "op"."qbe_stage",
    "op"."qbe_outcome",
    "op"."qbe_bid_amount",
    "op"."pathway",
    "op"."recommended_role",
    "agr"."fit_score",
    "agr"."is_strong_fit",
    "agr"."flags" AS "recommendation_flags",
    "agrd"."decision" AS "last_decision",
    "agrd"."decided_at",
    "agrd"."notes" AS "decision_notes",
    "arp"."project_label",
    "arp"."layer" AS "project_layer",
    "arp"."readiness" AS "project_readiness",
    "arp"."dgr_required" AS "project_dgr_required",
    "arp"."entity_preference" AS "project_entity_preference",
    "op"."created_at",
    "op"."updated_at"
   FROM ((("public"."org_pipeline" "op"
     LEFT JOIN "public"."act_grant_recommendation_projects" "arp" ON (("arp"."project_code" = "op"."project_code")))
     LEFT JOIN "public"."act_grant_recommendations" "agr" ON ((("agr"."project_code" = "op"."project_code") AND ("agr"."opportunity_id" = "op"."grant_opportunity_id"))))
     LEFT JOIN LATERAL ( SELECT "act_grant_recommendation_decisions"."decision",
            "act_grant_recommendation_decisions"."decided_at",
            "act_grant_recommendation_decisions"."notes"
           FROM "public"."act_grant_recommendation_decisions"
          WHERE (("act_grant_recommendation_decisions"."project_code" = "op"."project_code") AND ("act_grant_recommendation_decisions"."opportunity_id" = "op"."grant_opportunity_id"))
          ORDER BY "act_grant_recommendation_decisions"."decided_at" DESC
         LIMIT 1) "agrd" ON (true));


ALTER VIEW "public"."v_act_pipeline_unified" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_act_procurement_buyers" AS
 WITH "relevant_contracts" AS (
         SELECT "austender_contracts"."buyer_name",
            "austender_contracts"."contract_value",
            "austender_contracts"."title",
            "austender_contracts"."description",
            "austender_contracts"."contract_start",
            "austender_contracts"."contract_end",
            "austender_contracts"."date_published",
            "austender_contracts"."category",
            "austender_contracts"."procurement_method",
            ((((((
                CASE
                    WHEN ("lower"((("austender_contracts"."title" || ' '::"text") || COALESCE("austender_contracts"."description", ''::"text"))) ~ '\m(data|analytics|dashboard|intelligence|reporting)\M'::"text") THEN 1
                    ELSE 0
                END +
                CASE
                    WHEN ("lower"((("austender_contracts"."title" || ' '::"text") || COALESCE("austender_contracts"."description", ''::"text"))) ~ '\m(evaluation|impact assessment|monitoring|measurement)\M'::"text") THEN 1
                    ELSE 0
                END) +
                CASE
                    WHEN ("lower"((("austender_contracts"."title" || ' '::"text") || COALESCE("austender_contracts"."description", ''::"text"))) ~ '\m(research|evidence|study|review|scoping)\M'::"text") THEN 1
                    ELSE 0
                END) +
                CASE
                    WHEN ("lower"((("austender_contracts"."title" || ' '::"text") || COALESCE("austender_contracts"."description", ''::"text"))) ~ '\m(mapping|gis|spatial|geo)\M'::"text") THEN 1
                    ELSE 0
                END) +
                CASE
                    WHEN ("lower"((("austender_contracts"."title" || ' '::"text") || COALESCE("austender_contracts"."description", ''::"text"))) ~ '\m(consultation|engagement|community-led|co-design)\M'::"text") THEN 1
                    ELSE 0
                END) +
                CASE
                    WHEN ("lower"((("austender_contracts"."title" || ' '::"text") || COALESCE("austender_contracts"."description", ''::"text"))) ~ '\m(storytelling|narrative|communications|content)\M'::"text") THEN 1
                    ELSE 0
                END) +
                CASE
                    WHEN ("lower"((("austender_contracts"."title" || ' '::"text") || COALESCE("austender_contracts"."description", ''::"text"))) ~ '\m(indigenous|first nations|aboriginal|torres strait)\M'::"text") THEN 1
                    ELSE 0
                END) AS "topic_score"
           FROM "public"."austender_contracts"
          WHERE (("austender_contracts"."buyer_name" IS NOT NULL) AND ("austender_contracts"."contract_value" >= (25000)::numeric) AND ("austender_contracts"."date_published" >= (CURRENT_DATE - '3 years'::interval)) AND ("lower"((("austender_contracts"."title" || ' '::"text") || COALESCE("austender_contracts"."description", ''::"text"))) ~ '\m(data|analytics|dashboard|intelligence|reporting|evaluation|impact assessment|monitoring|measurement|research|evidence|study|review|scoping|mapping|gis|spatial|geo|consultation|engagement|community-led|co-design|storytelling|narrative|communications|content|indigenous|first nations|aboriginal|torres strait)\M'::"text"))
        )
 SELECT "buyer_name",
    "count"(*) AS "contract_count",
    ("sum"("contract_value"))::numeric(14,2) AS "total_relevant_spend",
    ("avg"("contract_value"))::numeric(14,2) AS "avg_contract_value",
    ("max"("contract_value"))::numeric(14,2) AS "max_contract_value",
    ("min"("contract_value"))::numeric(14,2) AS "min_contract_value",
    "max"("date_published") AS "most_recent_contract",
    "count"(*) FILTER (WHERE ("date_published" >= (CURRENT_DATE - '1 year'::interval))) AS "contracts_last_year",
    "count"(*) FILTER (WHERE ("date_published" >= (CURRENT_DATE - '6 mons'::interval))) AS "contracts_last_6mo",
    ("avg"("topic_score"))::numeric(4,2) AS "avg_topic_score",
    ( SELECT "string_agg"("sub"."cat", ' · '::"text" ORDER BY "sub"."n" DESC) AS "string_agg"
           FROM ( SELECT "rc2"."category" AS "cat",
                    "count"(*) AS "n"
                   FROM "relevant_contracts" "rc2"
                  WHERE (("rc2"."buyer_name" = "rc"."buyer_name") AND ("rc2"."category" IS NOT NULL))
                  GROUP BY "rc2"."category"
                  ORDER BY ("count"(*)) DESC
                 LIMIT 3) "sub") AS "top_categories",
    ( SELECT "array_agg"("sub"."title" ORDER BY "sub"."date_published" DESC) AS "array_agg"
           FROM ( SELECT "rc3"."title",
                    "rc3"."date_published"
                   FROM "relevant_contracts" "rc3"
                  WHERE ("rc3"."buyer_name" = "rc"."buyer_name")
                  ORDER BY "rc3"."date_published" DESC
                 LIMIT 3) "sub") AS "recent_contract_titles"
   FROM "relevant_contracts" "rc"
  GROUP BY "buyer_name"
 HAVING ("count"(*) >= 2)
  ORDER BY ("sum"("contract_value")) DESC;


ALTER VIEW "public"."v_act_procurement_buyers" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_act_procurement_buyers" IS 'Government buyers who procure ACT-deliverable work (data/intelligence/evaluation/evidence/etc.) — scored from austender_contracts last 3 years, >$25K, 2+ contracts.';



CREATE OR REPLACE VIEW "public"."v_activity_stream" WITH ("security_invoker"='true') AS
 SELECT 'transaction'::"text" AS "activity_type",
    ("xero_transactions"."id")::"text" AS "source_id",
    "xero_transactions"."project_code",
    ("xero_transactions"."date")::timestamp with time zone AS "activity_date",
        CASE "xero_transactions"."type"
            WHEN 'RECEIVE'::"text" THEN ('Received from '::"text" || COALESCE("xero_transactions"."contact_name", 'Unknown'::"text"))
            WHEN 'SPEND'::"text" THEN ('Payment to '::"text" || COALESCE("xero_transactions"."contact_name", 'Unknown'::"text"))
            ELSE 'Transfer'::"text"
        END AS "title",
    ('$'::"text" || ("abs"("xero_transactions"."total"))::"text") AS "description",
    "xero_transactions"."total" AS "amount"
   FROM "public"."xero_transactions"
  WHERE ("xero_transactions"."date" >= (CURRENT_DATE - '90 days'::interval))
UNION ALL
 SELECT 'email'::"text" AS "activity_type",
    ("communications_history"."id")::"text" AS "source_id",
        CASE
            WHEN (("communications_history"."project_codes" IS NOT NULL) AND ("array_length"("communications_history"."project_codes", 1) > 0)) THEN "communications_history"."project_codes"[1]
            ELSE NULL::"text"
        END AS "project_code",
    "communications_history"."occurred_at" AS "activity_date",
    COALESCE("communications_history"."subject", 'Email'::"text") AS "title",
    "left"(COALESCE("communications_history"."content_preview", ''::"text"), 120) AS "description",
    NULL::numeric AS "amount"
   FROM "public"."communications_history"
  WHERE ("communications_history"."occurred_at" >= (CURRENT_DATE - '90 days'::interval))
UNION ALL
 SELECT 'opportunity'::"text" AS "activity_type",
    ("ghl_opportunities"."id")::"text" AS "source_id",
    "ghl_opportunities"."project_code",
    COALESCE("ghl_opportunities"."ghl_updated_at", "ghl_opportunities"."updated_at") AS "activity_date",
    "ghl_opportunities"."name" AS "title",
    ((((("ghl_opportunities"."status" || ' — '::"text") || COALESCE("ghl_opportunities"."stage_name", ''::"text")) || ' ($'::"text") || (COALESCE("ghl_opportunities"."monetary_value", (0)::numeric))::"text") || ')'::"text") AS "description",
    "ghl_opportunities"."monetary_value" AS "amount"
   FROM "public"."ghl_opportunities"
  WHERE (COALESCE("ghl_opportunities"."ghl_updated_at", "ghl_opportunities"."updated_at") >= (CURRENT_DATE - '90 days'::interval))
UNION ALL
 SELECT 'meeting'::"text" AS "activity_type",
    ("project_knowledge"."id")::"text" AS "source_id",
    "project_knowledge"."project_code",
    COALESCE("project_knowledge"."recorded_at", "project_knowledge"."created_at") AS "activity_date",
    "project_knowledge"."title",
    "left"(COALESCE("project_knowledge"."summary", ''::"text"), 120) AS "description",
    NULL::numeric AS "amount"
   FROM "public"."project_knowledge"
  WHERE (("project_knowledge"."knowledge_type" = 'meeting'::"text") AND (COALESCE("project_knowledge"."recorded_at", "project_knowledge"."created_at") >= (CURRENT_DATE - '90 days'::interval)))
  ORDER BY 4 DESC;


ALTER VIEW "public"."v_activity_stream" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_activity_stream" IS 'Interleaved activity stream across all domains';



CREATE OR REPLACE VIEW "public"."v_agent_activity_summary" WITH ("security_invoker"='true') AS
 SELECT "agent_id",
    "action",
    "count"(*) AS "action_count",
    "sum"(
        CASE
            WHEN "success" THEN 1
            ELSE 0
        END) AS "success_count",
    "sum"(
        CASE
            WHEN (NOT "success") THEN 1
            ELSE 0
        END) AS "error_count",
    ("avg"("duration_ms"))::integer AS "avg_duration_ms",
    "max"("timestamp") AS "last_run"
   FROM "public"."agent_audit_log"
  WHERE ("timestamp" > ("now"() - '7 days'::interval))
  GROUP BY "agent_id", "action"
  ORDER BY "agent_id", ("count"(*)) DESC;


ALTER VIEW "public"."v_agent_activity_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_agent_runtime_sweeps" WITH ("security_invoker"='true') AS
 SELECT "ars"."agent_id",
    COALESCE("ar"."agent_name", "ars"."agent_id") AS "agent_name",
    (NULLIF(("ars"."state" ->> 'fullSweepCursor'::"text"), ''::"text"))::integer AS "full_sweep_cursor",
    (NULLIF(("ars"."state" ->> 'fullSweepCandidateCount'::"text"), ''::"text"))::integer AS "full_sweep_candidate_count",
        CASE
            WHEN ((NULLIF(("ars"."state" ->> 'fullSweepCandidateCount'::"text"), ''::"text"))::numeric > (0)::numeric) THEN "round"((((NULLIF(("ars"."state" ->> 'fullSweepCursor'::"text"), ''::"text"))::numeric / (NULLIF(("ars"."state" ->> 'fullSweepCandidateCount'::"text"), ''::"text"))::numeric) * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS "full_sweep_progress_pct",
    (NULLIF(("ars"."state" ->> 'fullSweepAdvancedBy'::"text"), ''::"text"))::integer AS "full_sweep_advanced_by",
    (NULLIF(("ars"."state" ->> 'fullSweepLastProgramsFound'::"text"), ''::"text"))::integer AS "full_sweep_last_programs_found",
    (NULLIF(("ars"."state" ->> 'fullSweepLastInserted'::"text"), ''::"text"))::integer AS "full_sweep_last_inserted",
    (NULLIF(("ars"."state" ->> 'fullSweepLastUpdated'::"text"), ''::"text"))::integer AS "full_sweep_last_updated",
    (NULLIF(("ars"."state" ->> 'fullSweepLastSkipped'::"text"), ''::"text"))::integer AS "full_sweep_last_skipped",
    (NULLIF(("ars"."state" ->> 'fullSweepLastErrors'::"text"), ''::"text"))::integer AS "full_sweep_last_errors",
    COALESCE(("ars"."state" -> 'fullSweepLastBatchFoundationIds'::"text"), '[]'::"jsonb") AS "full_sweep_last_batch_foundation_ids",
    COALESCE(("ars"."state" -> 'fullSweepLastBatchFoundationNames'::"text"), '[]'::"jsonb") AS "full_sweep_last_batch_foundation_names",
    (NULLIF(("ars"."state" ->> 'fullSweepLastRunAt'::"text"), ''::"text"))::timestamp with time zone AS "full_sweep_last_run_at",
    "s"."interval_hours",
    "s"."enabled",
    "s"."auto_create_task",
    "s"."last_run_at" AS "schedule_last_run_at",
    "ar"."status" AS "recent_run_status",
    "ar"."completed_at" AS "recent_run_completed_at",
    "ars"."updated_at"
   FROM (("public"."agent_runtime_state" "ars"
     LEFT JOIN "public"."agent_schedules" "s" ON (("s"."agent_id" = "ars"."agent_id")))
     LEFT JOIN LATERAL ( SELECT "agent_runs"."agent_name",
            "agent_runs"."status",
            "agent_runs"."completed_at"
           FROM "public"."agent_runs"
          WHERE ("agent_runs"."agent_id" = "ars"."agent_id")
          ORDER BY "agent_runs"."started_at" DESC
         LIMIT 1) "ar" ON (true))
  WHERE (("ars"."state" ? 'fullSweepCursor'::"text") OR ("ars"."state" ? 'fullSweepCandidateCount'::"text"));


ALTER VIEW "public"."v_agent_runtime_sweeps" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_agentic_funding_queue" WITH ("security_invoker"='true') AS
 SELECT "afo"."id" AS "opportunity_id",
    "afo"."name" AS "opportunity_name",
    "afo"."funder_name",
    "afo"."source_type",
    "afo"."deadline",
    "afo"."status",
    "afo"."relevance_score",
    "count"("fmr"."id") FILTER (WHERE ("fmr"."match_score" >= (70)::numeric)) AS "strong_match_count",
    "max"("fmr"."match_score") AS "best_match_score",
    "count"("faw"."id") AS "linked_award_count"
   FROM (("public"."alma_funding_opportunities" "afo"
     LEFT JOIN "public"."funding_match_recommendations" "fmr" ON (("fmr"."opportunity_id" = "afo"."id")))
     LEFT JOIN "public"."funding_awards" "faw" ON (("faw"."opportunity_id" = "afo"."id")))
  WHERE ("afo"."status" = ANY (ARRAY['open'::"text", 'closing_soon'::"text", 'upcoming'::"text"]))
  GROUP BY "afo"."id", "afo"."name", "afo"."funder_name", "afo"."source_type", "afo"."deadline", "afo"."status", "afo"."relevance_score";


ALTER VIEW "public"."v_agentic_funding_queue" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_agentic_funding_queue" IS 'Operational queue for agents to prioritize open opportunities with high-fit community matches.';



CREATE OR REPLACE VIEW "public"."v_alma_current_impact" AS
 SELECT "metric_type",
    "sum"("value") AS "total_value",
    "sum"("delta") AS "total_delta",
    "max"("period_end") AS "latest_period"
   FROM "public"."alma_impact_metrics"
  WHERE ("period_end" >= (CURRENT_DATE - '90 days'::interval))
  GROUP BY "metric_type";


ALTER VIEW "public"."v_alma_current_impact" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_announced_money_by_kind" AS
 SELECT "financial_year",
        CASE
            WHEN ("program_name" ~* '\mtotal\M.*\mbudget\M|\mbudget\M.*\mtotal\M|^program [0-9]|total allocation|administered budget'::"text") THEN 'budget_total'::"text"
            WHEN (("program_name" ~* 'cherry creek|banksia hill|unit 18|casuarina|woodford|wacol|don dale|ashley|cobham|bimberi|kurlana tapa|cleveland|west kimberley|malmsbury|parkville|frank baxter|holtze|alice springs youth detention'::"text") OR ("program_name" ~* 'detention centre|detention center|remand centre|youth justice centre|detention facility'::"text") OR ("program_name" ~* '\m(construct|construction|redevelop|redevelopment|refurbish|remediation|replacement|upgrade|precinct|expansion)\M'::"text")) THEN 'detention_facility'::"text"
            WHEN ("program_name" ~* '^(youth justice services|community youth justice|youth justice)$'::"text") THEN 'service_line'::"text"
            ELSE 'program'::"text"
        END AS "kind",
    "count"(*) AS "announcements",
    "count"(DISTINCT "program_name") AS "distinct_names",
    "count"(DISTINCT "state") AS "states",
    "sum"("amount_dollars") AS "annual_dollars"
   FROM "public"."justice_funding"
  WHERE ("measure_kind" = 'budget_announcement'::"text")
  GROUP BY "financial_year",
        CASE
            WHEN ("program_name" ~* '\mtotal\M.*\mbudget\M|\mbudget\M.*\mtotal\M|^program [0-9]|total allocation|administered budget'::"text") THEN 'budget_total'::"text"
            WHEN (("program_name" ~* 'cherry creek|banksia hill|unit 18|casuarina|woodford|wacol|don dale|ashley|cobham|bimberi|kurlana tapa|cleveland|west kimberley|malmsbury|parkville|frank baxter|holtze|alice springs youth detention'::"text") OR ("program_name" ~* 'detention centre|detention center|remand centre|youth justice centre|detention facility'::"text") OR ("program_name" ~* '\m(construct|construction|redevelop|redevelopment|refurbish|remediation|replacement|upgrade|precinct|expansion)\M'::"text")) THEN 'detention_facility'::"text"
            WHEN ("program_name" ~* '^(youth justice services|community youth justice|youth justice)$'::"text") THEN 'service_line'::"text"
            ELSE 'program'::"text"
        END;


ALTER VIEW "public"."v_announced_money_by_kind" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_announced_money_by_kind" IS 'Announced youth justice money split by what it buys, ALWAYS within a financial year. Mixing years is a measure error: 2024-25 covers 8 jurisdictions and 2025-26 only 2, so a cross-year total silently reweights toward whichever jurisdictions happened to report.';



CREATE MATERIALIZED VIEW "public"."v_ato_largest_entities" AS
 SELECT "entity_name",
    "total_income",
    "taxable_income",
    "tax_payable",
    "report_year",
        CASE
            WHEN ("total_income" > (0)::numeric) THEN "round"((("tax_payable" / "total_income") * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "effective_rate"
   FROM "public"."ato_tax_transparency"
  WHERE (("report_year" = '2022-23'::"text") AND ("total_income" > (1000000000)::numeric))
  ORDER BY "total_income" DESC
 LIMIT 30
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."v_ato_largest_entities" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."v_austender_entity_summary" AS
 SELECT
        CASE
            WHEN ("c"."abn" IS NOT NULL) THEN 'Charity'::"text"
            WHEN ("o"."abn" IS NOT NULL) THEN 'Indigenous Corp'::"text"
            ELSE 'Corporate/Other'::"text"
        END AS "entity_type",
    "count"(*) AS "contracts",
    "round"("sum"("a"."contract_value")) AS "total_value"
   FROM (("public"."austender_contracts" "a"
     LEFT JOIN "public"."acnc_charities" "c" ON (("a"."supplier_abn" = "c"."abn")))
     LEFT JOIN "public"."oric_corporations" "o" ON (("a"."supplier_abn" = "o"."abn")))
  WHERE (("a"."supplier_abn" IS NOT NULL) AND ("a"."contract_value" IS NOT NULL))
  GROUP BY
        CASE
            WHEN ("c"."abn" IS NOT NULL) THEN 'Charity'::"text"
            WHEN ("o"."abn" IS NOT NULL) THEN 'Indigenous Corp'::"text"
            ELSE 'Corporate/Other'::"text"
        END
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."v_austender_entity_summary" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."v_austender_procurement_by_type" AS
 SELECT
        CASE
            WHEN ("c"."abn" IS NOT NULL) THEN 'Charity'::"text"
            WHEN ("o"."abn" IS NOT NULL) THEN 'Indigenous Corp'::"text"
            ELSE 'Corporate/Other'::"text"
        END AS "entity_type",
    "a"."procurement_method",
    "count"(*) AS "contracts",
    "round"("sum"("a"."contract_value")) AS "total_value"
   FROM (("public"."austender_contracts" "a"
     LEFT JOIN "public"."acnc_charities" "c" ON (("a"."supplier_abn" = "c"."abn")))
     LEFT JOIN "public"."oric_corporations" "o" ON (("a"."supplier_abn" = "o"."abn")))
  WHERE (("a"."supplier_abn" IS NOT NULL) AND ("a"."contract_value" IS NOT NULL))
  GROUP BY
        CASE
            WHEN ("c"."abn" IS NOT NULL) THEN 'Charity'::"text"
            WHEN ("o"."abn" IS NOT NULL) THEN 'Indigenous Corp'::"text"
            ELSE 'Corporate/Other'::"text"
        END, "a"."procurement_method"
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."v_austender_procurement_by_type" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."v_austender_stats" AS
 SELECT "count"(*) AS "total_contracts",
    "round"("sum"("contract_value")) AS "total_value",
    "count"(DISTINCT "supplier_abn") AS "unique_suppliers",
    "count"(*) FILTER (WHERE ("supplier_abn" IS NOT NULL)) AS "contracts_with_abn"
   FROM "public"."austender_contracts"
  WHERE ("contract_value" IS NOT NULL)
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."v_austender_stats" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."v_austender_supplier_tax" AS
 WITH "top_suppliers" AS (
         SELECT "austender_contracts"."supplier_name",
            "austender_contracts"."supplier_abn",
            "count"(*) AS "contracts",
            "round"("sum"("austender_contracts"."contract_value")) AS "govt_value"
           FROM "public"."austender_contracts"
          WHERE (("austender_contracts"."contract_value" IS NOT NULL) AND ("austender_contracts"."supplier_abn" IS NOT NULL))
          GROUP BY "austender_contracts"."supplier_name", "austender_contracts"."supplier_abn"
          ORDER BY ("round"("sum"("austender_contracts"."contract_value"))) DESC
         LIMIT 50
        )
 SELECT "ts"."supplier_name",
    "ts"."supplier_abn",
    "ts"."contracts",
    "ts"."govt_value",
    "ato"."entity_name",
    "ato"."total_income",
    "ato"."taxable_income",
    "ato"."tax_payable",
    "ato"."report_year",
        CASE
            WHEN ("ato"."total_income" > (0)::numeric) THEN "round"((("ato"."tax_payable" / "ato"."total_income") * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "effective_rate"
   FROM ("top_suppliers" "ts"
     JOIN "public"."ato_tax_transparency" "ato" ON (("ts"."supplier_abn" = "ato"."abn")))
  WHERE ("ato"."report_year" = ANY (ARRAY['2022-23'::"text", '2023-24'::"text"]))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."v_austender_supplier_tax" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."v_austender_top_charities" AS
 SELECT "c"."name",
    "c"."abn",
    "count"("a"."id") AS "contracts",
    "round"("sum"("a"."contract_value")) AS "total_value"
   FROM ("public"."austender_contracts" "a"
     JOIN "public"."acnc_charities" "c" ON (("a"."supplier_abn" = "c"."abn")))
  WHERE (("a"."supplier_abn" IS NOT NULL) AND ("a"."contract_value" IS NOT NULL))
  GROUP BY "c"."name", "c"."abn"
  ORDER BY ("round"("sum"("a"."contract_value"))) DESC
 LIMIT 25
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."v_austender_top_charities" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."v_austender_top_oric" AS
 SELECT "o"."name",
    "o"."abn",
    "o"."state",
    "count"("a"."id") AS "contracts",
    "round"("sum"("a"."contract_value")) AS "total_value"
   FROM ("public"."austender_contracts" "a"
     JOIN "public"."oric_corporations" "o" ON (("a"."supplier_abn" = "o"."abn")))
  WHERE (("a"."supplier_abn" IS NOT NULL) AND ("o"."abn" IS NOT NULL) AND ("a"."contract_value" IS NOT NULL))
  GROUP BY "o"."name", "o"."abn", "o"."state"
  ORDER BY ("round"("sum"("a"."contract_value"))) DESC
 LIMIT 25
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."v_austender_top_oric" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_awaiting_response" WITH ("security_invoker"='true') AS
 SELECT "ch"."id",
    "ch"."ghl_contact_id",
    "ch"."channel",
    "ch"."direction",
    "ch"."from_identity",
    "ch"."to_identities",
    "ch"."subject",
    "ch"."content_preview",
    "ch"."full_content_ref",
    "ch"."summary",
    "ch"."sentiment",
    "ch"."topics",
    "ch"."action_items",
    "ch"."key_decisions",
    "ch"."waiting_for_response",
    "ch"."response_needed_by",
    "ch"."follow_up_date",
    "ch"."source_system",
    "ch"."source_id",
    "ch"."source_thread_id",
    "ch"."parent_id",
