CREATE OR REPLACE VIEW "public"."v_bgfit_grant_health" WITH ("security_invoker"='true') AS
 SELECT "g"."id",
    "g"."organization_id",
    "g"."grant_name",
    "g"."funder_name",
    "g"."approved_amount",
    "g"."received_amount",
    COALESCE("ts"."total_spent", (0)::numeric) AS "total_spent",
    ("g"."approved_amount" - COALESCE("ts"."total_spent", (0)::numeric)) AS "remaining_budget",
    ("g"."received_amount" - COALESCE("ts"."total_spent", (0)::numeric)) AS "cash_remaining",
    COALESCE("bi_agg"."issues_count", (0)::bigint) AS "issues_count",
    COALESCE("bi_agg"."items_not_purchased", (0)::bigint) AS "items_not_purchased",
    "g"."status",
    "g"."acquittal_due",
    ("g"."acquittal_due" - CURRENT_DATE) AS "days_until_acquittal"
   FROM (("public"."bgfit_grants" "g"
     LEFT JOIN ( SELECT "bgfit_transactions"."grant_id",
            "sum"("bgfit_transactions"."amount") AS "total_spent"
           FROM "public"."bgfit_transactions"
          WHERE ("bgfit_transactions"."transaction_type" = 'expense'::"text")
          GROUP BY "bgfit_transactions"."grant_id") "ts" ON (("ts"."grant_id" = "g"."id")))
     LEFT JOIN ( SELECT "bgfit_budget_items"."grant_id",
            "count"(*) FILTER (WHERE "bgfit_budget_items"."has_issue") AS "issues_count",
            "count"(*) FILTER (WHERE ("bgfit_budget_items"."status" = 'not_spent'::"text")) AS "items_not_purchased"
           FROM "public"."bgfit_budget_items"
          GROUP BY "bgfit_budget_items"."grant_id") "bi_agg" ON (("bi_agg"."grant_id" = "g"."id")));


ALTER VIEW "public"."v_bgfit_grant_health" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_bgfit_pnl" WITH ("security_invoker"='true') AS
 SELECT ("date_trunc"('month'::"text", ("transaction_date")::timestamp with time zone))::"date" AS "month",
    COALESCE("sum"("amount") FILTER (WHERE ("transaction_type" = 'income'::"text")), (0)::numeric) AS "income",
    COALESCE("sum"("amount") FILTER (WHERE ("transaction_type" = 'expense'::"text")), (0)::numeric) AS "expenses",
    (COALESCE("sum"("amount") FILTER (WHERE ("transaction_type" = 'income'::"text")), (0)::numeric) - COALESCE("sum"("amount") FILTER (WHERE ("transaction_type" = 'expense'::"text")), (0)::numeric)) AS "net",
    COALESCE("sum"("gst_amount"), (0)::numeric) AS "gst_total",
    "count"(*) AS "transaction_count"
   FROM "public"."bgfit_transactions" "t"
  GROUP BY ("date_trunc"('month'::"text", ("transaction_date")::timestamp with time zone))
  ORDER BY (("date_trunc"('month'::"text", ("transaction_date")::timestamp with time zone))::"date") DESC;


ALTER VIEW "public"."v_bgfit_pnl" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_bgfit_upcoming_deadlines" WITH ("security_invoker"='true') AS
 SELECT "d"."id",
    "d"."grant_id",
    "d"."deadline_type",
    "d"."title",
    "d"."due_date",
    "d"."status",
    "d"."submitted_date",
    "d"."requirements",
    "d"."document_url",
    "d"."reminder_days_before",
    "d"."created_at",
    "g"."grant_name",
    "g"."funder_name",
    ("d"."due_date" - CURRENT_DATE) AS "days_until_due",
        CASE
            WHEN ("d"."status" = 'complete'::"text") THEN 'done'::"text"
            WHEN (("d"."due_date" < CURRENT_DATE) AND ("d"."status" <> 'submitted'::"text")) THEN 'overdue'::"text"
            WHEN (("d"."due_date" - CURRENT_DATE) <= 7) THEN 'urgent'::"text"
            WHEN (("d"."due_date" - CURRENT_DATE) <= 30) THEN 'soon'::"text"
            ELSE 'upcoming'::"text"
        END AS "urgency"
   FROM ("public"."bgfit_deadlines" "d"
     LEFT JOIN "public"."bgfit_grants" "g" ON (("g"."id" = "d"."grant_id")))
  ORDER BY "d"."due_date";


ALTER VIEW "public"."v_bgfit_upcoming_deadlines" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_calendar_events_with_projects" WITH ("security_invoker"='true') AS
 SELECT "id",
