CREATE OR REPLACE VIEW "public"."v_catalog_objects" AS
 SELECT "c"."relname" AS "object_name",
    ("c"."relkind")::"text" AS "kind",
    "n"."nspname" AS "schema_name",
    COALESCE("s"."scope", 'unclassified'::"text") AS "scope",
    "s"."reason",
    "s"."decided_by",
    "s"."decided_at",
    (COALESCE("s"."scope", 'unclassified'::"text") = ANY (ARRAY['civic'::"text", 'unclassified'::"text"])) AS "show_by_default",
    ("s"."object_name" IS NULL) AS "needs_triage",
    ("c"."reltuples")::bigint AS "approx_rows",
    "pg_total_relation_size"(("c"."oid")::"regclass") AS "total_bytes"
   FROM (("pg_class" "c"
     JOIN "pg_namespace" "n" ON (("n"."oid" = "c"."relnamespace")))
     LEFT JOIN "public"."catalog_object_scope" "s" ON (("s"."object_name" = "c"."relname")))
  WHERE (("n"."nspname" = 'public'::"name") AND ("c"."relkind" = ANY (ARRAY['r'::"char", 'm'::"char", 'v'::"char"])));


ALTER VIEW "public"."v_catalog_objects" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_catalog_objects" IS 'Every public relation with its civic/ACT scope. show_by_default is the /clarity filter. needs_triage lists relations nobody has classified yet.';



