    (COALESCE("a"."grants_donations_au", (0)::numeric) + COALESCE("a"."grants_donations_intl", (0)::numeric)) AS "total_grants_given",
    "a"."ais_year" AS "latest_financial_year",
    ("co"."id" IS NOT NULL) AS "has_enrichment"
   FROM (("public"."acnc_charities" "c"
     LEFT JOIN "public"."mv_acnc_latest" "a" ON (("c"."abn" = "a"."abn")))
     LEFT JOIN "public"."community_orgs" "co" ON (("c"."abn" = "co"."acnc_abn")));


ALTER VIEW "public"."v_charity_explorer" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_charity_explorer" IS 'Charity explorer view joining register identity data with latest AIS financials.';



CREATE OR REPLACE VIEW "public"."v_claim_evidence_summary" AS
 SELECT "c"."claim_id",
    "c"."display_label",
    "c"."chapter",
    "c"."region",
    "count"("e"."id") FILTER (WHERE ("e"."supports" = true)) AS "supporting_sources",
    "count"("e"."id") FILTER (WHERE ("e"."supports" = false)) AS "contradicting_sources",
    "count"("e"."id") FILTER (WHERE ("e"."reviewer_status" = 'verified'::"text")) AS "verified_sources",
    "round"("avg"("e"."confidence") FILTER (WHERE ("e"."supports" = true)), 3) AS "avg_confidence",
    "count"("e"."id") AS "total_evidence_rows",
        CASE
            WHEN ("count"("e"."id") FILTER (WHERE ("e"."supports" = true)) >= 3) THEN 'triangulated'::"text"
            WHEN ("count"("e"."id") FILTER (WHERE ("e"."supports" = true)) = 2) THEN 'corroborated'::"text"
            WHEN ("count"("e"."id") FILTER (WHERE ("e"."supports" = true)) = 1) THEN 'single_source'::"text"
            ELSE 'no_evidence'::"text"
        END AS "triangulation_tier"
   FROM ("public"."civic_intelligence_claims" "c"
     LEFT JOIN "public"."civic_claim_evidence" "e" ON (("e"."claim_id" = "c"."claim_id")))
  GROUP BY "c"."claim_id", "c"."display_label", "c"."chapter", "c"."region";


ALTER VIEW "public"."v_claim_evidence_summary" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_claim_evidence_summary" IS 'Per-claim triangulation summary. Used by the civic page to render confidence badges.';



CREATE OR REPLACE VIEW "public"."v_clarity_board" WITH ("security_invoker"='true') AS
 SELECT "q"."slug",
    "q"."stub",
    "q"."question",
    "q"."subject",
    "q"."state",
    "q"."form",
    "q"."honest_at",
    "q"."publishable",
    "q"."defamation_sensitive",
    "q"."verification_stamp",
    "q"."caveat",
    "q"."exclusions",
    "q"."claim_phrasing",
    "q"."forbidden_phrasing",
    "q"."answer_sql",
    "q"."rows_sql",
    "q"."coverage_sql",
    "q"."refuses_when",
    "q"."live_rerun_ok",
    "q"."measured_ms",
    "q"."blocked_by",
    "q"."blocked_by_metric",
    "q"."unlocks_questions",
    "q"."unlock_effort",
    "q"."unlock_note",
    "q"."unlock_dollars",
    "q"."licence_note",
    "q"."uniqueness",
    "q"."uniqueness_basis",
    "q"."surface",
    "q"."reach_score",
    "q"."created_at",
    "q"."updated_at",
    "a"."headline",
    "a"."headline_sub",
    "a"."headline_num",
    "a"."coverage_num",
    "a"."coverage_den",
    "a"."coverage_label",
    "a"."computed_at",
    "a"."ok",
    "a"."error_text",
    "a"."sentinel_flags",
    "a"."duration_ms"
   FROM ("public"."clarity_question" "q"
     LEFT JOIN LATERAL ( SELECT "x"."id",
            "x"."question_slug",
            "x"."computed_at",
            "x"."ok",
            "x"."error_text",
            "x"."payload",
            "x"."headline",
            "x"."headline_sub",
            "x"."headline_num",
            "x"."coverage_num",
            "x"."coverage_den",
            "x"."coverage_label",
            "x"."sentinel_flags",
            "x"."row_count",
            "x"."duration_ms"
           FROM "public"."clarity_answer" "x"
          WHERE ("x"."question_slug" = "q"."slug")
          ORDER BY "x"."computed_at" DESC
         LIMIT 1) "a" ON (true))
  WHERE ("q"."state" <> 'retired'::"public"."clarity_question_state");


ALTER VIEW "public"."v_clarity_board" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_clarity_board_cards" WITH ("security_invoker"='true') AS
 SELECT "slug",
    "stub",
    "question",
    "subject",
    "state",
    "form",
    "honest_at",
    "publishable",
    "defamation_sensitive",
    "verification_stamp",
    "caveat",
    "exclusions",
    "claim_phrasing",
    "forbidden_phrasing",
    "answer_sql",
    "rows_sql",
    "coverage_sql",
    "refuses_when",
    "live_rerun_ok",
    "measured_ms",
    "blocked_by",
    "blocked_by_metric",
    "unlocks_questions",
    "unlock_effort",
    "unlock_note",
    "unlock_dollars",
    "licence_note",
    "uniqueness",
    "uniqueness_basis",
    "surface",
    "reach_score",
    "created_at",
    "updated_at",
    "headline",
    "headline_sub",
    "headline_num",
    "coverage_num",
    "coverage_den",
    "coverage_label",
    "computed_at",
    "ok",
    "error_text",
    "sentinel_flags",
    "duration_ms",
    ( SELECT "count"(*) AS "count"
           FROM "public"."clarity_question_ingredient" "i"
          WHERE ("i"."question_slug" = "b"."slug")) AS "ingredient_count",
    ( SELECT "i"."object_key"
           FROM "public"."clarity_question_ingredient" "i"
          WHERE (("i"."question_slug" = "b"."slug") AND "i"."is_binding")
         LIMIT 1) AS "binding_object",
    ( SELECT "i"."measured_pct"
           FROM "public"."clarity_question_ingredient" "i"
          WHERE (("i"."question_slug" = "b"."slug") AND "i"."is_binding")
         LIMIT 1) AS "binding_pct",
    ( SELECT "jsonb_agg"("jsonb_build_object"('object_key', "i"."object_key", 'join_key', "i"."join_key", 'role', "i"."role", 'is_binding', "i"."is_binding", 'measured_pct', "i"."measured_pct") ORDER BY "i"."is_binding" DESC, "i"."object_key") AS "jsonb_agg"
           FROM "public"."clarity_question_ingredient" "i"
          WHERE ("i"."question_slug" = "b"."slug")) AS "ingredients",
    ( SELECT "min"("o"."last_write_at") AS "min"
           FROM ("public"."clarity_question_ingredient" "i"
             JOIN "public"."clarity_object" "o" ON (("o"."object_key" = "i"."object_key")))
          WHERE ("i"."question_slug" = "b"."slug")) AS "oldest_ingredient_write",
    ( SELECT "jsonb_agg"("jsonb_build_object"('at', "x"."computed_at", 'h', "x"."headline", 'n', "x"."headline_num") ORDER BY "x"."computed_at") AS "jsonb_agg"
           FROM ( SELECT "y"."id",
                    "y"."question_slug",
                    "y"."computed_at",
                    "y"."ok",
                    "y"."error_text",
                    "y"."payload",
                    "y"."headline",
                    "y"."headline_sub",
                    "y"."headline_num",
                    "y"."coverage_num",
                    "y"."coverage_den",
                    "y"."coverage_label",
                    "y"."sentinel_flags",
                    "y"."row_count",
                    "y"."duration_ms"
                   FROM "public"."clarity_answer" "y"
                  WHERE (("y"."question_slug" = "b"."slug") AND "y"."ok")
                  ORDER BY "y"."computed_at" DESC
                 LIMIT 6) "x") AS "spark",
    ( SELECT "count"(*) AS "count"
           FROM "public"."clarity_answer" "y"
          WHERE ("y"."question_slug" = "b"."slug")) AS "run_count",
    ( SELECT "y"."row_count"
           FROM "public"."clarity_answer" "y"
          WHERE ("y"."question_slug" = "b"."slug")
          ORDER BY "y"."computed_at" DESC
         LIMIT 1) AS "row_count"
   FROM "public"."v_clarity_board" "b";


ALTER VIEW "public"."v_clarity_board_cards" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_clarity_burndown" WITH ("security_invoker"='true') AS
 WITH "win" AS (
         SELECT "clarity_gap_measurement"."metric_key",
            "clarity_gap_measurement"."value",
            "clarity_gap_measurement"."measured_at"
           FROM "public"."clarity_gap_measurement"
          WHERE (("clarity_gap_measurement"."status" = 'ok'::"text") AND ("clarity_gap_measurement"."value" IS NOT NULL) AND ("clarity_gap_measurement"."measured_at" > ("now"() - '90 days'::interval)))
        ), "ends" AS (
         SELECT "win"."metric_key",
            "count"(*) AS "samples",
            "min"("win"."measured_at") AS "first_at",
            "max"("win"."measured_at") AS "last_at",
            ("array_agg"("win"."value" ORDER BY "win"."measured_at"))[1] AS "first_value",
            ("array_agg"("win"."value" ORDER BY "win"."measured_at" DESC))[1] AS "last_value"
           FROM "win"
          GROUP BY "win"."metric_key"
        )
 SELECT "g"."metric_key",
    "g"."title",
    "g"."question",
    "g"."family",
    "g"."unit",
    "g"."direction",
    "g"."target",
    "e"."samples",
    "e"."first_at",
    "e"."last_at",
    "e"."first_value",
    "e"."last_value",
        CASE
            WHEN (("e"."samples" < 2) OR (EXTRACT(epoch FROM ("e"."last_at" - "e"."first_at")) < (86400)::numeric)) THEN NULL::numeric
            ELSE "round"((("e"."last_value" - "e"."first_value") / (EXTRACT(epoch FROM ("e"."last_at" - "e"."first_at")) / 604800.0)), 3)
        END AS "rate_per_week",
        CASE
            WHEN (("g"."target" IS NULL) OR ("e"."samples" < 2) OR (EXTRACT(epoch FROM ("e"."last_at" - "e"."first_at")) < (86400)::numeric)) THEN NULL::numeric
            ELSE ( SELECT
                    CASE
                        WHEN ("q"."r" = (0)::numeric) THEN NULL::numeric
                        WHEN ((("g"."target" - "e"."last_value") / "q"."r") <= (0)::numeric) THEN NULL::numeric
                        ELSE "ceil"((("g"."target" - "e"."last_value") / "q"."r"))
                    END AS "ceil"
               FROM ( SELECT (("e"."last_value" - "e"."first_value") / (EXTRACT(epoch FROM ("e"."last_at" - "e"."first_at")) / 604800.0)) AS "r") "q")
        END AS "eta_weeks"
   FROM ("public"."clarity_gap_metric" "g"
     LEFT JOIN "ends" "e" USING ("metric_key"))
  WHERE "g"."enabled";


ALTER VIEW "public"."v_clarity_burndown" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_clarity_changes" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."at",
    ("e"."event_type")::"text" AS "event_type",
    "e"."object_key",
