    "e"."after_value",
    "e"."delta_pct",
    "e"."severity",
    "e"."note",
    "e"."reason",
    "e"."reason_by",
    "e"."reason_at",
    (("e"."severity" = 'critical'::"text") AND ("e"."reason" IS NULL)) AS "unexplained",
    "o"."domain",
    "o"."row_count",
    ("o"."object_kind")::"text" AS "object_kind",
    COALESCE("o"."act_business", false) AS "act_business"
   FROM ("public"."clarity_event" "e"
     LEFT JOIN "public"."clarity_object" "o" ON (("o"."object_key" = "e"."object_key")));


ALTER VIEW "public"."v_clarity_changes" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_clarity_join_matrix" WITH ("security_invoker"='true') AS
 SELECT "so"."domain" AS "src_domain",
    "tobj"."domain" AS "tgt_domain",
    "count"(*) AS "edges",
    "count"(*) FILTER (WHERE "e"."declared") AS "declared_edges",
    "count"("e"."match_rate") AS "measured_edges",
    "max"("e"."match_rate") AS "best_match_rate",
    "min"("e"."match_rate") AS "worst_match_rate",
    "sum"("e"."match_denominator") AS "rows_at_stake"
   FROM (("public"."clarity_edge" "e"
     JOIN "public"."clarity_object" "so" ON (("so"."object_key" = "e"."src_object")))
     JOIN "public"."clarity_object" "tobj" ON (("tobj"."object_key" = "e"."tgt_object")))
  WHERE (("so"."domain" IS NOT NULL) AND ("tobj"."domain" IS NOT NULL) AND (COALESCE("so"."act_business", false) = false) AND (COALESCE("tobj"."act_business", false) = false))
  GROUP BY "so"."domain", "tobj"."domain";


ALTER VIEW "public"."v_clarity_join_matrix" OWNER TO "postgres";


