    "o"."routine_kind",
    "o"."routine_returns",
    "o"."routine_volatility",
    "o"."routine_src_bytes",
    "o"."trigger_attachments",
    "o"."rls_enabled",
    "o"."policy_count",
    "o"."anon_grant",
    "o"."anon_open_policies",
    "o"."anon_readable",
    "o"."authenticated_grant",
    "o"."security_invoker",
    "o"."security_definer",
    "o"."anon_execute",
    "o"."domain",
    "o"."lifecycle",
    "o"."grain",
    "o"."purpose",
    "o"."caveat",
    "o"."join_keys",
    "o"."act_business",
    "o"."act_business_source",
    "o"."refs_app",
    "o"."refs_script",
    "o"."refs_migration",
    "o"."refs_db_function",
    "o"."owner_app",
    "o"."state",
    "o"."importance",
    "o"."verdict",
    "o"."verdict_reason",
    "o"."verdict_by",
    "o"."verdict_at",
    "o"."first_seen_at",
