    ("dc"."table_name" IS NOT NULL) AS "catalog_linked",
    ("o"."domain" IS NOT NULL) AS "has_domain",
    (("o"."purpose" IS NOT NULL) AND ("btrim"("o"."purpose") <> ''::"text")) AS "has_purpose",
    ("dc"."owner_team" IS NOT NULL) AS "has_owner",
    ("o"."degree" > 0) AS "has_join",
    ((("o"."refs_app" + "o"."refs_script") + "o"."refs_db_function") > 0) AS "has_use",
    (("o"."last_write_at" IS NOT NULL) AND ("o"."last_write_at" > ("now"() - '30 days'::interval))) AS "is_fresh",
    ("o"."anon_readable" AND (COALESCE("dc"."pii_level", ''::"text") = ANY (ARRAY['high'::"text", 'medium'::"text"]))) AS "exposure_conflict"
   FROM ("public"."clarity_object" "o"
     LEFT JOIN "public"."data_catalog" "dc" ON (("dc"."table_name" = "o"."object_name")));


ALTER VIEW "public"."v_clarity_ledger" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_clarity_metric_latest" WITH ("security_invoker"='true') AS
 SELECT DISTINCT ON ("g"."metric_key") "g"."metric_key",
    "g"."title",
    "g"."question",
    "g"."family",
    "g"."unit",
    "g"."direction",
    "g"."target",
    "g"."enabled",
    "g"."note",
    "m"."measured_at",
    "m"."numerator",
    "m"."denominator",
    "m"."value",
    "m"."status",
    "m"."duration_ms",
        CASE
            WHEN ("g"."target" IS NULL) THEN NULL::boolean
            WHEN ("g"."direction" = 'higher_better'::"text") THEN ("m"."value" < "g"."target")
            ELSE ("m"."value" > "g"."target")
        END AS "breached"
   FROM ("public"."clarity_gap_metric" "g"
     JOIN "public"."clarity_gap_measurement" "m" USING ("metric_key"))
  ORDER BY "g"."metric_key", "m"."measured_at" DESC;


ALTER VIEW "public"."v_clarity_metric_latest" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_clarity_seams" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."mechanism",
    "e"."src_object",
    "e"."src_column",
    "e"."tgt_object",
    "e"."tgt_column",
    "e"."declared",
    "e"."match_rate",
    "e"."match_numerator",
    "e"."match_denominator",
    "e"."match_method",
    "e"."match_measured_at",
    "e"."rows_at_stake",
    "e"."grain",
    "e"."note",
    "round"(((COALESCE("e"."rows_at_stake", "e"."match_denominator", (0)::bigint))::numeric * ((1)::numeric - COALESCE("e"."match_rate", (0)::numeric)))) AS "rows_losing",
    ("e"."match_rate" - "h"."match_rate") AS "match_delta",
    "so"."domain" AS "src_domain",
    "tobj"."domain" AS "tgt_domain"
   FROM ((("public"."clarity_edge" "e"
     LEFT JOIN LATERAL ( SELECT "x"."match_rate"
           FROM "public"."clarity_edge_history" "x"
          WHERE (("x"."edge_id" = "e"."id") AND ("x"."captured_at" < "e"."match_measured_at"))
          ORDER BY "x"."captured_at" DESC
         LIMIT 1) "h" ON (true))
     LEFT JOIN "public"."clarity_object" "so" ON (("so"."object_key" = "e"."src_object")))
     LEFT JOIN "public"."clarity_object" "tobj" ON (("tobj"."object_key" = "e"."tgt_object")))
  WHERE ("e"."mechanism" <> 'view_lineage'::"text");


ALTER VIEW "public"."v_clarity_seams" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_clarity_wants" AS
 WITH "blocked" AS (
         SELECT "q"."slug",
            "q"."stub",
            "q"."question",
            "q"."subject",
            "q"."state",
            "q"."form",
            "q"."honest_at",
            "q"."publishable",
            "q"."defamation_sensitive",
            "q"."verification_stamp",
            "q"."caveat",
            "q"."exclusions",
            "q"."claim_phrasing",
            "q"."forbidden_phrasing",
            "q"."answer_sql",
            "q"."rows_sql",
            "q"."coverage_sql",
            "q"."refuses_when",
            "q"."live_rerun_ok",
            "q"."measured_ms",
            "q"."blocked_by",
            "q"."blocked_by_metric",
            "q"."unlocks_questions",
            "q"."unlock_effort",
            "q"."unlock_note",
            "q"."unlock_dollars",
            "q"."licence_note",
            "q"."uniqueness",
            "q"."uniqueness_basis",
            "q"."surface",
            "q"."reach_score",
            "q"."created_at",
            "q"."updated_at"
           FROM "public"."clarity_question" "q"
          WHERE ("q"."state" = ANY (ARRAY['unanswerable'::"public"."clarity_question_state", 'refused'::"public"."clarity_question_state", 'contested'::"public"."clarity_question_state"]))
        ), "blockers" AS (
         SELECT "b_1"."slug",
            "jsonb_agg"("jsonb_build_object"('object_key', "o"."object_key", 'object_name', "o"."object_name", 'rows', "o"."row_count", 'state', "o"."state") ORDER BY "o"."object_name") AS "blocker_objects"
           FROM ("blocked" "b_1"
             JOIN "public"."clarity_object" "o" ON (("o"."object_key" = ANY ("b_1"."blocked_by"))))
          GROUP BY "b_1"."slug"
        )
 SELECT "b"."slug",
    "b"."stub",
    "b"."question",
    "b"."subject",
    "b"."state",
    "b"."blocked_by",
    "b"."blocked_by_metric",
    "b"."unlock_effort",
    "b"."unlock_note",
    "b"."unlock_dollars",
    "b"."licence_note",
    COALESCE("bl"."blocker_objects", '[]'::"jsonb") AS "blocker_objects",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."clarity_question" "x"
          WHERE (("x"."slug" <> "b"."slug") AND (("x"."blocked_by" && "b"."blocked_by") OR (("b"."blocked_by_metric" IS NOT NULL) AND ("x"."blocked_by_metric" = "b"."blocked_by_metric"))))) AS "also_blocks",
    "cardinality"("b"."unlocks_questions") AS "unlocks_named",
    "m"."value" AS "metric_now",
    "m"."target" AS "metric_target",
    "m"."unit" AS "metric_unit",
    "m"."direction" AS "metric_direction",
    "m"."numerator" AS "metric_numerator",
    "m"."denominator" AS "metric_denominator",
    "m"."measured_at" AS "metric_measured_at",
        CASE
            WHEN (("m"."value" IS NULL) OR ("m"."target" IS NULL)) THEN NULL::numeric
            WHEN ("m"."direction" = 'higher_better'::"text") THEN "round"(("m"."target" - "m"."value"), 2)
            ELSE "round"(("m"."value" - "m"."target"), 2)
        END AS "metric_gap",
    "bd"."rate_per_week",
    "bd"."eta_weeks",
    "bd"."samples" AS "metric_samples",
    ("b"."unlock_effort" IS NOT NULL) AS "effort_known",
    "round"((((COALESCE("b"."unlock_dollars", (0)::numeric) + (1)::numeric) * ((1 + ( SELECT "count"(*) AS "count"
           FROM "public"."clarity_question" "x"
          WHERE (("x"."slug" <> "b"."slug") AND (("x"."blocked_by" && "b"."blocked_by") OR (("b"."blocked_by_metric" IS NOT NULL) AND ("x"."blocked_by_metric" = "b"."blocked_by_metric")))))))::numeric) / (
        CASE "b"."unlock_effort"
            WHEN 'S'::"public"."clarity_effort" THEN 1
            WHEN 'M'::"public"."clarity_effort" THEN 3
            ELSE 9
        END)::numeric), 2) AS "rank_score"
   FROM ((("blocked" "b"
     LEFT JOIN "blockers" "bl" ON (("bl"."slug" = "b"."slug")))
     LEFT JOIN "public"."v_clarity_metric_latest" "m" ON (("m"."metric_key" = "b"."blocked_by_metric")))
     LEFT JOIN "public"."v_clarity_burndown" "bd" ON (("bd"."metric_key" = "b"."blocked_by_metric")));


ALTER VIEW "public"."v_clarity_wants" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_clarity_wants" IS 'Every question that cannot be answered, with what it would cost and what it unlocks. Derived entirely from clarity_question — nothing here is hand-maintained separately.';



CREATE OR REPLACE VIEW "public"."v_contact_360" WITH ("security_invoker"='true') AS
 WITH "opp_agg" AS (
         SELECT "ghl_opportunities"."ghl_contact_id",
            "count"(*) AS "opportunity_count",
            COALESCE("sum"("ghl_opportunities"."monetary_value"), (0)::numeric) AS "total_pipeline_value",
            "count"(*) FILTER (WHERE ("ghl_opportunities"."status" = 'won'::"text")) AS "won_count",
            COALESCE("sum"(
                CASE
                    WHEN ("ghl_opportunities"."status" = 'won'::"text") THEN "ghl_opportunities"."monetary_value"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "won_value"
           FROM "public"."ghl_opportunities"
          WHERE ("ghl_opportunities"."ghl_contact_id" IS NOT NULL)
          GROUP BY "ghl_opportunities"."ghl_contact_id"
        ), "comms_agg" AS (
         SELECT "communications_history"."ghl_contact_id",
            "count"(*) AS "email_count",
            "max"("communications_history"."occurred_at") AS "last_email_date",
            "min"("communications_history"."occurred_at") AS "first_email_date"
           FROM "public"."communications_history"
          WHERE ("communications_history"."ghl_contact_id" IS NOT NULL)
          GROUP BY "communications_history"."ghl_contact_id"
        ), "tx_agg" AS (
         SELECT "lower"(TRIM(BOTH FROM "xero_transactions"."contact_name")) AS "contact_name_lower",
            COALESCE("sum"(
                CASE
                    WHEN ("xero_transactions"."type" = 'RECEIVE'::"text") THEN "xero_transactions"."total"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "total_revenue",
            COALESCE("sum"(
                CASE
                    WHEN ("xero_transactions"."type" = 'SPEND'::"text") THEN "abs"("xero_transactions"."total")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "total_payments",
            "count"(*) AS "transaction_count"
           FROM "public"."xero_transactions"
          WHERE (("xero_transactions"."contact_name" IS NOT NULL) AND ("xero_transactions"."contact_name" <> ''::"text"))
          GROUP BY ("lower"(TRIM(BOTH FROM "xero_transactions"."contact_name")))
        )
 SELECT "c"."id",
    "c"."ghl_id",
    "c"."full_name",
    "c"."email",
    "c"."phone",
    "c"."company_name",
    "c"."tags",
    "c"."projects",
    "c"."engagement_status",
    "c"."first_contact_date",
    "c"."last_contact_date",
    COALESCE("oa"."opportunity_count", (0)::bigint) AS "opportunity_count",
    COALESCE("oa"."total_pipeline_value", (0)::numeric) AS "total_pipeline_value",
    COALESCE("oa"."won_count", (0)::bigint) AS "won_count",
    COALESCE("oa"."won_value", (0)::numeric) AS "won_value",
    COALESCE("ca"."email_count", (0)::bigint) AS "email_count",
    "ca"."last_email_date",
    "ca"."first_email_date",
    COALESCE("ta"."total_revenue", (0)::numeric) AS "total_revenue",
    COALESCE("ta"."total_payments", (0)::numeric) AS "total_payments",
    COALESCE("ta"."transaction_count", (0)::bigint) AS "financial_transaction_count"
   FROM ((("public"."ghl_contacts" "c"
     LEFT JOIN "opp_agg" "oa" ON (("oa"."ghl_contact_id" = "c"."ghl_id")))
     LEFT JOIN "comms_agg" "ca" ON (("ca"."ghl_contact_id" = "c"."ghl_id")))
     LEFT JOIN "tx_agg" "ta" ON (("ta"."contact_name_lower" = "lower"(TRIM(BOTH FROM "c"."full_name")))));


ALTER VIEW "public"."v_contact_360" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_contact_360" IS 'Contact with pipeline, communication, and financial stats';



CREATE OR REPLACE VIEW "public"."v_contact_communication_summary" WITH ("security_invoker"='true') AS
 SELECT "c"."ghl_id",
    "c"."full_name",
    "c"."email",
    "rh"."temperature",
    "rh"."lcaa_stage",
    "rh"."days_since_contact",
    "rh"."total_touchpoints",
    "rh"."overall_sentiment",
    ( SELECT "count"(*) AS "count"
           FROM "public"."communications_history" "ch"
          WHERE (("ch"."ghl_contact_id" = "c"."ghl_id") AND ("ch"."channel" = 'email'::"text"))) AS "email_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."communications_history" "ch"
          WHERE (("ch"."ghl_contact_id" = "c"."ghl_id") AND ("ch"."channel" = 'calendar'::"text"))) AS "meeting_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."communications_history" "ch"
          WHERE (("ch"."ghl_contact_id" = "c"."ghl_id") AND ("ch"."channel" = 'call'::"text"))) AS "call_count",
    ( SELECT "array_agg"(DISTINCT "topic"."topic") AS "array_agg"
           FROM "public"."communications_history" "ch",
            LATERAL "unnest"("ch"."topics") "topic"("topic")
          WHERE ("ch"."ghl_contact_id" = "c"."ghl_id")) AS "all_topics"
   FROM ("public"."ghl_contacts" "c"
     LEFT JOIN "public"."relationship_health" "rh" ON (("c"."ghl_id" = "rh"."ghl_contact_id")));


ALTER VIEW "public"."v_contact_communication_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_contained_crm_people" WITH ("security_invoker"='true') AS
 WITH "scoped" AS (
         SELECT "c"."id",
            "c"."ghl_id",
            "c"."ghl_location_id",
            "c"."first_name",
            "c"."last_name",
            "c"."full_name",
            "c"."email",
            "c"."phone",
            "c"."company_name",
            "c"."tags",
            "c"."custom_fields",
            "c"."projects",
            "c"."engagement_status",
            "c"."first_contact_date",
            "c"."last_contact_date",
            "c"."ghl_created_at",
            "c"."ghl_updated_at",
            "c"."last_synced_at",
            "c"."sync_status",
            "c"."sync_error",
            "c"."created_at",
            "c"."updated_at",
            "c"."stories_count",
            "c"."published_stories",
            "c"."is_storyteller",
            "c"."is_elder",
            "c"."empathy_ledger_id",
            "c"."el_last_synced_at",
            "c"."auto_created",
            "c"."auto_created_from",
            "c"."first_seen_subject",
            "c"."enrichment_status",
            "c"."source",
            "c"."newsletter_consent",
            "c"."newsletter_consent_at",
            "c"."newsletter_unsubscribed_at",
            "c"."website",
            "c"."canonical_entity_id",
            "c"."xero_contact_id",
            "c"."xero_match_method",
            "c"."xero_matched_at",
            "c"."canonical_contact_id",
            "c"."audience_segments",
            "c"."primary_audience",
            "count"(*) OVER (PARTITION BY ("lower"(NULLIF(TRIM(BOTH FROM "c"."email"), ''::"text")))) AS "normalized_email_count"
           FROM "public"."ghl_contacts" "c"
          WHERE (EXISTS ( SELECT 1
                   FROM "unnest"(COALESCE("c"."tags", '{}'::"text"[])) "tag"("tag")
                  WHERE (("lower"("tag"."tag") ~~ '%justicehub%'::"text") OR ("lower"("tag"."tag") ~~ '%justice-hub%'::"text") OR ("lower"("tag"."tag") ~~ '%justice hub%'::"text") OR ("lower"("tag"."tag") ~~ '%contained%'::"text") OR ("lower"("tag"."tag") ~~ '%container%'::"text") OR ("lower"("tag"."tag") ~~ '%youth-justice%'::"text") OR ("lower"("tag"."tag") ~~ '%youth justice%'::"text"))))
        ), "affiliations" AS (
         SELECT "a_1"."ghl_contact_id",
            "jsonb_agg"("jsonb_build_object"('affiliation_id', "a_1"."id", 'organization_id', "a_1"."organization_id", 'gs_entity_id', "a_1"."gs_entity_id", 'organization_name', COALESCE("o"."name", "ge"."canonical_name"), 'relationship_type', "a_1"."relationship_type", 'role_title', "a_1"."role_title", 'is_primary', "a_1"."is_primary", 'is_current', "a_1"."is_current", 'confidence', "a_1"."confidence", 'match_method', "a_1"."match_method", 'review_status', "a_1"."review_status") ORDER BY "a_1"."is_primary" DESC, "a_1"."confidence" DESC, COALESCE("o"."name", "ge"."canonical_name")) AS "organizations",
            "count"(*) FILTER (WHERE ("a_1"."review_status" = 'verified'::"text")) AS "verified_organization_count",
            "count"(*) FILTER (WHERE ("a_1"."review_status" = 'proposed'::"text")) AS "proposed_organization_count"
           FROM (("public"."crm_contact_organization_affiliations" "a_1"
             LEFT JOIN "public"."organizations" "o" ON (("o"."id" = "a_1"."organization_id")))
             LEFT JOIN "public"."gs_entities" "ge" ON (("ge"."id" = "a_1"."gs_entity_id")))
          WHERE ("a_1"."review_status" <> 'rejected'::"text")
          GROUP BY "a_1"."ghl_contact_id"
        )
 SELECT "s"."id" AS "contact_id",
    "s"."ghl_id",
    COALESCE(NULLIF(TRIM(BOTH FROM "s"."full_name"), ''::"text"), NULLIF(TRIM(BOTH FROM "concat_ws"(' '::"text", "s"."first_name", "s"."last_name")), ''::"text"), '(unnamed)'::"text") AS "person_name",
    "s"."email",
    "s"."phone",
    "s"."company_name" AS "claimed_company_name",
    COALESCE("a"."organizations", '[]'::"jsonb") AS "organizations",
    COALESCE("a"."verified_organization_count", (0)::bigint) AS "verified_organization_count",
    COALESCE("a"."proposed_organization_count", (0)::bigint) AS "proposed_organization_count",
        CASE
            WHEN (COALESCE("a"."verified_organization_count", (0)::bigint) > 0) THEN 'linked'::"text"
            WHEN (COALESCE("a"."proposed_organization_count", (0)::bigint) > 0) THEN 'review_link'::"text"
            WHEN (NULLIF(TRIM(BOTH FROM "s"."company_name"), ''::"text") IS NOT NULL) THEN 'match_organization'::"text"
            ELSE 'enrich_organization'::"text"
        END AS "organization_review_state",
    "s"."engagement_status",
    "s"."newsletter_consent",
    "s"."newsletter_consent_at",
    "s"."newsletter_unsubscribed_at",
        CASE
            WHEN (("s"."newsletter_consent" IS TRUE) AND (NULLIF(TRIM(BOTH FROM "s"."email"), ''::"text") IS NOT NULL) AND ("s"."newsletter_unsubscribed_at" IS NULL)) THEN 'eligible_pending_live_dnd'::"text"
            WHEN ("s"."engagement_status" = ANY (ARRAY['hot'::"text", 'warm'::"text", 'personal-vip'::"text", 'active-delivery'::"text"])) THEN 'personal_outreach'::"text"
            ELSE 'not_newsletter_eligible'::"text"
        END AS "communication_lane",
        CASE
            WHEN ("s"."normalized_email_count" > 1) THEN 'deduplicate'::"text"
            WHEN (("s"."engagement_status" = ANY (ARRAY['hot'::"text", 'warm'::"text", 'personal-vip'::"text", 'active-delivery'::"text"])) AND ("s"."newsletter_consent" IS NOT TRUE)) THEN 'personal_outreach_consent_review'::"text"
            WHEN (("s"."newsletter_consent" IS TRUE) AND (NULLIF(TRIM(BOTH FROM "s"."email"), ''::"text") IS NOT NULL) AND ("s"."newsletter_unsubscribed_at" IS NULL)) THEN 'newsletter_eligible_pending_live_dnd'::"text"
            WHEN (NULLIF(TRIM(BOTH FROM "s"."email"), ''::"text") IS NULL) THEN 'enrich_missing_email'::"text"
            ELSE 'nurture_review'::"text"
        END AS "review_queue",
    (EXISTS ( SELECT 1
           FROM "unnest"(COALESCE("s"."tags", '{}'::"text"[])) "tag"("tag")
          WHERE (("lower"("tag"."tag") ~~ '%contained%'::"text") OR ("lower"("tag"."tag") ~~ '%container%'::"text")))) AS "contained_relevant",
    (EXISTS ( SELECT 1
           FROM "unnest"(COALESCE("s"."tags", '{}'::"text"[])) "tag"("tag")
          WHERE (("lower"("tag"."tag") ~~ '%justicehub%'::"text") OR ("lower"("tag"."tag") ~~ '%justice-hub%'::"text") OR ("lower"("tag"."tag") ~~ '%justice hub%'::"text")))) AS "justicehub_relevant",
    (EXISTS ( SELECT 1
           FROM "unnest"(COALESCE("s"."tags", '{}'::"text"[])) "tag"("tag")
          WHERE (("lower"("tag"."tag") ~~ '%youth-justice%'::"text") OR ("lower"("tag"."tag") ~~ '%youth justice%'::"text")))) AS "youth_justice_relevant",
    "s"."tags",
    "s"."last_contact_date",
    "s"."last_synced_at"
   FROM ("scoped" "s"
     LEFT JOIN "affiliations" "a" ON (("a"."ghl_contact_id" = "s"."id")));


ALTER VIEW "public"."v_contained_crm_people" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_contained_crm_people" IS 'CONTAINED/JusticeHub people smart list with organisation links, consent-aware communication lanes and review queues.';



CREATE OR REPLACE VIEW "public"."v_contained_crm_organizations" WITH ("security_invoker"='true') AS
 WITH "people" AS (
         SELECT "v_contained_crm_people"."contact_id",
            "v_contained_crm_people"."ghl_id",
            "v_contained_crm_people"."person_name",
            "v_contained_crm_people"."email",
            "v_contained_crm_people"."phone",
            "v_contained_crm_people"."claimed_company_name",
            "v_contained_crm_people"."organizations",
            "v_contained_crm_people"."verified_organization_count",
            "v_contained_crm_people"."proposed_organization_count",
            "v_contained_crm_people"."organization_review_state",
            "v_contained_crm_people"."engagement_status",
            "v_contained_crm_people"."newsletter_consent",
            "v_contained_crm_people"."newsletter_consent_at",
            "v_contained_crm_people"."newsletter_unsubscribed_at",
            "v_contained_crm_people"."communication_lane",
            "v_contained_crm_people"."review_queue",
            "v_contained_crm_people"."contained_relevant",
            "v_contained_crm_people"."justicehub_relevant",
            "v_contained_crm_people"."youth_justice_relevant",
            "v_contained_crm_people"."tags",
            "v_contained_crm_people"."last_contact_date",
            "v_contained_crm_people"."last_synced_at"
           FROM "public"."v_contained_crm_people"
        ), "expanded" AS (
         SELECT "p"."contact_id",
            "p"."ghl_id",
            "p"."person_name",
            "p"."email",
            "p"."phone",
            "p"."claimed_company_name",
            "p"."organizations",
            "p"."verified_organization_count",
            "p"."proposed_organization_count",
            "p"."organization_review_state",
            "p"."engagement_status",
            "p"."newsletter_consent",
            "p"."newsletter_consent_at",
            "p"."newsletter_unsubscribed_at",
            "p"."communication_lane",
            "p"."review_queue",
            "p"."contained_relevant",
            "p"."justicehub_relevant",
            "p"."youth_justice_relevant",
            "p"."tags",
            "p"."last_contact_date",
            "p"."last_synced_at",
            "affiliation"."value" AS "affiliation"
           FROM ("people" "p"
             CROSS JOIN LATERAL "jsonb_array_elements"("p"."organizations") "affiliation"("value"))
        ), "linked" AS (
         SELECT COALESCE(("expanded"."affiliation" ->> 'organization_id'::"text"), ("expanded"."affiliation" ->> 'gs_entity_id'::"text")) AS "organization_key",
            (NULLIF(("expanded"."affiliation" ->> 'organization_id'::"text"), ''::"text"))::"uuid" AS "organization_id",
            (NULLIF(("expanded"."affiliation" ->> 'gs_entity_id'::"text"), ''::"text"))::"uuid" AS "gs_entity_id",
            ("expanded"."affiliation" ->> 'organization_name'::"text") AS "organization_name",
            ("expanded"."affiliation" ->> 'review_status'::"text") AS "review_status",
            "expanded"."person_name",
            "expanded"."ghl_id",
            "expanded"."engagement_status",
            "expanded"."newsletter_consent",
            "expanded"."contained_relevant",
            "expanded"."justicehub_relevant",
            "expanded"."youth_justice_relevant",
            "expanded"."last_contact_date"
           FROM "expanded"
        ), "unlinked" AS (
         SELECT ('candidate:'::"text" || "lower"("regexp_replace"(TRIM(BOTH FROM "people"."claimed_company_name"), '[^a-z0-9]+'::"text", '-'::"text", 'g'::"text"))) AS "organization_key",
            NULL::"uuid" AS "organization_id",
            NULL::"uuid" AS "gs_entity_id",
            TRIM(BOTH FROM "people"."claimed_company_name") AS "organization_name",
            'candidate'::"text" AS "review_status",
            "people"."person_name",
            "people"."ghl_id",
            "people"."engagement_status",
            "people"."newsletter_consent",
            "people"."contained_relevant",
            "people"."justicehub_relevant",
            "people"."youth_justice_relevant",
            "people"."last_contact_date"
           FROM "people"
          WHERE (("jsonb_array_length"("people"."organizations") = 0) AND (NULLIF(TRIM(BOTH FROM "people"."claimed_company_name"), ''::"text") IS NOT NULL))
        ), "all_organization_people" AS (
         SELECT "linked"."organization_key",
            "linked"."organization_id",
            "linked"."gs_entity_id",
            "linked"."organization_name",
            "linked"."review_status",
            "linked"."person_name",
            "linked"."ghl_id",
            "linked"."engagement_status",
            "linked"."newsletter_consent",
            "linked"."contained_relevant",
            "linked"."justicehub_relevant",
            "linked"."youth_justice_relevant",
            "linked"."last_contact_date"
           FROM "linked"
        UNION ALL
         SELECT "unlinked"."organization_key",
            "unlinked"."organization_id",
            "unlinked"."gs_entity_id",
            "unlinked"."organization_name",
            "unlinked"."review_status",
            "unlinked"."person_name",
            "unlinked"."ghl_id",
            "unlinked"."engagement_status",
            "unlinked"."newsletter_consent",
            "unlinked"."contained_relevant",
            "unlinked"."justicehub_relevant",
            "unlinked"."youth_justice_relevant",
            "unlinked"."last_contact_date"
           FROM "unlinked"
        )
 SELECT "organization_key",
    ("max"(("organization_id")::"text"))::"uuid" AS "organization_id",
    ("max"(("gs_entity_id")::"text"))::"uuid" AS "gs_entity_id",
    "max"("organization_name") AS "organization_name",
        CASE
            WHEN "bool_or"(("review_status" = 'verified'::"text")) THEN 'linked'::"text"
            WHEN "bool_or"(("review_status" = 'proposed'::"text")) THEN 'review_link'::"text"
            ELSE 'create_or_match'::"text"
        END AS "organization_review_state",
    "count"(DISTINCT "ghl_id") AS "people_count",
    "array_agg"(DISTINCT "person_name" ORDER BY "person_name") AS "people",
    "array_agg"(DISTINCT "ghl_id" ORDER BY "ghl_id") AS "ghl_contact_ids",
    "count"(*) FILTER (WHERE ("newsletter_consent" IS TRUE)) AS "consented_people_count",
    "bool_or"("contained_relevant") AS "contained_relevant",
    "bool_or"("justicehub_relevant") AS "justicehub_relevant",
    "bool_or"("youth_justice_relevant") AS "youth_justice_relevant",
    "max"("last_contact_date") AS "last_contact_date",
        CASE
            WHEN "bool_or"(("engagement_status" = 'active-delivery'::"text")) THEN 'active-delivery'::"text"
            WHEN "bool_or"(("engagement_status" = 'hot'::"text")) THEN 'hot'::"text"
            WHEN "bool_or"(("engagement_status" = 'personal-vip'::"text")) THEN 'personal-vip'::"text"
            WHEN "bool_or"(("engagement_status" = 'warm'::"text")) THEN 'warm'::"text"
            WHEN "bool_or"(("engagement_status" = 'nurture'::"text")) THEN 'nurture'::"text"
            ELSE 'lead'::"text"
        END AS "warmest_engagement_status"
   FROM "all_organization_people"
  GROUP BY "organization_key";


ALTER VIEW "public"."v_contained_crm_organizations" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_contained_crm_organizations" IS 'CONTAINED/JusticeHub organisation smart list aggregated from reviewed person affiliations and unmatched company candidates.';



CREATE OR REPLACE VIEW "public"."v_ctg_youth_justice_progress" AS
 SELECT "a"."financial_year",
    "state"."abbrev" AS "state",
        CASE "state"."abbrev"
            WHEN 'NSW'::"text" THEN "a"."nsw"
            WHEN 'VIC'::"text" THEN "a"."vic"
            WHEN 'QLD'::"text" THEN "a"."qld"
            WHEN 'WA'::"text" THEN "a"."wa"
            WHEN 'SA'::"text" THEN "a"."sa"
            WHEN 'TAS'::"text" THEN "a"."tas"
            WHEN 'ACT'::"text" THEN "a"."act"
            WHEN 'NT'::"text" THEN "a"."nt"
            ELSE NULL::numeric
        END AS "actual_rate",
        CASE "state"."abbrev"
            WHEN 'NSW'::"text" THEN "t"."nsw"
            WHEN 'VIC'::"text" THEN "t"."vic"
            WHEN 'QLD'::"text" THEN "t"."qld"
            WHEN 'WA'::"text" THEN "t"."wa"
            WHEN 'SA'::"text" THEN "t"."sa"
            WHEN 'TAS'::"text" THEN "t"."tas"
            WHEN 'ACT'::"text" THEN "t"."act"
            WHEN 'NT'::"text" THEN "t"."nt"
            ELSE NULL::numeric
        END AS "trajectory_rate",
    "t"."aust" AS "national_target",
    "a"."aust" AS "national_actual",
        CASE "state"."abbrev"
            WHEN 'NSW'::"text" THEN ("a"."nsw" - COALESCE("t"."nsw", (0)::numeric))
            WHEN 'VIC'::"text" THEN ("a"."vic" - COALESCE("t"."vic", (0)::numeric))
            WHEN 'QLD'::"text" THEN ("a"."qld" - COALESCE("t"."qld", (0)::numeric))
            WHEN 'WA'::"text" THEN ("a"."wa" - COALESCE("t"."wa", (0)::numeric))
            WHEN 'SA'::"text" THEN ("a"."sa" - COALESCE("t"."sa", (0)::numeric))
            WHEN 'TAS'::"text" THEN ("a"."tas" - COALESCE("t"."tas", (0)::numeric))
            WHEN 'ACT'::"text" THEN ("a"."act" - COALESCE("t"."act", (0)::numeric))
            WHEN 'NT'::"text" THEN ("a"."nt" - COALESCE("t"."nt", (0)::numeric))
            ELSE NULL::numeric
        END AS "gap_from_target"
   FROM (("public"."rogs_justice_spending" "a"
     CROSS JOIN ( VALUES ('NSW'::"text"), ('VIC'::"text"), ('QLD'::"text"), ('WA'::"text"), ('SA'::"text"), ('TAS'::"text"), ('ACT'::"text"), ('NT'::"text")) "state"("abbrev"))
     LEFT JOIN "public"."rogs_justice_spending" "t" ON ((("t"."financial_year" = "a"."financial_year") AND ("t"."rogs_table" = 'CtG11A.1'::"text") AND ("t"."rogs_section" = 'closing-the-gap'::"text") AND ("t"."description3" = 'Trajectory'::"text"))))
  WHERE (("a"."rogs_table" = 'CtG11A.1'::"text") AND ("a"."rogs_section" = 'closing-the-gap'::"text") AND ("a"."description3" IS DISTINCT FROM 'Trajectory'::"text") AND ("a"."description3" IS DISTINCT FROM 'Linear regression estimates'::"text") AND ("a"."unit" = 'rate'::"text") AND ("a"."indigenous_status" ~~* '%Aboriginal%'::"text"))
  ORDER BY "a"."financial_year" DESC, "state"."abbrev";


ALTER VIEW "public"."v_ctg_youth_justice_progress" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_ctg_youth_justice_progress" IS 'Closing the Gap Outcome 11 progress: actual Indigenous detention rates vs trajectory targets';



CREATE OR REPLACE VIEW "public"."v_cultural_data_access" WITH ("security_invoker"='true') AS
 SELECT "agent_id",
    "action",
    "target_table",
    "target_id",
    "user_context",
    "timestamp"
   FROM "public"."agent_audit_log"
  WHERE ("cultural_data_accessed" = true)
  ORDER BY "timestamp" DESC;


ALTER VIEW "public"."v_cultural_data_access" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_data_catalog_latest" AS
 SELECT DISTINCT ON ("dc"."table_name") "dc"."table_name",
    "dc"."domain",
    "dc"."owner_team",
    "dc"."description",
    "dc"."source_of_truth",
    "dc"."pii_level",
    "dc"."sla_hours",
    "dc"."freshness_key",
    "dc"."provenance_field",
    "dc"."confidence_field",
    "dc"."active",
    "dcs"."snapshot_at",
    "dcs"."row_count",
    "dcs"."freshness_hours",
    "dcs"."provenance_coverage_pct",
    "dcs"."confidence_coverage_pct",
    "dc"."public_export",
    "dc"."licence",
    "dc"."source_url",
    "dc"."source_owner",
    "dc"."collection_method",
    "dc"."update_cadence",
    "dc"."public_caveat"
   FROM ("public"."data_catalog" "dc"
     LEFT JOIN "public"."data_catalog_snapshots" "dcs" ON (("dcs"."table_name" = "dc"."table_name")))
  ORDER BY "dc"."table_name", "dcs"."snapshot_at" DESC NULLS LAST;


ALTER VIEW "public"."v_data_catalog_latest" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_data_health" AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."gs_entities") AS "total_entities",
    ( SELECT "count"(*) AS "count"
           FROM "public"."gs_entities"
          WHERE ("gs_entities"."postcode" IS NOT NULL)) AS "entities_with_postcode",
    ( SELECT "count"(*) AS "count"
           FROM "public"."gs_entities"
          WHERE ("gs_entities"."sa2_code" IS NOT NULL)) AS "entities_with_sa2",
    ( SELECT "count"(*) AS "count"
           FROM "public"."gs_entities"
          WHERE (("gs_entities"."postcode" IS NOT NULL) AND ("gs_entities"."sa2_code" IS NULL))) AS "entities_postcode_no_sa2",
    ( SELECT "count"(*) AS "count"
           FROM "public"."gs_entities"
          WHERE ("gs_entities"."postcode" IS NULL)) AS "entities_no_postcode",
    ( SELECT "count"(DISTINCT "postcode_geo"."postcode") AS "count"
           FROM "public"."postcode_geo") AS "postcodes_total",
    ( SELECT "count"(DISTINCT "postcode_geo"."postcode") AS "count"
           FROM "public"."postcode_geo"
          WHERE ("postcode_geo"."sa2_code" IS NOT NULL)) AS "postcodes_with_sa2",
    ( SELECT "count"(DISTINCT "postcode_geo"."sa2_code") AS "count"
           FROM "public"."postcode_geo"
          WHERE (("postcode_geo"."sa2_code" IS NOT NULL) AND ("postcode_geo"."postcode" IN ( SELECT DISTINCT "gs_entities"."postcode"
                   FROM "public"."gs_entities"
                  WHERE ("gs_entities"."postcode" IS NOT NULL))))) AS "sa2_regions_with_data",
    2473 AS "sa2_regions_total",
    ( SELECT "count"(*) AS "count"
           FROM "public"."gs_relationships") AS "total_relationships",
    ( SELECT "count"(*) AS "count"
           FROM "public"."money_flows") AS "total_money_flows",
    ( SELECT "count"(*) AS "count"
           FROM "public"."acnc_charities") AS "acnc_records",
    ( SELECT "count"(*) AS "count"
           FROM "public"."foundations") AS "foundation_records",
    ( SELECT "count"(*) AS "count"
           FROM "public"."political_donations") AS "political_donation_records";


ALTER VIEW "public"."v_data_health" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_data_quality_scores" WITH ("security_invoker"='true') AS
 SELECT 'ghl_opportunities'::"text" AS "source",
    "count"(*) AS "total",
    "count"("ghl_opportunities"."project_code") AS "tagged",
    "round"(((("count"("ghl_opportunities"."project_code"))::numeric / (NULLIF("count"(*), 0))::numeric) * (100)::numeric), 1) AS "pct"
   FROM "public"."ghl_opportunities"
UNION ALL
 SELECT 'xero_transactions'::"text" AS "source",
    "count"(*) AS "total",
    "count"("xero_transactions"."project_code") AS "tagged",
    "round"(((("count"("xero_transactions"."project_code"))::numeric / (NULLIF("count"(*), 0))::numeric) * (100)::numeric), 1) AS "pct"
   FROM "public"."xero_transactions"
UNION ALL
 SELECT 'xero_invoices'::"text" AS "source",
    "count"(*) AS "total",
    "count"("xero_invoices"."project_code") AS "tagged",
    "round"(((("count"("xero_invoices"."project_code"))::numeric / (NULLIF("count"(*), 0))::numeric) * (100)::numeric), 1) AS "pct"
   FROM "public"."xero_invoices"
UNION ALL
 SELECT 'subscriptions'::"text" AS "source",
    "count"(*) AS "total",
    "count"(NULLIF("subscriptions"."project_codes", '{}'::"text"[])) AS "tagged",
    "round"(((("count"(NULLIF("subscriptions"."project_codes", '{}'::"text"[])))::numeric / (NULLIF("count"(*), 0))::numeric) * (100)::numeric), 1) AS "pct"
   FROM "public"."subscriptions"
  WHERE ("subscriptions"."account_status" = 'active'::"text");


ALTER VIEW "public"."v_data_quality_scores" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_data_sufficiency" AS
 SELECT "topic",
    "count"(*) FILTER (WHERE ("status" = 'active'::"text")) AS "active_sources",
    "count"(*) FILTER (WHERE ("status" = 'planned'::"text")) AS "planned_sources",
    "count"(*) FILTER (WHERE ("status" = 'paused'::"text")) AS "paused_sources",
    "count"(*) FILTER (WHERE (("last_refreshed_at" IS NULL) OR ("last_refreshed_at" < ("now"() - '60 days'::interval)))) AS "stale_sources",
    "sum"("row_count") FILTER (WHERE ("status" = 'active'::"text")) AS "active_row_count"
   FROM "public"."data_sources_inventory"
  GROUP BY "topic";


ALTER VIEW "public"."v_data_sufficiency" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_data_sufficiency" IS 'Per-topic rollup of source counts + staleness for the admin dashboard.';



CREATE OR REPLACE VIEW "public"."v_discovery_summary" WITH ("security_invoker"='true') AS
 SELECT "source",
    "event_type",
    "count"(*) AS "event_count",
    "avg"("confidence") AS "avg_confidence",
    "max"("created_at") AS "last_event"
   FROM "public"."subscription_discovery_events"
  WHERE ("created_at" > ("now"() - '30 days'::interval))
  GROUP BY "source", "event_type"
  ORDER BY ("count"(*)) DESC;


ALTER VIEW "public"."v_discovery_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_duplicate_review_queue" WITH ("security_invoker"='true') AS
 SELECT "pm"."id" AS "match_id",
    "pm"."match_score",
    "pm"."match_reasons",
    "pm"."detected_at",
    "a"."id" AS "entity_a_id",
    "a"."canonical_name" AS "name_a",
    "a"."canonical_email" AS "email_a",
    "a"."canonical_company" AS "company_a",
    "b"."id" AS "entity_b_id",
    "b"."canonical_name" AS "name_b",
    "b"."canonical_email" AS "email_b",
    "b"."canonical_company" AS "company_b"
   FROM (("public"."entity_potential_matches" "pm"
     JOIN "public"."canonical_entities" "a" ON (("pm"."entity_a_id" = "a"."id")))
     JOIN "public"."canonical_entities" "b" ON (("pm"."entity_b_id" = "b"."id")))
  WHERE ("pm"."status" = 'pending'::"text")
  ORDER BY "pm"."match_score" DESC;


ALTER VIEW "public"."v_duplicate_review_queue" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_enriched_opportunities" WITH ("security_invoker"='true') AS
 SELECT "o"."id",
    "o"."ghl_id",
    "o"."name",
    "o"."status",
    "o"."monetary_value",
    "o"."pipeline_name",
    "o"."stage_name",
    "o"."project_code",
    "o"."ghl_contact_id",
    "o"."ghl_pipeline_id",
    "o"."ghl_stage_id",
    "o"."assigned_to",
    "o"."ghl_created_at",
    "o"."ghl_updated_at",
    "o"."created_at",
    "o"."updated_at",
    "c"."full_name" AS "contact_name",
    "c"."email" AS "contact_email",
    "c"."company_name" AS "contact_company",
    "p"."name" AS "pipeline_name_resolved",
    "p"."ghl_location_id"
   FROM (("public"."ghl_opportunities" "o"
     LEFT JOIN "public"."ghl_contacts" "c" ON (("c"."ghl_id" = "o"."ghl_contact_id")))
     LEFT JOIN "public"."ghl_pipelines" "p" ON (("p"."ghl_id" = "o"."ghl_pipeline_id")));


ALTER VIEW "public"."v_enriched_opportunities" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_enriched_opportunities" IS 'Opportunities enriched with contact name/email and pipeline details';



CREATE OR REPLACE VIEW "public"."v_enrichment_review_queue" WITH ("security_invoker"='true') AS
 SELECT "ec"."id",
    "ec"."entity_id",
    "e"."canonical_name" AS "entity_name",
    "e"."entity_type",
    "ec"."source",
    "ec"."platform",
    "ec"."confidence",
    "ec"."extracted_fields",
    "ec"."created_at"
   FROM ("public"."enrichment_candidates" "ec"
     JOIN "public"."gs_entities" "e" ON (("e"."id" = "ec"."entity_id")))
  WHERE ("ec"."status" = 'pending'::"text")
  ORDER BY "ec"."confidence" DESC, "ec"."created_at";


ALTER VIEW "public"."v_enrichment_review_queue" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_entity_360" AS
 WITH "funding_totals" AS (
         SELECT "justice_funding"."alma_organization_id" AS "org_id",
            "sum"("justice_funding"."amount_dollars") AS "total_justice_funding",
            "count"(*) AS "justice_funding_count"
           FROM "public"."justice_funding"
          WHERE ("justice_funding"."alma_organization_id" IS NOT NULL)
          GROUP BY "justice_funding"."alma_organization_id"
        ), "foundation_received" AS (
         SELECT "o_1"."id" AS "org_id",
            "sum"("fg_1"."grant_amount") AS "foundation_dollars_received",
            "count"(*) AS "foundation_grants_received"
           FROM ("public"."organizations" "o_1"
             JOIN "public"."foundation_grantees" "fg_1" ON (("fg_1"."grantee_abn" = "o_1"."abn")))
          WHERE ("o_1"."abn" IS NOT NULL)
          GROUP BY "o_1"."id"
        ), "foundation_given" AS (
         SELECT "o_1"."id" AS "org_id",
            "sum"("fg_1"."grant_amount") AS "foundation_dollars_given",
            "count"(*) AS "foundation_grants_given"
           FROM ("public"."organizations" "o_1"
             JOIN "public"."foundation_grantees" "fg_1" ON (("fg_1"."foundation_abn" = "o_1"."abn")))
          WHERE ("o_1"."abn" IS NOT NULL)
          GROUP BY "o_1"."id"
        ), "classifications" AS (
         SELECT "civic_org_classifications"."organization_id" AS "org_id",
            "bool_or"((("civic_org_classifications"."tier" = 1) AND ("civic_org_classifications"."confirmed_at" IS NOT NULL))) AS "is_confirmed_tier1",
            "max"(
                CASE
                    WHEN ("civic_org_classifications"."confirmed_at" IS NOT NULL) THEN "civic_org_classifications"."tier"
                    ELSE NULL::smallint
                END) AS "confirmed_tier",
            "max"("civic_org_classifications"."sector_category") FILTER (WHERE ("civic_org_classifications"."confirmed_at" IS NOT NULL)) AS "confirmed_sector"
           FROM "public"."civic_org_classifications"
          GROUP BY "civic_org_classifications"."organization_id"
        ), "ato_latest" AS (
         SELECT DISTINCT ON ("ato_tax_transparency"."abn") "ato_tax_transparency"."abn",
            "ato_tax_transparency"."total_income",
            "ato_tax_transparency"."taxable_income",
            "ato_tax_transparency"."report_year"
           FROM "public"."ato_tax_transparency"
          ORDER BY "ato_tax_transparency"."abn", "ato_tax_transparency"."report_year" DESC NULLS LAST
        )
 SELECT "o"."id" AS "organization_id",
    "o"."abn",
    "o"."name",
    "o"."slug",
    "o"."state",
    "o"."city",
    "o"."type",
    "o"."is_active",
    "o"."acco_certified",
    "o"."is_indigenous_org",
    "o"."profile_completeness_score",
    "ac"."charity_size",
    "ac"."pbi",
    "ac"."hpc",
    "ac"."is_foundation" AS "acnc_is_foundation",
    "ac"."ben_aboriginal_tsi",
    "ac"."ben_youth",
    ("ac"."charity_size" IS NOT NULL) AS "is_acnc_charity",
    "oc"."icn" AS "oric_icn",
    "oc"."status" AS "oric_status",
    "oc"."corporation_size" AS "oric_corp_size",
    ("oc"."abn" IS NOT NULL) AS "in_oric_register",
    "ato"."total_income" AS "ato_total_income",
    "ato"."taxable_income" AS "ato_taxable_income",
    "ato"."report_year" AS "ato_report_year",
    "ndis"."registration_status" AS "ndis_status",
    "cls"."is_confirmed_tier1",
    "cls"."confirmed_tier",
    "cls"."confirmed_sector",
    COALESCE("ft"."total_justice_funding", (0)::numeric) AS "total_justice_funding_received",
    COALESCE("ft"."justice_funding_count", (0)::bigint) AS "justice_funding_records",
    COALESCE("fr"."foundation_dollars_received", (0)::numeric) AS "foundation_dollars_received",
    COALESCE("fr"."foundation_grants_received", (0)::bigint) AS "foundation_grants_received",
    COALESCE("fg"."foundation_dollars_given", (0)::numeric) AS "foundation_dollars_given",
    COALESCE("fg"."foundation_grants_given", (0)::bigint) AS "foundation_grants_given"
   FROM (((((((("public"."organizations" "o"
     LEFT JOIN "public"."acnc_charities" "ac" ON ((("ac"."abn" = "o"."abn") AND ("o"."abn" IS NOT NULL))))
     LEFT JOIN "public"."oric_corporations" "oc" ON ((("oc"."abn" = "o"."abn") AND ("o"."abn" IS NOT NULL))))
     LEFT JOIN "ato_latest" "ato" ON ((("ato"."abn" = "o"."abn") AND ("o"."abn" IS NOT NULL))))
     LEFT JOIN "public"."ndis_registered_providers" "ndis" ON ((("ndis"."abn" = "o"."abn") AND ("o"."abn" IS NOT NULL))))
     LEFT JOIN "classifications" "cls" ON (("cls"."org_id" = "o"."id")))
     LEFT JOIN "funding_totals" "ft" ON (("ft"."org_id" = "o"."id")))
     LEFT JOIN "foundation_received" "fr" ON (("fr"."org_id" = "o"."id")))
     LEFT JOIN "foundation_given" "fg" ON (("fg"."org_id" = "o"."id")))
  WHERE ("o"."archived" <> true);


ALTER VIEW "public"."v_entity_360" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_entity_360" IS 'Entity-360 view: every fact about an org joined via ABN. One row per active org. Powers /sites/[slug] enrichment and cross-source civic analysis.';



CREATE OR REPLACE VIEW "public"."v_entity_abr" AS
 SELECT "e"."id",
    "e"."gs_id",
    "e"."canonical_name",
    "e"."abn",
    "e"."entity_type",
    "a"."entity_type" AS "abr_entity_type",
    "a"."entity_type_code" AS "abr_type_code",
    "a"."status" AS "abr_status",
    "a"."gst_status",
    "a"."acnc_registered",
    "a"."charity_type",
    "a"."trading_names" AS "abr_trading_names",
    "a"."acn",
    "a"."record_updated_date",
    "ac"."company_type" AS "asic_company_type",
    "ac"."company_class" AS "asic_company_class",
    "ac"."status" AS "asic_status",
    "ac"."date_of_registration" AS "asic_registered_date"
   FROM (("public"."gs_entities" "e"
     LEFT JOIN "public"."abr_registry" "a" ON (("e"."abn" = "a"."abn")))
     LEFT JOIN "public"."asic_companies" "ac" ON (("a"."acn" = "ac"."acn")))
  WHERE ("e"."abn" IS NOT NULL);


ALTER VIEW "public"."v_entity_abr" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."vic_grants_awarded" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source" "text" NOT NULL,
    "agency" "text",
    "program_name" "text",
    "round_name" "text",
    "recipient_name" "text",
    "recipient_abn" "text",
    "amount_aud" numeric,
    "approval_date" "date",
    "start_date" "date",
    "end_date" "date",
    "financial_year" "text",
    "description" "text",
    "region" "text",
    "state" "text" DEFAULT 'VIC'::"text",
    "source_url" "text",
    "source_id" "text",
    "gs_entity_id" "uuid",
    "imported_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "raw" "jsonb",
    CONSTRAINT "vic_grants_awarded_source_check" CHECK (("source" = ANY (ARRAY['vmc'::"text", 'dffh'::"text", 'dpc'::"text", 'creative_vic'::"text", 'health_vic'::"text", 'rdv'::"text", 'djsir'::"text", 'djcs'::"text", 'deeca'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."vic_grants_awarded" OWNER TO "postgres";


COMMENT ON TABLE "public"."vic_grants_awarded" IS 'Awarded Victorian Government grants by source (VMC, DFFH, DPC, Creative Vic, etc). Loaded by scripts/import-vic-grants-awarded.mjs.';



CREATE OR REPLACE VIEW "public"."v_entity_funding_mix" AS
 WITH "ais_latest" AS (
         SELECT DISTINCT ON ("acnc_ais"."abn") "acnc_ais"."abn",
            "acnc_ais"."ais_year",
            "acnc_ais"."revenue_from_government",
            "acnc_ais"."donations_and_bequests",
            "acnc_ais"."revenue_from_goods_services",
            "acnc_ais"."revenue_from_investments",
            "acnc_ais"."total_revenue"
           FROM "public"."acnc_ais"
          WHERE (("acnc_ais"."abn" IS NOT NULL) AND ("acnc_ais"."total_revenue" IS NOT NULL))
          ORDER BY "acnc_ais"."abn", "acnc_ais"."ais_year" DESC
        ), "contracts_agg" AS (
         SELECT "austender_contracts"."supplier_abn" AS "abn",
            ("count"(*))::integer AS "contract_count",
            ("sum"("austender_contracts"."contract_value"))::bigint AS "contract_total"
           FROM "public"."austender_contracts"
          WHERE ("austender_contracts"."supplier_abn" IS NOT NULL)
          GROUP BY "austender_contracts"."supplier_abn"
        ), "gc_agg" AS (
         SELECT "grantconnect_awards"."recipient_abn" AS "abn",
            ("count"(*))::integer AS "gc_award_count",
            ("sum"("grantconnect_awards"."value_aud"))::bigint AS "gc_award_total"
           FROM "public"."grantconnect_awards"
          WHERE ("grantconnect_awards"."recipient_abn" IS NOT NULL)
          GROUP BY "grantconnect_awards"."recipient_abn"
        ), "vic_agg" AS (
         SELECT "vic_grants_awarded"."recipient_abn" AS "abn",
            ("count"(*))::integer AS "vic_award_count",
            ("sum"("vic_grants_awarded"."amount_aud"))::bigint AS "vic_award_total"
           FROM "public"."vic_grants_awarded"
          WHERE ("vic_grants_awarded"."recipient_abn" IS NOT NULL)
          GROUP BY "vic_grants_awarded"."recipient_abn"
        )
 SELECT "e"."gs_id",
    "e"."canonical_name",
    "e"."abn",
    "e"."entity_type",
    "e"."state",
    "ais"."ais_year" AS "latest_ais_year",
    ("ais"."revenue_from_government")::bigint AS "ais_govt_revenue",
    ("ais"."donations_and_bequests")::bigint AS "ais_donations",
    ("ais"."revenue_from_goods_services")::bigint AS "ais_fees",
    ("ais"."total_revenue")::bigint AS "ais_total_revenue",
        CASE
            WHEN ("ais"."total_revenue" > (0)::numeric) THEN "round"((("ais"."revenue_from_government" / "ais"."total_revenue") * (100)::numeric), 1)
            ELSE NULL::numeric
        END AS "ais_govt_pct",
    "c"."contract_count" AS "austender_count",
    "c"."contract_total" AS "austender_total",
    "gc"."gc_award_count" AS "grantconnect_count",
    "gc"."gc_award_total" AS "grantconnect_total",
    "v"."vic_award_count",
    "v"."vic_award_total"
   FROM (((("public"."gs_entities" "e"
     LEFT JOIN "ais_latest" "ais" ON (("ais"."abn" = "e"."abn")))
     LEFT JOIN "contracts_agg" "c" ON (("c"."abn" = "e"."abn")))
     LEFT JOIN "gc_agg" "gc" ON (("gc"."abn" = "e"."abn")))
     LEFT JOIN "vic_agg" "v" ON (("v"."abn" = "e"."abn")))
  WHERE ("e"."abn" IS NOT NULL);


ALTER VIEW "public"."v_entity_funding_mix" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_entity_funding_mix" IS 'Cross-source funder mix per entity. Use ais_govt_pct to spot government-dependent orgs (>80% = high concentration risk).';



CREATE OR REPLACE VIEW "public"."v_entity_name_candidates" AS
 SELECT "gs_entity_id",
    "sum"("amount_dollars") AS "total_dollars",
    "count"(*) AS "award_count",
    ( SELECT "array_agg"(DISTINCT TRIM(BOTH FROM "o"."name")) AS "array_agg"
           FROM "public"."organizations" "o"
          WHERE (("o"."gs_entity_id" = "f"."gs_entity_id") AND ("o"."name" IS NOT NULL) AND (TRIM(BOTH FROM "o"."name") <> ''::"text"))) AS "org_names",
    "count"(DISTINCT "recipient_name") AS "funded_name_count"
   FROM "public"."justice_funding" "f"
  WHERE (("gs_entity_id" IS NOT NULL) AND (NOT "is_aggregate"))
  GROUP BY "gs_entity_id";


ALTER VIEW "public"."v_entity_name_candidates" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_entity_name_candidates" IS 'Name candidates per funded entity. org_names comes ONLY from organizations records: a service name appearing on a payment line is not evidence of an organisation name, so funded names are counted but never offered as candidates.';



CREATE OR REPLACE VIEW "public"."v_entity_organisation_group" AS
 WITH "links" AS (
         SELECT "assertions"."subject_id" AS "a",
            "assertions"."value" AS "b"
           FROM "public"."assertions"
          WHERE (("assertions"."machine_rule" = 'same_abn_v1'::"text") AND ("assertions"."superseded_by" IS NULL))
        ), "grouped" AS (
         SELECT "links"."a" AS "entity_id",
            LEAST("links"."a", "min"("links"."b")) AS "canonical_id"
           FROM "links"
          GROUP BY "links"."a"
        )
 SELECT "entity_id",
    "canonical_id",
    ( SELECT ("count"(*) + 1)
           FROM "links" "l"
          WHERE ("l"."a" = "g"."entity_id")) AS "entities_in_group"
   FROM "grouped" "g";


ALTER VIEW "public"."v_entity_organisation_group" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_entity_organisation_group" IS 'Maps an entity id to the canonical id of the organisation it belongs to, where an ABN proves two ids are one organisation. NOTHING IS MERGED: use this to aggregate, and the underlying rows stay separate so a wrong link can be rejected.';



CREATE OR REPLACE VIEW "public"."v_entity_resolution_stats" WITH ("security_invoker"='true') AS
 SELECT "entity_type",
    "count"(*) AS "total_entities",
    ("avg"("merge_count"))::numeric(4,1) AS "avg_merges",
    ("avg"("confidence"))::numeric(3,2) AS "avg_confidence",
    "count"(*) FILTER (WHERE ("merge_count" > 1)) AS "merged_entities",
    "count"(*) FILTER (WHERE ("verification_status" = 'verified'::"text")) AS "verified_entities"
   FROM "public"."canonical_entities"
  GROUP BY "entity_type";


ALTER VIEW "public"."v_entity_resolution_stats" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."youth_detention_facilities" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "slug" "text",
    "facility_type" "text" DEFAULT 'youth_detention'::"text" NOT NULL,
    "street_address" "text",
    "suburb" "text",
    "city" "text" NOT NULL,
    "state" "text" NOT NULL,
    "postcode" "text",
    "latitude" numeric(10,8),
    "longitude" numeric(11,8),
    "operational_status" "text" DEFAULT 'operational'::"text",
    "opened_date" "date",
    "closed_date" "date",
    "capacity_beds" integer,
    "current_population" integer,
    "male_capacity" integer,
    "female_capacity" integer,
    "age_range_min" integer DEFAULT 10,
    "age_range_max" integer DEFAULT 18,
    "government_department" "text" NOT NULL,
    "managing_agency" "text",
    "contact_phone" "text",
    "contact_email" "text",
    "website" "text",
    "security_level" "text" DEFAULT 'mixed'::"text",
    "has_remand_section" boolean DEFAULT true,
    "has_sentenced_section" boolean DEFAULT true,
    "has_therapeutic_programs" boolean DEFAULT false,
    "has_education_programs" boolean DEFAULT true,
    "indigenous_population_percentage" numeric(5,2),
    "has_cultural_programs" boolean DEFAULT false,
    "has_indigenous_liaison" boolean DEFAULT false,
    "data_source" "text",
    "data_source_url" "text",
    "last_data_update" "date",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "youth_detention_facilities_facility_type_check" CHECK (("facility_type" = ANY (ARRAY['youth_detention'::"text", 'remand_centre'::"text", 'training_centre'::"text", 'watch_house'::"text", 'therapeutic_facility'::"text", 'transition_facility'::"text"]))),
    CONSTRAINT "youth_detention_facilities_operational_status_check" CHECK (("operational_status" = ANY (ARRAY['operational'::"text", 'under_construction'::"text", 'closed'::"text", 'temporary_closure'::"text"]))),
    CONSTRAINT "youth_detention_facilities_security_level_check" CHECK (("security_level" = ANY (ARRAY['minimum'::"text", 'medium'::"text", 'maximum'::"text", 'mixed'::"text"]))),
    CONSTRAINT "youth_detention_facilities_state_check" CHECK (("state" = ANY (ARRAY['NSW'::"text", 'VIC'::"text", 'QLD'::"text", 'SA'::"text", 'WA'::"text", 'TAS'::"text", 'NT'::"text", 'ACT'::"text"])))
);


