CREATE OR REPLACE VIEW "public"."v_finance_bank_line_evidence" WITH ("security_invoker"='true') AS
 WITH "candidate_rollup" AS (
         SELECT "links"."bank_line_id",
            ("count"(*) FILTER (WHERE ("links"."link_status" = ANY (ARRAY['candidate'::"text", 'approved'::"text", 'linked_in_xero'::"text", 'needs_review'::"text"]))))::integer AS "candidate_count",
            "max"("links"."confidence") FILTER (WHERE ("links"."link_status" = ANY (ARRAY['candidate'::"text", 'approved'::"text", 'linked_in_xero'::"text", 'needs_review'::"text"]))) AS "best_confidence",
            ("array_agg"("docs"."id" ORDER BY "links"."confidence" DESC NULLS LAST, "links"."created_at" DESC) FILTER (WHERE ("links"."link_status" = ANY (ARRAY['candidate'::"text", 'approved'::"text", 'linked_in_xero'::"text", 'needs_review'::"text"]))))[1] AS "best_document_id",
            ("array_agg"("docs"."source" ORDER BY "links"."confidence" DESC NULLS LAST, "links"."created_at" DESC) FILTER (WHERE ("links"."link_status" = ANY (ARRAY['candidate'::"text", 'approved'::"text", 'linked_in_xero'::"text", 'needs_review'::"text"]))))[1] AS "best_source",
            ("array_agg"("docs"."vendor_name" ORDER BY "links"."confidence" DESC NULLS LAST, "links"."created_at" DESC) FILTER (WHERE ("links"."link_status" = ANY (ARRAY['candidate'::"text", 'approved'::"text", 'linked_in_xero'::"text", 'needs_review'::"text"]))))[1] AS "best_vendor_name",
            "bool_or"(("links"."link_status" = ANY (ARRAY['approved'::"text", 'linked_in_xero'::"text"]))) AS "has_approved_link",
            "jsonb_agg"("jsonb_build_object"('link_id', "links"."id", 'document_id', "docs"."id", 'source', "docs"."source", 'source_record_id', "docs"."source_record_id", 'source_table', "docs"."source_table", 'vendor_name', "docs"."vendor_name", 'document_number', "docs"."document_number", 'document_date', "docs"."document_date", 'received_at', "docs"."received_at", 'amount_total', "docs"."amount_total", 'tax_amount', "docs"."tax_amount", 'currency_code', "docs"."currency_code", 'attachment_url', "docs"."attachment_url", 'attachment_storage_path', "docs"."attachment_storage_path", 'attachment_filename', "docs"."attachment_filename", 'attachment_content_type', "docs"."attachment_content_type", 'xero_bank_transaction_id', "docs"."xero_bank_transaction_id", 'xero_invoice_id', "docs"."xero_invoice_id", 'status', "docs"."status", 'link_status', "links"."link_status", 'match_method', "links"."match_method", 'confidence', "links"."confidence", 'rank', "links"."rank", 'is_best_candidate', "links"."is_best_candidate", 'vendor_score', "links"."vendor_score", 'amount_score', "links"."amount_score", 'date_score', "links"."date_score", 'amount_delta', "links"."amount_delta", 'date_delta_days', "links"."date_delta_days", 'xero_action', "links"."xero_action", 'review_owner', "links"."review_owner", 'review_note', "links"."review_note", 'provenance', "links"."provenance") ORDER BY "links"."confidence" DESC NULLS LAST, "links"."rank", "links"."created_at" DESC) FILTER (WHERE ("links"."link_status" = ANY (ARRAY['candidate'::"text", 'approved'::"text", 'linked_in_xero'::"text", 'needs_review'::"text"]))) AS "receipt_candidates"
           FROM ("public"."finance_receipt_bank_line_links" "links"
             JOIN "public"."finance_receipt_documents" "docs" ON (("docs"."id" = "links"."receipt_document_id")))
          GROUP BY "links"."bank_line_id"
        )
 SELECT "bsl"."id",
    "bsl"."date",
    "bsl"."type",
    "bsl"."payee",
    "bsl"."particulars",
    "bsl"."reference",
    "bsl"."analysis_code",
    "bsl"."amount",
    "bsl"."direction",
    "bsl"."source",
    "bsl"."status",
    "bsl"."bank_account",
    "bsl"."card_last4",
    "bsl"."matched_xero_transaction_id",
    "bsl"."matched_receipt_email_id",
    "bsl"."project_code",
    "bsl"."project_source",
    "bsl"."rd_eligible",
    "bsl"."notes",
    "bsl"."receipt_match_id",
    "bsl"."receipt_match_score",
    "bsl"."receipt_match_status",
    "bsl"."xero_transaction_id",
    "bsl"."xero_tenant_id",
    "bsl"."lane",
    "bsl"."lcaa_phase",
    COALESCE("cr"."candidate_count", 0) AS "candidate_count",
    "cr"."best_confidence",
    "cr"."best_document_id",
    "cr"."best_source",
    "cr"."best_vendor_name",
    COALESCE("cr"."has_approved_link", false) AS "has_approved_link",
    COALESCE("cr"."receipt_candidates", '[]'::"jsonb") AS "receipt_candidates",
        CASE
            WHEN ("bsl"."receipt_match_status" = 'no_receipt_needed'::"text") THEN 'no_receipt_needed'::"text"
            WHEN ("bsl"."receipt_match_status" = 'matched'::"text") THEN 'covered_legacy'::"text"
            WHEN COALESCE("cr"."has_approved_link", false) THEN 'covered_evidence'::"text"
            WHEN ("bsl"."receipt_match_status" = 'paper_on_file'::"text") THEN 'paper_on_file'::"text"
            WHEN ("bsl"."receipt_match_status" = 'lost'::"text") THEN 'lost'::"text"
            WHEN (COALESCE("cr"."best_confidence", (0)::numeric) >= 0.85) THEN 'high_confidence_candidate'::"text"
            WHEN (COALESCE("cr"."candidate_count", 0) > 0) THEN 'candidate'::"text"
            ELSE 'uncovered'::"text"
        END AS "evidence_status"
   FROM ("public"."bank_statement_lines" "bsl"
     LEFT JOIN "candidate_rollup" "cr" ON (("cr"."bank_line_id" = "bsl"."id")));


ALTER VIEW "public"."v_finance_bank_line_evidence" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_finance_bank_line_evidence" IS 'Bank statement lines with aggregated receipt evidence candidates and coverage status.';



CREATE OR REPLACE VIEW "public"."v_funder_summary" WITH ("security_invoker"='true') AS
 WITH "inv" AS (
         SELECT "xero_invoices"."contact_name" AS "funder_name",
            "count"(*) AS "invoice_count",
            "sum"("xero_invoices"."total") AS "gross_revenue",
            ("sum"("xero_invoices"."total") / 1.1) AS "net_revenue",
            "min"("xero_invoices"."date") AS "first_invoice",
            "max"("xero_invoices"."date") AS "last_invoice",
            (EXTRACT(day FROM ("now"() - (("max"("xero_invoices"."date"))::timestamp without time zone)::timestamp with time zone)))::integer AS "days_since_last",
            ("count"(DISTINCT EXTRACT(year FROM "xero_invoices"."date")))::integer AS "years_active",
            "array_agg"(DISTINCT "xero_invoices"."project_code" ORDER BY "xero_invoices"."project_code") FILTER (WHERE ("xero_invoices"."project_code" IS NOT NULL)) AS "projects",
            "cardinality"("array_agg"(DISTINCT "xero_invoices"."project_code") FILTER (WHERE ("xero_invoices"."project_code" IS NOT NULL))) AS "project_span",
            ("count"(*) FILTER (WHERE ("xero_invoices"."status" = 'AUTHORISED'::"text")))::integer AS "authorised_count",
            COALESCE("sum"("xero_invoices"."amount_due") FILTER (WHERE ("xero_invoices"."status" = 'AUTHORISED'::"text")), (0)::numeric) AS "outstanding",
            ("count"(*) FILTER (WHERE ("xero_invoices"."status" = 'PAID'::"text")))::integer AS "paid_count",
            COALESCE("sum"("xero_invoices"."total") FILTER (WHERE ("xero_invoices"."status" = 'PAID'::"text")), (0)::numeric) AS "paid_revenue"
           FROM "public"."xero_invoices"
          WHERE (("xero_invoices"."type" = 'ACCREC'::"text") AND ("xero_invoices"."status" <> ALL (ARRAY['DELETED'::"text", 'VOIDED'::"text"])))
          GROUP BY "xero_invoices"."contact_name"
        )
 SELECT "funder_name",
    "invoice_count",
    "paid_count",
    "authorised_count",
    "round"("gross_revenue", 0) AS "gross_revenue",
    "round"("net_revenue", 0) AS "net_revenue",
    "round"("paid_revenue", 0) AS "paid_revenue",
    "round"("outstanding", 0) AS "outstanding",
    "first_invoice",
    "last_invoice",
    "days_since_last",
    "years_active",
    "project_span",
    "projects",
    (LEAST((100)::double precision, GREATEST((0)::double precision, (((((LEAST((30)::double precision, ((("ln"(GREATEST("gross_revenue", (1000)::numeric)))::double precision - "ln"((1000)::double precision)) * (4.5)::double precision)) + (GREATEST((0)::numeric, ((25)::numeric - (("days_since_last")::numeric / 14.6))))::double precision) + (LEAST((20)::bigint, ("invoice_count" * 2)))::double precision) + (GREATEST(0, (("years_active" - 1) * 10)))::double precision) + (LEAST(5, (("project_span" - 1) * 3)))::double precision) + (
        CASE
            WHEN ("authorised_count" > 0) THEN 10
            ELSE 0
        END)::double precision))))::integer AS "warmth_score",
        CASE
            WHEN (("gross_revenue" >= (100000)::numeric) AND ("days_since_last" <= 90)) THEN 'HOT'::"text"
            WHEN (("gross_revenue" >= (50000)::numeric) AND ("days_since_last" <= 180)) THEN 'WARM'::"text"
            WHEN ("days_since_last" <= 90) THEN 'STEADY'::"text"
            WHEN ("days_since_last" <= 365) THEN 'COOLING'::"text"
            ELSE 'COLD'::"text"
        END AS "warmth_band"
   FROM "inv" "i";


ALTER VIEW "public"."v_funder_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_funder_next_move" AS
 SELECT "funder_name",
    "invoice_count",
    "paid_count",
    "authorised_count",
    "gross_revenue",
    "net_revenue",
    "paid_revenue",
    "outstanding",
    "first_invoice",
    "last_invoice",
    "days_since_last",
    "years_active",
    "project_span",
    "projects",
    "warmth_score",
    "warmth_band",
        CASE
            WHEN (("outstanding" > (0)::numeric) AND ("days_since_last" <= 30)) THEN (('Chase payment: '::"text" || "to_char"("outstanding", '$FM999,999,999'::"text")) || ' authorised, expect within 14 days'::"text")
            WHEN (("outstanding" > (0)::numeric) AND ("days_since_last" <= 90)) THEN (('Follow up on outstanding '::"text" || "to_char"("outstanding", '$FM999,999,999'::"text")) || ' authorised invoice'::"text")
            WHEN ("outstanding" > (0)::numeric) THEN ('Escalate stale authorised invoice — '::"text" || "to_char"("outstanding", '$FM999,999,999'::"text"))
            WHEN (("warmth_band" = 'HOT'::"text") AND ("years_active" >= 2)) THEN 'Renewal conversation: 2+ year repeat funder'::"text"
            WHEN ("warmth_band" = 'HOT'::"text") THEN 'Active relationship — schedule next-round conversation'::"text"
            WHEN ("warmth_band" = 'WARM'::"text") THEN (('Re-engage: 50K+ funder going quiet ('::"text" || "days_since_last") || 'd)'::"text")
            WHEN ("warmth_band" = 'STEADY'::"text") THEN 'Recent activity — explore partnership extension'::"text"
            WHEN ("warmth_band" = 'COOLING'::"text") THEN (('REVIVE: '::"text" || "days_since_last") || ' days quiet — warm-touch email'::"text")
            WHEN ("warmth_band" = 'COLD'::"text") THEN (('Cold lapse: '::"text" || "days_since_last") || 'd. Revive or close out.'::"text")
            ELSE 'Review'::"text"
        END AS "next_move"
   FROM "public"."v_funder_summary" "f";


ALTER VIEW "public"."v_funder_next_move" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_funders_summary" AS
 SELECT "alma_funding_opportunities"."funder_name",
    "alma_funding_opportunities"."source_type",
    "count"(*) AS "total_opportunities",
    "count"(*) FILTER (WHERE ("alma_funding_opportunities"."status" = ANY (ARRAY['open'::"text", 'closing_soon'::"text"]))) AS "active_opportunities",
    "sum"("alma_funding_opportunities"."total_pool_amount") FILTER (WHERE ("alma_funding_opportunities"."status" = ANY (ARRAY['open'::"text", 'closing_soon'::"text"]))) AS "total_available",
    "avg"("alma_funding_opportunities"."max_grant_amount") AS "avg_max_grant",
    "array_agg"(DISTINCT "unnested_jurisdiction"."unnested_jurisdiction") AS "all_jurisdictions"
   FROM "public"."alma_funding_opportunities",
    LATERAL "unnest"(COALESCE("alma_funding_opportunities"."jurisdictions", ARRAY[]::"text"[])) "unnested_jurisdiction"("unnested_jurisdiction")
  GROUP BY "alma_funding_opportunities"."funder_name", "alma_funding_opportunities"."source_type"
  ORDER BY ("count"(*) FILTER (WHERE ("alma_funding_opportunities"."status" = ANY (ARRAY['open'::"text", 'closing_soon'::"text"])))) DESC, ("sum"("alma_funding_opportunities"."total_pool_amount") FILTER (WHERE ("alma_funding_opportunities"."status" = ANY (ARRAY['open'::"text", 'closing_soon'::"text"])))) DESC NULLS LAST;


ALTER VIEW "public"."v_funders_summary" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_funders_summary" IS 'Summary of funders and their opportunities';



CREATE OR REPLACE VIEW "public"."v_funding_award_community_accountability" AS
 SELECT "fa"."id" AS "funding_award_id",
    "o"."name" AS "organization_name",
    "fp"."name" AS "funding_program_name",
    "fs"."name" AS "funding_source_name",
    "fa"."award_status",
    "fa"."amount_disbursed" AS "tracked_public_spend",
    0 AS "community_validation_count",
    COALESCE("cc"."commitment_count", (0)::bigint) AS "outcome_commitment_count",
    COALESCE("uc"."update_count", (0)::bigint) AS "outcome_update_count",
    "fa"."community_report_due_at",
    "fa"."updated_at"
   FROM ((((("public"."funding_awards" "fa"
     LEFT JOIN "public"."organizations" "o" ON (("o"."id" = "fa"."organization_id")))
     LEFT JOIN "public"."funding_programs" "fp" ON (("fp"."id" = "fa"."funding_program_id")))
     LEFT JOIN "public"."funding_sources" "fs" ON (("fs"."id" = "fp"."funding_source_id")))
     LEFT JOIN ( SELECT "funding_outcome_commitments"."funding_award_id",
            "count"(*) AS "commitment_count"
           FROM "public"."funding_outcome_commitments"
          GROUP BY "funding_outcome_commitments"."funding_award_id") "cc" ON (("cc"."funding_award_id" = "fa"."id")))
     LEFT JOIN ( SELECT "c"."funding_award_id",
            "count"("u"."id") AS "update_count"
           FROM ("public"."funding_outcome_commitments" "c"
             LEFT JOIN "public"."funding_outcome_updates" "u" ON (("u"."commitment_id" = "c"."id")))
          GROUP BY "c"."funding_award_id") "uc" ON (("uc"."funding_award_id" = "fa"."id")));


ALTER VIEW "public"."v_funding_award_community_accountability" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_funding_ingest_health" AS
 WITH "observed" AS (
         SELECT "justice_funding"."source" AS "code",
            "count"(*) AS "record_count",
            "max"("justice_funding"."created_at") AS "last_ingested_at",
            "min"("justice_funding"."financial_year") AS "earliest_financial_year",
            "max"("justice_funding"."financial_year") AS "latest_financial_year"
           FROM "public"."justice_funding"
          GROUP BY "justice_funding"."source"
        )
 SELECT COALESCE("s"."code", "o"."code") AS "code",
    "s"."label",
    "s"."jurisdiction",
    "s"."feed_kind",
    "s"."cadence_days",
    "s"."ingest_method",
    "s"."script_path",
    "s"."automatable",
    "s"."is_active",
    "s"."notes",
    COALESCE("o"."record_count", (0)::bigint) AS "record_count",
    "o"."last_ingested_at",
    "o"."earliest_financial_year",
    "o"."latest_financial_year",
    ("s"."code" IS NULL) AS "unregistered",
    (EXTRACT(day FROM ("now"() - "o"."last_ingested_at")))::integer AS "days_since_ingest",
        CASE
            WHEN ("s"."code" IS NULL) THEN 'unregistered'::"text"
            WHEN (NOT "s"."is_active") THEN 'retired'::"text"
            WHEN ("s"."feed_kind" <> 'recurring'::"text") THEN 'complete'::"text"
            WHEN ("o"."last_ingested_at" IS NULL) THEN 'never_ingested'::"text"
            WHEN (("now"() - "o"."last_ingested_at") > (("s"."cadence_days" || ' days'::"text"))::interval) THEN 'overdue'::"text"
            ELSE 'current'::"text"
        END AS "health"
   FROM ("observed" "o"
     FULL JOIN "public"."funding_ingest_sources" "s" ON (("s"."code" = "o"."code")));


ALTER VIEW "public"."v_funding_ingest_health" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_funding_outcomes_chain" AS
 SELECT "jf"."id" AS "funding_id",
    "jf"."recipient_name",
    "jf"."recipient_abn",
    "jf"."gs_entity_id",
    "ge"."canonical_name" AS "entity_name",
    "jf"."program_name" AS "funding_program",
    "jf"."amount_dollars",
    "jf"."financial_year",
    "jf"."state",
    "jf"."source" AS "funding_source",
    "os"."id" AS "submission_id",
    "os"."program_name" AS "outcomes_program",
    "os"."reporting_period",
    "os"."outcomes" AS "outcomes_data",
    "os"."narrative",
    "os"."methodology",
    "os"."status" AS "submission_status",
    "os"."proof_bundle_id",
    "ai"."id" AS "alma_id",
    "ai"."name" AS "alma_intervention",
    "ai"."type" AS "alma_type",
    "ai"."evidence_level",
    "ai"."cultural_authority",
    "ai"."portfolio_score",
        CASE
            WHEN (("os"."id" IS NOT NULL) AND ("os"."status" = 'validated'::"text")) THEN 'proven'::"text"
            WHEN ("os"."id" IS NOT NULL) THEN 'submitted'::"text"
            WHEN ("ai"."id" IS NOT NULL) THEN 'evidence_exists'::"text"
            ELSE 'no_outcomes'::"text"
        END AS "outcomes_status"
   FROM ((("public"."justice_funding" "jf"
     LEFT JOIN "public"."gs_entities" "ge" ON (("ge"."id" = "jf"."gs_entity_id")))
     LEFT JOIN "public"."outcome_submissions" "os" ON (("os"."gs_entity_id" = "ge"."gs_id")))
     LEFT JOIN "public"."alma_interventions" "ai" ON (("ai"."gs_entity_id" = "jf"."gs_entity_id")))
  WHERE ("jf"."gs_entity_id" IS NOT NULL);


ALTER VIEW "public"."v_funding_outcomes_chain" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_funding_pipeline" AS
 SELECT "id",
    "name",
    "funder_name",
    "source_type",
    "category",
    "total_pool_amount",
    "min_grant_amount",
    "max_grant_amount",
    "deadline",
    "status",
    "jurisdictions",
    "focus_areas",
    "source_url",
    "application_url",
    "relevance_score",
        CASE
            WHEN ("deadline" IS NULL) THEN NULL::integer
            WHEN ("deadline" <= "now"()) THEN 0
            ELSE (EXTRACT(day FROM ("deadline" - "now"())))::integer
        END AS "days_until_deadline",
    ( SELECT "count"(*) AS "count"
           FROM "public"."alma_funding_applications" "fa"
          WHERE ("fa"."opportunity_id" = "fo"."id")) AS "application_count",
    "created_at",
    "updated_at"
   FROM "public"."alma_funding_opportunities" "fo"
  WHERE ("status" <> 'archived'::"text")
  ORDER BY
        CASE "status"
            WHEN 'closing_soon'::"text" THEN 1
            WHEN 'open'::"text" THEN 2
            WHEN 'upcoming'::"text" THEN 3
            ELSE 4
        END, "deadline";


ALTER VIEW "public"."v_funding_pipeline" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_funding_pipeline" IS 'Active funding opportunities with days until deadline';



CREATE OR REPLACE VIEW "public"."v_funding_program_names" AS
 SELECT DISTINCT "program_name",
    "state"
   FROM "public"."justice_funding"
  WHERE (("program_name" IS NOT NULL) AND ("length"(TRIM(BOTH FROM "program_name")) > 3));


ALTER VIEW "public"."v_funding_program_names" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_funding_program_names" IS 'Distinct program_name/state pairs from justice_funding. Exists because PostgREST has no DISTINCT, and pulling 157k rows through a client to deduplicate them is how a script quietly hits the 1000-row cap.';



CREATE OR REPLACE VIEW "public"."v_org_funding_profile" AS
 SELECT "e"."id",
    "e"."gs_id",
    "e"."canonical_name",
    "e"."abn",
    "e"."entity_type",
    "e"."state",
    "e"."lga_name",
    "e"."postcode",
    "e"."lga_source",
    ("e"."is_community_controlled" OR ("e"."entity_type" = 'indigenous_corp'::"text")) AS "community_controlled",
    "e"."oric_status",
    "e"."oric_sector",
    "e"."oric_size",
    "e"."oric_income_band",
    "e"."oric_employee_band",
    COALESCE("c"."n", (0)::bigint) AS "contract_count",
    COALESCE("c"."v", (0)::numeric) AS "contract_value",
    COALESCE("gr"."n", (0)::bigint) AS "grants_received_count",
    COALESCE("gr"."v", (0)::numeric) AS "grants_received_value",
    COALESCE("gd"."n", (0)::bigint) AS "grants_delivered_here_count",
    COALESCE("gd"."v", (0)::numeric) AS "grants_delivered_here_value",
    COALESCE("jf"."n", (0)::bigint) AS "other_govt_grant_count",
    COALESCE("jf"."v", (0)::numeric) AS "other_govt_grant_value",
    COALESCE("ph"."n", (0)::bigint) AS "philanthropic_grant_count",
    ((COALESCE("c"."v", (0)::numeric) + COALESCE("gr"."v", (0)::numeric)) + COALESCE("jf"."v", (0)::numeric)) AS "total_traceable_value"
   FROM ((((("public"."gs_entities" "e"
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "n",
            "sum"("ac"."contract_value") AS "v"
           FROM "public"."austender_contracts" "ac"
          WHERE (("e"."abn" IS NOT NULL) AND ("ac"."supplier_abn" = "e"."abn") AND (("ac"."contract_start" IS NULL) OR ("ac"."contract_start" >= '2000-01-01'::"date")))) "c" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "n",
            "sum"("ga"."value_aud") AS "v"
           FROM "public"."grantconnect_awards" "ga"
          WHERE ("ga"."gs_entity_id" = "e"."id")) "gr" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "n",
            "sum"("ga"."value_aud") AS "v"
           FROM "public"."grantconnect_awards" "ga"
          WHERE (("e"."postcode" IS NOT NULL) AND ("ga"."delivery_postcode" = "e"."postcode"))) "gd" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "n",
            "sum"("j"."amount_dollars") AS "v"
           FROM "public"."justice_funding" "j"
          WHERE ("j"."gs_entity_id" = "e"."id")) "jf" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "n"
           FROM "public"."mv_foundation_grantees" "fg"
          WHERE ("fg"."grantee_entity_id" = "e"."id")) "ph" ON (true));


ALTER VIEW "public"."v_org_funding_profile" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_org_funding_profile" IS 'One row per organisation with each funding channel kept separate. Contracts are by registered address; grants_received is what an organisation holds; grants_delivered_here is what is spent in its postcode by anyone. Zero money with an ORIC income band means unmatchable, not inactive.';



CREATE OR REPLACE VIEW "public"."v_goods_central_channels" AS
 SELECT "p"."id" AS "entity_id",
    "p"."canonical_name",
    "p"."abn",
    "p"."lga_name",
    "p"."oric_size",
    "p"."oric_employee_band",
    "p"."total_traceable_value",
        CASE
            WHEN ("p"."canonical_name" ~* 'health|congress|medical'::"text") THEN 'health_service'::"text"
            WHEN ("p"."canonical_name" ~* 'women'::"text") THEN 'womens_council'::"text"
            WHEN ("p"."canonical_name" ~* 'store|wiru'::"text") THEN 'community_store'::"text"
            WHEN ("p"."canonical_name" ~* 'outstation|resource|homelands|services|housing|tangentyere'::"text") THEN 'housing_logistics'::"text"
            WHEN ("p"."canonical_name" ~* 'land council'::"text") THEN 'land_council'::"text"
            ELSE 'other'::"text"
        END AS "channel_archetype",
    "g"."id" AS "goods_relationship_id",
    "g"."relationship_type",
    "g"."stage",
    "g"."warmth_display",
    "g"."next_action"
   FROM ("public"."v_org_funding_profile" "p"
     LEFT JOIN "public"."goods_relationships" "g" ON ((("g"."entity_id" = "p"."id") OR ("lower"("g"."display_name") = "lower"("p"."canonical_name")))))
  WHERE (("p"."lga_name" = ANY (ARRAY['Alice Springs'::"text", 'MacDonnell'::"text", 'Central Desert'::"text", 'Barkly'::"text"])) AND ("p"."community_controlled" = true))
  ORDER BY "p"."total_traceable_value" DESC NULLS LAST;


ALTER VIEW "public"."v_goods_central_channels" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_goods_community_priority" AS
 WITH "seifa" AS (
         SELECT "seifa_2021"."postcode",
            "min"("seifa_2021"."decile_national") AS "irsd_decile"
           FROM "public"."seifa_2021"
          WHERE (("upper"("seifa_2021"."index_type") = 'IRSD'::"text") AND ("seifa_2021"."decile_national" IS NOT NULL))
          GROUP BY "seifa_2021"."postcode"
        )
 SELECT "gc"."id" AS "community_id",
    "gc"."community_name",
    "gc"."state",
    "gc"."postcode",
    "s"."irsd_decile" AS "seifa_irsd_decile",
    ("s"."irsd_decile" IS NOT NULL) AS "seifa_available",
        CASE
            WHEN ("s"."irsd_decile" IS NULL) THEN NULL::integer
            ELSE ("round"((((10 - "s"."irsd_decile"))::numeric * (100.0 / 9.0))))::integer
        END AS "disadvantage_score",
    COALESCE("gc"."demand_beds", 0) AS "demand_beds",
    COALESCE("gc"."assets_deployed", 0) AS "assets_deployed",
    GREATEST((COALESCE("gc"."demand_beds", 0) - COALESCE("gc"."assets_deployed", 0)), 0) AS "unmet_beds",
    COALESCE("gc"."indigenous_population_pct", (0)::numeric) AS "indigenous_population_pct",
    "round"(((GREATEST((COALESCE("gc"."demand_beds", 0) - COALESCE("gc"."assets_deployed", 0)), 0))::numeric * ((1)::numeric + COALESCE((((10 - "s"."irsd_decile"))::numeric / 9.0), (0)::numeric))), 1) AS "serve_next_score"
   FROM ("public"."goods_communities" "gc"
     LEFT JOIN "seifa" "s" ON (("s"."postcode" = "gc"."postcode")));


ALTER VIEW "public"."v_goods_community_priority" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_goods_community_priority" IS 'SEIFA 2021 IRSD disadvantage (postcode-joined, decile 1=most disadvantaged) overlaid on goods_communities, with serve_next_score = unmet bed demand amplified up to 2x by disadvantage. Read by goods-communities-hub.ts.';



CREATE OR REPLACE VIEW "public"."v_goods_foundation_targets" AS
 WITH "themes" AS (
         SELECT ARRAY['indigenous'::"text", 'aboriginal'::"text", 'rural_remote'::"text", 'social-enterprise'::"text", 'housing'::"text", 'employment'::"text", 'economic_development'::"text", 'regenerative'::"text", 'agriculture'::"text"] AS "arr"
        ), "goods_rel" AS (
         SELECT DISTINCT "goods_relationships"."entity_id",
            "goods_relationships"."display_name",
            "goods_relationships"."warmth_display" AS "warmth"
           FROM "public"."goods_relationships"
          WHERE ("goods_relationships"."entity_id" IS NOT NULL)
        ), "goods_ent" AS (
         SELECT DISTINCT "goods_rel"."entity_id"
           FROM "goods_rel"
        ), "goods_people" AS (
         SELECT DISTINCT ON ("pen"."person_name_normalised") "pen"."person_name_normalised",
            "pen"."person_name_display",
            "gr"."display_name" AS "goods_org",
            "gr"."warmth"
           FROM ("public"."mv_person_entity_network" "pen"
             JOIN "goods_rel" "gr" ON (("gr"."entity_id" = "pen"."entity_id")))
          WHERE (("pen"."board_count" >= 2) AND ("pen"."board_count" <= 15))
          ORDER BY "pen"."person_name_normalised", "gr"."warmth" DESC
        ), "bridge" AS (
         SELECT DISTINCT ON ("pen"."entity_id") "pen"."entity_id" AS "cand_entity",
            "gp"."person_name_display" AS "connector",
            "gp"."goods_org" AS "bridged_org",
            "gp"."warmth" AS "bridged_warmth"
           FROM ("public"."mv_person_entity_network" "pen"
             JOIN "goods_people" "gp" ON (("gp"."person_name_normalised" = "pen"."person_name_normalised")))
          WHERE (("pen"."board_count" >= 2) AND ("pen"."board_count" <= 15))
          ORDER BY "pen"."entity_id", "gp"."warmth" DESC
        ), "cand" AS (
         SELECT "f"."id",
            "f"."name",
            "f"."gs_entity_id",
            "f"."total_giving_annual",
            "f"."avg_grant_size",
            "f"."grant_range_min",
            "f"."grant_range_max",
            "f"."has_dgr",
            "f"."geographic_focus",
            "cardinality"(ARRAY( SELECT "unnest"("f"."thematic_focus") AS "unnest"
                INTERSECT
                 SELECT "unnest"(( SELECT "themes"."arr"
                           FROM "themes")) AS "unnest")) AS "theme_hits",
            ARRAY( SELECT "unnest"("f"."thematic_focus") AS "unnest"
                INTERSECT
                 SELECT "unnest"(( SELECT "themes"."arr"
                           FROM "themes")) AS "unnest") AS "matched_themes"
           FROM "public"."foundations" "f"
          WHERE (("f"."thematic_focus" && ( SELECT "themes"."arr"
                   FROM "themes")) AND ("f"."gs_entity_id" IS NOT NULL) AND (NOT ("f"."gs_entity_id" IN ( SELECT "goods_ent"."entity_id"
                   FROM "goods_ent"))))
        )
 SELECT "c"."id",
    "c"."name",
    "c"."gs_entity_id",
    "c"."total_giving_annual",
    "c"."avg_grant_size",
    "c"."grant_range_min",
    "c"."grant_range_max",
    "c"."has_dgr",
    "c"."theme_hits",
    "c"."matched_themes",
    "c"."geographic_focus",
    "b"."connector",
    "b"."bridged_org",
    "b"."bridged_warmth",
    ("b"."connector" IS NOT NULL) AS "has_bridge",
    ("round"(((((
        CASE
            WHEN ("b"."connector" IS NOT NULL) THEN 1000
            ELSE 0
        END + ("c"."theme_hits" * 100)) +
        CASE
            WHEN "c"."has_dgr" THEN 50
            ELSE 0
        END))::numeric + LEAST((50)::numeric, ((COALESCE("c"."total_giving_annual", (0)::numeric) / 1000000.0) * (10)::numeric)))))::integer AS "priority_score"
   FROM ("cand" "c"
     LEFT JOIN "bridge" "b" ON (("b"."cand_entity" = "c"."gs_entity_id")));


ALTER VIEW "public"."v_goods_foundation_targets" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_goods_life_events" AS
 WITH "supporters" AS (
         SELECT "gr"."id" AS "rel_id",
            "gr"."display_name",
            "gr"."relationship_type",
            "gr"."warmth_display",
            "e"."abn"
           FROM ("public"."goods_relationships" "gr"
             JOIN "public"."gs_entities" "e" ON (("e"."id" = "gr"."entity_id")))
          WHERE (("gr"."entity_id" IS NOT NULL) AND ("e"."abn" IS NOT NULL))
        ), "acnc" AS (
         SELECT "s"."rel_id",
            "s"."display_name",
            "s"."relationship_type",
            "s"."warmth_display",
            'acnc_filing'::"text" AS "kind",
            "a"."date_ais_received" AS "event_date",
            ("a"."ais_year")::"text" AS "event_fy",
            "a"."total_revenue" AS "amount",
            "a"."revenue_from_government" AS "amount2",
            "a"."fin_report_to" AS "period_to",
            NULL::"text" AS "label"
           FROM ("supporters" "s"
             JOIN LATERAL ( SELECT "m"."date_ais_received",
                    "m"."ais_year",
                    "m"."total_revenue",
                    "m"."revenue_from_government",
                    "m"."fin_report_to"
                   FROM "public"."mv_acnc_latest" "m"
                  WHERE ("m"."abn" = "s"."abn")
                  ORDER BY "m"."date_ais_received" DESC NULLS LAST
                 LIMIT 1) "a" ON (true))
          WHERE ("a"."date_ais_received" IS NOT NULL)
        ), "contracts" AS (
         SELECT "s"."rel_id",
            "s"."display_name",
            "s"."relationship_type",
            "s"."warmth_display",
            'gov_contract'::"text" AS "kind",
            "c"."contract_start" AS "event_date",
            NULL::"text" AS "event_fy",
            "c"."contract_value" AS "amount",
            NULL::numeric AS "amount2",
            "c"."contract_end" AS "period_to",
            "c"."buyer_name" AS "label"
           FROM ("supporters" "s"
             JOIN LATERAL ( SELECT "ac"."contract_start",
                    "ac"."contract_value",
                    "ac"."contract_end",
                    "ac"."buyer_name"
                   FROM "public"."austender_contracts" "ac"
                  WHERE ("ac"."supplier_abn" = "s"."abn")
                  ORDER BY "ac"."contract_start" DESC NULLS LAST
                 LIMIT 1) "c" ON (true))
          WHERE ("c"."contract_start" IS NOT NULL)
        ), "justice" AS (
         SELECT "s"."rel_id",
            "s"."display_name",
            "s"."relationship_type",
            "s"."warmth_display",
            'justice_funding'::"text" AS "kind",
            NULL::"date" AS "event_date",
            "j"."financial_year" AS "event_fy",
            "j"."amount",
            NULL::numeric AS "amount2",
            NULL::"date" AS "period_to",
            "j"."program_name" AS "label"
           FROM ("supporters" "s"
             JOIN LATERAL ( SELECT "jf"."financial_year",
                    "sum"("jf"."amount_dollars") AS "amount",
                    "max"("jf"."program_name") AS "program_name"
                   FROM "public"."justice_funding" "jf"
                  WHERE (("jf"."recipient_abn" = "s"."abn") AND ("jf"."financial_year" IS NOT NULL))
                  GROUP BY "jf"."financial_year"
                  ORDER BY "jf"."financial_year" DESC
                 LIMIT 1) "j" ON (true))
        )
 SELECT "acnc"."rel_id",
    "acnc"."display_name",
    "acnc"."relationship_type",
    "acnc"."warmth_display",
    "acnc"."kind",
    "acnc"."event_date",
    "acnc"."event_fy",
    "acnc"."amount",
    "acnc"."amount2",
    "acnc"."period_to",
    "acnc"."label"
   FROM "acnc"
UNION ALL
 SELECT "contracts"."rel_id",
    "contracts"."display_name",
    "contracts"."relationship_type",
    "contracts"."warmth_display",
    "contracts"."kind",
    "contracts"."event_date",
    "contracts"."event_fy",
    "contracts"."amount",
    "contracts"."amount2",
    "contracts"."period_to",
    "contracts"."label"
   FROM "contracts"
UNION ALL
 SELECT "justice"."rel_id",
    "justice"."display_name",
    "justice"."relationship_type",
    "justice"."warmth_display",
    "justice"."kind",
    "justice"."event_date",
    "justice"."event_fy",
    "justice"."amount",
    "justice"."amount2",
    "justice"."period_to",
    "justice"."label"
   FROM "justice";


ALTER VIEW "public"."v_goods_life_events" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_goods_life_events" IS 'Goods: most-recent public-record event per entity-linked supporter (ACNC filing, gov contract, justice funding) as "reasons to reach out". Ranking + copy in goods-life-events-shared.ts.';



CREATE OR REPLACE VIEW "public"."v_goods_relationship_funding" AS
 WITH "ent" AS (
         SELECT "gr"."id" AS "rel_id",
            "gr"."entity_id",
            "gr"."display_name",
            "gr"."relationship_type",
            COALESCE("gr"."warmth_display", 0) AS "warmth_display",
            NULLIF("e"."abn", ''::"text") AS "abn"
           FROM ("public"."goods_relationships" "gr"
             JOIN "public"."gs_entities" "e" ON (("e"."id" = "gr"."entity_id")))
          WHERE ("gr"."entity_id" IS NOT NULL)
        ), "fnd" AS (
         SELECT DISTINCT ON ("f"."gs_entity_id") "f"."gs_entity_id" AS "entity_id",
            "f"."total_giving_annual" AS "foundation_giving_annual",
            "f"."avg_grant_size" AS "foundation_avg_grant",
            "f"."thematic_focus" AS "foundation_themes",
            "f"."geographic_focus" AS "foundation_geo"
           FROM "public"."foundations" "f"
          WHERE (("f"."gs_entity_id" IS NOT NULL) AND ("f"."gs_entity_id" IN ( SELECT "ent_1"."entity_id"
                   FROM "ent" "ent_1")))
          ORDER BY "f"."gs_entity_id", "f"."total_giving_annual" DESC NULLS LAST
        ), "pol" AS (
         SELECT "political_donations"."donor_abn" AS "abn",
            "sum"("political_donations"."amount") AS "political_total",
            "count"(*) AS "political_count",
            "max"("political_donations"."financial_year") AS "political_latest_fy"
           FROM "public"."political_donations"
          WHERE (("political_donations"."donor_abn" IS NOT NULL) AND ("political_donations"."donor_abn" <> ''::"text") AND ("political_donations"."donor_abn" IN ( SELECT "ent_1"."abn"
                   FROM "ent" "ent_1"
                  WHERE ("ent_1"."abn" IS NOT NULL))))
          GROUP BY "political_donations"."donor_abn"
        ), "jf" AS (
         SELECT "justice_funding"."gs_entity_id" AS "entity_id",
            "sum"("justice_funding"."amount_dollars") AS "justice_total",
            "count"(DISTINCT "justice_funding"."program_name") AS "justice_program_count",
            "max"("justice_funding"."financial_year") AS "justice_latest_fy"
           FROM "public"."justice_funding"
          WHERE (("justice_funding"."gs_entity_id" IS NOT NULL) AND ("justice_funding"."gs_entity_id" IN ( SELECT "ent_1"."entity_id"
                   FROM "ent" "ent_1")))
          GROUP BY "justice_funding"."gs_entity_id"
        ), "aus" AS (
         SELECT "austender_contracts"."supplier_abn" AS "abn",
            "sum"("austender_contracts"."contract_value") AS "austender_total",
            "count"(*) AS "austender_contract_count",
            "max"("austender_contracts"."contract_start") AS "austender_latest"
           FROM "public"."austender_contracts"
          WHERE (("austender_contracts"."supplier_abn" IS NOT NULL) AND ("austender_contracts"."supplier_abn" <> ''::"text") AND ("austender_contracts"."supplier_abn" IN ( SELECT "ent_1"."abn"
                   FROM "ent" "ent_1"
                  WHERE ("ent_1"."abn" IS NOT NULL))))
          GROUP BY "austender_contracts"."supplier_abn"
        )
 SELECT "ent"."rel_id",
    "ent"."entity_id",
    "ent"."display_name",
    "ent"."relationship_type",
    "ent"."warmth_display",
    "ent"."abn",
    "fnd"."foundation_giving_annual",
    "fnd"."foundation_avg_grant",
    "fnd"."foundation_themes",
    "fnd"."foundation_geo",
    "pol"."political_total",
    "pol"."political_count",
    "pol"."political_latest_fy",
    "jf"."justice_total",
    "jf"."justice_program_count",
    "jf"."justice_latest_fy",
    "aus"."austender_total",
    "aus"."austender_contract_count",
    "aus"."austender_latest",
    (COALESCE("fnd"."foundation_giving_annual", (0)::numeric) + COALESCE("pol"."political_total", (0)::numeric)) AS "gives_total",
    (COALESCE("jf"."justice_total", (0)::numeric) + COALESCE("aus"."austender_total", (0)::numeric)) AS "receives_total"
   FROM (((("ent"
     LEFT JOIN "fnd" ON (("fnd"."entity_id" = "ent"."entity_id")))
     LEFT JOIN "jf" ON (("jf"."entity_id" = "ent"."entity_id")))
     LEFT JOIN "pol" ON (("pol"."abn" = "ent"."abn")))
     LEFT JOIN "aus" ON (("aus"."abn" = "ent"."abn")))
  WHERE (("fnd"."entity_id" IS NOT NULL) OR ("jf"."entity_id" IS NOT NULL) OR ("pol"."abn" IS NOT NULL) OR ("aus"."abn" IS NOT NULL));


ALTER VIEW "public"."v_goods_relationship_funding" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_goods_relationship_funding" IS 'Funder funding-history overlay on Goods relationships: MONEY OUT (foundations.total_giving_annual grantmaking + political_donations donor giving) and MONEY IN (justice_funding + austender_contracts received), each pre-aggregated per entity (semi-joined to the Goods relationship spine for speed) and joined on entity_id/abn. Only rows with a funding signal. Read by goods-relationship-funding.ts.';



CREATE OR REPLACE VIEW "public"."v_goods_relationship_power" AS
 SELECT "gr"."id" AS "rel_id",
    "gr"."entity_id",
    "gr"."display_name",
    "gr"."relationship_type",
    COALESCE("gr"."warmth_display", 0) AS "warmth_display",
    "pi"."power_score",
    "pi"."system_count",
    "pi"."in_procurement",
    "pi"."in_recorded_grants" AS "in_justice_funding",
    "pi"."in_political_donations",
    "pi"."in_charity_registry",
    "pi"."in_foundation",
    "pi"."in_alma_evidence",
    "pi"."in_ato_transparency",
    "pi"."total_dollar_flow",
    "pi"."foundation_giving",
    "rd"."influence_vectors",
    "rd"."revolving_door_score",
    "rd"."lobbies",
    "rd"."donates",
    "rd"."contracts",
    "rd"."receives_funding"
   FROM (("public"."goods_relationships" "gr"
     LEFT JOIN "public"."mv_entity_power_index" "pi" ON (("pi"."id" = "gr"."entity_id")))
     LEFT JOIN "public"."mv_revolving_door" "rd" ON (("rd"."id" = "gr"."entity_id")))
  WHERE (("gr"."entity_id" IS NOT NULL) AND (("pi"."id" IS NOT NULL) OR ("rd"."id" IS NOT NULL)));


ALTER VIEW "public"."v_goods_relationship_power" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_goods_warm_intros" AS
 WITH "goods" AS (
         SELECT "gr"."id" AS "rel_id",
            "gr"."entity_id",
            "gr"."display_name",
            "gr"."relationship_type",
            "gr"."warmth_display"
           FROM "public"."goods_relationships" "gr"
          WHERE ("gr"."entity_id" IS NOT NULL)
        ), "conn" AS (
         SELECT "g"."rel_id",
            "g"."display_name" AS "target_name",
            "g"."relationship_type",
            "g"."warmth_display",
            "bi"."person_name_display" AS "person",
            "pen"."role_type",
            "bi"."board_count",
            "bi"."interlock_score",
            "bi"."connects_community_controlled",
            "bi"."organisations",
            "bi"."entity_ids"
           FROM (("goods" "g"
             JOIN "public"."mv_person_entity_network" "pen" ON (("pen"."entity_id" = "g"."entity_id")))
             JOIN "public"."mv_board_interlocks" "bi" ON (("bi"."person_name_normalised" = "pen"."person_name_normalised")))
          WHERE (("bi"."board_count" >= 2) AND ("bi"."board_count" <= 15))
        )
 SELECT "rel_id",
    "target_name",
    "relationship_type",
    "warmth_display",
    "person",
    "role_type",
    "board_count",
    "interlock_score",
    "connects_community_controlled",
    ( SELECT "array_agg"("s"."o") AS "array_agg"
           FROM ( SELECT DISTINCT "o"."o"
                   FROM "unnest"("c"."organisations") "o"("o")
                  WHERE ("o"."o" IS DISTINCT FROM "c"."target_name")
                  ORDER BY "o"."o"
                 LIMIT 4) "s") AS "other_orgs",
    ( SELECT "g2"."display_name"
           FROM "goods" "g2"
          WHERE (("g2"."entity_id" = ANY ("c"."entity_ids")) AND ("g2"."rel_id" <> "c"."rel_id"))
          ORDER BY "g2"."warmth_display" DESC
         LIMIT 1) AS "bridges_to_goods"
   FROM "conn" "c";


