CREATE OR REPLACE VIEW "public"."v_grant_place_capture" AS
 WITH "pc" AS (
         SELECT "g"."postcode",
            "min"("g"."lga_name") AS "lga_name",
            "min"("g"."state") AS "state",
            "min"("g"."remoteness_2021") AS "remoteness"
           FROM "public"."postcode_geo" "g"
          WHERE (("g"."lga_name" IS NOT NULL) AND (("g"."locality" !~~ '% - %'::"text") OR (EXISTS ( SELECT 1
                   FROM "public"."abs_poa_lga_ratio" "r_1"
                  WHERE ("r_1"."poa_code" = "g"."postcode")))))
          GROUP BY "g"."postcode"
         HAVING ("count"(DISTINCT "g"."lga_name") = 1)
        ), "base" AS (
         SELECT "grantconnect_awards"."ga_id",
            "grantconnect_awards"."parent_ga_id",
            "grantconnect_awards"."agency",
            "grantconnect_awards"."category",
            "grantconnect_awards"."go_id",
            "grantconnect_awards"."go_title",
            "grantconnect_awards"."recipient_name",
            "grantconnect_awards"."recipient_abn",
            "grantconnect_awards"."recipient_id",
            "grantconnect_awards"."pbs_program",
            "grantconnect_awards"."status",
            "grantconnect_awards"."value_aud",
            "grantconnect_awards"."variation_value_aud",
            "grantconnect_awards"."variation_reason",
            "grantconnect_awards"."approval_date",
            "grantconnect_awards"."start_date",
            "grantconnect_awards"."end_date",
            "grantconnect_awards"."publish_date",
            "grantconnect_awards"."variation_date",
            "grantconnect_awards"."selection_process",
            "grantconnect_awards"."description",
            "grantconnect_awards"."state",
            "grantconnect_awards"."gs_entity_id",
            "grantconnect_awards"."imported_at",
            "grantconnect_awards"."recipient_suburb",
            "grantconnect_awards"."recipient_town_city",
            "grantconnect_awards"."recipient_postcode",
            "grantconnect_awards"."recipient_state",
            "grantconnect_awards"."delivery_state",
            "grantconnect_awards"."delivery_postcode",
            "grantconnect_awards"."grant_program",
            "grantconnect_awards"."grant_activity",
            "grantconnect_awards"."purpose"
           FROM "public"."grantconnect_awards"
          WHERE (("grantconnect_awards"."delivery_postcode" IS NOT NULL) AND ("grantconnect_awards"."recipient_postcode" IS NOT NULL) AND ("grantconnect_awards"."delivery_postcode" <> 'Multiple'::"text") AND ("grantconnect_awards"."value_aud" > (0)::numeric) AND ("lower"(TRIM(BOTH FROM "grantconnect_awards"."recipient_name")) <> ALL (ARRAY['total'::"text", 'totals'::"text", 'various'::"text", 'n/a'::"text", 'na'::"text", 'unknown'::"text", 'other'::"text"])))
        )
 SELECT "b"."ga_id",
    "b"."value_aud",
    "b"."recipient_name",
    "b"."recipient_abn",
    "b"."approval_date",
    "d"."lga_name" AS "delivery_lga",
    "d"."state" AS "delivery_state",
    "d"."remoteness" AS "delivery_remoteness",
    "r"."lga_name" AS "recipient_lga",
    "r"."state" AS "recipient_state",
    ("d"."lga_name" = "r"."lga_name") AS "captured_locally"
   FROM (("base" "b"
     JOIN "pc" "d" ON (("d"."postcode" = "b"."delivery_postcode")))
     LEFT JOIN "pc" "r" ON (("r"."postcode" = "b"."recipient_postcode")));


ALTER VIEW "public"."v_grant_place_capture" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_grant_place_capture" IS 'Grant awards where both delivery and recipient location resolve to a single, trustworthy LGA. 110,267 of 291,264 awards ($42.37bn of $230bn) after the #301 postcode_geo repair widened it from 85,898 / $33.75bn. captured_locally = the receiving org sits in the LGA the work was delivered into. Four exclusions apply, documented in migrations/2026-08-19-grant-place-capture.sql and narrowed in migrations/2026-08-20-grant-place-capture-narrow-sa3.sql. Do not widen them without re-reading both headers.';



