     LEFT JOIN "public"."foundations" "f" ON (("lower"("go"."provider") = "lower"("f"."name"))))
  WHERE ("go"."provider" IS NOT NULL)
  GROUP BY "go"."provider", "f"."name", "f"."total_giving_annual"
