CREATE OR REPLACE VIEW "public"."v_grant_readiness" WITH ("security_invoker"='true') AS
 SELECT "ga"."id" AS "application_id",
    "go"."name" AS "grant_name",
    "go"."provider",
    "go"."fit_score",
    "go"."amount_max",
    "go"."closes_at",
    "ga"."status" AS "application_status",
    "ga"."lead_contact",
    "ga"."assigned_to",
    "ga"."priority",
    COALESCE("req"."total_requirements", (0)::bigint) AS "total_requirements",
    COALESCE("req"."ready_count", (0)::bigint) AS "ready_count",
    COALESCE("req"."needed_count", (0)::bigint) AS "needed_count",
        CASE
            WHEN (COALESCE("req"."total_requirements", (0)::bigint) = 0) THEN (0)::numeric
            ELSE "round"((((COALESCE("req"."ready_count", (0)::bigint))::numeric / ("req"."total_requirements")::numeric) * (100)::numeric))
        END AS "readiness_pct"
   FROM (("public"."grant_applications" "ga"
     JOIN "public"."grant_opportunities" "go" ON (("ga"."opportunity_id" = "go"."id")))
     LEFT JOIN ( SELECT "grant_application_requirements"."application_id",
            "count"(*) AS "total_requirements",
            "count"(*) FILTER (WHERE (("grant_application_requirements"."status" = 'ready'::"text") OR ("grant_application_requirements"."status" = 'submitted'::"text"))) AS "ready_count",
            "count"(*) FILTER (WHERE ("grant_application_requirements"."status" = 'needed'::"text")) AS "needed_count"
           FROM "public"."grant_application_requirements"
          GROUP BY "grant_application_requirements"."application_id") "req" ON (("req"."application_id" = "ga"."id")))
  WHERE ("ga"."status" <> ALL (ARRAY['withdrawn'::"text", 'unsuccessful'::"text"]))
  ORDER BY "go"."closes_at";


