CREATE OR REPLACE VIEW "public"."v_index_cost_ranking" AS
 SELECT "t"."relname" AS "table_name",
    "i"."relname" AS "index_name",
    "am"."amname" AS "method",
    "pg_relation_size"(("i"."oid")::"regclass") AS "bytes",
    "pg_size_pretty"("pg_relation_size"(("i"."oid")::"regclass")) AS "size",
    "s"."idx_scan",
    ("pg_relation_size"(("i"."oid")::"regclass") / GREATEST("s"."idx_scan", (1)::bigint)) AS "bytes_per_scan",
    ("x"."indisunique" OR "x"."indisprimary") AS "is_constraint",
    COALESCE("o"."owner", 'unknown'::"text") AS "table_owner",
    COALESCE("o"."consumers", ARRAY['unclassified'::"text"]) AS "consumers",
    ("o"."object" IS NULL) AS "ownership_undeclared",
    (("o"."object" IS NOT NULL) AND ("o"."consumers" = ARRAY['justicehub'::"text"])) AS "justicehub_alone"
   FROM ((((("pg_stat_user_indexes" "s"
     JOIN "pg_class" "i" ON (("i"."oid" = "s"."indexrelid")))
     JOIN "pg_class" "t" ON (("t"."oid" = "s"."relid")))
     JOIN "pg_index" "x" ON (("x"."indexrelid" = "i"."oid")))
     JOIN "pg_am" "am" ON (("am"."oid" = "i"."relam")))
     LEFT JOIN "public"."schema_ownership" "o" ON (("o"."object" = "t"."relname")));


ALTER VIEW "public"."v_index_cost_ranking" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_index_cost_ranking" IS 'Indexes ranked by bytes_per_scan (bytes / greatest(idx_scan,1)) with the owner of their table joined in. Never-scanned and barely-scanned rank together on purpose: idx_scan = 0 is a cliff that hid the largest index in this database. Check justicehub_alone before proposing any drop. GH #465.';



