CREATE OR REPLACE VIEW "public"."v_llm_spend_monthly" AS
 SELECT "date_trunc"('month'::"text", "u"."created_at") AS "month",
    "u"."provider",
    "u"."model",
    "count"(*) AS "calls",
    "count"(*) FILTER (WHERE ("p"."input_price_per_1m" IS NULL)) AS "unpriced_calls",
    "sum"("u"."input_tokens") AS "input_tokens",
    "sum"("u"."output_tokens") AS "output_tokens",
    "round"("sum"((((("u"."input_tokens")::numeric / 1000000.0) * "p"."input_price_per_1m") + ((("u"."output_tokens")::numeric / 1000000.0) * "p"."output_price_per_1m"))), 4) AS "priced_cost_usd"
   FROM ("public"."llm_usage" "u"
     LEFT JOIN "public"."api_pricing" "p" ON ((("p"."provider" = "u"."provider") AND ("p"."model" = "u"."model") AND ("p"."endpoint" = COALESCE("u"."endpoint", 'chat'::"text")) AND ("p"."effective_from" <= ("u"."created_at")::"date") AND (("p"."effective_until" IS NULL) OR ("p"."effective_until" > ("u"."created_at")::"date")))))
  GROUP BY ("date_trunc"('month'::"text", "u"."created_at")), "u"."provider", "u"."model";


ALTER VIEW "public"."v_llm_spend_monthly" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_llm_spend_monthly" IS 'Monthly model spend per provider/model. priced_cost_usd is NULL or partial when unpriced_calls > 0: check that column before quoting the cost. GH #450.';



