  ORDER BY ("date_trunc"('month'::"text", ("date")::timestamp with time zone)) DESC, "project_code";


ALTER VIEW "public"."v_monthly_revenue" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_mv_dependency_edges" AS
 WITH RECURSIVE "raw" AS (
         SELECT DISTINCT "dep"."oid" AS "dependent",
            "dep"."relkind" AS "dep_kind",
            "src"."oid" AS "source",
            "src"."relkind" AS "src_kind"
           FROM ((((("pg_depend" "d"
             JOIN "pg_rewrite" "r" ON ((("r"."oid" = "d"."objid") AND ("d"."classid" = ('"pg_rewrite"'::"regclass")::"oid"))))
             JOIN "pg_class" "dep" ON (("dep"."oid" = "r"."ev_class")))
             JOIN "pg_class" "src" ON ((("src"."oid" = "d"."refobjid") AND ("d"."refclassid" = ('"pg_class"'::"regclass")::"oid"))))
             JOIN "pg_namespace" "nd" ON (("nd"."oid" = "dep"."relnamespace")))
             JOIN "pg_namespace" "ns" ON (("ns"."oid" = "src"."relnamespace")))
          WHERE (("dep"."oid" <> "src"."oid") AND ("nd"."nspname" = 'public'::"name") AND ("ns"."nspname" = 'public'::"name") AND ("dep"."relkind" = ANY (ARRAY['m'::"char", 'v'::"char"])) AND ("src"."relkind" = ANY (ARRAY['m'::"char", 'v'::"char"])))
        ), "reach"("root", "cur", "cur_kind", "hops") AS (
         SELECT "r"."dependent",
            "r"."source",
            "r"."src_kind",
            1 AS "?column?"
           FROM "raw" "r"
          WHERE ("r"."dep_kind" = 'm'::"char")
        UNION
         SELECT "rc"."root",
            "r2"."source",
            "r2"."src_kind",
            ("rc"."hops" + 1)
           FROM ("reach" "rc"
             JOIN "raw" "r2" ON (("r2"."dependent" = "rc"."cur")))
          WHERE (("rc"."cur_kind" = 'v'::"char") AND ("rc"."hops" < 16))
        )
 SELECT DISTINCT (("root")::"regclass")::"text" AS "mv_name",
    (("cur")::"regclass")::"text" AS "depends_on"
   FROM "reach"
  WHERE (("cur_kind" = 'm'::"char") AND ("root" <> "cur"));


ALTER VIEW "public"."v_mv_dependency_edges" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_mv_dependency_edges" IS 'Materialized-view -> materialized-view dependency edges derived from pg_depend/pg_rewrite, chased transitively through plain views. Consumed by mv_refresh_plan().';



CREATE OR REPLACE VIEW "public"."v_mv_refresh_drift" AS
 WITH "cat" AS (
         SELECT "c"."relname" AS "mv_name",
            "pg_total_relation_size"(("c"."oid")::"regclass") AS "bytes",
            (EXISTS ( SELECT 1
                   FROM "pg_index" "i"
                  WHERE (("i"."indrelid" = "c"."oid") AND "i"."indisunique" AND ("i"."indpred" IS NULL) AND ("i"."indexprs" IS NULL)))) AS "has_unique_idx"
           FROM ("pg_class" "c"
             JOIN "pg_namespace" "n" ON (("n"."oid" = "c"."relnamespace")))
          WHERE (("n"."nspname" = 'public'::"name") AND ("c"."relkind" = 'm'::"char"))
        ), "last_success" AS (
         SELECT DISTINCT ON ("mv_refresh_log"."mv_name") "mv_refresh_log"."mv_name",
            "mv_refresh_log"."finished_at",
            "mv_refresh_log"."started_at"
           FROM "public"."mv_refresh_log"
          WHERE ("mv_refresh_log"."status" = ANY (ARRAY['success'::"text", 'success-fallback'::"text"]))
          ORDER BY "mv_refresh_log"."mv_name", "mv_refresh_log"."finished_at" DESC
        ), "last_attempt" AS (
         SELECT DISTINCT ON ("mv_refresh_log"."mv_name") "mv_refresh_log"."mv_name",
            "mv_refresh_log"."started_at",
            "mv_refresh_log"."status"
           FROM "public"."mv_refresh_log"
          ORDER BY "mv_refresh_log"."mv_name", "mv_refresh_log"."started_at" DESC
        )
 SELECT COALESCE("cat"."mv_name", ("r"."mv_name")::"name") AS "mv_name",
        CASE
            WHEN ("r"."mv_name" IS NULL) THEN 'UNREGISTERED'::"text"
            WHEN ("cat"."mv_name" IS NULL) THEN 'ORPHAN_ROW'::"text"
            ELSE 'ok'::"text"
        END AS "drift",
    "r"."tier",
    "r"."enabled",
    "r"."health",
    "r"."max_age_hours",
    "r"."notes",
    "cat"."bytes",
    "cat"."has_unique_idx",
    "ls"."finished_at" AS "last_success_at",
    "la"."started_at" AS "last_attempt_at",
    "la"."status" AS "last_attempt_status",
    ("now"() - "ls"."finished_at") AS "staleness",
    "round"((EXTRACT(epoch FROM ("now"() - "ls"."finished_at")) / 3600.0), 1) AS "age_hours",
        CASE
            WHEN ("r"."mv_name" IS NULL) THEN 'unregistered'::"text"
            WHEN ("cat"."mv_name" IS NULL) THEN 'orphan'::"text"
            WHEN ("r"."tier" = 'retire'::"text") THEN 'retired'::"text"
            WHEN ("r"."enabled" IS NOT TRUE) THEN 'disabled'::"text"
            WHEN (("ls"."finished_at" IS NULL) AND ("r"."max_age_hours" IS NULL)) THEN 'unlogged'::"text"
            WHEN ("ls"."finished_at" IS NULL) THEN 'never'::"text"
            WHEN ("r"."max_age_hours" IS NULL) THEN 'unmanaged'::"text"
            WHEN (("now"() - "ls"."finished_at") > "make_interval"("hours" => "r"."max_age_hours")) THEN 'stale'::"text"
            ELSE 'fresh'::"text"
        END AS "freshness"
   FROM ((("cat"
     FULL JOIN "public"."mv_refresh_registry" "r" ON (("r"."mv_name" = "cat"."mv_name")))
     LEFT JOIN "last_success" "ls" ON (("ls"."mv_name" = COALESCE("cat"."mv_name", ("r"."mv_name")::"name"))))
     LEFT JOIN "last_attempt" "la" ON (("la"."mv_name" = COALESCE("cat"."mv_name", ("r"."mv_name")::"name"))));


ALTER VIEW "public"."v_mv_refresh_drift" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_mv_refresh_drift" IS 'Every matview with the freshness verdict a surface should disclose. last_success_at counts SUCCESSFUL refreshes only -- the earlier definition used the last row of any status, so a failed refresh read as a refresh. freshness ''unlogged'' means an on_demand matview owned by a path that does not write to mv_refresh_log (see notes); it is an honest unknown, not a zero. See migrations/2026-08-20-mv-staleness-visible.sql and #314.';



