CREATE OR REPLACE VIEW "public"."v_ndis_registered_provider_graph_match" AS
 WITH "latest" AS (
         SELECT "max"("ndis_registered_providers"."report_date") AS "report_date"
           FROM "public"."ndis_registered_providers"
        ), "entity_abns" AS (
         SELECT DISTINCT "regexp_replace"("gs_entities"."abn", '\D'::"text", ''::"text", 'g'::"text") AS "abn_norm"
           FROM "public"."gs_entities"
          WHERE (("gs_entities"."abn" IS NOT NULL) AND ("regexp_replace"("gs_entities"."abn", '\D'::"text", ''::"text", 'g'::"text") <> ''::"text"))
        )
 SELECT "r"."report_date",
    "r"."registration_status",
    "count"(*) AS "provider_count",
    "count"("e"."abn_norm") AS "matched_entity_count",
    "round"(((100.0 * ("count"("e"."abn_norm"))::numeric) / (NULLIF("count"(*), 0))::numeric), 1) AS "matched_entity_pct"
   FROM (("public"."ndis_registered_providers" "r"
     JOIN "latest" "l" ON (("l"."report_date" = "r"."report_date")))
     LEFT JOIN "entity_abns" "e" ON (("e"."abn_norm" = "regexp_replace"(COALESCE("r"."abn", ''::"text"), '\D'::"text", ''::"text", 'g'::"text"))))
  GROUP BY "r"."report_date", "r"."registration_status"
  ORDER BY ("count"(*)) DESC, "r"."registration_status";


