CREATE OR REPLACE VIEW "public"."v_need_to_respond" WITH ("security_invoker"='true') AS
 SELECT "ch"."id",
    "ch"."ghl_contact_id",
    "ch"."channel",
    "ch"."direction",
    "ch"."from_identity",
    "ch"."to_identities",
    "ch"."subject",
    "ch"."content_preview",
    "ch"."full_content_ref",
    "ch"."summary",
    "ch"."sentiment",
    "ch"."topics",
    "ch"."action_items",
    "ch"."key_decisions",
    "ch"."waiting_for_response",
    "ch"."response_needed_by",
    "ch"."follow_up_date",
    "ch"."source_system",
    "ch"."source_id",
    "ch"."source_thread_id",
    "ch"."parent_id",
    "ch"."occurred_at",
    "ch"."synced_at",
    "ch"."enriched_at",
    "ch"."created_at",
    "ch"."updated_at",
    "ch"."dismissed_at",
    "ch"."dismissed_reason",
    "c"."full_name" AS "contact_name",
    "c"."email" AS "contact_email",
    EXTRACT(day FROM ("now"() - "ch"."occurred_at")) AS "days_since"
   FROM ("public"."communications_history" "ch"
     JOIN "public"."ghl_contacts" "c" ON (("ch"."ghl_contact_id" = "c"."ghl_id")))
  WHERE (("ch"."waiting_for_response" = true) AND ("ch"."response_needed_by" = 'us'::"text") AND ("ch"."dismissed_at" IS NULL) AND (COALESCE("c"."email", ''::"text") !~~* '%noreply%'::"text") AND (COALESCE("c"."email", ''::"text") !~~* '%no-reply%'::"text") AND (COALESCE("c"."email", ''::"text") !~~* '%donotreply%'::"text") AND (COALESCE("c"."email", ''::"text") !~~* '%notifications@%'::"text") AND (COALESCE("c"."email", ''::"text") !~~* '%mailer-daemon@%'::"text") AND ("ch"."occurred_at" > ("now"() - '90 days'::interval)))
  ORDER BY "ch"."occurred_at" DESC;


ALTER VIEW "public"."v_need_to_respond" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_need_to_respond" IS 'Emails waiting for our response, excluding dismissed, noreply senders, and >90 day old emails';



CREATE OR REPLACE VIEW "public"."v_newsletter_audience" WITH ("security_invoker"='true') AS
 SELECT "gc"."id",
    "gc"."ghl_id",
    "gc"."full_name",
    "gc"."email",
    "gc"."newsletter_consent",
    "gc"."newsletter_consent_at",
    "gc"."newsletter_unsubscribed_at",
    "gc"."projects",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "unnest"("gc"."tags") "t_1"("t")
              WHERE ("lower"("t_1"."t") = 'goods-newsletter'::"text"))) THEN 'goods'::"text"
            WHEN (EXISTS ( SELECT 1
               FROM "unnest"("gc"."tags") "t_1"("t")
              WHERE ("lower"("t_1"."t") = 'harvest-newsletter'::"text"))) THEN 'harvest'::"text"
            WHEN (EXISTS ( SELECT 1
               FROM "unnest"("gc"."tags") "t_1"("t")
              WHERE ("lower"("t_1"."t") = 'newsletter'::"text"))) THEN 'generic'::"text"
            ELSE NULL::"text"
        END AS "newsletter_segment",
    "array_agg"(DISTINCT "t"."t") FILTER (WHERE ("t"."t" ~~ '%newsletter%'::"text")) AS "newsletter_tags"
   FROM ("public"."ghl_contacts" "gc"
     LEFT JOIN LATERAL "unnest"("gc"."tags") "t"("t") ON (("lower"("t"."t") ~~ '%newsletter%'::"text")))
  WHERE (("gc"."newsletter_consent" = true) AND ("gc"."newsletter_unsubscribed_at" IS NULL) AND ("gc"."email" IS NOT NULL) AND ("gc"."email" !~~ '%.local'::"text") AND ("gc"."email" !~~ '%.temp'::"text"))
  GROUP BY "gc"."id", "gc"."ghl_id", "gc"."full_name", "gc"."email", "gc"."newsletter_consent", "gc"."newsletter_consent_at", "gc"."newsletter_unsubscribed_at", "gc"."projects", "gc"."tags";


ALTER VIEW "public"."v_newsletter_audience" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_newsletter_reprompt_candidates" WITH ("security_invoker"='true') AS
 SELECT "id",
    "ghl_id",
    "full_name",
    "email",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "unnest"("gc"."tags") "t"("t")
              WHERE ("lower"("t"."t") = 'goods-newsletter'::"text"))) THEN 'goods'::"text"
            WHEN (EXISTS ( SELECT 1
               FROM "unnest"("gc"."tags") "t"("t")
              WHERE ("lower"("t"."t") = 'harvest-newsletter'::"text"))) THEN 'harvest'::"text"
            WHEN (EXISTS ( SELECT 1
               FROM "unnest"("gc"."tags") "t"("t")
              WHERE ("lower"("t"."t") = 'newsletter'::"text"))) THEN 'generic'::"text"
            ELSE NULL::"text"
        END AS "newsletter_segment",
    "projects",
    "tags",
    "last_contact_date"
   FROM "public"."ghl_contacts" "gc"
  WHERE ((EXISTS ( SELECT 1
           FROM "unnest"("gc"."tags") "t"("t")
          WHERE ("lower"("t"."t") ~~ '%newsletter%'::"text"))) AND (COALESCE("newsletter_consent", false) = false) AND ("email" IS NOT NULL) AND ("email" !~~ '%.local'::"text") AND ("email" !~~ '%.temp'::"text"));


ALTER VIEW "public"."v_newsletter_reprompt_candidates" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_nt_community_entity_matches" AS
 WITH "community_patterns" AS (
         SELECT "c"."id" AS "community_id",
            "c"."community_name",
            "c"."region_label",
            "c"."service_region",
            "c"."land_council",
            "c"."postcode" AS "community_postcode",
            "c"."is_official_remote_community",
            "c"."goods_focus_priority",
            "c"."goods_signal_name",
            "c"."goods_signal_type",
            "c"."known_buyer_name",
            "aliases"."alias_name",
            (('(^|[^a-z0-9])'::"text" || "regexp_replace"("lower"("aliases"."alias_name"), '[^a-z0-9]+'::"text", '[^a-z0-9]+'::"text", 'g'::"text")) || '([^a-z0-9]|$)'::"text") AS "alias_regex"
           FROM ("public"."nt_communities" "c"
             CROSS JOIN LATERAL ( SELECT DISTINCT TRIM(BOTH FROM "value"."value") AS "alias_name"
                   FROM "unnest"("array_prepend"("c"."community_name", "c"."aliases")) "value"("value")
                  WHERE (TRIM(BOTH FROM "value"."value") <> ''::"text")) "aliases")
        )
 SELECT DISTINCT ON ("cp"."community_id", "e"."id") "cp"."community_id",
    "cp"."community_name",
    "cp"."region_label",
    "cp"."service_region",
    "cp"."land_council",
    "cp"."community_postcode",
    "cp"."is_official_remote_community",
    "cp"."goods_focus_priority",
    "cp"."goods_signal_name",
    "cp"."goods_signal_type",
    "cp"."known_buyer_name",
    "cp"."alias_name",
    "e"."id" AS "entity_id",
    "e"."gs_id",
    "e"."canonical_name" AS "entity_name",
    "e"."abn",
    "e"."website",
    "e"."entity_type",
    "e"."sector",
    "e"."sub_sector",
    "e"."postcode" AS "entity_postcode",
    "e"."lga_name" AS "entity_lga_name",
    "e"."is_community_controlled",
    "e"."source_count",
        CASE
            WHEN ("lower"("e"."canonical_name") = "lower"("cp"."alias_name")) THEN 'exact_name'::"text"
            WHEN ("lower"("e"."canonical_name") = "lower"("cp"."community_name")) THEN 'exact_community'::"text"
            WHEN ("lower"("e"."canonical_name") ~ (('(^|[^a-z0-9])'::"text" || "regexp_replace"("lower"("cp"."community_name"), '[^a-z0-9]+'::"text", '[^a-z0-9]+'::"text", 'g'::"text")) || '([^a-z0-9]|$)'::"text")) THEN 'community_word'::"text"
            ELSE 'alias_word'::"text"
        END AS "match_method",
    ((
        CASE
            WHEN ("lower"("e"."canonical_name") = "lower"("cp"."community_name")) THEN 40
            WHEN ("lower"("e"."canonical_name") = "lower"("cp"."alias_name")) THEN 36
            WHEN ("lower"("e"."canonical_name") ~ (('(^|[^a-z0-9])'::"text" || "regexp_replace"("lower"("cp"."community_name"), '[^a-z0-9]+'::"text", '[^a-z0-9]+'::"text", 'g'::"text")) || '([^a-z0-9]|$)'::"text")) THEN 30
            ELSE 22
        END + LEAST(COALESCE("e"."source_count", 0), 8)) +
        CASE
            WHEN "e"."is_community_controlled" THEN 8
            ELSE 0
        END) AS "match_score"
   FROM ("community_patterns" "cp"
     JOIN "public"."gs_entities" "e" ON ((("e"."state" = 'NT'::"text") AND ("lower"("e"."canonical_name") ~ "cp"."alias_regex"))))
  ORDER BY "cp"."community_id", "e"."id", ("length"("cp"."alias_name")) DESC, COALESCE("e"."source_count", 0) DESC;


ALTER VIEW "public"."v_nt_community_entity_matches" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_nt_community_buyer_crosswalk" AS
 SELECT "community_id",
    "community_name",
    "region_label",
    "service_region",
    "land_council",
    "community_postcode",
    "is_official_remote_community",
    "goods_focus_priority",
    "goods_signal_name",
    "goods_signal_type",
    "known_buyer_name",
    "alias_name",
    "entity_id",
    "gs_id",
    "entity_name" AS "buyer_name",
    "abn",
    "website",
    "entity_type",
    "sector",
    "sub_sector",
    "entity_postcode",
    "entity_lga_name",
    "is_community_controlled",
    "source_count",
    "match_method",
    "match_score",
        CASE
            WHEN ("entity_name" ~* '(outback stores|store|supermarket|progress)'::"text") THEN 'store'::"text"
            WHEN ("entity_name" ~* '(health|medical|clinic|health board|health service)'::"text") THEN 'health'::"text"
            WHEN ("entity_name" ~* '(housing)'::"text") THEN 'housing'::"text"
            WHEN ("entity_name" ~* '(council|regional council|shire)'::"text") THEN 'council'::"text"
            ELSE 'other_service'::"text"
        END AS "buyer_type"
   FROM "public"."v_nt_community_entity_matches" "m"
  WHERE ("entity_name" ~* '(outback stores|store|supermarket|progress|health|medical|clinic|health board|health service|housing|council|regional council|shire)'::"text");


ALTER VIEW "public"."v_nt_community_buyer_crosswalk" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_nt_community_procurement_summary" AS
 WITH "entity_counts" AS (
         SELECT "v_nt_community_entity_matches"."community_id",
            "count"(DISTINCT "v_nt_community_entity_matches"."entity_id") AS "entity_match_count",
            "count"(DISTINCT "v_nt_community_entity_matches"."entity_id") FILTER (WHERE "v_nt_community_entity_matches"."is_community_controlled") AS "community_controlled_match_count"
           FROM "public"."v_nt_community_entity_matches"
          GROUP BY "v_nt_community_entity_matches"."community_id"
        ), "buyer_counts" AS (
         SELECT "v_nt_community_buyer_crosswalk"."community_id",
            "count"(DISTINCT "v_nt_community_buyer_crosswalk"."entity_id") AS "buyer_match_count",
            "count"(DISTINCT "v_nt_community_buyer_crosswalk"."entity_id") FILTER (WHERE ("v_nt_community_buyer_crosswalk"."buyer_type" = 'store'::"text")) AS "store_count",
            "count"(DISTINCT "v_nt_community_buyer_crosswalk"."entity_id") FILTER (WHERE ("v_nt_community_buyer_crosswalk"."buyer_type" = 'health'::"text")) AS "health_count",
            "count"(DISTINCT "v_nt_community_buyer_crosswalk"."entity_id") FILTER (WHERE ("v_nt_community_buyer_crosswalk"."buyer_type" = 'housing'::"text")) AS "housing_count",
            "count"(DISTINCT "v_nt_community_buyer_crosswalk"."entity_id") FILTER (WHERE ("v_nt_community_buyer_crosswalk"."buyer_type" = 'council'::"text")) AS "council_count",
            "count"(DISTINCT "v_nt_community_buyer_crosswalk"."entity_id") FILTER (WHERE ("v_nt_community_buyer_crosswalk"."buyer_type" = 'other_service'::"text")) AS "other_service_count",
            "array_agg"("v_nt_community_buyer_crosswalk"."buyer_name" ORDER BY "v_nt_community_buyer_crosswalk"."match_score" DESC) AS "top_buyer_names"
           FROM "public"."v_nt_community_buyer_crosswalk"
          GROUP BY "v_nt_community_buyer_crosswalk"."community_id"
        )
 SELECT "c"."id" AS "community_id",
    "c"."community_name",
    "c"."region_label",
    "c"."service_region",
    "c"."land_council",
    "c"."postcode",
    "c"."is_official_remote_community",
    "c"."goods_focus_priority",
    "c"."goods_signal_name",
    "c"."goods_signal_type",
    "c"."known_buyer_name",
    COALESCE("ec"."entity_match_count", (0)::bigint) AS "entity_match_count",
    COALESCE("bc"."buyer_match_count", (0)::bigint) AS "buyer_match_count",
    COALESCE("bc"."store_count", (0)::bigint) AS "store_count",
    COALESCE("bc"."health_count", (0)::bigint) AS "health_count",
    COALESCE("bc"."housing_count", (0)::bigint) AS "housing_count",
    COALESCE("bc"."council_count", (0)::bigint) AS "council_count",
    COALESCE("bc"."other_service_count", (0)::bigint) AS "other_service_count",
    COALESCE("ec"."community_controlled_match_count", (0)::bigint) AS "community_controlled_match_count",
    COALESCE("bc"."top_buyer_names", ARRAY[]::"text"[]) AS "top_buyer_names",
    ("c"."postcode" IS NULL) AS "needs_postcode_enrichment",
    (("c"."goods_signal_name" IS NOT NULL) OR ("c"."known_buyer_name" IS NOT NULL) OR ("c"."proof_line" IS NOT NULL)) AS "has_goods_signal"
   FROM (("public"."nt_communities" "c"
     LEFT JOIN "entity_counts" "ec" ON (("ec"."community_id" = "c"."id")))
     LEFT JOIN "buyer_counts" "bc" ON (("bc"."community_id" = "c"."id")))
  ORDER BY "c"."is_official_remote_community" DESC, "c"."community_name";


ALTER VIEW "public"."v_nt_community_procurement_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_org_grant_health" WITH ("security_invoker"='true') AS
 SELECT "g"."id",
    "g"."grant_name",
    "g"."funder_name",
    "g"."organization_id",
    COALESCE("g"."approved_amount", "g"."amount_awarded") AS "approved_amount",
    "g"."amount_awarded",
    "g"."contract_start",
    "g"."contract_end",
    "g"."status",
    COALESCE("b"."total_budgeted", (0)::numeric) AS "total_budgeted",
    COALESCE("b"."total_actual", (0)::numeric) AS "total_spent",
    (COALESCE("g"."approved_amount", "g"."amount_awarded", (0)::numeric) - COALESCE("b"."total_actual", (0)::numeric)) AS "remaining_budget",
    COALESCE("i"."issues_count", (0)::bigint) AS "issues_count"
   FROM (("public"."org_grants" "g"
     LEFT JOIN ( SELECT "org_grant_budget_lines"."grant_id",
            "sum"("org_grant_budget_lines"."budgeted_amount") AS "total_budgeted",
            "sum"("org_grant_budget_lines"."actual_amount") AS "total_actual"
           FROM "public"."org_grant_budget_lines"
          GROUP BY "org_grant_budget_lines"."grant_id") "b" ON (("b"."grant_id" = "g"."id")))
     LEFT JOIN ( SELECT "bl"."grant_id",
            "count"(*) AS "issues_count"
           FROM "public"."org_grant_budget_lines" "bl"
          WHERE ("bl"."has_issue" = true)
          GROUP BY "bl"."grant_id") "i" ON (("i"."grant_id" = "g"."id")));


ALTER VIEW "public"."v_org_grant_health" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_org_upcoming_deadlines" WITH ("security_invoker"='true') AS
 SELECT "d"."id",
    "d"."organization_id",
    "d"."grant_id",
    "d"."title",
    "d"."due_date",
    "d"."deadline_type",
    "d"."status",
    "d"."submitted_date",
    "d"."requirements",
    "d"."document_url",
    "d"."reminder_days_before",
    "d"."notes",
    "d"."created_at",
    "d"."updated_at",
    ("d"."due_date" - CURRENT_DATE) AS "days_until_due",
        CASE
            WHEN ("d"."status" = ANY (ARRAY['completed'::"text", 'submitted'::"text"])) THEN 'done'::"text"
            WHEN ("d"."due_date" < CURRENT_DATE) THEN 'overdue'::"text"
            WHEN ("d"."due_date" <= (CURRENT_DATE + '7 days'::interval)) THEN 'urgent'::"text"
            WHEN ("d"."due_date" <= (CURRENT_DATE + '30 days'::interval)) THEN 'upcoming'::"text"
            ELSE 'future'::"text"
        END AS "urgency",
    "g"."grant_name",
    "g"."funder_name"
   FROM ("public"."org_deadlines" "d"
     LEFT JOIN "public"."org_grants" "g" ON (("g"."id" = "d"."grant_id")))
  ORDER BY "d"."due_date";


ALTER VIEW "public"."v_org_upcoming_deadlines" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_outstanding_invoices" WITH ("security_invoker"='true') AS
 SELECT "id",
    "xero_id" AS "xero_invoice_id",
    "invoice_number",
    "contact_name",
    "project_code",
    "type",
    "total",
    "amount_due",
    "amount_paid",
    "date",
    "due_date",
        CASE
            WHEN ("due_date" IS NULL) THEN 'no_due_date'::"text"
            WHEN ("due_date" >= CURRENT_DATE) THEN 'current'::"text"
            WHEN ("due_date" >= (CURRENT_DATE - '30 days'::interval)) THEN '1-30_days'::"text"
            WHEN ("due_date" >= (CURRENT_DATE - '60 days'::interval)) THEN '31-60_days'::"text"
            WHEN ("due_date" >= (CURRENT_DATE - '90 days'::interval)) THEN '61-90_days'::"text"
            ELSE '90+_days'::"text"
        END AS "aging_bucket",
        CASE
            WHEN ("due_date" IS NULL) THEN 0
            ELSE (CURRENT_DATE - "due_date")
        END AS "days_overdue"
   FROM "public"."xero_invoices"
  WHERE (("amount_due" > (0)::numeric) AND ("status" = ANY (ARRAY['AUTHORISED'::"text", 'SUBMITTED'::"text"])))
  ORDER BY "due_date";


ALTER VIEW "public"."v_outstanding_invoices" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_pending_receipts" WITH ("security_invoker"='true') AS
 SELECT "id",
    "source_type",
    "source_id",
    "vendor_name",
    "amount",
    "transaction_date",
    "category",
    "description",
    "status",
    "match_confidence",
    "suggested_email_subject",
    "suggested_email_from",
    "week_start",
    "deferred_count",
    (CURRENT_DATE - "transaction_date") AS "days_old",
        CASE
            WHEN ("transaction_date" >= (CURRENT_DATE - 7)) THEN 'quick_resolve_eligible'::"text"
            WHEN ("transaction_date" >= (CURRENT_DATE - 30)) THEN 'recent'::"text"
            WHEN ("transaction_date" >= (CURRENT_DATE - 60)) THEN 'aging'::"text"
            ELSE 'backlog'::"text"
        END AS "age_category"
   FROM "public"."receipt_matches" "rm"
  WHERE ("status" = ANY (ARRAY['pending'::"text", 'email_suggested'::"text", 'deferred'::"text"]))
  ORDER BY "match_confidence" DESC NULLS LAST, "transaction_date" DESC;


ALTER VIEW "public"."v_pending_receipts" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_pending_subscriptions_review" WITH ("security_invoker"='true') AS
 SELECT "id",
    "vendor_name",
    "vendor_aliases",
    "detected_amount",
    "detected_currency",
    "detected_cycle",
    "discovery_source",
    "discovery_confidence",
    "first_seen_at",
    "last_seen_at",
    "payment_count",
    "avg_interval_days",
    "amount_variance_pct",
    "evidence",
    "status",
    "resolved_subscription_id",
    "resolved_at",
    "resolved_by",
    "created_at",
    "updated_at",
    COALESCE(( SELECT "s"."vendor_name"
           FROM "public"."subscriptions" "s"
          WHERE ("lower"("s"."vendor_name") = "lower"("ps"."vendor_name"))
         LIMIT 1), NULL::"text") AS "possible_match"
   FROM "public"."pending_subscriptions" "ps"
  WHERE ("status" = 'pending'::"text")
  ORDER BY "discovery_confidence" DESC, "payment_count" DESC;


ALTER VIEW "public"."v_pending_subscriptions_review" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_person_360" AS
SELECT
    NULL::"uuid" AS "person_id",
