ALTER VIEW "public"."v_person_360" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_pipeline_value" WITH ("security_invoker"='true') AS
 SELECT "opportunity_type",
    "stage",
    "count"(*) AS "opportunity_count",
    "sum"("value_mid") AS "total_value",
    "sum"((("value_mid" * "probability") / (100)::numeric)) AS "weighted_value",
    "avg"("probability") AS "avg_probability"
   FROM "public"."opportunities_unified"
  WHERE ("stage" <> ALL (ARRAY['realized'::"text", 'lost'::"text", 'expired'::"text"]))
  GROUP BY "opportunity_type", "stage"
  ORDER BY "opportunity_type", "stage";


ALTER VIEW "public"."v_pipeline_value" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_prf_portfolio_outcomes" AS
 SELECT "jf"."recipient_name",
    "jf"."recipient_abn",
    "jf"."gs_entity_id",
    "ge"."canonical_name",
    "jf"."amount_dollars",
    ( SELECT "count"(*) AS "count"
           FROM "public"."outcome_submissions" "os"
          WHERE ("os"."gs_entity_id" = "ge"."gs_id")) AS "submissions",
    ( SELECT "count"(*) AS "count"
           FROM "public"."outcome_submissions" "os"
          WHERE (("os"."gs_entity_id" = "ge"."gs_id") AND ("os"."status" = 'validated'::"text"))) AS "validated",
    ( SELECT "count"(*) AS "count"
           FROM "public"."alma_interventions" "ai"
          WHERE ("ai"."gs_entity_id" = "jf"."gs_entity_id")) AS "alma_interventions",
    ( SELECT "max"("ai"."portfolio_score") AS "max"
           FROM "public"."alma_interventions" "ai"
          WHERE ("ai"."gs_entity_id" = "jf"."gs_entity_id")) AS "best_portfolio_score",
    ( SELECT "count"(*) AS "count"
           FROM "public"."governed_proof_bundles" "gpb"
          WHERE ("gpb"."subject_id" = "ge"."gs_id")) AS "proof_bundles",
    ( SELECT "count"(*) AS "count"
           FROM "public"."governed_proof_tasks" "gpt"
          WHERE (("gpt"."target_id" = "ge"."gs_id") AND ("gpt"."status" <> 'completed'::"text"))) AS "pending_tasks",
        CASE
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."outcome_submissions" "os"
              WHERE (("os"."gs_entity_id" = "ge"."gs_id") AND ("os"."status" = 'validated'::"text"))) > 0) THEN 'proven'::"text"
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."outcome_submissions" "os"
              WHERE ("os"."gs_entity_id" = "ge"."gs_id")) > 0) THEN 'submitted'::"text"
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."alma_interventions" "ai"
              WHERE ("ai"."gs_entity_id" = "jf"."gs_entity_id")) > 0) THEN 'evidence_exists'::"text"
            ELSE 'awaiting_submission'::"text"
        END AS "status"
   FROM ("public"."justice_funding" "jf"
     LEFT JOIN "public"."gs_entities" "ge" ON (("ge"."id" = "jf"."gs_entity_id")))
  WHERE ("jf"."program_name" = 'PRF Justice Reinvestment Portfolio'::"text")
  ORDER BY "jf"."recipient_name";


ALTER VIEW "public"."v_prf_portfolio_outcomes" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_program_deliverers" AS
 WITH "announced" AS (
         SELECT ("f"."gs_entity_id")::"text" AS "gs_entity_id",
            ("array_agg"("f"."recipient_name" ORDER BY ("length"("f"."recipient_name"))))[1] AS "announced_name"
           FROM "public"."justice_funding" "f"
          WHERE (("f"."gs_entity_id" IS NOT NULL) AND ("f"."measure_kind" = 'budget_announcement'::"text") AND (NOT "f"."is_aggregate") AND ("f"."recipient_name" IS NOT NULL) AND ("f"."recipient_name" !~* '^\s*(\(?blank\)?|n/?a|none|nil|unknown|various|multiple)\s*$'::"text") AND ("f"."recipient_name" !~ '/'::"text") AND ("f"."recipient_name" !~ '\s[-–—]\s'::"text") AND ("f"."recipient_name" !~* '^(department|ministry|office) of\M'::"text") AND ("length"("f"."recipient_name") <= 120))
          GROUP BY ("f"."gs_entity_id")::"text"
        ), "rows_" AS (
         SELECT "a"."value" AS "program_name",
            COALESCE("g"."canonical_id", "a"."subject_id") AS "org_id",
            "an"."announced_name",
            "n"."value" AS "register_name",
            COALESCE("an"."announced_name", "n"."value") AS "organisation",
            "a"."asserter_kind",
            "a"."basis",
            "a"."source_url"
           FROM ((("public"."assertions" "a"
             LEFT JOIN "public"."assertions" "n" ON ((("n"."subject_id" = "a"."subject_id") AND ("n"."machine_rule" = 'display_name_v1'::"text") AND ("n"."superseded_by" IS NULL))))
             LEFT JOIN "announced" "an" ON (("an"."gs_entity_id" = "a"."subject_id")))
             LEFT JOIN "public"."v_entity_organisation_group" "g" ON (("g"."entity_id" = "a"."subject_id")))
          WHERE (("a"."predicate" = 'delivers_program'::"text") AND ("a"."superseded_by" IS NULL))
        )
 SELECT "program_name",
    "org_id" AS "gs_entity_id",
    COALESCE(("array_agg"("organisation" ORDER BY ("announced_name" IS NOT NULL) DESC) FILTER (WHERE ("organisation" IS NOT NULL)))[1], 'Name unresolved'::"text") AS "organisation",
    ("array_agg"("register_name" ORDER BY ("announced_name" IS NOT NULL) DESC) FILTER (WHERE (("register_name" IS NOT NULL) AND ("lower"("register_name") <> "lower"(COALESCE("announced_name", ''::"text"))))))[1] AS "legal_name",
    ("array_agg"("asserter_kind" ORDER BY ("basis" = 'statutory'::"text") DESC, ("basis" = 'disclosed'::"text") DESC))[1] AS "asserter_kind",
    ("array_agg"("basis" ORDER BY ("basis" = 'statutory'::"text") DESC, ("basis" = 'disclosed'::"text") DESC))[1] AS "basis",
    ("array_agg"("source_url") FILTER (WHERE ("source_url" IS NOT NULL)))[1] AS "source_url",
    "count"(*) AS "assertions"
   FROM "rows_"
  GROUP BY "program_name", "org_id";


ALTER VIEW "public"."v_program_deliverers" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_program_deliverers" IS 'Who a government says delivers a named program, ONE ROW PER ORGANISATION. Entity ids sharing a statutory ABN are one organisation. organisation is the PUBLIC name from the announcement; legal_name carries the register name when it differs.';



CREATE OR REPLACE VIEW "public"."v_program_detail_deliverers" AS
 SELECT "p"."id" AS "program_id",
    "d"."program_name",
    "d"."gs_entity_id",
    "d"."organisation",
    "d"."legal_name",
    "a"."asserter_kind",
    "a"."basis",
    "a"."source_url",
    "a"."note",
    ("a"."created_at")::"date" AS "read_at",
    "substring"("a"."note", 'Quoted: "(.*)"'::"text") AS "source_quote"
   FROM (("public"."alma_government_programs" "p"
     JOIN "public"."v_program_deliverers" "d" ON (("lower"(TRIM(BOTH FROM "d"."program_name")) = "lower"(TRIM(BOTH FROM "p"."name")))))
     LEFT JOIN LATERAL ( SELECT "x"."asserter_kind",
            "x"."basis",
            "x"."source_url",
            "x"."note",
            "x"."created_at"
           FROM "public"."assertions" "x"
          WHERE (("x"."subject_id" = "d"."gs_entity_id") AND ("x"."predicate" = 'delivers_program'::"text") AND ("x"."superseded_by" IS NULL))
          ORDER BY
                CASE "x"."basis"
                    WHEN 'statutory'::"text" THEN 1
                    WHEN 'certified'::"text" THEN 2
                    WHEN 'disclosed'::"text" THEN 3
                    WHEN 'stated'::"text" THEN 4
                    WHEN 'derived'::"text" THEN 5
                    ELSE 6
                END, ("x"."note" ~~ '%Quoted: "%'::"text") DESC, "x"."created_at" DESC
         LIMIT 1) "a" ON (true))
  WHERE (("d"."organisation" IS NOT NULL) AND ("d"."organisation" <> 'Name unresolved'::"text"));


ALTER VIEW "public"."v_program_detail_deliverers" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_program_spine" AS
 WITH "links" AS (
         SELECT "assertions"."subject_id",
            "count"(*) FILTER (WHERE ("assertions"."value" IS NOT NULL)) AS "link_count",
            "count"(*) FILTER (WHERE (("assertions"."value" IS NOT NULL) AND ("assertions"."basis" = 'derived'::"text"))) AS "strong_links",
            ("array_agg"("assertions"."value" ORDER BY ("assertions"."basis" = 'derived'::"text") DESC, "assertions"."value") FILTER (WHERE ("assertions"."value" IS NOT NULL)))[1:4] AS "example_links"
           FROM "public"."assertions"
          WHERE (("assertions"."machine_rule" = 'program_link_v1'::"text") AND ("assertions"."superseded_by" IS NULL))
          GROUP BY "assertions"."subject_id"
        )
 SELECT "p"."id",
    "p"."name",
    "p"."jurisdiction",
    "p"."department",
    "p"."status",
    "p"."budget_amount",
    "p"."official_url",
    "p"."announced_date",
    COALESCE("l"."link_count", (0)::bigint) AS "funding_links",
    COALESCE("l"."strong_links", (0)::bigint) AS "strong_links",
    "l"."example_links",
    COALESCE("d"."orgs_named", (0)::bigint) AS "orgs_named",
    COALESCE("d"."orgs_with_dollars", (0)::bigint) AS "orgs_with_dollars",
    "d"."traceable_dollars"
   FROM (("public"."alma_government_programs" "p"
     LEFT JOIN "links" "l" ON (("l"."subject_id" = ("p"."id")::"text")))
     LEFT JOIN LATERAL ( SELECT "count"(DISTINCT "lower"(TRIM(BOTH FROM "f"."recipient_name"))) AS "orgs_named",
            "count"(DISTINCT "lower"(TRIM(BOTH FROM "f"."recipient_name"))) FILTER (WHERE ("f"."amount_dollars" IS NOT NULL)) AS "orgs_with_dollars",
            "sum"("f"."amount_dollars") AS "traceable_dollars"
           FROM "public"."justice_funding" "f"
          WHERE (("f"."state" = "p"."jurisdiction") AND ("f"."measure_kind" = 'grant'::"text") AND (NOT "f"."is_aggregate") AND ("f"."recipient_name" IS NOT NULL) AND ("f"."program_name" = ANY (COALESCE("l"."example_links", ARRAY[]::"text"[]))))) "d" ON (true));


ALTER VIEW "public"."v_program_spine" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_program_spine" IS 'One row per named government program. funding_links=0 means nothing published that we hold connects it to an organisation. Superseded links are excluded so a rejected correction stops counting. GRANTS ONLY in traceable_dollars: never summed with contract_value.';



CREATE OR REPLACE VIEW "public"."v_project_actions" WITH ("security_invoker"='true') AS
 SELECT "id",
    "project_code",
    "title",
    "action_items",
    "follow_up_date",
    "recorded_at"
   FROM "public"."project_knowledge" "pk"
  WHERE (("action_required" = true) OR ("follow_up_date" IS NOT NULL))
  ORDER BY "follow_up_date", "recorded_at" DESC;


ALTER VIEW "public"."v_project_actions" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_project_activity_stream" WITH ("security_invoker"='true') AS
 SELECT ("ch"."id")::"text" AS "activity_id",
    'email'::"text" AS "activity_type",
    COALESCE("ch"."project_codes"[1], 'UNLINKED'::"text") AS "project_code",
    "ch"."subject" AS "title",
    "ch"."summary" AS "description",
    "ch"."occurred_at" AS "activity_date",
    "jsonb_build_object"('from', "ch"."from_identity", 'direction', "ch"."direction", 'sentiment', "ch"."sentiment") AS "metadata"
   FROM "public"."communications_history" "ch"
  WHERE (("ch"."channel" = 'email'::"text") AND ("ch"."occurred_at" > ("now"() - '90 days'::interval)))
UNION ALL
 SELECT ("xt"."id")::"text" AS "activity_id",
    'transaction'::"text" AS "activity_type",
    COALESCE("xt"."project_code", 'UNLINKED'::"text") AS "project_code",
    "xt"."contact_name" AS "title",
    "xt"."type" AS "description",
    ("xt"."date")::timestamp with time zone AS "activity_date",
    "jsonb_build_object"('amount', "xt"."total", 'type', "xt"."type") AS "metadata"
   FROM "public"."xero_transactions" "xt"
  WHERE ("xt"."date" > ("now"() - '90 days'::interval))
UNION ALL
 SELECT ("pk"."id")::"text" AS "activity_id",
    'knowledge'::"text" AS "activity_type",
    COALESCE("pk"."project_code", 'UNLINKED'::"text") AS "project_code",
    "pk"."title",
    "pk"."content" AS "description",
    "pk"."recorded_at" AS "activity_date",
    "jsonb_build_object"('knowledge_type', "pk"."knowledge_type", 'importance', "pk"."importance") AS "metadata"
   FROM "public"."project_knowledge" "pk"
  WHERE ("pk"."recorded_at" > ("now"() - '90 days'::interval))
UNION ALL
 SELECT ("ce"."id")::"text" AS "activity_id",
    'meeting'::"text" AS "activity_type",
    COALESCE("ce"."project_code", 'UNLINKED'::"text") AS "project_code",
    "ce"."title",
    "ce"."description",
    "ce"."start_time" AS "activity_date",
    "jsonb_build_object"('attendees', "ce"."attendees", 'calendar', "ce"."google_calendar_id") AS "metadata"
   FROM "public"."calendar_events" "ce"
  WHERE ("ce"."start_time" > ("now"() - '90 days'::interval));


ALTER VIEW "public"."v_project_activity_stream" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_project_alignment" WITH ("security_invoker"='true') AS
 WITH "email_coverage" AS (
         SELECT DISTINCT "unnest"("communications_history"."project_codes") AS "project_code"
           FROM "public"."communications_history"
          WHERE (("communications_history"."project_codes" IS NOT NULL) AND ("array_length"("communications_history"."project_codes", 1) > 0))
        ), "calendar_coverage" AS (
         SELECT DISTINCT "calendar_events"."project_code"
           FROM "public"."calendar_events"
          WHERE ("calendar_events"."project_code" IS NOT NULL)
        ), "xero_coverage" AS (
         SELECT DISTINCT "xero_transactions"."project_code"
           FROM "public"."xero_transactions"
          WHERE (("xero_transactions"."project_code" IS NOT NULL) AND ("xero_transactions"."project_code" <> ''::"text"))
        UNION
         SELECT DISTINCT "xero_invoices"."project_code"
           FROM "public"."xero_invoices"
          WHERE (("xero_invoices"."project_code" IS NOT NULL) AND ("xero_invoices"."project_code" <> ''::"text"))
        ), "contact_coverage" AS (
         SELECT DISTINCT "p_1"."code" AS "project_code"
           FROM ("public"."projects" "p_1"
             CROSS JOIN LATERAL "unnest"("p_1"."ghl_tags") "tag"("tag"))
          WHERE (EXISTS ( SELECT 1
                   FROM "public"."ghl_contacts" "c"
                  WHERE ("tag"."tag" = ANY ("c"."tags"))))
        ), "knowledge_counts" AS (
         SELECT "project_knowledge"."project_code",
            "count"(*) AS "cnt"
           FROM "public"."project_knowledge"
          WHERE ("project_knowledge"."project_code" IS NOT NULL)
          GROUP BY "project_knowledge"."project_code"
        )
 SELECT "p"."id",
    "p"."code",
    "p"."name",
    "p"."tier",
    "p"."category",
    "p"."status",
    "p"."importance_weight",
    "p"."cultural_protocols",
    (EXISTS ( SELECT 1
           FROM "email_coverage" "e"
          WHERE ("e"."project_code" = "p"."code"))) AS "has_gmail_coverage",
    (EXISTS ( SELECT 1
           FROM "calendar_coverage" "cal"
          WHERE ("cal"."project_code" = "p"."code"))) AS "has_calendar_coverage",
    (EXISTS ( SELECT 1
           FROM "xero_coverage" "x"
          WHERE ("x"."project_code" = "p"."code"))) AS "has_xero_coverage",
    (EXISTS ( SELECT 1
           FROM "contact_coverage" "cc"
          WHERE ("cc"."project_code" = "p"."code"))) AS "has_contacts",
    (("p"."notion_page_id" IS NOT NULL) OR ("array_length"("p"."notion_pages", 1) > 0)) AS "has_notion_page",
    (COALESCE("kc"."cnt", (0)::bigint))::integer AS "knowledge_count",
    (((((
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "email_coverage" "e"
              WHERE ("e"."project_code" = "p"."code"))) THEN 20
            ELSE 0
        END +
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "calendar_coverage" "cal"
              WHERE ("cal"."project_code" = "p"."code"))) THEN 20
            ELSE 0
        END) +
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "xero_coverage" "x"
              WHERE ("x"."project_code" = "p"."code"))) THEN 20
            ELSE 0
        END) +
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "contact_coverage" "cc"
              WHERE ("cc"."project_code" = "p"."code"))) THEN 20
            ELSE 0
        END) +
        CASE
            WHEN (("p"."notion_page_id" IS NOT NULL) OR ("array_length"("p"."notion_pages", 1) > 0)) THEN 10
            ELSE 0
        END) +
        CASE
            WHEN (COALESCE("kc"."cnt", (0)::bigint) > 0) THEN 10
            ELSE 0
        END) AS "coverage_score",
    (("p"."tier" = 'ecosystem'::"text") AND ((NOT (EXISTS ( SELECT 1
           FROM "email_coverage" "e"
          WHERE ("e"."project_code" = "p"."code")))) OR (NOT (EXISTS ( SELECT 1
           FROM "calendar_coverage" "cal"
          WHERE ("cal"."project_code" = "p"."code")))) OR (NOT (EXISTS ( SELECT 1
           FROM "xero_coverage" "x"
          WHERE ("x"."project_code" = "p"."code")))) OR (NOT (EXISTS ( SELECT 1
           FROM "contact_coverage" "cc"
          WHERE ("cc"."project_code" = "p"."code")))))) AS "has_coverage_gaps"
   FROM ("public"."projects" "p"
     LEFT JOIN "knowledge_counts" "kc" ON (("kc"."project_code" = "p"."code")))
  ORDER BY "p"."importance_weight" DESC, "p"."name";


ALTER VIEW "public"."v_project_alignment" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_project_decisions" WITH ("security_invoker"='true') AS
 SELECT "project_code",
    "project_name",
    "title",
    "content",
    "decision_status",
    "decision_rationale",
    "recorded_at",
    "participants"
   FROM "public"."project_knowledge" "pk"
  WHERE ("knowledge_type" = 'decision'::"text")
  ORDER BY "project_code", "recorded_at" DESC;


ALTER VIEW "public"."v_project_decisions" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_project_financials" WITH ("security_invoker"='true') AS
 SELECT "p"."code",
    "p"."name",
    "p"."tier",
    "p"."importance_weight",
    COALESCE("sum"(
        CASE
            WHEN ("t"."type" = 'RECEIVE'::"text") THEN "abs"("t"."total")
            ELSE NULL::numeric
        END), (0)::numeric) AS "total_income",
    COALESCE("sum"(
        CASE
            WHEN ("t"."type" = 'SPEND'::"text") THEN "abs"("t"."total")
            ELSE NULL::numeric
        END), (0)::numeric) AS "total_expenses",
    COALESCE("sum"(
        CASE
            WHEN ("t"."type" = 'RECEIVE'::"text") THEN "abs"("t"."total")
            ELSE (- "abs"("t"."total"))
        END), (0)::numeric) AS "net_position",
    COALESCE("sum"(
        CASE
            WHEN (("t"."type" = 'SPEND'::"text") AND ("t"."date" >= ("date_trunc"('year'::"text", (CURRENT_DATE - '6 mons'::interval)) + '6 mons'::interval))) THEN "abs"("t"."total")
            ELSE NULL::numeric
        END), (0)::numeric) AS "fy_expenses",
    COALESCE("sum"(
        CASE
            WHEN (("t"."type" = 'RECEIVE'::"text") AND ("t"."date" >= ("date_trunc"('year'::"text", (CURRENT_DATE - '6 mons'::interval)) + '6 mons'::interval))) THEN "abs"("t"."total")
            ELSE NULL::numeric
        END), (0)::numeric) AS "fy_income",
    "count"("t"."id") AS "transaction_count",
    COALESCE(( SELECT "sum"("i"."amount_due") AS "sum"
           FROM "public"."xero_invoices" "i"
          WHERE (("i"."project_code" = "p"."code") AND ("i"."type" = 'ACCREC'::"text") AND ("i"."amount_due" > (0)::numeric))), (0)::numeric) AS "receivable",
    COALESCE(( SELECT "sum"(("o"."monetary_value")::numeric) AS "sum"
           FROM "public"."ghl_opportunities" "o"
          WHERE (("o"."project_code" = "p"."code") AND ("o"."status" <> 'lost'::"text"))), (0)::numeric) AS "pipeline_value",
    COALESCE(( SELECT "sum"(COALESCE("g"."outcome_amount", "g"."amount_requested")) AS "sum"
           FROM "public"."grant_applications" "g"
          WHERE (("g"."project_code" = "p"."code") AND ("g"."status" = ANY (ARRAY['approved'::"text", 'acquitted'::"text"])))), (0)::numeric) AS "grant_funding",
    COALESCE(( SELECT "sum"("abs"("s"."amount")) AS "sum"
           FROM "public"."subscriptions" "s"
          WHERE (("p"."code" = ANY ("s"."project_codes")) AND ("s"."account_status" = 'active'::"text"))), (0)::numeric) AS "monthly_subscriptions"
   FROM ("public"."projects" "p"
     LEFT JOIN "public"."xero_transactions" "t" ON (("t"."project_code" = "p"."code")))
  WHERE ("p"."status" = ANY (ARRAY['active'::"text", 'ideation'::"text"]))
  GROUP BY "p"."code", "p"."name", "p"."tier", "p"."importance_weight"
  ORDER BY "p"."importance_weight" DESC;


ALTER VIEW "public"."v_project_financials" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_project_funding_position" AS
 SELECT "a"."id" AS "allocation_id",
    "a"."project_code",
    "a"."funder_org_name",
    "a"."grant_or_contract_ref",
    "a"."committed_amount",
    "a"."status",
    "a"."period_start",
    "a"."period_end",
    "a"."next_report_due",
    "a"."next_report_name",
    COALESCE("d"."drawn_total", (0)::numeric) AS "drawn_amount",
    ("a"."committed_amount" - COALESCE("d"."drawn_total", (0)::numeric)) AS "remaining_amount",
        CASE
            WHEN ("a"."committed_amount" > (0)::numeric) THEN "round"((((100)::numeric * COALESCE("d"."drawn_total", (0)::numeric)) / "a"."committed_amount"), 1)
            ELSE NULL::numeric
        END AS "drawn_pct",
    COALESCE("d"."drawdown_count", (0)::bigint) AS "drawdown_count",
    "d"."last_drawn_at",
    "a"."pile_tag",
    "a"."notes"
   FROM ("public"."project_funding_allocations" "a"
     LEFT JOIN ( SELECT "project_funding_drawdowns"."allocation_id",
            "sum"("project_funding_drawdowns"."drawn_amount") AS "drawn_total",
            "count"(*) AS "drawdown_count",
            "max"("project_funding_drawdowns"."drawn_at") AS "last_drawn_at"
           FROM "public"."project_funding_drawdowns"
          GROUP BY "project_funding_drawdowns"."allocation_id") "d" ON (("d"."allocation_id" = "a"."id")));


ALTER VIEW "public"."v_project_funding_position" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_project_health_summary" WITH ("security_invoker"='true') AS
 SELECT "health_status",
    "count"(*) AS "project_count",
    "round"("avg"("overall_score"), 1) AS "avg_score",
    "min"("overall_score") AS "min_score",
    "max"("overall_score") AS "max_score"
   FROM "public"."project_health"
  GROUP BY "health_status";


ALTER VIEW "public"."v_project_health_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_project_lifetime_position" AS
 SELECT "project_code",
    "sum"("revenue_invoiced") AS "revenue_invoiced_lifetime",
    "sum"("expense_billed") AS "expense_billed_lifetime",
    "sum"("expense_bank") AS "expense_bank_lifetime",
    "sum"("receive_bank") AS "receive_bank_lifetime",
    "sum"("invoice_count") AS "invoice_count_lifetime",
    "sum"("txn_count") AS "txn_count_lifetime",
    "min"("quarter_start") AS "first_quarter",
    "max"("quarter_start") AS "last_quarter"
   FROM "public"."mv_project_quarter_position"
  GROUP BY "project_code";


ALTER VIEW "public"."v_project_lifetime_position" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_project_money_state" WITH ("security_invoker"='true') AS
 WITH "fy_range" AS (
         SELECT '2025-07-01'::"date" AS "fy_start",
            '2026-06-30'::"date" AS "fy_end"
        ), "txn_stats" AS (
         SELECT "t"."project_code",
            "count"(*) FILTER (WHERE (("t"."date" >= "f"."fy_start") AND ("t"."date" <= "f"."fy_end"))) AS "txn_count_fy",
            "count"(*) FILTER (WHERE ((("t"."date" >= "f"."fy_start") AND ("t"."date" <= "f"."fy_end")) AND ("t"."project_code" IS NULL))) AS "txn_untagged_fy",
            "sum"(
                CASE
                    WHEN (("t"."type" = ANY (ARRAY['SPEND'::"text", 'SPEND-OVERPAYMENT'::"text", 'SPEND-PREPAYMENT'::"text"])) AND (("t"."date" >= "f"."fy_start") AND ("t"."date" <= "f"."fy_end"))) THEN "t"."total"
                    ELSE (0)::numeric
                END) AS "expenses_fy",
            "sum"(
                CASE
                    WHEN (("t"."type" = ANY (ARRAY['RECEIVE'::"text", 'RECEIVE-OVERPAYMENT'::"text", 'RECEIVE-PREPAYMENT'::"text"])) AND (("t"."date" >= "f"."fy_start") AND ("t"."date" <= "f"."fy_end"))) THEN "t"."total"
                    ELSE (0)::numeric
                END) AS "income_fy",
            "max"("t"."date") AS "last_transaction_at"
           FROM ("public"."xero_transactions" "t"
             CROSS JOIN "fy_range" "f")
          GROUP BY "t"."project_code"
        ), "inv_stats" AS (
         SELECT "i"."project_code",
            "count"(*) FILTER (WHERE (("i"."date" >= "f"."fy_start") AND ("i"."date" <= "f"."fy_end"))) AS "inv_count_fy",
            "count"(*) FILTER (WHERE ((("i"."date" >= "f"."fy_start") AND ("i"."date" <= "f"."fy_end")) AND ("i"."project_code" IS NULL))) AS "inv_untagged_fy",
            "sum"(
                CASE
                    WHEN (("i"."type" = 'ACCREC'::"text") AND ("i"."status" = ANY (ARRAY['AUTHORISED'::"text", 'SUBMITTED'::"text"]))) THEN "i"."amount_due"
                    ELSE (0)::numeric
                END) AS "receivables",
            "sum"(
                CASE
                    WHEN (("i"."type" = 'ACCREC'::"text") AND ("i"."status" = 'PAID'::"text") AND (("i"."date" >= "f"."fy_start") AND ("i"."date" <= "f"."fy_end"))) THEN "i"."total"
                    ELSE (0)::numeric
                END) AS "revenue_paid_fy",
            "max"("i"."fully_paid_date") FILTER (WHERE ("i"."type" = 'ACCREC'::"text")) AS "last_invoice_paid_at",
            "max"("i"."date") FILTER (WHERE ("i"."type" = 'ACCPAY'::"text")) AS "last_bill_at"
           FROM ("public"."xero_invoices" "i"
             CROSS JOIN "fy_range" "f")
          GROUP BY "i"."project_code"
        ), "opp_stats" AS (
         SELECT "o"."project_code",
            "count"(*) FILTER (WHERE ("o"."status" = 'open'::"text")) AS "opp_open_count",
            "count"(*) FILTER (WHERE (("o"."status" = 'open'::"text") AND ("o"."project_code" IS NULL))) AS "opp_untagged_count",
            "sum"(
                CASE
                    WHEN ("o"."status" = 'open'::"text") THEN (COALESCE("o"."monetary_value", (0)::numeric) *
                    CASE
                        WHEN ("lower"("o"."stage_name") ~ '(won|invoiced|harvest|graduation)'::"text") THEN 1.00
                        WHEN ("lower"("o"."stage_name") ~ '(submitted|growth|negotiation)'::"text") THEN 0.70
                        WHEN ("lower"("o"."stage_name") ~ '(proposed|invited|application.in.progress)'::"text") THEN 0.50
                        WHEN ("lower"("o"."stage_name") ~ '(germination|scoping|needs.assessment)'::"text") THEN 0.25
                        WHEN ("lower"("o"."stage_name") ~ '(grant.opportunity.identified)'::"text") THEN 0.00
                        WHEN ("lower"("o"."stage_name") ~ '(identified|signal|new.lead|new.inquiry|outreach)'::"text") THEN 0.10
                        WHEN ("lower"("o"."stage_name") ~ '(lost|cancelled|dropped)'::"text") THEN 0.00
                        ELSE 0.10
                    END)
                    ELSE (0)::numeric
                END) AS "pipeline_weighted",
            "sum"(
                CASE
                    WHEN ("o"."status" = 'open'::"text") THEN COALESCE("o"."monetary_value", (0)::numeric)
                    ELSE (0)::numeric
                END) AS "pipeline_raw",
            "max"("o"."last_stage_change_at") FILTER (WHERE ("o"."status" = 'open'::"text")) AS "last_opp_update_at"
           FROM "public"."ghl_opportunities" "o"
          GROUP BY "o"."project_code"
        ), "grant_stats" AS (
         SELECT "ga"."project_code",
            "sum"(
                CASE
                    WHEN ("ga"."status" = ANY (ARRAY['submitted'::"text", 'in_review'::"text", 'interview'::"text"])) THEN COALESCE("ga"."amount_requested", (0)::numeric)
                    ELSE (0)::numeric
                END) AS "grants_in_flight",
            "count"(*) FILTER (WHERE ("ga"."status" = ANY (ARRAY['submitted'::"text", 'in_review'::"text", 'interview'::"text"]))) AS "grants_in_flight_count"
           FROM "public"."grant_applications" "ga"
          GROUP BY "ga"."project_code"
        )
 SELECT "p"."code" AS "project_code",
    "p"."name" AS "project_name",
    "p"."tier",
    "p"."category",
    "p"."status" AS "project_status",
    "p"."importance_weight",
    COALESCE("ts"."txn_count_fy", (0)::bigint) AS "txn_count_fy",
    COALESCE("ts"."txn_untagged_fy", (0)::bigint) AS "txn_untagged_fy",
    COALESCE("inv"."inv_count_fy", (0)::bigint) AS "inv_count_fy",
    COALESCE("inv"."inv_untagged_fy", (0)::bigint) AS "inv_untagged_fy",
    COALESCE("opp"."opp_open_count", (0)::bigint) AS "opp_open_count",
    COALESCE("opp"."opp_untagged_count", (0)::bigint) AS "opp_untagged_count",
    COALESCE("ts"."income_fy", (0)::numeric) AS "income_fy",
    COALESCE("ts"."expenses_fy", (0)::numeric) AS "expenses_fy",
    (COALESCE("ts"."income_fy", (0)::numeric) - COALESCE("ts"."expenses_fy", (0)::numeric)) AS "net_fy",
    COALESCE("inv"."revenue_paid_fy", (0)::numeric) AS "revenue_paid_fy",
    COALESCE("inv"."receivables", (0)::numeric) AS "receivables",
    COALESCE("opp"."pipeline_weighted", (0)::numeric) AS "pipeline_weighted",
    COALESCE("opp"."pipeline_raw", (0)::numeric) AS "pipeline_raw",
    COALESCE("gs"."grants_in_flight", (0)::numeric) AS "grants_in_flight",
    COALESCE("gs"."grants_in_flight_count", (0)::bigint) AS "grants_in_flight_count",
    "ts"."last_transaction_at",
    "inv"."last_invoice_paid_at",
    "inv"."last_bill_at",
    "opp"."last_opp_update_at",
    GREATEST((CURRENT_DATE - "ts"."last_transaction_at"), 0) AS "days_since_transaction",
    GREATEST((CURRENT_DATE - "inv"."last_invoice_paid_at"), 0) AS "days_since_invoice_paid",
    GREATEST((CURRENT_DATE - ("opp"."last_opp_update_at")::"date"), 0) AS "days_since_opp_update"
   FROM (((("public"."projects" "p"
     LEFT JOIN "txn_stats" "ts" ON (("ts"."project_code" = "p"."code")))
     LEFT JOIN "inv_stats" "inv" ON (("inv"."project_code" = "p"."code")))
     LEFT JOIN "opp_stats" "opp" ON (("opp"."project_code" = "p"."code")))
     LEFT JOIN "grant_stats" "gs" ON (("gs"."project_code" = "p"."code")))
  ORDER BY "p"."importance_weight" DESC NULLS LAST, "p"."name";


ALTER VIEW "public"."v_project_money_state" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_project_money_state" IS 'v3: Grant Opportunity Identified scouting bucket weighted at 0 (was 10%). Other stages unchanged. Pipeline_weighted now reflects actively-pursued opportunities only.';



CREATE OR REPLACE VIEW "public"."v_project_pipeline_totals" AS
 SELECT "project_code",
    "count"(DISTINCT "pipeline_name") AS "pipelines_active",
    "sum"("open_count") AS "open_count",
    "sum"("won_count") AS "won_count",
    "sum"("lost_count") AS "lost_count",
    "sum"("open_value_aud") AS "open_value_aud",
    "sum"("won_value_aud") AS "won_value_aud",
    "max"("latest_activity_at") AS "latest_activity_at",
    "max"("computed_at") AS "computed_at"
   FROM "public"."project_pipelines"
  WHERE (("project_code" IS NOT NULL) AND ("project_code" <> ''::"text"))
  GROUP BY "project_code";


ALTER VIEW "public"."v_project_pipeline_totals" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_project_questions" WITH ("security_invoker"='true') AS
 SELECT "project_code",
    "project_name",
    "title",
    "content",
    "recorded_at",
    "follow_up_date",
    "importance"
   FROM "public"."project_knowledge" "pk"
  WHERE (("knowledge_type" = 'question'::"text") AND ("action_required" = true))
  ORDER BY "importance" DESC, "recorded_at" DESC;


ALTER VIEW "public"."v_project_questions" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_project_relationships" WITH ("security_invoker"='true') AS
 SELECT "gc"."ghl_id" AS "contact_id",
    "gc"."full_name" AS "contact_name",
    "gc"."email",
    "gc"."company_name",
    "gc"."tags",
    "p"."code" AS "project_code",
    "rh"."temperature",
    "rh"."temperature_trend",
    "rh"."last_contact_at",
    "rh"."email_score",
    "rh"."calendar_score",
    "rh"."risk_flags"
   FROM ((("public"."ghl_contacts" "gc"
     CROSS JOIN LATERAL "unnest"("gc"."tags") "tag"("tag"))
     JOIN "public"."projects" "p" ON ((("lower"("p"."name") = "lower"("tag"."tag")) OR ("lower"("replace"("p"."name", ' '::"text", '-'::"text")) = "lower"("tag"."tag")) OR ("lower"("replace"("p"."name", ' '::"text", ''::"text")) = "lower"("tag"."tag")) OR ("lower"("p"."code") = "lower"("tag"."tag")))))
     LEFT JOIN "public"."relationship_health" "rh" ON (("rh"."ghl_contact_id" = "gc"."ghl_id")))
  WHERE (("gc"."tags" IS NOT NULL) AND ("array_length"("gc"."tags", 1) > 0));


ALTER VIEW "public"."v_project_relationships" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_project_strategic_summary" WITH ("security_invoker"='true') AS
 SELECT "p"."code",
    "p"."name",
    "p"."tier",
    "p"."status" AS "project_status",
    "p"."category",
    "sp"."revenue_model",
    "sp"."time_to_revenue",
    "sp"."product_readiness_pct",
    "sp"."rd_eligible",
    "sp"."rd_category",
    "sp"."tam_annual",
    "sp"."sam_annual",
    "sp"."one_liner",
    "sp"."biggest_blocker",
    "sp"."fastest_win",
    "sp"."independence_score",
    "sp"."contributes_to",
    "sp"."depends_on",
    "sp"."feeds_into",
    COALESCE("bud"."expense_budget", (0)::numeric) AS "annual_budget",
    COALESCE("bud"."revenue_budget", (0)::numeric) AS "annual_revenue_target",
    COALESCE("fin"."total_revenue", (0)::numeric) AS "fy_revenue",
    COALESCE("fin"."total_expenses", (0)::numeric) AS "fy_expenses",
    (COALESCE("fin"."total_revenue", (0)::numeric) + COALESCE("fin"."total_expenses", (0)::numeric)) AS "fy_net",
    COALESCE("opp"."opp_count", (0)::bigint) AS "pipeline_count",
    COALESCE("opp"."weighted_value", (0)::numeric) AS "pipeline_weighted"
   FROM (((("public"."projects" "p"
     LEFT JOIN "public"."project_strategic_profile" "sp" ON (("sp"."project_code" = "p"."code")))
     LEFT JOIN ( SELECT "project_budgets"."project_code",
            "sum"(
                CASE
                    WHEN ("project_budgets"."budget_type" = 'expense'::"text") THEN "project_budgets"."budget_amount"
                    ELSE (0)::numeric
                END) AS "expense_budget",
            "sum"(
                CASE
                    WHEN ("project_budgets"."budget_type" = ANY (ARRAY['revenue'::"text", 'grant'::"text"])) THEN "project_budgets"."budget_amount"
                    ELSE (0)::numeric
                END) AS "revenue_budget"
           FROM "public"."project_budgets"
          WHERE ("project_budgets"."fy_year" = 'FY26'::"text")
          GROUP BY "project_budgets"."project_code") "bud" ON (("bud"."project_code" = "p"."code")))
     LEFT JOIN ( SELECT "project_monthly_financials"."project_code",
            "sum"("project_monthly_financials"."revenue") AS "total_revenue",
            "sum"("project_monthly_financials"."expenses") AS "total_expenses"
           FROM "public"."project_monthly_financials"
          WHERE ("project_monthly_financials"."month" >= '2025-07-01'::"date")
          GROUP BY "project_monthly_financials"."project_code") "fin" ON (("fin"."project_code" = "p"."code")))
     LEFT JOIN ( SELECT "unnest"("opportunities_unified"."project_codes") AS "project_code",
            "count"(*) AS "opp_count",
            "sum"((("opportunities_unified"."value_mid" * "opportunities_unified"."probability") / (100)::numeric)) AS "weighted_value"
           FROM "public"."opportunities_unified"
          WHERE ("opportunities_unified"."stage" <> ALL (ARRAY['lost'::"text", 'expired'::"text"]))
          GROUP BY ("unnest"("opportunities_unified"."project_codes"))) "opp" ON (("opp"."project_code" = "p"."code")))
  WHERE (("p"."status" = 'active'::"text") OR ("sp"."project_code" IS NOT NULL));


ALTER VIEW "public"."v_project_strategic_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_project_summary" WITH ("security_invoker"='true') AS
 WITH "tx_stats" AS (
         SELECT "xero_transactions"."project_code",
            COALESCE("sum"(
                CASE
                    WHEN ("xero_transactions"."type" = 'RECEIVE'::"text") THEN "xero_transactions"."total"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "total_income",
            COALESCE("sum"(
                CASE
                    WHEN ("xero_transactions"."type" = 'SPEND'::"text") THEN "abs"("xero_transactions"."total")
                    ELSE (0)::numeric
                END), (0)::numeric) AS "total_expenses",
            COALESCE("sum"(
                CASE
                    WHEN ("xero_transactions"."type" = 'RECEIVE'::"text") THEN "xero_transactions"."total"
                    WHEN ("xero_transactions"."type" = 'SPEND'::"text") THEN "xero_transactions"."total"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "net",
            "count"(*) AS "transaction_count"
           FROM "public"."xero_transactions"
          WHERE ("xero_transactions"."project_code" IS NOT NULL)
          GROUP BY "xero_transactions"."project_code"
        ), "inv_stats" AS (
         SELECT "xero_invoices"."project_code",
            "count"(*) AS "invoice_count",
            COALESCE("sum"("xero_invoices"."amount_due"), (0)::numeric) AS "outstanding_amount"
           FROM "public"."xero_invoices"
          WHERE (("xero_invoices"."project_code" IS NOT NULL) AND ("xero_invoices"."status" <> ALL (ARRAY['PAID'::"text", 'VOIDED'::"text", 'DELETED'::"text"])))
          GROUP BY "xero_invoices"."project_code"
        ), "opp_stats" AS (
         SELECT "ghl_opportunities"."project_code",
            "count"(*) AS "opportunity_count",
            COALESCE("sum"("ghl_opportunities"."monetary_value"), (0)::numeric) AS "pipeline_value",
            "count"(*) FILTER (WHERE ("ghl_opportunities"."status" = 'open'::"text")) AS "open_opportunities"
           FROM "public"."ghl_opportunities"
          WHERE ("ghl_opportunities"."project_code" IS NOT NULL)
          GROUP BY "ghl_opportunities"."project_code"
        ), "email_stats" AS (
         SELECT "unnest"("communications_history"."project_codes") AS "project_code",
            "count"(*) AS "email_count",
            "max"("communications_history"."occurred_at") AS "last_email_date"
           FROM "public"."communications_history"
          WHERE (("communications_history"."project_codes" IS NOT NULL) AND ("array_length"("communications_history"."project_codes", 1) > 0))
          GROUP BY ("unnest"("communications_history"."project_codes"))
        ), "grant_stats" AS (
         SELECT "grant_applications"."project_code",
            "count"(*) AS "grant_count",
            COALESCE("sum"(
                CASE
                    WHEN ("grant_applications"."status" = 'successful'::"text") THEN "grant_applications"."outcome_amount"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "grants_won",
            COALESCE("sum"(
                CASE
                    WHEN ("grant_applications"."status" = ANY (ARRAY['submitted'::"text", 'under_review'::"text"])) THEN "grant_applications"."amount_requested"
                    ELSE (0)::numeric
                END), (0)::numeric) AS "grants_pending"
           FROM "public"."grant_applications"
          WHERE ("grant_applications"."project_code" IS NOT NULL)
          GROUP BY "grant_applications"."project_code"
        ), "sub_stats" AS (
         SELECT "unnest"("subscriptions"."project_codes") AS "project_code",
            COALESCE("sum"(
                CASE "subscriptions"."billing_cycle"
                    WHEN 'monthly'::"text" THEN "subscriptions"."amount"
                    WHEN 'annual'::"text" THEN ("subscriptions"."amount" / (12)::numeric)
                    WHEN 'quarterly'::"text" THEN ("subscriptions"."amount" / (3)::numeric)
                    ELSE (0)::numeric
                END), (0)::numeric) AS "subscription_monthly_cost"
           FROM "public"."subscriptions"
          WHERE (("subscriptions"."account_status" = 'active'::"text") AND ("subscriptions"."project_codes" IS NOT NULL) AND ("array_length"("subscriptions"."project_codes", 1) > 0))
          GROUP BY ("unnest"("subscriptions"."project_codes"))
        )
 SELECT "ph"."project_code",
    "ph"."project_name",
    "ph"."overall_score" AS "health_score",
    "ph"."health_status",
    "ph"."momentum_score",
    "ph"."engagement_score",
    "ph"."financial_score",
    "ph"."timeline_score",
    "ph"."calculated_at" AS "health_calculated_at",
    COALESCE("tx"."total_income", (0)::numeric) AS "total_income",
    COALESCE("tx"."total_expenses", (0)::numeric) AS "total_expenses",
    COALESCE("tx"."net", (0)::numeric) AS "net",
    COALESCE("tx"."transaction_count", (0)::bigint) AS "transaction_count",
    COALESCE("inv"."invoice_count", (0)::bigint) AS "invoice_count",
    COALESCE("inv"."outstanding_amount", (0)::numeric) AS "outstanding_amount",
    COALESCE("opp"."opportunity_count", (0)::bigint) AS "opportunity_count",
    COALESCE("opp"."pipeline_value", (0)::numeric) AS "pipeline_value",
    COALESCE("opp"."open_opportunities", (0)::bigint) AS "open_opportunities",
    COALESCE("em"."email_count", (0)::bigint) AS "email_count",
    "em"."last_email_date",
    COALESCE("gr"."grant_count", (0)::bigint) AS "grant_count",
    COALESCE("gr"."grants_won", (0)::numeric) AS "grants_won",
    COALESCE("gr"."grants_pending", (0)::numeric) AS "grants_pending",
    COALESCE("ss"."subscription_monthly_cost", (0)::numeric) AS "subscription_monthly_cost"
   FROM (((((("public"."project_health" "ph"
     LEFT JOIN "tx_stats" "tx" ON (("tx"."project_code" = "ph"."project_code")))
     LEFT JOIN "inv_stats" "inv" ON (("inv"."project_code" = "ph"."project_code")))
     LEFT JOIN "opp_stats" "opp" ON (("opp"."project_code" = "ph"."project_code")))
     LEFT JOIN "email_stats" "em" ON (("em"."project_code" = "ph"."project_code")))
     LEFT JOIN "grant_stats" "gr" ON (("gr"."project_code" = "ph"."project_code")))
     LEFT JOIN "sub_stats" "ss" ON (("ss"."project_code" = "ph"."project_code")));


