            "qld_watchhouse_snapshots"."raw_pdf_sha256",
            "qld_watchhouse_snapshots"."total_people",
            "qld_watchhouse_snapshots"."total_adults",
            "qld_watchhouse_snapshots"."total_children",
            "qld_watchhouse_snapshots"."adult_first_nations",
            "qld_watchhouse_snapshots"."adult_non_indigenous",
            "qld_watchhouse_snapshots"."adult_other_status",
            "qld_watchhouse_snapshots"."child_first_nations",
            "qld_watchhouse_snapshots"."child_non_indigenous",
            "qld_watchhouse_snapshots"."child_other_status",
            "qld_watchhouse_snapshots"."adult_0_2_days",
            "qld_watchhouse_snapshots"."adult_3_7_days",
            "qld_watchhouse_snapshots"."adult_over_7_days",
            "qld_watchhouse_snapshots"."child_0_2_days",
            "qld_watchhouse_snapshots"."child_3_7_days",
            "qld_watchhouse_snapshots"."child_over_7_days",
            "qld_watchhouse_snapshots"."adult_longest_days",
            "qld_watchhouse_snapshots"."child_longest_days",
