           FROM "public"."qld_watchhouse_snapshots"
          ORDER BY "qld_watchhouse_snapshots"."source_generated_at" DESC
         LIMIT 1) "s"
     LEFT JOIN LATERAL ( SELECT "jsonb_agg"("jsonb_build_object"('watchhouse_name', "r"."watchhouse_name", 'age_group', "r"."age_group", 'total_in_custody', "r"."total_in_custody", 'male', "r"."male", 'female', "r"."female", 'other_gender', "r"."other_gender", 'first_nations', "r"."first_nations", 'non_indigenous', "r"."non_indigenous", 'other_status', "r"."other_status", 'custody_0_2_days', "r"."custody_0_2_days", 'custody_3_7_days', "r"."custody_3_7_days", 'custody_over_7_days', "r"."custody_over_7_days", 'longest_days', "r"."longest_days") ORDER BY "r"."age_group", "r"."watchhouse_name") AS "rows"
           FROM "public"."qld_watchhouse_snapshot_rows" "r"
          WHERE ("r"."snapshot_id" = "s"."id")) "rows_json" ON (true));


