CREATE OR REPLACE VIEW "public"."v_qld_yj_bills_active" AS
 WITH "raw_mentions" AS (
         SELECT "civic_hansard"."sitting_date",
            "civic_hansard"."speaker_name",
            "civic_hansard"."speaker_party",
            "regexp_matches"("civic_hansard"."body_text", '\m([A-Z][A-Za-z][^.\n]{6,120}?(?:Amendment Bill|Bill) 20[12][0-9])'::"text", 'g'::"text") AS "m"
           FROM "public"."civic_hansard"
          WHERE (("civic_hansard"."jurisdiction" = 'QLD'::"text") AND ("civic_hansard"."body_text" ~ '(youth justice|adult crime|youth detention|making queensland safer|breach of bail|young offender|child criminal)'::"text"))
        ), "cleaned" AS (
         SELECT TRIM(BOTH ' '::"text" FROM "regexp_replace"("regexp_replace"("regexp_replace"("regexp_replace"("raw_mentions"."m"[1], '^(?:Tabled paper\s*:\s*|I rise (?:to speak (?:to|in support of|in strong support of|to\s+the|to\s+oppose) the|in (?:strong )?support of the|tonight in strong support of the|today to support the|to oppose the)\s+|I am pleased to introduce the\s+|.+?electorate(?:\s+\(.+?\))?\s+(?:to speak |in support of the |on the |speaking on the )?)'::"text", ''::"text", 'i'::"text"), '^(?:to (?:speak|support|introduce|oppose|debate)|on|in)\s+(?:the|on)?\s+'::"text", ''::"text", 'i'::"text"), '^(?:on the |the )'::"text", ''::"text", 'i'::"text"), '\s+'::"text", ' '::"text", 'g'::"text")) AS "bill_name",
            "raw_mentions"."sitting_date",
            "raw_mentions"."speaker_name",
            "raw_mentions"."speaker_party",
            "raw_mentions"."m"[1] AS "raw_match"
           FROM "raw_mentions"
        )
 SELECT "bill_name",
    ("count"(*))::integer AS "mentions",
    ("count"(DISTINCT "speaker_name"))::integer AS "distinct_speakers",
    "array_agg"(DISTINCT "speaker_party") FILTER (WHERE ("speaker_party" IS NOT NULL)) AS "parties",
    "min"("sitting_date") AS "first_mention",
    "max"("sitting_date") AS "last_mention",
        CASE
            WHEN ("bill_name" ~* '(adult crime|adult time|youth crime|youth detention|young offender|breach of bail|making queensland safer|youth justice)'::"text") THEN true
            ELSE false
        END AS "is_yj_specific"
   FROM "cleaned"
  WHERE ((("length"("bill_name") >= 12) AND ("length"("bill_name") <= 200)) AND ("bill_name" !~ '^[a-z]'::"text"))
  GROUP BY "bill_name"
 HAVING ("count"(*) >= 1)
  ORDER BY
        CASE
            WHEN ("bill_name" ~* '(adult crime|adult time|youth crime|youth detention|young offender|breach of bail|making queensland safer|youth justice)'::"text") THEN true
            ELSE false
        END DESC, (("count"(*))::integer) DESC;


ALTER VIEW "public"."v_qld_yj_bills_active" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_qld_yj_bills_active" IS 'Bill names and debate volume extracted from civic_hansard body_text for QLD YJ-relevant bills. Read for the structural list of legislation actually being debated. Bill names are best-effort regex from PDF text — verify against parliament.qld.gov.au before quoting.';



