CREATE OR REPLACE VIEW "public"."v_rd_expenses" WITH ("security_invoker"='true') AS
 SELECT "vr"."vendor_name",
    "vr"."category",
    "vr"."project_code",
    "t"."contact_name",
    "t"."total",
    "t"."date",
    "t"."id" AS "transaction_id"
   FROM ("public"."vendor_project_rules" "vr"
     JOIN "public"."xero_transactions" "t" ON ((("t"."project_code" = "vr"."project_code") AND ("t"."type" = 'SPEND'::"text") AND (("lower"("t"."contact_name") ~~* (('%'::"text" || "lower"("vr"."vendor_name")) || '%'::"text")) OR (EXISTS ( SELECT 1
           FROM "unnest"("vr"."aliases") "alias"("alias")
          WHERE ("lower"("t"."contact_name") ~~* (('%'::"text" || "lower"("alias"."alias")) || '%'::"text"))))))))
  WHERE ("vr"."rd_eligible" = true);


