CREATE OR REPLACE VIEW "public"."v_receipt_pipeline_funnel" WITH ("security_invoker"='true') AS
 SELECT "stage",
    "count"(*) AS "count",
    COALESCE("sum"("amount"), (0)::numeric) AS "total_amount",
    "min"("transaction_date") AS "oldest_date",
    "max"("transaction_date") AS "newest_date",
    "count"(*) FILTER (WHERE ("transaction_date" < (CURRENT_DATE - '14 days'::interval))) AS "stuck_count"
   FROM "public"."receipt_pipeline_status"
  GROUP BY "stage"
  ORDER BY
        CASE "stage"
            WHEN 'missing_receipt'::"text" THEN 1
            WHEN 'forwarded_to_dext'::"text" THEN 2
            WHEN 'dext_processed'::"text" THEN 3
            WHEN 'xero_bill_created'::"text" THEN 4
            WHEN 'reconciled'::"text" THEN 5
            ELSE NULL::integer
        END;


ALTER VIEW "public"."v_receipt_pipeline_funnel" OWNER TO "postgres";


