CREATE OR REPLACE VIEW "public"."v_subscription_alerts" WITH ("security_invoker"='true') AS
 SELECT "id",
    "vendor_name",
    "vendor_email",
    "account_email",
    "account_status",
    "billing_cycle",
    "amount",
    "currency",
    "next_billing_date",
    "category",
    "purpose",
    "project_codes",
    "is_essential",
    "review_status",
    "receipt_automation",
    "dext_supplier_rule",
    "xero_bank_rule",
    "notes",
    "created_at",
    "updated_at",
    "current_login_email",
    "login_url",
    "migration_notes",
    "migrated_at",
    "xero_repeating_invoice_id",
    "discovery_source",
    "discovery_confidence",
    "last_discovery_check",
    "expected_amount",
    "last_payment_date",
    "consecutive_missed_payments",
        CASE
            WHEN ("consecutive_missed_payments" >= 2) THEN 'possibly_cancelled'::"text"
            WHEN (("expected_amount" IS NOT NULL) AND ("amount" IS NOT NULL) AND (("abs"(("amount" - "expected_amount")) / NULLIF("expected_amount", (0)::numeric)) > 0.1)) THEN 'price_change'::"text"
            WHEN (("next_billing_date" IS NOT NULL) AND ("next_billing_date" < CURRENT_DATE)) THEN 'overdue_renewal'::"text"
            ELSE 'ok'::"text"
        END AS "alert_status",
        CASE
            WHEN ("consecutive_missed_payments" >= 2) THEN 'high'::"text"
            WHEN ("consecutive_missed_payments" = 1) THEN 'medium'::"text"
            WHEN (("next_billing_date" IS NOT NULL) AND ("next_billing_date" < CURRENT_DATE)) THEN 'medium'::"text"
            ELSE 'low'::"text"
        END AS "alert_priority"
   FROM "public"."subscriptions" "s"
  WHERE ("account_status" = 'active'::"text");


ALTER VIEW "public"."v_subscription_alerts" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_team_capacity" WITH ("security_invoker"='true') AS
 SELECT "tm"."id",
    "tm"."name",
    "tm"."role",
    "tm"."available_hours_per_week",
    COALESCE("sum"("ra"."hours_per_week"), (0)::numeric) AS "allocated_hours",
    ("tm"."available_hours_per_week" - COALESCE("sum"("ra"."hours_per_week"), (0)::numeric)) AS "available_hours",
    "round"(((COALESCE("sum"("ra"."hours_per_week"), (0)::numeric) / NULLIF("tm"."available_hours_per_week", (0)::numeric)) * (100)::numeric), 1) AS "utilisation_pct",
    "array_agg"(DISTINCT "ra"."project_code") FILTER (WHERE ("ra"."project_code" IS NOT NULL)) AS "projects"
   FROM ("public"."team_members" "tm"
     LEFT JOIN "public"."resource_allocations" "ra" ON ((("ra"."team_member_id" = "tm"."id") AND (("ra"."end_date" IS NULL) OR ("ra"."end_date" >= CURRENT_DATE)) AND ("ra"."start_date" <= CURRENT_DATE))))
  WHERE ("tm"."status" = 'active'::"text")
  GROUP BY "tm"."id", "tm"."name", "tm"."role", "tm"."available_hours_per_week";


ALTER VIEW "public"."v_team_capacity" OWNER TO "postgres";


