ALTER VIEW "public"."v_youth_justice_cost_comparison" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_youth_justice_entities" AS
 SELECT "e"."id",
    "e"."gs_id",
    "e"."canonical_name",
    "e"."abn",
    "e"."entity_type",
    "e"."sector",
    "e"."state",
    "e"."postcode",
    "e"."remoteness",
    "e"."lga_name",
    "e"."is_community_controlled",
    COALESCE("jf"."justice_funding_total", (0)::numeric) AS "justice_funding_total",
    COALESCE("jf"."justice_grant_count", (0)::bigint) AS "justice_grant_count",
    COALESCE("ac"."contract_total", (0)::numeric) AS "contract_total",
    COALESCE("ac"."contract_count", (0)::bigint) AS "contract_count",
    COALESCE("alma"."intervention_count", (0)::bigint) AS "alma_intervention_count",
    "alma"."evidence_levels",
    "alma"."avg_cost_per_person",
    ("jf"."justice_funding_total" IS NOT NULL) AS "has_justice_funding",
    ("ac"."contract_total" IS NOT NULL) AS "has_yj_contracts",
    ("alma"."intervention_count" IS NOT NULL) AS "has_alma_interventions"
   FROM ((("public"."gs_entities" "e"
     LEFT JOIN LATERAL ( SELECT "sum"("j"."amount_dollars") AS "justice_funding_total",
            "count"(*) AS "justice_grant_count"
           FROM "public"."justice_funding" "j"
          WHERE (("j"."gs_entity_id" = "e"."id") AND (("j"."sector" ~~* '%youth%'::"text") OR ("j"."sector" ~~* '%justice%'::"text") OR ("j"."program_name" ~~* '%youth%'::"text") OR ("j"."program_name" ~~* '%juvenile%'::"text")))) "jf" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("c"."contract_value") AS "contract_total",
            "count"(*) AS "contract_count"
           FROM "public"."austender_contracts" "c"
          WHERE (("c"."supplier_abn" = "e"."abn") AND (("c"."title" ~~* '%youth justice%'::"text") OR ("c"."title" ~~* '%juvenile%'::"text") OR ("c"."title" ~~* '%young offend%'::"text") OR ("c"."title" ~~* '%youth detention%'::"text")))) "ac" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "intervention_count",
            "array_agg"(DISTINCT "ai"."evidence_level") AS "evidence_levels",
            "avg"("ai"."cost_per_young_person") AS "avg_cost_per_person"
           FROM "public"."alma_interventions" "ai"
          WHERE (("ai"."gs_entity_id" = "e"."id") AND ("ai"."serves_youth_justice" = true))) "alma" ON (true))
  WHERE ((COALESCE("jf"."justice_funding_total", (0)::numeric) > (0)::numeric) OR (COALESCE("ac"."contract_total", (0)::numeric) > (0)::numeric) OR (COALESCE("alma"."intervention_count", (0)::bigint) > 0));


ALTER VIEW "public"."v_youth_justice_entities" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_youth_justice_entities" IS 'Organizations receiving youth justice funding, contracts, or delivering ALMA interventions';



CREATE OR REPLACE VIEW "public"."v_youth_justice_recipients" AS
 WITH "canon" AS (
         SELECT "f"."id",
            COALESCE("g"."canonical_id", ("f"."gs_entity_id")::"text") AS "org_id",
            "f"."gs_entity_id",
            "f"."amount_dollars",
            "f"."recipient_name",
            "f"."recipient_abn",
            "f"."financial_year",
            "f"."link_basis"
           FROM ("public"."justice_funding" "f"
             LEFT JOIN "public"."v_entity_organisation_group" "g" ON (("g"."entity_id" = ("f"."gs_entity_id")::"text")))
          WHERE (("f"."sector" = 'youth_justice'::"text") AND ("f"."measure_kind" = 'grant'::"text") AND (NOT "f"."is_aggregate") AND ("f"."gs_entity_id" IS NOT NULL))
        ), "totals" AS (
         SELECT "canon"."org_id",
            "sum"("canon"."amount_dollars") AS "total_dollars",
            "count"(*) AS "award_count",
            "count"(DISTINCT "canon"."recipient_name") AS "funded_name_count",
            "count"(DISTINCT "canon"."gs_entity_id") AS "entity_ids_merged",
            "min"("canon"."financial_year") AS "first_year",
            "max"("canon"."financial_year") AS "last_year",
            "bool_or"(("canon"."link_basis" = 'abn_exact_backfill'::"text")) AS "link_was_machine_backfilled",
            "max"("canon"."recipient_abn") AS "abn"
           FROM "canon"
          GROUP BY "canon"."org_id"
        ), "members" AS (
         SELECT "t_1"."org_id",
            "t_1"."org_id" AS "member_id"
           FROM "totals" "t_1"
        UNION
         SELECT "g"."canonical_id",
            "g"."entity_id"
           FROM "public"."v_entity_organisation_group" "g"
        ), "announced" AS (
         SELECT "m"."org_id",
            ("array_agg"("f"."recipient_name" ORDER BY ("length"("f"."recipient_name"))))[1] AS "announced_name"
           FROM ("members" "m"
             JOIN "public"."justice_funding" "f" ON ((("f"."gs_entity_id")::"text" = "m"."member_id")))
          WHERE (("f"."measure_kind" = 'budget_announcement'::"text") AND (NOT "f"."is_aggregate") AND ("f"."recipient_name" IS NOT NULL) AND ("f"."recipient_name" !~* '^\s*(\(?blank\)?|n/?a|none|nil|unknown|various|multiple)\s*$'::"text") AND ("f"."recipient_name" !~ '/'::"text") AND ("f"."recipient_name" !~ '\s[-–—]\s'::"text") AND ("f"."recipient_name" !~* '^(department|ministry|office) of\M'::"text") AND ("length"("f"."recipient_name") <= 120))
          GROUP BY "m"."org_id"
        ), "registered" AS (
         SELECT "m"."org_id",
            ("array_agg"("a"."value" ORDER BY ("a"."basis" = 'derived'::"text") DESC))[1] AS "register_name",
            ("array_agg"("a"."basis" ORDER BY ("a"."basis" = 'derived'::"text") DESC))[1] AS "name_basis",
            ("array_agg"("a"."note" ORDER BY ("a"."basis" = 'derived'::"text") DESC))[1] AS "name_note"
           FROM ("members" "m"
             JOIN "public"."assertions" "a" ON ((("a"."subject_id" = "m"."member_id") AND ("a"."machine_rule" = 'display_name_v1'::"text") AND ("a"."superseded_by" IS NULL))))
          GROUP BY "m"."org_id"
        )
 SELECT "t"."org_id" AS "gs_entity_id",
    "t"."abn",
    COALESCE("an"."announced_name", "r"."register_name") AS "display_name",
        CASE
            WHEN (("an"."announced_name" IS NOT NULL) AND ("r"."register_name" IS NOT NULL) AND ("lower"("an"."announced_name") <> "lower"("r"."register_name"))) THEN "r"."register_name"
            ELSE NULL::"text"
        END AS "legal_name",
    "r"."name_basis",
    "r"."name_note",
    "t"."total_dollars",
    "t"."award_count",
    "t"."funded_name_count",
    "t"."entity_ids_merged",
    "t"."first_year",
    "t"."last_year",
    "t"."link_was_machine_backfilled",
    "round"(((100.0 * "t"."total_dollars") / NULLIF("sum"("t"."total_dollars") OVER (), (0)::numeric)), 2) AS "share_pct",
    "row_number"() OVER (ORDER BY "t"."total_dollars" DESC NULLS LAST) AS "rank"
   FROM (("totals" "t"
     LEFT JOIN "announced" "an" ON (("an"."org_id" = "t"."org_id")))
     LEFT JOIN "registered" "r" ON (("r"."org_id" = "t"."org_id")));


ALTER VIEW "public"."v_youth_justice_recipients" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_youth_justice_recipients" IS 'Youth justice GRANT recipients, one row per ORGANISATION. display_name is the PUBLIC name from a government announcement where one exists, matching v_program_deliverers so the same body is named identically on every page; legal_name carries the register name when it differs.';



CREATE OR REPLACE VIEW "public"."v_youth_justice_recipient_stats" AS
 WITH "r" AS (
         SELECT "v_youth_justice_recipients"."total_dollars",
            "v_youth_justice_recipients"."rank"
           FROM "public"."v_youth_justice_recipients"
        )
 SELECT "count"(*) AS "organisations",
    "sum"("total_dollars") AS "total_dollars",
    "round"(((100.0 * "sum"("total_dollars") FILTER (WHERE ("rank" <= 10))) / NULLIF("sum"("total_dollars"), (0)::numeric)), 1) AS "top_ten_pct",
    "round"(((100.0 * "sum"("total_dollars") FILTER (WHERE ("rank" <= 100))) / NULLIF("sum"("total_dollars"), (0)::numeric)), 1) AS "top_hundred_pct",
    ("percentile_cont"((0.5)::double precision) WITHIN GROUP (ORDER BY (("total_dollars")::double precision)))::numeric AS "median_dollars",
    "count"(*) FILTER (WHERE ("total_dollars" < (10000)::numeric)) AS "under_ten_thousand"
   FROM "r";


ALTER VIEW "public"."v_youth_justice_recipient_stats" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_youth_justice_recipient_stats" IS 'Header figures for /funding/recipients, computed in SQL so they cannot contradict the list below them and cannot be truncated by the PostgREST 1000-row cap.';



CREATE OR REPLACE VIEW "public"."v_youth_justice_state_dashboard" AS
 WITH "spending" AS (
         SELECT "rogs_justice_spending"."financial_year",
            'detention'::"text" AS "service",
            "rogs_justice_spending"."nsw",
            "rogs_justice_spending"."vic",
            "rogs_justice_spending"."qld",
            "rogs_justice_spending"."wa",
            "rogs_justice_spending"."sa",
            "rogs_justice_spending"."tas",
            "rogs_justice_spending"."act",
            "rogs_justice_spending"."nt",
            "rogs_justice_spending"."aust"
           FROM "public"."rogs_justice_spending"
          WHERE (("rogs_justice_spending"."rogs_table" = '17A.10'::"text") AND ("rogs_justice_spending"."rogs_section" = 'youth_justice'::"text") AND ("rogs_justice_spending"."description3" = 'Total expenditure'::"text") AND ("rogs_justice_spending"."unit" = '$''000'::"text"))
        ), "cost_per_detention" AS (
         SELECT "rogs_justice_spending"."financial_year",
            "rogs_justice_spending"."nsw",
            "rogs_justice_spending"."vic",
            "rogs_justice_spending"."qld",
            "rogs_justice_spending"."wa",
            "rogs_justice_spending"."sa",
            "rogs_justice_spending"."tas",
            "rogs_justice_spending"."act",
            "rogs_justice_spending"."nt",
            "rogs_justice_spending"."aust"
           FROM "public"."rogs_justice_spending"
          WHERE (("rogs_justice_spending"."rogs_table" = '17A.20'::"text") AND ("rogs_justice_spending"."rogs_section" = 'youth_justice'::"text") AND ("rogs_justice_spending"."unit" = '$'::"text"))
        ), "recidivism" AS (
         SELECT "rogs_justice_spending"."financial_year",
            "rogs_justice_spending"."nsw",
            "rogs_justice_spending"."vic",
            "rogs_justice_spending"."qld",
            "rogs_justice_spending"."wa",
            "rogs_justice_spending"."sa",
            "rogs_justice_spending"."tas",
            "rogs_justice_spending"."act",
            "rogs_justice_spending"."nt",
            "rogs_justice_spending"."aust"
           FROM "public"."rogs_justice_spending"
          WHERE (("rogs_justice_spending"."rogs_table" = '17A.26'::"text") AND ("rogs_justice_spending"."rogs_section" = 'youth_justice'::"text") AND ("rogs_justice_spending"."unit" = '%'::"text"))
        ), "completion" AS (
         SELECT "rogs_justice_spending"."financial_year",
            "rogs_justice_spending"."nsw",
            "rogs_justice_spending"."vic",
            "rogs_justice_spending"."qld",
            "rogs_justice_spending"."wa",
            "rogs_justice_spending"."sa",
            "rogs_justice_spending"."tas",
            "rogs_justice_spending"."act",
            "rogs_justice_spending"."nt",
            "rogs_justice_spending"."aust"
           FROM "public"."rogs_justice_spending"
          WHERE (("rogs_justice_spending"."rogs_table" = '17A.25'::"text") AND ("rogs_justice_spending"."rogs_section" = 'youth_justice'::"text") AND ("rogs_justice_spending"."unit" = '%'::"text") AND ("rogs_justice_spending"."description2" = 'Proportion of orders'::"text"))
        ), "indigenous_rate" AS (
         SELECT "rogs_justice_spending"."financial_year",
            "rogs_justice_spending"."nsw",
            "rogs_justice_spending"."vic",
            "rogs_justice_spending"."qld",
            "rogs_justice_spending"."wa",
            "rogs_justice_spending"."sa",
            "rogs_justice_spending"."tas",
            "rogs_justice_spending"."act",
            "rogs_justice_spending"."nt",
            "rogs_justice_spending"."aust"
           FROM "public"."rogs_justice_spending"
          WHERE (("rogs_justice_spending"."rogs_table" = '17A.7'::"text") AND ("rogs_justice_spending"."rogs_section" = 'youth_justice'::"text") AND ("rogs_justice_spending"."description2" = 'Rate ratio'::"text") AND ("rogs_justice_spending"."unit" = 'ratio'::"text"))
        ), "ctg_detention" AS (
         SELECT "rogs_justice_spending"."financial_year",
            "rogs_justice_spending"."description3" AS "data_type",
            "rogs_justice_spending"."nsw",
            "rogs_justice_spending"."vic",
            "rogs_justice_spending"."qld",
            "rogs_justice_spending"."wa",
            "rogs_justice_spending"."sa",
            "rogs_justice_spending"."tas",
            "rogs_justice_spending"."act",
            "rogs_justice_spending"."nt",
            "rogs_justice_spending"."aust"
           FROM "public"."rogs_justice_spending"
          WHERE (("rogs_justice_spending"."rogs_table" = 'CtG11A.1'::"text") AND ("rogs_justice_spending"."rogs_section" = 'closing-the-gap'::"text") AND ("rogs_justice_spending"."unit" = 'rate'::"text") AND ("rogs_justice_spending"."indigenous_status" ~~* '%Aboriginal%'::"text") AND ("rogs_justice_spending"."description2" ~~* '%Rate per 10000%'::"text"))
        ), "facilities" AS (
         SELECT "youth_detention_facilities"."state",
            "count"(*) FILTER (WHERE ("youth_detention_facilities"."operational_status" = 'operational'::"text")) AS "facility_count",
            "sum"("youth_detention_facilities"."capacity_beds") FILTER (WHERE ("youth_detention_facilities"."operational_status" = 'operational'::"text")) AS "total_beds",
            "avg"("youth_detention_facilities"."indigenous_population_percentage") FILTER (WHERE ("youth_detention_facilities"."operational_status" = 'operational'::"text")) AS "avg_indigenous_pct"
           FROM "public"."youth_detention_facilities"
          GROUP BY "youth_detention_facilities"."state"
        )
 SELECT "s"."financial_year",
    "state"."abbrev" AS "state",
    (
        CASE "state"."abbrev"
            WHEN 'NSW'::"text" THEN "s"."nsw"
            WHEN 'VIC'::"text" THEN "s"."vic"
            WHEN 'QLD'::"text" THEN "s"."qld"
            WHEN 'WA'::"text" THEN "s"."wa"
            WHEN 'SA'::"text" THEN "s"."sa"
            WHEN 'TAS'::"text" THEN "s"."tas"
            WHEN 'ACT'::"text" THEN "s"."act"
            WHEN 'NT'::"text" THEN "s"."nt"
            ELSE NULL::numeric
        END / 1000.0) AS "total_expenditure_m",
        CASE "state"."abbrev"
            WHEN 'NSW'::"text" THEN "cpd"."nsw"
            WHEN 'VIC'::"text" THEN "cpd"."vic"
            WHEN 'QLD'::"text" THEN "cpd"."qld"
            WHEN 'WA'::"text" THEN "cpd"."wa"
            WHEN 'SA'::"text" THEN "cpd"."sa"
            WHEN 'TAS'::"text" THEN "cpd"."tas"
            WHEN 'ACT'::"text" THEN "cpd"."act"
            WHEN 'NT'::"text" THEN "cpd"."nt"
            ELSE NULL::numeric
        END AS "cost_per_detention",
        CASE "state"."abbrev"
            WHEN 'NSW'::"text" THEN "r"."nsw"
            WHEN 'VIC'::"text" THEN "r"."vic"
            WHEN 'QLD'::"text" THEN "r"."qld"
            WHEN 'WA'::"text" THEN "r"."wa"
            WHEN 'SA'::"text" THEN "r"."sa"
            WHEN 'TAS'::"text" THEN "r"."tas"
            WHEN 'ACT'::"text" THEN "r"."act"
            WHEN 'NT'::"text" THEN "r"."nt"
            ELSE NULL::numeric
        END AS "recidivism_pct",
        CASE "state"."abbrev"
            WHEN 'NSW'::"text" THEN "c"."nsw"
            WHEN 'VIC'::"text" THEN "c"."vic"
            WHEN 'QLD'::"text" THEN "c"."qld"
            WHEN 'WA'::"text" THEN "c"."wa"
            WHEN 'SA'::"text" THEN "c"."sa"
            WHEN 'TAS'::"text" THEN "c"."tas"
            WHEN 'ACT'::"text" THEN "c"."act"
            WHEN 'NT'::"text" THEN "c"."nt"
            ELSE NULL::numeric
        END AS "completion_pct",
        CASE "state"."abbrev"
            WHEN 'NSW'::"text" THEN "ir"."nsw"
            WHEN 'VIC'::"text" THEN "ir"."vic"
            WHEN 'QLD'::"text" THEN "ir"."qld"
            WHEN 'WA'::"text" THEN "ir"."wa"
            WHEN 'SA'::"text" THEN "ir"."sa"
            WHEN 'TAS'::"text" THEN "ir"."tas"
            WHEN 'ACT'::"text" THEN "ir"."act"
            WHEN 'NT'::"text" THEN "ir"."nt"
            ELSE NULL::numeric
        END AS "indigenous_rate_ratio",
    "f"."facility_count",
    "f"."total_beds",
    "f"."avg_indigenous_pct" AS "facility_indigenous_pct"
   FROM (((((("spending" "s"
     CROSS JOIN ( VALUES ('NSW'::"text"), ('VIC'::"text"), ('QLD'::"text"), ('WA'::"text"), ('SA'::"text"), ('TAS'::"text"), ('ACT'::"text"), ('NT'::"text")) "state"("abbrev"))
     LEFT JOIN "cost_per_detention" "cpd" ON (("cpd"."financial_year" = "s"."financial_year")))
     LEFT JOIN "recidivism" "r" ON (("r"."financial_year" = "s"."financial_year")))
     LEFT JOIN "completion" "c" ON (("c"."financial_year" = "s"."financial_year")))
     LEFT JOIN "indigenous_rate" "ir" ON (("ir"."financial_year" = "s"."financial_year")))
     LEFT JOIN "facilities" "f" ON (("f"."state" = "state"."abbrev")))
  ORDER BY "s"."financial_year" DESC, "state"."abbrev";


