CREATE OR REPLACE VIEW "public"."agentic_project_dashboard" WITH ("security_invoker"='true') AS
 SELECT "p"."id",
    "p"."name",
    "p"."goal",
    "p"."status",
    "p"."owner",
    "p"."created_at",
    "count"("t"."id") AS "total_tasks",
    "count"("t"."id") FILTER (WHERE ("t"."status" = 'completed'::"text")) AS "completed_tasks",
    "count"("t"."id") FILTER (WHERE ("t"."status" = 'agent_working'::"text")) AS "agent_working",
    "count"("t"."id") FILTER (WHERE ("t"."status" = 'needs_review'::"text")) AS "needs_review",
    "count"("t"."id") FILTER (WHERE ("t"."assigned_agent" IS NOT NULL)) AS "agent_tasks",
    "count"("t"."id") FILTER (WHERE ("t"."assigned_human" IS NOT NULL)) AS "human_tasks"
   FROM ("public"."agentic_projects" "p"
     LEFT JOIN "public"."agentic_tasks" "t" ON (("t"."project_id" = "p"."id")))
  GROUP BY "p"."id";



CREATE OR REPLACE VIEW "public"."v_bgfit_budget_vs_actual" WITH ("security_invoker"='true') AS
 SELECT "bi"."id",
    "bi"."grant_id",
    "g"."grant_name",
    "bi"."category",
    "bi"."item_name",
    "bi"."budgeted_amount",
    COALESCE("sum"("t"."amount"), (0)::numeric) AS "actual_amount",
    ("bi"."budgeted_amount" - COALESCE("sum"("t"."amount"), (0)::numeric)) AS "variance",
        CASE
            WHEN (COALESCE("sum"("t"."amount"), (0)::numeric) = (0)::numeric) THEN 'not_spent'::"text"
            WHEN (("abs"((COALESCE("sum"("t"."amount"), (0)::numeric) - "bi"."budgeted_amount")) / "bi"."budgeted_amount") < 0.1) THEN 'on_track'::"text"
            WHEN (COALESCE("sum"("t"."amount"), (0)::numeric) > "bi"."budgeted_amount") THEN 'overspent'::"text"
            ELSE 'underspent'::"text"
        END AS "calculated_status",
    "bi"."status",
    "bi"."has_issue",
    "bi"."issue_severity",
    "bi"."issue_description",
    "bi"."supplier_name",
    "bi"."receipt_details"
   FROM (("public"."bgfit_budget_items" "bi"
     JOIN "public"."bgfit_grants" "g" ON (("g"."id" = "bi"."grant_id")))
     LEFT JOIN "public"."bgfit_transactions" "t" ON ((("t"."budget_item_id" = "bi"."id") AND ("t"."transaction_type" = 'expense'::"text"))))
  GROUP BY "bi"."id", "g"."grant_name", "g"."id";



CREATE OR REPLACE VIEW "public"."v_person_360" AS
 SELECT "p"."id" AS "person_id",
    "p"."slug",
    "p"."full_name",
    "p"."display_name",
    "p"."honorific",
    "p"."primary_role",
    "p"."indigenous",
    "p"."state_focus",
    "p"."region_focus",
    "p"."photo_url",
    "count"("prh"."id") AS "role_count",
    "count"("prh"."id") FILTER (WHERE "prh"."is_current") AS "current_role_count",
    "array_agg"(DISTINCT "prh"."role_type") FILTER (WHERE ("prh"."role_type" IS NOT NULL)) AS "role_types",
    "array_agg"(DISTINCT "prh"."organization_id") FILTER (WHERE ("prh"."organization_id" IS NOT NULL)) AS "linked_org_ids"
   FROM ("public"."people" "p"
     LEFT JOIN "public"."person_role_holdings" "prh" ON (("prh"."person_id" = "p"."id")))
  GROUP BY "p"."id";



CREATE OR REPLACE VIEW "public"."v_unified_contacts" WITH ("security_invoker"='true') AS
 SELECT "ce"."id",
    "ce"."canonical_name" AS "name",
    "ce"."canonical_email" AS "email",
    "ce"."canonical_phone" AS "phone",
    "ce"."canonical_company" AS "company",
    "ce"."confidence",
    "ce"."relationship_strength",
    "ce"."primary_project_codes",
    "array_agg"(DISTINCT "ei"."source") AS "sources",
    "max"(
        CASE
            WHEN ("ei"."source" = 'ghl'::"text") THEN "ei"."source_record_id"
            ELSE NULL::"text"
        END) AS "ghl_id",
    "max"(
        CASE
            WHEN ("ei"."source" = 'notion'::"text") THEN "ei"."source_record_id"
            ELSE NULL::"text"
        END) AS "notion_id",
    "count"(DISTINCT "ei"."id") AS "identifier_count",
    "ce"."created_at",
    "ce"."updated_at"
   FROM ("public"."canonical_entities" "ce"
     LEFT JOIN "public"."entity_identifiers" "ei" ON (("ei"."entity_id" = "ce"."id")))
  WHERE ("ce"."entity_type" = 'person'::"text")
  GROUP BY "ce"."id";



