  WHERE (("outcome"."id" = "jr_outcome_evidence_links"."jr_outcome_id") AND ("site"."lead_organization_id" IS NOT NULL) AND "public"."is_org_member"("site"."lead_organization_id", 'viewer'::"text")))));



