CREATE POLICY "jr_review_decisions community workspace read" ON "public"."jr_review_decisions" FOR SELECT TO "authenticated" USING (((EXISTS ( SELECT 1
   FROM ("public"."jr_outcomes" "outcome"
     JOIN "public"."jr_sites" "site" ON (("site"."id" = "outcome"."jr_site_id")))
  WHERE (("outcome"."id" = "jr_review_decisions"."jr_outcome_id") AND ("site"."lead_organization_id" IS NOT NULL) AND "public"."is_org_member"("site"."lead_organization_id", 'viewer'::"text")))) OR (EXISTS ( SELECT 1
   FROM (("public"."jr_outcome_evidence_links" "evidence"
     JOIN "public"."jr_outcomes" "outcome" ON (("outcome"."id" = "evidence"."jr_outcome_id")))
     JOIN "public"."jr_sites" "site" ON (("site"."id" = "outcome"."jr_site_id")))
  WHERE (("evidence"."id" = "jr_review_decisions"."jr_outcome_evidence_link_id") AND ("site"."lead_organization_id" IS NOT NULL) AND "public"."is_org_member"("site"."lead_organization_id", 'viewer'::"text")))) OR (EXISTS ( SELECT 1
   FROM ("public"."jr_evidence_drafts" "draft"
     JOIN "public"."jr_sites" "site" ON (("site"."id" = "draft"."jr_site_id")))
  WHERE (("draft"."id" = "jr_review_decisions"."jr_evidence_draft_id") AND ("site"."lead_organization_id" IS NOT NULL) AND "public"."is_org_member"("site"."lead_organization_id", 'viewer'::"text"))))));



